#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MarginRowScheduleOuterRoute {
    Actionable,
    ProofTail,
    DeferredPgd,
    Memory,
}

impl MarginRowScheduleOuterRoute {
    const fn stable_token(self) -> &'static str {
        match self {
            Self::Actionable => "actionable",
            Self::ProofTail => "proof_tail",
            Self::DeferredPgd => "deferred_pgd",
            Self::Memory => "memory",
        }
    }
}

fn margin_row_reserve_route_token(
    route: super::margin_row_bab::MarginRowReserveRoute,
) -> &'static str {
    match route {
        super::margin_row_bab::MarginRowReserveRoute::NotApplicable => "not_applicable",
        super::margin_row_bab::MarginRowReserveRoute::Fixed => "fixed",
        super::margin_row_bab::MarginRowReserveRoute::AdaptivePreserved => "adaptive_preserved",
        super::margin_row_bab::MarginRowReserveRoute::AdaptiveReleasedAlphaBetaTier => {
            "adaptive_released"
        }
    }
}

fn optional_f64_bits_token(bits: Option<u64>) -> String {
    bits.map_or_else(|| "none".to_string(), |bits| bits.to_string())
}

fn optional_usize_token(value: Option<usize>) -> String {
    value.map_or_else(|| "none".to_string(), |value| value.to_string())
}

fn render_margin_row_schedule_execution(
    policy: super::margin_row_bab::MarginRowScheduleRuntimePolicy,
    global_rayon: super::margin_row_bab::GlobalRayonOutcome,
    outer_route: MarginRowScheduleOuterRoute,
    concurrent_route: &str,
    concurrent_resources: super::margin_row_bab::ConcurrentLaneResourceOutcome,
    internal_before_secs: u64,
    uncapped: super::margin_row_bab::MarginRowReserveDecision,
    capped: super::margin_row_bab::MarginRowReserveDecision,
    internal_after_secs: u64,
) -> String {
    let held_reserve_secs = internal_before_secs.saturating_sub(internal_after_secs);
    format!(
        "schema={MARGIN_ROW_SCHEDULE_EXECUTION_SCHEMA} phase=allocation \
         outer_route={} configured_reserve_secs={} contextual_reserve_secs={} \
         configured_adaptive_reserve={} contextual_adaptive_reserve={} \
         configured_reserve_max_frac_bits={} contextual_reserve_max_frac_bits={} \
         configured_release_frac_bits={} contextual_release_frac_bits={} \
         configured_concurrent={} contextual_concurrent={} \
         configured_early_exit={} contextual_early_exit={} \
         configured_verifier_threads={} contextual_verifier_threads={} \
         configured_concurrent_threads={} contextual_concurrent_threads={} \
         host_parallelism={} global_pool_route={} global_pool_requested_threads={} \
         global_pool_actual_threads={} lane_pool_route={} lane_pool_threads={} \
         private_pool_route={} concurrent_route={} concurrent_spawned={} \
         internal_before_secs={} reserve_route={} \
         uncapped_reserve_secs={} capped_reserve_secs={} held_reserve_secs={} \
         internal_after_secs={} sparse_root_requested={} policy_mismatch=false",
        outer_route.stable_token(),
        policy.configured_reserve_secs,
        policy.contextual_reserve_secs,
        policy.configured_adaptive_reserve,
        policy.contextual_adaptive_reserve,
        optional_f64_bits_token(policy.configured_reserve_max_frac_bits),
        optional_f64_bits_token(policy.contextual_reserve_max_frac_bits),
        policy.configured_adaptive_release_frac_bits,
        policy.contextual_adaptive_release_frac_bits,
        policy.configured_concurrent,
        policy.contextual_concurrent,
        policy.configured_early_exit,
        policy.contextual_early_exit,
        optional_usize_token(policy.configured_verifier_threads),
        optional_usize_token(policy.contextual_verifier_threads),
        optional_usize_token(policy.configured_concurrent_threads),
        optional_usize_token(policy.contextual_concurrent_threads),
        optional_usize_token(global_rayon.host_threads),
        global_rayon.route.stable_token(),
        optional_usize_token(global_rayon.requested_threads),
        optional_usize_token(global_rayon.actual_threads),
        concurrent_resources.pool_route.stable_token(),
        optional_usize_token(concurrent_resources.lane_threads),
        concurrent_resources.private_pool_route.stable_token(),
        concurrent_route,
        concurrent_route == "spawned",
        internal_before_secs,
        margin_row_reserve_route_token(capped.route),
        uncapped.reserve_secs,
        capped.reserve_secs,
        held_reserve_secs,
        internal_after_secs,
        capped.enables_scored_sparse_crown(),
    )
}

#[cfg(test)]
#[test]
fn margin_row_schedule_execution_receipt_is_exact_and_versioned() {
    let policy = super::margin_row_bab::MarginRowScheduleRuntimePolicy {
        configured_reserve_secs: 45,
        contextual_reserve_secs: 30,
        configured_adaptive_reserve: true,
        contextual_adaptive_reserve: false,
        configured_reserve_max_frac_bits: Some(0.35_f64.to_bits()),
        contextual_reserve_max_frac_bits: None,
        configured_adaptive_release_frac_bits: 0.40_f64.to_bits(),
        contextual_adaptive_release_frac_bits: 0.50_f64.to_bits(),
        configured_concurrent: true,
        contextual_concurrent: false,
        configured_early_exit: true,
        contextual_early_exit: true,
        configured_verifier_threads: Some(4),
        contextual_verifier_threads: None,
        configured_concurrent_threads: None,
        contextual_concurrent_threads: None,
    };
    let global_rayon = super::margin_row_bab::GlobalRayonOutcome {
        route: super::margin_row_bab::GlobalRayonRoute::Applied,
        requested_threads: Some(4),
        actual_threads: Some(4),
        host_threads: Some(20),
    };
    let concurrent_resources = super::margin_row_bab::ConcurrentLaneResourceOutcome {
        pool_route: super::margin_row_bab::ConcurrentLanePoolRoute::VerifierRemainder,
        lane_threads: Some(16),
        private_pool_route: super::margin_row_bab::PrivatePoolRoute::Built,
    };
    let uncapped = super::margin_row_bab::MarginRowReserveDecision {
        configured_secs: 45,
        reserve_secs: 45,
        route: super::margin_row_bab::MarginRowReserveRoute::AdaptivePreserved,
    };
    let capped = super::margin_row_bab::MarginRowReserveDecision {
        configured_secs: 45,
        reserve_secs: 33,
        route: super::margin_row_bab::MarginRowReserveRoute::AdaptivePreserved,
    };
    assert_eq!(
        render_margin_row_schedule_execution(
            policy,
            global_rayon,
            MarginRowScheduleOuterRoute::Actionable,
            "spawned",
            concurrent_resources,
            95,
            uncapped,
            capped,
            62,
        ),
        "schema=ny-cli/margin-row-schedule-execution/v2 phase=allocation \
         outer_route=actionable configured_reserve_secs=45 contextual_reserve_secs=30 \
         configured_adaptive_reserve=true contextual_adaptive_reserve=false \
         configured_reserve_max_frac_bits=4599976659396224614 \
         contextual_reserve_max_frac_bits=none \
         configured_release_frac_bits=4600877379321698714 \
         contextual_release_frac_bits=4602678819172646912 configured_concurrent=true \
         contextual_concurrent=false configured_early_exit=true contextual_early_exit=true \
         configured_verifier_threads=4 contextual_verifier_threads=none \
         configured_concurrent_threads=none contextual_concurrent_threads=none \
         host_parallelism=20 global_pool_route=applied global_pool_requested_threads=4 \
         global_pool_actual_threads=4 lane_pool_route=verifier_remainder \
         lane_pool_threads=16 private_pool_route=built concurrent_route=spawned \
         concurrent_spawned=true \
         internal_before_secs=95 reserve_route=adaptive_preserved \
         uncapped_reserve_secs=45 capped_reserve_secs=33 held_reserve_secs=33 \
         internal_after_secs=62 sparse_root_requested=false policy_mismatch=false",
    );
}

#[derive(Debug, PartialEq, Eq)]
struct RootJointIntermAlphaFlightReceipt {
    status: crate::flight::FlightStatus,
    details: String,
}

/// Convert the verifier's validated fixed-size observation into one exact
/// flight event. Missing, stale, contradictory, or incomplete observations do
/// not emit a partial event: search must never promote configuration alone.
fn root_joint_interm_alpha_flight_receipt(
    captured: &str,
) -> Option<RootJointIntermAlphaFlightReceipt> {
    let value: serde_json::Value = serde_json::from_str(captured).ok()?;
    let execution = value.get("execution_observations")?.as_object()?;
    if execution.get("schema")?.as_str()? != EXECUTION_OBSERVATIONS_SCHEMA
        || !execution.get("run_active")?.as_bool()?
        || execution.get("recording_conflict")?.as_bool()?
    {
        return None;
    }
    let root = execution.get("root_joint_interm_alpha")?.as_object()?;
    const FIELDS: &[&str] = &[
        "schema",
        "observed",
        "attribution_conflict",
        "counter_overflow",
        "invocations",
        "input_split_invocations",
        "multi_objective_invocations",
        "configured_master",
        "configured_max_dim_override",
        "input_split_configured_max_dim",
        "multi_objective_configured_max_dim",
        "configured_secs",
        "configured_iters",
        "configured_lr_bits",
        "configured_deadline_ascent",
        "configured_min_remaining_secs",
        "configured_max_sel",
        "configured_frozen_stop",
        "configured_pure_chain",
        "configured_bn_gpu_extract",
        "max_effective_iters",
        "target_count",
        "available_budget_ms",
        "effective_slice_ms",
        "configured_slice_work_invocations",
        "configured_iters_binding_invocations",
        "lowered_min_remaining_work_invocations",
        "raised_min_remaining_binding_refusals",
        "work_started",
        "attempts",
        "completed",
        "tightened_count",
        "outlier_tightened_count",
        "target_attempts",
        "base_folds_completed",
        "ascent_iterations_attempted",
        "max_ascent_iterations_attempted",
        "optimizer_steps",
        "ascent_folds_completed",
        "max_selected_rows",
        "selection_cap_bound_targets",
        "frozen_stop_targets",
        "pure_chain_targets",
        "bn_extract_targets",
        "master_disabled",
        "admission_floor_refusals",
        "deadline_route_refusals",
        "slice_refusals",
        "no_target_refusals",
        "capability_refusals",
        "execution_refusals",
    ];
    if root.len() != FIELDS.len() || FIELDS.iter().any(|field| !root.contains_key(*field)) {
        return None;
    }
    if root.get("schema")?.as_str()? != ROOT_JOINT_INTERM_ALPHA_OBSERVATION_SCHEMA
        || !root.get("observed")?.as_bool()?
        || root.get("attribution_conflict")?.as_bool()?
        || root.get("counter_overflow")?.as_bool()?
    {
        return None;
    }
    let integer = |name: &str| root.get(name)?.as_u64();
    let optional_integer = |name: &str| match root.get(name)? {
        serde_json::Value::Null => Some(None),
        value => value.as_u64().map(Some),
    };
    let invocations = integer("invocations")?;
    let input_split_invocations = integer("input_split_invocations")?;
    let multi_objective_invocations = integer("multi_objective_invocations")?;
    let configured_master = root.get("configured_master")?.as_bool()?;
    let configured_max_dim_override = optional_integer("configured_max_dim_override")?;
    let input_split_configured_max_dim = optional_integer("input_split_configured_max_dim")?;
    let multi_objective_configured_max_dim =
        optional_integer("multi_objective_configured_max_dim")?;
    let configured_secs = integer("configured_secs")?;
    let configured_iters = integer("configured_iters")?;
    let configured_lr_bits = u32::try_from(integer("configured_lr_bits")?).ok()?;
    let configured_lr = f32::from_bits(configured_lr_bits);
    let configured_deadline_ascent = root.get("configured_deadline_ascent")?.as_bool()?;
    let configured_min_remaining_secs = integer("configured_min_remaining_secs")?;
    let configured_max_sel = integer("configured_max_sel")?;
    let configured_frozen_stop = root.get("configured_frozen_stop")?.as_bool()?;
    let configured_pure_chain = root.get("configured_pure_chain")?.as_bool()?;
    let configured_bn_gpu_extract = root.get("configured_bn_gpu_extract")?.as_bool()?;
    let max_effective_iters = integer("max_effective_iters")?;
    let target_count = integer("target_count")?;
    let available_budget_ms = integer("available_budget_ms")?;
    let effective_slice_ms = integer("effective_slice_ms")?;
    let configured_slice_work_invocations = integer("configured_slice_work_invocations")?;
    let configured_iters_binding_invocations = integer("configured_iters_binding_invocations")?;
    let lowered_min_remaining_work_invocations = integer("lowered_min_remaining_work_invocations")?;
    let raised_min_remaining_binding_refusals = integer("raised_min_remaining_binding_refusals")?;
    let work_started = integer("work_started")?;
    let attempts = integer("attempts")?;
    let completed = integer("completed")?;
    let tightened_count = integer("tightened_count")?;
    let outlier_tightened_count = integer("outlier_tightened_count")?;
    let target_attempts = integer("target_attempts")?;
    let base_folds_completed = integer("base_folds_completed")?;
    let ascent_iterations_attempted = integer("ascent_iterations_attempted")?;
    let max_ascent_iterations_attempted = integer("max_ascent_iterations_attempted")?;
    let optimizer_steps = integer("optimizer_steps")?;
    let ascent_folds_completed = integer("ascent_folds_completed")?;
    let max_selected_rows = integer("max_selected_rows")?;
    let selection_cap_bound_targets = integer("selection_cap_bound_targets")?;
    let frozen_stop_targets = integer("frozen_stop_targets")?;
    let pure_chain_targets = integer("pure_chain_targets")?;
    let bn_extract_targets = integer("bn_extract_targets")?;
    let master_disabled = integer("master_disabled")?;
    let admission_floor_refusals = integer("admission_floor_refusals")?;
    let deadline_route_refusals = integer("deadline_route_refusals")?;
    let slice_refusals = integer("slice_refusals")?;
    let no_target_refusals = integer("no_target_refusals")?;
    let capability_refusals = integer("capability_refusals")?;
    let execution_refusals = integer("execution_refusals")?;
    let routes = input_split_invocations.checked_add(multi_objective_invocations)?;
    let maximum_ascent_attempts = target_attempts.checked_mul(max_effective_iters)?;
    let classified = [
        completed,
        master_disabled,
        admission_floor_refusals,
        deadline_route_refusals,
        slice_refusals,
        no_target_refusals,
        capability_refusals,
        execution_refusals,
    ]
    .into_iter()
    .try_fold(0u64, u64::checked_add)?;
    let route = match (input_split_invocations > 0, multi_objective_invocations > 0) {
        (true, false) => "input_split",
        (false, true) => "multi_objective",
        (true, true) => "mixed",
        (false, false) => return None,
    };
    if invocations == 0
        || routes != invocations
        || classified != invocations
        || (input_split_invocations > 0) != input_split_configured_max_dim.is_some()
        || (multi_objective_invocations > 0) != multi_objective_configured_max_dim.is_some()
        || input_split_configured_max_dim == Some(0)
        || multi_objective_configured_max_dim == Some(0)
        || configured_max_dim_override.is_some_and(|override_value| {
            override_value == 0
                || input_split_configured_max_dim.is_some_and(|value| value != override_value)
                || multi_objective_configured_max_dim.is_some_and(|value| value != override_value)
        })
        || (configured_max_dim_override.is_none()
            && (input_split_configured_max_dim.is_some_and(|value| value != 32_768)
                || multi_objective_configured_max_dim.is_some_and(|value| {
                    value
                        != if configured_master && configured_deadline_ascent {
                            32_768
                        } else {
                            2_048
                        }
                })))
        || !configured_lr.is_finite()
        || attempts != completed
        || attempts > invocations
        || work_started > invocations
        || configured_slice_work_invocations > work_started
        || configured_iters_binding_invocations > work_started
        || lowered_min_remaining_work_invocations > work_started
        || raised_min_remaining_binding_refusals > admission_floor_refusals
        || (configured_slice_work_invocations > 0
            && (configured_secs == 0
                || configured_secs
                    .checked_mul(1_000)
                    .is_none_or(|configured_ms| effective_slice_ms < configured_ms)))
        || (configured_iters_binding_invocations > 0
            && (configured_iters == 0
                || max_effective_iters != configured_iters
                || max_ascent_iterations_attempted != configured_iters))
        || (work_started > 0) != (target_attempts > 0)
        || target_attempts > target_count
        || base_folds_completed > target_attempts
        || tightened_count > base_folds_completed
        || (outlier_tightened_count > 0 && (input_split_invocations == 0 || attempts == 0))
        || ascent_iterations_attempted > maximum_ascent_attempts
        || max_ascent_iterations_attempted > max_effective_iters
        || max_ascent_iterations_attempted > ascent_iterations_attempted
        || optimizer_steps > ascent_iterations_attempted
        || ascent_folds_completed > optimizer_steps
        || selection_cap_bound_targets > target_attempts
        || frozen_stop_targets > target_attempts
        || pure_chain_targets > target_attempts
        || bn_extract_targets > target_attempts
        || max_selected_rows > configured_max_sel
        || (selection_cap_bound_targets > 0 && max_selected_rows != configured_max_sel)
        || (configured_max_sel == 0 && (max_selected_rows > 0 || selection_cap_bound_targets > 0))
        || (!configured_frozen_stop && frozen_stop_targets > 0)
        || (!configured_pure_chain && pure_chain_targets > 0)
        || (!configured_bn_gpu_extract && bn_extract_targets > 0)
        || (lowered_min_remaining_work_invocations > 0
            && (multi_objective_invocations == 0 || configured_min_remaining_secs >= 240))
        || (raised_min_remaining_binding_refusals > 0
            && (multi_objective_invocations == 0 || configured_min_remaining_secs <= 240))
        || (max_effective_iters == 0
            && (ascent_iterations_attempted > 0
                || max_ascent_iterations_attempted > 0
                || optimizer_steps > 0
                || ascent_folds_completed > 0))
        || tightened_count > target_count
        || effective_slice_ms > available_budget_ms
        || (attempts > 0 && (!configured_master || target_count == 0 || effective_slice_ms == 0))
        || (!configured_master
            && (target_attempts > 0 || tightened_count > 0 || outlier_tightened_count > 0))
    {
        return None;
    }
    let status = if attempts > 0 {
        crate::flight::FlightStatus::Ran
    } else {
        crate::flight::FlightStatus::Skipped
    };
    let configured_max_dim_override =
        configured_max_dim_override.map_or_else(|| "none".to_string(), |value| value.to_string());
    let input_split_configured_max_dim = input_split_configured_max_dim
        .map_or_else(|| "none".to_string(), |value| value.to_string());
    let multi_objective_configured_max_dim = multi_objective_configured_max_dim
        .map_or_else(|| "none".to_string(), |value| value.to_string());
    Some(RootJointIntermAlphaFlightReceipt {
        status,
        details: format!(
            "schema={ROOT_JOINT_INTERM_ALPHA_FLIGHT_SCHEMA} phase=terminal \
             observation_schema={ROOT_JOINT_INTERM_ALPHA_OBSERVATION_SCHEMA} route={route} \
             configured_master={configured_master} \
             configured_max_dim_override={configured_max_dim_override} \
             input_split_configured_max_dim={input_split_configured_max_dim} \
             multi_objective_configured_max_dim={multi_objective_configured_max_dim} \
             configured_secs={configured_secs} configured_iters={configured_iters} \
             configured_lr_bits={configured_lr_bits} \
             configured_deadline_ascent={configured_deadline_ascent} \
             configured_min_remaining_secs={configured_min_remaining_secs} \
             configured_max_sel={configured_max_sel} \
             configured_frozen_stop={configured_frozen_stop} \
             configured_pure_chain={configured_pure_chain} \
             configured_bn_gpu_extract={configured_bn_gpu_extract} \
             max_effective_iters={max_effective_iters} \
             invocations={invocations} input_split_invocations={input_split_invocations} \
             multi_objective_invocations={multi_objective_invocations} \
             target_count={target_count} available_budget_ms={available_budget_ms} \
             effective_slice_ms={effective_slice_ms} \
             configured_slice_work_invocations={configured_slice_work_invocations} \
             configured_iters_binding_invocations={configured_iters_binding_invocations} \
             lowered_min_remaining_work_invocations={lowered_min_remaining_work_invocations} \
             raised_min_remaining_binding_refusals={raised_min_remaining_binding_refusals} \
             work_started={work_started} \
             attempts={attempts} completed={completed} tightened_count={tightened_count} \
             outlier_tightened_count={outlier_tightened_count} \
             target_attempts={target_attempts} base_folds_completed={base_folds_completed} \
             ascent_iterations_attempted={ascent_iterations_attempted} \
             max_ascent_iterations_attempted={max_ascent_iterations_attempted} \
             optimizer_steps={optimizer_steps} \
             ascent_folds_completed={ascent_folds_completed} \
             max_selected_rows={max_selected_rows} \
             selection_cap_bound_targets={selection_cap_bound_targets} \
             frozen_stop_targets={frozen_stop_targets} \
             pure_chain_targets={pure_chain_targets} bn_extract_targets={bn_extract_targets} \
             master_disabled={master_disabled} \
             admission_floor_refusals={admission_floor_refusals} \
             deadline_route_refusals={deadline_route_refusals} \
             slice_refusals={slice_refusals} no_target_refusals={no_target_refusals} \
             capability_refusals={capability_refusals} execution_refusals={execution_refusals}"
        ),
    })
}

fn note_root_joint_interm_alpha_execution(captured: Option<&str>) {
    let Some(receipt) = captured.and_then(root_joint_interm_alpha_flight_receipt) else {
        return;
    };
    crate::flight::note(
        "root_joint_interm_alpha_execution",
        receipt.status,
        Some(receipt.details),
    );
}

#[derive(Debug, PartialEq, Eq)]
struct MoKfsbFlightReceipt {
    status: crate::flight::FlightStatus,
    details: String,
}

/// Convert the verifier's closed wave-kFSB aggregate into one terminal flight
/// event. The captured JSON is an untrusted boundary: accept only the exact
/// versioned object and producer-realizable checked aggregates. In particular,
/// configuration delivery by itself is not selector execution evidence.
fn mo_kfsb_flight_receipt(captured: &str) -> Option<MoKfsbFlightReceipt> {
    let value: serde_json::Value = serde_json::from_str(captured).ok()?;
    let execution = value.get("execution_observations")?.as_object()?;
    if execution.get("schema")?.as_str()? != EXECUTION_OBSERVATIONS_SCHEMA
        || !execution.get("run_active")?.as_bool()?
        || execution.get("recording_conflict")?.as_bool()?
    {
        return None;
    }
    let observed = execution.get("mo_kfsb")?.as_object()?;
    const FIELDS: &[&str] = &[
        "schema",
        "observed",
        "attribution_conflict",
        "counter_overflow",
        "canonical_master",
        "legacy_childsim",
        "configured_master",
        "configured_candidates",
        "effective_candidates",
        "configured_reduce_op",
        "effective_reduce_op",
        "heuristic_eligible",
        "branch_opportunities",
        "offered_domains",
        "nonempty_domain_opportunities",
        "candidate_eligible_opportunities",
        "typed_select_opportunities",
        "lower_master_opportunities",
        "effective_master_opportunities",
        "route_eligible_opportunities",
        "selector_waves",
        "selector_domains",
        "committed_waves",
        "committed_parents",
        "committed_leaves",
        "force_on_binding_waves",
        "master_binding_refusals",
    ];
    if observed.len() != FIELDS.len()
        || FIELDS.iter().any(|field| !observed.contains_key(*field))
        || observed.get("schema")?.as_str()? != MO_KFSB_OBSERVATION_SCHEMA
        || !observed.get("observed")?.as_bool()?
        || observed.get("attribution_conflict")?.as_bool()?
        || observed.get("counter_overflow")?.as_bool()?
    {
        return None;
    }
    let canonical_master = match observed.get("canonical_master")?.as_str()? {
        value @ ("absent" | "exact_enable" | "exact_disable" | "rejected") => value,
        _ => return None,
    };
    let boolean = |name: &str| observed.get(name)?.as_bool();
    let integer = |name: &str| observed.get(name)?.as_u64();
    let legacy_childsim = boolean("legacy_childsim")?;
    let configured_master = boolean("configured_master")?;
    let configured_candidates = integer("configured_candidates")?;
    let effective_candidates = integer("effective_candidates")?;
    let reduce_op = |name: &str| match observed.get(name)?.as_str()? {
        value @ ("min" | "max" | "mean") => Some(value),
        _ => None,
    };
    let configured_reduce_op = reduce_op("configured_reduce_op")?;
    let effective_reduce_op = reduce_op("effective_reduce_op")?;
    let heuristic_eligible = boolean("heuristic_eligible")?;
    let branch_opportunities = integer("branch_opportunities")?;
    let offered_domains = integer("offered_domains")?;
    let nonempty_domain_opportunities = integer("nonempty_domain_opportunities")?;
    let candidate_eligible_opportunities = integer("candidate_eligible_opportunities")?;
    let typed_select_opportunities = integer("typed_select_opportunities")?;
    let lower_master_opportunities = integer("lower_master_opportunities")?;
    let effective_master_opportunities = integer("effective_master_opportunities")?;
    let route_eligible_opportunities = integer("route_eligible_opportunities")?;
    let selector_waves = integer("selector_waves")?;
    let selector_domains = integer("selector_domains")?;
    let committed_waves = integer("committed_waves")?;
    let committed_parents = integer("committed_parents")?;
    let committed_leaves = integer("committed_leaves")?;
    let force_on_binding_waves = integer("force_on_binding_waves")?;
    let master_binding_refusals = integer("master_binding_refusals")?;
    let committed_leaf_capacity =
        committed_parents.checked_mul(1_u64 << MO_KFSB_MAX_MULTI_OBJECTIVE_SPLIT_DEPTH)?;
    let selector_wave_floor = route_eligible_opportunities
        .saturating_sub(branch_opportunities.checked_sub(effective_master_opportunities)?);
    let exact_disable_refusal_floor = route_eligible_opportunities
        .saturating_sub(branch_opportunities.checked_sub(lower_master_opportunities)?);
    let exact_enable_force_on_floor = committed_waves.saturating_sub(lower_master_opportunities);
    let nonselector_waves = branch_opportunities.checked_sub(selector_waves)?;
    let selector_domain_capacity = offered_domains.checked_sub(nonselector_waves)?;
    let noncommitting_selector_waves = selector_waves.checked_sub(committed_waves)?;
    let committed_parent_capacity = selector_domains.checked_sub(noncommitting_selector_waves)?;

    // Every observation is one closed selector opportunity. Common policy
    // values above are non-null only after such an opportunity, and every
    // aggregate below is bounded by facts the producer observed directly.
    let opportunity_counts = [
        nonempty_domain_opportunities,
        candidate_eligible_opportunities,
        typed_select_opportunities,
        lower_master_opportunities,
        effective_master_opportunities,
        route_eligible_opportunities,
        selector_waves,
        committed_waves,
        force_on_binding_waves,
        master_binding_refusals,
    ];
    if branch_opportunities == 0
        || opportunity_counts
            .into_iter()
            .any(|count| count > branch_opportunities)
        || offered_domains == 0
        || nonempty_domain_opportunities != branch_opportunities
        || nonempty_domain_opportunities > offered_domains
        || candidate_eligible_opportunities
            != if effective_candidates > 0 {
                branch_opportunities
            } else {
                0
            }
        || (effective_reduce_op == "mean" && configured_reduce_op != "mean")
        || (typed_select_opportunities > 0 && effective_reduce_op != "min")
        || typed_select_opportunities > candidate_eligible_opportunities
        || (!heuristic_eligible && typed_select_opportunities > 0)
        || route_eligible_opportunities > nonempty_domain_opportunities
        || ((!heuristic_eligible || effective_candidates == 0) && route_eligible_opportunities > 0)
        || lower_master_opportunities
            != if configured_master {
                branch_opportunities
            } else {
                typed_select_opportunities
            }
        || selector_domains > offered_domains
        || selector_domains > selector_domain_capacity
        || (selector_waves == branch_opportunities && selector_domains != offered_domains)
        || (selector_domains > 0 && selector_waves == 0)
        || (selector_domains > 0 && route_eligible_opportunities == 0)
        || selector_waves > route_eligible_opportunities
        || selector_waves > selector_domains
        || selector_waves > effective_master_opportunities
        || selector_waves < selector_wave_floor
        || ((!heuristic_eligible
            || effective_candidates == 0
            || effective_master_opportunities == 0)
            && selector_waves > 0)
        || committed_waves > selector_waves
        || committed_waves > route_eligible_opportunities
        || committed_waves > nonempty_domain_opportunities
        || committed_parents > selector_domains
        || committed_parents > committed_parent_capacity
        || (committed_waves > 0) != (committed_parents > 0)
        || committed_waves > committed_parents
        || (committed_leaves > 0 && committed_parents == 0)
        || committed_leaves > committed_leaf_capacity
        || force_on_binding_waves > committed_waves
        || force_on_binding_waves > branch_opportunities.checked_sub(lower_master_opportunities)?
        || master_binding_refusals > lower_master_opportunities
        || master_binding_refusals > route_eligible_opportunities
        || match canonical_master {
            "absent" => {
                effective_master_opportunities
                    != if legacy_childsim {
                        branch_opportunities
                    } else {
                        lower_master_opportunities
                    }
                    || force_on_binding_waves > 0
                    || master_binding_refusals > 0
            }
            "exact_enable" => {
                legacy_childsim
                    || effective_master_opportunities != branch_opportunities
                    || force_on_binding_waves < exact_enable_force_on_floor
                    || master_binding_refusals > 0
            }
            "exact_disable" => {
                legacy_childsim
                    || effective_master_opportunities > 0
                    || force_on_binding_waves > 0
                    || master_binding_refusals < exact_disable_refusal_floor
            }
            "rejected" => {
                legacy_childsim
                    || effective_master_opportunities > 0
                    || force_on_binding_waves > 0
                    || master_binding_refusals > 0
            }
            _ => true,
        }
    {
        return None;
    }

    let status = if selector_waves > 0 {
        crate::flight::FlightStatus::Ran
    } else {
        crate::flight::FlightStatus::Skipped
    };
    Some(MoKfsbFlightReceipt {
        status,
        details: format!(
            "schema={MO_KFSB_FLIGHT_SCHEMA} phase=terminal \
             observation_schema={MO_KFSB_OBSERVATION_SCHEMA} \
             canonical_master={canonical_master} legacy_childsim={legacy_childsim} \
             configured_master={configured_master} \
             configured_candidates={configured_candidates} \
             effective_candidates={effective_candidates} \
             configured_reduce_op={configured_reduce_op} \
             effective_reduce_op={effective_reduce_op} \
             heuristic_eligible={heuristic_eligible} \
             branch_opportunities={branch_opportunities} offered_domains={offered_domains} \
             nonempty_domain_opportunities={nonempty_domain_opportunities} \
             candidate_eligible_opportunities={candidate_eligible_opportunities} \
             typed_select_opportunities={typed_select_opportunities} \
             lower_master_opportunities={lower_master_opportunities} \
             effective_master_opportunities={effective_master_opportunities} \
             route_eligible_opportunities={route_eligible_opportunities} \
             selector_waves={selector_waves} selector_domains={selector_domains} \
             committed_waves={committed_waves} committed_parents={committed_parents} \
             committed_leaves={committed_leaves} \
             force_on_binding_waves={force_on_binding_waves} \
             master_binding_refusals={master_binding_refusals}"
        ),
    })
}

fn note_mo_kfsb_execution(captured: Option<&str>) {
    let Some(receipt) = captured.and_then(mo_kfsb_flight_receipt) else {
        return;
    };
    crate::flight::note("mo_kfsb_execution", receipt.status, Some(receipt.details));
}

#[derive(Debug, PartialEq, Eq)]
struct MoAlphaStepFlightReceipt {
    status: crate::flight::FlightStatus,
    details: String,
}

/// Convert the producer's fixed-size every-fourth alpha observation into one
/// exact terminal event. The captured JSON is an untrusted boundary: policy,
/// schedule, and work counters must form a producer-realizable closed
/// aggregate before any flight evidence is emitted.
fn mo_alpha_step_flight_receipt(captured: &str) -> Option<MoAlphaStepFlightReceipt> {
    let value: serde_json::Value = serde_json::from_str(captured).ok()?;
    let execution = value.get("execution_observations")?.as_object()?;
    if execution.get("schema")?.as_str()? != EXECUTION_OBSERVATIONS_SCHEMA
        || !execution.get("run_active")?.as_bool()?
        || execution.get("recording_conflict")?.as_bool()?
    {
        return None;
    }
    let observed = execution.get("mo_alpha_step")?.as_object()?;
    const FIELDS: &[&str] = &[
        "schema",
        "observed",
        "effective_alpha_step",
        "effective_beta_spsa",
        "schedule_period",
        "alpha_round_remainder",
        "attribution_conflict",
        "counter_overflow",
        "optimizer_invocations",
        "eligible_invocations",
        "eligible_iterations",
        "fourth_iteration_opportunities",
        "alpha_rounds_scheduled",
        "beta_rounds_scheduled",
        "alpha_rounds_completed",
        "alpha_rounds_refused",
        "alpha_updates_applied",
        "perturbed_coordinates",
    ];
    if observed.len() != FIELDS.len()
        || FIELDS.iter().any(|field| !observed.contains_key(*field))
        || observed.get("schema")?.as_str()? != MO_ALPHA_STEP_OBSERVATION_SCHEMA
        || observed.get("attribution_conflict")?.as_bool()?
        || observed.get("counter_overflow")?.as_bool()?
    {
        return None;
    }

    let boolean = |name: &str| observed.get(name)?.as_bool();
    let optional_boolean = |name: &str| match observed.get(name)? {
        serde_json::Value::Null => Some(None),
        value => value.as_bool().map(Some),
    };
    let integer = |name: &str| observed.get(name)?.as_u64();
    let was_observed = boolean("observed")?;
    let effective_alpha_step = optional_boolean("effective_alpha_step")?;
    let effective_beta_spsa = optional_boolean("effective_beta_spsa")?;
    let schedule_period = integer("schedule_period")?;
    let alpha_round_remainder = integer("alpha_round_remainder")?;
    let optimizer_invocations = integer("optimizer_invocations")?;
    let eligible_invocations = integer("eligible_invocations")?;
    let eligible_iterations = integer("eligible_iterations")?;
    let fourth_iteration_opportunities = integer("fourth_iteration_opportunities")?;
    let alpha_rounds_scheduled = integer("alpha_rounds_scheduled")?;
    let beta_rounds_scheduled = integer("beta_rounds_scheduled")?;
    let alpha_rounds_completed = integer("alpha_rounds_completed")?;
    let alpha_rounds_refused = integer("alpha_rounds_refused")?;
    let alpha_updates_applied = integer("alpha_updates_applied")?;
    let perturbed_coordinates = integer("perturbed_coordinates")?;
    let scheduled_rounds = alpha_rounds_scheduled.checked_add(beta_rounds_scheduled)?;
    let alpha_outcomes = alpha_rounds_completed.checked_add(alpha_rounds_refused)?;
    let fourth_iteration_floor =
        fourth_iteration_opportunities.checked_mul(MO_ALPHA_STEP_SCHEDULE_PERIOD)?;
    let fourth_iteration_ceiling = eligible_invocations
        .checked_mul(MO_ALPHA_STEP_SCHEDULE_PERIOD - 1)?
        .checked_add(fourth_iteration_floor)?;

    if schedule_period != MO_ALPHA_STEP_SCHEDULE_PERIOD
        || alpha_round_remainder != MO_ALPHA_STEP_ROUND_REMAINDER
        || was_observed != (optimizer_invocations > 0)
        || effective_alpha_step.is_some() != was_observed
        || effective_beta_spsa.is_some() != was_observed
        || eligible_invocations > optimizer_invocations
        || (eligible_iterations > 0 && eligible_invocations == 0)
        || fourth_iteration_opportunities > eligible_iterations
        || eligible_iterations < fourth_iteration_floor
        || eligible_iterations > fourth_iteration_ceiling
        || scheduled_rounds != eligible_iterations
        || alpha_outcomes != alpha_rounds_scheduled
        || alpha_updates_applied != alpha_rounds_completed
        || (alpha_rounds_scheduled == 0) != (perturbed_coordinates == 0)
        || perturbed_coordinates < alpha_rounds_scheduled
        || (eligible_invocations == 1
            && alpha_rounds_scheduled > 0
            && !perturbed_coordinates.is_multiple_of(alpha_rounds_scheduled))
        || (effective_beta_spsa == Some(false)
            && (eligible_invocations > 0
                || eligible_iterations > 0
                || fourth_iteration_opportunities > 0
                || alpha_rounds_scheduled > 0
                || beta_rounds_scheduled > 0))
        || (effective_alpha_step == Some(true)
            && alpha_rounds_scheduled != fourth_iteration_opportunities)
        || (effective_alpha_step == Some(false)
            && (alpha_rounds_scheduled > 0
                || alpha_rounds_completed > 0
                || alpha_rounds_refused > 0
                || alpha_updates_applied > 0
                || perturbed_coordinates > 0))
    {
        return None;
    }

    let effective_token = |value: Option<bool>| match value {
        Some(true) => "true",
        Some(false) => "false",
        None => "none",
    };
    let status = if alpha_rounds_completed > 0 {
        crate::flight::FlightStatus::Ran
    } else {
        crate::flight::FlightStatus::Skipped
    };
    Some(MoAlphaStepFlightReceipt {
        status,
        details: format!(
            "schema={MO_ALPHA_STEP_FLIGHT_SCHEMA} phase=terminal \
             observation_schema={MO_ALPHA_STEP_OBSERVATION_SCHEMA} \
             observed={was_observed} \
             effective_alpha_step={} effective_beta_spsa={} \
             schedule_period={schedule_period} \
             alpha_round_remainder={alpha_round_remainder} \
             optimizer_invocations={optimizer_invocations} \
             eligible_invocations={eligible_invocations} \
             eligible_iterations={eligible_iterations} \
             fourth_iteration_opportunities={fourth_iteration_opportunities} \
             alpha_rounds_scheduled={alpha_rounds_scheduled} \
             beta_rounds_scheduled={beta_rounds_scheduled} \
             alpha_rounds_completed={alpha_rounds_completed} \
             alpha_rounds_refused={alpha_rounds_refused} \
             alpha_updates_applied={alpha_updates_applied} \
             perturbed_coordinates={perturbed_coordinates}",
            effective_token(effective_alpha_step),
            effective_token(effective_beta_spsa),
        ),
    })
}

fn note_mo_alpha_step_execution(captured: Option<&str>) {
    let Some(receipt) = captured.and_then(mo_alpha_step_flight_receipt) else {
        return;
    };
    crate::flight::note(
        "mo_alpha_step_execution",
        receipt.status,
        Some(receipt.details),
    );
}

/// Compute the internal `ny --timeout` from the scored competition budget.
///
/// Internal grace = `max(5, TIMEOUT / 20)`. The internal deadline fires below the
/// scored budget so the JSON verdict is flushed before the budget elapses. For tiny
/// budgets (`< grace`), give `ny` the whole budget rather than a zero/negative
/// internal timeout (the OS backstop in the wrapper still applies). This matches
/// `run_instance.sh` exactly.
pub(crate) fn internal_timeout_secs(timeout_secs: u64) -> u64 {
    let grace = (timeout_secs / 20).max(MIN_RESULTS_FLUSH_RESERVE_SECS);
    timeout_secs
        .checked_sub(grace)
        .filter(|&t| t >= 1)
        .unwrap_or(timeout_secs)
}

/// What must be left after branch-and-bound decides to stop, measured
/// (#scored-wall-clamp).
///
/// TWO COSTS ARE PAID AFTER THE STOP DECISION, and this reserve is their sum
/// plus headroom — not a percentage, not a guess:
///
/// * the IN-FLIGHT BATCH. The disjunctive loop's fine-grained termination
///   checks bracket the per-domain and per-child work, but the batched rebound
///   at the top of an iteration runs to completion once entered. MEASURED on
///   `isomorphic_acasxu_2026` rows 4/15/42 at the official 100 s budget: the
///   process exits 0.498 s, 1.198 s and 1.294 s after the wall — one rebound at
///   `batch_size = 2048`;
/// * PUBLICATION. Writing, re-reading and confirming RESULTS_FILE: measured at
///   9-18 ms on every compliant arm.
///
/// The in-flight batch is the larger of the two, and the loop no longer starts
/// one it has measured itself unable to finish (`BabWall::cannot_finish`), so
/// the tail is the ERROR in that estimate rather than a whole batch: RE-MEASURED
/// with the guard in place, the process exits 0.00-0.19 s after the wall across
/// 70 armed runs. 2 s is therefore ~10x the worst tail actually observed, and
/// the in-process watchdog at `budget + WATCHDOG_GRACE_SECS` remains the
/// backstop below it.
///
/// IT IS NOT FREE TO OVER-RESERVE. At 3 s (this constant's first value) the
/// wall sat at 97 s and the guard's early stop at ~95 s — exactly where
/// `instance_42` decides, measured at 95.7 s and 96.7 s in the dark arm. Every
/// second of reserve is a second of proof search, and on a family whose rows
/// pile up against the wall it is paid in rows.
///
/// WHY NOT THE HISTORICAL TIER. [`internal_timeout_secs`] reserves
/// `max(budget/20, 5)` — 5 s at budget 100, 9 s at 180, 24 s at 480 — for a
/// publication step that costs milliseconds. That reserve is why other families
/// leave 5-11 % of their budget unused, and here it was ALSO cutting rows: with
/// the wall at the 95 s tier, `instance_42` (which the dark arm decides at
/// 96.7 s, inside its 100 s budget) was demoted to `timeout`. The tier is left
/// alone for every other purpose it serves; the STOP is derived from the
/// official budget, which is the number that actually scores.
///
/// A lane whose in-flight unit is larger than this must measure its own tail
/// before arming the clamp. That is what the per-family preset key is for.
const SCORED_WALL_STOP_RESERVE_SECS: u64 = 2;

/// The ABSOLUTE instant branch-and-bound must stop by (#scored-wall-clamp).
///
/// THE DERIVATION: `command_start + scored_budget - SCORED_WALL_STOP_RESERVE_SECS`.
/// Every term is the honest one — the OFFICIAL budget, not ny's internal tier,
/// and a reserve measured from what the stop actually costs.
///
/// WHY AN INSTANT AND NOT A DURATION. The tier is a duration, and handed to a
/// lane as one it silently restarts the clock: every second spent before the
/// lane was constructed — model load, spec parse, the isomorphic falsifier's
/// 20-30 s — is charged once in reality and then forgotten in the lane's own
/// accounting. This family re-anchors THREE times on the way down
/// (`run_relational_vnncomp`'s arm deadline, `verify_difference_bounds`'s
/// `deadline`, the BaB's own `now`). Anchoring ONCE at the command entry and
/// passing the resulting instant means the seconds already gone are already
/// charged, whatever a callee believes its remaining budget to be.
///
/// This is the number no downstream policy may breach. A lane may legitimately
/// inflate its own timeout — the disjunctive input-split search is
/// non-monotonic in its deadline, so a nearer one buys looser bounds and more
/// splits — but inflating a HORIZON must not inflate a STOP.
///
/// The `.max(1)` mirrors [`internal_timeout_secs`]'s own floor: a budget at or
/// below the reserve yields a stop of one second, never a wall in the past.
fn scored_wall_from_budget(
    command_start: std::time::Instant,
    timeout_secs: u64,
) -> std::time::Instant {
    command_start
        + std::time::Duration::from_secs(
            timeout_secs
                .saturating_sub(SCORED_WALL_STOP_RESERVE_SECS)
                .max(1),
        )
}

/// Smallest whole-second publication margin used by the historical wrapper.
///
/// The historical policy scales this to 5% on long rows. A category that
/// explicitly assigns zero time to post-BaB PGD gives that scalable tail back
/// to proof search while retaining this fixed margin for verdict translation,
/// trusted-oracle work, and atomic RESULTS_FILE publication.
const MIN_RESULTS_FLUSH_RESERVE_SECS: u64 = 5;

const SAFENLP_SHORT_GRACE_ENV: &str = "NY_SAFENLP_SHORT_GRACE";
const SAFENLP_SHORT_GRACE_MAX_BUDGET_SECS: u64 = 30;
const SAFENLP_SHORT_GRACE_SECS: u64 = 1;
/// Stop admitting final renames before the hard-stop boundary. Rendering and
/// staging happen before admission, so this interval contains only one rename
/// plus the explicit publication acknowledgement.
const SAFENLP_SHORT_PUBLICATION_MARGIN: std::time::Duration = std::time::Duration::from_millis(500);
/// Leave bounded time for direct SIGKILL delivery and for the harness to reap
/// the process. The solver still receives the exact 19-second internal timeout
/// on an official 20-second row; this guard belongs only to hard-stop delivery,
/// not the solver budget calculation.
const SAFENLP_SHORT_HARD_STOP_MARGIN: std::time::Duration = std::time::Duration::from_millis(250);
/// A child-consumed prepare ACK must arrive this far before the hard stop,
/// leaving a distinct bounded window for the helper to receive the finalize
/// byte before canonical H.
const SAFENLP_SHORT_FINALIZATION_WINDOW: std::time::Duration =
    std::time::Duration::from_millis(100);

/// Central declared read for the shared beta/GPU diagnostic switch.
///
/// This deliberately remains a live read for parity with the older probe
/// sites. It nonetheless passes through `ny-levers`, so the two terminal
/// readouts added in this module do not create new unenumerated raw-read debt.
fn beta_gpu_probe_armed() -> bool {
    ny_levers::read(&ny_levers::decls::telemetry::BETA_GPU_PROBE)
        .value
        .as_bool()
}

/// Dark gate for the GENERAL pre-Softmax attack-scoring objective
/// (`NY_ATTACK_PRE_SOFTMAX_OBJECTIVE`).
///
/// Disarmed — the shipped default — this returns `false` before anything reads
/// the model, the property, or any pre-Softmax tensor, so the attack lane's
/// objective, direction row and DLR denominator are the historical
/// post-Softmax ones and the path is byte-identical to the unwired tree.
///
/// DELIVERY SEAM (#lever-reachability, 2026-08-23):
/// `NY_ATTACK_PRE_SOFTMAX_OBJECTIVE` still wins in both directions; absent, the
/// typed `attack.pre_softmax_objective` key decides. It changes which
/// counterexamples are findable, and a counterexample only becomes `sat`
/// through the unchanged trusted-oracle gate.
fn pre_softmax_attack_objective_armed() -> bool {
    crate::preset_gates::attack_pre_softmax_objective_armed()
}

/// Run the PROVEN terminal-Softmax strip guard as an ATTACK-SCORING admission.
///
/// Returns `None` on every refusal, after LOGGING the refusal reason once —
/// a silent refusal here is a debugging trap, and the whole point of the lever
/// is to be able to tell "the guard said no" from "the guard said yes and the
/// search still found nothing".
///
/// The check itself is CHEAP: `ny_onnx::admit_pre_softmax_attack_scoring` is a
/// handful of shape and constraint-shape tests over already-parsed metadata —
/// no forward pass and no tensor arithmetic. It is called with a model this
/// lane had to load anyway, so an armed refusal costs no extra I/O and a
/// disarmed run never reaches it at all.
fn admit_pre_softmax_attack_objective(
    model: &ny_onnx::OnnxModel,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
) -> Option<ny_onnx::PreSoftmaxAttackAdmission> {
    match ny_onnx::admit_pre_softmax_attack_scoring(model, spec) {
        Ok(admission) => {
            println!(
                "ORT-refine grad lane: pre-Softmax attack objective ADMITTED \
                 (tensor {}, {} outputs, true label {}); acceptance is unchanged \
                 (trusted ORT forward on the ORIGINAL graph)",
                admission.pre_softmax_tensor, admission.num_outputs, admission.true_label
            );
            Some(admission)
        }
        Err(reason) => {
            println!(
                "ORT-refine grad lane: pre-Softmax attack objective REFUSED ({reason}); \
                 keeping the historical post-Softmax objective"
            );
            None
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum InternalTimeoutRoute {
    Historical,
    SafeNlpShortGrace,
    /// An explicit preset opt-out for both post-BaB attack consumers assigns
    /// the scalable historical tail to proof search, retaining only the fixed
    /// publication margin.
    PresetProofTail,
    /// #flush-grace: a typed `bab.phase_budget.results_flush_grace_secs`
    /// states the family's own publication reserve outright, replacing the
    /// historical `max(5, budget/20)` rule. Outranks the proof-tail route
    /// (both come from the same preset, and the explicit number is the more
    /// specific statement) and never displaces the SafeNLP short-grace route,
    /// which owns a separate hard-stop and single-writer publication lane.
    PresetFlushGrace,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct InternalTimeoutDecision {
    solver_timeout_secs: u64,
    effective_flush_reserve_secs: u64,
    historical_solver_timeout_secs: u64,
    route: InternalTimeoutRoute,
}

/// VNN-COMP wrapper policy for the attack that runs after the in-process
/// verifier returns `unknown`/`timeout`.
///
/// This independent wrapper lane has its own typed preset switch. The engine's
/// `post_bab_pgd_fraction` remains solely an engine schedule: zero alone cannot
/// disable this lane. A preset that explicitly disables both consumers may
/// give the scalable historical tail to proof. The environment kill switch
/// disables only the wrapper lane and never reclaims an engine reservation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PostBabWrapperRoute {
    AttackEnabled,
    DisabledByEnvironment,
    DisabledByPreset,
    ProofTailByPreset,
}

impl PostBabWrapperRoute {
    const fn stable_token(self) -> &'static str {
        match self {
            Self::AttackEnabled => "attack_enabled",
            Self::DisabledByEnvironment => "disabled_by_environment",
            Self::DisabledByPreset => "disabled_by_preset",
            Self::ProofTailByPreset => "proof_tail_by_preset",
        }
    }

    fn attack_enabled(self) -> bool {
        matches!(self, Self::AttackEnabled)
    }

    fn proof_owns_historical_tail(self) -> bool {
        matches!(self, Self::ProofTailByPreset)
    }
}

fn postbab_deferred_pgd_consumer_available(
    route: PostBabWrapperRoute,
    margin_row_memory_allowed: bool,
) -> bool {
    route.attack_enabled() && margin_row_memory_allowed
}

fn deferred_outer_pgd_has_priority(
    schedule: Option<ResolvedInitialPgdSchedule>,
    consumer_available: bool,
) -> bool {
    consumer_available && matches!(schedule, Some(ResolvedInitialPgdSchedule::Deferred))
}

/// Reproduce the handler's effective deferred-PGD fraction from the exact
/// validated preset snapshot it will later consume. Reading the raw YAML field
/// is insufficient: `pgd_order: after` moves `max(upfront, post)` into the
/// post-BaB slot during typed preset application.
fn effective_deferred_pgd_fraction(snapshot: Option<&BetaCrownPresetSnapshot>) -> Option<f32> {
    let preset = snapshot?.loaded()?;
    if !matches!(
        resolve_initial_pgd_schedule(preset),
        Ok(Some(ResolvedInitialPgdSchedule::Deferred))
    ) {
        return None;
    }
    let mut config = BetaCrownConfig::default();
    crate::preset::apply_preset(&mut config, preset).ok()?;
    config
        .enable_pgd_attack
        .then_some(config.phase_budget.post_bab_pgd_fraction.clamp(0.0, 0.5))
}

/// Freeze the internal/outer-PGD handoff against the command-level solver
/// clock. `timeout_before_fixed_reserves_secs` has already charged the upfront
/// wrapper attack. The difference to `verifier_timeout_secs` is the exact
/// fixed tail held by margin/post-BaB policy. Subtract that held tail and the
/// effective fractional tail from the already-anchored solver deadline; never
/// create a fresh deadline from the later verifier setup time.
fn frozen_outer_deferred_internal_deadline(
    solver_phase_deadline: Option<std::time::Instant>,
    timeout_before_fixed_reserves_secs: u64,
    verifier_timeout_secs: u64,
    effective_post_bab_fraction: Option<f32>,
    outer_pgd_has_priority: bool,
) -> Option<std::time::Instant> {
    if !outer_pgd_has_priority {
        return None;
    }
    let solver_phase_deadline = solver_phase_deadline?;
    let fraction = effective_post_bab_fraction?;
    let held_fixed_secs = timeout_before_fixed_reserves_secs.saturating_sub(verifier_timeout_secs);
    solver_phase_deadline
        .checked_sub(std::time::Duration::from_secs(held_fixed_secs))?
        .checked_sub(
            std::time::Duration::from_secs(verifier_timeout_secs).mul_f32(fraction.clamp(0.0, 0.5)),
        )
}

fn nonlinear_fallback_may_precede_outer_pgd(deferred_outer_pgd_priority: bool) -> bool {
    !deferred_outer_pgd_priority
}

/// VNN-COMP wrapper policy for the exact-gradient falsifier that runs before
/// the in-process verifier.
///
/// The wrapper used to ignore `attack.pgd_order`, so a preset such as NN4SYS
/// (`skip`) still reloaded a 151 MB model, built ORT state, and spent an attack
/// slice before the preset-disabled verifier attack. `input_bab` likewise
/// promises to suppress the upfront stage. Resolve both consumers from the
/// same immutable preset snapshot while retaining the exact historical
/// environment overrides.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UpfrontWrapperRoute {
    AutoDisjunction,
    /// Preserve automatic multi-clause-disjunction admission and additionally
    /// admit the narrow low-dimensional relational-conjunction shape selected
    /// by a typed preset.
    PresetRelationalConjunction,
    DisabledByEnvironment,
    DisabledByPreset,
    /// The frozen preset is syntactically or semantically invalid. No
    /// environment force may run a verdict-producing wrapper lane ahead of
    /// the retained preset error.
    DisabledByInvalidPreset,
    ForcedByEnvironment,
    /// The typed `attack.upfront_attack: true` category key (#upfront-preset).
    /// Arms the lane like [`Self::ForcedByEnvironment`], but it travels with
    /// the preset, so `ny vnncomp`, `vnncomp_sweep`, and `ny benchmarks run`
    /// all measure the same lane the submission wrapper arms. One deliberate
    /// difference (#ml4acopf-upfront-single): a multi-clause disjunction keeps
    /// its automatic admission and cap under this route, see
    /// [`upfront_attack_admission`].
    ForcedByPreset,
}

/// Source-sensitive master decision frozen in the scored run's LeverSet.
///
/// `Default(Unset)` means the historical schedule/property-derived automatic
/// route. Only an explicit typed or environment false is a kill switch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UpfrontAttackMaster {
    Contextual,
    DisabledByEnvironment,
    ForcedByEnvironment,
    DisabledByPreset,
    ForcedByPreset,
}

/// Every upfront-attack value the wrapper consumes, resolved exactly once.
///
/// The same `LeverSet` that constructs this policy constructs the flight
/// receipt. No method in this policy performs a process-environment lookup.
#[derive(Debug, Clone, Copy, PartialEq)]
struct UpfrontAttackPolicy {
    master: UpfrontAttackMaster,
    wall_cap: std::time::Duration,
    auto_wall_cap: std::time::Duration,
    budget_fraction: f64,
    bnn_wall_cap: std::time::Duration,
    bnn_budget_fraction: f64,
    probe_first: bool,
}

/// Frozen fixed-wall allocation for the outer post-BaB falsifier.
///
/// This is deliberately separate from `PhaseBudgetConfig::post_bab_pgd_fraction`:
/// that fraction schedules the in-process verifier's own tail, while this value
/// shortens the verifier invocation so the wrapper has a deterministic window.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PostBabReservePolicy {
    configured_secs: u64,
}

/// Frozen diversified-restart count for the outer post-BaB falsifier
/// (#postbab-restart-diversity).
///
/// Zero (the declaration default) preserves the historical convergent
/// single-descent stack byte-for-byte; a positive count re-enters the stage-0
/// alternation from deterministically seeded diversified basins after it
/// self-terminates with attack window remaining.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PostBabRestartPolicy {
    configured_restarts: u64,
}

/// Frozen source-sensitive admission for the outer post-BaB falsifier.
///
/// The legacy environment variable is a kill switch, not a general override:
/// exact `0` disables the wrapper, while every other spelling leaves the
/// independent typed-preset decision intact. Keeping both facts here preserves
/// that contract while removing the live environment read from the scored path.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PostBabWrapperPolicy {
    effective_enabled: bool,
    effective_source: ny_levers::Source,
    lower_enabled: bool,
    lower_source: ny_levers::Source,
    disabled_by_environment: bool,
    disabled_by_preset: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UpfrontAttackConsultation {
    ProbeFirst,
    Ordinary,
}

impl UpfrontAttackMaster {
    const fn stable_token(self) -> &'static str {
        match self {
            Self::Contextual => "contextual",
            Self::DisabledByEnvironment => "disabled_by_environment",
            Self::ForcedByEnvironment => "forced_by_environment",
            Self::DisabledByPreset => "disabled_by_preset",
            Self::ForcedByPreset => "forced_by_preset",
        }
    }
}

impl UpfrontAttackConsultation {
    const fn stable_token(self) -> &'static str {
        match self {
            Self::ProbeFirst => "probe_first",
            Self::Ordinary => "ordinary",
        }
    }
}

impl UpfrontAttackPolicy {
    fn from_levers(levers: &ny_levers::LeverSet) -> std::result::Result<Self, String> {
        use ny_levers::decls::vnncomp_entry::{
            BNN_ATTACK_CAP, BNN_ATTACK_FRAC, UPFRONT_ATTACK, UPFRONT_ATTACK_AUTO_CAP,
            UPFRONT_ATTACK_CAP, UPFRONT_ATTACK_FRAC,
        };
        use ny_levers::{LeverValue, Source};

        let master_value = levers.get(&UPFRONT_ATTACK);
        let master = match (levers.source(&UPFRONT_ATTACK), master_value) {
            (Source::Default, LeverValue::Unset) => UpfrontAttackMaster::Contextual,
            (Source::Config, LeverValue::Bool(false)) => UpfrontAttackMaster::DisabledByPreset,
            (Source::Config, LeverValue::Bool(true)) => UpfrontAttackMaster::ForcedByPreset,
            (Source::LegacyEnv, LeverValue::Bool(false)) => {
                UpfrontAttackMaster::DisabledByEnvironment
            }
            (Source::LegacyEnv, LeverValue::Bool(true)) => UpfrontAttackMaster::ForcedByEnvironment,
            // BoolOverride never rejects: malformed/non-Unicode input is
            // recorded in ignored_raw and retains Config/Default as source.
            (source, value) => {
                return Err(format!(
                    "{} has impossible frozen resolution source={source:?} value={value:?}",
                    UPFRONT_ATTACK.name,
                ));
            }
        };

        let integer = |decl: &'static ny_levers::LeverDecl| match levers.get(decl) {
            LeverValue::U64(value) => Ok(value),
            other => Err(format!("{} resolved to non-u64 value {other:?}", decl.name)),
        };
        let fraction = |decl: &'static ny_levers::LeverDecl| match levers.get(decl) {
            LeverValue::F64(value) if value.is_finite() && value > 0.0 && value <= 1.0 => Ok(value),
            other => Err(format!(
                "{} resolved outside 0 < fraction <= 1: {other:?}",
                decl.name
            )),
        };

        Ok(Self {
            master,
            wall_cap: std::time::Duration::from_secs(integer(&UPFRONT_ATTACK_CAP)?),
            auto_wall_cap: std::time::Duration::from_secs(integer(&UPFRONT_ATTACK_AUTO_CAP)?),
            budget_fraction: fraction(&UPFRONT_ATTACK_FRAC)?,
            bnn_wall_cap: std::time::Duration::from_secs(integer(&BNN_ATTACK_CAP)?),
            bnn_budget_fraction: fraction(&BNN_ATTACK_FRAC)?,
            probe_first: levers
                .is_armed(&ny_levers::decls::dark_probes::UPFRONT_ATTACK_PROBE_FIRST),
        })
    }
}

impl PostBabReservePolicy {
    fn from_levers(levers: &ny_levers::LeverSet) -> std::result::Result<Self, String> {
        use ny_levers::decls::vnncomp_entry::POSTBAB_RESERVE_SECS;

        match levers.get(&POSTBAB_RESERVE_SECS) {
            ny_levers::LeverValue::U64(configured_secs) => Ok(Self { configured_secs }),
            other => Err(format!(
                "{} resolved to non-u64 value {other:?}",
                POSTBAB_RESERVE_SECS.name
            )),
        }
    }
}

impl PostBabRestartPolicy {
    fn from_levers(levers: &ny_levers::LeverSet) -> std::result::Result<Self, String> {
        use ny_levers::decls::vnncomp_entry::POSTBAB_RESTARTS;

        match levers.get(&POSTBAB_RESTARTS) {
            ny_levers::LeverValue::U64(configured_restarts) => Ok(Self {
                configured_restarts,
            }),
            other => Err(format!(
                "{} resolved to non-u64 value {other:?}",
                POSTBAB_RESTARTS.name
            )),
        }
    }
}

impl PostBabWrapperPolicy {
    const ENABLED: Self = Self {
        effective_enabled: true,
        effective_source: ny_levers::Source::Default,
        lower_enabled: true,
        lower_source: ny_levers::Source::Default,
        disabled_by_environment: false,
        disabled_by_preset: false,
    };

    fn from_levers(levers: &ny_levers::LeverSet) -> std::result::Result<Self, String> {
        use ny_levers::decls::vnncomp_entry::POSTBAB_ATTACK;
        use ny_levers::{LeverValue, Source};

        let resolved = levers.resolved(&POSTBAB_ATTACK).ok_or_else(|| {
            format!(
                "{} is absent from the frozen scored-run LeverSet",
                POSTBAB_ATTACK.name
            )
        })?;
        let bool_value = |value: &LeverValue| match value {
            LeverValue::Bool(value) => Ok(*value),
            other => Err(format!(
                "{} resolved to non-boolean value {other:?}",
                POSTBAB_ATTACK.name
            )),
        };

        let effective = bool_value(&resolved.value)?;
        let lower = bool_value(&resolved.lower_value)?;
        let disabled_by_environment = resolved.source == Source::LegacyEnv && !effective;
        // BoolKillOverride retains the lower Config layer when exact env `0`
        // is effective. This matters for the historical kill-only contract:
        // env `1` never erased a typed false, and env `0` plus a complete typed
        // opt-out still assigned the tail to proof.
        let disabled_by_preset = (resolved.source == Source::Config && !effective)
            || (resolved.source == Source::LegacyEnv
                && resolved.lower_source == Source::Config
                && !lower);

        Ok(Self {
            effective_enabled: effective,
            effective_source: resolved.source,
            lower_enabled: lower,
            lower_source: resolved.lower_source,
            disabled_by_environment,
            disabled_by_preset,
        })
    }

    fn receipt_details(self, explicit_fraction: Option<f32>, route: PostBabWrapperRoute) -> String {
        let wrapper_routing_fraction = explicit_fraction
            .filter(|fraction| fraction.is_finite())
            .map(|fraction| fraction.clamp(0.0, 0.5));
        let explicit_fraction =
            explicit_fraction.map_or_else(|| "absent".to_string(), |fraction| fraction.to_string());
        let wrapper_routing_fraction = wrapper_routing_fraction
            .map_or_else(|| "absent".to_string(), |fraction| fraction.to_string());
        format!(
            "schema=ny-cli/postbab-wrapper-policy/v1 effective_enabled={} \
             effective_source={} lower_enabled={} lower_source={} \
             explicit_engine_fraction={} wrapper_routing_fraction={} \
             disabled_by_environment={} disabled_by_preset={} route={}",
            u8::from(self.effective_enabled),
            self.effective_source.as_str(),
            u8::from(self.lower_enabled),
            self.lower_source.as_str(),
            explicit_fraction,
            wrapper_routing_fraction,
            u8::from(self.disabled_by_environment),
            u8::from(self.disabled_by_preset),
            route.stable_token(),
        )
    }
}

impl UpfrontWrapperRoute {
    const fn stable_token(self) -> &'static str {
        match self {
            Self::AutoDisjunction => "auto_disjunction",
            Self::PresetRelationalConjunction => "preset_relational_conjunction",
            Self::DisabledByEnvironment => "disabled_by_environment",
            Self::DisabledByPreset => "disabled_by_preset",
            Self::DisabledByInvalidPreset => "disabled_by_invalid_preset",
            Self::ForcedByEnvironment => "forced_by_environment",
            Self::ForcedByPreset => "forced_by_preset",
        }
    }

    fn attack_enabled(self) -> bool {
        matches!(
            self,
            Self::AutoDisjunction
                | Self::PresetRelationalConjunction
                | Self::ForcedByEnvironment
                | Self::ForcedByPreset
        )
    }

    fn forced(self) -> bool {
        matches!(self, Self::ForcedByEnvironment | Self::ForcedByPreset)
    }

    fn preset_relational_conjunction(self) -> bool {
        matches!(self, Self::PresetRelationalConjunction)
    }
}

fn upfront_wrapper_route(
    preset_schedule: Option<ResolvedInitialPgdSchedule>,
    preset_relational_exact_gradient: bool,
    master: UpfrontAttackMaster,
) -> UpfrontWrapperRoute {
    // The master was already layered environment-over-preset-over-default in
    // the entry-time LeverSet. Preserve that precedence without reopening
    // either source here.
    match master {
        UpfrontAttackMaster::DisabledByEnvironment => {
            return UpfrontWrapperRoute::DisabledByEnvironment;
        }
        UpfrontAttackMaster::ForcedByEnvironment => {
            return UpfrontWrapperRoute::ForcedByEnvironment;
        }
        UpfrontAttackMaster::DisabledByPreset => {
            return UpfrontWrapperRoute::DisabledByPreset;
        }
        UpfrontAttackMaster::ForcedByPreset => return UpfrontWrapperRoute::ForcedByPreset,
        UpfrontAttackMaster::Contextual => {}
    }
    if matches!(
        preset_schedule,
        Some(
            ResolvedInitialPgdSchedule::Disabled
                | ResolvedInitialPgdSchedule::InputBab
                // `after`: the attack still runs, just not HERE. Suppressing the upfront
                // wrapper is what frees its slice for branch-and-bound; the post-BaB stage
                // spends it.
                | ResolvedInitialPgdSchedule::Deferred
        )
    ) {
        UpfrontWrapperRoute::DisabledByPreset
    } else if preset_relational_exact_gradient {
        UpfrontWrapperRoute::PresetRelationalConjunction
    } else {
        UpfrontWrapperRoute::AutoDisjunction
    }
}

/// Resolve the upfront wrapper from the already-frozen, semantically validated
/// preset.
///
/// A missing preset preserves the historical automatic disjunction lane.
/// Invalid snapshots suppress wrapper work regardless of environment overrides;
/// [`run_and_translate`] returns their retained error as a sound `unknown`
/// before every wrapper fast path.
fn upfront_wrapper_route_from_snapshot(
    preset_snapshot: Option<&BetaCrownPresetSnapshot>,
    master: UpfrontAttackMaster,
) -> UpfrontWrapperRoute {
    match preset_snapshot {
        None => upfront_wrapper_route(None, false, master),
        Some(BetaCrownPresetSnapshot::Invalid(_)) => UpfrontWrapperRoute::DisabledByInvalidPreset,
        Some(BetaCrownPresetSnapshot::Loaded(preset)) => {
            match resolve_initial_pgd_schedule(preset) {
                Ok(schedule) => upfront_wrapper_route(
                    schedule,
                    preset
                        .attack
                        .vnncomp_upfront_relational_exact_gradient
                        .unwrap_or(false),
                    master,
                ),
                // `BetaCrownPresetSnapshot::load` turns this into `Invalid`.
                // Retain a fail-closed guard for manually constructed snapshots.
                Err(_) => UpfrontWrapperRoute::DisabledByInvalidPreset,
            }
        }
    }
}

/// Resolve the wrapper policy from the typed engine field and the already-
/// frozen wrapper admission policy.
///
/// Wrapper omission/`true` preserves the default-enabled lane even when the
/// engine fraction is zero. Proof-tail ownership requires an explicit wrapper
/// opt-out AND an explicit typed value whose established engine clamp resolves
/// to zero; neither an environment-only kill nor a non-finite fraction can
/// acquire proof time.
fn postbab_wrapper_route(
    explicit_fraction: Option<f32>,
    policy: PostBabWrapperPolicy,
) -> PostBabWrapperRoute {
    let effective_fraction = explicit_fraction
        .filter(|fraction| fraction.is_finite())
        .map(|fraction| fraction.clamp(0.0, 0.5));
    if policy.disabled_by_preset && effective_fraction == Some(0.0) {
        PostBabWrapperRoute::ProofTailByPreset
    } else if policy.disabled_by_environment {
        PostBabWrapperRoute::DisabledByEnvironment
    } else if policy.disabled_by_preset {
        PostBabWrapperRoute::DisabledByPreset
    } else {
        PostBabWrapperRoute::AttackEnabled
    }
}

/// Resolve from the wrapper's immutable preset snapshot. A missing or invalid
/// snapshot preserves the historical route; β-CROWN receives the same invalid
/// snapshot and returns a sound non-verdict without rereading the path.
fn postbab_engine_fraction_from_snapshot(
    preset_snapshot: Option<&BetaCrownPresetSnapshot>,
) -> Option<f32> {
    preset_snapshot
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| preset.bab.phase_budget.post_bab_pgd_fraction)
}

fn postbab_wrapper_route_from_snapshot(
    preset_snapshot: Option<&BetaCrownPresetSnapshot>,
    policy: PostBabWrapperPolicy,
) -> PostBabWrapperRoute {
    postbab_wrapper_route(
        postbab_engine_fraction_from_snapshot(preset_snapshot),
        policy,
    )
}

/// Give the scalable historical flush reserve back to the solver only when the
/// typed preset explicitly gives the post-BaB lane zero budget. SafeNLP's
/// separately guarded one-second route remains authoritative.
fn apply_postbab_wrapper_timeout_policy(
    historical: InternalTimeoutDecision,
    timeout_secs: u64,
    wrapper_route: PostBabWrapperRoute,
) -> InternalTimeoutDecision {
    if historical.route != InternalTimeoutRoute::Historical
        || !wrapper_route.proof_owns_historical_tail()
    {
        return historical;
    }

    let solver_timeout_secs = timeout_secs
        .checked_sub(MIN_RESULTS_FLUSH_RESERVE_SECS)
        .filter(|&timeout| timeout >= 1)
        .unwrap_or(timeout_secs);
    InternalTimeoutDecision {
        solver_timeout_secs,
        effective_flush_reserve_secs: timeout_secs.saturating_sub(solver_timeout_secs),
        historical_solver_timeout_secs: historical.historical_solver_timeout_secs,
        route: InternalTimeoutRoute::PresetProofTail,
    }
}

/// Resolve the typed publication reserve from the wrapper's immutable preset
/// snapshot (#flush-grace).
///
/// A missing or invalid snapshot, an absent `bab.phase_budget` section, or an
/// absent key all yield `None` — the declaration default — which is today's
/// `max(5, budget/20)` behaviour, byte for byte.
fn results_flush_grace_from_snapshot(
    preset_snapshot: Option<&BetaCrownPresetSnapshot>,
) -> Option<u64> {
    preset_snapshot
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| preset.bab.phase_budget.results_flush_grace_secs)
}

/// Replace the historical `max(5, budget/20)` publication grace with the value
/// the category's own preset states (#flush-grace).
///
/// WHAT THIS REPLACES, AND WHY THAT IS THE GENERALISATION. The historical rule
/// reserves `max(5, budget / 20)`: 5 s at every budget up to 100 s, then 5 % of
/// it. On a 20 s row that is a 25 % tax on proof search, and the doc block on
/// [`SCORED_WALL_STOP_RESERVE_SECS`] records what the reserve actually has to
/// cover — 9-18 ms of publication plus the error in the branch-and-bound stop
/// estimate, measured at 0.00-0.19 s across 70 armed runs on the one family
/// that carries a `BabWall`. Substituting only the `5` and keeping the `max`
/// would leave every budget at or above `20 * grace` untouched, i.e. it would
/// change nothing on the long rows where the 5 % tail is largest. So an
/// explicit value is stated absolutely, and it is a claim the family makes
/// about its OWN tail.
///
/// PRECEDENCE. `SafeNlpShortGrace` is untouched: it is a separate dark
/// experiment that also re-plumbs publication onto a single-writer coordinator
/// with its own hard stop, and a typed key must not half-enter that lane. The
/// proof-tail route IS superseded, because both are preset statements and an
/// explicit number is the more specific one.
///
/// THE CLAMP IS THE SAME TOTAL ARITHMETIC THE OTHER TWO ROUTES USE: subtract,
/// require at least one second, otherwise fall back to the whole budget. It
/// cannot produce a zero, negative, or over-budget internal timeout, and it
/// never touches the scored instance deadline, either watchdog tier, or the
/// pre-written sound `unknown`.
fn apply_results_flush_grace_policy(
    decision: InternalTimeoutDecision,
    timeout_secs: u64,
    grace_secs: Option<u64>,
) -> InternalTimeoutDecision {
    let Some(grace_secs) = grace_secs else {
        return decision;
    };
    if decision.route == InternalTimeoutRoute::SafeNlpShortGrace {
        return decision;
    }

    let solver_timeout_secs = timeout_secs
        .checked_sub(grace_secs)
        .filter(|&timeout| timeout >= 1)
        .unwrap_or(timeout_secs);
    InternalTimeoutDecision {
        solver_timeout_secs,
        effective_flush_reserve_secs: timeout_secs.saturating_sub(solver_timeout_secs),
        historical_solver_timeout_secs: decision.historical_solver_timeout_secs,
        route: InternalTimeoutRoute::PresetFlushGrace,
    }
}

/// UNCONDITIONAL publication-reserve receipt (#flush-grace).
///
/// `eprintln!`, not `println!`, deliberately: the sweep nulls the child's
/// stdout and keeps only a bounded STDERR tail, which is the family
/// `[budget]`/`[stop]` already belong to (see `vnncomp_sweep`'s stop-evidence
/// filter). A stdout line would be discarded by exactly the tool most likely
/// to be reading for it.
///
/// Emitted on EVERY scored run, including the default route, so that an ABSENT
/// line means the binary predates this lever and any null measured through it
/// is VOID rather than negative.
fn flush_grace_receipt_line(timeout_secs: u64, decision: InternalTimeoutDecision) -> String {
    let source = match decision.route {
        InternalTimeoutRoute::PresetFlushGrace => "preset",
        InternalTimeoutRoute::PresetProofTail => "preset-proof-tail",
        InternalTimeoutRoute::SafeNlpShortGrace => "env-safenlp-short-grace",
        InternalTimeoutRoute::Historical => "default",
    };
    format!(
        "[flush-grace] budget_s={timeout_secs} grace_s={} source={source} \
internal_timeout_s={}",
        decision.effective_flush_reserve_secs, decision.solver_timeout_secs,
    )
}

fn emit_flush_grace_receipt(timeout_secs: u64, decision: InternalTimeoutDecision) {
    eprintln!("{}", flush_grace_receipt_line(timeout_secs, decision));
}

/// Absolute verifier deadline for routes that consume nearly all of the scored
/// budget. The proof-tail route is anchored before model/runtime setup so setup
/// time cannot slide a duration-based timeout past the publication margin.
fn beta_phase_deadline(
    decision: InternalTimeoutDecision,
    instance_deadline: std::time::Instant,
) -> Option<std::time::Instant> {
    match decision.route {
        InternalTimeoutRoute::SafeNlpShortGrace => Some(instance_deadline),
        // #flush-grace shares the proof-tail anchoring for the reason stated
        // on this function: a duration-based grant silently restarts the clock
        // at lane construction, so setup seconds are charged twice in reality
        // and once in the accounting. A SMALL grace makes that error decisive —
        // a 1 s reserve on a 20 s budget is entirely consumed by a 1 s model
        // load — so the explicit-grace route must be absolute or it is unsound
        // against its own budget.
        InternalTimeoutRoute::PresetProofTail | InternalTimeoutRoute::PresetFlushGrace => Some(
            instance_deadline
                .checked_sub(std::time::Duration::from_secs(
                    decision.effective_flush_reserve_secs,
                ))
                .unwrap_or(instance_deadline),
        ),
        InternalTimeoutRoute::Historical => None,
    }
}

/// Absolute end of the internal solver grant, frozen from the scored instance
/// clock before preset planning, model loading, wrapper attacks, or verifier
/// setup. This also caps the historical verifier route, whose configured
/// duration must not restart the original grant after model/setup work.
fn solver_phase_deadline(
    decision: InternalTimeoutDecision,
    instance_deadline: std::time::Instant,
) -> std::time::Instant {
    instance_deadline
        .checked_sub(std::time::Duration::from_secs(
            decision.effective_flush_reserve_secs,
        ))
        .unwrap_or(instance_deadline)
}

/// Preserve an explicit route's authority; otherwise charge the historical
/// verifier's complete setup against its original absolute solver grant.
/// This is separate from the proof-tail scheduling flag: giving Historical
/// an authority must not suppress its post-verifier or concurrent consumers.
fn beta_solver_authority_deadline(
    route_deadline: Option<std::time::Instant>,
    original_solver_deadline: Option<std::time::Instant>,
) -> Option<std::time::Instant> {
    route_deadline.or(original_solver_deadline)
}

/// Normalize only the harmless spelling differences accepted for the narrow
/// SafeNLP timeout experiment. Paths, suffixes, and broader aliases stay out of
/// scope so the dark lever cannot accidentally affect another category.
///
/// #name-blind-routing: this is the LAST category-name decision on the scored
/// path, and it is env-dark (`NY_SAFENLP_SHORT_GRACE`, never exported by
/// `run_instance.sh`). It was deliberately NOT deleted with the other three
/// env-dark name-keyed routes: under the workspace's `-D warnings` gate,
/// removing this selection makes the whole parent-anchored short-grace
/// watchdog/publication protocol dead code, and that protocol shares its
/// deadline/result-policy/control types and the `__vnncomp-watchdog` argv
/// dispatcher with the historical external watchdog that runs on EVERY scored
/// row. Deleting it is a watchdog refactor that must be compiled, unit-tested
/// and timing-measured on its own, not a blind edit. The category-name ratchet
/// (`crates/ny-levers/tests/category_name_ratchet.rs`) counts this literal, so
/// the follow-up that removes it must lower that baseline.
fn is_safenlp_2024_category(category: &str) -> bool {
    category.trim().to_ascii_lowercase().replace('-', "_") == "safenlp_2024"
}

/// Exact-string gate for the dark SafeNLP timeout experiment.
///
/// `var_os` plus `OsStr` equality makes non-Unicode values fail closed. In
/// particular, truthy spellings, whitespace, and malformed values do not arm
/// the experiment.
fn safenlp_short_grace_gate_enabled(raw: Option<&OsStr>) -> bool {
    raw == Some(OsStr::new("1"))
}

/// Select the competition verifier's internal timeout.
///
/// The historical timeout function above remains the sole path unless every
/// narrow experiment gate matches: exact environment value `1`, normalized
/// category `safenlp_2024`, and a scored budget of at most 30 seconds. The
/// outer instance deadline, both watchdogs, and the pre-written sound
/// `unknown` remain unchanged and authoritative.
fn internal_timeout_decision(
    category: &str,
    timeout_secs: u64,
    gate_raw: Option<&OsStr>,
) -> InternalTimeoutDecision {
    let historical_solver_timeout_secs = internal_timeout_secs(timeout_secs);
    if !safenlp_short_grace_gate_enabled(gate_raw)
        || !is_safenlp_2024_category(category)
        || timeout_secs > SAFENLP_SHORT_GRACE_MAX_BUDGET_SECS
    {
        return InternalTimeoutDecision {
            solver_timeout_secs: historical_solver_timeout_secs,
            effective_flush_reserve_secs: timeout_secs
                .saturating_sub(historical_solver_timeout_secs),
            historical_solver_timeout_secs,
            route: InternalTimeoutRoute::Historical,
        };
    }

    // Keep the established positive-timeout fallback for the one-second edge:
    // a one-second scored budget cannot reserve a full second and still launch
    // the solver. This is unreachable through normal 2025 SafeNLP instances,
    // but keeping it explicit makes the pure boundary behavior total.
    let solver_timeout_secs = timeout_secs
        .checked_sub(SAFENLP_SHORT_GRACE_SECS)
        .filter(|&t| t >= 1)
        .unwrap_or(timeout_secs);
    InternalTimeoutDecision {
        solver_timeout_secs,
        effective_flush_reserve_secs: timeout_secs.saturating_sub(solver_timeout_secs),
        historical_solver_timeout_secs,
        route: InternalTimeoutRoute::SafeNlpShortGrace,
    }
}

#[cfg(any(not(unix), test))]
fn safenlp_short_hard_stop_deadline(instance_deadline: std::time::Instant) -> std::time::Instant {
    instance_deadline
        .checked_sub(SAFENLP_SHORT_HARD_STOP_MARGIN)
        .unwrap_or_else(std::time::Instant::now)
}

fn safenlp_short_publication_deadline(instance_deadline: std::time::Instant) -> std::time::Instant {
    instance_deadline
        .checked_sub(SAFENLP_SHORT_PUBLICATION_MARGIN)
        .unwrap_or_else(std::time::Instant::now)
}

fn safenlp_short_prepare_ack_deadline(
    hard_stop_deadline: CanonicalMonotonicInstant,
) -> CanonicalMonotonicInstant {
    hard_stop_deadline
        .checked_sub(SAFENLP_SHORT_FINALIZATION_WINDOW)
        .unwrap_or(CanonicalMonotonicInstant::EXPIRED)
}

/// Lowercase the category and strip a trailing `_20NN` year suffix, yielding the two
/// preset-file basename candidates the shell wrapper searched: `[full_lower, base]`.
///
/// e.g. `Acasxu_2023` -> `["acasxu_2023", "acasxu"]`, `cersyve` -> `["cersyve"]`
/// (no duplicate when there is no year suffix).
fn preset_basename_candidates(category: &str) -> Vec<String> {
    let lower = category.to_ascii_lowercase();
    let base = strip_year_suffix(&lower).to_string();
    if base == lower {
        vec![lower]
    } else {
        vec![lower, base]
    }
}

/// Strip a trailing `_20NN` (four-digit, `20xx`) suffix from a category name, matching
/// the shell `sed 's/_20[0-9][0-9]$//'`.
fn strip_year_suffix(category_lower: &str) -> &str {
    // A `_20NN` suffix is exactly 5 chars (`_`, `2`, `0`, digit, digit).
    let bytes = category_lower.as_bytes();
    if bytes.len() >= 5 {
        let tail = &category_lower[bytes.len() - 5..];
        let tb = tail.as_bytes();
        if tb[0] == b'_'
            && tb[1] == b'2'
            && tb[2] == b'0'
            && tb[3].is_ascii_digit()
            && tb[4].is_ascii_digit()
        {
            return &category_lower[..bytes.len() - 5];
        }
    }
    category_lower
}

fn is_vnncomp_year_dir_name(name: &str) -> bool {
    name.strip_prefix("vnncomp")
        .is_some_and(|suffix| suffix.len() == 2 && suffix.bytes().all(|byte| byte.is_ascii_digit()))
}

/// List the `vnncomp*` preset directories at or under `configs_dir`, newest year first.
///
/// Directory names are sorted in DESCENDING lexical order (matching the shell
/// `sort -r`), so `vnncomp25` precedes `vnncomp24`. This makes the newest year's
/// preset win when the same category exists in multiple year directories. A
/// caller that already selected one exact year may pass that `vnncompYY`
/// directory itself; in that case no sibling year is searched.
fn vnncomp_dirs_newest_first(configs_dir: &Path) -> Vec<PathBuf> {
    if configs_dir.is_dir()
        && configs_dir
            .file_name()
            .and_then(|name| name.to_str())
            .is_some_and(is_vnncomp_year_dir_name)
    {
        return vec![configs_dir.to_path_buf()];
    }
    let Ok(entries) = fs::read_dir(configs_dir) else {
        return Vec::new();
    };
    let mut dirs: Vec<PathBuf> = entries
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.path())
        .filter(|path| {
            path.is_dir()
                && path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| name.starts_with("vnncomp"))
        })
        .collect();
    // Descending by directory name => newest year directory first.
    dirs.sort_by(|a, b| b.file_name().cmp(&a.file_name()));
    dirs
}

/// Select the one configuration directory belonging to an explicit benchmark year.
///
/// Whole-corpus sweeps know which VNN-COMP corpus they are measuring. They must
/// therefore never use [`resolve_preset_path`]'s native, yearless
/// "newest-directory wins" policy: once `vnncomp26` exists, that policy makes a
/// 2025 `safenlp_2024` sweep silently load the materially different 2026 preset.
/// This helper accepts either the parent `configs/` directory or the already
/// scoped `configs/vnncompYY` directory and returns only the exact requested
/// year. A differently scoped directory or a missing year fails closed.
pub(crate) fn benchmark_configs_dir(configs_dir: &Path, year: u32) -> Option<PathBuf> {
    let expected = format!("vnncomp{:02}", year % 100);
    let basename = configs_dir.file_name().and_then(|name| name.to_str());
    let selected = match basename {
        Some(name) if is_vnncomp_year_dir_name(name) => {
            if name != expected {
                return None;
            }
            configs_dir.to_path_buf()
        }
        _ => configs_dir.join(expected),
    };
    selected.is_dir().then_some(selected)
}

/// Return well-formed `vnncompYY` directories newest-first, capped at `year`.
///
/// #sweep-preset-parity: retain fallback to older presets while excluding
/// newer-year presets. For the newest corpus this matches the scored
/// [`resolve_preset_path`] search.
pub(crate) fn benchmark_preset_search_dirs(configs_dir: &Path, year: u32) -> Vec<PathBuf> {
    let expected = format!("vnncomp{:02}", year % 100);
    vnncomp_dirs_newest_first(configs_dir)
        .into_iter()
        .filter(|dir| {
            dir.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| is_vnncomp_year_dir_name(name) && name <= expected.as_str())
        })
        .collect()
}

/// Resolve the preset YAML a corpus sweep of `year` must load for `category`.
///
/// Same per-directory candidate order as [`resolve_preset_path`] (full
/// category-with-year name, then the year-stripped base name), over the
/// year-capped directory list. `None` means no preset exists at or before the
/// requested year, and the row genuinely runs on auto defaults.
pub(crate) fn sweep_preset_path(configs_dir: &Path, year: u32, category: &str) -> Option<PathBuf> {
    let candidates = preset_basename_candidates(category);
    for year_dir in benchmark_preset_search_dirs(configs_dir, year) {
        for candidate in &candidates {
            let preset = year_dir.join(format!("{candidate}.yaml"));
            if preset.is_file() {
                return Some(preset);
            }
        }
    }
    None
}

/// The `--configs-dir` a sweep must hand the child that measures `category`.
///
/// The child re-derives its own preset with [`resolve_preset_path`]; handing it
/// the already-scoped directory that actually holds the resolved yaml makes its
/// yearless search terminate on exactly the file the sweep resolved, without
/// giving the child any new resolution policy of its own.
pub(crate) fn sweep_preset_dir(configs_dir: &Path, year: u32, category: &str) -> Option<PathBuf> {
    sweep_preset_path(configs_dir, year, category)
        .and_then(|preset| preset.parent().map(Path::to_path_buf))
}

/// Resolve the preset YAML for a category by searching `configs_dir/vnncomp*/`.
///
/// For each `vnncomp*` directory (newest first), the full category-with-year name is
/// tried before the year-stripped base name. The first existing file wins. Returns
/// `None` when no preset exists for the category (epsilon/auto defaults are then used).
pub(crate) fn resolve_preset_path(configs_dir: &Path, category: &str) -> Option<PathBuf> {
    let candidates = preset_basename_candidates(category);
    for year_dir in vnncomp_dirs_newest_first(configs_dir) {
        for candidate in &candidates {
            let preset = year_dir.join(format!("{candidate}.yaml"));
            if preset.is_file() {
                return Some(preset);
            }
        }
    }
    None
}

/// Record the durable category YAML separately from the effective preset.
///
/// [`crate::plan_resolver`] may materialize adaptive settings into a temporary
/// effective YAML. The existing `preset` flight event correctly names that file,
/// but it is deleted when the child exits and therefore cannot prove which
/// category preset a banked row started from. `preset_base` is the durable input
/// identity used by sweep/search attribution; the effective event remains intact.
fn note_base_preset(configs_dir: Option<&Path>, preset: Option<&Path>, category: &str) {
    match preset {
        Some(path) => crate::flight::note(
            "preset_base",
            crate::flight::FlightStatus::Ran,
            Some(path.display().to_string()),
        ),
        None => crate::flight::note(
            "preset_base",
            crate::flight::FlightStatus::Skipped,
            Some(match configs_dir {
                Some(dir) => format!(
                    "no base preset for category '{category}' under {}; AUTO DEFAULTS",
                    dir.display()
                ),
                None => "no configs dir found; AUTO DEFAULTS".to_string(),
            }),
        ),
    }
}

/// Auto-derive the `configs/` directory by walking up from the given start paths.
///
/// Tries, in order: each provided start path's ancestors for a child `configs/`
/// directory (so a binary at `<repo>/target/release/ny` and an ONNX anywhere under
/// `<repo>` both resolve to `<repo>/configs`). Returns the first existing directory.
pub(crate) fn auto_derive_configs_dir(starts: &[PathBuf]) -> Option<PathBuf> {
    for start in starts {
        let mut cursor: Option<&Path> = Some(start.as_path());
        while let Some(dir) = cursor {
            let candidate = dir.join("configs");
            if candidate.is_dir() {
                return Some(candidate);
            }
            cursor = dir.parent();
        }
    }
    None
}

/// Hidden `argv[1]` for the out-of-process vnncomp watchdog helper (see
/// `handle_vnncomp_command`). Intercepted in `main.rs` before clap parsing and
/// logging setup, like `__shape-infer`.
pub(crate) const EXTERNAL_WATCHDOG_SUBCOMMAND: &str = "__vnncomp-watchdog";

// ── The external-watchdog subsystem is Unix-only ────────────────────────────
//
// Everything that drives it — `spawn_external_watchdog`, the writer/reader
// loops, `hard_kill_parent` — is `#[cfg(unix)]`, because it is built on fork
// semantics, process groups and signals. The scored platform is Linux.
//
// The items those Unix paths CONSUME (the protocol bytes, the deadline types,
// the policy enums) are deliberately NOT `#[cfg(unix)]`-gated, so on Windows
// they are compiled but unreachable, which is exactly `dead_code`. Each such
// item therefore carries
//
//     #[cfg_attr(not(unix), allow(dead_code, reason = "..."))]
//
// rather than a `#[cfg(unix)]` gate. The distinction matters: an `allow` keeps
// the item COMPILED AND TYPE-CHECKED on every platform, whereas a gate would
// remove it from the Windows build entirely and let it rot unnoticed — which
// is precisely how `ny-onnx`'s Windows arm came to name two unstable APIs and
// stop building at all. Silence the warning; do not hide the code.

/// Extra grace the OUT-OF-PROCESS watchdog waits past the in-process watchdog
/// (`timeout + WATCHDOG_GRACE_SECS + this`) before declaring the verifier
/// process wedged. Healthy overruns always exit through the in-process path
/// first; the helper only ever fires on a process that stopped scheduling.
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
const EXTERNAL_WATCHDOG_EXTRA_GRACE_SECS: u64 = 10;

/// Extra grace the in-process watchdog waits past the scored budget before
/// replacing the placeholder result and requesting a process-wide hard stop.
const WATCHDOG_GRACE_SECS: u64 = 5;

/// A byte on the external watchdog's stdin asks it to fire immediately. EOF
/// still means the parent exited normally and the helper should retire.
const EXTERNAL_WATCHDOG_FIRE_REQUEST: &[u8] = b"F";
/// Fire immediately, but leave RESULTS_FILE alone: the parent's in-process
/// watchdog found a verdict this instance had already published BEFORE its own
/// deadline, so the only thing left to enforce is the hard stop
/// (#watchdog-verdict-overwrite). Distinct from `F` because an ordinary
/// immediate fire must still seal a verdict that raced in after the deadline.
const EXTERNAL_WATCHDOG_PRESERVE_FIRE_REQUEST: &[u8] = b"K";
/// A byte tells the short helper that the coordinator completed its sole
/// rename. It remains only a request until the helper consumes it pre-cutoff
/// and returns [`EXTERNAL_WATCHDOG_PUBLICATION_ACK`].
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
const EXTERNAL_WATCHDOG_PUBLICATION_COMMIT: &[u8] = b"C";
/// After accepting the child's prepare ACK, the parent writes this byte into
/// the same ordered control pipe. Only a helper receipt timestamp strictly
/// before the shared canonical H transitions Prepared → Finalized.
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
const EXTERNAL_WATCHDOG_PUBLICATION_FINALIZE: &[u8] = b"P";
/// The short helper writes this byte back only after consuming `C` before its
/// anchored cutoff. A non-text value avoids mistaking any incidental stdout
/// text for a protocol acknowledgement.
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
const EXTERNAL_WATCHDOG_PUBLICATION_ACK: u8 = 0x06;
const EXTERNAL_WATCHDOG_PARENT_ANCHORED_PROTOCOL: &str = "parent-anchored-monotonic-v2";

fn publish_result_atomically(
    results_file: &Path,
    rendered: &str,
    tmp_extension: &str,
) -> std::io::Result<()> {
    let tmp = results_file.with_extension(tmp_extension);
    fs::write(&tmp, rendered)?;
    fs::rename(tmp, results_file)
}

/// Process-local record that a DECIDED verdict reached RESULTS_FILE.
///
/// #watchdog-verdict-overwrite. The deadline watchdogs exist to replace the
/// competition-safety placeholder (`unknown`) when the verifier overruns its
/// budget. They must never replace a verdict the verifier already committed.
/// MEASURED loss: a `sat` was published at 1.7 s, the process then wedged in
/// its exit handlers for the rest of the 350 s budget, and the in-process
/// watchdog overwrote its own already-written result file with `timeout` — a
/// scored point silently converted to a zero, with the log still reading
/// `Result: sat`. That is a correctness-of-REPORTING defect independent of any
/// backend: ANY hang after publication converts a decided row into a lost one.
static DECIDED_VERDICT_PUBLISHED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// `true` for the verdicts the verifier only writes when it actually decided
/// the instance. `unknown` is deliberately excluded: it is also the
/// competition-safety pre-write, so the watchdogs cannot tell a placeholder
/// from a final `unknown` and must keep their historical freedom to replace it
/// (both score zero either way). `timeout` is likewise replaceable.
fn is_decided_verdict_token(token: &str) -> bool {
    matches!(token, "sat" | "unsat" | "error")
}

/// Record a successful RESULTS_FILE publication so the in-process watchdog can
/// refuse to overwrite it (#watchdog-verdict-overwrite).
fn note_published_verdict(result: &VnncompResult) {
    if is_decided_verdict_token(result.token()) {
        DECIDED_VERDICT_PUBLISHED.store(true, std::sync::atomic::Ordering::SeqCst);
    }
}

/// Outcome of the in-process watchdog's timeout commit.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TimeoutCommit {
    /// The placeholder (or an earlier `timeout`) was replaced with `timeout`.
    Committed,
    /// This instance had already published a decided verdict BEFORE the
    /// watchdog's deadline; the watchdog left it alone.
    DeclinedDecidedVerdict,
}

/// The in-process watchdog's timeout commit (#watchdog-verdict-overwrite).
///
/// Enforcing a deadline means replacing the competition-safety PLACEHOLDER.
/// A verdict this instance itself published before the watchdog woke is not a
/// placeholder — it is the answer the row earned — so it is preserved and only
/// the hard stop still happens.
///
/// The decision reads the in-process publication flag and NOTHING ELSE. It
/// deliberately does not sniff the results file: sweeps reuse results paths, so
/// a decided token on disk can be a STALE verdict from a previous run that this
/// instance wedged before overwriting with its placeholder, and preserving that
/// would report another instance's answer.
///
/// Deadline integrity is unaffected. The flag is set only by a publication this
/// process completed, and this function is only consulted at the moment the
/// watchdog fires; a verdict that arrives AFTER the deadline is still sealed as
/// `timeout` by the out-of-process helper (see `ExternalWatchdogControl`).
fn commit_timeout_unless_verdict_published(
    results_file: &Path,
    tmp_extension: &str,
) -> std::io::Result<TimeoutCommit> {
    commit_timeout_unless_verdict_published_with(
        DECIDED_VERDICT_PUBLISHED.load(std::sync::atomic::Ordering::SeqCst),
        results_file,
        tmp_extension,
    )
}

/// Seam for [`commit_timeout_unless_verdict_published`]: the process-global
/// publication flag is passed in so the rule is testable without a global whose
/// value depends on which other test published first.
fn commit_timeout_unless_verdict_published_with(
    published_in_process: bool,
    results_file: &Path,
    tmp_extension: &str,
) -> std::io::Result<TimeoutCommit> {
    if published_in_process {
        return Ok(TimeoutCommit::DeclinedDecidedVerdict);
    }
    commit_timeout_result_checked(results_file, tmp_extension).map(|()| TimeoutCommit::Committed)
}

/// End a COMPLETED scored `ny vnncomp` instance without running libc exit
/// handlers or ELF fini sections.
///
/// #attack-steering-segv — MEASURED root cause (12 of 12 captured faults, gdb,
/// same signature): the main thread reaches `exit` → `__run_exit_handlers` →
/// `_dl_fini` → `_dl_call_fini`, which runs libGLX_nvidia's / libnvidia-glcore's
/// destructors, WHILE a detached verifier thread is still inside that same
/// driver stack. On this host that thread is `ny-attack-arming` inside
/// `WgpuDevice::new` (`create_compute_pipeline`, or `vkDestroyDevice` while
/// dropping a partially built device); it then faults on the globals fini just
/// freed (`__pthread_rwlock_wrlock_full64 (rwlock=0x8)`), or the main thread
/// itself aborts inside fini's own `free` (`malloc_consolidate(): invalid chunk
/// size`). Fast rows are the exposed class because a ~0.7 s instance publishes
/// its verdict while ~360 ms of driver construction is still in flight.
///
/// The class is NOT specific to WGPU: `hard_stop_from_in_process_watchdog`
/// already documents the same fault hitting the r7 cGAN scorecard with a
/// detached AY worker and the CUDA replay live at `exit(0)`. ORT's thread pools
/// are in the same position. Joining every such thread is neither possible (a
/// wedged driver never returns) nor desirable (it is pure latency on a scored
/// budget).
///
/// So the scored path abandons them the only way that is race-free by
/// construction: the verdict and the flight sidecar are already durable, stdout
/// and stderr are flushed here, and `_exit(2)` ends the process with status 0
/// through a single syscall — no atexit handler, no ELF fini, no destructor,
/// nothing for a live thread to race. The kernel reclaims the address space,
/// the GPU contexts, and every thread at once. This also removes the observed
/// HANG: the exiting thread can no longer deadlock against a driver lock held
/// by a thread that is still initializing.
///
/// RE-MEASURED on the exposed row (cctsdb patch-1 /
/// spec_onnx_patch-1_idx_00099_1, 350 s budget, serial, WGPU route):
///
/// * before — 3 abnormal exits in 40 runs (2x SIGSEGV, 1x SIGABRT
///   `free(): invalid size`), every one of them AFTER `Result: sat`;
/// * after  — 0 abnormal exits in 100 runs, 100 `sat`, and the mean instance
///   is 0.72 s rather than 0.88 s because driver fini no longer runs.
#[allow(unsafe_code)]
pub(crate) fn exit_scored_instance_without_teardown() -> ! {
    use std::io::Write;
    // #mr-census: a margin-row lane still running here (the detached
    // concurrent worker after its final join grace expired) never reaches its
    // own census `Drop`, so print its snapshot now. Silent when no lane is live.
    if let Some(line) =
        ny_propagate::margin_row::census::snapshot_if_live("process_exit_with_live_lane")
    {
        eprintln!("{line}");
        // ...and the per-mechanism stop receipts (`[root-eval-reuse]`,
        // `[narrow-r]`, `[mr-errlane] done`), which the lane's own `Drop`
        // would have printed: without them every timeout row lacks them.
        for extra in ny_propagate::margin_row::census::stop_lines() {
            eprintln!("{extra}");
        }
    }
    // Rust's stdout is line-buffered, so `Result:`/`Loading preset:` are
    // already on their way out; flush anyway so a redirected (block-buffered)
    // stdout is complete before the process disappears. stderr is unbuffered.
    let _ = std::io::stdout().flush();
    let _ = std::io::stderr().flush();
    #[cfg(unix)]
    {
        // SAFETY: `_exit` is async-signal-safe, touches no Rust state, and
        // never returns. Status 0 preserves the historical exit code of a
        // completed instance (a harness that reads a signal/137 would treat
        // the row as killed rather than decided).
        unsafe { libc::_exit(0) }
    }
    #[cfg(not(unix))]
    {
        std::process::exit(0)
    }
}

// --------------------------------------------------------------------------
//  #twinwall-early-exit — publish the concurrent lane's UNSAT the moment it
//  exists, instead of running the internal verifier's clock out on a row that
//  is already proved.
// --------------------------------------------------------------------------

/// THE DEFECT. `spawn_concurrent_lane` starts the margin-row lane at instance
/// start and the internal alpha/beta verifier then blocks the main thread for
/// the whole remaining budget. The lane's verdict is not consulted until the
/// verifier RETURNS, so a proof that lands early is simply parked in the
/// channel. MEASURED on cifar100_2024 `resnet_medium prop_idx_7704_sidx_3701`
/// at the scored 100 s budget: `margin-row BaB (concurrent): UNSAT in 10.4s`,
/// process wall 89.7 s — ~79 s spent on a row that was already certified. The
/// same shape appears on every lane-proved row (`idx_5410`: UNSAT at 59.0 s,
/// publication at ~100 s).
///
/// THE FIX. The lane thread publishes RESULTS_FILE itself and ends the process
/// through the same `_exit(0)` the scored path already uses on completion
/// (`exit_scored_instance_without_teardown`). Nothing is computed differently;
/// the only change is WHEN the identical verdict reaches disk.
///
/// WHY THIS CANNOT CHANGE A VERDICT.
/// * The lane is fail-closed: `run_margin_row_lane` returns `Unsat` or
///   `Unknown`, never `Sat`, so the early path can only publish `unsat`.
/// * Nothing downstream refines a lane `unsat`. Both existing consumers
///   (`ConcurrentLaneTake::Verdict` at the post-BaB grace and at the final
///   join) `return res` verbatim — no gate, no re-check, no normalization
///   beyond `normalize_vnnlib2_sat_result`, which only rewrites `Sat`.
/// * The attack lanes can only ADD `sat`; they never turn an `unsat` into
///   anything else, and they are not consulted on a row the lane has proved.
/// * THIS BULLET WAS THE DEFECT, and it is corrected here rather than deleted,
///   because the false justification is what let the race survive review. It
///   used to read: "the one ordering difference is that a verifier `sat`
///   arriving LATER than the lane's proof no longer wins the race. Those two
///   verdicts are contradictory: on a sound pair the case is empty, and the
///   moat rows (three banked `sat`) are the standing check that it stays
///   empty." Both sentences are true and NEITHER supports the conclusion. A
///   contradiction means one of the two lanes is unsound, which is exactly the
///   case in which the protocol has to choose — and "whichever thread finished
///   first" is not a choice, it is the absence of one. The `sat` at stake is
///   not the verifier's raw claim either: by the time it exists ONNX Runtime
///   has re-executed the model and reproduced the violation, so the race was
///   between a CONSTRUCTIVE, organizer-checkable witness and a bound-based
///   claim. Losing it publishes a wrong verdict (-150) on a row this process
///   had already solved correctly. #sat-precedence now gives the constructive
///   witness absolute priority; see [`SatPrecedence`].
///
/// Armed target = the scored RESULTS_FILE, published only on the ordinary
/// (non-short-grace) route. Absent target ⇒ the lane falls back to today's
/// channel handoff exactly as before.
static LANE_EARLY_PUBLISH_TARGET: std::sync::RwLock<Option<PathBuf>> = std::sync::RwLock::new(None);

/// Exclusive terminal-publication claim shared by the main thread and the
/// lane thread. Whoever claims it writes RESULTS_FILE; the loser must not.
/// Without this, a verifier verdict returning in the same microsecond as the
/// lane's proof could interleave two writes and leave the file disagreeing
/// with the `Result:` line in the log.
static TERMINAL_PUBLICATION_CLAIMED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Arm the lane-side early publication for this instance's RESULTS_FILE.
fn arm_lane_early_publish(results_file: &Path) {
    if let Ok(mut slot) = LANE_EARLY_PUBLISH_TARGET.write() {
        *slot = Some(results_file.to_path_buf());
    }
}

/// Take the single terminal-publication right. `true` = the caller owns it.
fn claim_terminal_publication() -> bool {
    claim_terminal_publication_in(&TERMINAL_PUBLICATION_CLAIMED)
}

/// Seam for [`claim_terminal_publication`]: the flag is passed in so the
/// exclusion rule is testable against a LOCAL atomic, without a process global
/// whose value depends on which other test published first. Mirrors the shape
/// already used by `commit_timeout_unless_verdict_published_with`.
fn claim_terminal_publication_in(flag: &std::sync::atomic::AtomicBool) -> bool {
    !flag.swap(true, std::sync::atomic::Ordering::SeqCst)
}

/// Give the claim back after a FAILED write, so the other writer can still
/// publish (#twinwall-early-exit). Called from [`publish_lane_unsat_in`], which
/// is the only writer that can take the claim and then fail to use it.
///
/// Without this the protocol has a hole: the lane claims, its write fails, and
/// the main thread — which must respect the claim — then declines too, so
/// RESULTS_FILE keeps the competition-safety `unknown` placeholder instead of
/// the verdict the run actually reached. Both score zero, so this is not a
/// soundness bug, but it silently downgrades a `timeout` to an `unknown` and
/// there is no reason to accept that. Releasing is safe precisely because it
/// only ever happens on a path where NOTHING was written.
fn release_terminal_publication_in(flag: &std::sync::atomic::AtomicBool) {
    flag.store(false, std::sync::atomic::Ordering::SeqCst);
}

// --------------------------------------------------------------------------
//  #sat-precedence — a CONFIRMED counterexample outranks every `unsat`
// --------------------------------------------------------------------------

/// THE DEFECT. `#twinwall-early-exit` gave the two publishers a mutual-EXCLUSION
/// protocol and nothing else, so the winner was decided purely by ARRIVAL ORDER.
/// The margin-row lane runs on its own thread for the whole instance, while the
/// main thread does not claim publication until `run_and_translate` has
/// returned — long after the trusted-oracle gate accepted a counterexample. A
/// row whose counterexample ONNX Runtime had ALREADY reconfirmed could therefore
/// be published as `unsat` simply because the lane finished first: a wrong
/// verdict (-150) on a row this process had already solved correctly.
///
/// The claim in the old rationale that made this look acceptable —
/// "those two verdicts are contradictory: on a sound pair the case is empty" —
/// is true and IRRELEVANT. Exactly when the case is non-empty, one of the two
/// lanes is unsound, and the protocol has to say which one we publish. Arrival
/// order is not an answer.
///
/// THE PRECEDENCE. The two claims are not symmetric:
///
/// * a confirmed `sat` is CONSTRUCTIVE — a concrete input, re-executed through
///   the reference runtime, at which the property is violated. The organizer can
///   check it without trusting any bound of ours;
/// * an `unsat` is a BOUND-based claim, only as good as every certificate that
///   fed it. One under-charged certificate anywhere makes it false.
///
/// So when they disagree the constructive witness wins, whichever thread
/// finished first.
///
/// HOW THE RACE IS CLOSED RATHER THAN NARROWED. [`publish_lane_unsat_in`]
/// performs the precedence read, the terminal-publication claim AND the
/// RESULTS_FILE write inside ONE critical section of this mutex, and both
/// [`note_confirmed_sat_in`] and [`SatAdjudicationGuard`] take the same mutex.
/// No confirmation can slip between the lane's check and its write. The
/// `adjudicating` counter then extends the exclusion over the whole
/// trusted-oracle gate — the interval that CONTAINS the instant a counterexample
/// becomes confirmed — so a lane proof landing while a candidate is under
/// adjudication defers instead of publishing.
///
/// COST OF DEFERRING: no soundness cost and no verdict cost. A declined early
/// exit hands the lane's `Unsat` to the channel exactly as before, and the main
/// thread still publishes it at the post-BaB or final join if the adjudication
/// ends in a downgrade. Only the early-exit LATENCY saving is lost, and only on
/// a row where a candidate counterexample and a certified proof were in flight
/// at the same instant.
#[derive(Debug, Default)]
struct SatPrecedence {
    /// An ONNX-Runtime-reconfirmed counterexample exists for this instance.
    /// LATCHED: a later candidate's downgrade cannot clear an earlier
    /// confirmation, because the earlier witness is still a valid violation.
    confirmed: bool,
    /// Trusted-oracle adjudications currently in flight. A counter rather than a
    /// flag so repeated / nested gate calls compose — the post-BaB attack lane
    /// re-enters the gate after the first verdict.
    adjudicating: usize,
    /// #attack-concurrent: concurrent-attack publications in flight — inside
    /// the ATTACK DOOR ([`AttackPublicationGuard`]): from before the trusted
    /// gate to after the attack's own critical section. The main thread's
    /// synchronized door ([`publish_main_verdict_in`]) waits on it.
    attack_inflight: usize,
    /// #attack-concurrent: the main thread CLOSED the attack door — its verdict
    /// is being (or has been) written. No attack publication may start, and an
    /// in-flight one may no longer write. Latched.
    attack_door_closed: bool,
}

static SAT_PRECEDENCE: std::sync::Mutex<SatPrecedence> = std::sync::Mutex::new(SatPrecedence {
    confirmed: false,
    adjudicating: 0,
    attack_inflight: 0,
    attack_door_closed: false,
});

/// #attack-concurrent: signalled whenever a concurrent-attack publication
/// leaves the attack door, so the main thread's synchronized door wakes as
/// soon as the last in-flight adjudication ends. Paired with
/// [`SAT_PRECEDENCE`].
static ATTACK_DOOR_CHANGED: std::sync::Condvar = std::sync::Condvar::new();

/// Lock the precedence record, ignoring poisoning.
///
/// A panic in some other thread must not turn this into a panic on the
/// publication path. `into_inner` keeps the (plain-data) state, and the two
/// fields only ever latch to `true` or increment-then-decrement, so the worst a
/// poisoned state can carry is an adjudication that is never released — which
/// REFUSES the lane's early exit. That is the safe direction.
fn lock_sat_precedence(
    precedence: &std::sync::Mutex<SatPrecedence>,
) -> std::sync::MutexGuard<'_, SatPrecedence> {
    precedence
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Record that the trusted oracle RECONFIRMED a counterexample for this
/// instance. From this instant no lane may publish `unsat` (#sat-precedence).
fn note_confirmed_sat_in(precedence: &std::sync::Mutex<SatPrecedence>) {
    lock_sat_precedence(precedence).confirmed = true;
}

/// Process-global face of [`note_confirmed_sat_in`].
fn note_confirmed_sat() {
    note_confirmed_sat_in(&SAT_PRECEDENCE);
}

/// RAII marker for "a candidate counterexample is inside the trusted-oracle gate
/// right now" (#sat-precedence). Held for the whole of
/// [`gate_sat_with_trusted_oracle`], so the interval in which a counterexample
/// becomes confirmed is strictly inside a period during which the lane is
/// refused.
struct SatAdjudicationGuard<'a> {
    precedence: &'a std::sync::Mutex<SatPrecedence>,
}

impl<'a> SatAdjudicationGuard<'a> {
    fn enter_in(precedence: &'a std::sync::Mutex<SatPrecedence>) -> Self {
        lock_sat_precedence(precedence).adjudicating += 1;
        Self { precedence }
    }
}

impl Drop for SatAdjudicationGuard<'_> {
    fn drop(&mut self) {
        let mut state = lock_sat_precedence(self.precedence);
        state.adjudicating = state.adjudicating.saturating_sub(1);
    }
}

/// Process-global face of [`SatAdjudicationGuard::enter_in`].
fn enter_sat_adjudication() -> SatAdjudicationGuard<'static> {
    SatAdjudicationGuard::enter_in(&SAT_PRECEDENCE)
}

/// #sat-precedence, MAIN-THREAD side. An `unsat` must not be published on an
/// instance for which the trusted oracle already reconfirmed a counterexample.
///
/// This is not the lane race — that is closed inside [`publish_lane_unsat_in`] —
/// it is the deterministic tail of it. A counterexample can be confirmed and
/// still fail to reach RESULTS_FILE: the #witness-exec-match gate refuses a
/// witness whose `Y_j` block it cannot validate the way the organizer will, and
/// the resulting `unknown` then falls through to the post-BaB grace and the
/// final twin-wall join, either of which can hand back the margin-row lane's
/// `Unsat` (`ConcurrentLaneTake::Verdict(res) => return res`). Publishing that
/// would state the exact opposite of a constructive result this process holds.
/// The outward answer is the 0-point `unknown`.
///
/// Only `Unsat` is affected. `Sat`, `Unknown`, `Timeout` and `Error` pass
/// through untouched, so on every instance that never latched a confirmation —
/// which is every instance that never upheld a `sat` — this is two loads and a
/// pattern match.
fn refuse_unsat_against_confirmed_counterexample_in(
    precedence: &std::sync::Mutex<SatPrecedence>,
    result: VnncompResult,
) -> VnncompResult {
    if !matches!(result, VnncompResult::Unsat(_)) {
        return result;
    }
    // Read and RELEASE before the logging below: the guard's scope is explicit
    // here rather than resting on the temporary-lifetime rule for `if`
    // conditions, and nothing else in this function needs the lock.
    let confirmed = lock_sat_precedence(precedence).confirmed;
    refuse_unsat_given_confirmation(confirmed, result)
}

/// The #sat-precedence filter on an already-read confirmation state, so the
/// synchronized main door ([`publish_main_verdict_in`]) can apply it INSIDE
/// its critical section. Identical decision and logging to
/// [`refuse_unsat_against_confirmed_counterexample_in`].
fn refuse_unsat_given_confirmation(confirmed: bool, result: VnncompResult) -> VnncompResult {
    if !matches!(result, VnncompResult::Unsat(_)) || !confirmed {
        return result;
    }
    eprintln!(
        "vnncomp: REFUSING to publish `unsat` — this instance holds an \
         ONNX-Runtime-reconfirmed counterexample whose witness could not be published \
         (#sat-precedence); emitting the sound `unknown` instead"
    );
    crate::flight::note(
        "sat_precedence",
        crate::flight::FlightStatus::Ran,
        Some("main-thread unsat REFUSED: a confirmed counterexample exists".to_string()),
    );
    VnncompResult::Unknown
}

/// Process-global face of [`refuse_unsat_against_confirmed_counterexample_in`].
fn refuse_unsat_against_confirmed_counterexample(result: VnncompResult) -> VnncompResult {
    refuse_unsat_against_confirmed_counterexample_in(&SAT_PRECEDENCE, result)
}

/// Outcome of the lane's terminal-publication attempt (#sat-precedence).
#[derive(Debug, Eq, PartialEq)]
enum LaneUnsatPublication {
    /// The lane owns RESULTS_FILE and its `unsat` is on disk.
    Published,
    /// A counterexample has already been reconfirmed by ONNX Runtime; the
    /// constructive witness outranks this bound-based proof.
    RefusedConfirmedSat,
    /// A candidate counterexample is inside the trusted-oracle gate right now.
    RefusedAdjudicatingSat,
    /// The main thread already took the single publication right.
    RefusedClaimTaken,
    /// The claim was taken and given back; nothing reached disk.
    WriteFailed(String),
}

/// The lane's terminal publication as ONE critical section: precedence read,
/// exclusive claim, and the write itself (#sat-precedence).
///
/// `write` deliberately runs while the precedence mutex is held. That is the
/// whole point: it makes "a confirmed counterexample outranks this `unsat`" a
/// fact about the FILE rather than about a check that happened some time before
/// the file was written.
#[allow(
    clippy::significant_drop_tightening,
    reason = "the guard is deliberately held ACROSS `write`"
)]
fn publish_lane_unsat_in<W>(
    precedence: &std::sync::Mutex<SatPrecedence>,
    claim: &std::sync::atomic::AtomicBool,
    write: W,
) -> LaneUnsatPublication
where
    W: FnOnce() -> Result<()>,
{
    let state = lock_sat_precedence(precedence);
    if state.confirmed {
        return LaneUnsatPublication::RefusedConfirmedSat;
    }
    if state.adjudicating > 0 {
        return LaneUnsatPublication::RefusedAdjudicatingSat;
    }
    if !claim_terminal_publication_in(claim) {
        return LaneUnsatPublication::RefusedClaimTaken;
    }
    match write() {
        Ok(()) => LaneUnsatPublication::Published,
        Err(error) => {
            // Nothing reached disk, so hand the right back: the main thread must
            // still be able to publish whatever the internal verifier decided.
            release_terminal_publication_in(claim);
            LaneUnsatPublication::WriteFailed(error.to_string())
        }
    }
}

/// Publish a certified concurrent-lane `unsat` from the LANE's own thread and
/// end the instance (#twinwall-early-exit). Returns only when publication was
/// declined — the caller then hands the verdict to the channel as before.
///
/// #sat-precedence: the attempt goes through [`publish_lane_unsat_in`], so a
/// counterexample this process has already had ONNX Runtime reconfirm — or is
/// adjudicating right now — refuses this publication outright. See
/// [`SatPrecedence`] for why the constructive witness outranks the proof.
pub(crate) fn publish_lane_unsat_and_exit(lane_secs: f64, receipt: UnsatReceipt) {
    let Some(results_file) = LANE_EARLY_PUBLISH_TARGET
        .read()
        .ok()
        .and_then(|slot| slot.clone())
    else {
        eprintln!(
            "margin-row BaB: EARLY EXIT declined — no scored publication target is armed for \
             this route; handing the verdict to the ordinary join"
        );
        return;
    };
    let result = VnncompResult::Unsat(receipt);
    match publish_lane_unsat_in(&SAT_PRECEDENCE, &TERMINAL_PUBLICATION_CLAIMED, || {
        write_results(&results_file, &result)
    }) {
        LaneUnsatPublication::Published => {}
        LaneUnsatPublication::RefusedConfirmedSat => {
            eprintln!(
                "margin-row BaB: EARLY EXIT REFUSED — this instance holds an ONNX-Runtime-\
                 reconfirmed counterexample, and a constructive witness outranks a bound-based \
                 proof (#sat-precedence); handing the verdict to the ordinary join"
            );
            crate::flight::note(
                "sat_precedence",
                crate::flight::FlightStatus::Ran,
                Some(format!(
                    "lane UNSAT at {lane_secs:.1}s REFUSED publication: a confirmed \
                     counterexample already exists for this instance"
                )),
            );
            return;
        }
        LaneUnsatPublication::RefusedAdjudicatingSat => {
            eprintln!(
                "margin-row BaB: EARLY EXIT DEFERRED — a candidate counterexample is inside the \
                 trusted-oracle gate right now (#sat-precedence); handing the verdict to the \
                 ordinary join, which still publishes it if the candidate is downgraded"
            );
            crate::flight::note(
                "sat_precedence",
                crate::flight::FlightStatus::Ran,
                Some(format!(
                    "lane UNSAT at {lane_secs:.1}s DEFERRED: a counterexample candidate was \
                     under trusted-oracle adjudication"
                )),
            );
            return;
        }
        LaneUnsatPublication::RefusedClaimTaken => {
            eprintln!(
                "margin-row BaB: EARLY EXIT declined — the main thread already claimed terminal \
                 publication; handing the verdict to the ordinary join"
            );
            return;
        }
        LaneUnsatPublication::WriteFailed(error) => {
            eprintln!(
                "margin-row BaB: EARLY EXIT declined — could not publish {}: {error}; released \
                 the publication claim so the ordinary join can still write",
                results_file.display()
            );
            return;
        }
    }
    crate::flight::note(
        "margin_row_early_exit",
        crate::flight::FlightStatus::Ran,
        Some(format!(
            "lane UNSAT at {lane_secs:.1}s; published and terminated without waiting for the \
             internal verifier"
        )),
    );
    crate::flight::note(
        "result_publish",
        crate::flight::FlightStatus::Ran,
        Some(result.token().to_string()),
    );
    crate::flight::finish(result.token());
    crate::flight::global().write_sidecar(&results_file);
    println!("Result: {}", result.token());
    eprintln!(
        "margin-row BaB: EARLY EXIT — certified UNSAT published at {lane_secs:.1}s of lane time; \
         terminating instead of running out the internal verifier's remaining budget"
    );
    close_proof_bundle(&result);
    exit_scored_instance_without_teardown();
}

/// ENGINE_PROGRAM §1.7 B1, AFTER RESULTS_FILE is written: close the Proof
/// profile's proof-hint bundle with the PUBLISHED verdict (a no-op under
/// Competition, which wired `NullSink`). Post-publication by construction:
/// every caller has already written RESULTS_FILE and the flight sidecar.
fn close_proof_bundle(result: &VnncompResult) {
    let unsat = match result {
        VnncompResult::Unsat(receipt) => Some(receipt),
        _ => None,
    };
    super::proof_bundle::after_publication_receipt(result.token(), unsat);
}

// --------------------------------------------------------------------------
//  #attack-concurrent — publish the concurrent attack lane's `sat` from the
//  attack thread, first-verdict-wins, through the main path's sat pipeline.
// --------------------------------------------------------------------------

/// Everything the attack thread needs to replay the main path's sat pipeline
/// and publish: the scored RESULTS_FILE and the paths/deadline the trusted
/// gate and the VNN-LIB 2.0 normalization read.
#[derive(Clone, Debug)]
struct ConcurrentAttackPublishTarget {
    results_file: PathBuf,
    onnx: PathBuf,
    vnnlib: PathBuf,
    instance_deadline: Option<std::time::Instant>,
}

/// Armed on the ORDINARY route only, beside [`arm_lane_early_publish`] (the
/// short-grace route has a single authorized writer and keeps it). Silent and
/// inert unless a race site with `attack.concurrent` armed reaches
/// [`publish_concurrent_attack_sat`]; absent ⇒ every race site refuses as
/// `publisher_unarmed` and runs today's serial code.
static CONCURRENT_ATTACK_PUBLISH_TARGET: std::sync::RwLock<Option<ConcurrentAttackPublishTarget>> =
    std::sync::RwLock::new(None);

fn arm_concurrent_attack_publish(
    results_file: &Path,
    onnx: &Path,
    vnnlib: &Path,
    instance_deadline: Option<std::time::Instant>,
) {
    if let Ok(mut slot) = CONCURRENT_ATTACK_PUBLISH_TARGET.write() {
        *slot = Some(ConcurrentAttackPublishTarget {
            results_file: results_file.to_path_buf(),
            onnx: onnx.to_path_buf(),
            vnnlib: vnnlib.to_path_buf(),
            instance_deadline,
        });
    }
}

/// Whether a scored publication target is armed for the concurrent attack.
pub(crate) fn concurrent_attack_publisher_armed() -> bool {
    CONCURRENT_ATTACK_PUBLISH_TARGET
        .read()
        .is_ok_and(|slot| slot.is_some())
}

/// The `[attack-concurrent] armed=1` line, printed once at the entry point
/// when the frozen preset arms the key (and nothing at all otherwise).
fn announce_attack_concurrent(preset_snapshot: Option<&BetaCrownPresetSnapshot>) {
    let armed = preset_snapshot
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| preset.attack.concurrent)
        .unwrap_or(false);
    if armed {
        eprintln!("[attack-concurrent] armed=1 source=preset key=attack.concurrent value=on");
        crate::flight::note(
            "attack_concurrent_armed",
            crate::flight::FlightStatus::Ran,
            Some("source=preset key=attack.concurrent value=on".to_string()),
        );
    }
}

/// Outcome of the concurrent attack's terminal-publication attempt.
#[derive(Debug, Eq, PartialEq)]
enum AttackSatPublication {
    /// The attack owns RESULTS_FILE and its `sat` is on disk.
    Published,
    /// The trusted gate never latched a confirmation: a `sat` reaches
    /// RESULTS_FILE only through the gate (defence in depth; the caller only
    /// gets here after the gate upheld it).
    RefusedUnconfirmed,
    /// The single terminal-publication right was already taken.
    RefusedClaimTaken,
    /// The claim was taken and given back; nothing reached disk.
    WriteFailed(String),
    /// The main thread closed the attack door: its verdict is committed.
    RefusedDoorClosed,
}

/// The attack's terminal publication as ONE critical section of the
/// #sat-precedence lock: the confirmation check, the exclusive claim, and the
/// write. Holding the lock across the write makes "first verdict wins" a fact
/// about the FILE: a lane `unsat` (which takes the same lock and refuses on
/// `confirmed`) cannot interleave, and the main thread's later claim fails.
#[allow(
    clippy::significant_drop_tightening,
    reason = "the guard is deliberately held ACROSS `write`"
)]
fn publish_attack_sat_in<W>(
    precedence: &std::sync::Mutex<SatPrecedence>,
    claim: &std::sync::atomic::AtomicBool,
    write: W,
) -> AttackSatPublication
where
    W: FnOnce() -> Result<()>,
{
    let state = lock_sat_precedence(precedence);
    if state.attack_door_closed {
        return AttackSatPublication::RefusedDoorClosed;
    }
    if !state.confirmed {
        return AttackSatPublication::RefusedUnconfirmed;
    }
    if !claim_terminal_publication_in(claim) {
        return AttackSatPublication::RefusedClaimTaken;
    }
    match write() {
        Ok(()) => AttackSatPublication::Published,
        Err(error) => {
            release_terminal_publication_in(claim);
            AttackSatPublication::WriteFailed(error.to_string())
        }
    }
}

/// #attack-concurrent follow-up (b): one concurrent-attack publication inside
/// the ATTACK DOOR — entered by [`prepare_concurrent_attack_sat`] on the
/// attack thread (inside the race scope), moved into the adjudication job and
/// held by [`publish_concurrent_attack_sat`] through the trusted gate until it
/// returns (an upheld, published `sat` never returns: the process ends inside
/// it); a job dropped unrun releases it. The main thread's synchronized door
/// ([`publish_main_verdict_in`]) waits while any is held, and `enter_in`
/// refuses (`None`) once that door has closed.
struct AttackPublicationGuard<'a> {
    precedence: &'a std::sync::Mutex<SatPrecedence>,
    door: &'a std::sync::Condvar,
}

impl<'a> AttackPublicationGuard<'a> {
    fn enter_in(
        precedence: &'a std::sync::Mutex<SatPrecedence>,
        door: &'a std::sync::Condvar,
    ) -> Option<Self> {
        let mut state = lock_sat_precedence(precedence);
        if state.attack_door_closed {
            return None;
        }
        state.attack_inflight += 1;
        Some(Self { precedence, door })
    }
}

impl Drop for AttackPublicationGuard<'_> {
    fn drop(&mut self) {
        {
            let mut state = lock_sat_precedence(self.precedence);
            state.attack_inflight = state.attack_inflight.saturating_sub(1);
        }
        self.door.notify_all();
    }
}

/// Wall the main thread's synchronized door keeps before the instance's
/// official deadline: it waits for an in-flight concurrent-attack
/// adjudication no later than `instance_deadline - this`, then closes the
/// attack door and publishes its own verdict regardless.
const MAIN_DOOR_PUBLISH_RESERVE: std::time::Duration = std::time::Duration::from_secs(1);

/// What the main thread's synchronized door did.
#[derive(Debug)]
struct MainDoorReport {
    /// The verdict after the #sat-precedence filter: what was (or, without
    /// the claim, would have been) written.
    result: VnncompResult,
    /// The door took the single terminal-publication claim.
    owns_publication: bool,
    /// The write's own answer, when the door owned the claim.
    written: Option<Result<bool>>,
    /// Wall spent waiting for in-flight attack adjudications.
    waited: std::time::Duration,
    /// Attack adjudications still in flight when the door closed: abandoned
    /// at the door's deadline (they can no longer write).
    inflight_at_close: usize,
}

/// #attack-concurrent follow-up (b): the MAIN thread's terminal publication,
/// SYNCHRONIZED with in-flight concurrent-attack adjudications. The
/// counterpart of the margin-row lane's adjudication-aware door
/// ([`publish_lane_unsat_in`]) for the publisher that cannot defer to a later
/// join, because it IS the last join. Used only on a run where a race
/// spawned; every other run keeps the dark door verbatim.
///
/// Needed because the race's join is bounded (follow-up (a)): an attack
/// adjudication may outlive the race, so "the scope joined the attack thread
/// before the lane returned" no longer orders it before this door.
///
/// 1. WAIT (the lock released while waiting) while a concurrent-attack
///    publication is inside the attack door, until `wait_until`. An upheld
///    attack `sat` publishes meanwhile (and ends the process); a downgrade
///    wakes the door at once.
/// 2. CLOSE the attack door (latched): an adjudication still in flight at the
///    deadline is abandoned — it may finish its gate, but it can no longer
///    write, and no new attack publication may start.
/// 3. In the SAME critical section: the #sat-precedence filter (a
///    confirmation latched before this point turns `unsat` into `unknown`),
///    the single terminal claim, and the write.
///
/// Holding the lock from the close through the write makes the order a fact
/// about the FILE, as on the other two doors: a confirmation latched before
/// the close is honoured by the filter, and one latched after it cannot reach
/// the file because the attack door is closed.
#[allow(
    clippy::significant_drop_tightening,
    reason = "the guard is deliberately held from the door's close ACROSS `write`"
)]
fn publish_main_verdict_in<W>(
    precedence: &std::sync::Mutex<SatPrecedence>,
    door: &std::sync::Condvar,
    claim: &std::sync::atomic::AtomicBool,
    result: VnncompResult,
    wait_until: Option<std::time::Instant>,
    write: W,
) -> MainDoorReport
where
    W: FnOnce(&VnncompResult) -> Result<bool>,
{
    let started = std::time::Instant::now();
    let mut state = lock_sat_precedence(precedence);
    while state.attack_inflight > 0 {
        let Some(remaining) = wait_until
            .and_then(|deadline| deadline.checked_duration_since(std::time::Instant::now()))
            .filter(|remaining| !remaining.is_zero())
        else {
            break;
        };
        state = match door.wait_timeout(state, remaining) {
            Ok((guard, _)) => guard,
            Err(poisoned) => poisoned.into_inner().0,
        };
    }
    let waited = started.elapsed();
    let inflight_at_close = state.attack_inflight;
    state.attack_door_closed = true;
    let result = refuse_unsat_given_confirmation(state.confirmed, result);
    if !claim_terminal_publication_in(claim) {
        return MainDoorReport {
            result,
            owns_publication: false,
            written: None,
            waited,
            inflight_at_close,
        };
    }
    let written = write(&result);
    drop(state);
    MainDoorReport {
        result,
        owns_publication: true,
        written: Some(written),
        waited,
        inflight_at_close,
    }
}

/// The concurrent attack's sat pipeline, in the MAIN path's order, with every
/// stage injected so the order itself is testable
/// (`concurrent_publisher_replays_the_main_sat_pipeline_order`):
///
/// 1. parse the captured-route JSON (`parse_competition_json_with`, the graph
///    ledger never consulted: only a `sat` witness is read);
/// 2. the #smart-turn-qdq report-only latch (`run_and_translate`);
/// 3. `gate_sat_with_trusted_oracle` (holds the adjudication marker, latches
///    the confirmation);
/// 4. `graph_free_sidefile::record_trusted_oracle_outcome`;
/// 5. `normalize_vnnlib2_sat_result` (the entry point, after the gate);
/// 6. the one-critical-section publication.
fn concurrent_attack_sat_pipeline(
    json: &str,
    qdq_withholds: impl FnOnce() -> bool,
    gate: impl FnOnce(Option<&str>) -> VnncompResult,
    record: impl FnOnce(bool, bool),
    normalize: impl FnOnce(VnncompResult) -> VnncompResult,
    publish: impl FnOnce(&VnncompResult) -> AttackSatPublication,
) -> std::result::Result<VnncompResult, crate::commands::beta_crown::ConcurrentSatPublication> {
    use crate::commands::beta_crown::ConcurrentSatPublication as Declined;
    let witness =
        match parse_competition_json_with(json, || Err("graph_ledger_not_consulted".to_string())) {
            Some(VnncompResult::Sat { witness }) => witness,
            _ => return Err(Declined::Downgraded),
        };
    if qdq_withholds() {
        eprintln!(
            "[qdq_relax] report-only: withholding the concurrent attack's sat verdict — the \
             dark QDQ relaxation lane may not publish verdicts this round"
        );
        return Err(Declined::Withheld);
    }
    let gated = gate(witness.as_deref());
    let upheld = matches!(gated, VnncompResult::Sat { .. });
    record(true, upheld);
    if !upheld {
        return Err(Declined::Downgraded);
    }
    let normalized = normalize(gated);
    if !matches!(normalized, VnncompResult::Sat { .. }) {
        return Err(Declined::Downgraded);
    }
    match publish(&normalized) {
        AttackSatPublication::Published => Ok(normalized),
        AttackSatPublication::RefusedUnconfirmed => Err(Declined::Unconfirmed),
        AttackSatPublication::RefusedClaimTaken => Err(Declined::ClaimTaken),
        AttackSatPublication::WriteFailed(error) => Err(Declined::WriteFailed(error)),
        AttackSatPublication::RefusedDoorClosed => Err(Declined::DoorClosed),
    }
}

/// #attack-concurrent: PREPARE a race candidate's adjudication on the ATTACK
/// thread — the dispatch's publish hook calls this with the JSON it rendered
/// for the candidate — by ENTERING THE ATTACK DOOR HERE and handing the entry
/// to the owned job that later runs [`publish_concurrent_attack_sat`] on the
/// detached `attack-concurrent-gate` thread.
///
/// review(attack-conc-followups): the entry used to happen INSIDE that job,
/// i.e. on the detached thread, after the race had already been allowed to
/// stop waiting for it. A join deadline that had already passed when the
/// candidate was prepared (a proof decided within `JOIN_RESERVE` of the
/// overall deadline, or a candidate arriving just before the bounded join's
/// end) let the race return, the lane return, and the main thread's
/// synchronized door find `attack_inflight == 0`, close, and publish — while
/// the detached job had not yet registered, so the candidate was then
/// refused at a closed door WITHOUT ever being adjudicated. That is ordering
/// by thread-spawn timing, not by construction. Entered here, the in-flight
/// count is raised on the attack thread, inside the race scope, before the
/// race can join — so the door sees every prepared candidate.
pub(crate) fn prepare_concurrent_attack_sat(
    json: String,
    report: crate::commands::beta_crown::ConcurrentSatReport,
) -> crate::commands::beta_crown::attack_concurrent::PreparedSat {
    prepare_concurrent_attack_sat_in(
        &SAT_PRECEDENCE,
        &ATTACK_DOOR_CHANGED,
        json,
        report,
        publish_concurrent_attack_sat,
    )
}

/// The adjudication a prepared candidate's job runs, holding its attack-door
/// entry (seam for [`prepare_concurrent_attack_sat_in`]).
type ConcurrentAttackAdjudicator = fn(
    AttackPublicationGuard<'static>,
    &str,
    &crate::commands::beta_crown::ConcurrentSatReport,
) -> crate::commands::beta_crown::ConcurrentSatPublication;

/// Seam for [`prepare_concurrent_attack_sat`]: the door state and the
/// adjudicator are passed in so the "entered at preparation, not in the job"
/// rule is testable on local state.
fn prepare_concurrent_attack_sat_in(
    precedence: &'static std::sync::Mutex<SatPrecedence>,
    door: &'static std::sync::Condvar,
    json: String,
    report: crate::commands::beta_crown::ConcurrentSatReport,
    adjudicate: ConcurrentAttackAdjudicator,
) -> crate::commands::beta_crown::attack_concurrent::PreparedSat {
    use crate::commands::beta_crown::attack_concurrent::PreparedSat;
    use crate::commands::beta_crown::ConcurrentSatPublication as Declined;
    // Follow-up (b): the whole adjudication runs INSIDE the attack door, which
    // the main thread's synchronized publication waits on (and closes at its
    // deadline). A closed door means the main thread's verdict is committed.
    let Some(entered) = AttackPublicationGuard::enter_in(precedence, door) else {
        eprintln!(
            "[attack-concurrent] candidate refused site={}: the main thread already closed the \
             attack door (its verdict is committed)",
            report.site.token()
        );
        return PreparedSat::Declined(Declined::DoorClosed);
    };
    PreparedSat::Adjudicate(Box::new(move || adjudicate(entered, &json, &report)))
}

/// Publish the concurrent attack lane's candidate from the detached gate
/// thread and end the instance (#attack-concurrent). `json` is the
/// captured-route JSON the dispatch rendered for the lane's `Violated` result
/// (the same renderer the main path's capture uses); `_attack_door` is the
/// attack-door entry [`prepare_concurrent_attack_sat`] took on the attack
/// thread, held until this returns (an upheld, published `sat` never
/// returns). Returns only when publication was declined; the race then leaves
/// the proof's verdict in charge (or, for `NotArmed` / `WriteFailed`, hands
/// the candidate to the main thread as the serial site would).
fn publish_concurrent_attack_sat(
    _attack_door: AttackPublicationGuard<'static>,
    json: &str,
    report: &crate::commands::beta_crown::ConcurrentSatReport,
) -> crate::commands::beta_crown::ConcurrentSatPublication {
    use crate::commands::beta_crown::ConcurrentSatPublication as Declined;
    let Some(target) = CONCURRENT_ATTACK_PUBLISH_TARGET
        .read()
        .ok()
        .and_then(|slot| slot.clone())
    else {
        return Declined::NotArmed;
    };
    let outcome = concurrent_attack_sat_pipeline(
        json,
        crate::commands::beta_crown::qdq_probe::qdq_relaxation_engaged,
        |witness| {
            gate_sat_with_trusted_oracle(
                &target.onnx,
                &target.vnnlib,
                witness,
                target.instance_deadline,
            )
        },
        graph_free_sidefile::record_trusted_oracle_outcome,
        |gated| normalize_vnnlib2_sat_result(&target.onnx, &target.vnnlib, gated),
        |result| {
            publish_attack_sat_in(&SAT_PRECEDENCE, &TERMINAL_PUBLICATION_CLAIMED, || {
                write_results(&target.results_file, result)
            })
        },
    );
    let result = match outcome {
        Ok(result) => result,
        Err(declined) => {
            if declined == Declined::DoorClosed {
                eprintln!(
                    "[attack-concurrent] candidate refused site={}: the main thread closed the \
                     attack door while it was under adjudication (abandoned at the door's \
                     deadline; the committed verdict stands)",
                    report.site.token()
                );
                crate::flight::note(
                    "attack_concurrent_door_closed",
                    crate::flight::FlightStatus::Ran,
                    Some(format!(
                        "site={} adjudication outlived the main door",
                        report.site.token()
                    )),
                );
            }
            if declined == Declined::ClaimTaken {
                // Unreachable by admission (the margin-row lane owns concurrency
                // whenever it exists) and by the synchronized main door (it
                // claims only with no attack publication in flight, or after
                // CLOSING the attack door, which this publication checks
                // first): a second publisher exists.
                eprintln!(
                    "[attack-concurrent] EMERGENCY CONFLICT site={} — an ORT-confirmed sat \
                     found the terminal publication already claimed; NOT writing (the \
                     claimant's verdict stands, #sat-precedence refuses any later unsat)",
                    report.site.token()
                );
                crate::flight::note(
                    "attack_concurrent_conflict",
                    crate::flight::FlightStatus::Ran,
                    Some(format!(
                        "site={} confirmed sat found the terminal claim taken",
                        report.site.token()
                    )),
                );
            }
            return declined;
        }
    };
    let line = report.published_line();
    crate::flight::note(
        "attack_concurrent",
        crate::flight::FlightStatus::Ran,
        Some(line.trim_start_matches("[attack-concurrent] ").to_string()),
    );
    crate::flight::note(
        "result_publish",
        crate::flight::FlightStatus::Ran,
        Some(result.token().to_string()),
    );
    crate::flight::finish(result.token());
    crate::flight::global().write_sidecar(&target.results_file);
    println!("Result: {}", result.token());
    eprintln!("{line}");
    close_proof_bundle(&result);
    exit_scored_instance_without_teardown();
}

static SHORT_GRACE_STAGE_SEQUENCE: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

#[cfg(test)]
#[path = "vnncomp/prepared_root_writer_tests.rs"]
mod prepared_root_writer_tests;

/// Path, staging, channel and writer metadata remain paid on the genuine
/// retained proof owner's original ledger until publication has finished.
fn retained_publication_bytes(path: &Path) -> Result<usize> {
    path.as_os_str()
        .len()
        .checked_mul(4)
        .and_then(|bytes| bytes.checked_add(8192))
        .ok_or_else(|| anyhow!("retained proof publication capacity overflow"))
}

/// A failed write can leave a partial file before a queued request exists.
/// This stack-only guard borrows the already paid path and closes that gap.
struct UnpublishedResultCleanup<'a> {
    path: Option<&'a Path>,
}

impl<'a> UnpublishedResultCleanup<'a> {
    fn new(path: &'a Path) -> Self {
        Self { path: Some(path) }
    }

    fn disarm(&mut self) {
        self.path = None;
    }
}

impl Drop for UnpublishedResultCleanup<'_> {
    fn drop(&mut self) {
        if let Some(path) = self.path {
            let _ = fs::remove_file(path);
        }
    }
}

fn stage_short_grace_result(
    results_file: &Path,
    result: &VnncompResult,
) -> std::io::Result<PathBuf> {
    stage_short_grace_result_with_writer(results_file, result, |path, rendered| {
        fs::write(path, rendered)
    })
}

fn stage_short_grace_result_with_writer(
    results_file: &Path,
    result: &VnncompResult,
    write: impl FnOnce(&Path, &str) -> std::io::Result<()>,
) -> std::io::Result<PathBuf> {
    use std::sync::atomic::Ordering;

    // Rendering and the potentially blocking file write deliberately happen
    // in the verifier thread, before the coordinator admits a publication.
    // The coordinator's final critical section is therefore one same-directory
    // rename plus a child-confirmed ACK wait bounded by the anchored cutoff.
    let rendered = result.render_results_file();
    let sequence = SHORT_GRACE_STAGE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
    let staged_path = results_file.with_extension(format!(
        "short-grace.{}.{}.staged",
        std::process::id(),
        sequence
    ));
    if let VnncompResult::Unsat(receipt) = result {
        if receipt.has_retained_owner() {
            let bytes = retained_publication_bytes(results_file)
                .map_err(|error| std::io::Error::other(error.to_string()))?;
            if staged_path.capacity() > bytes {
                return Err(std::io::Error::other(
                    "retained proof staged path capacity exceeds admission",
                ));
            }
        }
    }
    let mut cleanup = UnpublishedResultCleanup::new(&staged_path);
    write(&staged_path, &rendered)?;
    cleanup.disarm();
    drop(cleanup);
    Ok(staged_path)
}

struct ShortGracePublicationRequest {
    staged_path: PathBuf,
    acknowledgement: std::sync::mpsc::SyncSender<std::result::Result<(), String>>,
    receipt: Option<UnsatReceipt>,
    _publication_claim: Option<ny_propagate::certify::work::PersistentReservation>,
}

impl Drop for ShortGracePublicationRequest {
    fn drop(&mut self) {
        // A successful rename makes this a cheap NotFound. Every decline/error
        // path removes the staged verdict so it can never be mistaken for an
        // admitted RESULTS_FILE publication.
        let _ = fs::remove_file(&self.staged_path);
    }
}

#[derive(Clone)]
struct ShortGraceResultPublisher {
    results_file: PathBuf,
    sender: std::sync::mpsc::Sender<ShortGracePublicationRequest>,
}

impl ShortGraceResultPublisher {
    /// Ask the sole short-grace coordinator to publish one terminal result.
    ///
    /// `Ok(false)` means the scored deadline won the race: the coordinator is
    /// closed and the pre-written `unknown` is immutable. No caller on this
    /// route writes RESULTS_FILE directly after the coordinator starts.
    fn publish_terminal(&self, result: VnncompResult) -> std::io::Result<bool> {
        let receipt = match &result {
            VnncompResult::Unsat(receipt) if receipt.has_retained_owner() => Some(receipt.clone()),
            _ => None,
        };
        let publication_claim = receipt
            .as_ref()
            .map(|receipt| {
                receipt.reserve_owner_publication(
                    retained_publication_bytes(&self.results_file)?,
                    None,
                )
            })
            .transpose()
            .map(Option::flatten)
            .map_err(|error| std::io::Error::other(error.to_string()))?;
        let staged_path = stage_short_grace_result(&self.results_file, &result)?;
        if let Some(receipt) = &receipt {
            if let Err(error) = receipt.checkpoint_owner(None) {
                let _ = fs::remove_file(&staged_path);
                return Err(std::io::Error::other(error.to_string()));
            }
        }
        let (acknowledgement, result_rx) = std::sync::mpsc::sync_channel(1);
        if self
            .sender
            .send(ShortGracePublicationRequest {
                staged_path,
                acknowledgement,
                receipt,
                _publication_claim: publication_claim,
            })
            .is_err()
        {
            return Ok(false);
        }
        match result_rx.recv() {
            Ok(Ok(())) => {
                // Only an ACKNOWLEDGED rename is a publication on this route,
                // so the #watchdog-verdict-overwrite record is taken here and
                // not at staging time.
                note_published_verdict(&result);
                Ok(true)
            }
            Ok(Err(error)) => Err(std::io::Error::other(error)),
            Err(_) => Ok(false),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ShortGraceCoordinatorOutcome {
    Published,
    Deadline,
    PublisherDropped,
    PublicationFailed,
    AcknowledgementFailed,
}

/// Sole terminal-results writer for the short-grace route.
///
/// The placeholder is written before this starts and verdict bytes are fully
/// staged before they enter the channel. A request must be admitted strictly
/// before `publication_deadline`; after its sole rename, it must also complete
/// the helper's child-confirmed canonical-monotonic C/ACK/P protocol. The
/// independent hard-stop timer does not run in this function, so a blocked
/// rename or missing ACK cannot delay deadline enforcement.
fn await_short_grace_terminal_result(
    results_file: &Path,
    publication_deadline: std::time::Instant,
    receiver: std::sync::mpsc::Receiver<ShortGracePublicationRequest>,
    external_watchdog: Option<&ExternalWatchdogController>,
) -> ShortGraceCoordinatorOutcome {
    await_short_grace_terminal_result_with_rename(
        results_file,
        publication_deadline,
        receiver,
        external_watchdog,
        |staged_path, destination| fs::rename(staged_path, destination),
    )
}

fn await_short_grace_terminal_result_with_rename<F>(
    results_file: &Path,
    publication_deadline: std::time::Instant,
    receiver: std::sync::mpsc::Receiver<ShortGracePublicationRequest>,
    external_watchdog: Option<&ExternalWatchdogController>,
    rename: F,
) -> ShortGraceCoordinatorOutcome
where
    F: FnOnce(&Path, &Path) -> std::io::Result<()>,
{
    await_short_grace_terminal_result_with_rename_and_record(
        results_file,
        publication_deadline,
        receiver,
        external_watchdog,
        rename,
        ExternalWatchdogController::record_publication_commit,
    )
}

fn await_short_grace_terminal_result_with_rename_and_record<F, R>(
    results_file: &Path,
    publication_deadline: std::time::Instant,
    receiver: std::sync::mpsc::Receiver<ShortGracePublicationRequest>,
    external_watchdog: Option<&ExternalWatchdogController>,
    rename: F,
    record_publication: R,
) -> ShortGraceCoordinatorOutcome
where
    F: FnOnce(&Path, &Path) -> std::io::Result<()>,
    R: FnOnce(&ExternalWatchdogController) -> bool,
{
    let remaining = publication_deadline.saturating_duration_since(std::time::Instant::now());
    let request = match receiver.recv_timeout(remaining) {
        Ok(request) => request,
        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
            return ShortGraceCoordinatorOutcome::Deadline;
        }
        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
            return ShortGraceCoordinatorOutcome::PublisherDropped;
        }
    };

    // `recv_timeout` may return a concurrently queued request at the boundary.
    // The absolute deadline, not channel scheduling order, is authoritative.
    if std::time::Instant::now() >= publication_deadline {
        return ShortGraceCoordinatorOutcome::Deadline;
    }

    if let Some(receipt) = &request.receipt {
        if let Err(error) = receipt.checkpoint_owner(Some(publication_deadline)) {
            let _ = request.acknowledgement.send(Err(error.to_string()));
            return ShortGraceCoordinatorOutcome::PublicationFailed;
        }
    }

    // Source validation itself may consume the final remaining interval.
    // The coordinator cutoff applies immediately before the actual rename.
    if std::time::Instant::now() >= publication_deadline {
        return ShortGraceCoordinatorOutcome::Deadline;
    }

    match rename(&request.staged_path, results_file) {
        Ok(()) => {
            // A rename that stalls across the acknowledgement boundary is not
            // a committed result. The always-armed in-process timer kills the
            // parent, and the external helper restores `unknown` unless it
            // consumed C, returned ACK before the earlier prepare cutoff, and
            // then received P before the exact shared monotonic H.
            let acknowledged = external_watchdog.is_some_and(record_publication);
            if !acknowledged {
                let _ =
                    commit_unknown_result_checked(results_file, "short-grace-unacknowledged.tmp");
                return ShortGraceCoordinatorOutcome::AcknowledgementFailed;
            }
            // Best-effort parent-side suppression only. The helper's P receipt
            // timestamp remains authoritative across this check's scheduling
            // gap.
            if external_watchdog.is_none_or(|watchdog| !watchdog.hard_stop.is_strictly_future()) {
                let _ =
                    commit_unknown_result_checked(results_file, "short-grace-unacknowledged.tmp");
                return ShortGraceCoordinatorOutcome::Deadline;
            }
            let _ = request.acknowledgement.send(Ok(()));
            ShortGraceCoordinatorOutcome::Published
        }
        Err(error) => {
            let _ = request.acknowledgement.send(Err(error.to_string()));
            ShortGraceCoordinatorOutcome::PublicationFailed
        }
    }
}

/// Best-effort deadline-result commit with explicit confirmation.
///
/// The atomic temp-file + rename path is retried once, then a direct write is
/// attempted as a last resort. Failure remains non-fatal to watchdog
/// enforcement: an unwritable results path must not let a wedged verifier run
/// forever, and the competition pre-write normally leaves sound `unknown`.
fn commit_timeout_result_checked(results_file: &Path, tmp_extension: &str) -> std::io::Result<()> {
    let rendered = VnncompResult::Timeout.render_results_file();
    let confirm = || -> std::io::Result<()> {
        let contents = fs::read_to_string(results_file)?;
        if contents.lines().next() == Some("timeout") {
            Ok(())
        } else {
            Err(std::io::Error::other(
                "results file did not contain timeout after watchdog write",
            ))
        }
    };

    let mut last_error = None;
    for _ in 0..2 {
        match publish_result_atomically(results_file, &rendered, tmp_extension)
            .and_then(|()| confirm())
        {
            Ok(()) => return Ok(()),
            Err(error) => last_error = Some(error),
        }
    }

    fs::write(results_file, rendered)
        .and_then(|()| confirm())
        .map_err(|direct_error| {
            std::io::Error::other(format!(
                "atomic timeout commit failed ({}) and direct fallback failed ({direct_error})",
                last_error
                    .as_ref()
                    .map_or_else(|| "unknown error".to_owned(), ToString::to_string)
            ))
        })
}

fn commit_unknown_result_checked(results_file: &Path, tmp_extension: &str) -> std::io::Result<()> {
    let rendered = VnncompResult::Unknown.render_results_file();
    let confirm = || -> std::io::Result<()> {
        let contents = fs::read_to_string(results_file)?;
        if contents.lines().next() == Some("unknown") {
            Ok(())
        } else {
            Err(std::io::Error::other(
                "results file did not contain unknown after watchdog write",
            ))
        }
    };

    publish_result_atomically(results_file, &rendered, tmp_extension)
        .and_then(|()| confirm())
        .or_else(|atomic_error| {
            fs::write(results_file, rendered)
                .and_then(|()| confirm())
                .map_err(|direct_error| {
                    std::io::Error::other(format!(
                        "atomic unknown commit failed ({atomic_error}) and direct fallback failed \
                         ({direct_error})"
                    ))
                })
        })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
enum ExternalWatchdogDeadline {
    /// Historical/default-off protocol. The helper starts this relative timer
    /// after exec exactly as it did before the SafeNLP experiment existed.
    RelativeSeconds(u64),
    /// Short-grace protocol. This is the exact absolute `CLOCK_MONOTONIC`
    /// boundary sampled by the parent and transported unchanged through exec.
    ParentAnchoredMonotonic {
        hard_stop: CanonicalMonotonicInstant,
    },
}

/// Process-independent nanoseconds on Unix `CLOCK_MONOTONIC`.
///
/// Unlike `std::time::Instant`, this value can be serialized into the helper
/// argv without deriving a second deadline from later wall/monotonic samples.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct CanonicalMonotonicInstant(u64);

impl CanonicalMonotonicInstant {
    const EXPIRED: Self = Self(0);

    #[cfg_attr(
        not(unix),
        allow(dead_code, reason = "the external watchdog is Unix-only")
    )]
    fn checked_add(self, duration: std::time::Duration) -> Option<Self> {
        let nanos = u64::try_from(duration.as_nanos()).ok()?;
        self.0.checked_add(nanos).map(Self)
    }

    fn checked_sub(self, duration: std::time::Duration) -> Option<Self> {
        let nanos = u64::try_from(duration.as_nanos()).ok()?;
        self.0.checked_sub(nanos).map(Self)
    }

    fn remaining(self) -> Option<std::time::Duration> {
        let now = canonical_monotonic_now()?;
        Some(std::time::Duration::from_nanos(
            self.0.saturating_sub(now.0),
        ))
    }

    fn is_strictly_future(self) -> bool {
        canonical_monotonic_now().is_some_and(|now| now < self)
    }
}

#[cfg(unix)]
fn canonical_monotonic_now() -> Option<CanonicalMonotonicInstant> {
    let now = rustix::time::clock_gettime(rustix::time::ClockId::Monotonic);
    let nanos = u64::try_from(now.tv_sec)
        .ok()?
        .checked_mul(1_000_000_000)?
        .checked_add(u64::try_from(now.tv_nsec).ok()?)?;
    Some(CanonicalMonotonicInstant(nanos))
}

#[cfg(not(unix))]
fn canonical_monotonic_now() -> Option<CanonicalMonotonicInstant> {
    None
}

#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
fn parent_anchored_watchdog_deadline(
    hard_stop: CanonicalMonotonicInstant,
) -> ExternalWatchdogDeadline {
    ExternalWatchdogDeadline::ParentAnchoredMonotonic { hard_stop }
}

fn parse_canonical_monotonic_instant(value: &OsStr) -> Result<CanonicalMonotonicInstant> {
    let nanos: u64 = value.to_string_lossy().parse().map_err(|error| {
        anyhow!("{EXTERNAL_WATCHDOG_SUBCOMMAND}: bad hard_stop_monotonic_nanos: {error}")
    })?;
    Ok(CanonicalMonotonicInstant(nanos))
}

#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
fn resolve_short_external_watchdog_deadline(
    deadline: ExternalWatchdogDeadline,
) -> CanonicalMonotonicInstant {
    match deadline {
        ExternalWatchdogDeadline::RelativeSeconds(seconds) => canonical_monotonic_now()
            .and_then(|now| now.checked_add(std::time::Duration::from_secs(seconds)))
            .unwrap_or(CanonicalMonotonicInstant::EXPIRED),
        ExternalWatchdogDeadline::ParentAnchoredMonotonic { hard_stop } => hard_stop,
    }
}

#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
fn historical_external_watchdog_contract(
    timeout_secs: u64,
) -> (ExternalWatchdogDeadline, ExternalWatchdogResultPolicy) {
    (
        ExternalWatchdogDeadline::RelativeSeconds(
            timeout_secs + WATCHDOG_GRACE_SECS + EXTERNAL_WATCHDOG_EXTRA_GRACE_SECS,
        ),
        ExternalWatchdogResultPolicy::CommitTimeout,
    )
}

/// Spawn the out-of-process watchdog helper: a fresh exec of this binary via
/// the hidden [`EXTERNAL_WATCHDOG_SUBCOMMAND`] entry.
#[cfg(unix)]
fn spawn_external_watchdog(
    results_file: &Path,
    deadline: ExternalWatchdogDeadline,
    result_policy: ExternalWatchdogResultPolicy,
) -> std::io::Result<std::process::Child> {
    let exe = std::env::current_exe()?;
    let mut command = std::process::Command::new(exe);
    command.arg(EXTERNAL_WATCHDOG_SUBCOMMAND).arg(results_file);
    let child_returns_publication_ack = match (deadline, result_policy) {
        (
            ExternalWatchdogDeadline::RelativeSeconds(fire_after_secs),
            ExternalWatchdogResultPolicy::CommitTimeout,
        ) => {
            // Keep the historical argv contract byte-for-byte for all
            // default-off/out-of-scope routes.
            command
                .arg(fire_after_secs.to_string())
                .arg(std::process::id().to_string());
            false
        }
        (
            ExternalWatchdogDeadline::ParentAnchoredMonotonic { hard_stop },
            ExternalWatchdogResultPolicy::PreserveAcknowledged,
        ) => {
            command
                .arg(EXTERNAL_WATCHDOG_PARENT_ANCHORED_PROTOCOL)
                .arg(hard_stop.0.to_string())
                .arg(std::process::id().to_string())
                .arg("preserve-acknowledged");
            true
        }
        _ => {
            return Err(std::io::Error::other(
                "external watchdog deadline/result policy mismatch",
            ));
        }
    };
    command
        .stdin(std::process::Stdio::piped())
        // Historical/default-off stdout remains exactly null. Only the
        // parent-anchored short protocol receives a one-byte ACK pipe.
        .stdout(if child_returns_publication_ack {
            std::process::Stdio::piped()
        } else {
            std::process::Stdio::null()
        })
        // The helper's fire message must land in the same place the in-process
        // watchdog's message would have gone.
        .stderr(std::process::Stdio::inherit())
        .spawn()
}

#[derive(Clone)]
struct ExternalWatchdogController {
    sender: std::sync::mpsc::SyncSender<ExternalWatchdogWriteRequest>,
    hard_stop: CanonicalMonotonicInstant,
    publication_acks: std::sync::Arc<
        std::sync::Mutex<std::sync::mpsc::Receiver<Option<CanonicalMonotonicInstant>>>,
    >,
}

#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
enum ExternalWatchdogWriteRequest {
    FireNow,
    PublicationCommit {
        prepare_ack_deadline: CanonicalMonotonicInstant,
    },
    PublicationFinalize {
        hard_stop: CanonicalMonotonicInstant,
        write_observed_before_h: std::sync::mpsc::SyncSender<bool>,
    },
}

impl ExternalWatchdogController {
    fn record_publication_commit(&self) -> bool {
        self.record_publication_commit_inner(|| {})
    }

    #[cfg(test)]
    #[cfg_attr(
        not(unix),
        allow(dead_code, reason = "the external watchdog is Unix-only")
    )]
    fn record_publication_commit_with_boundary_fault<F>(&self, before_finalize_enqueue: F) -> bool
    where
        F: FnOnce(),
    {
        self.record_publication_commit_inner(before_finalize_enqueue)
    }

    fn record_publication_commit_inner<F>(&self, before_finalize_enqueue: F) -> bool
    where
        F: FnOnce(),
    {
        let prepare_ack_deadline = safenlp_short_prepare_ack_deadline(self.hard_stop);
        if !prepare_ack_deadline.is_strictly_future() {
            return false;
        }
        if self
            .sender
            .try_send(ExternalWatchdogWriteRequest::PublicationCommit {
                prepare_ack_deadline,
            })
            .is_err()
        {
            return false;
        }

        let Some(remaining) = prepare_ack_deadline
            .remaining()
            .filter(|remaining| !remaining.is_zero())
        else {
            return false;
        };
        let Ok(receiver) = self.publication_acks.lock() else {
            return false;
        };
        let prepare_acknowledged = match receiver.recv_timeout(remaining) {
            Ok(Some(received_at)) => {
                // The ACK reader timestamps receipt in the parent. Requiring
                // both that timestamp and this return path to precede the
                // cutoff prevents a queued/stale ACK from becoming retroactive.
                received_at < prepare_ack_deadline && prepare_ack_deadline.is_strictly_future()
            }
            Ok(None) | Err(_) => false,
        };
        drop(receiver);
        if !prepare_acknowledged {
            return false;
        }

        // These checks minimize late queue traffic, but no userspace
        // check→send sequence is atomic with H. The helper's canonical
        // receive timestamp is the sole authority if this thread is preempted
        // in the final gap below.
        if !self.hard_stop.is_strictly_future() {
            return false;
        }
        let (write_observed_before_h, write_observed_before_h_rx) =
            std::sync::mpsc::sync_channel(1);
        if !self.hard_stop.is_strictly_future() {
            return false;
        }
        before_finalize_enqueue();
        if self
            .sender
            .try_send(ExternalWatchdogWriteRequest::PublicationFinalize {
                hard_stop: self.hard_stop,
                write_observed_before_h,
            })
            .is_err()
        {
            return false;
        }
        let Some(remaining) = self
            .hard_stop
            .remaining()
            .filter(|remaining| !remaining.is_zero())
        else {
            return false;
        };
        write_observed_before_h_rx
            .recv_timeout(remaining)
            .is_ok_and(|observed| observed && self.hard_stop.is_strictly_future())
    }

    fn request_immediate_fire(&self) -> bool {
        self.sender
            .try_send(ExternalWatchdogWriteRequest::FireNow)
            .is_ok()
    }
}

#[cfg(all(unix, test))]
fn write_short_watchdog_request_with_boundary_fault<W, F>(
    writer: &mut W,
    request: ExternalWatchdogWriteRequest,
    before_finalize_write: F,
) -> bool
where
    W: std::io::Write + std::os::fd::AsFd,
    F: FnOnce(),
{
    write_short_watchdog_request_inner(writer, request, before_finalize_write)
}

#[cfg(unix)]
fn write_short_watchdog_request_inner<W, F>(
    writer: &mut W,
    request: ExternalWatchdogWriteRequest,
    before_finalize_write: F,
) -> bool
where
    W: std::io::Write + std::os::fd::AsFd,
    F: FnOnce(),
{
    match request {
        ExternalWatchdogWriteRequest::FireNow => {
            writer.write_all(EXTERNAL_WATCHDOG_FIRE_REQUEST).is_ok()
        }
        ExternalWatchdogWriteRequest::PublicationCommit {
            prepare_ack_deadline,
        } => {
            if !prepare_ack_deadline.is_strictly_future() {
                return true;
            }
            writer
                .write_all(EXTERNAL_WATCHDOG_PUBLICATION_COMMIT)
                .is_ok()
        }
        ExternalWatchdogWriteRequest::PublicationFinalize {
            hard_stop,
            write_observed_before_h,
        } => {
            // This best-effort check avoids a known-late syscall. It cannot
            // prevent scheduler preemption in the final check→write gap, so a
            // physically late P is allowed to reach the helper and is rejected
            // there by its authoritative canonical receive timestamp.
            if !hard_stop.is_strictly_future() {
                let _ = write_observed_before_h.send(false);
                return true;
            }
            before_finalize_write();
            let write_succeeded =
                rustix::io::write(writer.as_fd(), EXTERNAL_WATCHDOG_PUBLICATION_FINALIZE) == Ok(1);
            let timely_observation =
                canonical_monotonic_now().is_some_and(|written_at| written_at < hard_stop);
            let _ = write_observed_before_h.send(write_succeeded && timely_observation);
            write_succeeded
        }
    }
}

#[cfg(unix)]
fn forward_short_watchdog_acknowledgements<R>(
    mut acknowledgement_reader: R,
    publication_ack_tx: std::sync::mpsc::SyncSender<Option<CanonicalMonotonicInstant>>,
) where
    R: std::io::Read,
{
    let mut response = [0u8; 64];
    loop {
        match acknowledgement_reader.read(&mut response) {
            Ok(0) => return,
            Ok(read) => {
                for byte in &response[..read] {
                    if *byte == EXTERNAL_WATCHDOG_PUBLICATION_ACK
                        && publication_ack_tx.send(canonical_monotonic_now()).is_err()
                    {
                        return;
                    }
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
            Err(_) => return,
        }
    }
}

#[cfg(unix)]
fn run_short_watchdog_writer<W>(
    writer: W,
    receiver: std::sync::mpsc::Receiver<ExternalWatchdogWriteRequest>,
) where
    W: std::io::Write + std::os::fd::AsFd,
{
    run_short_watchdog_writer_inner(writer, receiver, || {});
}

#[cfg(all(unix, test))]
fn run_short_watchdog_writer_with_boundary_fault<W, F>(
    writer: W,
    receiver: std::sync::mpsc::Receiver<ExternalWatchdogWriteRequest>,
    before_finalize_write: F,
) where
    W: std::io::Write + std::os::fd::AsFd,
    F: FnMut(),
{
    run_short_watchdog_writer_inner(writer, receiver, before_finalize_write);
}

#[cfg(unix)]
fn run_short_watchdog_writer_inner<W, F>(
    mut writer: W,
    receiver: std::sync::mpsc::Receiver<ExternalWatchdogWriteRequest>,
    mut before_finalize_write: F,
) where
    W: std::io::Write + std::os::fd::AsFd,
    F: FnMut(),
{
    while let Ok(request) = receiver.recv() {
        if !write_short_watchdog_request_inner(&mut writer, request, || {
            before_finalize_write();
        }) {
            break;
        }
    }
}

/// Split the short-route helper control pipe into a non-blocking command queue
/// and an outer lifetime lease. The leaked lease is intentional: the kernel
/// closes it only when the verifier process actually exits, so returning from
/// the publication coordinator cannot retire the helper early.
#[cfg(unix)]
fn retain_short_watchdog_until_process_exit(
    mut child: std::process::Child,
    hard_stop: CanonicalMonotonicInstant,
) -> std::io::Result<ExternalWatchdogController> {
    use std::os::fd::AsFd;

    let lifetime_lease = child
        .stdin
        .take()
        .ok_or_else(|| std::io::Error::other("watchdog child had no piped stdin"))?;
    let acknowledgement_reader = child
        .stdout
        .take()
        .ok_or_else(|| std::io::Error::other("short watchdog child had no ACK pipe"))?;
    let writer_fd = lifetime_lease.as_fd().try_clone_to_owned()?;
    let writer = fs::File::from(writer_fd);
    let (sender, receiver) = std::sync::mpsc::sync_channel(4);
    let (publication_ack_tx, publication_ack_rx) = std::sync::mpsc::sync_channel(4);
    std::thread::Builder::new()
        .name("vnncomp-watchdog-ack".to_owned())
        .spawn(move || {
            forward_short_watchdog_acknowledgements(acknowledgement_reader, publication_ack_tx);
        })?;
    std::thread::Builder::new()
        .name("vnncomp-watchdog-control".to_owned())
        .spawn(move || run_short_watchdog_writer(writer, receiver))?;

    // This is the main-owned watchdog lease. Unlike the coordinator-owned
    // writer in the rejected design, it survives terminal publication and all
    // Rust returns. The OS closes it at actual process exit.
    std::mem::forget(lifetime_lease);
    let _ = std::thread::Builder::new()
        .name("vnncomp-watchdog-reaper".to_owned())
        .spawn(move || {
            let _ = child.wait();
        });
    Ok(ExternalWatchdogController {
        sender,
        hard_stop,
        publication_acks: std::sync::Arc::new(std::sync::Mutex::new(publication_ack_rx)),
    })
}

#[cfg(unix)]
fn spawn_and_retain_short_watchdog(
    results_file: &Path,
    hard_stop: CanonicalMonotonicInstant,
) -> std::io::Result<ExternalWatchdogController> {
    // One argument supplies both consumers: the exact H serialized into the
    // helper argv is also stored in the controller and every writer request.
    let child = spawn_external_watchdog(
        results_file,
        parent_anchored_watchdog_deadline(hard_stop),
        ExternalWatchdogResultPolicy::PreserveAcknowledged,
    )?;
    retain_short_watchdog_until_process_exit(child, hard_stop)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
enum ExternalWatchdogControl {
    Retire,
    FireNow,
    /// Hard-stop now, but do NOT touch RESULTS_FILE: the parent published a
    /// decided verdict before its own deadline (#watchdog-verdict-overwrite).
    FirePreservingVerdict,
    PublicationCommitRequested {
        received_at: Option<CanonicalMonotonicInstant>,
    },
    PublicationFinalizeRequested {
        received_at: Option<CanonicalMonotonicInstant>,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
enum ShortWatchdogPublicationState {
    Unacknowledged,
    Prepared,
    Finalized,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
enum ExternalWatchdogResultPolicy {
    CommitTimeout,
    PreserveAcknowledged,
}

/// Exact historical/default-off watchdog loop from the pre-experiment
/// baseline. Keep this separate from the short protocol so an unset gate or
/// explicit `0` retains the original reader, relative clock, timeout commit,
/// `kill(1)`, and retirement behavior.
fn serve_historical_external_watchdog_loop<R>(
    results_file: PathBuf,
    fire_after_secs: u64,
    parent_pid: u32,
    mut control: R,
) -> Result<()>
where
    R: std::io::Read + Send + 'static,
{
    use std::sync::mpsc::{sync_channel, RecvTimeoutError};

    let (control_tx, control_rx) = sync_channel(1);
    std::thread::spawn(move || {
        let mut request = [0u8; 64];
        let event = loop {
            match control.read(&mut request) {
                Ok(0) => break ExternalWatchdogControl::Retire,
                // #watchdog-verdict-overwrite: the parent distinguishes the two
                // hard-stop reasons by BYTE. Anything that is not the explicit
                // preserve request keeps the historical unconditional timeout
                // commit, so an unknown/legacy byte can never silently preserve
                // a post-deadline verdict.
                Ok(read)
                    if request[..read].contains(&EXTERNAL_WATCHDOG_PRESERVE_FIRE_REQUEST[0]) =>
                {
                    break ExternalWatchdogControl::FirePreservingVerdict;
                }
                Ok(_) => break ExternalWatchdogControl::FireNow,
                Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
                Err(_) => break ExternalWatchdogControl::Retire,
            }
        };
        let _ = control_tx.send(event);
    });

    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(fire_after_secs);
    let mut preserve_published_verdict = false;
    let immediate = loop {
        let now = std::time::Instant::now();
        if now >= deadline {
            break false;
        }
        #[cfg(target_os = "linux")]
        if !Path::new(&format!("/proc/{parent_pid}")).exists() {
            return Ok(());
        }
        match control_rx.recv_timeout(std::cmp::min(
            deadline - now,
            std::time::Duration::from_secs(1),
        )) {
            Ok(ExternalWatchdogControl::Retire) => return Ok(()),
            Ok(ExternalWatchdogControl::FirePreservingVerdict) => {
                preserve_published_verdict = true;
                break true;
            }
            Ok(ExternalWatchdogControl::FireNow)
            | Ok(ExternalWatchdogControl::PublicationCommitRequested { .. })
            | Ok(ExternalWatchdogControl::PublicationFinalizeRequested { .. }) => break true,
            Err(RecvTimeoutError::Timeout) => {}
            Err(RecvTimeoutError::Disconnected) => return Ok(()),
        }
    };

    // #watchdog-verdict-overwrite: `preserve` means the parent's in-process
    // watchdog found a verdict it had ALREADY published before its own deadline
    // and declined to replace it. The hard stop below still happens — only the
    // verdict survives. Every other path is byte-for-byte historical: an
    // ordinary immediate fire still seals `timeout` over a verdict that raced
    // in after the deadline, and a helper firing on its own timer still
    // replaces only a placeholder.
    let write_timeout = !preserve_published_verdict
        && (immediate
            || match fs::read_to_string(&results_file) {
                Ok(contents) => contents.lines().next().is_none_or(|line| line == "unknown"),
                Err(_) => true,
            });
    let commit_error = if write_timeout {
        commit_timeout_result_checked(&results_file, "extwatchdog.tmp").err()
    } else {
        None
    };

    let status = std::process::Command::new("kill")
        .arg("-KILL")
        .arg(parent_pid.to_string())
        .status()
        .with_context(|| format!("external watchdog failed to invoke kill for pid {parent_pid}"))?;
    if !status.success() {
        return Err(anyhow!(
            "external watchdog kill -KILL {parent_pid} exited with {status}"
        ));
    }
    if let Some(error) = commit_error {
        eprintln!(
            "vnncomp external watchdog: WARNING: could not confirm timeout in {} before \
             hard-stopping pid {parent_pid}: {error}; preserving deadline enforcement",
            results_file.display()
        );
    }
    if immediate {
        eprintln!(
            "vnncomp external watchdog: in-process deadline helper requested an immediate hard \
             stop; SIGKILLed verifier pid {parent_pid} without running process exit handlers"
        );
    } else {
        eprintln!(
            "vnncomp external watchdog: {fire_after_secs}s (scored budget + grace) exceeded with \
             the verifier process still alive and its in-process watchdog silent — process-wide \
             wedge; SIGKILLed verifier pid {parent_pid}"
        );
    }
    Ok(())
}

/// Parent-anchored short protocol. `C` installs Prepared before the raw ACK
/// syscall; only a later, ordered `P` installs Finalized.
#[cfg(unix)]
fn serve_short_external_watchdog_loop<R, W>(
    results_file: PathBuf,
    deadline_spec: ExternalWatchdogDeadline,
    parent_pid: u32,
    control: R,
    publication_acknowledgement: W,
) -> Result<()>
where
    R: std::io::Read + Send + 'static,
    W: std::os::fd::AsFd,
{
    serve_short_external_watchdog_loop_with_fault(
        results_file,
        deadline_spec,
        parent_pid,
        control,
        publication_acknowledgement,
        || {},
    )
}

#[cfg(unix)]
fn serve_short_external_watchdog_loop_with_fault<R, W, F>(
    results_file: PathBuf,
    deadline_spec: ExternalWatchdogDeadline,
    parent_pid: u32,
    mut control: R,
    publication_acknowledgement: W,
    after_ack_visible: F,
) -> Result<()>
where
    R: std::io::Read + Send + 'static,
    W: std::os::fd::AsFd,
    F: FnOnce(),
{
    let (control_tx, control_rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let mut request = [0u8; 64];
        loop {
            match control.read(&mut request) {
                Ok(0) => {
                    let _ = control_tx.send(ExternalWatchdogControl::Retire);
                    return;
                }
                Ok(read) => {
                    // Timestamp raw receipt in the helper on the exact
                    // process-independent clock carried in argv. If the clock
                    // cannot be sampled, C/P are non-authoritative.
                    let received_at = canonical_monotonic_now();
                    for byte in &request[..read] {
                        let event = match *byte {
                            byte if byte == EXTERNAL_WATCHDOG_PUBLICATION_COMMIT[0] => {
                                ExternalWatchdogControl::PublicationCommitRequested { received_at }
                            }
                            byte if byte == EXTERNAL_WATCHDOG_PUBLICATION_FINALIZE[0] => {
                                ExternalWatchdogControl::PublicationFinalizeRequested {
                                    received_at,
                                }
                            }
                            _ => ExternalWatchdogControl::FireNow,
                        };
                        if control_tx.send(event).is_err()
                            || event == ExternalWatchdogControl::FireNow
                        {
                            return;
                        }
                    }
                }
                Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
                Err(_) => {
                    let _ = control_tx.send(ExternalWatchdogControl::Retire);
                    return;
                }
            }
        }
    });

    serve_short_external_watchdog_events(
        results_file,
        deadline_spec,
        parent_pid,
        control_rx,
        &publication_acknowledgement,
        after_ack_visible,
    )
}

#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
fn retire_short_external_watchdog(
    results_file: &Path,
    publication_state: ShortWatchdogPublicationState,
) -> Result<()> {
    if publication_state != ShortWatchdogPublicationState::Finalized {
        commit_unknown_result_checked(results_file, "extwatchdog-unknown.tmp").with_context(
            || {
                format!(
                    "short-grace watchdog could not seal unacknowledged result {} on parent exit",
                    results_file.display()
                )
            },
        )?;
    }
    Ok(())
}

#[cfg(unix)]
fn hard_kill_parent(parent_pid: u32) -> Result<bool> {
    let raw_pid = i32::try_from(parent_pid)
        .map_err(|_| anyhow!("external watchdog parent pid {parent_pid} exceeds i32"))?;
    let pid = rustix::process::Pid::from_raw(raw_pid)
        .ok_or_else(|| anyhow!("external watchdog parent pid must be nonzero"))?;
    match rustix::process::kill_process(pid, rustix::process::Signal::KILL) {
        Ok(()) => Ok(true),
        // The in-process fail-safe may have aborted the parent immediately
        // after queuing F. The helper still seals an unacknowledged result.
        Err(error) if error == rustix::io::Errno::SRCH => Ok(false),
        Err(error) => Err(anyhow!(
            "external watchdog failed to SIGKILL pid {parent_pid}: {error}"
        )),
    }
}

/// Non-Unix fallback. Every caller sits behind `#[cfg(unix)]`, so nothing
/// reaches it here — it exists to keep this arm type-checked rather than to
/// run. See the subsystem note at the top of the watchdog section for why that
/// is an `allow` and not a `#[cfg]` gate.
#[cfg(not(unix))]
#[allow(dead_code, reason = "the external watchdog is Unix-only")]
fn hard_kill_parent(parent_pid: u32) -> Result<bool> {
    let status = std::process::Command::new("kill")
        .arg("-KILL")
        .arg(parent_pid.to_string())
        .status()
        .with_context(|| format!("external watchdog failed to invoke kill for pid {parent_pid}"))?;
    if status.success() {
        Ok(true)
    } else {
        Err(anyhow!(
            "external watchdog kill -KILL {parent_pid} exited with {status}"
        ))
    }
}

#[cfg(unix)]
fn apply_short_watchdog_control<W, F>(
    event: ExternalWatchdogControl,
    publication_state: &mut ShortWatchdogPublicationState,
    prepare_ack_deadline: CanonicalMonotonicInstant,
    hard_stop: CanonicalMonotonicInstant,
    publication_acknowledgement: &W,
    after_ack_visible: &mut Option<F>,
) where
    W: std::os::fd::AsFd,
    F: FnOnce(),
{
    match event {
        ExternalWatchdogControl::PublicationCommitRequested { received_at } => {
            if *publication_state == ShortWatchdogPublicationState::Unacknowledged
                && received_at.is_some_and(|received_at| received_at < prepare_ack_deadline)
            {
                // Install Prepared BEFORE the one-byte raw pipe write. An ACK
                // can therefore never describe state that still needs
                // post-write installation. On a definite zero/error write,
                // roll back because no ACK byte became visible.
                *publication_state = ShortWatchdogPublicationState::Prepared;
                let returned = match rustix::io::write(
                    publication_acknowledgement.as_fd(),
                    &[EXTERNAL_WATCHDOG_PUBLICATION_ACK],
                ) {
                    Ok(1) => {
                        if let Some(fault) = after_ack_visible.take() {
                            // Deterministic audit seam: this is the first
                            // action after the successful raw syscall.
                            fault();
                        }
                        true
                    }
                    Ok(_) | Err(_) => false,
                };
                if !returned {
                    *publication_state = ShortWatchdogPublicationState::Unacknowledged;
                }
            }
        }
        ExternalWatchdogControl::PublicationFinalizeRequested { received_at } => {
            if *publication_state == ShortWatchdogPublicationState::Prepared
                && received_at.is_some_and(|received_at| received_at < hard_stop)
            {
                *publication_state = ShortWatchdogPublicationState::Finalized;
            }
        }
        // `FirePreservingVerdict` belongs to the historical protocol's reader
        // (#watchdog-verdict-overwrite); the short protocol never emits it, and
        // like `FireNow` it carries no publication-state transition.
        ExternalWatchdogControl::Retire
        | ExternalWatchdogControl::FireNow
        | ExternalWatchdogControl::FirePreservingVerdict => {}
    }
}

#[cfg(unix)]
fn serve_short_external_watchdog_events<W, F>(
    results_file: PathBuf,
    deadline_spec: ExternalWatchdogDeadline,
    parent_pid: u32,
    control_rx: std::sync::mpsc::Receiver<ExternalWatchdogControl>,
    publication_acknowledgement: &W,
    after_ack_visible: F,
) -> Result<()>
where
    W: std::os::fd::AsFd,
    F: FnOnce(),
{
    use std::sync::mpsc::{RecvTimeoutError, TryRecvError};

    let hard_stop = resolve_short_external_watchdog_deadline(deadline_spec);
    let prepare_ack_deadline = safenlp_short_prepare_ack_deadline(hard_stop);
    let mut publication_state = ShortWatchdogPublicationState::Unacknowledged;
    let mut after_ack_visible = Some(after_ack_visible);

    let immediate = 'watch: loop {
        // Preserve pipe order across adversarial scheduling: process every
        // already-forwarded C/P/EOF record before declaring the clock expired.
        loop {
            match control_rx.try_recv() {
                Ok(ExternalWatchdogControl::Retire) => {
                    return retire_short_external_watchdog(&results_file, publication_state);
                }
                Ok(ExternalWatchdogControl::FireNow) => break 'watch true,
                Ok(event) => apply_short_watchdog_control(
                    event,
                    &mut publication_state,
                    prepare_ack_deadline,
                    hard_stop,
                    publication_acknowledgement,
                    &mut after_ack_visible,
                ),
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => {
                    return retire_short_external_watchdog(&results_file, publication_state);
                }
            }
        }

        let Some(remaining) = hard_stop.remaining() else {
            break 'watch false;
        };
        if remaining.is_zero() {
            break 'watch false;
        }
        // Deliberately rely on the process-lifetime pipe lease. A /proc check
        // can observe parent disappearance before the reader forwards an
        // earlier C byte, violating control-pipe order at parent exit.
        match control_rx.recv_timeout(std::cmp::min(remaining, std::time::Duration::from_secs(1))) {
            Ok(ExternalWatchdogControl::Retire) => {
                return retire_short_external_watchdog(&results_file, publication_state);
            }
            Ok(ExternalWatchdogControl::FireNow) => break 'watch true,
            Ok(event) => apply_short_watchdog_control(
                event,
                &mut publication_state,
                prepare_ack_deadline,
                hard_stop,
                publication_acknowledgement,
                &mut after_ack_visible,
            ),
            Err(RecvTimeoutError::Timeout) => {}
            Err(RecvTimeoutError::Disconnected) => {
                return retire_short_external_watchdog(&results_file, publication_state);
            }
        }
    };

    // This is one safe syscall through rustix on Unix, with no child process
    // and no unbounded `Command::status()` wait.
    let kill_delivered = hard_kill_parent(parent_pid)?;
    if publication_state == ShortWatchdogPublicationState::Prepared {
        // SIGKILL closes the main-owned lease. Drain the reader's ordered
        // kernel-pipe tail so a P written before parent acceptance/exit cannot
        // be lost merely because this helper was paused after returning ACK.
        // This starts only after successful SIGKILL/ESRCH: kernel teardown
        // guarantees EOF, while channel disconnect is the reader fail-safe.
        loop {
            match control_rx.recv() {
                Ok(ExternalWatchdogControl::Retire) | Err(std::sync::mpsc::RecvError) => break,
                Ok(event) => apply_short_watchdog_control(
                    event,
                    &mut publication_state,
                    prepare_ack_deadline,
                    hard_stop,
                    publication_acknowledgement,
                    &mut after_ack_visible,
                ),
            }
        }
    }
    let unknown_commit_error = if publication_state != ShortWatchdogPublicationState::Finalized {
        // SIGKILL prevents any further parent userspace write. Sealing after
        // signal delivery therefore erases a rename that crossed the cutoff
        // without receiving an explicit pre-cutoff acknowledgement.
        commit_unknown_result_checked(&results_file, "extwatchdog-unknown.tmp").err()
    } else {
        None
    };

    if let Some(error) = unknown_commit_error {
        eprintln!(
            "vnncomp external watchdog: WARNING: could not seal unacknowledged short-grace \
             publication in {} after hard-stopping pid {parent_pid}: {error}",
            results_file.display()
        );
    }
    if immediate {
        eprintln!(
            "vnncomp external watchdog: in-process deadline helper requested an immediate hard \
             stop; {} verifier pid {parent_pid} without running process exit handlers",
            if kill_delivered {
                "SIGKILLed"
            } else {
                "found already-exited"
            }
        );
    } else {
        eprintln!(
            "vnncomp external watchdog: parent-anchored deadline exceeded with the verifier \
             process still alive — process-wide wedge; {} verifier pid {parent_pid}",
            if kill_delivered {
                "SIGKILLed"
            } else {
                "found already-exited"
            }
        );
    }
    Ok(())
}

/// Serve the hidden `ny __vnncomp-watchdog <results_file> <fire_after_secs>
/// <parent_pid>` subprocess (see the spawn site in `handle_vnncomp_command`
/// for the full contract). Runs with NO GPU/ORT/preset/logging setup: its only
/// job is to outlive a wedged parent verifier and enforce the scored deadline
/// from a separate address space.
///
/// Retire paths:
/// - stdin EOF: the parent actually exited (normal return, watchdog, panic,
///   signal); the short protocol seals `unknown` unless ordered C/ACK/P
///   preparation and finalization completed first;
/// - the parent pid disappeared (the same conservative rule applies).
///
/// Fire paths:
/// - historical/default-off: preserve the existing checked-timeout contract;
/// - short-grace: SIGKILL first, then preserve only a result carrying an
///   early child ACK whose later P was received by the helper strictly before
///   the exact shared monotonic H; otherwise seal sound `unknown`;
/// - direct SIGKILL is one bounded syscall, so no `kill(1)` subprocess can
///   extend the deadline.
pub(crate) fn serve_external_watchdog() -> Result<()> {
    let args: Vec<std::ffi::OsString> = std::env::args_os().skip(2).collect();
    match args.as_slice() {
        [results_file, fire_after_secs, parent_pid] => {
            let results_file = PathBuf::from(results_file);
            let fire_after_secs: u64 =
                fire_after_secs.to_string_lossy().parse().map_err(|err| {
                    anyhow!("{EXTERNAL_WATCHDOG_SUBCOMMAND}: bad fire_after_secs: {err}")
                })?;
            let parent_pid: u32 = parent_pid
                .to_string_lossy()
                .parse()
                .map_err(|err| anyhow!("{EXTERNAL_WATCHDOG_SUBCOMMAND}: bad parent_pid: {err}"))?;
            serve_historical_external_watchdog_loop(
                results_file,
                fire_after_secs,
                parent_pid,
                std::io::stdin(),
            )
        }
        [results_file, protocol, hard_stop_monotonic_nanos, parent_pid, policy]
            if protocol == OsStr::new(EXTERNAL_WATCHDOG_PARENT_ANCHORED_PROTOCOL)
                && policy == OsStr::new("preserve-acknowledged") =>
        {
            let results_file = PathBuf::from(results_file);
            let hard_stop = parse_canonical_monotonic_instant(hard_stop_monotonic_nanos)?;
            let parent_pid: u32 = parent_pid
                .to_string_lossy()
                .parse()
                .map_err(|err| anyhow!("{EXTERNAL_WATCHDOG_SUBCOMMAND}: bad parent_pid: {err}"))?;
            #[cfg(unix)]
            {
                serve_short_external_watchdog_loop(
                    results_file,
                    ExternalWatchdogDeadline::ParentAnchoredMonotonic { hard_stop },
                    parent_pid,
                    std::io::stdin(),
                    std::io::stdout(),
                )
            }
            #[cfg(not(unix))]
            {
                let _ = (results_file, hard_stop, parent_pid);
                Err(anyhow!(
                    "{EXTERNAL_WATCHDOG_SUBCOMMAND}: parent-anchored short watchdog protocol \
                     requires Unix"
                ))
            }
        }
        _ => Err(anyhow!(
            "{EXTERNAL_WATCHDOG_SUBCOMMAND}: expected <results_file> <fire_after_secs> \
             <parent_pid>, or <results_file> {EXTERNAL_WATCHDOG_PARENT_ANCHORED_PROTOCOL} \
             <hard_stop_monotonic_nanos> <parent_pid> preserve-acknowledged"
        )),
    }
}

/// End an over-budget Unix verifier without `std::process::exit`.
///
/// Rust's Unix `process::exit` calls libc `exit`, which runs `atexit` handlers
/// and ELF shared-object fini sections while other verifier threads are still
/// active. The r7 cGAN scorecard hit SIGSEGV exactly in that window: a detached
/// AY worker and the CUDA replay were live when the watchdog called `exit(0)`.
/// Ask the already-clean helper process to SIGKILL us instead, so no parent
/// exit handler or foreign-library teardown runs concurrently. If the helper
/// is unavailable, `abort` is the fail-safe hard stop: it also skips exit
/// handlers. The timeout commit has already been attempted, and the sound
/// pre-written `unknown` remains if the results path is unwritable.
#[cfg_attr(
    not(unix),
    allow(dead_code, reason = "the external watchdog is Unix-only")
)]
fn historical_watchdog_abort_delay_after_request<W: std::io::Write>(
    control: Option<W>,
    request: &[u8],
) -> Option<std::time::Duration> {
    let mut control = control?;
    if control.write_all(request).is_err() {
        return None;
    }
    drop(control);
    Some(std::time::Duration::from_secs(
        EXTERNAL_WATCHDOG_EXTRA_GRACE_SECS,
    ))
}

#[cfg(unix)]
fn hard_stop_from_in_process_watchdog(
    external_watchdog_control: Option<std::process::ChildStdin>,
    request: &[u8],
) -> ! {
    if let Some(delay) =
        historical_watchdog_abort_delay_after_request(external_watchdog_control, request)
    {
        // This is intentionally the exact baseline/default-off fallback:
        // normally the helper kills us immediately, while abort remains a
        // bounded last resort if the helper fails after consuming F.
        std::thread::sleep(delay);
    }
    std::process::abort()
}

#[cfg(not(unix))]
fn hard_stop_from_in_process_watchdog(
    _external_watchdog_control: Option<std::process::ChildStdin>,
    _request: &[u8],
) -> ! {
    std::process::exit(0)
}

// Keep the historical non-Unix termination contract type-checked even though
// Unix CI cannot execute it. In particular, do not let the Unix-only short
// protocol pull `AsFd` or raw-syscall types into this fallback build.
#[cfg(not(unix))]
const _: fn(Option<std::process::ChildStdin>, &[u8]) -> ! = hard_stop_from_in_process_watchdog;

fn hard_kill_current_process() -> ! {
    #[cfg(unix)]
    {
        if let Ok(raw_pid) = i32::try_from(std::process::id()) {
            if let Some(pid) = rustix::process::Pid::from_raw(raw_pid) {
                let _ = rustix::process::kill_process(pid, rustix::process::Signal::KILL);
            }
        }
    }
    // A direct SIGKILL normally never returns. `abort` is the no-exit-handler
    // fail-safe if PID conversion or signal delivery unexpectedly fails.
    std::process::abort()
}

#[cfg(unix)]
fn run_short_grace_hard_stop<F>(hard_stop_deadline: CanonicalMonotonicInstant, hard_stop: F)
where
    F: FnOnce(),
{
    // Clock/conversion failure is fail-closed: zero delay preserves the
    // pre-written unknown rather than extending the scored budget.
    std::thread::sleep(hard_stop_deadline.remaining().unwrap_or_default());
    hard_stop();
}

#[cfg(not(unix))]
fn run_short_grace_hard_stop<F>(deadline: std::time::Instant, hard_stop: F)
where
    F: FnOnce(),
{
    std::thread::sleep(deadline.saturating_duration_since(std::time::Instant::now()));
    hard_stop();
}

/// The short route has no post-notification wait. Queueing F is non-blocking;
/// `abort` is the immediate, process-local fail-safe if the helper or its
/// control writer is unavailable. The external helper independently owns the
/// same canonical monotonic deadline.
fn hard_stop_short_grace(external_watchdog: Option<ExternalWatchdogController>) -> ! {
    if let Some(watchdog) = external_watchdog {
        let _ = watchdog.request_immediate_fire();
    }
    hard_kill_current_process()
}

/// #batched-bab observability (dark, `NY_BETA_GPU_PROBE=1`): the `[wide-lane]`
/// readout.
///
/// The published count alone cannot say whether a lane that fired 6 times covered
/// 6 of 6 candidate batches or 6 of 600 — so print the DENOMINATOR and the decline
/// tally beside it (`ny_core::wide_lane_telemetry`). Both are process-global and
/// monotonic, so this renders the same totals from either completion site; call it
/// from BOTH (the timing-out one is the path a scored deep row takes).
///
/// Print-only: reading the counters cannot change a verdict, a bound, or a route.
fn emit_wide_lane_readout() {
    let published = ny_gpu::wide_resnet_batched_taken_count();
    eprintln!("[wide-lane] domain-stacked GPU CROWN published {published} time(s) this run");
    eprintln!(
        "[wide-lane] {}",
        ny_core::wide_lane_telemetry::format_wide_lane_tally(published)
    );
}

/// Project the one typed solver research gate that remains preset-deliverable
/// into the run's early lever receipt.
///
/// The runtime bridge is installed later by `handle_beta_crown_command`; this
/// projection uses the same immutable preset snapshot so an armed scored run
/// cannot execute with a receipt that incorrectly records the dark default.
/// `NY_CONST_MATMUL_INTERVAL` is deliberately absent: its axis is Unsafe +
/// EnvOnly and semantic validation rejects the retired typed field.
fn solver_preset_gate_config_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    if std::ptr::eq(
        decl,
        &raw const ny_levers::decls::dark_probes::JOINT_BILINEAR_QUAD,
    ) {
        return loaded
            .solver
            .joint_bilinear_quad
            .map(ny_levers::LeverValue::Bool);
    }
    None
}

/// `#auto-alloc` — project the PER-INSTANCE root allocation into the frozen
/// lever set, so the receipt records the values the lane actually ran.
///
/// WHY THIS LAYER AND NOT THE RESOLVED POLICY. Mutating
/// `MarginRowRuntimePolicy` after `from_levers` reaches the lane correctly and
/// leaves the RECEIPT wrong: `<results>.res.flight.json` records
/// `NY_MARGIN_ROW_INTERM_ALPHA` with `"source": "config"` and the yaml's value,
/// so a run would report `interm_alpha=2` while proving with `0`. In a campaign
/// where attribution rests on receipts that is not cosmetic — it is the exact
/// generator of a null nobody can tell apart from a VOID. Projecting here means
/// one source of truth for the lane, the receipt and the ratchets alike.
///
/// Placed BEFORE `preset_delivered_config_value` in the closure so it outranks
/// the yaml for the two decls it owns, and returns `None` for every other decl
/// so nothing else changes. It can only ever narrow an already-authorised
/// value (see `auto_alloc::decide`), so outranking the yaml cannot spend budget
/// the category did not grant.
#[expect(
    clippy::option_option,
    reason = "the lever projector protocol of `materialize_levers`: outer `None` = not this \
              projector's declaration, `Some(None)` = its declaration with no value (the \
              declaration default, never rediscovered by the generic projector), \
              `Some(Some(v))` = the value; see `margin_row_schedule_preset_config_value`"
)]
fn auto_alloc_config_value(
    decision: &ny_propagate::margin_row::auto_alloc::AutoAllocDecision,
    decl: &'static ny_levers::LeverDecl,
) -> Option<Option<ny_levers::LeverValue>> {
    use ny_levers::decls::margin_row::{MARGIN_ROW_BI_TOPK, MARGIN_ROW_INTERM_ALPHA};
    if !decision.applied {
        return None;
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_INTERM_ALPHA) {
        return Some(
            u64::try_from(decision.after.0)
                .ok()
                .map(ny_levers::LeverValue::U64),
        );
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_BI_TOPK) {
        return Some(
            u64::try_from(decision.after.1)
                .ok()
                .map(ny_levers::LeverValue::U64),
        );
    }
    None
}

/// Project the coupled margin-row lane scheduler from the validated typed
/// preset without round-tripping its `f32` fractions through JSON.
///
/// The outer `Option` identifies a scheduler declaration; the inner option is
/// its optional typed value. This distinction is load-bearing: an absent or
/// historically declined fraction must fall through to the declaration
/// default, and must not be rediscovered by the generic JSON projector as a
/// different `f64` value (or as an invalid config that suppresses the run).
// The three states are the point and collapsing them would lose one: outer
// `None` = this decl is not a margin-row schedule key at all (fall through to
// the generic projector); `Some(None)` = it IS one and the preset declines it,
// which must reach the declaration default WITHOUT the generic projector
// rediscovering some other value; `Some(Some(v))` = the preset supplies `v`.
#[expect(
    clippy::option_option,
    reason = "three load-bearing states (above); a two-state type would lose one"
)]
fn margin_row_schedule_preset_config_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<Option<ny_levers::LeverValue>> {
    use ny_levers::decls::margin_row::{
        MARGIN_ROW_ADAPTIVE_RELEASE_FRAC, MARGIN_ROW_ADAPTIVE_RESERVE, MARGIN_ROW_CONCURRENT,
        MARGIN_ROW_CONCURRENT_THREADS, MARGIN_ROW_EARLY_EXIT, MARGIN_ROW_RESERVE_MAX_FRAC,
        MARGIN_ROW_RESERVE_SECS, VERIFIER_THREADS,
    };

    let schedule = &loaded.margin_row;
    if std::ptr::eq(decl, &raw const MARGIN_ROW_RESERVE_SECS) {
        return Some(schedule.reserve_secs.map(ny_levers::LeverValue::U64));
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_ADAPTIVE_RESERVE) {
        return Some(schedule.adaptive_reserve.map(ny_levers::LeverValue::Bool));
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_RESERVE_MAX_FRAC) {
        return Some(schedule.reserve_max_frac.and_then(|value| {
            (value.is_finite() && value > 0.0 && value < 1.0)
                .then_some(ny_levers::LeverValue::F64(f64::from(value)))
        }));
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_ADAPTIVE_RELEASE_FRAC) {
        return Some(schedule.release_frac.and_then(|value| {
            (value.is_finite() && value > 0.0 && value < 1.0)
                .then_some(ny_levers::LeverValue::F64(f64::from(value)))
        }));
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_CONCURRENT) {
        return Some(schedule.concurrent.map(ny_levers::LeverValue::Bool));
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_EARLY_EXIT) {
        return Some(schedule.early_exit.map(ny_levers::LeverValue::Bool));
    }
    if std::ptr::eq(decl, &raw const VERIFIER_THREADS) {
        return Some(
            schedule
                .verifier_threads
                .and_then(|value| u64::try_from(value).ok())
                .map(ny_levers::LeverValue::U64),
        );
    }
    if std::ptr::eq(decl, &raw const MARGIN_ROW_CONCURRENT_THREADS) {
        return Some(
            schedule
                .concurrent_threads
                .and_then(|value| u64::try_from(value).ok())
                .map(ny_levers::LeverValue::U64),
        );
    }
    None
}

/// The relational route consumes exactly one value from its category preset.
/// Keep its receipt projection as narrow as its execution contract: projecting
/// the preset wholesale would claim that model/BaB fields this route bypasses
/// affected the run.
/// #cz-hybrid-budget — the budget the fall-through pipeline is handed after the
/// wired MetaRoom CZ lane has run.
///
/// # The defect
///
/// The lane was handed `instance_deadline - 5s` and the pipeline below was
/// never told what it spent. MEASURED on metaroom_2023 6cnn_ry_39_6
/// spec_idx_119 at its official 210 s budget: the lane consumed 188.7 s for
/// `proved_unsat=false, strictly_positive=0/19`, the internal verifier then
/// re-derived its own window from scratch (`[budget] graph-enter
/// total_s=148.000 elapsed_s=0.000`) with ~21 s actually left, overran, and
/// ny's own watchdog SIGKILLed it at 216 s — 6 s past the official budget, with
/// `[ny-box] END rc=137` and NO `Result:` line printed at all.
///
/// # The contract
///
/// The answer is NEVER greater than the instance's live remaining seconds, and
/// never greater than the original grant. An IDLE lane (every row the
/// two-basename allowlist does not match) hands the original grant through
/// untouched, which is what makes this byte-identical on every other row.
/// The 1 s floor keeps downstream `Duration` arithmetic well-formed; the
/// absolute `instance_deadline` still gates every phase below it.
#[cfg_attr(not(feature = "mip"), allow(dead_code))]
fn cz_hybrid_handoff_budget_secs(
    ny_timeout: u64,
    instance_remaining_s: f64,
    lane_engaged: bool,
) -> u64 {
    if !lane_engaged {
        return ny_timeout;
    }
    let remaining = if instance_remaining_s.is_finite() {
        instance_remaining_s.max(0.0)
    } else {
        0.0
    };
    (ny_timeout as f64).min(remaining).floor().max(1.0) as u64
}

fn relational_scored_wall_clamp_config_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    std::ptr::eq(
        decl,
        &raw const ny_levers::decls::dark_probes::SCORED_WALL_CLAMP,
    )
    .then_some(loaded.solver.scored_wall_clamp)
    .flatten()
    .map(ny_levers::LeverValue::Bool)
}

/// #router-r1: the relational route's projection of the router's two typed
/// modes (`router.mode`, `optimizer.mode`).
///
/// The relational route runs the router's own start site, so its
/// receipt-owning authority must carry the modes from the SAME frozen preset.
/// Without this projection the key parsed and validated and was then DROPPED
/// on every dual-network row: the frozen set resolved `off` from the default
/// layer, and that start site was reachable only through the Debug
/// environment variable, which a competition harness never exports. No
/// shipped yaml sets either key, so every shipped relational receipt is
/// unchanged.
fn relational_router_config_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    let token = if std::ptr::eq(decl, &raw const ny_levers::decls::router::ROUTER_MODE) {
        loaded.router.mode.map(ny_core::router::RouterMode::token)
    } else if std::ptr::eq(decl, &raw const ny_levers::decls::router::OPTIMIZER_MODE) {
        loaded
            .optimizer
            .mode
            .map(ny_core::router::OptimizerMode::token)
    } else {
        None
    };
    token
        .map(|token| ny_levers::LeverValue::Text(token.to_owned()))
        .or_else(|| relational_router_rule_value(loaded, decl))
        .or_else(|| relational_optimizer_rule_value(loaded, decl))
}

/// #router-r3: the relational route's projection of the `optimizer.rules.*`
/// switches (R3's four O-STOP rules and, since #router-r6, the four O-TRIAL
/// rules) and #router-r7's `optimizer.priors`, from the SAME frozen preset as
/// the two modes. No shipped yaml sets any of them, so every shipped
/// relational receipt is unchanged.
fn relational_optimizer_rule_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    use ny_levers::decls::router::{
        OPTIMIZER_PRIORS, OPTIMIZER_RULE_ATTACK_DEFER, OPTIMIZER_RULE_GOVERNOR,
        OPTIMIZER_RULE_IA_YIELD, OPTIMIZER_RULE_ROOT_ADMISSION,
        OPTIMIZER_RULE_TRIAL_ATTACK_HALVING, OPTIMIZER_RULE_TRIAL_LR_BACKOFF,
        OPTIMIZER_RULE_TRIAL_SPLIT_RESTART, OPTIMIZER_RULE_TRIAL_WIDTH,
    };
    let rules = &loaded.optimizer.rules;
    [
        (&OPTIMIZER_RULE_GOVERNOR, rules.governor),
        (&OPTIMIZER_RULE_IA_YIELD, rules.ia_yield),
        (&OPTIMIZER_RULE_ATTACK_DEFER, rules.attack_defer),
        (&OPTIMIZER_RULE_ROOT_ADMISSION, rules.root_admission),
        // #router-r6: the four O-TRIAL rules.
        (&OPTIMIZER_RULE_TRIAL_WIDTH, rules.trial_width),
        (&OPTIMIZER_RULE_TRIAL_LR_BACKOFF, rules.trial_lr_backoff),
        (
            &OPTIMIZER_RULE_TRIAL_SPLIT_RESTART,
            rules.trial_split_restart,
        ),
        (
            &OPTIMIZER_RULE_TRIAL_ATTACK_HALVING,
            rules.trial_attack_halving,
        ),
        // #router-r7: the offline-prior switch rides the same projection.
        (&OPTIMIZER_PRIORS, loaded.optimizer.priors),
    ]
    .into_iter()
    .find(|(candidate, _)| std::ptr::eq(*candidate, decl))
    .and_then(|(_, value)| value)
    .map(ny_levers::LeverValue::Bool)
}

/// #router-r2: the relational route's projection of the seven
/// `router.rules.*` switches, from the SAME frozen preset as the two modes.
/// No shipped yaml sets any of them, so every shipped relational receipt is
/// unchanged.
fn relational_router_rule_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    use ny_levers::decls::router::{
        ROUTER_RULE_ADMISSION, ROUTER_RULE_CAP_AUTHORITY, ROUTER_RULE_CONTRACTS,
        ROUTER_RULE_DERIVED_CAPS, ROUTER_RULE_FAR_HAND_ON, ROUTER_RULE_GAP_CONTRACT,
        ROUTER_RULE_HAND_ON, ROUTER_RULE_LEASE, ROUTER_RULE_PUBLISH_GRACE, ROUTER_RULE_ROUTE,
        ROUTER_RULE_TERMINAL,
    };
    let rules = &loaded.router.rules;
    [
        (&ROUTER_RULE_ADMISSION, rules.admission),
        (&ROUTER_RULE_CONTRACTS, rules.contracts),
        (&ROUTER_RULE_CAP_AUTHORITY, rules.cap_authority),
        (&ROUTER_RULE_TERMINAL, rules.terminal),
        (&ROUTER_RULE_HAND_ON, rules.hand_on),
        (&ROUTER_RULE_PUBLISH_GRACE, rules.publish_grace),
        (&ROUTER_RULE_DERIVED_CAPS, rules.derived_caps),
        // #router-r4: acting set 3.
        (&ROUTER_RULE_LEASE, rules.lease),
        (&ROUTER_RULE_FAR_HAND_ON, rules.far_hand_on),
        // #router-r5: acting set 4.
        (&ROUTER_RULE_ROUTE, rules.route),
        (&ROUTER_RULE_GAP_CONTRACT, rules.gap_contract),
    ]
    .into_iter()
    .find(|(candidate, _)| std::ptr::eq(*candidate, decl))
    .and_then(|(_, value)| value)
    .map(ny_levers::LeverValue::Bool)
}

/// Everything the relational route freezes from its category preset: the
/// scored-wall clamp it executes and the router modes it runs under. Nothing
/// else rides along.
fn relational_config_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    relational_scored_wall_clamp_config_value(loaded, decl)
        .or_else(|| relational_router_config_value(loaded, decl))
}

/// #iso-edge-cap: the typed preset values the RELATIONAL route projects from
/// its category preset into the difference-network BaB, beside the one lever
/// (`scored_wall_clamp`) it freezes into the receipt.
///
/// WHY A SEPARATE PROJECTION. Relational categories take an early return that
/// never reaches `preset::apply`: `verify_difference_bounds` builds its
/// `BetaCrownConfig` INLINE from `BetaCrownConfig::acas_xu()`. A typed key
/// delivered only through `apply` would therefore parse, validate and do
/// nothing on exactly the lane whose edge work it governs — the
/// deliverable-but-not-delivered class. Each field here is read from the SAME
/// frozen preset snapshot the scored-wall clamp is read from, through the SAME
/// mapping `apply` uses, and lands in the inline config.
///
/// `Default` — no preset, an absent key, or the historical test entry
/// `run_relational_vnncomp` — projects nothing, so the lane is byte-identical
/// to the pre-key code.
#[derive(Debug, Clone, Copy, Default, PartialEq)]
struct RelationalPresetKeys {
    /// `attack.relational_point_vjp`: opt-in original-tower template advice.
    relational_point_vjp: bool,
    /// The existing typed `attack.concurrent` scheduling policy.
    attack_concurrent: bool,
    paired_difference: Option<crate::preset::PairedDifferencePreset>,
    /// `bab.branching.input_split.edge_wave_cap` →
    /// `BetaCrownConfig::input_split_edge_wave_cap`.
    edge_wave_cap: Option<ny_propagate::beta_crown::EdgeWaveCapConfig>,
}

impl RelationalPresetKeys {
    fn from_preset(loaded: &crate::preset::PresetConfig) -> Self {
        let mut relational_point_vjp = false;
        crate::preset::apply_relational_point_vjp_policy(&mut relational_point_vjp, loaded);
        Self {
            relational_point_vjp,
            attack_concurrent: loaded.attack.concurrent.unwrap_or(false),
            paired_difference: loaded.solver.paired_difference,
            edge_wave_cap: loaded
                .bab
                .branching
                .input_split
                .edge_wave_cap
                .as_ref()
                .map(crate::preset::InputSplitEdgeWaveCapPreset::to_config),
        }
    }
}

/// Proposals never own a neural verdict. A miss, expired checker or unavailable
/// provider leaves the complete input root for the following sound search.
fn try_paired_lp_prepass(
    chain: &ny_propagate::paired_difference::PairedChain,
    domain: &ny_propagate::paired_difference::BoxDomain,
    epsilon: f64,
    options: crate::preset::PairedDifferencePreset,
    deadline: std::time::Instant,
    workers: ny_propagate::paired_difference::ParallelWorkers,
) -> bool {
    use std::time::Instant;

    let start = Instant::now();
    if start >= deadline {
        return false;
    }
    eprintln!(
        "[paired-difference-lp] armed backend={} source=preset memory_mib={} native_steps={} live_seconds={:.3}",
        options.lp_backend.as_str(),
        options.lp_memory_mib,
        options.lp_steps,
        deadline.saturating_duration_since(start).as_secs_f64()
    );
    match options.lp_backend {
        crate::preset::PairedLpBackend::Native => {
            match chain.prove_lp_until(domain, epsilon, deadline, options.lp_steps, workers) {
                Some(report) => {
                    let timely = Instant::now() < deadline;
                    eprintln!(
                        "[paired-difference-lp] done backend=native source=ny_checked proved={} timely={} iterations={} variables={} equalities={} inequalities={} elapsed_s={:.6}",
                        report.proof.proved,
                        timely,
                        report.iterations,
                        report.proof.variables,
                        report.proof.equalities,
                        report.proof.inequalities,
                        start.elapsed().as_secs_f64()
                    );
                    report.proof.proved && Instant::now() < deadline
                }
                None => {
                    eprintln!(
                        "[paired-difference-lp] done backend=native source=ny_checked proved=false reason=declined_or_expired"
                    );
                    false
                }
            }
        }
        crate::preset::PairedLpBackend::Ay => {
            #[cfg(not(feature = "mip"))]
            {
                eprintln!(
                    "[paired-difference-lp] declined backend=ay proved=false reason=mip_feature_required"
                );
                false
            }
            #[cfg(feature = "mip")]
            {
                // Model construction, parsing and reduced numerical proposal
                // construction consume this same LP slice. Reduction is only
                // a preconditioner; the checker below uses full source rows.
                // Reserve a bounded tail for replaying the prepared source rows and
                // checking the entire multiplier portfolio independently.
                let remaining = deadline.saturating_duration_since(Instant::now());
                let checker_reserve = remaining
                    .mul_f64(0.1)
                    .min(std::time::Duration::from_secs(2));
                let proposal_deadline = deadline.checked_sub(checker_reserve).unwrap_or(start);
                let Some(memory_bytes) = options.lp_memory_mib.checked_mul(1024 * 1024) else {
                    eprintln!(
                        "[paired-difference-lp] declined backend=ay proved=false reason=memory_budget_overflow"
                    );
                    return false;
                };
                let Some(prepared) = chain.prepare_root_lp_until(domain, proposal_deadline) else {
                    eprintln!(
                        "[paired-difference-lp] declined backend=ay proved=false reason=source_build_declined_or_expired"
                    );
                    return false;
                };
                let Some(source_text) = prepared.dump_until(proposal_deadline) else {
                    eprintln!(
                        "[paired-difference-lp] declined backend=ay proved=false reason=source_dump_expired"
                    );
                    return false;
                };
                let source = match ny_mip::paired_difference_ay::SourceModel::parse(&source_text) {
                    Ok(source) => source,
                    Err(reason) => {
                        eprintln!(
                            "[paired-difference-lp] declined backend=ay proved=false reason=source_parse:{reason}"
                        );
                        return false;
                    }
                };
                if Instant::now() >= proposal_deadline {
                    eprintln!(
                        "[paired-difference-lp] declined backend=ay proved=false reason=source_budget_expired"
                    );
                    return false;
                }
                let proposal = match ny_mip::paired_difference_ay::solve_reduced_float(
                    &source,
                    proposal_deadline,
                    memory_bytes,
                ) {
                    Ok(proposal) => proposal,
                    Err(reason) => {
                        eprintln!(
                            "[paired-difference-lp] declined backend=ay proved=false reason=proposal:{reason}"
                        );
                        return false;
                    }
                };
                let mut texts = vec![proposal.dual_text.as_str()];
                if let Some(alternate) = proposal.alternate_dual_text.as_deref() {
                    texts.push(alternate);
                }
                eprintln!(
                    "[paired-difference-lp] proposals backend=ay proposer=reduced_float source=ny_source_dump finished_objectives={} transcripts={} reduced_free_variables={:?} reduced_nonzeros={:?} within_lp_deadline={} elapsed_s={:.6}",
                    proposal.finished_objectives,
                    texts.len(),
                    proposal.reduced_free_variables,
                    proposal.reduced_nonzeros,
                    Instant::now() < deadline,
                    start.elapsed().as_secs_f64()
                );
                for diagnostic in &proposal.diagnostics {
                    eprintln!(
                        "[paired-difference-lp] objective backend=ay output={} sign={} status={} elapsed_s={:.6}",
                        diagnostic.output, diagnostic.sign, diagnostic.status, diagnostic.elapsed_s
                    );
                }
                // Only NY's checker reads the private prepared source and meets valid
                // endpoints against the full original variable boxes and
                // authored rows. Approximate elimination, AY status, objective
                // values and ranking scores are not acceptance authority.
                let replay_start = Instant::now();
                match prepared.check_texts_until(epsilon, &texts, deadline) {
                    Some(report) => {
                        let timely = Instant::now() < deadline;
                        eprintln!(
                            "[paired-difference-lp] done backend=ay source=ny_checked source_model_constructions=1 source_model_reused_for_replay=true proved={} timely={} finished_objectives={} variables={} equalities={} inequalities={} replay_s={:.6} elapsed_s={:.6}",
                            report.proved,
                            timely,
                            proposal.finished_objectives,
                            report.variables,
                            report.equalities,
                            report.inequalities,
                            replay_start.elapsed().as_secs_f64(),
                            start.elapsed().as_secs_f64()
                        );
                        report.proved && Instant::now() < deadline
                    }
                    None => {
                        eprintln!(
                            "[paired-difference-lp] done backend=ay source=ny_checked source_model_constructions=1 source_model_reused_for_replay=true proved=false finished_objectives={} reason=checker_declined_or_expired replay_s={:.6} elapsed_s={:.6}",
                            proposal.finished_objectives,
                            replay_start.elapsed().as_secs_f64(),
                            start.elapsed().as_secs_f64()
                        );
                        false
                    }
                }
            }
        }
    }
}

#[cfg(all(test, feature = "mip"))]
mod paired_lp_prepass_tests {
    use super::try_paired_lp_prepass;
    use crate::preset::{PairedDifferencePreset, PairedLpBackend};
    use ny_propagate::paired_difference::{BoxDomain, PairedChain, ParallelWorkers, Stage};
    use std::time::{Duration, Instant};

    fn affine_fixture() -> (PairedChain, BoxDomain, PairedDifferencePreset) {
        // Exactly f(x)=9x/8+1/4, g(x)=x. The full source difference
        // ranges over [1/8, 3/8] and yields a nonconstant AY objective.
        let chain = PairedChain {
            input_dim: 1,
            output_dim: 1,
            stages: vec![Stage::Affine {
                rows: 1,
                cols: 1,
                wf: vec![1.125],
                wg: vec![1.0],
                bf: vec![0.25],
                bg: vec![0.0],
            }],
        };
        let domain = BoxDomain {
            lo: vec![-1.0],
            hi: vec![1.0],
        };
        let options = PairedDifferencePreset {
            max_seconds: 20.0,
            max_domains: 1,
            max_lp_seconds: 20.0,
            lp_backend: PairedLpBackend::Ay,
            lp_memory_mib: 128,
            lp_steps: 1,
            workers: 1,
        };
        (chain, domain, options)
    }

    #[test]
    fn paired_lp_prepass_ay_accepts_certified_affine_band() {
        let (chain, domain, options) = affine_fixture();
        assert!(try_paired_lp_prepass(
            &chain,
            &domain,
            0.4,
            options,
            Instant::now() + Duration::from_secs(20),
            ParallelWorkers::new(1).unwrap(),
        ));
    }

    #[test]
    fn paired_lp_prepass_ay_rejects_violating_affine_band() {
        let (chain, domain, options) = affine_fixture();
        // x=1 is in the source box and gives |f(1)-g(1)|=3/8>3/10.
        assert!(domain.lo[0] <= 1.0 && domain.hi[0] >= 1.0);
        let Stage::Affine { wf, wg, bf, bg, .. } = &chain.stages[0] else {
            panic!("fixture must retain its affine source stage");
        };
        let x = 1.0;
        let difference = (wf[0] * x + bf[0]) - (wg[0] * x + bg[0]);
        assert!(difference.abs() > 0.3);
        assert!(!try_paired_lp_prepass(
            &chain,
            &domain,
            0.3,
            options,
            Instant::now() + Duration::from_secs(20),
            ParallelWorkers::new(1).unwrap(),
        ));
    }

    #[test]
    fn paired_lp_prepass_ay_rejects_expired_deadline() {
        let (chain, domain, options) = affine_fixture();
        let expired = Instant::now();
        assert!(!try_paired_lp_prepass(
            &chain,
            &domain,
            0.4,
            options,
            expired,
            ParallelWorkers::new(1).unwrap(),
        ));
    }
}

#[cfg(test)]
mod relational_preset_keys_tests {
    use super::RelationalPresetKeys;

    fn keys_from(text: &str) -> RelationalPresetKeys {
        let loaded: crate::preset::PresetConfig =
            serde_yaml::from_str(text).expect("the yaml parses");
        RelationalPresetKeys::from_preset(&loaded)
    }

    /// DARK BY DEFAULT: no preset, an empty preset and the scored-wall-only
    /// preset all project nothing.
    #[test]
    fn relational_edge_wave_cap_projection_is_dark_by_default() {
        assert_eq!(RelationalPresetKeys::default().edge_wave_cap, None);
        assert_eq!(keys_from("{}\n"), RelationalPresetKeys::default());
        assert_eq!(
            keys_from("solver:\n  scored_wall_clamp: true\n"),
            RelationalPresetKeys::default()
        );
    }

    /// The typed AY choice selects the reduced numeric proposer, while Native
    /// remains an explicit compatibility choice. Both use source replay.
    #[test]
    fn paired_difference_preset_projects_into_relational_authority() {
        assert_eq!(keys_from("{}\n").paired_difference, None);
        let keys = keys_from(
            "solver:\n  paired_difference:\n    max_seconds: 10.0\n    max_domains: 20000\n",
        );
        assert_eq!(
            keys.paired_difference,
            Some(crate::preset::PairedDifferencePreset {
                max_seconds: 10.0,
                max_domains: 20000,
                max_lp_seconds: 0.0,
                lp_backend: crate::preset::PairedLpBackend::Ay,
                lp_memory_mib: 2048,
                lp_steps: 2000,
                workers: 1
            })
        );
        let explicit = keys_from(
            "solver:\n  paired_difference:\n    max_seconds: 10.0\n    max_domains: 20000\n    max_lp_seconds: 5.0\n    lp_backend: native\n    lp_memory_mib: 16\n    lp_steps: 17\n    workers: 2\n",
        );
        assert_eq!(
            explicit.paired_difference,
            Some(crate::preset::PairedDifferencePreset {
                max_seconds: 10.0,
                max_domains: 20000,
                max_lp_seconds: 5.0,
                lp_backend: crate::preset::PairedLpBackend::Native,
                lp_memory_mib: 16,
                lp_steps: 17,
                workers: 2,
            })
        );
        let ay = keys_from(
            "solver:\n  paired_difference:\n    max_seconds: 10.0\n    max_domains: 20000\n    lp_backend: ay\n    lp_memory_mib: 256\n",
        )
        .paired_difference
        .unwrap();
        assert_eq!(ay.lp_backend, crate::preset::PairedLpBackend::Ay);
        assert_eq!(ay.lp_backend.as_str(), "ay");
        assert_eq!(ay.lp_memory_mib, 256);
    }

    /// THE ROUTE: the typed block in a category preset reaches the relational
    /// projection — the only way it can reach the inline relational config.
    #[test]
    fn relational_edge_wave_cap_projection_delivers_the_typed_block() {
        let empty = keys_from("bab:\n  branching:\n    input_split:\n      edge_wave_cap: {}\n");
        let cap = empty.edge_wave_cap.expect("presence arms");
        assert_eq!(cap.max_secs, None);
        assert_eq!(cap.rebound_share, None);

        let named = keys_from(
            "bab:\n  branching:\n    input_split:\n      edge_wave_cap:\n        \
             max_secs: 1.5\n        rebound_share: 0.5\n",
        );
        let cap = named.edge_wave_cap.expect("named block arms");
        assert_eq!(cap.max_secs, Some(1.5));
        assert_eq!(cap.rebound_share, Some(0.5));
    }

    /// The shipped isomorphic and monotonic presets do NOT arm the cap:
    /// arming lands only in the commit that carries its measurement.
    #[test]
    fn shipped_relational_presets_do_not_arm_the_edge_wave_cap() {
        let repo_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        for relative in [
            "configs/vnncomp26/isomorphic_acasxu_2026.yaml",
            "configs/vnncomp26/monotonic_acasxu_2026.yaml",
            "configs/vnncomp25/isomorphic_acasxu_2026.yaml",
            "configs/vnncomp25/monotonic_acasxu_2026.yaml",
        ] {
            let path = repo_root.join(relative);
            if !path.is_file() {
                continue;
            }
            let loaded = crate::preset::load_preset(&path).expect("shipped preset loads");
            assert_eq!(
                RelationalPresetKeys::from_preset(&loaded).edge_wave_cap,
                None,
                "{relative} must not arm #iso-edge-cap without a measured promotion"
            );
        }
        // The one the category actually resolves to must exist, or the loop
        // above proved nothing.
        assert!(repo_root
            .join("configs/vnncomp26/isomorphic_acasxu_2026.yaml")
            .is_file());
    }
}

/// Project the wave-batched kFSB treatment exactly as the runtime resolves it.
///
/// New search arms use dedicated fields so changing the wave selector cannot
/// silently retune ordinary FSB/kFSB. Existing shipped presets predate those
/// fields, however, and the runtime deliberately inherits their generic values
/// when the dedicated values are absent. The receipt must record that same
/// effective fallback instead of the declarations' 8/min defaults.
fn kfsb_preset_config_value(
    loaded: &crate::preset::PresetConfig,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    let branching = &loaded.bab.branching;
    if std::ptr::eq(decl, &raw const ny_levers::decls::kfsb::MO_KFSB_K) {
        return branching
            .kfsb_multi_candidates
            .or(branching.candidates)
            .and_then(|value| u64::try_from(value).ok())
            .map(ny_levers::LeverValue::U64);
    }
    if std::ptr::eq(decl, &raw const ny_levers::decls::kfsb::MO_KFSB_REDUCE) {
        return branching
            .kfsb_multi_reduceop
            .as_ref()
            .or(branching.reduceop.as_ref())
            .cloned()
            .map(ny_levers::LeverValue::Text);
    }
    None
}

/// Project every `Deliver::PresetKey` axis from the immutable preset snapshot
/// into the governed lever receipt.
///
/// This is deliberately driven by `ny_levers::space` instead of another
/// hand-maintained list. The delivery key is already the reviewed contract
/// between an environment treatment and its scored YAML route; using that same
/// key here prevents a newly promoted mechanism from executing under a typed
/// preset while the early flight receipt still claims its declaration default.
fn preset_delivered_config_value(
    serialized: &serde_json::Value,
    decl: &'static ny_levers::LeverDecl,
) -> Option<ny_levers::LeverValue> {
    let axis = ny_levers::space::axes()
        .iter()
        .chain(ny_levers::space::unsafe_axes())
        .find(|axis| axis.name == decl.name)?;
    let ny_levers::space::Deliver::PresetKey(key) = axis.deliver else {
        return None;
    };
    let value = key
        .split('.')
        .try_fold(serialized, |node, part| node.as_object()?.get(part))?;
    if value.is_null() {
        return None;
    }

    match decl.kind {
        ny_levers::LeverKind::Bool
        | ny_levers::LeverKind::BoolOverride
        | ny_levers::LeverKind::BoolKillOverride
        | ny_levers::LeverKind::TruthyTrimmed
        | ny_levers::LeverKind::TrimmedExactOne
        | ny_levers::LeverKind::Presence => value.as_bool().map(ny_levers::LeverValue::Bool),
        ny_levers::LeverKind::U64
        | ny_levers::LeverKind::U64Override
        | ny_levers::LeverKind::U64Trimmed
        | ny_levers::LeverKind::UsizeTrimmed
        | ny_levers::LeverKind::UsizeTrimmedUnicodeOwned
        | ny_levers::LeverKind::UsizeTrimmedOverride { .. }
        | ny_levers::LeverKind::UsizeOverride { .. }
        | ny_levers::LeverKind::Usize { .. } => value.as_u64().map(ny_levers::LeverValue::U64),
        ny_levers::LeverKind::F32Positive | ny_levers::LeverKind::F32NonNegative => value
            .as_f64()
            .map(|value| ny_levers::LeverValue::F64(f64::from(value as f32))),
        ny_levers::LeverKind::F64Open { .. }
        | ny_levers::LeverKind::F64OpenOverride { .. }
        | ny_levers::LeverKind::F64OpenUnicodeOwned { .. }
        | ny_levers::LeverKind::F64ClosedTrimmed { .. } => {
            value.as_f64().map(ny_levers::LeverValue::F64)
        }
        ny_levers::LeverKind::Secs => value.as_f64().map(ny_levers::LeverValue::Secs),
        ny_levers::LeverKind::Enum(_) | ny_levers::LeverKind::LayeredEnum { .. } => value
            .as_str()
            .map(|text| ny_levers::LeverValue::Text(text.to_string())),
        ny_levers::LeverKind::Text => value
            .as_str()
            .map(str::to_owned)
            // A few legacy raw-predicate gates have a typed Boolean delivery
            // key but intentionally retain their historical Text parser. The
            // receipt must carry the exact token that predicate represents.
            .or_else(|| {
                value
                    .as_bool()
                    .map(|on| if on { "1" } else { "0" }.to_string())
            })
            .map(ny_levers::LeverValue::Text),
    }
}

/// Native VNN-COMP `run_instance.sh` entry point.
///
/// See the module docs for the full contract. Always writes RESULTS_FILE (with a sound
/// verdict) and returns `Ok(())` on the happy path; returns `Err` only when RESULTS_FILE
/// itself cannot be written (the caller treats that as a fatal CLI error).
pub(crate) fn handle_vnncomp_command(
    version: String,
    category: String,
    onnx: PathBuf,
    vnnlib: PathBuf,
    results_file: PathBuf,
    timeout_secs: u64,
    configs_dir: Option<PathBuf>,
) -> Result<()> {
    // #scored-wall-clamp: the anchor for every absolute deadline this command
    // derives. Taken FIRST, before any work at all, so that the wall a lane is
    // handed already charges the seconds this command spends getting there.
    let command_start = std::time::Instant::now();

    // Protocol: the first argument must be the version string.
    if version != VERSION_STRING {
        return Err(anyhow!(
            "Expected version string '{VERSION_STRING}', got '{version}'"
        ));
    }

    // State WHICH VERIFIER this is before any work (#binary-identity). Four
    // times this campaign a bank was attributed to the wrong binary because
    // nothing in the per-instance log said which one ran; the derived version
    // and feature tier on this line are what tell two builds apart.
    crate::build_id::log_once();
    // State the compute regime before any work: which measurements mean what
    // has turned on this line before (#backend-detect).
    crate::compute_backend::log_once();

    // FLIGHT RECORDER (#flight-record, I7): from here on, every seam this
    // command layer decides is noted, and the record is serialized next to
    // RESULTS_FILE on every terminal path. The artifact — not the log stream —
    // is where "which methods ran/skipped, on what backend" must live, because
    // the scored paths run RUST_LOG=error.
    {
        let backend = crate::compute_backend::detect();
        crate::flight::global().begin(backend.kind, &backend.summary, &category, timeout_secs);
        // #phase-cost: this record carries the run's per-phase cost census.
        crate::flight::global().attach_phase_cost();
    }
    // #soundness-spine M2a: the proof profile `main.rs` froze for this entry
    // point (`competition` unless `--proof-profile` overrode it). A caller
    // that froze nothing gets the scored default. Printed once per process and
    // recorded in the flight sidecar; it selects artifact sinks and audit
    // rates only.
    {
        let profile =
            ny_core::proof_profile::freeze(ny_core::proof_profile::ResolvedProofProfile::resolve(
                ny_core::proof_profile::EntryPoint::VnncompV1,
                None,
            ));
        let _ = ny_core::proof_profile::announce(profile);
        crate::flight::global().note_proof_profile(profile);
        // ENGINE_PROGRAM §1.7 B1: the ONE sink this process's lanes stream
        // proof hints into, wired before any lane runs — `NullSink` under
        // Competition (nothing written), the proof-hint bundle next to
        // RESULTS_FILE under Proof (finalised after publication by
        // `close_proof_bundle`). Write-only: no verdict path reads a sink.
        let sink = super::proof_bundle::wire_scored_run(profile, &results_file, &onnx, &vnnlib);
        crate::flight::note(
            "proof_sink",
            crate::flight::FlightStatus::Ran,
            Some(format!("sink={sink} mode={}", profile.mode.token())),
        );
    }
    // #graph-free-candidates: remember where RESULTS_FILE lives so an ARMED
    // graph-free lane can write its diagnostic side file beside it. A plain
    // path store — nothing reads it unless `attack.graph_free_candidate_sidefile`
    // is armed, so a dark run is unaffected.
    graph_free_sidefile::set_results_target(&results_file);

    // Local cooperative anchor for the scored budget. Everything downstream
    // that spends opportunistic time after the main verification run budgets
    // against this `Instant`; the hard-stop authority below uses the shared
    // process-independent monotonic value instead.
    // Sample the process-independent scored clock first. The short watchdog's
    // authoritative H is derived exactly once from this value and never
    // reconstructed from a later `Instant`, wall clock, or helper-local sample.
    #[cfg(unix)]
    let canonical_instance_start = canonical_monotonic_now();
    let instance_deadline =
        std::time::Instant::now() + std::time::Duration::from_secs(timeout_secs);
    // #instance-budget: publish the authoritative deadline ONCE so deep gates
    // can apply invariant I1 against the real remaining budget instead of
    // whatever phase-local deadline happens to be in scope. Measured defect:
    // the forward-linear admission gate saw 37-38s when 186-226s was live,
    // because five call levels down the only deadline available was the 40s
    // root-alpha phase cap. Advisory and scheduling-only -- it never touches a
    // bound.
    ny_core::instance_budget::publish(instance_deadline);
    let short_grace_gate = std::env::var_os(SAFENLP_SHORT_GRACE_ENV);
    let timeout_decision =
        internal_timeout_decision(&category, timeout_secs, short_grace_gate.as_deref());
    let short_grace_route = timeout_decision.route == InternalTimeoutRoute::SafeNlpShortGrace;
    crate::flight::note(
        "internal_timeout_route",
        crate::flight::FlightStatus::Ran,
        Some(format!(
            "route={:?} solver_timeout={}s scored_budget={timeout_secs}s",
            timeout_decision.route, timeout_decision.solver_timeout_secs
        )),
    );
    #[cfg(unix)]
    let short_hard_stop = short_grace_route
        .then_some(canonical_instance_start)
        .flatten()
        .and_then(|start| {
            start.checked_add(
                std::time::Duration::from_secs(timeout_secs)
                    .saturating_sub(SAFENLP_SHORT_HARD_STOP_MARGIN),
            )
        });
    #[cfg(not(unix))]
    let short_hard_stop =
        short_grace_route.then(|| safenlp_short_hard_stop_deadline(instance_deadline));

    // The short-grace route gives RESULTS_FILE one writer: a coordinator whose
    // receive window closes at the already-anchored scored deadline. Publish
    // the sound placeholder before either watchdog starts, then hand the
    // verifier only a channel sender; it has no post-deadline file-write path.
    let (short_grace_publisher, short_grace_receiver) = if short_grace_route {
        write_results(&results_file, &VnncompResult::Unknown)?;
        let (sender, receiver) = std::sync::mpsc::channel();
        (
            Some(ShortGraceResultPublisher {
                results_file: results_file.clone(),
                sender,
            }),
            Some(receiver),
        )
    } else {
        (None, None)
    };

    // OUT-OF-PROCESS WATCHDOG (#vnncomp-external-watchdog): the deadline
    // coordinator below is itself a THREAD of this process, so it enforces
    // nothing once the whole process stops scheduling. Observed 2026-07-24
    // (vggnet16_2022 spec1,
    // NY_DD_ZONOTOPE=0, GB10, concurrent GPU verifier on the same device): the
    // run froze process-wide and sat >6h past a 1200s budget with the
    // pre-written `unknown` placeholder still on disk — the coordinator's
    // post-sleep work (allocate + write) never completed because every thread
    // wedged behind the stalled GPU submission. The only deadline enforcement
    // that survives a process-wide freeze lives in a DIFFERENT process: spawn a
    // helper via the hidden `__vnncomp-watchdog` entry (fresh exec of this
    // binary; no GPU/ORT/preset/logging state). The helper idles on its stdin
    // pipe — parent exit through ANY path closes the pipe and retires the
    // helper. The short route keeps a dedicated lease open until actual OS
    // process exit and sends explicit publication/fire control records through
    // a separate non-blocking writer. Its helper deadline is anchored in this
    // parent before spawn/exec. This avoids libc `exit` and its concurrent
    // foreign-library fini handlers. SOUND:
    // `timeout` never claims unsat/sat. Kill switch:
    // NY_VNNCOMP_EXTERNAL_WATCHDOG=0 (the coordinator then uses hard abort).
    #[cfg(unix)]
    let (historical_external_watchdog_control, short_external_watchdog) =
        if std::env::var("NY_VNNCOMP_EXTERNAL_WATCHDOG").as_deref() != Ok("0") {
            if short_grace_route {
                match short_hard_stop {
                    Some(hard_stop) => {
                        match spawn_and_retain_short_watchdog(&results_file, hard_stop) {
                            Ok(controller) => (None, Some(controller)),
                            // No diagnostic on the deadline setup path: the independent
                            // in-process timer still has an immediate abort fail-safe.
                            Err(_) => (None, None),
                        }
                    }
                    // A missing/overflowed canonical clock cannot authorize a
                    // terminal verdict or extend the deadline.
                    None => (None, None),
                }
            } else {
                let (deadline, result_policy) = historical_external_watchdog_contract(timeout_secs);
                match spawn_external_watchdog(&results_file, deadline, result_policy) {
                    Ok(mut child) => {
                        // Historical/default-off ownership and argv/timing
                        // remain exactly as before.
                        let control = child.stdin.take();
                        std::mem::forget(child);
                        (control, None)
                    }
                    Err(_) => (None, None),
                }
            }
        } else {
            (None, None)
        };
    #[cfg(not(unix))]
    let (historical_external_watchdog_control, short_external_watchdog): (
        Option<std::process::ChildStdin>,
        Option<ExternalWatchdogController>,
    ) = (None, None);

    // Hard wall-clock enforcement: every deadline inside the verifier is
    // cooperative (`Instant` polling between rounds/steps), so a single
    // oversized BaB batch or wedged GPU readback can overrun the scored budget
    // unboundedly when the shell backstop is absent. The short route separates
    // its sole publication coordinator from an ALWAYS-ARMED timer. Even if the
    // final rename blocks, the timer queues a fire request without blocking and
    // immediately aborts this process; the helper independently fires at the
    // same parent-anchored boundary.
    if let Some(receiver) = short_grace_receiver {
        let publication_deadline = safenlp_short_publication_deadline(instance_deadline);
        let hard_stop_watchdog = short_external_watchdog.clone();
        #[cfg(unix)]
        let hard_stop_deadline = short_hard_stop.unwrap_or(CanonicalMonotonicInstant::EXPIRED);
        #[cfg(not(unix))]
        let hard_stop_deadline =
            short_hard_stop.unwrap_or_else(|| safenlp_short_hard_stop_deadline(instance_deadline));
        std::thread::spawn(move || {
            run_short_grace_hard_stop(hard_stop_deadline, || {
                // No I/O, allocation, logging, or wait is allowed between the
                // timer boundary and the abort fail-safe.
                hard_stop_short_grace(hard_stop_watchdog);
            });
        });

        let results_file = results_file.clone();
        let publication_watchdog = short_external_watchdog;
        std::thread::spawn(move || {
            let _ = await_short_grace_terminal_result(
                &results_file,
                publication_deadline,
                receiver,
                publication_watchdog.as_ref(),
            );
        });
    } else {
        let results_file = results_file.clone();
        std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_secs(
                timeout_secs + WATCHDOG_GRACE_SECS,
            ));
            // #watchdog-verdict-overwrite: enforce the deadline against the
            // PLACEHOLDER only. If this instance already published a decided
            // verdict and then wedged (the measured 1.7 s `sat` that hung for
            // the rest of a 350 s budget), the hard stop below still fires —
            // but the verdict it earned survives instead of being replaced by
            // `timeout`, and the helper is told to preserve it too.
            let commit = commit_timeout_unless_verdict_published(&results_file, "watchdog.tmp");
            let request = match commit {
                Ok(TimeoutCommit::DeclinedDecidedVerdict) => {
                    EXTERNAL_WATCHDOG_PRESERVE_FIRE_REQUEST
                }
                Ok(TimeoutCommit::Committed) | Err(_) => EXTERNAL_WATCHDOG_FIRE_REQUEST,
            };
            // #flight-record-hard-stop: the LAST point at which this row can
            // still leave evidence. The command's post-verdict sidecar writes
            // are on paths this stop never reaches, so without this flush a
            // hard-stopped row records nothing at all — MEASURED as 1 of 19
            // TIMEOUT rows on the isomorphic_acasxu_2026 sweep, i.e. blind on
            // exactly the rows whose budget has scoring consequence.
            //
            // Ordering is deliberate: AFTER the timeout commit, so RESULTS_FILE
            // is already sealed and the record can name what was sealed, and
            // BEFORE the helper request, so the flush cannot be interrupted by
            // the kill it precedes. It touches only the sidecar path and never
            // blocks (see `write_hard_stop_sidecar`), so the deadline it
            // reports is the deadline it still enforces.
            crate::flight::global().write_hard_stop_sidecar(
                &results_file,
                match commit {
                    Ok(TimeoutCommit::DeclinedDecidedVerdict) => {
                        "in-process watchdog hard stop at budget+grace; \
                         the verdict this row published before the deadline was preserved"
                    }
                    Ok(TimeoutCommit::Committed) => {
                        "in-process watchdog hard stop at budget+grace; timeout committed"
                    }
                    Err(_) => {
                        "in-process watchdog hard stop at budget+grace; \
                         timeout commit failed, the pre-written unknown stands"
                    }
                },
            );
            // No stderr write is allowed on this critical path: a full pipe
            // must not delay the helper request or the bounded abort fallback.
            hard_stop_from_in_process_watchdog(historical_external_watchdog_control, request);
        });
    }

    // Resolve the configs directory: explicit flag, else auto-derive from the binary
    // and ONNX paths (nearest ancestor `configs/`).
    let configs_dir = configs_dir.or_else(configs_dir_from_env).or_else(|| {
        let mut starts = Vec::new();
        if let Ok(exe) = std::env::current_exe() {
            starts.push(exe);
        }
        // Canonicalize: a relative ONNX path (the competition harness passes
        // `onnx/foo.onnx` from inside the benchmark dir) has an ancestor chain
        // that terminates at `""` without ever reaching the repo root.
        starts.push(fs::canonicalize(&onnx).unwrap_or_else(|_| onnx.clone()));
        if let Ok(cwd) = std::env::current_dir() {
            starts.push(cwd);
        }
        auto_derive_configs_dir(&starts)
    });

    // NOTE the position: this used to sit ~150 lines BELOW, after the
    // relational early return, so a relational category reached
    // `resolve_preset_path` with the raw `--configs-dir` flag and nothing else
    // — which the competition harness does not pass. #scored-wall-clamp needs
    // the SAME derivation both routes have always used, so the derivation moved
    // up rather than being duplicated. Nothing about the non-relational path
    // changes: the value it binds is byte-identical, only computed earlier.

    // #name-blind-routing: the relational route is chosen by the INSTANCE's
    // own VNN-LIB (a property that declares two or more networks), never by the
    // category name the harness passes. See `RelationalRouteDecision`.
    let relational_route = RelationalRouteDecision::for_vnnlib(&vnnlib);
    if relational_route.selected() {
        // Relational properties bypass the YAML MODEL/SOLVER shape, but the
        // scored-wall deadline gate below is delivered by their category
        // preset. Freeze and validate that preset before the first (immutable)
        // receipt materialization, then project exactly the one typed value
        // this route executes. Materializing all defaults first used to record
        // NY_SCORED_WALL_CLAMP=false while the shipped preset ran it as true.
        let relational_base_preset = configs_dir
            .as_deref()
            .and_then(|dir| resolve_preset_path(dir, &category));
        note_base_preset(
            configs_dir.as_deref(),
            relational_base_preset.as_deref(),
            &category,
        );
        let relational_preset_snapshot = relational_base_preset
            .as_deref()
            .map(BetaCrownPresetSnapshot::load);
        let (relational_scored_wall_clamp, relational_frozen_levers) =
            match relational_preset_snapshot.as_ref() {
                None => {
                    let frozen = crate::flight::global().materialize_levers(|_| None);
                    (None, frozen)
                }
                Some(snapshot) => {
                    if let Some(loaded) = snapshot.loaded() {
                        let configured = loaded.solver.scored_wall_clamp;
                        // #router-r1: this route also runs the shadow router
                        // (its start site below), so the router's two typed
                        // modes ride in the same frozen projection.
                        let frozen = crate::flight::global()
                            .materialize_levers(|decl| relational_config_value(loaded, decl));
                        (configured, frozen)
                    } else {
                        let reason = snapshot
                            .invalid_error()
                            .unwrap_or("invalid relational preset");
                        crate::flight::global().mark_levers_invalid_config(reason);
                        crate::flight::note(
                            "preset",
                            crate::flight::FlightStatus::Skipped,
                            Some(reason.to_owned()),
                        );
                        write_results(&results_file, &VnncompResult::Unknown)?;
                        crate::flight::note(
                            "result_publish",
                            crate::flight::FlightStatus::Ran,
                            Some("unknown: invalid relational preset".to_string()),
                        );
                        crate::flight::finish(VnncompResult::Unknown.token());
                        crate::flight::global().write_sidecar(&results_file);
                        return Ok(());
                    }
                }
            };
        let Some(relational_frozen_levers) = relational_frozen_levers else {
            let reason = "relational parameter authority did not materialize";
            crate::flight::note(
                "relational_route",
                crate::flight::FlightStatus::Skipped,
                Some(reason.to_string()),
            );
            write_results(&results_file, &VnncompResult::Unknown)?;
            crate::flight::finish(VnncompResult::Unknown.token());
            crate::flight::global().write_sidecar(&results_file);
            return Ok(());
        };
        crate::flight::note(
            "relational_route",
            crate::flight::FlightStatus::Ran,
            Some(relational_route.receipt()),
        );
        // #router-r1: the shadow router on the relational route (same
        // contract as the ordinary route below; this route runs no model scan,
        // so its facts are `Unknown("relational-route")`).
        if crate::router::requested(&relational_frozen_levers) {
            crate::router::start(&crate::router::StartContext {
                levers: Some(&relational_frozen_levers),
                authority: crate::router::Authority::Frozen,
                model: None,
                model_bytes: None,
                facts_reason: Some("relational-route"),
                declared_networks: u64::try_from(relational_route.declared_networks()).ok(),
                relational_selected: Some(relational_route.selected()),
                official_budget_secs: timeout_secs,
                internal_secs: timeout_decision.solver_timeout_secs,
                join_margin: CONCURRENT_LANE_JOIN_MARGIN,
                anchor: command_start,
                target_host: None,
                pinned_keys: crate::router::route::pinned_keys(
                    relational_preset_snapshot
                        .as_ref()
                        .and_then(BetaCrownPresetSnapshot::loaded),
                    Some(&relational_frozen_levers),
                ),
                // #router-r6: the trial knobs this row pinned (frozen sites).
                trial_pinned_keys: crate::router::otrial::pinned_keys(
                    relational_preset_snapshot
                        .as_ref()
                        .and_then(BetaCrownPresetSnapshot::loaded),
                    Some(&relational_frozen_levers),
                ),
                // #admission-precision: this route reads no property at start.
                spec: super::beta_crown::spec_shape::SpecRead::Unknown("relational-route"),
            });
        }
        write_results(&results_file, &VnncompResult::Unknown)?;
        // #scored-wall-clamp: relational categories bypass the YAML preset
        // path for MODEL and SOLVER shape — they build a difference network,
        // not the preset's network — but a DEADLINE POLICY is not a shape, and
        // this family's 105 % budget overrun was caused precisely by the
        // deadline policy having no preset-reachable authority over it. Resolve
        // the preset here for that one typed key and nothing else, so the fix
        // can reach a scored run (a competition harness exports no `NY_*`).
        // Absent preset, absent section or absent key ⇒ `None` ⇒ the
        // declaration default ⇒ today's behaviour.
        // #flush-grace: the relational lane returns before the preset-owned
        // policy chain below, and derives its own tier from
        // `internal_timeout_secs` directly, so emit the receipt for the route
        // it actually takes. Without this an absent line would be ambiguous
        // between "old binary" and "relational category".
        emit_flush_grace_receipt(timeout_secs, timeout_decision);
        let scored_wall = scored_wall_clamp_armed_from_levers(&relational_frozen_levers)
            .then(|| scored_wall_from_budget(command_start, timeout_secs));
        crate::flight::note(
            "scored_wall_clamp",
            if scored_wall.is_some() {
                crate::flight::FlightStatus::Ran
            } else {
                crate::flight::FlightStatus::Skipped
            },
            Some(format!(
                "preset_key={relational_scored_wall_clamp:?} armed={} \
                 scored_budget={timeout_secs}s internal_tier={}s \
                 wall_reserve={SCORED_WALL_STOP_RESERVE_SECS}s",
                scored_wall.is_some(),
                internal_timeout_secs(timeout_secs),
            )),
        );
        // #iso-edge-cap: the route's typed preset projection for the
        // difference-network BaB's inline config (see `RelationalPresetKeys`),
        // read from the SAME frozen snapshot as the clamp above. Absent preset
        // or absent key ⇒ `Default` ⇒ nothing projected ⇒ today's behaviour,
        // and no flight event is added.
        let relational_preset_keys = relational_preset_snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.loaded())
            .map(RelationalPresetKeys::from_preset)
            .unwrap_or_default();
        if let Some(cap) = relational_preset_keys.edge_wave_cap {
            crate::flight::note(
                "edge_wave_cap",
                crate::flight::FlightStatus::Ran,
                Some(format!(
                    "preset_key=bab.branching.input_split.edge_wave_cap max_secs={:?} \
                     rebound_share={:?} (None = the lane default)",
                    cap.max_secs, cap.rebound_share,
                )),
            );
        }
        let result = run_relational_vnncomp_with_frozen_levers(
            &onnx,
            &vnnlib,
            timeout_secs,
            scored_wall,
            Some(relational_frozen_levers),
            relational_preset_keys,
            relational_preset_keys
                .attack_concurrent
                .then(|| relational_overlap::PublishTarget {
                    results_file: results_file.clone(),
                    deadline: instance_deadline,
                }),
        )
        .unwrap_or_else(|err| {
            eprintln!("Relational verification produced no verdict (sound unknown): {err}");
            VnncompResult::Unknown
        });
        let (result, wrote) = if let Some(live) =
            crate::commands::beta_crown::attack_concurrent::live_threads_if_engaged()
                .filter(|_| relational_preset_keys.attack_concurrent)
        {
            debug_assert_eq!(
                live, 0,
                "relational attack scope must join before publication"
            );
            let door = publish_main_verdict_in(
                &SAT_PRECEDENCE,
                &ATTACK_DOOR_CHANGED,
                &TERMINAL_PUBLICATION_CLAIMED,
                result,
                instance_deadline.checked_sub(MAIN_DOOR_PUBLISH_RESERVE),
                |result| write_results(&results_file, result).map(|()| true),
            );
            (door.result, door.written.transpose()?.unwrap_or(false))
        } else {
            write_results(&results_file, &result)?;
            (result, true)
        };
        if !wrote {
            return Ok(());
        }
        // #batched-bab observability (dark, NY_BETA_GPU_PROBE=1): report
        // whether the wide domain-stacked GPU CROWN lane actually PUBLISHED a
        // result this run. The counter is production-armed but was previously
        // readable only from tests, so a lane that silently never fires (the
        // exact failure this campaign kept hitting: an armed device refused by
        // a capability, a request gate, or a shape predicate) looked identical
        // to one doing the work.
        //
        // #chain-wide (S2): additionally self-announce whenever the lane
        // actually PUBLISHED (`wide_resnet_batched_taken_count() > 0`) — the
        // typed `bab.chain_wide`/`bab.beta_graft` arming is preset-delivered
        // with no env in competition, and repo law voids any lane measurement
        // without the lane's own stderr observable. Print-only; runs where the
        // lane never fires keep byte-identical stderr.
        if beta_gpu_probe_armed() || ny_gpu::wide_resnet_batched_taken_count() > 0 {
            emit_wide_lane_readout();
        }
        println!("Result: {}", result.token());
        crate::flight::note(
            "result_publish",
            crate::flight::FlightStatus::Ran,
            Some(result.token().to_string()),
        );
        crate::flight::finish(result.token());
        crate::flight::global().write_sidecar(&results_file);
        close_proof_bundle(&result);
        return Ok(());
    }

    // Validate input files BEFORE touching RESULTS_FILE. A missing input is a genuine
    // failure -> write `error` (matches the shell wrapper).
    if !onnx.is_file() {
        write_terminal_result(
            &results_file,
            short_grace_publisher.as_ref(),
            VnncompResult::Error,
        )?;
        eprintln!("Error: ONNX file not found: {}", onnx.display());
        crate::flight::note(
            "result_publish",
            crate::flight::FlightStatus::Ran,
            Some("error: ONNX file not found".to_string()),
        );
        crate::flight::finish(VnncompResult::Error.token());
        crate::flight::global().write_sidecar(&results_file);
        return Ok(());
    }
    if !vnnlib.is_file() {
        write_terminal_result(
            &results_file,
            short_grace_publisher.as_ref(),
            VnncompResult::Error,
        )?;
        eprintln!("Error: VNNLIB file not found: {}", vnnlib.display());
        crate::flight::note(
            "result_publish",
            crate::flight::FlightStatus::Ran,
            Some("error: VNNLIB file not found".to_string()),
        );
        crate::flight::finish(VnncompResult::Error.token());
        crate::flight::global().write_sidecar(&results_file);
        return Ok(());
    }

    println!(
        "Running VNN-COMP instance: category='{category}' onnx='{}' vnnlib='{}' results='{}' timeout={}s",
        onnx.display(),
        vnnlib.display(),
        results_file.display(),
        timeout_secs
    );

    // Preset auto-loading: category -> yaml, newest year first, base-name fallback.
    let base_preset = configs_dir
        .as_deref()
        .and_then(|dir| resolve_preset_path(dir, &category));
    note_base_preset(configs_dir.as_deref(), base_preset.as_deref(), &category);
    // Resolve model/budget/backend-adaptive defaults under the category preset
    // before freezing the shared wrapper/engine preset snapshot. The temporary
    // effective preset is owned by `resolved_plan` through the entire run.
    let plan_runtime = crate::plan_resolver::PlanRuntimeOverrides::from_env_values(
        std::env::var_os(crate::plan_resolver::PGD_TIME_CAP_DISABLE_ENV).as_deref(),
        std::env::var_os(crate::plan_resolver::DISJUNCTIVE_PGD_SKIP_ENV).as_deref(),
    );
    let resolved_plan = crate::plan_resolver::resolve_and_materialize_with_runtime(
        &onnx,
        base_preset.as_deref(),
        timeout_secs,
        crate::compute_backend::detect(),
        plan_runtime,
        crate::plan_resolver::probe_fl_rate,
    );
    crate::flight::note(
        "plan_resolved",
        crate::flight::FlightStatus::Ran,
        Some(resolved_plan.flight_summary()),
    );
    if resolved_plan.effective_preset() != base_preset.as_deref() {
        println!(
            "Plan resolver: merged effective preset {} (base: {})",
            resolved_plan
                .effective_preset()
                .map_or_else(|| "<none>".to_string(), |path| path.display().to_string()),
            base_preset.as_deref().map_or_else(
                || "auto defaults (no category preset)".to_string(),
                |path| path.display().to_string()
            ),
        );
    }
    // Borrow from the value that owns the merged temp preset's keep-alive
    // guard. At this call site the path is never copied beyond the synchronous
    // run, so `resolved_plan` necessarily remains live through every reader.
    // (The accessor cannot prevent a future caller from copying the path; its
    // contract explicitly requires retaining the plan in that case.)
    let preset = resolved_plan.effective_preset();
    // One immutable, semantically validated preset read owns wrapper scheduling,
    // the receipt-backed margin-row policy, and the in-process β-CROWN
    // configuration. An invalid snapshot is retained so run_and_translate
    // returns sound unknown before every wrapper verdict/work lane, without a
    // second path read.
    let preset_snapshot = preset.map(BetaCrownPresetSnapshot::load);
    // PHASE 0c LAYERED REGISTRY RECEIPT: `begin` captured the registered raw env
    // bytes before any work, but it deliberately did not pretend that an
    // env-only snapshot was the run's final declared-input resolution. Materialize only
    // after this exact preset snapshot has passed semantic validation. No
    // preset is a valid resolved default layer; an invalid preset gets an
    // explicit `invalid_config` state and is rejected below before any wrapper
    // verdict lane.
    let frozen_levers = match preset_snapshot.as_ref() {
        None => crate::flight::global().materialize_levers(|_| None),
        Some(snapshot) => {
            if let Some(loaded) = snapshot.loaded() {
                let serialized_preset = serde_json::to_value(loaded).ok();
                let alpha_zero_yield = crate::preset::effective_alpha_zero_yield_frac(loaded);
                // The sign-space lane is armed from the preset on the scored
                // path (#bnn-sign-space), so the receipt must show it that way:
                // without this projection the run's evidence would record the
                // declaration default while a new `sat` SOURCE was live.
                let bnn_sign_space = loaded.attack.bnn_sign_space;
                // Same obligation for the STE-PGD lane, which is armed from the
                // preset on the scored path too (#bnn-ste-pgd).
                let bnn_ste_pgd = loaded.attack.bnn_ste_pgd;
                // `#auto-alloc`: derive the root phase parameters from THIS model
                // before the lever set freezes, so the receipt, the lane and the
                // ratchets all see one value. Declines to `applied=false` (and
                // projects nothing) whenever the spec or the proxy is
                // unavailable, which is byte-identical to the preset.
                let auto_alloc_decision = {
                    let lane_budget_secs =
                        (timeout_secs as f64) - CONCURRENT_LANE_JOIN_MARGIN.as_secs_f64();
                    let spec = super::margin_row_bab::extract_twin_spec(&onnx);
                    // #bi-patch: an ARMED preset prices the phase at the patch
                    // MACs (the phase's own planner cost model); `None` is the
                    // historical dense pricing, byte-identical.
                    let patch_ratio = ny_propagate::margin_row::auto_alloc::patch_pricing_ratio(
                        loaded.margin_row.bi_patch,
                        loaded.margin_row.bi_patch_ratio,
                    );
                    let d = ny_propagate::margin_row::auto_alloc::decide_with_patch(
                        spec.as_ref(),
                        lane_budget_secs,
                        loaded
                            .margin_row
                            .alpha_secs
                            .unwrap_or(ny_propagate::margin_row::auto_alloc::DEFAULT_ALPHA_SECS),
                        loaded.margin_row.interm_alpha.unwrap_or(0),
                        loaded
                            .margin_row
                            .bi_topk
                            .unwrap_or(ny_propagate::margin_row::auto_alloc::DEFAULT_TOPK),
                        loaded
                            .margin_row
                            .bi_chunk
                            .unwrap_or(ny_propagate::margin_row::auto_alloc::DEFAULT_CHUNK),
                        patch_ratio,
                    );
                    eprintln!("{}", d.line());
                    d
                };
                crate::flight::global().materialize_levers(|decl| {
                    if let Some(value) = auto_alloc_config_value(&auto_alloc_decision, decl) {
                        return value;
                    }
                    // #graph-free-candidates: an INSTRUMENT has no search axis,
                    // so the generic projector below cannot see its typed key;
                    // project it here so an armed run's receipt says so.
                    if let Some(value) = graph_free_sidefile::preset_config_value(loaded, decl) {
                        return value;
                    }
                    if let Some(value) = kfsb_preset_config_value(loaded, decl) {
                        return Some(value);
                    }
                    if let Some(value) = margin_row_schedule_preset_config_value(loaded, decl) {
                        return value;
                    }
                    if let Some(value) = serialized_preset
                        .as_ref()
                        .and_then(|preset| preset_delivered_config_value(preset, decl))
                    {
                        return Some(value);
                    }
                    if let Some(value) = solver_preset_gate_config_value(loaded, decl) {
                        return Some(value);
                    }
                    if std::ptr::eq(
                        decl,
                        &raw const ny_levers::decls::dark_probes::BNN_SIGN_SPACE_LANE,
                    ) {
                        return bnn_sign_space.map(ny_levers::LeverValue::Bool);
                    }
                    if std::ptr::eq(
                        decl,
                        &raw const ny_levers::decls::dark_probes::BNN_STE_PGD_LANE,
                    ) {
                        return bnn_ste_pgd.map(ny_levers::LeverValue::Bool);
                    }
                    std::ptr::eq(
                        decl,
                        &raw const ny_levers::decls::root_alpha::ALPHA_ZERO_YIELD_FRAC,
                    )
                    .then_some(alpha_zero_yield)
                    .flatten()
                    .map(ny_levers::LeverValue::F64)
                })
            } else if let Some(reason) = snapshot.invalid_error() {
                crate::flight::global().mark_levers_invalid_config(reason);
                None
            } else {
                None
            }
        }
    };
    // Consume the same immutable authority whose resolution was serialized in
    // the flight receipt. A declaration/registry mismatch is a programming
    // error, but on the scored path it fails closed to the existing
    // missing-authority `unknown` instead of reopening the process environment.
    let (frozen_levers, postbab_wrapper_policy) = match frozen_levers {
        Some(levers) => match PostBabWrapperPolicy::from_levers(&levers) {
            Ok(policy) => (Some(levers), policy),
            Err(error) => {
                eprintln!(
                    "Invalid frozen VNN-COMP post-BaB wrapper policy; suppressing scored work: \
                     {error}"
                );
                crate::flight::note(
                    "postbab_wrapper_policy",
                    crate::flight::FlightStatus::Skipped,
                    Some(error),
                );
                (None, PostBabWrapperPolicy::ENABLED)
            }
        },
        None => (None, PostBabWrapperPolicy::ENABLED),
    };
    let postbab_wrapper_route =
        postbab_wrapper_route_from_snapshot(preset_snapshot.as_ref(), postbab_wrapper_policy);
    if frozen_levers.is_some() {
        crate::flight::note(
            "postbab_wrapper_policy",
            crate::flight::FlightStatus::Ran,
            Some(postbab_wrapper_policy.receipt_details(
                postbab_engine_fraction_from_snapshot(preset_snapshot.as_ref()),
                postbab_wrapper_route,
            )),
        );
    }
    let margin_row_schedule_policy = frozen_levers.as_ref().and_then(|levers| {
        match super::margin_row_bab::MarginRowScheduleRuntimePolicy::from_levers(levers) {
            Ok(policy) => Some(policy),
            Err(error) => {
                eprintln!(
                    "Invalid frozen VNN-COMP margin-row schedule policy; suppressing scored \
                     work: {error}"
                );
                crate::flight::note(
                    "margin_row_schedule_policy",
                    crate::flight::FlightStatus::Skipped,
                    Some(error),
                );
                None
            }
        }
    });
    let margin_row_schedule_policy_invalid =
        frozen_levers.is_some() && margin_row_schedule_policy.is_none();
    let timeout_decision =
        apply_postbab_wrapper_timeout_policy(timeout_decision, timeout_secs, postbab_wrapper_route);
    // #flush-grace: applied LAST of the three so an explicit typed reserve
    // outranks the proof-tail rule, and guarded inside the policy so it can
    // never displace the SafeNLP short-grace lane.
    let timeout_decision = apply_results_flush_grace_policy(
        timeout_decision,
        timeout_secs,
        results_flush_grace_from_snapshot(preset_snapshot.as_ref()),
    );
    // Unconditional, and emitted HERE rather than beside the `Timeout:` line so
    // that no early return between this point and that line can suppress it.
    emit_flush_grace_receipt(timeout_secs, timeout_decision);
    crate::flight::note(
        "results_flush_grace",
        if timeout_decision.route == InternalTimeoutRoute::PresetFlushGrace {
            crate::flight::FlightStatus::Ran
        } else {
            crate::flight::FlightStatus::Skipped
        },
        Some(format!(
            "route={:?} budget={timeout_secs}s grace={}s internal_timeout={}s \
historical_internal_timeout={}s",
            timeout_decision.route,
            timeout_decision.effective_flush_reserve_secs,
            timeout_decision.solver_timeout_secs,
            timeout_decision.historical_solver_timeout_secs,
        )),
    );
    // #router-r1 (ROUTER_PROGRAM R1): the SHADOW router starts here — after
    // the lever freeze, before any lane. It reads its mode from the SAME
    // frozen LeverSet the receipt serialises (from the entry-time environment
    // layer alone only when the preset was invalid and no set exists), takes
    // facts from the plan resolver's existing scan, and logs a pure plan. It
    // returns nothing and moves nothing, and with the router off it does
    // nothing at all (one lever lookup). Fail-open inside; the retrospective
    // half runs from `crate::flight::finish`, after publication.
    {
        let entry_env_levers = if frozen_levers.is_none() {
            crate::flight::global().entry_env_levers()
        } else {
            None
        };
        let (router_levers, router_authority) = match frozen_levers.as_deref() {
            Some(levers) => (Some(levers), crate::router::Authority::Frozen),
            None => (
                entry_env_levers.as_ref(),
                crate::router::Authority::EntryEnv,
            ),
        };
        if router_levers.is_some_and(crate::router::requested) {
            crate::router::start(&crate::router::StartContext {
                levers: router_levers,
                authority: router_authority,
                model: resolved_plan.facts.as_ref(),
                model_bytes: fs::metadata(&onnx).ok().map(|meta| meta.len()),
                facts_reason: None,
                declared_networks: u64::try_from(relational_route.declared_networks()).ok(),
                relational_selected: Some(relational_route.selected()),
                official_budget_secs: timeout_secs,
                internal_secs: timeout_decision.solver_timeout_secs,
                join_margin: CONCURRENT_LANE_JOIN_MARGIN,
                anchor: command_start,
                target_host: None,
                // #router-r5: the typed keys this row's file (or a
                // non-default lever source) pinned; a route never overrides
                // them.
                pinned_keys: crate::router::route::pinned_keys(
                    preset_snapshot
                        .as_ref()
                        .and_then(BetaCrownPresetSnapshot::loaded),
                    router_levers,
                ),
                // #router-r6: the trial knobs this row's file (or a
                // non-default lever source) pinned; a pinned knob's trial
                // site is frozen.
                trial_pinned_keys: crate::router::otrial::pinned_keys(
                    preset_snapshot
                        .as_ref()
                        .and_then(BetaCrownPresetSnapshot::loaded),
                    router_levers,
                ),
                // #admission-precision: the property's archetype and routing
                // shape — the lanes' parser and the one extractor the lanes
                // route on. Read only here, when the router was requested: an
                // `off` row parses nothing new.
                spec: super::beta_crown::spec_shape::read_spec(&vnnlib),
            });
        }
    }
    match (&configs_dir, preset) {
        (Some(dir), Some(path)) => {
            println!("Configs dir: {}", dir.display());
            println!("Loading preset: {}", path.display());
            crate::flight::note(
                "preset",
                crate::flight::FlightStatus::Ran,
                Some(path.display().to_string()),
            );
        }
        (Some(dir), None) => {
            println!(
                "Configs dir: {} (no preset for category '{category}'; using auto defaults)",
                dir.display()
            );
            eprintln!(
                "WARNING: no preset found for category '{category}' under {} — \
                 running with AUTO DEFAULTS. Any measurement taken this way is NOT \
                 comparable to a preset-configured run. Pass --configs-dir or set \
                 NY_CONFIGS_DIR to the repo's configs/ directory.",
                dir.display()
            );
        }
        (None, _) => {
            println!("No configs dir found; using auto defaults (no preset)");
            eprintln!(
                "WARNING: no configs dir found (searched the binary path, the ONNX path, \
                 and the working directory) — running category '{category}' with AUTO \
                 DEFAULTS, discarding its tuned preset. This silently happens when the \
                 binary lives outside the repo (an isolated CARGO_TARGET_DIR). Any \
                 measurement taken this way is NOT comparable to a preset-configured \
                 run. Pass --configs-dir or set NY_CONFIGS_DIR."
            );
        }
    }
    if preset.is_none() {
        // One skip event for both no-preset shapes; the reason distinguishes
        // them so a bank query can separate "category has no yaml" from the
        // far worse "binary ran outside the repo and lost every preset".
        crate::flight::note(
            "preset",
            crate::flight::FlightStatus::Skipped,
            Some(if configs_dir.is_some() {
                format!("no preset for category '{category}'; AUTO DEFAULTS")
            } else {
                "no configs dir found; AUTO DEFAULTS".to_string()
            }),
        );
    }

    // Timeout tiering: internal ny deadline fires below the scored budget. The
    // dark SafeNLP short-grace selector changes only this inner deadline; the
    // scored instance deadline and watchdog tiers above remain untouched. The
    // margin-row twin-wall lane's budget reserve is applied later, per-instance,
    // inside run_and_translate (see `margin_row_reserve_decision`), so it is NOT
    // pre-subtracted here — doing so would double-reserve and starve both tiers.
    let ny_timeout = timeout_decision.solver_timeout_secs;
    println!(
        "Timeout: ny --timeout={ny_timeout}s, competition budget={timeout_secs}s (auto branching/backend/verifier/PGD)"
    );
    if timeout_decision.route == InternalTimeoutRoute::SafeNlpShortGrace {
        println!(
            "SafeNLP short-grace: gate={SAFENLP_SHORT_GRACE_ENV}=1, \
             normalized_category=safenlp_2024, budget={timeout_secs}s, \
             requested_flush_reserve={SAFENLP_SHORT_GRACE_SECS}s, \
             effective_flush_reserve={}s, solver_timeout={ny_timeout}s, \
             historical_solver_timeout={}s, hard_stop_margin_ms={}",
            timeout_decision.effective_flush_reserve_secs,
            timeout_decision.historical_solver_timeout_secs,
            SAFENLP_SHORT_HARD_STOP_MARGIN.as_millis(),
        );
    } else if timeout_decision.route == InternalTimeoutRoute::PresetFlushGrace {
        println!(
            "Results-flush grace: typed bab.phase_budget.results_flush_grace_secs replaces the \
historical max(5, budget/20) rule; budget={timeout_secs}s, \
effective_flush_reserve={}s, solver_timeout={ny_timeout}s (absolute), \
historical_solver_timeout={}s",
            timeout_decision.effective_flush_reserve_secs,
            timeout_decision.historical_solver_timeout_secs,
        );
    } else if timeout_decision.route == InternalTimeoutRoute::PresetProofTail {
        println!(
            "Post-BaB proof-tail policy: explicit vnncomp_post_bab_attack=false and \
             post_bab_pgd_fraction=0; \
             leftover wrapper attack disabled, solver receives an absolute {}s deadline, \
             fixed RESULTS_FILE reserve={}s (historical solver timeout={}s)",
            ny_timeout,
            timeout_decision.effective_flush_reserve_secs,
            timeout_decision.historical_solver_timeout_secs,
        );
    }

    // Competition-safety pre-write (sound `unknown`). If verification overruns its
    // internal deadline — e.g. a long single CROWN backward or α-CROWN
    // intermediate-bound pass on a deep conv ResNet that does not poll the deadline
    // often enough — the OS-level wall-clock backstop in run_instance.sh kills this
    // process. Without a verdict already on disk that kill leaves an EMPTY results
    // file, which the competition scores as `error` (strictly worse than the 0-point,
    // no-penalty `unknown`/`timeout`). Writing `unknown` up front guarantees a sound
    // verdict always exists; `write_results` below overwrites it with the real
    // verdict on normal completion. SOUND: `unknown` never claims unsat/sat.
    if !short_grace_route {
        write_results(&results_file, &VnncompResult::Unknown)?;
        // #twinwall-early-exit: the placeholder is down, so RESULTS_FILE is now
        // a legal publication target. Arm the lane-side early publish for the
        // ordinary route only — the short-grace route has a single authorized
        // writer (its deadline coordinator) and must keep it.
        arm_lane_early_publish(&results_file);
        // #attack-concurrent: the same target for the concurrent attack
        // lane's `sat`, on the same route only. Silent and inert unless a race
        // site with `attack.concurrent` armed publishes through it.
        arm_concurrent_attack_publish(&results_file, &onnx, &vnnlib, Some(instance_deadline));
    }
    // #attack-concurrent: the key's own observable, once, before any lane.
    announce_attack_concurrent(preset_snapshot.as_ref());

    if margin_row_schedule_policy_invalid {
        let result = VnncompResult::Unknown;
        if write_terminal_result(
            &results_file,
            short_grace_publisher.as_ref(),
            result.clone(),
        )? {
            println!("Result: {}", result.token());
        }
        crate::flight::note(
            "result_publish",
            crate::flight::FlightStatus::Ran,
            Some("unknown: invalid frozen margin-row schedule policy".to_string()),
        );
        crate::flight::finish(result.token());
        crate::flight::global().write_sidecar(&results_file);
        return Ok(());
    }

    // Configure process-global Rayon only from the already-frozen policy and
    // after a sound placeholder can be published, but before any optional CZ
    // or verifier work can initialize the pool independently.
    let global_rayon_outcome = if let Some(policy) = margin_row_schedule_policy {
        match super::margin_row_bab::configure_global_rayon(policy) {
            Ok(outcome) => outcome,
            Err(failure) => {
                eprintln!(
                    "internal verifier thread cap: FAILED — {}; suppressing scored work",
                    failure.error,
                );
                crate::flight::note(
                    "margin_row_global_rayon",
                    crate::flight::FlightStatus::Skipped,
                    Some(format!(
                        "route=build_failed requested_threads={} host_parallelism={} error={}",
                        failure.requested_threads,
                        optional_usize_token(failure.host_threads),
                        failure.error,
                    )),
                );
                let result = VnncompResult::Unknown;
                if write_terminal_result(
                    &results_file,
                    short_grace_publisher.as_ref(),
                    result.clone(),
                )? {
                    println!("Result: {}", result.token());
                }
                crate::flight::note(
                    "result_publish",
                    crate::flight::FlightStatus::Ran,
                    Some("unknown: global Rayon initialization failed".to_string()),
                );
                crate::flight::finish(result.token());
                crate::flight::global().write_sidecar(&results_file);
                return Ok(());
            }
        }
    } else {
        super::margin_row_bab::GlobalRayonOutcome::NOT_REQUESTED
    };
    match global_rayon_outcome.route {
        super::margin_row_bab::GlobalRayonRoute::Applied => eprintln!(
            "internal verifier thread cap: ENGAGED — global Rayon pool has {} threads \
             (requested {}, host has {})",
            global_rayon_outcome.actual_threads.unwrap_or(0),
            global_rayon_outcome.requested_threads.unwrap_or(0),
            optional_usize_token(global_rayon_outcome.host_threads),
        ),
        super::margin_row_bab::GlobalRayonRoute::AlreadyInitialized => eprintln!(
            "internal verifier thread cap: REFUSED — global Rayon was already initialized with \
             {} threads (requested {}, host has {}); this run is void for the cap A/B",
            global_rayon_outcome.actual_threads.unwrap_or(0),
            global_rayon_outcome.requested_threads.unwrap_or(0),
            optional_usize_token(global_rayon_outcome.host_threads),
        ),
        super::margin_row_bab::GlobalRayonRoute::NotRequested => {}
    }

    // #cz-hybrid: independent certified CZ+Box verdict lane (PyRAT's metaroom
    // constrained-zonotope domain, ported as the M3–M26 series and previously
    // reachable only from a guarded example). Gated by the typed `cz_hybrid`
    // preset section's exact two-basename instance allowlist, so on every row
    // but the allowlisted one it costs two string compares and the pipeline
    // below is byte-identical. INDEPENDENT is deliberate: on the one
    // allowlisted row (metaroom spec_idx_119) the pipeline's root bound is
    // −808.77 with ~14 gained per BaB level (re-measured 2026-08-24), so
    // feeding the CZ bound into it would be a category error — the lane
    // carries the whole proof or nothing. It can publish exactly one verdict,
    // a fully certified `unsat` (19/19 challenger margins independently
    // replayed strictly positive); every other outcome — sealed-assert
    // mismatch, resource refusal, deadline, unproven margins — logs its
    // reason to the flight record and falls through unchanged.
    //
    // #cz-hybrid-budget. The lane used to be handed `instance_deadline - 5s`
    // unconditionally, and the fall-through pipeline was never told how much of
    // that it had actually spent. MEASURED on metaroom_2023 6cnn_ry_39_6
    // spec_idx_119 at its official 210 s budget: 188.7 s consumed for
    // `proved_unsat=false, strictly_positive=0/19`, then the internal verifier
    // re-derived `total_s=148.000 elapsed_s=0.000` with ~21 s left, overran, and
    // ny's own watchdog SIGKILLed it at 216 s with NO `Result:` line printed.
    // Two halves of one fix: `cz_hybrid.max_budget_fraction` bounds the lane,
    // and the handoff budget below is the LIVE remaining rather than the
    // original static grant.
    #[cfg(feature = "mip")]
    let ny_timeout = {
        let cz_lane_start = std::time::Instant::now();
        let cz_deadline = instance_deadline
            .checked_sub(std::time::Duration::from_secs(5))
            .unwrap_or(instance_deadline);
        // `None` (every shipped preset) keeps today's deadline exactly.
        // Validation refuses anything outside `(0.0, 1.0]`, and this filter is
        // the fail-closed second gate for a snapshot that bypassed it.
        let cz_deadline = match preset_snapshot
            .as_ref()
            .and_then(BetaCrownPresetSnapshot::loaded)
            .and_then(|loaded| loaded.cz_hybrid.max_budget_fraction)
            .filter(|frac| frac.is_finite() && *frac > 0.0 && *frac <= 1.0)
        {
            Some(frac) => {
                let window = instance_deadline
                    .saturating_duration_since(cz_lane_start)
                    .as_secs_f64()
                    * frac;
                cz_lane_start
                    .checked_add(std::time::Duration::from_secs_f64(window.max(0.0)))
                    .map_or(cz_deadline, |capped| capped.min(cz_deadline))
            }
            None => cz_deadline,
        };
        let lane = super::cz_metaroom_wired::evaluate(
            preset_snapshot
                .as_ref()
                .and_then(BetaCrownPresetSnapshot::loaded),
            &onnx,
            &vnnlib,
            cz_deadline,
        );
        crate::flight::note(
            "cz_hybrid_lane",
            if lane.engaged() {
                crate::flight::FlightStatus::Ran
            } else {
                crate::flight::FlightStatus::Skipped
            },
            Some(lane.receipt()),
        );
        if let super::cz_metaroom_wired::CzHybridLaneOutcome::ProvedUnsat { .. } = &lane {
            let result = VnncompResult::Unsat(UnsatReceipt::legacy_uncovered(
                LegacyUnsatAuthority::CzHybridLane,
            ));
            let owns_publication = claim_terminal_publication();
            if owns_publication
                && write_terminal_result(
                    &results_file,
                    short_grace_publisher.as_ref(),
                    result.clone(),
                )?
            {
                println!("Result: {}", result.token());
            }
            crate::flight::note(
                "result_publish",
                crate::flight::FlightStatus::Ran,
                Some(result.token().to_string()),
            );
            crate::flight::finish(result.token());
            crate::flight::global().write_sidecar(&results_file);
            close_proof_bundle(&result);
            return Ok(());
        }
        // The handoff. UNCONDITIONAL observable: the lane runs on every row
        // (two string compares when it is not allowlisted), so an absent line
        // means the binary has no budget handoff, not that the lane was idle.
        let lane_elapsed_s = cz_lane_start.elapsed().as_secs_f64();
        let instance_remaining_s = instance_deadline
            .saturating_duration_since(std::time::Instant::now())
            .as_secs_f64();
        // Never GREATER than what the instance actually has left. The floor of
        // 1 s keeps the downstream Duration arithmetic well-formed; the
        // absolute `instance_deadline` still gates every phase below.
        //
        // SCOPED TO AN ENGAGED LANE, deliberately. On every row the two-basename
        // allowlist does not match, the lane costs two string compares and this
        // must be byte-identical to the pre-change tree — so an idle lane hands
        // the ORIGINAL grant through untouched, and only a lane that actually
        // spent instance wall re-sizes the handoff.
        let handoff_budget_s =
            cz_hybrid_handoff_budget_secs(ny_timeout, instance_remaining_s, lane.engaged());
        eprintln!(
            "[cz-hybrid] budget lane_elapsed_s={lane_elapsed_s:.3} \
instance_remaining_s={instance_remaining_s:.3} handoff_budget_s={handoff_budget_s}"
        );
        handoff_budget_s
    };

    // Run β-CROWN in-process with the AUTO defaults and capture the verdict JSON.
    let beta_phase_deadline = beta_phase_deadline(timeout_decision, instance_deadline);
    let solver_phase_deadline = solver_phase_deadline(timeout_decision, instance_deadline);
    let result = run_and_translate(
        &onnx,
        &vnnlib,
        preset,
        ny_timeout,
        Some(instance_deadline),
        beta_phase_deadline,
        Some(solver_phase_deadline),
        postbab_wrapper_route,
        preset_snapshot,
        frozen_levers,
        margin_row_schedule_policy,
        global_rayon_outcome,
    );
    let result = normalize_vnnlib2_sat_result(&onnx, &vnnlib, result);
    // #sat-precedence (main-thread side): the post-BaB grace and the final
    // twin-wall join both `return res` verbatim, so a lane `unsat` can arrive
    // here on an instance whose counterexample the trusted oracle already
    // reconfirmed. A constructive witness outranks a bound-based claim; when the
    // witness itself could not be published, the outward answer is `unknown`,
    // not the verdict we have positive evidence against.
    // #attack-concurrent follow-up (b): on a run where a race SPAWNED, the
    // terminal publication synchronizes with any concurrent-attack
    // adjudication still in flight (the race's join is bounded, so one may
    // have outlived it): wait for it until the door's own deadline, close the
    // attack door, then filter + claim + write in ONE #sat-precedence
    // critical section. Every other run — the dark default, the short-grace
    // route (which never races) — takes the historical door below verbatim.
    let synchronized_door =
        crate::commands::beta_crown::attack_concurrent::live_threads_if_engaged()
            .filter(|_| short_grace_publisher.is_none());
    let (result, wrote) = if let Some(live) = synchronized_door {
        // Every race joined its scoped attack thread before its lane returned.
        debug_assert_eq!(
            live, 0,
            "a concurrent attack thread outlived its race scope"
        );
        let door = publish_main_verdict_in(
            &SAT_PRECEDENCE,
            &ATTACK_DOOR_CHANGED,
            &TERMINAL_PUBLICATION_CLAIMED,
            result,
            instance_deadline.checked_sub(MAIN_DOOR_PUBLISH_RESERVE),
            |result| write_terminal_result(&results_file, None, result.clone()),
        );
        let note = format!(
            "attack_concurrent_live_at_publish={live} door=synchronized waited_ms={} \
             inflight_at_close={} owns_publication={}",
            door.waited.as_millis(),
            door.inflight_at_close,
            u8::from(door.owns_publication),
        );
        eprintln!("[attack-concurrent] main-door {note}");
        crate::flight::note(
            "attack_concurrent_publish",
            crate::flight::FlightStatus::Ran,
            Some(note),
        );
        if !door.owns_publication {
            eprintln!(
                "vnncomp: terminal publication already claimed by a concurrent lane; leaving \
                 its verdict in place"
            );
        }
        let wrote = door.written.transpose()?.unwrap_or(false);
        (door.result, wrote)
    } else {
        let result = refuse_unsat_against_confirmed_counterexample(result);
        // #twinwall-early-exit: the concurrent lane may already have claimed the
        // single terminal publication right and be inside its `_exit(0)`. Losing
        // the claim means RESULTS_FILE holds the lane's certified `unsat`; writing
        // over it here would be the one way this feature could corrupt a verdict.
        let owns_publication = claim_terminal_publication();
        if !owns_publication {
            eprintln!(
                "vnncomp: terminal publication already claimed by the margin-row early exit; \
                 leaving its certified verdict in place"
            );
        }
        let wrote = owns_publication
            && write_terminal_result(
                &results_file,
                short_grace_publisher.as_ref(),
                result.clone(),
            )?;
        (result, wrote)
    };
    if wrote {
        // #batched-bab observability (see the sibling site): report whether
        // the wide domain-stacked GPU CROWN lane actually PUBLISHED here too —
        // this is the completion path a timing-out scored row takes.
        // #chain-wide: self-announcing on published>0, as at the sibling site.
        if beta_gpu_probe_armed() || ny_gpu::wide_resnet_batched_taken_count() > 0 {
            emit_wide_lane_readout();
        }
        println!("Result: {}", result.token());
    }
    // #alpha-steering-proposal: record actual proposal-channel dispatches in
    // the flight record (truthful outcome, not gate eligibility — the counter
    // increments only after accepted joint-adjoint gradients).
    let alpha_steering = ny_propagate::alpha_gradient_steering::telemetry();
    if alpha_steering.proposal_dispatches > 0 {
        crate::flight::note(
            "alpha_gradient_steering",
            crate::flight::FlightStatus::Ran,
            Some(format!(
                "source=wgpu_proposal dispatches={} backend={}",
                alpha_steering.proposal_dispatches,
                alpha_steering.backend.unwrap_or("unmaterialized"),
            )),
        );
    }
    // #binding-row-replay: record accepted CPU replay gradients the same way
    // (truthful outcome — the counter increments only after the margin lane
    // consumed the replay's gradients).
    if alpha_steering.replay_dispatches > 0 {
        crate::flight::note(
            "alpha_gradient_replay",
            crate::flight::FlightStatus::Ran,
            Some(format!(
                "source=cpu_replay dispatches={}",
                alpha_steering.replay_dispatches,
            )),
        );
    }
    // #forward-linear-cost-gate (I7): mirror the last cold-build admission
    // decision — calibrated rate + provenance, seam mode, predicted vs
    // remaining — into the sidecar. `None` means no deadline-carrying cold
    // build was ever considered (cache hit, non-conv category, or the 30 s
    // floor refused before the rate mattered).
    if let Some(admission) = ny_propagate::forward_linear_admission_record() {
        crate::flight::note(
            "forward_linear_admission",
            if admission.admitted {
                crate::flight::FlightStatus::Ran
            } else {
                crate::flight::FlightStatus::Skipped
            },
            Some(format!(
                "seam={} rate={}MACs source={} predicted={}s remaining={}s \
                 build_gmacs={} probe_gmacs={} probe_secs={:.3}",
                if admission.seam_f32 { "f32" } else { "f64" },
                admission.macs_per_sec,
                admission.rate_source,
                admission.predicted_secs,
                admission.remaining_secs,
                admission.build_macs / 1_000_000_000,
                admission.probe_macs / 1_000_000_000,
                admission.probe_secs,
            )),
        );
    }
    // #cprime-admission (I7): mirror collector walk-admission activity —
    // refusal/admission counts, reclaimed share seconds, and the numbers of
    // the last refusal — into the sidecar. `None` means no deadline-carrying
    // collection ever consulted the estimator.
    if let Some(walks) = ny_propagate::collector_walk_admission_record() {
        crate::flight::note(
            "collector_walk_admission",
            if walks.refused > 0 {
                crate::flight::FlightStatus::Skipped
            } else {
                crate::flight::FlightStatus::Ran
            },
            Some(format!(
                "admitted={} refused={} rollover_grants={} measured_grants={} \
                 reclaimed_share={:.1}s \
                 rate={}MACs correction={:.3}{} last_refused={}",
                walks.admitted,
                walks.refused,
                walks.rollover_grants,
                walks.measured_grants,
                walks.reclaimed_share_secs,
                walks.macs_per_sec,
                walks.correction,
                if walks.calibrated {
                    " (calibrated)"
                } else {
                    " (prior)"
                },
                walks
                    .last_refused_node
                    .as_deref()
                    .map(|node| {
                        format!(
                            "{node}[est={:.1}s share={:.1}s]",
                            walks.last_refused_estimate_secs, walks.last_refused_share_secs,
                        )
                    })
                    .unwrap_or_else(|| "none".to_string()),
            )),
        );
    }
    // #fl-value-gpu-tier (I7): whether the FL value dispatch consulted the
    // wgpu f32 tier this run, and how often it actually dispatched. calls=0
    // with an installed engine means every consult refused (size threshold /
    // budget / deadline) — the discriminating datum the 2026-08-02 wiring
    // hunt lacked.
    {
        let fl = ny_propagate::fl_value_gemm::telemetry_snapshot();
        if fl.calls > 0 || fl.backend.is_some() {
            crate::flight::note(
                "fl_value_gpu_tier",
                if fl.hits > 0 {
                    crate::flight::FlightStatus::Ran
                } else {
                    crate::flight::FlightStatus::Skipped
                },
                Some(format!(
                    "consults={} dispatches={} backend={}",
                    fl.calls,
                    fl.hits,
                    fl.backend.unwrap_or("uninitialized")
                )),
            );
        }
    }
    crate::flight::note(
        "result_publish",
        crate::flight::FlightStatus::Ran,
        Some(result.token().to_string()),
    );
    crate::flight::finish(result.token());
    crate::flight::global().write_sidecar(&results_file);
    close_proof_bundle(&result);
    Ok(())
}

/// #name-blind-routing: which verification route a row takes is decided by
/// the INSTANCE's own VNN-LIB structure, never by its category name.
///
/// A property that declares two or more networks (`declare-network`, VNN-LIB
/// 2.0) is relational: it constrains f and g jointly, and the single-network
/// lanes parse `declare-network` wrappers while ignoring their metadata, so
/// they must never see one. Such a property takes the dual-network route,
/// whose own full parse (`VnnLibSpec::dual_network`) and soundness gates then
/// validate the relation and fail closed to `unknown` on any shape they cannot
/// certify. Every other property — VNN-LIB 1.0 (no declaration) and ordinary
/// VNN-LIB 2.0 (one declaration) — takes the ordinary route.
///
/// This replaced `is_relational_category`, an exact match on
/// `isomorphic_acasxu_2026` / `monotonic_acasxu_2026`. The census in
/// `scratchpad/vbs/diag13/build_name-blind-routing.md` scans every scored
/// 2025/2026 property: all 100 rows of those two categories declare exactly
/// two networks, and no row of any other scored category declares more than
/// one, so the selected route is identical on every scored row. A renamed or
/// unseen relational benchmark now reaches the dual-network route instead of
/// single-network lanes that cannot read it.
///
/// The probe reads only the declaration prelude (up to the first assertion),
/// so it costs nothing measurable on the very large single-network properties
/// that must not pay for a second full parse. An unreadable property counts
/// zero networks and falls through to the ordinary route, which reports it.
///
/// #admission-census: `pub(crate)` so the census (`router::census`) asks the
/// SAME probe the scored entry point asks, never a copy of it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct RelationalRouteDecision {
    prelude: Option<ny_onnx::vnnlib::NetworkPrelude>,
}

impl RelationalRouteDecision {
    pub(crate) fn for_vnnlib(vnnlib: &Path) -> Self {
        Self {
            prelude: ny_onnx::vnnlib::load_vnnlib_network_prelude(vnnlib).ok(),
        }
    }

    pub(crate) fn declared_networks(self) -> usize {
        self.prelude.map_or(0, |prelude| prelude.declared_networks)
    }

    pub(crate) fn selected(self) -> bool {
        self.prelude
            .is_some_and(|prelude| prelude.is_multi_network())
    }

    /// Flight receipt for the route taken: the structural fact that chose it.
    fn receipt(self) -> String {
        format!(
            "dual-network property (declared_networks={}); standard lanes not applicable",
            self.declared_networks()
        )
    }
}

/// Bind every graph participating in one relational proof to the exact
/// receipt-owning authority captured at command entry.
///
/// Difference-network construction intentionally copies model topology only,
/// so this is the explicit handoff boundary for both source towers and their
/// stitched graph. Grouping the three assignments keeps a future relational
/// arm from silently leaving one graph on live compatibility readers.
fn attach_relational_frozen_authority(
    graph_a: &mut GraphNetwork,
    graph_b: &mut GraphNetwork,
    difference: &mut GraphNetwork,
    frozen_levers: &Option<std::sync::Arc<ny_levers::LeverSet>>,
) {
    for graph in [graph_a, graph_b, difference] {
        graph.set_frozen_levers(frozen_levers.clone());
    }
}

/// Carry a relational graph's exact authority into the verifier config that
/// may clone or reconfigure that graph for input-split BaB.
fn relational_bab_frozen_authority(
    graph: &GraphNetwork,
) -> Option<std::sync::Arc<ny_levers::LeverSet>> {
    graph.frozen_levers().cloned()
}

// REACHABLE ONLY FROM TESTS as of this commit. Every caller is inside a
// `#[cfg(test)]` block (this file's suite, plus `relational_equiv.rs`'s
// external-vnncomp smoke), so the lib build sees it as dead. It is NOT deleted:
// `relational_equiv.rs`'s own docs say "the vnncomp dispatch enters [this] ONLY
// for a relational category", i.e. the production dispatch arm is what is
// missing, and that is the implemented-but-unreachable defect class this repo
// treats as a bug to WIRE UP with measurement -- not one to resolve by deleting
// a verification lane. Allowed narrowly here so the finding stays visible at the
// site instead of being laundered through a crate-level allow.
#[allow(dead_code)]
pub(crate) fn run_relational_vnncomp(
    onnx_arg: &Path,
    vnnlib: &Path,
    timeout_secs: u64,
    // #scored-wall-clamp: the absolute instant this process owes a verdict by,
    // or `None` for the historical behaviour in which the BaB's own (possibly
    // inflated) deadline is also its stop. Threaded rather than re-derived:
    // the anchor is the COMMAND's entry, not this function's.
    scored_wall: Option<std::time::Instant>,
) -> Result<VnncompResult> {
    run_relational_vnncomp_with_frozen_levers(
        onnx_arg,
        vnnlib,
        timeout_secs,
        scored_wall,
        None,
        RelationalPresetKeys::default(),
        None,
    )
}

fn run_relational_vnncomp_with_frozen_levers(
    onnx_arg: &Path,
    vnnlib: &Path,
    timeout_secs: u64,
    scored_wall: Option<std::time::Instant>,
    frozen_levers: Option<std::sync::Arc<ny_levers::LeverSet>>,
    // #iso-edge-cap: typed preset values for the inline BaB config;
    // `Default` projects nothing.
    preset_keys: RelationalPresetKeys,
    overlap_publish: Option<relational_overlap::PublishTarget>,
) -> Result<VnncompResult> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Verify);
    if !vnnlib.is_file() {
        return Ok(VnncompResult::Error);
    }
    let vnnlib_spec = match ny_onnx::vnnlib::load_vnnlib(vnnlib) {
        Ok(spec) => spec,
        Err(err) => {
            eprintln!(
                "Relational VNN-LIB did not match a validated dual-network shortcut: {err}; returning sound unknown"
            );
            return Ok(VnncompResult::Unknown);
        }
    };
    let Some(dual) = vnnlib_spec.dual_network.as_ref() else {
        eprintln!(
            "VNN-LIB did not contain a validated dual-network relation; returning sound unknown"
        );
        return Ok(VnncompResult::Unknown);
    };
    // ARITHMETIC-ONLY EMPTY-UNSAFE-REGION SHORTCUT (runs BEFORE the
    // difference-network structural gate and BEFORE any ONNX load).
    //
    // For the isomorphic epsilon-equivalence shape the unsafe region is the
    // conjunction over outputs of
    //   (Y_g[i] - Y_f[i] >  +eps)  AND  (Y_g[i] - Y_f[i] <  -eps).
    // With eps > 0 a single such pair is already infeasible (Farkas multipliers
    // (1,1) collapse the two strict atoms to `-2·eps > 0`, a contradiction), so the
    // whole conjunction is empty: NO counterexample can exist for ANY f, g, or input
    // x. An empty unsafe region means the property holds and the unique correct
    // VNN-COMP verdict is `unsat`.
    //
    // This shortcut depends ONLY on the parsed OUTPUT-atom facts
    // (`isomorphic_output_safe_complement && !unsupported_output_relation`, every
    // index carries both the +eps Positive and -eps Negative STRICT deviation with
    // one shared eps) plus eps being exact-positive. It deliberately does NOT use the
    // input-bounds half of `dual_difference_soundness_gate`: the unsafe region is
    // empty regardless of any input box, weights, biases, or CROWN bound, so the
    // emptiness proof is independent of f and g entirely (zero wrong-unsat risk).
    //
    // We emit `unsat` ONLY after a freshly built, self-checked (`check_farkas`) exact
    // Farkas contradiction AND the certify facade's own re-check of the same
    // atoms (`certify::authorize_scalar_emptiness`, #spine-legacy-lanes), which
    // mints the instance token the verdict is published from. ANY failure
    // (wrong property kind, output shape not the validated strict
    // safe-complement, eps not exact-positive, cert does not self-check, the
    // facade refuses) falls through to today's exact behavior: the
    // difference-network structural gate followed by `Verified => Unknown`
    // (always sound).
    match try_prove_empty_isomorphic_unsafe_region(dual, vnnlib) {
        Ok(Some(receipt)) => {
            return Ok(VnncompResult::Unsat(receipt));
        }
        Ok(None) => {
            // Shortcut declined; continue to the sound difference-network path.
        }
        Err(reason) => {
            eprintln!(
                "Isomorphic emptiness shortcut self-check failed ({reason}); continuing to sound difference-network path"
            );
        }
    }

    // COUPLED-BOX SAT SEARCH for the monotonic relation (runs BEFORE the
    // difference-network soundness gate's g-bound finiteness check, which today
    // rejects the X_g[0]=+inf upper the coupling leaves open and forces `unknown`).
    //
    // For the `equal-to` monotonic property (e.g. `monotonic_acasxu_2026`'s
    // output-3 monotone in input-0) it can be
    // FALSE: a coupled point with X_f[0] >= X_g[0], X_f[k]==X_g[k] for k>=1 and
    // Y_f[3] < Y_g[3] is a genuine counterexample. We search the coupled space for
    // such a point, then emit `sat` ONLY after an INDEPENDENT forward pass of BOTH
    // original networks re-confirms the strict output violation with a margin (mirror
    // the MIP/SMT witness-revalidation discipline). A wrong `sat` is -150; on any
    // miss (no point, revalidation fails, structural mismatch, load error) we fall
    // THROUGH to today's exact behavior (the gate below, `Verified => unknown`),
    // which stays sound. The g-bound derivation only has to be finite-and-in-box for
    // the witness; soundness rides entirely on the dual forward-pass revalidation.
    match try_monotonic_coupled_sat(dual, onnx_arg, vnnlib) {
        Ok(Some(sat)) => return Ok(sat),
        Ok(None) => {
            // No revalidated counterexample found; continue to the sound gate path.
        }
        Err(reason) => {
            eprintln!(
                "Monotonic coupled-box SAT search produced no verdict ({reason}); continuing to sound gate path"
            );
        }
    }

    let gate = match dual_difference_soundness_gate(dual) {
        Ok(gate) => gate,
        Err(reason) => {
            // DEFENSE IN DEPTH (gate-flip hardening): the canonical SHAPE gate
            // is a spelling classifier, not the soundness authority — with the
            // implication lane enabled (default-on; `NY_RELATIONAL_UNSAT=0`
            // is the explicit kill-switch), a Verified
            // difference-network run can become `unsat` ONLY through the
            // certified `parsed ⇒ E` Farkas proof, which rejects any semantic
            // mismatch the shape gate would have caught (and much more). So
            // when the full formula DNF extracted and the minimal structural
            // facts hold, proceed to build + verify under the implication
            // authority instead of hard-declining on an unrecognized spelling.
            // With the explicit kill-switch set, keep the conservative decline.
            match implication_authority_gate_bypass(dual) {
                Some(gate) => {
                    eprintln!(
                        "Dual-network canonical shape gate declined ({reason}); proceeding under \
                         the enabled formula-implication authority"
                    );
                    gate
                }
                None => {
                    eprintln!(
                        "Dual-network shortcut not soundly validated: {reason}; returning unknown"
                    );
                    return Ok(VnncompResult::Unknown);
                }
            }
        }
    };

    let mut network_paths = resolve_relational_network_paths(onnx_arg, vnnlib)?;
    if network_paths.len() == 1 && gate.allows_single_network_reuse() {
        network_paths.push(network_paths[0].clone());
    }
    if network_paths.len() != 2 {
        eprintln!("Error: relational VNN-COMP instance must provide exactly two ONNX paths");
        return Ok(VnncompResult::Error);
    }
    for path in &network_paths {
        if !path.is_file() {
            eprintln!("Error: ONNX file not found: {}", path.display());
            return Ok(VnncompResult::Error);
        }
    }

    let ny_timeout = internal_timeout_secs(timeout_secs);

    let result = match gate.kind {
        DualDifferenceKind::Isomorphic { epsilon } => {
            let (mut graph_a, mut graph_b) = match load_relational_graphs_or_unknown(&network_paths)
            {
                Ok(graphs) => graphs,
                Err(result) => return Ok(result),
            };
            let mut diff = build_difference_network(&graph_a, &graph_b)?;
            attach_relational_frozen_authority(
                &mut graph_a,
                &mut graph_b,
                &mut diff,
                &frozen_levers,
            );
            let input_bounds = bounds_from_f64(&dual.f_input_bounds)?;
            let output_dim = infer_output_dim(&diff, &input_bounds)?;
            let output_bounds = match gate.output_bounds(output_dim) {
                Ok(bounds) => bounds,
                Err(reason) => {
                    eprintln!(
                        "Constructed isomorphic difference network failed soundness gate: {reason}; returning unknown"
                    );
                    return Ok(VnncompResult::Unknown);
                }
            };
            // ISOMORPHIC SAT FALSIFIER (mirrors the monotonic lane): search the
            // shared box for a strict epsilon-band violation and emit `sat`
            // ONLY after the independent dual-forward revalidation confirms it
            // with margin. Corner-seeded multiplicative ascent + EARLY EXIT:
            // a SAT witness short-circuits in seconds (the peak sits at a box
            // corner), so a generous cap only costs time on genuine UNSAT
            // instances (where the BaB is the decider anyway). The elapsed
            // time is charged against the BaB budget below; any miss falls
            // through to the sound verify path.
            let arm_deadline =
                std::time::Instant::now() + std::time::Duration::from_secs(ny_timeout.max(1));
            // The full search (grid + 200k uniform + ascent + gradient) reaches
            // the known witnesses in ~17s on a dev box; a genuine UNSAT instance
            // completes the same search (finds nothing) in the same ~17s and
            // returns immediately, so a generous cap costs UNSAT nothing while
            // giving the SAT search headroom on a slower machine.
            let falsifier_deadline = std::time::Instant::now()
                + std::time::Duration::from_secs((ny_timeout / 3).clamp(6, 30));
            let site_start = std::time::Instant::now();
            let overall_deadline = scored_wall.map_or(arm_deadline, |wall| wall.min(arm_deadline));
            let admitted = if preset_keys.attack_concurrent {
                relational_overlap::admit(
                    overlap_publish.as_ref(),
                    &diff,
                    site_start,
                    falsifier_deadline,
                    overall_deadline,
                )
            } else {
                None
            };
            if admitted.is_none() {
                if let Some(witness) = try_isomorphic_shared_sat_with_vjp(
                    &diff,
                    &graph_a,
                    &graph_b,
                    &network_paths[0],
                    &network_paths[1],
                    dual,
                    epsilon,
                    falsifier_deadline,
                    preset_keys.relational_point_vjp,
                ) {
                    return Ok(VnncompResult::Sat {
                        witness: Some(witness),
                    });
                }
            }
            let attack_diff = admitted.as_ref().map(|_| diff.clone());
            let proof = || -> Result<VnncompResult> {
                // Gate-flip authorization (default ON; NY_RELATIONAL_UNSAT=0 disables):
                // prove `parsed formula ⇒ the literally-verified region` with
                // self-checked Farkas certificates + a structural spot check of
                // the difference net. `None` on any miss ⇒ the Verified→unknown
                // gate below stays exactly as today.
                let unsat_auth = super::relational_equiv::try_authorize_relational_unsat(
                    dual.formula_dnf.as_ref(),
                    super::relational_equiv::CheckedKind::Isomorphic {
                        eps_hat: inward_nonnegative_f32(epsilon),
                        output_dim,
                    },
                    &diff,
                    &graph_a,
                    &graph_b,
                    &input_bounds,
                );
                // The native engine certifies the signed difference itself. Its
                // exact source-chain admission and complete input cover are both
                // necessary; the existing formula-implication authority remains
                // necessary before a proof may become a protocol verdict.
                if let Some(options) = preset_keys.paired_difference {
                    if options.max_seconds.is_finite()
                        && options.max_seconds > 0.0
                        && options.max_seconds <= 90.0
                        && options.max_domains > 0
                        && options.max_domains <= 2_000_000
                        && options.max_lp_seconds.is_finite()
                        && options.max_lp_seconds >= 0.0
                        && options.max_lp_seconds <= options.max_seconds
                        && (16..=2_048).contains(&options.lp_memory_mib)
                        && (1..=100_000).contains(&options.lp_steps)
                        && (1..=16).contains(&options.workers)
                        && ny_core::require_f64_interval_proof_environment().is_ok()
                        && unsat_auth.is_some()
                        && super::relational_equiv::relational_unsat_enabled()
                    {
                        match ny_propagate::paired_difference::PairedChain::from_graphs(
                            &graph_a,
                            &graph_b,
                            input_bounds.len(),
                        ) {
                            Ok(chain) => {
                                let domain = ny_propagate::paired_difference::BoxDomain {
                                    lo: input_bounds.iter().map(|b| f64::from(b.lower())).collect(),
                                    hi: input_bounds.iter().map(|b| f64::from(b.upper())).collect(),
                                };
                                let now = std::time::Instant::now();
                                let mut deadline = (now
                                    + std::time::Duration::from_secs_f64(options.max_seconds))
                                .min(arm_deadline);
                                if let Some(wall) = scored_wall {
                                    deadline = deadline.min(wall);
                                }
                                eprintln!("[paired-difference] armed source=preset max_domains={} live_seconds={:.3}", options.max_domains, deadline.saturating_duration_since(now).as_secs_f64());
                                let workers =
                                    ny_propagate::paired_difference::ParallelWorkers::new(
                                        options.workers,
                                    )
                                    .expect("worker count validated above");
                                let band_epsilon = f64::from(inward_nonnegative_f32(epsilon));
                                if options.max_lp_seconds > 0.0 {
                                    let lp_now = std::time::Instant::now();
                                    let lp_deadline = (lp_now
                                        + std::time::Duration::from_secs_f64(
                                            options.max_lp_seconds,
                                        ))
                                    .min(deadline);
                                    if lp_now < lp_deadline {
                                        if try_paired_lp_prepass(
                                            &chain,
                                            &domain,
                                            band_epsilon,
                                            options,
                                            lp_deadline,
                                            workers,
                                        ) && std::time::Instant::now() < lp_deadline
                                        {
                                            return authorized_unsat_or_unknown(unsat_auth, vnnlib);
                                        }
                                    }
                                }
                                // An LP miss retains the same complete root. Input
                                // splitting uses only the remaining paired budget.
                                let proof = chain.prove_refined_parallel(
                                    &domain,
                                    band_epsilon,
                                    deadline,
                                    options.max_domains,
                                    true,
                                    workers,
                                );
                                eprintln!("[paired-difference] done proved={} evaluated={} closed={} open={} reason={} worst_closed_bound={:.17e} elapsed_s={:.6}", proof.proved, proof.evaluated, proof.closed, proof.open, proof.reason, proof.worst_closed_bound, proof.elapsed.as_secs_f64());
                                if proof.proved && std::time::Instant::now() < deadline {
                                    return authorized_unsat_or_unknown(unsat_auth, vnnlib);
                                }
                            }
                            Err(reason) => {
                                eprintln!("[paired-difference] declined reason={reason}")
                            }
                        }
                    } else {
                        eprintln!("[paired-difference] declined reason=invalid_budget_or_missing_formula_authority");
                    }
                }
                // BaB-`Violated` counterexamples (the shared 5-D point) go through
                // the SAME independent dual-forward revalidation as the falsifier
                // (internal pre-filter + trusted ORT confirmation).
                let revalidate = |candidate: &[f32]| {
                    revalidate_isomorphic_witness(
                        &graph_a,
                        &graph_b,
                        &network_paths[0],
                        &network_paths[1],
                        candidate,
                        dual,
                        epsilon,
                    )
                };
                let remaining_secs = arm_deadline
                    .saturating_duration_since(std::time::Instant::now())
                    .as_secs()
                    .max(1);
                // Arm the coupled-δ leaf oracle (default-off; NY_REL_COUPLED_DELTA=1)
                // from the ISOMORPHIC source towers, before `input_bounds` is moved.
                let coupled_oracle = super::coupled_delta::coupled_delta_oracle_from_env(
                    &graph_a,
                    &graph_b,
                    &diff,
                    &input_bounds,
                );
                verify_difference_bounds(
                    diff,
                    input_bounds,
                    output_bounds,
                    remaining_secs,
                    scored_wall,
                    unsat_auth,
                    vnnlib,
                    Some(&revalidate),
                    coupled_oracle,
                    preset_keys,
                )
            };
            if let Some(admitted) = admitted {
                let attack_diff = attack_diff.expect("admitted race has its source attack graph");
                relational_overlap::run(
                    admitted,
                    overlap_publish.expect("admitted publisher"),
                    &attack_diff,
                    &graph_a,
                    &graph_b,
                    &network_paths[0],
                    &network_paths[1],
                    dual,
                    epsilon,
                    site_start,
                    falsifier_deadline,
                    overall_deadline,
                    preset_keys.relational_point_vjp,
                    proof,
                )
            } else {
                proof()
            }
        }
        DualDifferenceKind::Monotonic { varying_input, .. } => {
            let (mut graph_a, mut graph_b) = match load_relational_graphs_or_unknown(&network_paths)
            {
                Ok(graphs) => graphs,
                Err(result) => return Ok(result),
            };
            let (mut diff, input_bounds) =
                build_monotonic_difference_network(&graph_a, &graph_b, dual, varying_input)?;
            attach_relational_frozen_authority(
                &mut graph_a,
                &mut graph_b,
                &mut diff,
                &frozen_levers,
            );
            let output_dim = infer_output_dim(&diff, &input_bounds)?;
            let output_bounds = match gate.output_bounds(output_dim) {
                Ok(bounds) => bounds,
                Err(reason) => {
                    eprintln!(
                        "Constructed monotonic difference network failed soundness gate: {reason}; returning unknown"
                    );
                    return Ok(VnncompResult::Unknown);
                }
            };
            // Gate-flip authorization for the monotonic arm (same discipline;
            // `lb` is the literal safe-bound lower the verifier enforces).
            let unsat_auth = match gate.kind {
                DualDifferenceKind::Monotonic { output, .. } => {
                    super::relational_equiv::try_authorize_relational_unsat(
                        dual.formula_dnf.as_ref(),
                        super::relational_equiv::CheckedKind::Monotonic {
                            output,
                            lb: output_bounds
                                .get(output)
                                .map(|b| b.lower())
                                .unwrap_or(f32::NAN),
                        },
                        &diff,
                        &graph_a,
                        &graph_b,
                        &input_bounds,
                    )
                }
                DualDifferenceKind::Isomorphic { .. } => None,
            };
            // BaB-`Violated` counterexamples (the coupled 6-D diff point) go
            // through the SAME independent decompose-and-dual-forward
            // revalidation the coupled SAT search uses.
            let mono_output = match gate.kind {
                DualDifferenceKind::Monotonic { output, .. } => output,
                DualDifferenceKind::Isomorphic { .. } => 0,
            };
            let revalidate = |candidate: &[f32]| -> Option<String> {
                let point: [f32; 6] = candidate.try_into().ok()?;
                match revalidate_monotonic_witness(
                    &graph_a,
                    &graph_b,
                    &network_paths[0],
                    &network_paths[1],
                    &point,
                    dual,
                    varying_input,
                    mono_output,
                ) {
                    Ok(Some((xf, xg, yf, yg))) => {
                        relational_counterexample_vnnlib(dual, &xf, &xg, &yf, &yg).ok()
                    }
                    _ => None,
                }
            };
            verify_difference_bounds(
                diff,
                input_bounds,
                output_bounds,
                ny_timeout,
                scored_wall,
                unsat_auth,
                vnnlib,
                Some(&revalidate),
                // Monotonic lane: the coupled-δ oracle targets the isomorphic
                // pair structure; not armed here.
                None,
                preset_keys,
            )
        }
    }?;
    Ok(result)
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct DualDifferenceGate {
    declared_output_dim: usize,
    kind: DualDifferenceKind,
}

#[derive(Debug, Clone, Copy)]
enum DualDifferenceKind {
    Isomorphic {
        epsilon: f64,
    },
    Monotonic {
        output: usize,
        varying_input: usize,
        strict_unsafe: bool,
    },
}

impl DualDifferenceGate {
    /// One ONNX may stand for both f and g exactly when the property itself
    /// says g IS f: the monotonic gate is minted only from a
    /// `(declare-network g (equal-to f) ...)` declaration
    /// (`NetworkRelation::EqualTo` -> `DualNetworkProperty::MonotonicGreaterEq`),
    /// so reusing the single supplied network is what the spec declares, not
    /// an assumption. An `isomorphic-to` pair relates two DIFFERENT networks
    /// and must supply both (#name-blind-routing: this used to additionally
    /// require the literal category `monotonic_acasxu_2026`, which every
    /// `equal-to` row in the scored corpus carries).
    fn allows_single_network_reuse(&self) -> bool {
        matches!(self.kind, DualDifferenceKind::Monotonic { .. })
    }

    fn output_bounds(&self, actual_output_dim: usize) -> std::result::Result<Vec<Bound>, String> {
        if actual_output_dim != self.declared_output_dim {
            return Err(format!(
                "network output dim {actual_output_dim} does not match VNN-LIB output dim {}",
                self.declared_output_dim
            ));
        }
        match self.kind {
            DualDifferenceKind::Isomorphic { epsilon } => {
                let eps = inward_nonnegative_f32(epsilon);
                Ok((0..actual_output_dim)
                    .map(|_| Bound::new(-eps, eps))
                    .collect())
            }
            DualDifferenceKind::Monotonic {
                output,
                strict_unsafe,
                ..
            } => {
                if output >= actual_output_dim {
                    return Err(format!(
                        "monotonic output index {output} out of bounds for {actual_output_dim}"
                    ));
                }
                let mut output_bounds =
                    vec![
                        Bound::new_allow_infinite(f32::NEG_INFINITY, f32::INFINITY);
                        actual_output_dim
                    ];
                output_bounds[output] =
                    monotonic_safe_output_bound_for_unsafe_relation(strict_unsafe);
                Ok(output_bounds)
            }
        }
    }
}

/// Minimal-validation fallback gate for an UNRECOGNIZED-spelling isomorphic
/// spec, usable ONLY under the formula-implication authority (defense in
/// depth for the gate flip).
///
/// Returns `Some(gate)` only when ALL of:
///   * the implication lane is enabled (default-on; `NY_RELATIONAL_UNSAT=0`
///     is the explicit kill-switch, which keeps the conservative decline);
///   * the property is `isomorphic-to` epsilon-equivalence (below) — this is
///     the whole scope; it used to also require the literal category
///     `isomorphic_acasxu_2026` (#name-blind-routing), which every
///     `isomorphic-to` row in the scored corpus carries;
///   * the FULL formula DNF extracted (`formula_dnf` present — the implication
///     proof's input; without it no `unsat` could ever be authorized anyway);
///   * the property parsed as epsilon-equivalence with a finite `eps >= 0`
///     (ε̂ is known) and every input is equality-coupled with finite matching
///     boxes (the shared-input difference net models the coupled space);
///   * declared dims are consistent and both boxes are finite.
///
/// SOUNDNESS: this bypass only widens where the difference network is BUILT
/// and VERIFIED. The verdict surface is unchanged: `Verified` still maps to
/// `unsat` ONLY with the `RelationalUnsatAuth` token (per-pair Farkas
/// certificates, `check_farkas`-re-checked, plus the structural spot check),
/// and everything else stays `unknown`. A semantic mismatch the shape gate
/// would have caught makes the implication proof fail — gate stays down.
/// The monotonic arm is NOT bypassed (its builder carries additional
/// structural requirements and the live blocker is isomorphic-only).
fn implication_authority_gate_bypass(dual: &DualNetworkSpec) -> Option<DualDifferenceGate> {
    if !super::relational_equiv::relational_unsat_enabled() {
        return None;
    }
    dual.formula_dnf.as_ref()?;
    let DualNetworkProperty::EpsilonEquivalence { epsilon } = dual.property else {
        return None;
    };
    if !epsilon.is_finite() || epsilon < 0.0 {
        return None;
    }
    let declared_input_dim = declared_dual_input_dim(dual).ok()?;
    let declared_output_dim = declared_dual_output_dim(dual).ok()?;
    if dual.f_input_bounds.len() != declared_input_dim
        || dual.g_input_bounds.len() != declared_input_dim
    {
        return None;
    }
    if !dual.shared_input_coupling
        || !dual.validation.input_equalities.iter().all(|c| *c)
        || dual.f_input_bounds != dual.g_input_bounds
    {
        return None;
    }
    validate_dual_bounds(&dual.f_input_bounds, "f").ok()?;
    validate_dual_bounds(&dual.g_input_bounds, "g").ok()?;
    Some(DualDifferenceGate {
        declared_output_dim,
        kind: DualDifferenceKind::Isomorphic { epsilon },
    })
}

/// Comprehensive structural gate for the dual-network difference shortcut.
///
/// `unsat` from this path means the verifier proved bounds on a constructed
/// difference network. That is sound only when every VNN-LIB assumption used to
/// construct that network has been explicitly validated:
///
/// * isomorphic: every input is explicitly coupled by `X_f[i] == X_g[i]`, f/g
///   boxes match exactly, and the output formula is built from the canonical
///   same-index strict epsilon-deviation atoms covering every output (the
///   canonical complement is DISJUNCTIVE — or-of-ors in the real 2026 files —
///   and any and/or combination of the validated atoms is a subset of their
///   union, which the band proof refutes atom-by-atom);
/// * monotonic: every non-varying input is explicitly coupled with matching
///   f/g boxes, the varying input has the `X_f[0] >= X_g[0]` direction that
///   matches the `f_o >= g_o` safe complement, and the output formula is one
///   canonical same-index monotonic unsafe comparison;
/// * the returned gate is the only object allowed to build output bounds, so
///   actual network dimensions are checked before verification can emit `unsat`.
///
/// The arm is selected by the PARSED PROPERTY alone (#name-blind-routing). The
/// property kind is itself structural: `isomorphic-to` mints
/// `EpsilonEquivalence`, `equal-to` mints `MonotonicGreaterEq`
/// (`parse_dual_network_spec`). The gate used to pair each arm with its literal
/// category name as well; in the scored corpus every `isomorphic-to` row is an
/// `isomorphic_acasxu_2026` row and every `equal-to` row a
/// `monotonic_acasxu_2026` row, so dropping the name admits exactly the same
/// rows, and every structural check below is unchanged.
pub(crate) fn dual_difference_soundness_gate(
    dual: &DualNetworkSpec,
) -> std::result::Result<DualDifferenceGate, String> {
    let declared_input_dim = declared_dual_input_dim(dual)?;
    let declared_output_dim = declared_dual_output_dim(dual)?;
    validate_dual_relation_targets(dual)?;
    if dual.f_input_bounds.len() != declared_input_dim
        || dual.g_input_bounds.len() != declared_input_dim
        || dual.validation.input_equalities.len() != declared_input_dim
        || dual.validation.f_input_ge_g_input.len() != declared_input_dim
        || dual.validation.g_input_ge_f_input.len() != declared_input_dim
    {
        return Err(
            "parsed dual-network validation vectors do not match declared input dim".into(),
        );
    }
    validate_dual_bounds(&dual.f_input_bounds, "f")?;
    validate_dual_bounds(&dual.g_input_bounds, "g")?;

    match &dual.property {
        DualNetworkProperty::EpsilonEquivalence { epsilon } => {
            if !epsilon.is_finite() || *epsilon < 0.0 {
                return Err("isomorphic epsilon must be finite and non-negative".into());
            }
            if !dual.shared_input_coupling
                || !dual
                    .validation
                    .input_equalities
                    .iter()
                    .all(|coupled| *coupled)
                || dual.f_input_bounds != dual.g_input_bounds
            {
                return Err(
                    "isomorphic difference network requires explicit equality coupling and matching bounds for every input"
                        .into(),
                );
            }
            if dual.validation.unsupported_output_relation
                || !dual.validation.isomorphic_output_safe_complement
            {
                return Err(
                    "isomorphic output relation is not the validated same-index strict epsilon complement"
                        .into(),
                );
            }
            Ok(DualDifferenceGate {
                declared_output_dim,
                kind: DualDifferenceKind::Isomorphic { epsilon: *epsilon },
            })
        }
        DualNetworkProperty::MonotonicGreaterEq {
            output,
            varying_input,
            strict_unsafe,
        } => {
            if declared_input_dim != 5 || *varying_input != 0 {
                return Err("only canonical ACAS monotonic input-0 specs are validated".into());
            }
            if *output >= declared_output_dim {
                return Err(format!(
                    "monotonic output index {output} out of declared range {declared_output_dim}"
                ));
            }
            for idx in 0..declared_input_dim {
                if idx == *varying_input {
                    continue;
                }
                if !dual.validation.input_equalities[idx]
                    || dual.f_input_bounds[idx] != dual.g_input_bounds[idx]
                {
                    return Err(format!(
                        "monotonic non-varying input {idx} lacks explicit equality coupling with matching bounds"
                    ));
                }
            }
            if !dual.validation.f_input_ge_g_input[*varying_input] {
                return Err(format!(
                    "monotonic varying input {varying_input} must explicitly assert X_f >= X_g"
                ));
            }
            if dual.validation.unsupported_output_relation
                || dual.validation.monotonic_output_relation_count != 1
            {
                return Err(
                    "monotonic output relation is not exactly one validated same-index unsafe comparison"
                        .into(),
                );
            }
            let (_, f_upper) = dual.f_input_bounds[*varying_input];
            let (g_lower, _) = dual.g_input_bounds[*varying_input];
            if !f_upper.is_finite() || !g_lower.is_finite() || f_upper < g_lower {
                return Err(
                    "monotonic varying-input delta bounds are not finite and non-negative".into(),
                );
            }
            Ok(DualDifferenceGate {
                declared_output_dim,
                kind: DualDifferenceKind::Monotonic {
                    output: *output,
                    varying_input: *varying_input,
                    strict_unsafe: *strict_unsafe,
                },
            })
        }
        _ => Err("dual-network property is not a validated dual-network shortcut".into()),
    }
}

fn declared_dual_input_dim(dual: &DualNetworkSpec) -> std::result::Result<usize, String> {
    let Some(first) = dual.networks.first() else {
        return Err("dual-network spec has no declared networks".into());
    };
    if dual
        .networks
        .iter()
        .any(|network| network.input_dim != first.input_dim)
    {
        return Err("dual-network declared input dimensions do not match".into());
    }
    Ok(first.input_dim)
}

fn declared_dual_output_dim(dual: &DualNetworkSpec) -> std::result::Result<usize, String> {
    let Some(first) = dual.networks.first() else {
        return Err("dual-network spec has no declared networks".into());
    };
    if dual
        .networks
        .iter()
        .any(|network| network.output_dim != first.output_dim)
    {
        return Err("dual-network declared output dimensions do not match".into());
    }
    Ok(first.output_dim)
}

fn validate_dual_relation_targets(dual: &DualNetworkSpec) -> std::result::Result<(), String> {
    if dual.networks.len() != 2 {
        return Err("dual-network shortcut requires exactly two declared networks".into());
    }
    let mut relation_count = 0usize;
    for (idx, network) in dual.networks.iter().enumerate() {
        let Some((relation, target)) = &network.relation_to else {
            continue;
        };
        relation_count += 1;
        let counterpart = &dual.networks[1 - idx];
        if target != &counterpart.name {
            return Err(format!(
                "network '{}' relation target '{}' is not counterpart '{}'",
                network.name, target, counterpart.name
            ));
        }
        let relation_matches_property = matches!(
            (relation, &dual.property),
            (
                ny_onnx::vnnlib::NetworkRelation::IsomorphicTo,
                DualNetworkProperty::EpsilonEquivalence { .. }
            ) | (
                ny_onnx::vnnlib::NetworkRelation::EqualTo,
                DualNetworkProperty::MonotonicGreaterEq { .. }
            )
        );
        if !relation_matches_property {
            return Err(format!(
                "network '{}' relation kind does not match parsed dual-network property",
                network.name
            ));
        }
    }
    if relation_count == 0 {
        return Err("dual-network shortcut requires an explicit network relation".into());
    }
    Ok(())
}

fn validate_dual_bounds(
    bounds: &[(f64, f64)],
    network_name: &str,
) -> std::result::Result<(), String> {
    for (idx, (lower, upper)) in bounds.iter().enumerate() {
        if !lower.is_finite() || !upper.is_finite() || lower > upper {
            return Err(format!(
                "{network_name} input {idx} has invalid bounds [{lower}, {upper}]"
            ));
        }
    }
    Ok(())
}

fn resolve_relational_network_paths(onnx_arg: &Path, vnnlib: &Path) -> Result<Vec<PathBuf>> {
    if onnx_arg.is_file() {
        return Ok(vec![onnx_arg.to_path_buf()]);
    }
    let field = onnx_arg.to_string_lossy();
    let names = network_paths_from_field(&field);
    let base = vnnlib
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    names
        .into_iter()
        .map(|name| Ok(resolve_relational_network_path(&base, &name)))
        .collect()
}

fn resolve_relational_network_path(base: &Path, name: &str) -> PathBuf {
    let path = Path::new(name);
    let direct = if path.is_absolute() {
        path.to_path_buf()
    } else {
        base.join(path)
    };
    if direct.exists() {
        return direct;
    }
    let direct_gz = with_gz_suffix(&direct);
    if direct_gz.exists() {
        return direct_gz;
    }

    for subdir in ["onnx", ""] {
        let candidate = base.join(subdir).join(path);
        if candidate.exists() {
            return candidate;
        }
        let candidate_gz = with_gz_suffix(&candidate);
        if candidate_gz.exists() {
            return candidate_gz;
        }
    }

    if name.starts_with("onnx/original/") {
        if let Some(file_name) = path.file_name() {
            let fallback = base.join("onnx").join(file_name);
            if fallback.exists() {
                return fallback;
            }
            let fallback_gz = with_gz_suffix(&fallback);
            if fallback_gz.exists() {
                return fallback_gz;
            }
        }
    }

    direct
}

fn with_gz_suffix(path: &Path) -> PathBuf {
    let mut name = path.as_os_str().to_os_string();
    name.push(".gz");
    PathBuf::from(name)
}

fn monotonic_safe_output_bound_for_unsafe_relation(strict_unsafe: bool) -> Bound {
    let lower = if strict_unsafe {
        // Unsafe is f_i < g_i, so the closed complement f_i - g_i >= 0 is safe.
        0.0
    } else {
        // Unsafe is f_i <= g_i, so equality is unsafe. A closed verifier objective
        // is sound only if it proves a strictly positive margin.
        ny_tensor::next_up_f32(0.0)
    };
    Bound::new_allow_infinite(lower, f32::INFINITY)
}

fn network_paths_from_field(field: &str) -> Vec<String> {
    let mut paths = Vec::new();
    let mut rest = field.trim();
    while let Some(end_rel) = rest.find(".onnx") {
        let mut end_idx = end_rel + ".onnx".len();
        if rest[end_idx..].starts_with(".gz") {
            end_idx += ".gz".len();
        }
        let prefix = &rest[..end_idx];
        let start_idx = prefix
            .rfind(|ch: char| {
                ch == '\'' || ch == '"' || ch == '(' || ch == '[' || ch == ',' || ch.is_whitespace()
            })
            .map(|idx| idx + 1)
            .unwrap_or(0);
        paths.push(prefix[start_idx..].trim().to_string());
        rest = &rest[end_idx..];
    }
    paths
}

/// Load BOTH relational networks, or degrade to a sound `unknown` (FAIL-CLOSED
/// MODEL LOADING). With the formula-implication lane default-on, the relational
/// path reaches model loading even for specs the canonical shape gate would
/// have declined, and a verdict must never depend on an unloadable model: a
/// load failure here is a broken/unreadable model file, not a verification
/// result, so the only sound outcome is `unknown` (mirrors the single-network
/// MODEL-LOAD-FAILURE demotion, loud marker included).
fn load_relational_graphs_or_unknown(
    network_paths: &[PathBuf],
) -> std::result::Result<(GraphNetwork, GraphNetwork), VnncompResult> {
    let mut graphs = Vec::with_capacity(2);
    for path in &network_paths[..2] {
        // Proof authority for `RelationalImplication`: the certified lowering
        // (every authored BatchNormalization kept; #spine-legacy-lanes M2e).
        match load_certified_graph_network(path) {
            Ok(graph) => graphs.push(graph),
            Err(err) => {
                eprintln!(
                    "NY-HARNESS: MODEL-LOAD-FAILURE — relational model {} did not load \
                     ({err}); the `unknown` below is a BROKEN MODEL FILE, not a \
                     verification result",
                    path.display()
                );
                return Err(VnncompResult::Unknown);
            }
        }
    }
    let graph_b = graphs.pop().expect("two graphs");
    let graph_a = graphs.pop().expect("two graphs");
    Ok((graph_a, graph_b))
}

/// Load an ONNX model as a `GraphNetwork` (the dual-network / ground-truth
/// difference path loader; also reused by `ny gt verify`).
pub(crate) fn load_graph_network(path: &Path) -> Result<GraphNetwork> {
    let (graph, _) = load_graph_network_retaining_model(path, false)?;
    Ok(graph)
}

/// As [`load_graph_network`], optionally handing back the parsed
/// [`ny_onnx::OnnxModel`] the conversion was made from.
///
/// The flag exists so the historical caller keeps its exact memory profile:
/// with `retain_model == false` the model is dropped at the end of this
/// function exactly as before, and nothing is live across the caller's search
/// that was not live at HEAD. It is set only by a caller that has a use for
/// the model — currently the dark pre-Softmax attack-objective admission,
/// which needs the graph-level metadata the guard reads and must not pay for a
/// SECOND load of the same file to get it.
pub(crate) fn load_graph_network_retaining_model(
    path: &Path,
    retain_model: bool,
) -> Result<(GraphNetwork, Option<ny_onnx::OnnxModel>)> {
    // Crash-isolate ORT shape inference (see `cli_shape_infer_backend`).
    let load_config = OnnxLoadConfig::default()
        .with_shape_infer_backend(crate::commands::cli_shape_infer_backend());
    let model = load_onnx_with_config(path, &load_config)?;
    let options = GraphNetworkOptions {
        compound_node_policy: CompoundNodePolicy::DecomposeNormalization,
        ..GraphNetworkOptions::default()
    };
    let graph = model.to_graph_network_with_options(options)?;
    Ok((graph, retain_model.then_some(model)))
}

/// #soundness-spine M2e / #spine-legacy-lanes: load a model whose
/// `GraphNetwork` an `unsat` lane uses as PROOF AUTHORITY, through
/// [`OnnxLoadConfig::certified_graph_lowering`]. That lowering keeps every
/// authored BatchNormalization node as a certified `BatchNormLayer` (outward
/// binary64 enclosure of the exact affine, `scale_err`/`bias_err` charged)
/// instead of folding it into the preceding Conv/Gemm with the composed
/// coefficient enclosure DROPPED (`fusion/batch_norm_fold.rs`).
///
/// Otherwise identical to [`load_graph_network`] (same shape-inference
/// backend, same compound-node policy), so on a model with no
/// BatchNormalization — every model its callers' benchmarks carry today — the
/// graph is byte-identical.
pub(crate) fn load_certified_graph_network(path: &Path) -> Result<GraphNetwork> {
    let load_config = OnnxLoadConfig::default()
        .with_shape_infer_backend(crate::commands::cli_shape_infer_backend())
        .certified_graph_lowering();
    debug_assert!(load_config.admits_certified_graph_lowering());
    let model = load_onnx_with_config(path, &load_config)?;
    let options = GraphNetworkOptions {
        compound_node_policy: CompoundNodePolicy::DecomposeNormalization,
        ..GraphNetworkOptions::default()
    };
    Ok(model.to_graph_network_with_options(options)?)
}

fn directed_lower_f32(v: f64) -> f32 {
    f64_to_f32_down(v)
}

fn directed_upper_f32(v: f64) -> f32 {
    f64_to_f32_up(v)
}

pub(crate) fn inward_nonnegative_f32(v: f64) -> f32 {
    debug_assert!(v.is_finite() && v >= 0.0);
    if v == 0.0 {
        0.0
    } else {
        directed_lower_f32(v).max(0.0)
    }
}

/// Round a DECLARED lower bound INWARD (up) to f32 so a clamped witness is
/// guaranteed `>= declared_lower` even after the f64->f32 cast. Used when emitting a
/// counterexample witness so the organizer's exact re-check `(>= X v)` passes.
fn inward_lower_f32(v: f64) -> f32 {
    f64_to_f32_up(v)
}

/// Round a DECLARED upper bound INWARD (down) to f32 so a clamped witness is
/// guaranteed `<= declared_upper` even after the f64->f32 cast.
fn inward_upper_f32(v: f64) -> f32 {
    f64_to_f32_down(v)
}

/// Clamp `v` into `[lo, hi]` without panicking on a degenerate/NaN box
/// (`f32::clamp` panics when `lo > hi`). Falls back to `lo` for an inverted box.
fn clamp_f32(v: f32, lo: f32, hi: f32) -> f32 {
    if lo <= hi {
        v.clamp(lo, hi)
    } else {
        lo
    }
}

/// Build an INWARD-rounded f32 `Bound` from a declared `(lower, upper)` f64 box, so a
/// point sampled inside it is guaranteed to satisfy the organizer's EXACT re-check of
/// the declared asserts. For a DEGENERATE declared box (`lower == upper`, a fixed
/// equality constant) inward rounding from both sides would invert the bound, so we
/// collapse it to the single nearest f32 instead.
fn inward_bound((lower, upper): (f64, f64)) -> Bound {
    if lower == upper {
        let v = lower as f32;
        return Bound::new(v, v);
    }
    let lo = inward_lower_f32(lower);
    let hi = inward_upper_f32(upper);
    if lo <= hi {
        Bound::new(lo, hi)
    } else {
        // Inward rounding crossed (extremely narrow box): collapse to a single f32
        // guaranteed within the declared box.
        // `(l+u)*0.5` kept verbatim: this collapse produces the input box the
        // verifier runs on — `f64::midpoint` differs at overflow edges and the
        // produced bound must not move (the clamp guarantees in-box either way).
        #[allow(clippy::manual_midpoint)]
        let mid = clamp_f32(((lower + upper) * 0.5) as f32, lower as f32, upper as f32);
        Bound::new(mid, mid)
    }
}

pub(crate) fn bounds_from_f64(bounds: &[(f64, f64)]) -> Result<Vec<Bound>> {
    bounds
        .iter()
        .enumerate()
        .map(|(idx, (lower, upper))| {
            finite_bound_from_f64(*lower, *upper)
                .with_context(|| format!("input bound {idx} is not finite after f32 rounding"))
        })
        .collect()
}

pub(crate) fn finite_bound_from_f64(lower: f64, upper: f64) -> Result<Bound> {
    if !lower.is_finite() || !upper.is_finite() || lower > upper {
        anyhow::bail!("invalid finite bound [{lower}, {upper}]");
    }
    let lower = directed_lower_f32(lower);
    let upper = directed_upper_f32(upper);
    if !lower.is_finite() || !upper.is_finite() {
        anyhow::bail!("bound endpoint overflows finite f32 range");
    }
    Ok(Bound::new(lower, upper))
}

fn infer_output_dim(graph: &GraphNetwork, input_bounds: &[Bound]) -> Result<usize> {
    let input = Verifier::bounds_to_tensor(input_bounds, None)?;
    Ok(graph.propagate_ibp(&input)?.lower().len())
}

/// Convert an `f64` epsilon to its EXACT dyadic rational. Non-finite values and
/// a poisoned exact-rational arena fail closed.
fn epsilon_to_exact_rat(eps: f64) -> Option<Rat> {
    Rat::from_f64_exact(eps)
}

/// Convert one REAL parsed deviation atom `t = Y_g[i] - Y_f[i] ⋈ c` into the
/// exact ny-cert [`LinearConstraint`] over named variables `yg_i`, `yf_i`,
/// preserving the atom's SIGNED constant exactly. Returns `None` for a
/// non-finite constant or an unhealthy exact-rational arena.
///
/// This is the load-bearing soundness primitive: the constraint is built from
/// the atom's REAL `(relation, constant)` — never a `±eps` template — so a
/// Farkas combination over these constraints proves emptiness of the ACTUAL
/// region or fails.
fn atom_to_constraint(atom: &IsomorphicOutputAtom) -> Option<LinearConstraint> {
    let yg = format!("yg_{}", atom.index);
    let yf = format!("yf_{}", atom.index);
    let constant = epsilon_to_exact_rat(atom.constant)?;
    let kind = match atom.relation {
        IsomorphicAtomRelation::Gt => ConstraintKind::Gt,
        IsomorphicAtomRelation::Lt => ConstraintKind::Lt,
        IsomorphicAtomRelation::Ge => ConstraintKind::Ge,
        IsomorphicAtomRelation::Le => ConstraintKind::Le,
    };
    Some(LinearConstraint::with_kind(
        kind,
        &[(yg.as_str(), Rat::ONE), (yf.as_str(), Rat::ONE.neg())],
        constant,
    ))
}

/// Build a Farkas infeasibility certificate for one output index from its REAL
/// parsed deviation atoms (the `idx_atoms` slice, all sharing `atom.index`).
///
/// The certificate is the non-negative combination (multipliers all `1`) of the
/// index's constraints. For the canonical strict-strict safe complement
///   A1:  `Y_g[i] - Y_f[i] > c_gt`   (`Gt`)
///   A2:  `Y_g[i] - Y_f[i] < c_lt`   (`Lt`)
/// with coeffs `{yg_i:+1, yf_i:-1}`, the multipliers `(1,1)` cancel both
/// variables and leave the strict residual `0 < c_lt - c_gt`, a contradiction
/// iff `c_lt <= c_gt` — which holds for the REAL region (`c_gt=+eps`,
/// `c_lt=-eps`) but FAILS for a crafted feasible region (`c_gt=-eps`,
/// `c_lt=+eps`), where `check_farkas` then returns an error and we decline.
///
/// Returns `None` if any atom's signed constant is non-finite or the rational
/// arena is unhealthy (caller then declines to `unknown`). The returned
/// certificate is NOT yet self-checked; the caller runs [`check_farkas`] over
/// it.
fn build_isomorphic_index_cert(idx_atoms: &[&IsomorphicOutputAtom]) -> Option<FarkasCertificate> {
    let mut constraints = Vec::with_capacity(idx_atoms.len());
    for atom in idx_atoms {
        constraints.push(atom_to_constraint(atom)?);
    }
    let multipliers = vec![Rat::ONE; constraints.len()];
    Some(FarkasCertificate {
        constraints,
        multipliers,
    })
}

/// Decide whether the isomorphic epsilon-equivalence unsafe region is provably
/// EMPTY, backing the decision with an exact, self-checked Farkas certificate
/// built from the REAL parsed output atoms.
///
/// Returns `Ok(Some(receipt))` (=> caller publishes `unsat`) ONLY when ALL of
/// the following hold:
///   * `dual.property` is `EpsilonEquivalence` (an `isomorphic-to` declaration;
///     this replaced a literal `isomorphic_acasxu_2026` category test,
///     #name-blind-routing);
///   * the top-level output structure is a CONJUNCTION
///     (`isomorphic_output_is_conjunction == true`) — a disjunctive `|t| > eps`
///     region is feasible and must NEVER be proved empty (BUG 2 guard);
///   * `unsupported_output_relation == false` and the parsed atoms cover EVERY
///     output index with a real strict-strict safe-complement
///     (`isomorphic_output_safe_complement == true`);
///   * for EVERY output index, a Farkas certificate built from THAT index's REAL
///     signed atoms passes the in-tree `check_farkas` contradiction check. The
///     real signed constants drive the residual, so a feasible region (e.g.
///     `t > -eps ∧ t < +eps`, BUG 1) fails the check and we DECLINE;
///   * #spine-legacy-lanes: the certify facade re-checks the SAME real atoms
///     (`certify::authorize_scalar_emptiness`: per index, a lower and an upper
///     atom that no value of `t` satisfies together, by exact comparison) and
///     mints the instance-scoped token the receipt is built from. The replay
///     above and the facade must AGREE; a facade refusal after a passing replay
///     declines and prints `[cover-gate] REFUSED`.
///
/// On `Ok(Some(_))` the certificate sidecar JSON is written next to `vnnlib`.
///
/// Returns `Ok(None)` whenever any structural precondition is not met, an
/// atom's constant cannot enter the exact arena, or a built certificate does
/// NOT prove a contradiction (the shortcut declines; caller falls through to
/// the sound difference-network path => `unknown`). It NEVER returns `Err` for
/// an unprovable region — only a genuine, self-checked contradiction yields
/// `unsat`.
fn try_prove_empty_isomorphic_unsafe_region(
    dual: &DualNetworkSpec,
    vnnlib: &Path,
) -> std::result::Result<Option<UnsatReceipt>, String> {
    let DualNetworkProperty::EpsilonEquivalence { .. } = dual.property else {
        return Ok(None);
    };
    let validation = &dual.validation;
    // BUG 2 GUARD: the unsafe region must be a CONJUNCTION. A disjunction
    // (`(or (t>eps) (t<-eps))`, i.e. `|t| > eps`) is feasible for distinct f/g,
    // so the property does NOT hold and `unsat` would be wrong. Decline.
    if !validation.isomorphic_output_is_conjunction {
        return Ok(None);
    }
    // The OUTPUT atoms must be exactly the validated strict same-index epsilon
    // safe-complement for EVERY output index, with no unsupported output relation.
    if validation.unsupported_output_relation || !validation.isomorphic_output_safe_complement {
        return Ok(None);
    }
    // We must have at least one real parsed atom to certify from; an empty atom
    // set could only ever vacuously "prove" emptiness, which we refuse.
    if validation.isomorphic_output_atoms.is_empty() {
        return Ok(None);
    }

    let output_dim = declared_dual_output_dim(dual)?;
    if output_dim == 0 {
        return Ok(None);
    }

    // Group the REAL parsed atoms by output index. Every declared output index
    // must carry atoms whose Farkas combination proves a contradiction; the
    // whole conjunctive region is empty iff some index's atoms are jointly
    // infeasible, but we require ALL indices' certs to self-check so the emitted
    // cert set is complete and there is no unindexed (uncovered) output.
    let mut certs = Vec::with_capacity(output_dim);
    let mut groups: Vec<Vec<ScalarAtom>> = Vec::with_capacity(output_dim);
    for index in 0..output_dim {
        let idx_atoms: Vec<&IsomorphicOutputAtom> = validation
            .isomorphic_output_atoms
            .iter()
            .filter(|atom| atom.index == index)
            .collect();
        // Every declared output index must be covered by real atoms; an
        // uncovered index means the parsed region is not the full per-index
        // safe complement we can certify — decline rather than guess.
        if idx_atoms.is_empty() {
            return Ok(None);
        }
        // Build the certificate from the REAL signed atoms and verify it proves
        // a contradiction of the ACTUAL region. If construction fails
        // (non-finite constant or unhealthy arena) or the contradiction does
        // NOT hold (feasible / wrong-sign region, BUG 1), we DECLINE to
        // `unknown` — never `unsat`.
        let Some(cert) = build_isomorphic_index_cert(&idx_atoms) else {
            return Ok(None);
        };
        if check_farkas(&cert).is_err() {
            return Ok(None);
        }
        certs.push((index, cert));
        groups.push(
            idx_atoms
                .iter()
                .map(|&atom| isomorphic_scalar_atom(atom))
                .collect(),
        );
    }
    if certs.is_empty() {
        return Ok(None);
    }
    // The facade's own re-check of the same atoms mints the token; the lane's
    // `check_farkas` replay above is kept, and both must agree.
    let receipt = match ny_propagate::certify::authorize_scalar_emptiness(&groups) {
        Ok(token) => {
            let min_slack = token.min_margin();
            let Some(receipt) = UnsatReceipt::from_token(token) else {
                eprintln!(
                    "[cover-gate] REFUSED scope=instance lane=isomorphic_emptiness \
                     token_not_publishable"
                );
                return Ok(None);
            };
            eprintln!(
                "[cover-gate] authorized scope=instance lane=isomorphic_emptiness groups={} \
                 min_slack={min_slack:.6e}",
                groups.len()
            );
            receipt
        }
        Err(refusal) => {
            eprintln!(
                "[cover-gate] REFUSED scope=instance lane=isomorphic_emptiness {refusal} \
                 (the check_farkas replay passed: the two checks disagree; declining)"
            );
            return Ok(None);
        }
    };

    println!(
        "Isomorphic unsafe region proven EMPTY by exact Farkas certificate over the REAL parsed output atoms ({} output indices); returning unsat",
        certs.len()
    );

    // Best-effort sidecar emission. Writing the audit JSON must NEVER change the
    // verdict: the cert already self-checked, so a filesystem failure only suppresses
    // the sidecar, it does not make us fall back from a proven `unsat`.
    if let Err(reason) = write_isomorphic_emptiness_cert(&certs, vnnlib) {
        eprintln!("warning: failed to write isomorphic emptiness certificate sidecar: {reason}");
    }
    Ok(Some(receipt))
}

/// One parsed isomorphic deviation atom `t ⋈ c` as the certify facade's
/// scalar atom (same relation, same REAL signed constant, no conversion).
fn isomorphic_scalar_atom(atom: &IsomorphicOutputAtom) -> ScalarAtom {
    let rel = match atom.relation {
        IsomorphicAtomRelation::Gt => ScalarRel::Gt,
        IsomorphicAtomRelation::Lt => ScalarRel::Lt,
        IsomorphicAtomRelation::Ge => ScalarRel::Ge,
        IsomorphicAtomRelation::Le => ScalarRel::Le,
    };
    ScalarAtom {
        rel,
        constant: atom.constant,
    }
}

/// Serialize the self-checked per-index Farkas certificates to a sidecar JSON next
/// to the VNN-LIB file (`<vnnlib>.cert.json`), in the canonical ny-cert
/// `farkas_certificate` schema Clean's external-certificate verifier consumes.
fn write_isomorphic_emptiness_cert(
    certs: &[(usize, FarkasCertificate)],
    vnnlib: &Path,
) -> std::result::Result<(), String> {
    let mut entries = Vec::with_capacity(certs.len());
    for (index, cert) in certs {
        let json = farkas_to_json(cert)
            .map_err(|e| format!("farkas index {index} not serialisable: {e}"))?;
        // BRIDGE: ny-cert's bounded `Json` carries no serde impls by design;
        // re-parse its canonical rendering for this serde_json payload.
        let json: serde_json::Value = serde_json::from_str(&json.to_string())
            .map_err(|e| format!("farkas index {index} JSON bridge: {e}"))?;
        entries.push(serde_json::json!({
            "output_index": index,
            "farkas": json,
        }));
    }
    let payload = serde_json::json!({
        "format": "ny-cert/isomorphic-empty-unsafe-region/v1",
        "claim":
            "the isomorphic epsilon-equivalence unsafe region is empty: for every output i the \
             conjunction of the REAL parsed deviation atoms over t = Y_g[i]-Y_f[i] is infeasible \
             (a non-negative Farkas combination of the actual signed atoms yields a strict \
             contradiction), so no counterexample exists and the property holds (unsat)",
        "conclusion": "contradiction",
        "vnnlib": vnnlib.display().to_string(),
        "certificates": entries,
    });
    let text = serde_json::to_string_pretty(&payload)
        .map_err(|e| format!("failed to serialise sidecar: {e}"))?;
    let out_path = sidecar_cert_path(vnnlib);
    fs::write(&out_path, text)
        .map_err(|e| format!("failed to write sidecar to {}: {e}", out_path.display()))?;
    println!(
        "Wrote exact Farkas emptiness certificate ({} output indices) to {}",
        certs.len(),
        out_path.display()
    );
    Ok(())
}

/// The `<vnnlib>.cert.json` sidecar path (appends `.cert.json`, preserving the
/// full VNN-LIB filename so it is unambiguous which instance the cert backs).
fn sidecar_cert_path(vnnlib: &Path) -> PathBuf {
    let mut name = vnnlib
        .file_name()
        .map(|n| n.to_os_string())
        .unwrap_or_default();
    name.push(".cert.json");
    vnnlib.with_file_name(name)
}

/// RELATIONAL BAB opt-out: `NY_RELATIONAL_BAB=0` restores the historical
/// single root α-CROWN pass. Default ON — the single pass converges at
/// lower_sum ≈ -33298 vs the needed ±0.05 band on the real isomorphic
/// instances (independent relaxations of both copies through ACASXU-scale
/// internal ranges); the 5-D shared input is exactly ny's input-split BaB
/// regime (acasxu_2023: 178/186).
fn relational_bab_enabled() -> bool {
    std::env::var("NY_RELATIONAL_BAB").ok().as_deref() != Some("0")
}

/// Convert the difference network's verified-band output box into the
/// disjunctive-unsafe clause form the input-split BaB lane consumes: one
/// SINGLE-ROW clause per finite box side —
///   * finite lower `L` on output `i`  →  unsafe atom `h_i < L`, refuted by
///     proving `min h_i > L`   (row `+e_i`, threshold `L`);
///   * finite upper `U` on output `i`  →  unsafe atom `h_i > U`, refuted by
///     proving `min -h_i > -U` (row `-e_i`, threshold `-U`).
///
/// `Verified` from the BaB lane ⇒ every clause refuted on every subdomain ⇒
/// the union of band-violation atoms is empty over the input box — EXACTLY
/// the region `E` the formula-implication authorization was built against
/// (the BaB refutation is strict `>`, one-sidedly STRONGER than the closed
/// band, so the `E` claim still holds). Returns `None` when no finite side
/// exists (nothing to verify — caller falls back to the single-pass path).
#[allow(clippy::type_complexity)]
fn band_clauses_from_output_bounds(
    output_bounds: &[Bound],
) -> Option<(Vec<Vec<f32>>, Vec<f32>, Vec<usize>)> {
    let n = output_bounds.len();
    let mut objectives: Vec<Vec<f32>> = Vec::new();
    let mut thresholds: Vec<f32> = Vec::new();
    for (i, b) in output_bounds.iter().enumerate() {
        let mut row = |sign: f32, threshold: f32| {
            let mut r = vec![0.0f32; n];
            r[i] = sign;
            objectives.push(r);
            thresholds.push(threshold);
        };
        if b.lower().is_finite() {
            row(1.0, b.lower());
        }
        if b.upper().is_finite() {
            row(-1.0, -b.upper());
        }
    }
    if objectives.is_empty() || thresholds.iter().any(|t| !t.is_finite()) {
        return None;
    }
    let clause_sizes = vec![1usize; objectives.len()];
    Some((objectives, thresholds, clause_sizes))
}

/// The gate-flip verdict for a difference-network `Verified`: `unsat` ONLY
/// with the `RelationalUnsatAuth` token (see `verify_difference_bounds`),
/// else the sound `unknown`. Shared by the BaB and single-pass lanes.
fn authorized_unsat_or_unknown(
    unsat_auth: Option<super::relational_equiv::RelationalUnsatAuth>,
    vnnlib: &Path,
) -> Result<VnncompResult> {
    match unsat_auth {
        Some(auth) => {
            println!(
                "Relational difference-network proof AUTHORIZED as unsat by the \
                 formula-implication certificate chain"
            );
            if let Err(reason) = super::relational_equiv::write_implication_sidecar(
                &auth,
                vnnlib,
                &sidecar_cert_path(vnnlib),
            ) {
                eprintln!("warning: failed to write implication sidecar: {reason}");
            }
            Ok(VnncompResult::Unsat(UnsatReceipt::legacy_uncovered(
                LegacyUnsatAuthority::RelationalImplication,
            )))
        }
        None => Ok(VnncompResult::Unknown),
    }
}

/// One latched whole-net finisher reservation. The same normalized slice is
/// used to shorten BaB and bound the finisher, while `overall_deadline` stays
/// anchored to the caller's original budget (it never slides after BaB).
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RelWholeMipPlan {
    slice: std::time::Duration,
    bab_timeout: std::time::Duration,
    bab_deadline: std::time::Instant,
    overall_deadline: std::time::Instant,
}

/// Pure reservation arithmetic for the relational whole-net MILP finisher.
///
/// Fail closed on every activation precondition: the optional lane must be
/// compiled, explicitly armed, and capable of authorizing an UNSAT verdict.
/// The requested slice is normalized once and then shared by BaB and the
/// finisher. BaB keeps at least one quarter of the budget; if that leaves less
/// than the finisher's one-second minimum, the optional lane stays disarmed.
fn compute_rel_whole_mip_plan(
    budget: std::time::Duration,
    overall_deadline: std::time::Instant,
    mip_available: bool,
    authorized: bool,
    explicitly_armed: bool,
    requested_slice: Option<&str>,
) -> Option<RelWholeMipPlan> {
    if !mip_available || !authorized || !explicitly_armed {
        return None;
    }

    const DEFAULT_SLICE: std::time::Duration = std::time::Duration::from_mins(1);
    const MIN_SLICE: std::time::Duration = std::time::Duration::from_secs(1);

    let bab_floor = budget / 4;
    let max_slice = budget.checked_sub(bab_floor)?;
    if max_slice < MIN_SLICE {
        return None;
    }

    let requested_secs = requested_slice
        .and_then(|raw| raw.parse::<f64>().ok())
        .filter(|secs| secs.is_finite() && *secs > 0.0);
    let requested = match requested_secs {
        Some(secs) => {
            // A syntactically valid but unrepresentably large finite value is
            // an explicit request for the largest admissible slice.
            std::time::Duration::try_from_secs_f64(secs).unwrap_or(max_slice)
        }
        // Missing, malformed, non-positive, and non-finite values retain the
        // historical 60-second default.
        None => DEFAULT_SLICE,
    };
    let slice = requested.max(MIN_SLICE).min(max_slice);
    let bab_timeout = budget.checked_sub(slice)?;
    let bab_deadline = overall_deadline.checked_sub(slice)?;
    Some(RelWholeMipPlan {
        slice,
        bab_timeout,
        bab_deadline,
        overall_deadline,
    })
}

/// Read the two rollout variables once and latch a coherent plan for the
/// entire BaB -> finisher sequence. Environment changes during verification
/// cannot create a reservation/finisher mismatch.
fn rel_whole_mip_plan_from_env(
    budget: std::time::Duration,
    overall_deadline: std::time::Instant,
    authorized: bool,
) -> Option<RelWholeMipPlan> {
    if !cfg!(feature = "mip") || !authorized {
        return None;
    }
    let explicitly_armed = std::env::var("NY_REL_WHOLE_MIP").ok().as_deref() == Some("1");
    if !explicitly_armed {
        return None;
    }
    let requested_slice = std::env::var("NY_REL_WHOLE_MIP_SLICE_S").ok();
    compute_rel_whole_mip_plan(
        budget,
        overall_deadline,
        true,
        true,
        true,
        requested_slice.as_deref(),
    )
}

const DEFAULT_REL_BAB_DEADLINE_MULT: f64 = 1.4;

/// Parse the relational BaB convergence-trajectory multiplier.
///
/// Only finite values in the reviewed inclusive range are accepted. An unset
/// or invalid direct invocation retains the scored default; measurement runs
/// validate and seal the raw value before launching the solver.
fn parse_rel_bab_deadline_mult(raw: Option<&str>) -> f64 {
    raw.and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite() && *value >= 1.0 && *value <= 10.0)
        .unwrap_or(DEFAULT_REL_BAB_DEADLINE_MULT)
}

/// Apply the convergence-trajectory multiplier without consuming an armed
/// whole-MIP finisher reservation. Supplying `preserve_whole_mip_reservation`
/// means the incoming timeout/deadline already encode the fixed reserved slice.
fn apply_rel_bab_deadline_mult(
    bab_timeout: std::time::Duration,
    bab_deadline: std::time::Instant,
    multiplier: f64,
    preserve_whole_mip_reservation: bool,
    now: std::time::Instant,
) -> (std::time::Duration, std::time::Instant) {
    if preserve_whole_mip_reservation || multiplier <= 1.0 {
        return (bab_timeout, bab_deadline);
    }
    (
        bab_timeout.mul_f64(multiplier),
        now + bab_deadline
            .saturating_duration_since(now)
            .mul_f64(multiplier),
    )
}

/// #rel-whole-mip: the last-resort WHOLE-NET certified MILP finisher on the
/// difference network. Fires ONLY when `NY_REL_WHOLE_MIP=1` (default OFF —
/// today's 530-binary root MILP times out) AND the implication token is
/// present (a `Verified` here can only ever become `unsat` through that
/// token). Returns `true` iff the whole band is CERTIFIED-UNSAT (tree_cert
/// admits any-k; ay's uncertified UNSAT is never admitted). Fail-open: any
/// miss ⇒ `false`, caller keeps the inconclusive BaB verdict.
#[cfg(feature = "mip")]
fn try_whole_net_diff_finisher(
    graph: &GraphNetwork,
    input_bounds: &[Bound],
    objectives: &[Vec<f32>],
    thresholds: &[f32],
    unsat_auth: &Option<super::relational_equiv::RelationalUnsatAuth>,
    plan: Option<RelWholeMipPlan>,
) -> bool {
    // No token ⇒ the flip is unauthorizable anyway; don't spend the slice.
    if unsat_auth.is_none() {
        return false;
    }
    let Some(plan) = plan else {
        return false;
    };
    let slice = plan.slice.as_secs_f64();
    let rows: Vec<(Vec<f32>, f32)> = objectives
        .iter()
        .cloned()
        .zip(thresholds.iter().copied())
        .collect();
    super::beta_crown::whole_net_certified_band_unsat(
        graph,
        input_bounds,
        &rows,
        slice,
        Some(plan.overall_deadline),
    )
}

/// Non-mip build: the whole-net MILP lane is unavailable — always fail-open.
#[cfg(not(feature = "mip"))]
fn try_whole_net_diff_finisher(
    _graph: &GraphNetwork,
    _input_bounds: &[Bound],
    _objectives: &[Vec<f32>],
    _thresholds: &[f32],
    _unsat_auth: &Option<super::relational_equiv::RelationalUnsatAuth>,
    _plan: Option<RelWholeMipPlan>,
) -> bool {
    false
}

#[allow(clippy::too_many_arguments)]
fn verify_difference_bounds(
    graph: GraphNetwork,
    input_bounds: Vec<Bound>,
    output_bounds: Vec<Bound>,
    timeout_secs: u64,
    // #scored-wall-clamp: the command-anchored absolute stop, or `None` for the
    // historical single-deadline behaviour. NOTE that `timeout_secs` above has
    // already been re-anchored twice by the time it arrives (the arm's own
    // `Instant::now()`, then this function's `deadline`), which is exactly why
    // the wall is threaded as an instant instead of being re-derived here.
    scored_wall: Option<std::time::Instant>,
    unsat_auth: Option<super::relational_equiv::RelationalUnsatAuth>,
    vnnlib: &Path,
    sat_revalidator: Option<&dyn Fn(&[f32]) -> Option<String>>,
    // Optional coupled-δ leaf oracle (isomorphic lane only; default-off, armed by
    // `NY_REL_COUPLED_DELTA=1`). Composed ahead of the exact Graph-MIP edge
    // oracle so the cheap sound bound decides most near-verified deep domains.
    coupled_oracle: Option<
        std::sync::Arc<dyn ny_propagate::beta_crown::graph_mip_leaf::GraphMipLeafOracle>,
    >,
    // #iso-edge-cap: typed values projected from the category preset for the
    // inline config below (`RelationalPresetKeys`); `Default` projects nothing.
    preset_keys: RelationalPresetKeys,
) -> Result<VnncompResult> {
    // RELATIONAL BAB (default ON, `NY_RELATIONAL_BAB=0` opts out): run the
    // FULL input-split BaB machinery — the acasxu_2023-winning configuration
    // (`BetaCrownConfig::acas_xu`) on the multi-clause disjunctive lane —
    // instead of a single root pass. The verdict surface is unchanged:
    //   * `Verified`  → the same token-gated flip as the single pass;
    //   * `Violated`  → `sat` ONLY when the INDEPENDENT dual-forward
    //     revalidator confirms the counterexample against the ORIGINAL
    //     networks with margin (never trust the stitched net alone);
    //   * anything else / any error → `unknown`/`timeout` (0-wrong: every
    //     miss degrades soundly, including a hard fallback to the historical
    //     single-pass path on a BaB error).
    if relational_bab_enabled() {
        if let Some((objectives, thresholds, clause_sizes)) =
            band_clauses_from_output_bounds(&output_bounds)
        {
            let budget = std::time::Duration::from_secs(timeout_secs.max(1));
            let deadline = std::time::Instant::now() + budget;
            // Relational-lane tuning on top of the acasxu-winning base
            // (#relational-bab profiling of the 26 iso timeouts):
            //   * batch_size 16384 -> 2048: the loop pops a whole batch, spends
            //     one batched rebound on it, and only THEN checks the wall -
            //     a 16384-wide terminal batch burned ~16s of a 92s run after
            //     the deadline (children never generated, work discarded).
            //     2048 caps that waste at ~2s and pops closer to best-first.
            //   * post_bab_pgd_fraction 0: this lane runs its own revalidated
            //     falsifier up front and the BaB-internal PGD attack; the 10%
            //     post-BaB PGD reservation would only shorten the proof phase.
            //   * max_domains 2M (from 100k): the measured proof trees run
            //     ~100-250k domains at ~1k dps; the default cap would turn a
            //     converging proof into Unknown.
            //   * collection-verify shortcut (lever 1): the ±e_i band spec
            //     backward is BIT-IDENTICAL to the per-domain CROWN-IBP
            //     collection's output entry (measured), so verified domains
            //     skip it — ~40% of rebound time at the frontier where most
            //     popped domains verify.
            //   * disjunctive multi-dim split (lever 2): honor
            //     input_split_depth=2 (top-2 SB dims, 4 children/pop) in the
            //     multi-clause lane, mirroring the conjunctive lane.
            //   * edge-domain MILP escalation (#relational-bab): near-verified
            //     deep domains (the plain-CROWN relaxation floor from boundary
            //     -unstable neuron PAIRS that splitting never eliminates) are
            //     DECIDED exactly by the certified-UNSAT-only Graph-MIP leaf
            //     solver instead of splitting forever. Gates env-tunable:
            //     NY_REL_EDGE_MILP_GAP (default 0.01), NY_REL_EDGE_MILP_DEPTH
            //     (default 20); NY_REL_EDGE_MILP=0 disarms.
            let edge_gap = std::env::var("NY_REL_EDGE_MILP_GAP")
                .ok()
                .and_then(|v| v.parse::<f32>().ok())
                .filter(|g| g.is_finite() && *g > 0.0)
                .unwrap_or(0.01);
            let edge_depth = std::env::var("NY_REL_EDGE_MILP_DEPTH")
                .ok()
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(20);
            //   * α-slope edge pass (option B, #relational-bab): per-domain
            //     α-CROWN on near-verified deep domains before splitting —
            //     the measured 1e-3..1e-1 α-over-plain gain covers most of
            //     the −0.0002..−0.03 relaxation floor the certified MILP
            //     cannot reach at k≈80 free binaries. NY_REL_EDGE_ALPHA=0
            //     disarms; NY_REL_EDGE_ALPHA_TOP caps passes per wave;
            //     NY_REL_EDGE_ALPHA_ITERS tunes the ascent length.
            let edge_alpha = std::env::var("NY_REL_EDGE_ALPHA").ok().as_deref() != Some("0");
            let edge_alpha_top = std::env::var("NY_REL_EDGE_ALPHA_TOP")
                .ok()
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(256);
            let edge_alpha_iters = std::env::var("NY_REL_EDGE_ALPHA_ITERS")
                .ok()
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(25);
            // #rel-whole-mip budget reservation: latch one coherent plan only
            // when the MIP lane is compiled, explicitly armed, AND carries the
            // implication token needed to authorize its result. The same safe,
            // normalized slice shortens both BaB's timeout and absolute deadline;
            // the finisher remains anchored to `deadline`, so BaB overshoot cannot
            // slide the overall scored budget. Default OFF (or no token/non-MIP)
            // preserves the historical `budget` / `deadline` values exactly.
            let whole_mip_plan =
                rel_whole_mip_plan_from_env(budget, deadline, unsat_auth.is_some());
            let bab_timeout = whole_mip_plan
                .map(|plan| plan.bab_timeout)
                .unwrap_or(budget);
            let bab_deadline = whole_mip_plan
                .map(|plan| plan.bab_deadline)
                .unwrap_or(deadline);
            // #relational-bab CONVERGENCE-TRAJECTORY knob (default 1.4).
            // MEASURED (2026-07-21): the disjunctive input-split BaB is
            // NON-MONOTONIC in the internal `bab_timeout` — a LARGER internal
            // deadline yields a SMALLER, converging tree (instance_4: budget=100
            // times out at ~149k domains, but budget≥120 VERIFIES at ~61s BaB /
            // 136k domains). The per-domain bound effort is deadline-shaped, so a
            // nearer deadline produces looser per-domain bounds → more splits →
            // non-convergence. Inflating the INTERNAL bab_timeout/deadline past
            // the scored budget restores the converging trajectory; converging
            // instances finish well under the real wall (~77s), and non-
            // converging ones are still bounded by the outer scored wall (the
            // scored-budget+5s watchdog caps any mult, verified at mult=2.0 →
            // 105s wall). Sound: the UNSAT verdict is only returned on a fully-
            // closed certified tree — running the search longer never fabricates
            // a verdict; the 0-wrong moat is untouched.
            //
            // VALIDATED (default 1.4) STACKED with the mimalloc global allocator
            // (~8% BaB speedup, ny-cli/main.rs) on the iso_acasxu 100s scored
            // shape: +4 holdouts CLOSE — instance_4 (~71s), instance_34 (~74s),
            // instance_49 (~91s), instance_25 (~99s); 31→35 / 50. The mimalloc
            // speedup was what opened the overlap: without it, 34 needed mult≤1.3
            // and 49/25 needed mult≥1.5 (no single value closed both); the ~8%
            // faster BaB widened both windows so mult=1.4 clears all four (34 at
            // 1.5+ still times out — 1.4 is the sweet spot). 34/49 robust (~74-
            // 91s), i25 borderline (~99s, closes here, safer on faster eval HW).
            // Zero corpus regression. `NY_REL_BAB_DEADLINE_MULT` accepts a
            // finite value in [1.0, 10.0] (1.0 = the historical no-op); an
            // unset or invalid direct invocation uses the 1.4 scored default.
            // An armed whole-MIP plan already shortened BaB to reserve its
            // finisher slice, so that fixed reservation takes precedence.
            let bab_deadline_mult = parse_rel_bab_deadline_mult(
                std::env::var("NY_REL_BAB_DEADLINE_MULT").ok().as_deref(),
            );
            let (bab_timeout, bab_deadline) = apply_rel_bab_deadline_mult(
                bab_timeout,
                bab_deadline,
                bab_deadline_mult,
                whole_mip_plan.is_some(),
                std::time::Instant::now(),
            );
            let bab = BetaCrownVerifier::new(BetaCrownConfig {
                frozen_levers: relational_bab_frozen_authority(&graph),
                timeout: bab_timeout,
                // #scored-wall-clamp. `bab_timeout` above has just been
                // multiplied by 1.4 and is now an EFFORT HORIZON that
                // deliberately overshoots the scored budget — that inflation is
                // what keeps this non-monotonic search on a converging
                // trajectory, and removing it loses rows. The wall is the other
                // half of the same fix: the loop stops here regardless of how
                // far the horizon reaches, so the trajectory is bought with
                // bound quality instead of with wall-clock the process does not
                // own. `None` (unarmed, and every non-relational caller) leaves
                // stop == horizon, i.e. exactly today's behaviour.
                input_split_scored_wall: scored_wall,
                batch_size: 2048,
                // Diagnostic knob (default-preserving): cap BaB domains so it
                // hands off early to the NY_REL_WHOLE_MIP finisher instead of
                // consuming the whole budget. Unset ⇒ the shipped 2M cap.
                max_domains: std::env::var("NY_REL_BAB_MAX_DOMAINS")
                    .ok()
                    .and_then(|v| v.parse::<usize>().ok())
                    .unwrap_or(2_000_000),
                input_split_collection_verify_shortcut: true,
                input_split_disjunctive_multi_dim: true,
                input_split_edge_milp: true,
                input_split_edge_milp_gap: edge_gap,
                input_split_edge_milp_depth: edge_depth,
                input_split_edge_alpha: edge_alpha,
                input_split_edge_alpha_top: edge_alpha_top,
                input_split_edge_alpha_iters: edge_alpha_iters,
                // #iso-edge-cap: bound the serial edge work above by the
                // scored stop and a per-wave allowance. `None` (no preset key,
                // the shipped state) leaves it ungoverned, exactly as before.
                input_split_edge_wave_cap: preset_keys.edge_wave_cap,
                phase_budget: ny_propagate::PhaseBudgetConfig {
                    post_bab_pgd_fraction: 0.0,
                    ..ny_propagate::PhaseBudgetConfig::default()
                },
                ..BetaCrownConfig::acas_xu()
            });
            // Compose the leaf-oracle stack for the edge escalation seam: the
            // cheap SOUND coupled-δ bound (default-off, isomorphic lane) is
            // consulted BEFORE the exact Graph-MIP edge solver (mip builds only),
            // so it decides most near-verified deep domains without a MIP solve
            // and the MIP handles the residual. Empty stack ⇒ byte-identical to
            // the historical no-oracle path.
            let mut leaf_oracles: Vec<
                std::sync::Arc<dyn ny_propagate::beta_crown::graph_mip_leaf::GraphMipLeafOracle>,
            > = Vec::new();
            if let Some(oracle) = coupled_oracle {
                leaf_oracles.push(oracle);
            }
            #[cfg(feature = "mip")]
            if let Some(oracle) = super::beta_crown::relational_edge_milp_oracle() {
                leaf_oracles.push(oracle);
            }
            let bab = match leaf_oracles.len() {
                0 => bab,
                1 => bab.with_graph_mip_leaf_oracle(leaf_oracles.into_iter().next().unwrap()),
                _ => bab.with_graph_mip_leaf_oracle(std::sync::Arc::new(
                    super::coupled_delta::CompositeLeafOracle::new(leaf_oracles),
                )),
            };
            let input = Verifier::bounds_to_tensor(&input_bounds, None)?;
            match bab.verify_graph_input_split_multi_clause_disjunctive(
                &graph,
                &input,
                &objectives,
                &thresholds,
                &clause_sizes,
                None,
                Some(bab_deadline),
            ) {
                Ok(result) => {
                    eprintln!(
                        "Relational difference-network BaB: {:?} ({} domains explored, {} verified, {:.1}s)",
                        match &result.result {
                            BabVerificationStatus::Violated { .. } => "Violated".to_string(),
                            other => format!("{other:?}"),
                        },
                        result.domains_explored,
                        result.domains_verified,
                        result.time_elapsed.as_secs_f64()
                    );
                    match result.result {
                        BabVerificationStatus::Verified => {
                            return authorized_unsat_or_unknown(unsat_auth, vnnlib);
                        }
                        BabVerificationStatus::Violated { counterexample, .. } => {
                            if let Some(revalidate) = sat_revalidator {
                                if let Some(witness) = revalidate(&counterexample) {
                                    return Ok(VnncompResult::Sat {
                                        witness: Some(witness),
                                    });
                                }
                            }
                            eprintln!(
                                "Relational BaB counterexample NOT independently revalidated; returning unknown"
                            );
                            return Ok(VnncompResult::Unknown);
                        }
                        // INCONCLUSIVE (BaB stalled at the relaxation floor):
                        // last-resort WHOLE-NET certified MILP finisher on the
                        // difference network (#rel-whole-mip, NY_REL_WHOLE_MIP=1,
                        // default OFF). Certified-UNSAT-only + token-gated ⇒
                        // fail-open, 0-wrong. Any miss keeps the BaB verdict.
                        BabVerificationStatus::Timeout => {
                            if try_whole_net_diff_finisher(
                                &graph,
                                &input_bounds,
                                &objectives,
                                &thresholds,
                                &unsat_auth,
                                whole_mip_plan,
                            ) {
                                return authorized_unsat_or_unknown(unsat_auth, vnnlib);
                            }
                            return Ok(VnncompResult::Timeout);
                        }
                        BabVerificationStatus::PotentialViolation { .. }
                        | BabVerificationStatus::Unknown { .. } => {
                            if try_whole_net_diff_finisher(
                                &graph,
                                &input_bounds,
                                &objectives,
                                &thresholds,
                                &unsat_auth,
                                whole_mip_plan,
                            ) {
                                return authorized_unsat_or_unknown(unsat_auth, vnnlib);
                            }
                            return Ok(VnncompResult::Unknown);
                        }
                    }
                }
                Err(e) => {
                    eprintln!(
                        "Relational difference-network BaB errored ({e}); falling back to the single-pass path"
                    );
                }
            }
        }
    }

    let spec = VerificationSpec::from_parts(
        input_bounds,
        output_bounds,
        Some(timeout_secs.saturating_mul(1000)),
        None,
    )?;
    let verifier = Verifier::new(PropagationConfig {
        method: PropagationMethod::AlphaCrown,
        ..PropagationConfig::default()
    });
    match verifier.verify_graph(&graph, &spec)? {
        // SOUNDNESS GATE — relational `unsat` is DISABLED.
        //
        // Authorizing `unsat` from a difference-network proof requires that the
        // parsed VNN-LIB formula is *exactly* the safe-complement the difference
        // network checks. Six rounds of adversarial review repeatedly found
        // VNN-LIB formula shapes that slip past shape-matching validation
        // (non-strict vs strict unsafe, cross-index output relations, negative-ε
        // `.abs()` normalization, extra non-monotonic `or` disjuncts, missing
        // input coupling, …) — each a potential WRONG `unsat`. Pattern-matching
        // formula shape to authorize `unsat` is fundamentally fragile, so a
        // difference-network `Verified` without the checked authorization below
        // maps to the sound `unknown`.
        // THE GATE FLIP (hardened): a difference-network `Verified` becomes
        // `unsat` ONLY when a [`RelationalUnsatAuth`] token is present —
        // i.e. the default-on lane was not explicitly disabled, the parsed
        // formula's full DNF was extracted exactly, AND `parsed ⇒ verified-region` was proven with
        // per-pair Farkas certificates (ay-produced, `check_farkas`-re-checked)
        // AND the difference net passed the structural spot check. Without the
        // token this arm is byte-identical to the historical demotion.
        VerificationResult::Verified { .. } => match unsat_auth {
            Some(auth) => {
                println!(
                    "Relational difference-network proof AUTHORIZED as unsat by the \
                     formula-implication certificate chain"
                );
                if let Err(reason) = super::relational_equiv::write_implication_sidecar(
                    &auth,
                    vnnlib,
                    &sidecar_cert_path(vnnlib),
                ) {
                    eprintln!("warning: failed to write implication sidecar: {reason}");
                }
                Ok(VnncompResult::Unsat(UnsatReceipt::legacy_uncovered(
                    LegacyUnsatAuthority::RelationalImplication,
                )))
            }
            None => Ok(VnncompResult::Unknown),
        },
        VerificationResult::Timeout { .. } => Ok(VnncompResult::Timeout),
        VerificationResult::Unknown { .. } | VerificationResult::Violated { .. } => {
            Ok(VnncompResult::Unknown)
        }
    }
}

fn build_monotonic_difference_network(
    network_a: &GraphNetwork,
    network_b: &GraphNetwork,
    dual: &DualNetworkSpec,
    varying_input: usize,
) -> Result<(GraphNetwork, Vec<Bound>)> {
    let dim = dual.f_input_bounds.len();
    if dim != 5 || varying_input != 0 {
        anyhow::bail!("only ACAS monotonic input-0 relation is supported");
    }
    validate_dual_bounds(&dual.f_input_bounds, "f").map_err(|reason| anyhow!(reason))?;
    validate_dual_bounds(&dual.g_input_bounds, "g").map_err(|reason| anyhow!(reason))?;
    let (_, f0_upper) = dual.f_input_bounds[0];
    let (g0_lower, _) = dual.g_input_bounds[0];
    let delta_upper = f0_upper - g0_lower;
    if !delta_upper.is_finite() || delta_upper < 0.0 {
        anyhow::bail!("monotonic varying-input delta bound is invalid: {delta_upper}");
    }
    let mut input_bounds = Vec::with_capacity(dim + 1);
    input_bounds.push(finite_bound_from_f64(g0_lower, f0_upper)?);
    input_bounds.push(finite_bound_from_f64(0.0, delta_upper)?);
    for &(lower, upper) in dual.f_input_bounds.iter().skip(1) {
        input_bounds.push(finite_bound_from_f64(lower, upper)?);
    }

    let mut graph = GraphNetwork::new();
    for (name, idx) in [
        ("xg0", 0_i64),
        ("delta", 1_i64),
        ("x1", 2_i64),
        ("x2", 3_i64),
        ("x3", 4_i64),
        ("x4", 5_i64),
    ] {
        graph.try_add_node(GraphNode::from_input(
            name,
            Layer::Gather(GatherLayer::new(0, Some(arr1(&[idx]).into_dyn()), vec![1])),
        ))?;
    }
    graph.try_add_node(GraphNode::binary(
        "xf0",
        Layer::Add(AddLayer),
        "xg0",
        "delta",
    ))?;
    add_concat_chain(&mut graph, "xf_input", &["xf0", "x1", "x2", "x3", "x4"])?;
    add_concat_chain(&mut graph, "xg_input", &["xg0", "x1", "x2", "x3", "x4"])?;
    copy_prefixed_network(&mut graph, network_a, "a_", "xf_input")?;
    copy_prefixed_network(&mut graph, network_b, "b_", "xg_input")?;
    graph.try_add_node(GraphNode::binary(
        "diff_output",
        Layer::Sub(SubLayer),
        format!("a_{}", network_a.output_name()),
        format!("b_{}", network_b.output_name()),
    ))?;
    graph.set_output("diff_output");
    Ok((graph, input_bounds))
}

/// Number of revalidated dual forward passes that gate a monotonic `sat`.
/// The same epsilon margin the MIP/SMT witness re-validators use
/// (`mip_highs.rs::REVALIDATION_MARGIN_EPS`): a `sat` requires the strict output
/// violation to hold by a real margin, not by f32 drift.
const MONOTONIC_REVALIDATION_MARGIN: f32 = 1e-5;

/// Derive a finite, SOUND g input box from the coupling so the difference-network
/// search is not blocked by the open `X_g` bounds the parser leaves.
///
/// The vnnlib only constrains the g inputs RELATIONALLY: `(>= X_f[0] X_g[0])`,
/// `(>= X_g[0] lo)`, and `(== X_f[k] X_g[k])` for the non-varying k. So the parser
/// leaves the g box open (`+inf`/`-inf`) on every index. We tighten it to a finite,
/// sound box:
///   * VARYING index: `X_f[0] >= X_g[0]` with `X_f[0] <= f0_upper` implies
///     `X_g[0] <= f0_upper`; the parsed `X_g[0] >= lo` (or f's lower) supplies the
///     lower. We require the `X_f >= X_g` coupling to be explicitly asserted (and the
///     opposite `X_g >= X_f` NOT asserted) before substituting.
///   * NON-VARYING index k: `X_f[k] == X_g[k]` means g's feasible range for k equals
///     f's box; we copy `f_input_bounds[k]` (which the gate separately confirms is
///     finite and equality-coupled).
///
/// The returned box is finite-and-in-box for the coupled feasible region. Soundness
/// of any emitted `sat` rides on the independent dual forward-pass revalidation, NOT
/// on this derivation (which only needs to bound the search domain).
fn coupled_g_input_bounds(
    dual: &DualNetworkSpec,
    varying_input: usize,
) -> std::result::Result<Vec<(f64, f64)>, String> {
    let dim = dual.g_input_bounds.len();
    if dim != dual.f_input_bounds.len() || varying_input >= dim {
        return Err("input-dim mismatch for coupled g-bound derivation".into());
    }
    let mut g_bounds = dual.g_input_bounds.clone();
    for idx in 0..dim {
        if idx == varying_input {
            // Varying index: derive finite [g_lower, f0_upper] from the >= coupling.
            let (g_lower_raw, _) = dual.g_input_bounds[idx];
            let (f_lower, f_upper) = dual.f_input_bounds[idx];
            let licensed = dual
                .validation
                .f_input_ge_g_input
                .get(idx)
                .copied()
                .unwrap_or(false)
                && !dual
                    .validation
                    .g_input_ge_f_input
                    .get(idx)
                    .copied()
                    .unwrap_or(false);
            if !licensed {
                return Err(
                    "open g-upper substitution requires an explicit X_f >= X_g coupling".into(),
                );
            }
            if !f_upper.is_finite() {
                return Err(
                    "f0_upper is not finite; cannot derive a finite coupled g-upper".into(),
                );
            }
            // Lower: prefer the parsed `X_g[0] >= lo`; fall back to f's lower bound.
            let g_lower = if g_lower_raw.is_finite() {
                g_lower_raw
            } else {
                f_lower
            };
            if !g_lower.is_finite() {
                return Err("coupled g-lower is not finite".into());
            }
            if g_lower > f_upper {
                return Err("derived coupled g-bound is empty (g_lower > f0_upper)".into());
            }
            g_bounds[idx] = (g_lower, f_upper);
        } else {
            // Non-varying index: g range == f range via the `==` coupling. Only
            // substitute when g is open AND the equality coupling is explicit; the
            // f box must itself be finite (the gate re-checks this).
            let g_finite =
                dual.g_input_bounds[idx].0.is_finite() && dual.g_input_bounds[idx].1.is_finite();
            if !g_finite {
                if !dual
                    .validation
                    .input_equalities
                    .get(idx)
                    .copied()
                    .unwrap_or(false)
                {
                    return Err(format!(
                        "open g input {idx} lacks an explicit X_f == X_g equality coupling"
                    ));
                }
                let (f_lower, f_upper) = dual.f_input_bounds[idx];
                if !f_lower.is_finite() || !f_upper.is_finite() {
                    return Err(format!("f input {idx} box is not finite"));
                }
                g_bounds[idx] = (f_lower, f_upper);
            }
        }
    }
    Ok(g_bounds)
}

/// Attempt to emit a monotonic `sat` by searching the coupled box for a genuine
/// counterexample, then independently re-confirming it on BOTH original networks.
///
/// Returns `Ok(Some(Sat{witness}))` ONLY when an independent dual forward pass
/// confirms `Y_f[output] < Y_g[output]` with margin; `Ok(None)` when no revalidated
/// counterexample is found (the caller falls through to the sound gate path); `Err`
/// on a load/parse problem (also routed to the sound fall-through by the caller).
/// NEVER emits `sat` from the difference-network value alone.
///
/// Scope is the parsed `equal-to` monotonic property (plus the canonical 5-input,
/// input-0 shape checked below); it used to also require the literal category
/// `monotonic_acasxu_2026` (#name-blind-routing), which every `equal-to` row in
/// the scored corpus carries.
fn try_monotonic_coupled_sat(
    dual: &DualNetworkSpec,
    onnx_arg: &Path,
    vnnlib: &Path,
) -> Result<Option<VnncompResult>> {
    // Only the validated monotonic property shape is searched. We deliberately reuse
    // the SAME structural facts the soundness gate checks (output index, varying
    // input, equality coupling, X_f>=X_g) so the search runs only on instances the
    // gate also recognizes — but we substitute a finite coupled g-box so the search
    // is not blocked by the open X_g[0] upper.
    let DualNetworkProperty::MonotonicGreaterEq {
        output,
        varying_input,
        ..
    } = dual.property
    else {
        return Ok(None);
    };
    if dual.f_input_bounds.len() != 5 || varying_input != 0 {
        return Ok(None);
    }

    // Derive the finite coupled g-box and validate the monotonic structural gate on
    // a coupled clone. If the gate declines (wrong shape, missing coupling, …), we
    // do NOT search — fall through to the sound path.
    let coupled_g = match coupled_g_input_bounds(dual, varying_input) {
        Ok(bounds) => bounds,
        Err(_) => return Ok(None),
    };
    let mut coupled_dual = dual.clone();
    coupled_dual.g_input_bounds = coupled_g;
    let gate = match dual_difference_soundness_gate(&coupled_dual) {
        Ok(gate) => gate,
        Err(_) => return Ok(None),
    };
    if !matches!(gate.kind, DualDifferenceKind::Monotonic { .. }) {
        return Ok(None);
    }

    // Resolve and load both original networks (g IS f for `equal-to`, but we load the
    // declared paths independently and revalidate through each).
    let mut network_paths = resolve_relational_network_paths(onnx_arg, vnnlib)?;
    if network_paths.len() == 1 && gate.allows_single_network_reuse() {
        network_paths.push(network_paths[0].clone());
    }
    if network_paths.len() != 2 || network_paths.iter().any(|p| !p.is_file()) {
        return Ok(None);
    }
    let graph_f = load_graph_network(&network_paths[0])?;
    let graph_g = load_graph_network(&network_paths[1])?;

    // Build the coupled difference network over the finite coupled box.
    let (diff, input_bounds) =
        build_monotonic_difference_network(&graph_f, &graph_g, &coupled_dual, varying_input)?;
    let output_dim = infer_output_dim(&diff, &input_bounds)?;
    if output >= output_dim {
        return Ok(None);
    }

    // Inward search box (declared bounds, INWARD-rounded) so the minimizer is already
    // organizer-in-box and the revalidation clamp is a no-op. xg0 in [g_lower, f0_upper],
    // x1,x2 in inward f boxes, x3,x4 degenerate at the const; xf0 in inward f[0] box.
    let _ = &input_bounds; // diff net was built/validated over the outward box.
    let g0 = coupled_dual.g_input_bounds[0];
    let g0_inward = inward_bound(g0);
    let search_bounds: [Bound; 6] = [
        g0_inward,
        Bound::new(0.0, (g0_inward.upper() - g0_inward.lower()).max(0.0)),
        inward_bound(coupled_dual.f_input_bounds[1]),
        inward_bound(coupled_dual.f_input_bounds[2]),
        inward_bound(coupled_dual.f_input_bounds[3]),
        inward_bound(coupled_dual.f_input_bounds[4]),
    ];
    let f0_inward = inward_bound(coupled_dual.f_input_bounds[0]);
    let xf0_box = (f0_inward.lower(), f0_inward.upper());

    // SEARCH: find a coupled point with diff_output[output] < 0 (i.e. Y_f - Y_g < 0).
    let Some(point) =
        search_monotonic_coupled_counterexample(&diff, &search_bounds, xf0_box, output)?
    else {
        return Ok(None);
    };

    // REVALIDATE: independently forward BOTH original networks at the decomposed
    // per-network inputs and confirm the strict violation with margin — internal
    // pre-filter plus the trusted ORT confirmation. Only a confirmed witness
    // yields `sat`.
    match revalidate_monotonic_witness(
        &graph_f,
        &graph_g,
        &network_paths[0],
        &network_paths[1],
        &point,
        &coupled_dual,
        varying_input,
        output,
    )? {
        Some((xf, xg, yf, yg)) => {
            let witness = relational_counterexample_vnnlib(&coupled_dual, &xf, &xg, &yf, &yg)?;
            Ok(Some(VnncompResult::Sat {
                witness: Some(witness),
            }))
        }
        None => Ok(None),
    }
}

/// Evaluate the difference network at a concrete 6-dim coupled point
/// `[xg0, delta, x1, x2, x3, x4]` using exact point IBP (lower == upper), returning
/// `diff_output[output] = Y_f[output] - Y_g[output]`. Mirrors `infer_output_dim`.
fn eval_diff_point(diff: &GraphNetwork, point: &[f32], output: usize) -> Result<f32> {
    let degenerate: Vec<Bound> = point.iter().map(|&v| Bound::new(v, v)).collect();
    let input = Verifier::bounds_to_tensor(&degenerate, None)?;
    // Concrete-point (interval CENTER per node), NOT IBP: the stitched
    // difference net's per-layer sound rounding + the final Sub widen a POINT
    // into a ~mrad-wide interval whose LOWER bound biases the deviation low
    // (see `forward_point_vec`). Concrete-point matches ORT to ~1e-6.
    let out = diff.propagate_concrete_point(&input, None, None)?;
    let lower = out.lower();
    lower
        .iter()
        .nth(output)
        .copied()
        .ok_or_else(|| anyhow!("diff output index {output} out of range"))
}

/// A tiny deterministic xorshift RNG for fixed-seed random restarts (mirrors the
/// `SimpleRng` uniform sampling used in disjunctive PGD). Fixed seed => reproducible
/// search, so the verdict is a pure function of the instance.
struct SearchRng(u64);

impl SearchRng {
    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    /// Uniform f32 in `[lo, hi]` (returns `lo` for a degenerate axis). Bounds are
    /// finite by construction (derived from parsed declared boxes).
    fn uniform(&mut self, lo: f32, hi: f32) -> f32 {
        if hi <= lo {
            return lo;
        }
        let frac = (self.next_u64() >> 11) as f64 / ((1u64 << 53) as f64);
        let lo64 = f32_to_f64_exact(lo);
        let hi64 = f32_to_f64_exact(hi);
        let v = lo64 + frac * (hi64 - lo64);
        (v as f32).clamp(lo, hi)
    }
}

/// Search the coupled difference network for a point with
/// `diff_output[output] < 0` (a candidate monotonicity counterexample), restricted to
/// the INWARD-rounded DECLARED box so the minimizer is already organizer-in-box.
///
/// The 6-dim diff input is `[xg0, delta, x1, x2, x3, x4]`. We sample `xg0` and a
/// target `xf0` (both within their inward declared boxes), set `delta = xf0 - xg0`
/// with `xf0 >= xg0` enforced (so `X_f[0] >= X_g[0]` holds by construction), and feed
/// `[xg0, delta, x1, x2, x3, x4]` to the diff net. x1,x2 range over their inward f
/// boxes; x3,x4 are degenerate (the `==` consts). Searching the INWARD box (rather
/// than the outward diff box) means the witness `revalidate_monotonic_witness` clamps
/// is a no-op, so the diff-net minimizer coincides with the in-box revalidated point.
/// Strategy: deterministic grid scan, fixed-seed random restarts, then a bounded
/// coordinate descent; return the GLOBAL MINIMIZER (most negative) when it clears the
/// revalidation margin. The budget is small and fixed (never threatens the wall clock).
fn search_monotonic_coupled_counterexample(
    diff: &GraphNetwork,
    search_bounds: &[Bound; 6],
    xf0_box: (f32, f32),
    output: usize,
) -> Result<Option<[f32; 6]>> {
    let lo: Vec<f32> = search_bounds.iter().map(Bound::lower).collect();
    let hi: Vec<f32> = search_bounds.iter().map(Bound::upper).collect();
    let (xf0_lo, xf0_hi) = xf0_box;

    // Build a coupling-feasible, in-box diff point from sampled (xg0, xf0_target, x1,
    // x2): delta = clamp(xf0_target, xf0_box) - xg0, forced >= 0.
    let make_point = |xg0: f32, xf0_target: f32, x1: f32, x2: f32| -> [f32; 6] {
        let xf0 = clamp_f32(xf0_target.max(xg0), xf0_lo, xf0_hi);
        let delta = (xf0 - xg0).max(0.0);
        [xg0, delta, x1, x2, lo[4], lo[5]]
    };

    // Helper: evaluate a candidate, returning Some(value) on success.
    let eval = |point: &[f32; 6]| -> Option<f32> {
        eval_diff_point(diff, point, output)
            .ok()
            .filter(|v| !v.is_nan())
    };

    // We return the GLOBAL MINIMIZER (most negative diff value) found across the whole
    // bounded budget, NOT the first negative point. A tiny-negative point (e.g. delta
    // ~ 0, diff ~ -1e-45 numerical noise) would NOT clear the downstream revalidation
    // margin and would waste the attempt; the minimizer is a genuine large-margin
    // violation when one exists. The diff-net point IBP is exact (lower==upper), so
    // its value tracks the independent dual forward Y_f-Y_g closely.
    let mut best: Option<([f32; 6], f32)> = None;
    let consider = |best: &mut Option<([f32; 6], f32)>, point: [f32; 6], value: f32| {
        if best.as_ref().map(|(_, b)| value < *b).unwrap_or(true) {
            *best = Some((point, value));
        }
    };

    // (a) Deterministic grid scan over the four sampling axes [xg0, xf0, x1, x2];
    // x3,x4 are degenerate (the `==` consts). We grid xf0 over its OWN inward box.
    const GRID_TICKS: usize = 9;
    let axis_tick = |l: f32, h: f32, t: usize| -> f32 {
        if h <= l {
            return l;
        }
        let frac = t as f32 / (GRID_TICKS - 1) as f32;
        (l + frac * (h - l)).clamp(l, h)
    };
    for a in 0..GRID_TICKS {
        for b in 0..GRID_TICKS {
            for c in 0..GRID_TICKS {
                for d in 0..GRID_TICKS {
                    let xg0 = axis_tick(lo[0], hi[0], a);
                    let xf0 = axis_tick(xf0_lo, xf0_hi, b);
                    let x1 = axis_tick(lo[2], hi[2], c);
                    let x2 = axis_tick(lo[3], hi[3], d);
                    let point = make_point(xg0, xf0, x1, x2);
                    if let Some(value) = eval(&point) {
                        consider(&mut best, point, value);
                    }
                }
            }
        }
    }

    // (b) Fixed-seed uniform random restarts over the sampling space to harden
    // coverage; every sampled point is rebuilt coupling-feasible and in-box.
    const RANDOM_RESTARTS: usize = 4096;
    let mut rng = SearchRng(0x9E37_79B9_7F4A_7C15);
    for _ in 0..RANDOM_RESTARTS {
        let xg0 = rng.uniform(lo[0], hi[0]);
        let xf0 = rng.uniform(xf0_lo, xf0_hi);
        let x1 = rng.uniform(lo[2], hi[2]);
        let x2 = rng.uniform(lo[3], hi[3]);
        let point = make_point(xg0, xf0, x1, x2);
        if let Some(value) = eval(&point) {
            consider(&mut best, point, value);
        }
    }

    // (c) Cheap coordinate descent in the SAMPLING space [xg0, xf0, x1, x2] from the
    // best point: nudge each axis toward decreasing diff value, rebuilding a feasible
    // in-box diff point each step. Bounded passes refine the minimizer.
    if let Some((point, value)) = best {
        // Recover the sampling coords from the diff point: xf0 = xg0 + delta.
        let mut s = [point[0], point[0] + point[1], point[2], point[3]];
        let mut cur = (point, value);
        let ranges = [
            (lo[0], hi[0]),
            (xf0_lo, xf0_hi),
            (lo[2], hi[2]),
            (lo[3], hi[3]),
        ];
        for _ in 0..64 {
            let mut improved = false;
            for axis in 0..4 {
                let (l, h) = ranges[axis];
                if h <= l {
                    continue;
                }
                let step = (h - l) * 0.05;
                for dir in [step, -step] {
                    let mut trial_s = s;
                    trial_s[axis] = (trial_s[axis] + dir).clamp(l, h);
                    let trial = make_point(trial_s[0], trial_s[1], trial_s[2], trial_s[3]);
                    if let Some(v) = eval(&trial) {
                        if v < cur.1 {
                            cur = (trial, v);
                            s = trial_s;
                            improved = true;
                        }
                    }
                }
            }
            if !improved {
                break;
            }
        }
        best = Some(cur);
    }

    // Require the minimizer to be strictly negative beyond the revalidation margin so
    // we never forward a numerical-noise point that the independent dual re-eval would
    // reject. The downstream `revalidate_monotonic_witness` is the soundness gate;
    // this threshold only keeps the attempt efficient.
    match best {
        Some((point, value)) if value < -MONOTONIC_REVALIDATION_MARGIN => Ok(Some(point)),
        _ => Ok(None),
    }
}

/// Decompose a coupled diff point and INDEPENDENTLY re-evaluate BOTH original
/// networks, returning `(X_f, X_g, Y_f, Y_g)` ONLY when the strict output violation
/// `Y_f[output] < Y_g[output]` is re-confirmed with margin.
///
/// Mirrors the MIP/SMT witness-revalidation discipline: NEVER trust the
/// difference-network value alone. The diff point is `[xg0, delta, x1, x2, x3, x4]`;
/// we reconstruct per-network f32 inputs `X_g = [xg0, x1, x2, x3, x4]` and
/// `X_f = [xg0+delta, x1, x2, x3, x4]` (clamped into the f box, keeping
/// `X_f[0] >= X_g[0]` and the k>=1 equalities + fixed x3/x4), then forward each
/// ORIGINAL graph at the degenerate point (lower==upper => exact eval), independent
/// of the stitched diff net. Confirmation requires
/// `Y_g[output] - Y_f[output] >= MONOTONIC_REVALIDATION_MARGIN` (a real margin, not
/// f32 drift). Returns `None` on any forward error or unconfirmed margin.
///
/// TRUSTED-ORACLE GATE (soundness-critical, mirrors the main sat gate's
/// `confirm_violation_with_ort` rationale): the internal graph forward is only
/// a PRE-FILTER — it shares ny's graph loader with the verifier, so both can
/// agree on a WRONG output. `sat` is emitted ONLY after BOTH original ONNX
/// models, re-executed through real ONNX Runtime at the decomposed witness,
/// re-confirm the strict monotonic violation with the same margin; ORT
/// unavailability or disagreement returns `None` (caller degrades soundly).
/// The returned outputs are the TRUSTED ORT outputs.
fn revalidate_monotonic_witness(
    graph_f: &GraphNetwork,
    graph_g: &GraphNetwork,
    onnx_f: &Path,
    onnx_g: &Path,
    point: &[f32; 6],
    coupled_dual: &DualNetworkSpec,
    varying_input: usize,
    output: usize,
) -> Result<Option<([f32; 5], [f32; 5], Vec<f32>, Vec<f32>)>> {
    if coupled_dual.f_input_bounds.len() != 5
        || coupled_dual.g_input_bounds.len() != 5
        || varying_input != 0
    {
        return Ok(None);
    }
    // Clamp the witness into the DECLARED vnnlib boxes (NOT the outward-rounded diff
    // search box), with INWARD f32 rounding, so the organizer's EXACT re-check of the
    // input asserts `(>= X v)` / `(<= X v)` passes on the emitted bytes. Outward diff
    // bounds (next_down on lower) would leave X_g[0] a hair below the declared lower
    // and the organizer would reject the witness as out-of-box.
    //   X_g[0] box = [g_lower_declared, f0_upper_declared] (coupled finite g[0])
    //   X_f[0] box = [f0_lower_declared, f0_upper_declared] AND X_f[0] >= X_g[0]
    //   X_f[k]=X_g[k] box = declared f box for k>=1 (degenerate for fixed inputs)
    let g0_box = inward_bound(coupled_dual.g_input_bounds[0]);
    let f0_box = inward_bound(coupled_dual.f_input_bounds[0]);
    let (xg0_lo, xg0_hi) = (g0_box.lower(), g0_box.upper());
    let (xf0_lo, xf0_hi) = (f0_box.lower(), f0_box.upper());
    if xg0_lo > xg0_hi || xf0_lo > xf0_hi {
        return Ok(None);
    }

    let xg0 = clamp_f32(point[0], xg0_lo, xg0_hi);
    let delta = point[1].max(0.0); // delta >= 0 guarantees X_f[0] >= X_g[0]
    let shared: [f32; 4] = [point[2], point[3], point[4], point[5]];

    // X_f[0] = xg0 + delta, clamped into the DECLARED f box. Keep the >= coupling: if
    // the clamp drops X_f[0] below X_g[0] we cannot honor the coupling, so bail.
    let xf0 = clamp_f32(xg0 + delta, xf0_lo, xf0_hi);
    if xf0 < xg0 {
        return Ok(None);
    }

    // Clamp each shared coordinate into its DECLARED f box (k>=1). Fixed (equality
    // const) inputs have a degenerate declared box, pinning to the constant.
    let mut shared_clamped = [0.0f32; 4];
    for (k, value) in shared.iter().enumerate() {
        let b = inward_bound(coupled_dual.f_input_bounds[k + 1]);
        shared_clamped[k] = clamp_f32(*value, b.lower(), b.upper());
    }

    let x_f: [f32; 5] = [
        xf0,
        shared_clamped[0],
        shared_clamped[1],
        shared_clamped[2],
        shared_clamped[3],
    ];
    let x_g: [f32; 5] = [
        xg0,
        shared_clamped[0],
        shared_clamped[1],
        shared_clamped[2],
        shared_clamped[3],
    ];

    // Coupling sanity (must hold for the witness to be organizer-recheckable).
    if x_f[0] < x_g[0] {
        return Ok(None);
    }

    // INDEPENDENT forward of EACH ORIGINAL graph at the degenerate per-network point.
    let y_f = forward_original_point(graph_f, &x_f)?;
    let y_g = forward_original_point(graph_g, &x_g)?;
    if output >= y_f.len() || output >= y_g.len() {
        return Ok(None);
    }

    // CONFIRM the strict unsafe atom Y_f[output] < Y_g[output] by a real margin
    // (internal pre-filter only — never sufficient for a `sat` on its own;
    // NaN-rejecting: the pre-filter must PASS, not merely not-fail — a NaN
    // margin yields partial_cmp None, which is != Greater/Equal, so it rejects).
    let margin = y_g[output] - y_f[output];
    if !matches!(
        margin.partial_cmp(&MONOTONIC_REVALIDATION_MARGIN),
        Some(std::cmp::Ordering::Greater | std::cmp::Ordering::Equal)
    ) {
        return Ok(None);
    }

    // Trusted confirmation: the same strict violation must hold on the ORT
    // outputs of BOTH original models at the same decomposed witness.
    let Some((y_f_ort, y_g_ort)) = ort_dual_forward(onnx_f, onnx_g, &x_f, &x_g) else {
        eprintln!(
            "Monotonic sat candidate could not be re-confirmed (ORT unavailable); \
             downgrading to the sound path"
        );
        return Ok(None);
    };
    if output >= y_f_ort.len() || output >= y_g_ort.len() {
        return Ok(None);
    }
    let ort_margin = f32_to_f64_exact(y_g_ort[output]) - f32_to_f64_exact(y_f_ort[output]);
    if !ort_margin.is_finite() || ort_margin < f32_to_f64_exact(MONOTONIC_REVALIDATION_MARGIN) {
        eprintln!(
            "Monotonic sat candidate REJECTED by the trusted ORT dual-forward \
             (internal forward disagreed with ONNX Runtime); downgrading to the sound path"
        );
        return Ok(None);
    }
    Ok(Some((x_f, x_g, y_f_ort, y_g_ort)))
}

/// Independent concrete forward pass through an ORIGINAL ACAS network at a 5-dim
/// point using exact point IBP (lower == upper). Returns the output vector.
/// Mirrors `verify/pgd.rs::evaluate_network` / `mip_highs.rs::independent_mip_forward`.
fn forward_original_point(graph: &GraphNetwork, point: &[f32; 5]) -> Result<Vec<f32>> {
    forward_point_vec(graph, point)
}

/// [`forward_original_point`] for arbitrary input dimension.
///
/// Uses [`GraphNetwork::propagate_concrete_point`] (interval CENTER after every
/// node), NOT `propagate_ibp`. This is soundness-CRITICAL for the falsifier:
/// `propagate_ibp` is sound-rounding-aware and widens even a POINT input by the
/// accumulated certified f32 error (~1.7e-3 per output over the 7-layer ACAS
/// net); in a STITCHED difference network the final `Sub` ADDS the two
/// branches' errors (~3.6e-3 wide), and returning `out.lower()` biased the
/// deviation LOW by that much — enough to HIDE a genuine 0.0515 deviation
/// (reported 0.0496 < ε). The concrete-point forward matches ONNX Runtime to
/// ~1e-6, so `|f(x) − g(x)|` at a witness is faithful. Witness-evaluation only
/// (every caller is sat-finding / revalidation, never a Verified verdict).
fn forward_point_vec(graph: &GraphNetwork, point: &[f32]) -> Result<Vec<f32>> {
    let degenerate: Vec<Bound> = point.iter().map(|&v| Bound::new(v, v)).collect();
    let input = Verifier::bounds_to_tensor(&degenerate, None)?;
    let out = graph.propagate_concrete_point(&input, None, None)?;
    Ok(out.lower().iter().copied().collect())
}

fn tensor_shape_len(shape: &[usize]) -> Result<usize> {
    let mut length = 1usize;
    for &dimension in shape {
        if dimension == 0 {
            anyhow::bail!("VNN-LIB assignment tensor has a zero dimension");
        }
        length = length
            .checked_mul(dimension)
            .ok_or_else(|| anyhow!("VNN-LIB assignment tensor shape overflows usize"))?;
    }
    Ok(length)
}

/// Serialize the mandatory VNN-LIB 2.0 textual assignment. Each tensor gets
/// one exact declaration header followed by its row-major scalar values, one
/// per line. Hidden tensors cannot be reconstructed from NY's public witness
/// and therefore fail closed.
fn format_vnnlib2_assignment(
    declarations: &[TensorDeclaration],
    inputs: &[f64],
    outputs: &[f64],
) -> Result<String> {
    if declarations.is_empty() {
        anyhow::bail!("VNN-LIB 2.0 assignment has no tensor declarations");
    }
    let mut lines = Vec::new();
    let mut input_position = 0usize;
    let mut output_position = 0usize;

    for declaration in declarations {
        if declaration.name.split_whitespace().count() != 1
            || declaration.element_type.split_whitespace().count() != 1
        {
            anyhow::bail!(
                "invalid VNN-LIB assignment header for tensor '{}'",
                declaration.name
            );
        }
        let length = tensor_shape_len(&declaration.shape)?;
        let dimensions = declaration
            .shape
            .iter()
            .map(usize::to_string)
            .collect::<Vec<_>>()
            .join(", ");
        lines.push(format!(
            "{} {} [{}]",
            declaration.name, declaration.element_type, dimensions
        ));
        match declaration.kind {
            TensorDeclarationKind::Input => {
                let end = input_position
                    .checked_add(length)
                    .ok_or_else(|| anyhow!("VNN-LIB input assignment length overflow"))?;
                let values = inputs.get(input_position..end).ok_or_else(|| {
                    anyhow!(
                        "not enough input values for tensor '{}' (need {length})",
                        declaration.name
                    )
                })?;
                for &value in values {
                    // #witness-f64-render: the emitted decimal MUST reproduce the
                    // declared f64 exactly. Rust's f64 `Display` is the shortest
                    // round-tripping form, so this holds by construction — but a
                    // witness that fell off its declared bound by 1e-8 is scored
                    // -150, so the invariant is asserted rather than assumed.
                    // (The previous f32 renderer violated it: collins_rul_cnn pin
                    // -0.42296521394810976 -> "-0.42296523".)
                    if value.to_string().parse::<f64>() != Ok(value) {
                        anyhow::bail!(
                            "VNN-LIB 2.0 assignment for '{}' would not round-trip losslessly",
                            declaration.name
                        );
                    }
                    if !value.is_finite() {
                        anyhow::bail!(
                            "non-finite input value in VNN-LIB assignment for '{}'",
                            declaration.name
                        );
                    }
                    lines.push(value.to_string());
                }
                input_position = end;
            }
            TensorDeclarationKind::Output => {
                let end = output_position
                    .checked_add(length)
                    .ok_or_else(|| anyhow!("VNN-LIB output assignment length overflow"))?;
                let values = outputs.get(output_position..end).ok_or_else(|| {
                    anyhow!(
                        "not enough output values for tensor '{}' (need {length})",
                        declaration.name
                    )
                })?;
                for &value in values {
                    if !value.is_finite() {
                        anyhow::bail!(
                            "non-finite output value in VNN-LIB assignment for '{}'",
                            declaration.name
                        );
                    }
                    lines.push(value.to_string());
                }
                output_position = end;
            }
            TensorDeclarationKind::Hidden => {
                anyhow::bail!(
                    "cannot emit a VNN-LIB 2.0 assignment for hidden tensor '{}'",
                    declaration.name
                );
            }
        }
    }
    if input_position != inputs.len() {
        anyhow::bail!(
            "VNN-LIB assignment consumed {input_position} of {} input values",
            inputs.len()
        );
    }
    if output_position != outputs.len() {
        anyhow::bail!(
            "VNN-LIB assignment consumed {output_position} of {} output values",
            outputs.len()
        );
    }
    Ok(lines.join("\n"))
}

/// Convert the legacy flat `X_i`/`Y_i` witness produced by the verifier into
/// the mandatory VNN-LIB 2.0 tensor assignment. Outputs are recomputed through
/// ONNX Runtime so the serialized assignment is complete and faithful. Any
/// parse, shape, or inference mismatch downgrades `sat` to sound `unknown`.
fn normalize_vnnlib2_sat_result(
    onnx: &Path,
    vnnlib: &Path,
    result: VnncompResult,
) -> VnncompResult {
    if !matches!(result, VnncompResult::Sat { .. }) {
        return result;
    }
    let declarations = match load_vnnlib_assignment_declarations(vnnlib) {
        Ok(declarations) => declarations,
        Err(error) => {
            eprintln!(
                "VNN-LIB assignment declarations could not be parsed ({error}); downgrading sat to unknown"
            );
            return VnncompResult::Unknown;
        }
    };
    if declarations.is_empty() {
        return result;
    }
    let witness = match &result {
        VnncompResult::Sat {
            witness: Some(witness),
        } => witness,
        VnncompResult::Sat { witness: None } => {
            eprintln!("VNN-LIB 2.0 sat carried no witness; downgrading sat to unknown");
            return VnncompResult::Unknown;
        }
        _ => unreachable!(),
    };
    // #witness-f64-render: parse with the F64-PRESERVING parser. The f32 parser
    // here re-rendered every pin through `f32::to_string()`, i.e. the shortest
    // decimal that round-trips AS F32 — which moves the emitted value off the
    // declared f64 bound and can push it OUT of the declared box, turning a
    // genuine `sat` into an organizer-invalid counterexample (-150).
    // Measured: collins_rul_cnn_2022 pin -0.42296521394810976 -> "-0.42296523"
    // (1.6e-8 outside its own degenerate [a,a] box); cgan2026 face
    // 0.6853536367416382 -> "0.68535364", 3.3e-9 ABOVE the declared upper.
    // Emitting the declared f64 verbatim is valid under both an f64 and an f32
    // reading of the witness; the f32 re-render is valid only under the latter.
    let inputs = match parse_witness_inputs_f64(witness) {
        Ok(inputs) => inputs,
        Err(error) => {
            eprintln!(
                "VNN-LIB 2.0 witness inputs could not be parsed ({error}); downgrading sat to unknown"
            );
            return VnncompResult::Unknown;
        }
    };
    // The network is still evaluated on the f32 tensor, exactly as the organizer
    // does; only the RENDERED witness keeps full f64 precision.
    let inputs_f32: Vec<f32> = inputs.iter().map(|&v| v as f32).collect();
    let outputs = match ny_onnx::diff::OrtForward::from_path(onnx, inputs_f32.len())
        .and_then(|mut forward| forward.run(&inputs_f32))
    {
        Ok(outputs) => outputs.into_iter().map(f64::from).collect::<Vec<_>>(),
        Err(error) => {
            eprintln!(
                "VNN-LIB 2.0 witness output reconstruction failed ({error}); downgrading sat to unknown"
            );
            return VnncompResult::Unknown;
        }
    };
    match format_vnnlib2_assignment(&declarations, &inputs, &outputs) {
        Ok(rendered) => VnncompResult::Sat {
            witness: Some(rendered),
        },
        Err(error) => {
            eprintln!(
                "VNN-LIB 2.0 witness serialization failed ({error}); downgrading sat to unknown"
            );
            VnncompResult::Unknown
        }
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// Isomorphic SAT side (the falsifier): coupled deviation search + independent
// dual-forward revalidation. Mirrors the monotonic lane's discipline.
// ═══════════════════════════════════════════════════════════════════════════

/// TRUSTED dual forward at a witness: re-execute BOTH ORIGINAL ONNX models
/// through real ONNX Runtime — the same `OrtForward` mechanism as
/// `confirm_violation_with_ort`, whose input shape comes straight from the
/// ONNX protobuf, deliberately NOT via ny's graph loader (whose
/// graph-loading/op bug is the very thing the trusted-oracle gate guards
/// against). Returns `(y_f, y_g)`; `None` when ORT is unavailable or either
/// forward fails — callers MUST downgrade their `sat` on `None`.
fn ort_dual_forward(
    onnx_f: &Path,
    onnx_g: &Path,
    x_f: &[f32],
    x_g: &[f32],
) -> Option<(Vec<f32>, Vec<f32>)> {
    let mut forward_f = ny_onnx::diff::OrtForward::from_path(onnx_f, x_f.len()).ok()?;
    let y_f = forward_f.run(x_f).ok()?;
    let mut forward_g = ny_onnx::diff::OrtForward::from_path(onnx_g, x_g.len()).ok()?;
    let y_g = forward_g.run(x_g).ok()?;
    Some((y_f, y_g))
}

/// Revalidate an isomorphic deviation candidate `x` (the SHARED input point):
/// clamp into the INWARD-rounded declared f box (organizer-recheckable),
/// independently forward BOTH ORIGINAL networks, and confirm a STRICT
/// epsilon-band violation with a real margin, in f64 (`|Y_g[i] - Y_f[i]| >
/// eps + margin` for some `i` — outward-guarded, so f32 drift can never
/// promote an in-band point). Returns the emitted witness on confirmation.
///
/// TRUSTED-ORACLE GATE (soundness-critical, mirrors the main sat gate's
/// `confirm_violation_with_ort` rationale): the internal
/// `propagate_concrete_point` forward shares ny's graph loader with the
/// verifier, so both can agree on a WRONG output if the graph is loaded or an
/// op is implemented incorrectly. The internal dual forward is therefore only
/// a PRE-FILTER; `sat` is emitted ONLY after BOTH original ONNX models,
/// re-executed through real ONNX Runtime at the same witness, confirm the
/// strict epsilon-band violation with the same margin. ORT unavailability or
/// disagreement returns `None` (the caller degrades to the sound path). The
/// emitted witness carries the TRUSTED ORT outputs.
fn revalidate_isomorphic_witness(
    graph_f: &GraphNetwork,
    graph_g: &GraphNetwork,
    onnx_f: &Path,
    onnx_g: &Path,
    candidate: &[f32],
    dual: &DualNetworkSpec,
    epsilon: f64,
) -> Option<String> {
    if candidate.len() != dual.f_input_bounds.len() {
        return None;
    }
    let x: Vec<f32> = candidate
        .iter()
        .zip(dual.f_input_bounds.iter())
        .map(|(&v, &declared)| {
            let b = inward_bound(declared);
            clamp_f32(v, b.lower(), b.upper())
        })
        .collect();
    let strictly_violated = |y_f: &[f32], y_g: &[f32]| -> bool {
        y_f.len() == y_g.len()
            && !y_f.is_empty()
            && y_f.iter().zip(y_g.iter()).any(|(&f, &g)| {
                let dev = f32_to_f64_exact(g) - f32_to_f64_exact(f);
                dev.is_finite()
                    && dev.abs() > epsilon + f32_to_f64_exact(MONOTONIC_REVALIDATION_MARGIN)
            })
    };
    // Internal pre-filter: cheap, but NEVER sufficient for a `sat` on its own.
    let y_f = forward_point_vec(graph_f, &x).ok()?;
    let y_g = forward_point_vec(graph_g, &x).ok()?;
    if !strictly_violated(&y_f, &y_g) {
        return None;
    }
    // Trusted confirmation: the strict violation must hold on the ORT outputs.
    let Some((y_f_ort, y_g_ort)) = ort_dual_forward(onnx_f, onnx_g, &x, &x) else {
        eprintln!(
            "Isomorphic sat candidate could not be re-confirmed (ORT unavailable); \
             downgrading to the sound path"
        );
        return None;
    };
    if !strictly_violated(&y_f_ort, &y_g_ort) {
        eprintln!(
            "Isomorphic sat candidate REJECTED by the trusted ORT dual-forward \
             (internal forward disagreed with ONNX Runtime); downgrading to the sound path"
        );
        return None;
    }
    relational_counterexample_vnnlib(dual, &x, &x, &y_f_ort, &y_g_ort).ok()
}

/// Search the SHARED-input difference network for a point maximizing
/// `max_i |h_i(x)|` over the inward-rounded declared box — the isomorphic
/// falsifier's candidate generator. Deterministic grid + fixed-seed random
/// restarts + bounded coordinate ascent (the monotonic lane's strategy,
/// maximizing instead of minimizing). Returns the maximizer when it clears
/// `eps + margin`; the downstream dual-forward revalidation is the soundness
/// gate — this threshold only keeps the attempt efficient.
fn search_isomorphic_deviation(
    diff: &GraphNetwork,
    search_bounds: &[Bound],
    epsilon: f64,
    deadline: std::time::Instant,
) -> Option<Vec<f32>> {
    search_isomorphic_deviation_with_advice_and_cancel(
        diff,
        search_bounds,
        epsilon,
        deadline,
        None,
        None,
    )
}

fn search_isomorphic_deviation_with_advice(
    diff: &GraphNetwork,
    search_bounds: &[Bound],
    epsilon: f64,
    deadline: std::time::Instant,
    advice: Option<&relational_vjp::DenseTwinAdvice>,
) -> Option<Vec<f32>> {
    search_isomorphic_deviation_with_advice_and_cancel(
        diff,
        search_bounds,
        epsilon,
        deadline,
        advice,
        None,
    )
}

fn search_isomorphic_deviation_cancellable(
    diff: &GraphNetwork,
    search_bounds: &[Bound],
    epsilon: f64,
    deadline: std::time::Instant,
    cancel: Option<&ny_propagate::PgdCancelToken>,
) -> Option<Vec<f32>> {
    search_isomorphic_deviation_with_advice_and_cancel(
        diff,
        search_bounds,
        epsilon,
        deadline,
        None,
        cancel,
    )
}

fn search_isomorphic_deviation_with_advice_and_cancel(
    diff: &GraphNetwork,
    search_bounds: &[Bound],
    epsilon: f64,
    deadline: std::time::Instant,
    advice: Option<&relational_vjp::DenseTwinAdvice>,
    cancel: Option<&ny_propagate::PgdCancelToken>,
) -> Option<Vec<f32>> {
    let cancelled = || cancel.is_some_and(ny_propagate::PgdCancelToken::is_cancelled);
    let stopped = || cancelled() || std::time::Instant::now() >= deadline;
    let dim = search_bounds.len();
    if dim == 0 {
        return None;
    }
    let started = std::time::Instant::now();
    let lo: Vec<f32> = search_bounds.iter().map(Bound::lower).collect();
    let hi: Vec<f32> = search_bounds.iter().map(Bound::upper).collect();
    let n_evals = std::cell::Cell::new(0usize);
    let forward = |point: &[f32]| -> Result<Vec<f32>> {
        if let Some(output) = advice.and_then(|advice| advice.forward(point)) {
            return Ok(output);
        }
        forward_point_vec(diff, point)
    };

    // Deadline-aware eval: the search is a bounded SLICE of the arm budget
    // (never the whole wall); expiry keeps the best-so-far incumbent.
    let eval = |x: &[f32]| -> Option<f32> {
        if stopped() {
            return None;
        }
        n_evals.set(n_evals.get() + 1);
        let out = forward(x).ok()?;
        let dev = out
            .iter()
            .map(|v| v.abs())
            .fold(f32::NEG_INFINITY, f32::max);
        dev.is_finite().then_some(dev)
    };

    let mut best: Option<(Vec<f32>, f32)> = None;
    // Top-K candidate pool (#34-class): the PGD stage seeds from the K most
    // -deviating points seen anywhere in the grid/random sweep, not just the
    // single incumbent — a near-miss local peak elsewhere in the box is often
    // the true witness basin.
    const SEED_POOL: usize = 8;
    let mut pool: Vec<(Vec<f32>, f32)> = Vec::new();
    let consider = |best: &mut Option<(Vec<f32>, f32)>,
                    pool: &mut Vec<(Vec<f32>, f32)>,
                    x: Vec<f32>,
                    v: f32| {
        if best.as_ref().map(|(_, b)| v > *b).unwrap_or(true) {
            *best = Some((x.clone(), v));
        }
        if pool.len() < SEED_POOL {
            pool.push((x, v));
            pool.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        } else if pool.last().map(|(_, w)| v > *w).unwrap_or(false) {
            pool.pop();
            pool.push((x, v));
            pool.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        }
    };

    let threshold = epsilon + f32_to_f64_exact(MONOTONIC_REVALIDATION_MARGIN);
    // EARLY EXIT + VISIBILITY: a silent decline is undiagnosable — always log
    // best deviation, argmax, eval count, and wall time. A SAT witness needs
    // ONE point past the band; the moment `best` crosses `threshold` we stop
    // and report. UNSAT runs the full budget and returns None — but ALWAYS
    // logs, so a MISS is diagnosable live rather than invisible.
    let crossed = |best: &Option<(Vec<f32>, f32)>| {
        best.as_ref()
            .is_some_and(|(_, v)| f32_to_f64_exact(*v) > threshold)
    };
    let finish = |best: &Option<(Vec<f32>, f32)>| -> Option<Vec<f32>> {
        if cancelled() {
            tracing::info!(
                n_evals = n_evals.get(),
                elapsed_s = started.elapsed().as_secs_f64(),
                "iso falsifier: cooperatively cancelled"
            );
            return None;
        }
        match best {
            Some((x, v)) => {
                let over = f32_to_f64_exact(*v) > threshold;
                tracing::info!(
                    best_dev = *v,
                    eps = epsilon,
                    over_eps = over,
                    n_evals = n_evals.get(),
                    elapsed_s = started.elapsed().as_secs_f64(),
                    argmax = ?x,
                    "iso falsifier: search complete ({})",
                    if over { "WITNESS" } else { "no violation" }
                );
                over.then(|| x.clone())
            }
            None => {
                tracing::info!(
                    n_evals = n_evals.get(),
                    elapsed_s = started.elapsed().as_secs_f64(),
                    "iso falsifier: search complete (no evaluable point — deadline before first eval?)"
                );
                None
            }
        }
    };

    // (a) Deterministic grid over the free axes (degenerate axes pinned),
    // budget-capped: ticks chosen so the grid stays ≤ ~20k evals.
    let free: Vec<usize> = (0..dim).filter(|&k| hi[k] > lo[k]).collect();
    if !free.is_empty() {
        let ticks: usize = match free.len() {
            1 => 4096,
            2 => 128,
            3 => 27,
            4 => 12,
            5 => 7,
            _ => 3,
        };
        let axis_tick = |k: usize, t: usize| -> f32 {
            let (l, h) = (lo[k], hi[k]);
            let frac = t as f32 / (ticks - 1).max(1) as f32;
            (l + frac * (h - l)).clamp(l, h)
        };
        let total = ticks.pow(free.len().min(8) as u32);
        for flat in 0..total {
            if cancelled() {
                return finish(&best);
            }
            let mut x = lo.clone();
            let mut rest = flat;
            for &k in &free {
                x[k] = axis_tick(k, rest % ticks);
                rest /= ticks;
            }
            if let Some(v) = eval(&x) {
                consider(&mut best, &mut pool, x, v);
            }
        }
    }
    if crossed(&best) {
        return finish(&best);
    }

    // (b) Fixed-seed uniform random restarts (reproducible verdict). #34
    // recipe: the winning numpy falsifier used 200k uniform samples — the
    // 5-D box affords it (deterministic count, deadline-guarded inside
    // `eval`; the sparse 4096 draw missed a real 0.0532 witness).
    const RANDOM_RESTARTS: usize = 200_000;
    let mut rng = SearchRng(0x9E37_79B9_7F4A_7C15);
    for _ in 0..RANDOM_RESTARTS {
        if cancelled() {
            return finish(&best);
        }
        let x: Vec<f32> = (0..dim).map(|k| rng.uniform(lo[k], hi[k])).collect();
        if let Some(v) = eval(&x) {
            consider(&mut best, &mut pool, x, v);
        }
    }
    if crossed(&best) {
        return finish(&best);
    }

    // (b2) MULTIPLICATIVE-step coordinate ascent from the top pool (#34
    // recipe): per round, every pool candidate tries a random coordinate
    // nudge of size `10^u(-4,-1) x dim width` with random sign — the
    // log-uniform step ladder crosses basins the fixed-fraction ascent and
    // the gradient stage plateau on. Fixed-seed, deadline-guarded.
    {
        let mut seeds: Vec<Vec<f32>> = pool.iter().map(|(x, _)| x.clone()).collect();
        if seeds.is_empty() {
            if let Some((x, _)) = &best {
                seeds.push(x.clone());
            }
        }
        'rounds: for _ in 0..60 {
            for xi in 0..seeds.len() {
                let cur = eval(&seeds[xi]);
                let Some(mut cur_v) = cur else { break 'rounds };
                for _ in 0..4 {
                    let k = (rng.next_u64() as usize) % dim;
                    if hi[k] <= lo[k] {
                        continue;
                    }
                    // log-uniform step in [1e-4, 1e-1] x width, random sign.
                    let u = rng.uniform(-4.0, -1.0);
                    let step = (hi[k] - lo[k]) * 10f32.powf(u);
                    let sign = if rng.next_u64() & 1 == 0 { 1.0 } else { -1.0 };
                    let mut trial = seeds[xi].clone();
                    trial[k] = (trial[k] + sign * step).clamp(lo[k], hi[k]);
                    if let Some(tv) = eval(&trial) {
                        if tv > cur_v {
                            cur_v = tv;
                            seeds[xi] = trial.clone();
                            consider(&mut best, &mut pool, trial, tv);
                        }
                    } else {
                        break 'rounds; // deadline
                    }
                }
            }
        }
    }
    if crossed(&best) {
        return finish(&best);
    }

    // (c) Bounded coordinate ascent from the incumbent.
    if let Some((mut x, mut v)) = best.clone() {
        for _ in 0..64 {
            let mut improved = false;
            for k in 0..dim {
                if hi[k] <= lo[k] {
                    continue;
                }
                let step = (hi[k] - lo[k]) * 0.05;
                for dir in [step, -step] {
                    let mut trial = x.clone();
                    trial[k] = (trial[k] + dir).clamp(lo[k], hi[k]);
                    if let Some(tv) = eval(&trial) {
                        if tv > v {
                            x = trial;
                            v = tv;
                            improved = true;
                        }
                    }
                }
            }
            if !improved {
                break;
            }
        }
        best = Some((x, v));
    }
    if crossed(&best) {
        return finish(&best);
    }

    // (d) Gradient-guided PGD refinement (#34-class fix: a 0.0532 deviation
    // sat witness sat between grid points where axis-aligned coordinate
    // ascent stalls — DIAGONAL moves need the gradient). Numeric central
    // differences of the active deviation `s * h_{i*}(x)` (i* = argmax |h_i|,
    // s = its sign), signed-gradient steps with a decaying step size,
    // launched from the incumbent plus fixed-seed random restarts. Purely a
    // candidate generator: the dual-forward revalidation stays the gate.
    {
        let active = |x: &[f32]| -> Option<(usize, f32, f32)> {
            if stopped() {
                return None;
            }
            n_evals.set(n_evals.get() + 1);
            let out = forward(x).ok()?;
            let (mut bi, mut bv) = (0usize, f32::NEG_INFINITY);
            for (i, o) in out.iter().enumerate() {
                if o.abs() > bv {
                    bv = o.abs();
                    bi = i;
                }
            }
            bv.is_finite()
                .then(|| (bi, if out[bi] >= 0.0 { 1.0 } else { -1.0 }, bv))
        };
        let mut starts: Vec<Vec<f32>> = pool.iter().map(|(x, _)| x.clone()).collect();
        if let Some((x, _)) = &best {
            if starts.is_empty() {
                starts.push(x.clone());
            }
        }
        for _ in 0..4 {
            starts.push((0..dim).map(|k| rng.uniform(lo[k], hi[k])).collect());
        }
        for start in starts {
            let mut x = start;
            let Some((mut oi, mut os, mut v)) = active(&x) else {
                break; // deadline
            };
            consider(&mut best, &mut pool, x.clone(), v);
            let mut eta = 0.2f32;
            for _ in 0..48 {
                if stopped() {
                    break;
                }
                // The optional prepared template supplies an analytic search
                // direction. The dark path keeps the original central differences.
                let analytic = advice.and_then(|advice| advice.signed_gradient(&x, oi, os));
                let mut grad = vec![0.0f32; dim];
                let mut ok = true;
                if let Some(direction) = analytic {
                    grad = direction;
                    ok = !stopped();
                } else {
                    for k in 0..dim {
                        if hi[k] <= lo[k] {
                            continue;
                        }
                        let h = (hi[k] - lo[k]) * 1e-3;
                        let mut xp = x.clone();
                        xp[k] = (xp[k] + h).clamp(lo[k], hi[k]);
                        let mut xm = x.clone();
                        xm[k] = (xm[k] - h).clamp(lo[k], hi[k]);
                        let (Ok(op), Ok(om)) = (forward(&xp), forward(&xm)) else {
                            ok = false;
                            break;
                        };
                        if stopped() {
                            ok = false;
                            break;
                        }
                        grad[k] = os
                            * (op.get(oi).copied().unwrap_or(0.0)
                                - om.get(oi).copied().unwrap_or(0.0));
                    }
                }
                if !ok {
                    break;
                }
                let mut trial = x.clone();
                for k in 0..dim {
                    if hi[k] <= lo[k] || grad[k] == 0.0 {
                        continue;
                    }
                    let step = (hi[k] - lo[k]) * eta * grad[k].signum();
                    trial[k] = (trial[k] + step).clamp(lo[k], hi[k]);
                }
                match active(&trial) {
                    Some((ti, ts, tv)) if tv > v => {
                        x = trial;
                        oi = ti;
                        os = ts;
                        v = tv;
                        consider(&mut best, &mut pool, x.clone(), v);
                    }
                    Some(_) => {
                        eta *= 0.5;
                        if eta < 1e-3 {
                            break;
                        }
                    }
                    None => break, // deadline
                }
            }
        }
    }

    finish(&best)
}

/// Isomorphic SAT falsifier: search the shared box for an epsilon-band
/// violation, then emit `sat` ONLY after the independent dual-forward
/// revalidation — internal pre-filter plus the trusted ORT confirmation of
/// both ORIGINAL models — confirms it (0-wrong: any miss returns `None` and
/// the caller proceeds to the sound verify path).
fn try_isomorphic_shared_sat(
    diff: &GraphNetwork,
    graph_f: &GraphNetwork,
    graph_g: &GraphNetwork,
    onnx_f: &Path,
    onnx_g: &Path,
    dual: &DualNetworkSpec,
    epsilon: f64,
    deadline: std::time::Instant,
) -> Option<String> {
    let search_bounds: Vec<Bound> = dual
        .f_input_bounds
        .iter()
        .map(|&declared| inward_bound(declared))
        .collect();
    let candidate = search_isomorphic_deviation(diff, &search_bounds, epsilon, deadline)?;
    revalidate_isomorphic_witness(graph_f, graph_g, onnx_f, onnx_g, &candidate, dual, epsilon)
}

#[allow(clippy::too_many_arguments)]
fn try_isomorphic_shared_sat_with_vjp(
    diff: &GraphNetwork,
    graph_f: &GraphNetwork,
    graph_g: &GraphNetwork,
    onnx_f: &Path,
    onnx_g: &Path,
    dual: &DualNetworkSpec,
    epsilon: f64,
    deadline: std::time::Instant,
    enabled: bool,
) -> Option<String> {
    if !enabled {
        return try_isomorphic_shared_sat(
            diff, graph_f, graph_g, onnx_f, onnx_g, dual, epsilon, deadline,
        );
    }
    let bounds: Vec<Bound> = dual
        .f_input_bounds
        .iter()
        .map(|&bound| inward_bound(bound))
        .collect();
    eprintln!("[relational-vjp] requested source=preset original_deadline=1");
    let Some(advice) = relational_vjp::DenseTwinAdvice::build(graph_f, graph_g, &bounds, deadline)
    else {
        eprintln!("[relational-vjp] declined reason=unsupported_original_tower_template");
        return try_isomorphic_shared_sat(
            diff, graph_f, graph_g, onnx_f, onnx_g, dual, epsilon, deadline,
        );
    };
    eprintln!("[relational-vjp] armed source=preset device=cpu grid_random_coordinate_pgd_caps_unchanged=1 analytic_template_gradient=1");
    let candidate =
        search_isomorphic_deviation_with_advice(diff, &bounds, epsilon, deadline, Some(&advice));
    advice.receipt();
    revalidate_isomorphic_witness(graph_f, graph_g, onnx_f, onnx_g, &candidate?, dual, epsilon)
}

/// Format a VNN-COMP 2026 dual-network counterexample in the mandatory
/// VNN-LIB 2.0 section 5.3 textual assignment format. The official checker
/// consumes networks in source order and each network's input before output;
/// indexed SMT pairs such as `(X_f[0] value)` are not valid VNN-LIB 2.0
/// assignments.
fn relational_counterexample_vnnlib(
    dual: &DualNetworkSpec,
    xf: &[f32],
    xg: &[f32],
    yf: &[f32],
    yg: &[f32],
) -> Result<String> {
    if dual.networks.len() != 2 {
        anyhow::bail!("relational counterexample requires exactly two declared networks");
    }
    let f_index = dual
        .networks
        .iter()
        .position(|network| network.name == "f")
        .unwrap_or(0);
    let g_index = dual
        .networks
        .iter()
        .position(|network| network.name == "g")
        .unwrap_or(1);
    if f_index == g_index {
        anyhow::bail!("relational counterexample could not distinguish f and g networks");
    }

    let mut declarations = Vec::with_capacity(4);
    let mut inputs: Vec<f64> = Vec::with_capacity(xf.len() + xg.len());
    let mut outputs = Vec::with_capacity(yf.len() + yg.len());
    for (index, network) in dual.networks.iter().enumerate() {
        let (network_input, network_output) = if index == f_index {
            (xf, yf)
        } else if index == g_index {
            (xg, yg)
        } else {
            anyhow::bail!("unexpected relational network index {index}");
        };
        declarations.push(TensorDeclaration {
            network: Some(network.name.clone()),
            name: network.input.clone(),
            element_type: network.input_type.clone(),
            shape: network.input_shape.clone(),
            kind: TensorDeclarationKind::Input,
        });
        declarations.push(TensorDeclaration {
            network: Some(network.name.clone()),
            name: network.output.clone(),
            element_type: network.output_type.clone(),
            shape: network.output_shape.clone(),
            kind: TensorDeclarationKind::Output,
        });
        // Decode f32 bits directly so subnormal witness values remain exact
        // even if the calling thread has DAZ enabled. The renderer keeps full
        // f64 precision (#witness-f64-render).
        inputs.extend(network_input.iter().map(|&value| f32_to_f64_exact(value)));
        outputs.extend(network_output.iter().map(|&value| f32_to_f64_exact(value)));
    }
    format_vnnlib2_assignment(&declarations, &inputs, &outputs)
}

fn add_concat_chain(graph: &mut GraphNetwork, final_name: &str, inputs: &[&str]) -> Result<()> {
    let mut current = inputs[0].to_string();
    for (idx, next) in inputs.iter().enumerate().skip(1) {
        let name = if idx == inputs.len() - 1 {
            final_name.to_string()
        } else {
            format!("{final_name}_{idx}")
        };
        graph.try_add_node(GraphNode::binary(
            name.clone(),
            Layer::Concat(ConcatLayer::new(0)),
            current,
            (*next).to_string(),
        ))?;
        current = name;
    }
    Ok(())
}

fn copy_prefixed_network(
    dst: &mut GraphNetwork,
    src: &GraphNetwork,
    prefix: &str,
    input_node: &str,
) -> Result<()> {
    for name in src.node_names() {
        let node = src
            .node(name)
            .ok_or_else(|| anyhow!("node '{name}' missing in source graph"))?;
        let inputs = node
            .inputs()
            .iter()
            .map(|input| {
                if input == NETWORK_INPUT {
                    input_node.to_string()
                } else {
                    format!("{prefix}{input}")
                }
            })
            .collect();
        dst.try_add_node(GraphNode::new(
            format!("{prefix}{name}"),
            node.layer().clone(),
            inputs,
        ))?;
    }
    Ok(())
}

/// Convert the frozen negative aggregate-memory guard into the positive graph
/// execution decision. Keeping this at the VNN-COMP entry boundary prevents a
/// later process-environment mutation from changing the scored run.
pub(in crate::commands) fn chunk_wave_parallel_enabled_from_levers(
    frozen_levers: &ny_levers::LeverSet,
) -> bool {
    !frozen_levers.is_armed(&ny_levers::decls::crown_ibp_budget::NO_CHUNK_WAVE_PAR)
}

/// #fast-f32-prewarm-all-hosts: when `bab.fast_f32_prewarm` (or its
/// environment alias `NY_FAST_F32_PREWARM`) is armed, materialize the
/// registered process-global fast-f32 GEMM factory NOW — before any lane can
/// consult it under finite deadline authority, where resolution deliberately
/// fails closed on a cold slot. Dark by default: the shipped state performs
/// no call at all and is byte-identical to today. The CUDA build's own
/// unconditional vnncomp prewarm is unaffected (a second materialization of
/// an already-published slot is a no-op).
/// Returns `None` when the gate is dark (no call was made at all — the
/// shipped, byte-identical state) and `Some(ready)` when armed, where
/// `ready` is [`ny_propagate::fast_f32_gemm::prewarm_fast_f32_gemm`]'s own
/// answer — true exactly when `fast_f32_gemm::is_preinitialized()` now holds,
/// which is what every finite-deadline consumer checks.
pub(in crate::commands) fn prewarm_fast_f32_for_all_hosts_if_armed() -> Option<bool> {
    if !ny_propagate::preset_gates::fast_f32_prewarm_armed() {
        return None;
    }
    let ready = ny_propagate::fast_f32_gemm::prewarm_fast_f32_gemm();
    let backend = ny_propagate::fast_f32_gemm::telemetry_snapshot().backend;
    tracing::info!(
        "[fast_f32_prewarm] armed: fast f32 GEMM materialized={ready} backend={backend:?} \
         before any finite-deadline consumer"
    );
    Some(ready)
}

/// Invoke β-CROWN with the AUTO defaults, capture the rendered competition JSON, and
/// translate it to a VNN-COMP result.
///
/// All capture state is torn down before returning, even on error. A verification
/// error (the `Result` is `Err`) that did NOT crash maps to the sound `unknown`,
/// except for a structurally preserved verifier deadline, which maps to `timeout`.
/// `error` is reserved for the file-validation failures handled by the caller.
fn run_and_translate(
    onnx: &Path,
    vnnlib: &Path,
    preset: Option<&Path>,
    ny_timeout: u64,
    instance_deadline: Option<std::time::Instant>,
    beta_phase_deadline: Option<std::time::Instant>,
    solver_phase_deadline: Option<std::time::Instant>,
    postbab_wrapper_route: PostBabWrapperRoute,
    preset_snapshot: Option<BetaCrownPresetSnapshot>,
    frozen_levers: Option<std::sync::Arc<ny_levers::LeverSet>>,
    frozen_margin_row_schedule_policy: Option<
        super::margin_row_bab::MarginRowScheduleRuntimePolicy,
    >,
    global_rayon_outcome: super::margin_row_bab::GlobalRayonOutcome,
) -> VnncompResult {
    // PRESET AUTHORITY GATE: a YAML-valid preset can still be semantically
    // invalid (unsupported branching/attack/model-loader policy, invalid
    // numeric config, and so on). The immutable snapshot validates those
    // decisions before this function. Reject an invalid snapshot before TLL,
    // upfront APGD, concurrent margin work, or any other wrapper verdict lane:
    // none may earn a verdict from configuration the verifier would reject.
    //
    // No-preset calls remain historical. A loaded snapshot is the exact same
    // object later handed to β-CROWN, so there is no second path read or TOCTOU.
    if let Some(error) = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::invalid_error)
    {
        eprintln!(
            "Invalid VNN-COMP preset; suppressing all wrapper fast paths and returning \
             sound unknown: {error}"
        );
        return VnncompResult::Unknown;
    }

    // PHASE-2 AUTHORITY: runtime consumes the exact Arc whose receipt was
    // serialized by `FlightRecorder::materialize_levers`. Missing or malformed
    // authority fails to sound unknown; reopening the live process environment
    // here would make execution disagree with its entry-time evidence.
    let Some(frozen_levers) = frozen_levers else {
        eprintln!(
            "VNN-COMP run has no materialized LeverSet; suppressing wrapper fast paths and \
             returning sound unknown"
        );
        return VnncompResult::Unknown;
    };
    let upfront_attack_policy = match UpfrontAttackPolicy::from_levers(&frozen_levers) {
        Ok(policy) => policy,
        Err(error) => {
            eprintln!(
                "Invalid frozen VNN-COMP upfront policy; suppressing wrapper fast paths and \
                 returning sound unknown: {error}"
            );
            return VnncompResult::Unknown;
        }
    };
    let exact_vjp_policy = match ExactVjpPgdConfig::from_levers(&frozen_levers) {
        Ok(policy) => policy,
        Err(error) => {
            eprintln!(
                "Invalid frozen VNN-COMP exact-VJP policy; suppressing wrapper fast paths and \
                 returning sound unknown: {error}"
            );
            return VnncompResult::Unknown;
        }
    };
    let kfsb_cert_reuse_armed = frozen_levers.is_armed(&ny_levers::decls::kfsb::MO_KFSB_CERT_REUSE);
    let chunk_wave_parallel_enabled = chunk_wave_parallel_enabled_from_levers(&frozen_levers);
    let postbab_reserve_policy = match PostBabReservePolicy::from_levers(&frozen_levers) {
        Ok(policy) => policy,
        Err(error) => {
            eprintln!(
                "Invalid frozen VNN-COMP post-BaB reserve policy; suppressing wrapper fast paths \
                 and returning sound unknown: {error}"
            );
            return VnncompResult::Unknown;
        }
    };
    let postbab_restart_policy = match PostBabRestartPolicy::from_levers(&frozen_levers) {
        Ok(policy) => policy,
        Err(error) => {
            eprintln!(
                "Invalid frozen VNN-COMP post-BaB restart policy; suppressing wrapper fast \
                 paths and returning sound unknown: {error}"
            );
            return VnncompResult::Unknown;
        }
    };
    // #lsnc-attack-twin: resolved from the SAME frozen LeverSet as the receipt.
    let point_folded_twin_policy =
        match attack_twin_lane::PointFoldedTwinPolicy::from_levers(&frozen_levers) {
            Ok(policy) => policy,
            Err(error) => {
                eprintln!(
                    "Invalid frozen VNN-COMP point-folded-twin policy; suppressing wrapper fast \
                     paths and returning sound unknown: {error}"
                );
                return VnncompResult::Unknown;
            }
        };
    point_folded_twin_policy.announce();
    let bnn_falsification_policy = match BnnFalsificationPolicy::from_levers(&frozen_levers) {
        Ok(policy) => policy,
        Err(error) => {
            eprintln!(
                "Invalid frozen VNN-COMP BNN falsification policy; suppressing wrapper fast \
                 paths and returning sound unknown: {error}"
            );
            return VnncompResult::Unknown;
        }
    };
    let mut margin_row_runtime_policy =
        match ny_propagate::margin_row::MarginRowRuntimePolicy::from_levers(&frozen_levers) {
            Ok(policy) => policy,
            Err(error) => {
                eprintln!(
                    "Invalid frozen VNN-COMP margin-row policy; suppressing wrapper fast paths \
                     and returning sound unknown: {error}"
                );
                return VnncompResult::Unknown;
            }
        };
    // #router-r5 CR-RS: margin-row capabilities the acting router ROUTED on
    // this row (only at SR.seal, never over a pinned key) are configured on
    // the lane's frozen policy here, before any lane reads it. A no-op (one
    // atomic load) unless one was routed — every row today.
    crate::router::route::apply_to_margin_row(&mut margin_row_runtime_policy);
    let prepared_classwise_requested = margin_row_runtime_policy.classwise;

    let Some(margin_row_schedule_policy) = frozen_margin_row_schedule_policy else {
        eprintln!(
            "VNN-COMP run has no frozen margin-row schedule policy; suppressing wrapper fast \
             paths and returning sound unknown"
        );
        return VnncompResult::Unknown;
    };

    // #lever-reachability: write every compatibility-cell-backed promoted
    // lever from the already-validated snapshot, ONCE, here. Receipt-owned
    // full-policy families above bypass these process-wide cells.
    //
    // WHY HERE AND NOT NEXT TO EACH LANE. Several of these readers latch their
    // answer in a `OnceLock` (the historical hot-path shape), so a cell written
    // after the latch is taken is invisible. This point is after the preset
    // AUTHORITY gate above — an invalid preset must never arm anything — and
    // before the attack slice, the root phases and the margin-row lane, which
    // is every consumer in the batch.
    //
    // Authored typed values arrive here; absent values retain each declaration's
    // default. The CIFAR100/TinyImageNet presets enable the frozen-dual parent
    // and four breakpoint refinement steps with bounded automatic admission.
    // The unarmed-promotion pin covers only keys still absent from shipped
    // presets; it does not suppress delivery for an explicitly armed family.
    if let Some(loaded) = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::loaded)
    {
        crate::preset_gates::apply(loaded);
    }
    // #graph-free-candidates: the armed line, printed once per ARMED run
    // before any lane starts (after the bridge above, so a yaml arming is
    // visible), so an armed run whose graph-free lane never engages is
    // distinguishable from a dark one. Dark: nothing is printed.
    if crate::preset_gates::graph_free_candidate_sidefile_armed() {
        eprintln!(
            "[graph-free-candidates] armed=1 source={} key={} schema={}",
            crate::preset_gates::graph_free_candidate_sidefile_source(),
            graph_free_sidefile::PRESET_KEY,
            graph_free_sidefile::SCHEMA,
        );
    }

    // #fast-f32-prewarm-all-hosts (dark, bab.fast_f32_prewarm /
    // NY_FAST_F32_PREWARM): materialize the registered fast-f32 GEMM factory
    // for EVERY build on the vnncomp route, not only CUDA. Finite-deadline
    // consumers (`fast_f32_gemm::resolve_engine_for_deadline`) deliberately
    // fail closed on a cold OnceLock, so on a non-CUDA host the factory
    // installed by #cpu-gemm-engine is otherwise never materialized and the
    // Conv2d Patches compose's GEMM of last resort becomes the quarantined
    // WGPU proof adapter (reports/measured-2026/cct_bound_gap_2026-08-31).
    // Must run AFTER the preset bridge above (the cell is written there) and
    // BEFORE any lane consults the slot under finite authority. For the CPU
    // faer engine the materialization is allocation-free.
    prewarm_fast_f32_for_all_hosts_if_armed();

    // Reserve the sole WGPU-context slot before any wrapper falsification
    // wave can materialize its attack device. The later in-process β-CROWN
    // call receives `backend=None` and `gpu=false`, so its request is exactly
    // determined by this frozen preset pin or the VNN-LIB input-size AUTO rule.
    // When that request is WGPU, β-CROWN owns qualification and reuses the
    // admitted proof device for attacks. Sequential CPU/ORT falsification
    // remains enabled; only the separate wrapper WGPU pre-wave is suppressed.
    let preset_device = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| preset.general.device.as_deref());
    let margin_row_concurrent_gpu_device_premise =
        preset_device.is_some_and(|device| matches!(device, "wgpu" | "cuda" | "metal" | "gpu"));
    let input_element_count = ny_onnx::vnnlib::load_vnnlib(vnnlib)
        .ok()
        .map(|spec| spec.num_inputs);
    let beta_requests_wgpu = vnncomp_beta_requests_wgpu(
        preset_device,
        input_element_count,
        accelerator_capability_hint(),
    );
    let _beta_wgpu_context_reservation = BetaWgpuContextReservation::enter(beta_requests_wgpu);

    // The proof-tail route's absolute β deadline is the last instant at which
    // optional proof work may run. The interval after it belongs exclusively
    // to verdict normalization and RESULTS_FILE publication.
    let post_beta_deadline = post_beta_work_deadline(instance_deadline, beta_phase_deadline);
    let proof_tail_reserved = beta_phase_deadline.is_some();

    // Release-dark structural probe for Two-Level-Lattice (TLL) nets
    // (tllverifybench_2023). Its decoded lattice bound is useful, but finite
    // NY/ORT samples do not authenticate equality with the authored graph.
    // `try_tll_unsat` therefore always declines until a raw graph-identity and
    // source-property certificate lands; do not restore verdict authority by
    // merely flipping its source gate. See `tll_structure`.
    // TLL decoding performs non-interruptible model loading and an ORT
    // cross-check. It therefore cannot be admitted when a fixed proof tail is
    // reserved; the ordinary verifier retains the full bounded proof phase.
    if !proof_tail_reserved {
        if let Some(res) = super::tll_structure::try_tll_unsat(onnx, vnnlib) {
            crate::flight::note(
                "tll_fast_path",
                crate::flight::FlightStatus::Ran,
                Some(
                    "TLL structural lane produced the verdict; later lanes not reached".to_string(),
                ),
            );
            return res;
        }
    }
    crate::flight::note(
        "tll_fast_path",
        crate::flight::FlightStatus::Skipped,
        Some("structural probe declined (non-TLL net or unsupported property)".to_string()),
    );

    // UPFRONT FALSIFICATION LANE (#upfront-apgd). Try the exact-gradient DLR-APGD
    // attack before the (SPSA-attack) BaB verifier: on adversarial-robustness
    // instances a nearby counterexample is found in seconds, short-circuiting to a
    // fast ORT-confirmed `sat` that the internal search otherwise misses. Routed
    // through the identical trusted-oracle gate as any other `sat`, so it is
    // soundness-safe by construction.
    //
    // VERDICT-NEUTRAL FALL-THROUGH (#upfront-gate-fallthrough, collins_rul_cnn_2022):
    // this lane may TERMINATE the run only by UPHOLDING a gated `sat`. When the gate
    // DOWNGRADES the candidate, returning its `unknown` here forfeited the instance
    // in <1s without the sound verifier ever running (19 instant unknowns on the
    // 2-clause pure-output disjunctions). Instead fall through to the normal
    // verification path, exactly as `try_upfront_falsify`'s contract documents: the
    // EXISTING per-clause disjunction machinery gets the full remaining budget to
    // refute EVERY clause (unsat), uphold a confirmed witness for SOME clause (sat,
    // through this same unchanged gate), or stay `unknown`. No gate is weakened:
    // no new sat source and no new unsat source is introduced by falling through.
    let attack_start = std::time::Instant::now();

    // SIGN-SPACE FALSIFICATION LANE (#bnn-sign-space, `attack.bnn_sign_space`,
    // override `NY_BNN_SIGN_SPACE`).
    //
    // Placed FIRST inside the attack slice, and inside it deliberately: the time
    // it spends is charged against the internal verifier budget by the same
    // `attack_start` subtraction the upfront attack pays, so arming it cannot
    // push BaB past the scored deadline. It has to run BEFORE
    // `try_upfront_falsify` because on a `Sign` net that lane takes half the
    // remaining budget (`#bnn-attack-budget`) and would leave nothing behind it.
    //
    // WHY IT IS HERE AT ALL. On a binarized net gradients through `Sign` are
    // meaningless and BaB cannot progress through a piecewise-constant
    // activation, so the DLR-APGD lane and the verifier are both structurally
    // weak; the LP-guided sign-space search is the only thing that has ever
    // taken the three `model_30` eps=1 rows
    // (`docs/BNN_SIGN_SPACE_FALSIFICATION_2026-08-12.md`).
    //
    // SOUNDNESS. The lane returns a claimed counterexample INPUT, never a
    // verdict — `ny_mip::SignSpaceOutcome` has no verified/unsat variant by
    // construction, so it cannot cause a false `unsat`. The candidate becomes a
    // `sat` only by passing the EXISTING, UNCHANGED `gate_sat_with_trusted_oracle`
    // (real ONNX Runtime forward on the ORIGINAL model + true-f64 recheck), and
    // it reaches that gate as an ORIGINAL-MODEL witness via the same
    // `rehydrate_original_witness_outputs` every rehydrating lane uses. Every other
    // outcome — refused, exhausted, disarmed — is `None` here and falls through
    // to the normal verification path with no behaviour change; that rule is
    // `sign_space_lane_verdict`, which is unit-tested.
    //
    // ARMED BY DEFAULT ON THE SCORED PATH, THROUGH THE CATEGORY PRESET
    // (`attack.bnn_sign_space`) — not globally, and not by an environment
    // variable, which is the point: a competition harness exports no `NY_*`, so
    // the typed preset key is what turns the three captured `model_30` eps=1
    // rows into an actual score. `NY_BNN_SIGN_SPACE` still WINS wherever it is
    // present, in both directions ("1" arms, "0" disarms, anything else is a
    // recorded rejection that falls back to the declaration default). The
    // entry-time `BnnFalsificationPolicy::from_levers` freezes that layered
    // answer once. With the key absent AND the variable unset, the policy is
    // disarmed and `try_sign_space_falsify` returns `None` before loading the
    // model or the property, exactly as before.
    let loaded_preset = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::loaded);
    let bnn_lower_policy = match BnnFalsificationPolicy::from_config_values(
        loaded_preset.and_then(|preset| preset.attack.bnn_sign_space),
        loaded_preset.and_then(|preset| preset.attack.bnn_sign_space_minimal_move),
        loaded_preset.and_then(|preset| preset.attack.bnn_sign_space_trust_region.as_deref()),
        loaded_preset.and_then(|preset| preset.attack.bnn_ste_pgd),
    ) {
        Ok(policy) => policy,
        Err(error) => {
            eprintln!(
                "Invalid lower VNN-COMP BNN falsification policy; suppressing wrapper fast \
                 paths and returning sound unknown: {error}"
            );
            return VnncompResult::Unknown;
        }
    };
    crate::flight::note(
        "bnn_falsification_policy",
        crate::flight::FlightStatus::Ran,
        Some(bnn_falsification_policy.flight_reason(bnn_lower_policy, cfg!(feature = "mip"))),
    );
    // #sbench-f64-attack: the post-BaB active-set caps and the float64
    // target-margin stage (`attack.active_set_repair_secs`,
    // `attack.f64_target_margin_ulps`), read once from the SAME frozen,
    // validated snapshot. Both absent — every shipped preset — resolves to
    // `PostBabActiveSetPolicy::HISTORICAL`: the historical constants, no f64
    // stage, no line printed.
    let postbab_active_set_policy =
        f64_target_attack::PostBabActiveSetPolicy::from_preset(loaded_preset);
    postbab_active_set_policy.announce();
    // The upfront lane's admission route is a pure function of the frozen
    // preset snapshot and the source-sensitive master in the entry-time
    // LeverSet. It is resolved HERE, before the attack slice starts, because
    // the Layer-A allocator below has to know whether that lane is consulted at
    // all in order to size the pool it may redistribute.
    let upfront_wrapper_route =
        upfront_wrapper_route_from_snapshot(preset_snapshot.as_ref(), upfront_attack_policy.master);
    let upfront_lower_master = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| preset.attack.upfront_attack)
        .map_or(UpfrontAttackMaster::Contextual, |armed| {
            if armed {
                UpfrontAttackMaster::ForcedByPreset
            } else {
                UpfrontAttackMaster::DisabledByPreset
            }
        });
    let upfront_lower_route =
        upfront_wrapper_route_from_snapshot(preset_snapshot.as_ref(), upfront_lower_master);
    let upfront_lower_probe_first = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| preset.attack.upfront_attack_probe_first)
        .unwrap_or(false);
    crate::flight::note(
        "upfront_attack_policy",
        crate::flight::FlightStatus::Ran,
        Some(format!(
            "schema=ny-cli/upfront-policy/v2 master={} route={} lower_master={} lower_route={} wall_cap_secs={} \
             auto_wall_cap_secs={} budget_fraction={} bnn_wall_cap_secs={} bnn_budget_fraction={} \
             probe_first={} lower_probe_first={}",
            upfront_attack_policy.master.stable_token(),
            upfront_wrapper_route.stable_token(),
            upfront_lower_master.stable_token(),
            upfront_lower_route.stable_token(),
            upfront_attack_policy.wall_cap.as_secs(),
            upfront_attack_policy.auto_wall_cap.as_secs(),
            upfront_attack_policy.budget_fraction,
            upfront_attack_policy.bnn_wall_cap.as_secs(),
            upfront_attack_policy.bnn_budget_fraction,
            upfront_attack_policy.probe_first,
            upfront_lower_probe_first,
        )),
    );
    // #attack-vertex-geometry: the upfront lane's typed step geometry and
    // corner seeds, frozen from the same preset snapshot. Both are DARK by
    // default (absent keys = the historical lane); there is no environment
    // spelling. Every consultation below reports them through
    // `UpfrontAttackShapeReceipt` whenever either is armed.
    let upfront_attack_shape =
        attack_vertex_geometry::UpfrontAttackShape::from_snapshot(preset_snapshot.as_ref());
    // #attack-open-disjuncts: arm the margin-row lane's certified-root
    // publication from the same frozen snapshot, BEFORE any lane can start
    // (the concurrent lane spawns below) and before the upfront attack, so
    // the `phase=entry` receipt prints on every armed run even when an earlier
    // lane decides it. Dark (keys absent, or `restrict: false`) = no call, no
    // line. An invalid value is rejected by the preset load itself.
    if let Some(policy) = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| crate::preset::open_disjunct_attack_from_preset(preset).ok())
        .flatten()
        .filter(|policy| policy.restrict)
    {
        crate::commands::beta_crown::arm_open_disjunct_attack(policy);
    }

    // UPFRONT ATTACK PROBE-FIRST (#upfront-probe-first,
    // `NY_UPFRONT_ATTACK_PROBE_FIRST`, DARK BY DEFAULT).
    //
    // WHAT IT IS: one extra consultation of the SAME upfront lane that already
    // sits at the bottom of this slice, here at the TOP, under a small fixed
    // cap. Nothing else moves: on a miss the two BNN lanes and the ordinary
    // upfront consultation run afterwards in today's order under today's
    // windows, and the probe's seconds are charged against the same
    // `attack_start` subtraction every lane in this slice pays, so it cannot
    // push branch-and-bound past the scored deadline.
    //
    // WHY, MEASURED. On the five `traffic_signs model_30_idx_{6371,178}`
    // eps>=3 rows the verdict is decided by the LAST 0.2% of the wall: 15/15
    // default-path runs at HEAD `002abbb2e` are won by THIS lane in 1-2 exact
    // gradient steps and 2-3 ORT forwards -- but it runs third, so the win
    // lands at t=242.7-336.8 s, behind an LP sign-space walk that exhausts (or
    // refuses in 0.02 s) and an STE-PGD lane that burns its full 240 s cap and
    // exhausts. Those rows are not budget-limited and not capability-limited;
    // they are ORDER-limited, and the prefix is the only route by which host
    // load can lose them.
    //
    // SOUNDNESS. Identical to the lane's ordinary consultation, because it IS
    // that lane: it returns a claimed counterexample INPUT and never a verdict,
    // and the claim becomes a `sat` only by passing the EXISTING, UNCHANGED
    // `gate_sat_with_trusted_oracle`. A candidate the gate drops falls through
    // to the ordinary path (verdict-neutral fall-through, #upfront-gate-fallthrough).
    if upfront_attack_policy.probe_first {
        let probe_witness = try_upfront_falsify(
            onnx,
            vnnlib,
            post_beta_deadline,
            upfront_wrapper_route,
            &upfront_attack_policy,
            UpfrontAttackConsultation::ProbeFirst,
            crate::commands::lane_allocation::LaneWindow::Cap(UPFRONT_ATTACK_PROBE_CAP),
            None,
            upfront_attack_shape,
        );
        match probe_witness {
            Some(witness) => {
                let gated =
                    gate_sat_with_trusted_oracle(onnx, vnnlib, Some(&witness), instance_deadline);
                if matches!(gated, VnncompResult::Sat { .. }) {
                    crate::flight::note(
                        "upfront_attack_probe",
                        crate::flight::FlightStatus::Ran,
                        Some(
                            "sat: trusted-oracle gate confirmed the probe-first candidate; \
                             the LP sign-space and STE-PGD lanes were not reached"
                                .to_string(),
                        ),
                    );
                    return gated;
                }
                crate::flight::note(
                    "upfront_attack_probe",
                    crate::flight::FlightStatus::Ran,
                    Some(
                        "candidate rejected by the trusted-oracle gate; fell through to \
                         the ordinary attack slice"
                            .to_string(),
                    ),
                );
            }
            None => crate::flight::note(
                "upfront_attack_probe",
                crate::flight::FlightStatus::Ran,
                Some(format!(
                    "consulted under a {:.0}s cap; no confirmed candidate, falling \
                     through to the ordinary attack slice",
                    UPFRONT_ATTACK_PROBE_CAP.as_secs_f64()
                )),
            ),
        }
    } else {
        crate::flight::note(
            "upfront_attack_probe",
            crate::flight::FlightStatus::Skipped,
            Some(
                "probe-first disarmed (no attack.upfront_attack_probe_first key and no \
                 NY_UPFRONT_ATTACK_PROBE_FIRST=1); the upfront lane is consulted once, in \
                its ordinary place behind the two BNN lanes"
                    .to_string(),
            ),
        );
        note_upfront_attack_execution(
            crate::flight::FlightStatus::Skipped,
            UpfrontAttackConsultation::ProbeFirst,
            upfront_wrapper_route,
            None,
            None,
            crate::commands::lane_allocation::LaneWindow::Skip,
            post_beta_deadline
                .map(|deadline| deadline.saturating_duration_since(std::time::Instant::now())),
            "none",
            "none",
            UpfrontBudgetCompetition::NotEvaluated,
            None,
            "probe_disarmed",
        );
    }

    // LANE BUDGET ALLOCATOR, LAYER A (`NY_LANE_BUDGET_ALLOCATOR`, DARK BY
    // DEFAULT). Armed, the three lanes that actually hold the attack-slice
    // budget — the LP sign-space walk, STE-PGD and the upfront DLR-APGD attack
    // — are committed to caps chosen JOINTLY and UP FRONT by a multiple-choice
    // knapsack instead of each taking a private fraction of whatever it was
    // handed. Disarmed — which is every scored run, since a competition harness
    // exports no `NY_*` and this lever has no typed preset key —
    // `lane_allocation` is `None`, the objective probe is never taken, no
    // request is built, the solver is never entered, and every lane's window
    // comes back `LaneWindow::Private`, which is the value each call site
    // matches to take exactly the helper it takes today.
    //
    // IT STANDS DOWN UNDER `#lane-value-scheduler`. That mechanism owns the two
    // BNN lanes in flight; this one owns the caps up front. They compose, but
    // only one may hold a lane's cap at a time, so the scheduler wins where
    // both are armed.
    //
    // #lane-budget-frame (`NY_LANE_BUDGET_FRAME`, DARK BY DEFAULT) is the third
    // and WEAKEST cap authority, and it stands down under both of the others.
    // Armed alone, it commits every lane to exactly the window today's own
    // rules produce — nothing is redistributed — but it decides them ONCE, up
    // front, so a lane that declines cannot have its unspent seconds absorbed
    // by a downstream lane that would otherwise re-derive its window from the
    // LIVE remaining clock. Those seconds fall past the attack slice to the
    // branch-and-bound residual claimant instead.
    let allocator_armed = crate::commands::lane_allocation::lane_budget_allocator_armed();
    let scheduler_armed = crate::commands::lane_schedule::lane_value_scheduler_armed();
    let lane_allocation =
        if crate::commands::lane_allocation::allocator_admitted(allocator_armed, scheduler_armed) {
            plan_attack_slice_allocation(
                onnx,
                vnnlib,
                post_beta_deadline,
                bnn_falsification_policy,
                upfront_wrapper_route,
                &upfront_attack_policy,
            )
        } else if crate::commands::lane_allocation::frame_admitted(
            // #router-r2 CR-C: the acting router admits the same identity
            // frame without its lever; unarmed this is `lever || false`, i.e.
            // exactly the lever: bit-identical.
            crate::commands::lane_allocation::lane_budget_frame_armed()
                || crate::router::acting::governs_attack_slice(),
            allocator_armed,
            scheduler_armed,
        ) {
            frame_attack_slice_allocation(
                onnx,
                vnnlib,
                post_beta_deadline,
                bnn_falsification_policy,
                upfront_wrapper_route,
                &upfront_attack_policy,
            )
        } else {
            None
        };
    let committed_allocation = lane_allocation
        .as_ref()
        .map(CommittedAttackSlice::allocation);
    // #router-r2 CR-C: record the committed frame's windows as the attack
    // lanes' contracts in the one deadline authority (a no-op unless the
    // acting router governs the attack slice).
    crate::router::acting::commit_attack_contracts(committed_allocation);
    let sign_space_window = crate::commands::lane_allocation::lane_window(
        committed_allocation,
        crate::commands::lane_allocation::AllocatedLane::SignSpace,
    );
    let ste_pgd_window = crate::commands::lane_allocation::lane_window(
        committed_allocation,
        crate::commands::lane_allocation::AllocatedLane::StePgd,
    );
    let upfront_window = crate::commands::lane_allocation::lane_window(
        committed_allocation,
        crate::commands::lane_allocation::AllocatedLane::UpfrontAttack,
    );
    //
    // #lane-value-scheduler (`NY_LANE_VALUE_SCHEDULER`, DARK BY DEFAULT). Armed,
    // the two BNN lanes below run under ONE marginal-value ledger instead of
    // this chain of private fixed fractions, and the two `if let` blocks that
    // follow are SKIPPED. Disarmed -- which is every scored run, since a
    // competition harness exports no `NY_*` -- `scheduled_bnn` is `None`, the
    // scheduler module is never entered, no ledger is built, and the two blocks
    // below run exactly as they do today, in the same order, on the same
    // windows, from the same helpers.
    let scheduled_bnn = if crate::commands::lane_schedule::lane_value_scheduler_armed() {
        Some(run_bnn_lane_schedule(
            onnx,
            vnnlib,
            post_beta_deadline,
            bnn_falsification_policy,
        ))
    } else {
        None
    };
    if let Some(scheduled) = scheduled_bnn.as_ref() {
        // The SAME routing rule the unscheduled lanes use: a claimed witness
        // becomes a verdict ONLY by passing the unchanged trusted-oracle gate,
        // and anything else falls through to the ordinary path.
        if let Some((lane, witness)) = scheduled {
            if let Some(sat) = falsification_lane_verdict(
                lane,
                "Scheduled BNN falsification",
                Some(witness.clone()),
                |witness| {
                    gate_sat_with_trusted_oracle(onnx, vnnlib, Some(witness), instance_deadline)
                },
            ) {
                crate::flight::note(
                    lane,
                    crate::flight::FlightStatus::Ran,
                    Some(
                        "sat: trusted-oracle gate confirmed the scheduled lane's candidate"
                            .to_string(),
                    ),
                );
                return sat;
            }
        }
    } else if let Some(sat) = sign_space_lane_verdict(
        try_sign_space_falsify(
            onnx,
            vnnlib,
            post_beta_deadline,
            bnn_falsification_policy,
            // #router-r2 CR-1/CR-C: the lane is handed its cell's window at
            // its own start (`sign_space_window` unchanged when ungoverned).
            crate::router::acting::claim_attack_window(
                ny_core::deadline_authority::LaneSlot::AttackSignSpace,
                sign_space_window,
            ),
        ),
        |witness| gate_sat_with_trusted_oracle(onnx, vnnlib, Some(witness), instance_deadline),
    ) {
        crate::flight::note(
            "bnn_sign_space",
            crate::flight::FlightStatus::Ran,
            Some("sat: trusted-oracle gate confirmed the sign-space candidate".to_string()),
        );
        return sat;
    }
    // #router-r2 CR-H: the sign-space lane returned without a sat; hand its
    // unspent contract to the terminal (a no-op when it was not governed).
    crate::router::acting::release_lane(
        ny_core::deadline_authority::LaneSlot::AttackSignSpace,
        false,
    );

    // STE-PGD FALSIFICATION LANE (#bnn-ste-pgd, `attack.bnn_ste_pgd`, override
    // `NY_BNN_STE_PGD`).
    //
    // ARMED BY DEFAULT ON THE SCORED PATH, THROUGH THE CATEGORY PRESET, on the
    // same terms and by the same route as the LP lane above: a competition
    // harness exports no `NY_*`, so the typed key is what turns the seven
    // captured 48x48/64x64 rows into an actual score. With the key absent AND
    // the variable unset, `run_ste_pgd_lane` returns `Disarmed` before it loads
    // the model or parses the property, so an unarmed category is
    // byte-identical to the tree without this lane. `NY_BNN_STE_PGD` still WINS
    // wherever it is present, in both directions.
    //
    // PLACED AFTER THE LP LANE, ON PURPOSE — and MEASURED, not assumed. The two
    // lanes are complementary: on the three `model_30` eps=1 rows the LP search
    // owns, this lane was measured `exhausted` (best margin -222 after 97 flips
    // and 24755 probes over its whole budget), because at eps=1 the box is one
    // grey level wide and its pixel-space step degenerates to the flip-at-a-time
    // move the LP search already makes. Running it first would therefore spend
    // the slice that recovers those three rows on a search that cannot recover
    // them.
    //
    // IT DOES NOT PAY FOR THAT PLACEMENT IN BUDGET. As the TRAILING lane it
    // sizes itself by subtraction rather than halving what it is handed
    // (`DOWNSTREAM_RESERVE`, `#ste-pgd-budget`), so it reaches its full 4-minute
    // cap instead of the quarter-instance the compounding halves left it — the
    // difference between four of these rows and seven. It still pays out of the
    // same `attack_start` subtraction, so it cannot push BaB past the deadline,
    // and the reserve keeps the upfront attack the ~50 s it needs for the
    // fifteen deeper rows it already takes.
    //
    // WHY IT IS HERE AT ALL. `Sign` is piecewise constant, so its true
    // derivative is zero almost everywhere — but the STRAIGHT-THROUGH ESTIMATOR
    // runs the REAL `Sign` forward and substitutes a surrogate derivative in
    // the backward pass only, which is the standard technique for binarized
    // nets. The witnesses this reaches sit 483-1483 first-layer flips from the
    // box centre, a distance the LP lane's 7-16 accepted flips per lane cannot
    // cover (`docs/BNN_SIGN_SPACE_FALSIFICATION_2026-08-12.md` sections 5, 10).
    //
    // SOUNDNESS. Identical to the LP lane's, by sharing its machinery: the lane
    // returns a claimed counterexample INPUT and never a verdict
    // (`ny_mip::SignSpaceOutcome` has no verified/unsat variant by
    // construction), admission is the SAME structural `admit` on the SAME
    // extracted request, and the candidate becomes a `sat` only by passing the
    // EXISTING, UNCHANGED `gate_sat_with_trusted_oracle`. Every other outcome
    // is `None` here and falls through with no behaviour change — the shared
    // `falsification_lane_verdict` rule, which is unit-tested.
    if scheduled_bnn.is_none() {
        if let Some(sat) = falsification_lane_verdict(
            "bnn_ste_pgd",
            "STE-PGD falsification",
            try_ste_pgd_falsify(
                onnx,
                vnnlib,
                post_beta_deadline,
                bnn_falsification_policy,
                // #router-r2 CR-1/CR-C: the cell's window at the lane's start.
                crate::router::acting::claim_attack_window(
                    ny_core::deadline_authority::LaneSlot::AttackStePgd,
                    ste_pgd_window,
                ),
            ),
            |witness| gate_sat_with_trusted_oracle(onnx, vnnlib, Some(witness), instance_deadline),
        ) {
            crate::flight::note(
                "bnn_ste_pgd",
                crate::flight::FlightStatus::Ran,
                Some("sat: trusted-oracle gate confirmed the STE-PGD candidate".to_string()),
            );
            return sat;
        }
        // #router-r2 CR-H: undecided; hand the unspent contract on.
        crate::router::acting::release_lane(
            ny_core::deadline_authority::LaneSlot::AttackStePgd,
            false,
        );
    }

    // FALSIFICATION PORTFOLIO LANE (`NY_FALSIFY_PORTFOLIO`, DARK BY DEFAULT).
    //
    // The ported `ny-falsify` chassis: S1 `special` (declared corners, centre,
    // parity patterns, bound/centre midpoints) and S9 `square` (random block
    // sign-flip hill climbing). Both come from
    // `scripts/audit_unsat_by_falsification.py`, which has run as a one-sided
    // unsat AUDITOR for months and has never influenced a verdict; its
    // self-test refuted 75 of 100 known-SAT rows with SIX strategies and no
    // dominance among them (`reports/falsification_audit/selftest_calibration.json`).
    // These two are the ones ny ships no equivalent of: the corner lane above
    // is capped at five variable dimensions and emits vertices only, while
    // `special` won a 200-free-input row and four of its eight patterns are
    // interior; `square` is the only strategy that ever cracked soundnessbench
    // and it works against a FLAT objective, the `#deadlane` case where every
    // estimated gradient is identically zero.
    //
    // PLACED LAST INSIDE THE ATTACK SLICE, before the ordinary upfront attack.
    // It pays out of the same `attack_start` subtraction, so arming it cannot
    // push BaB past the scored deadline, and its 8%-of-remaining slice is the
    // fraction the upfront attack already takes.
    //
    // DARK, AND IT STAYS DARK UNTIL A SWEEP SAYS OTHERWISE. There is no typed
    // `attack.*` key for it, deliberately: a competition harness exports no
    // `NY_*`, so an env-only lever cannot reach a scored run. The measurement
    // that gated the port returned zero counterexamples on 42 open-row
    // measurements, and a default does not move without one.
    //
    // SOUNDNESS. `ny-falsify` has NO dependency on any workspace crate, so
    // `VnncompResult` is not nameable inside it and its `Proposal` type has no
    // verdict-bearing variant by construction; a `Candidate` carries INPUTS
    // ONLY, so no search arithmetic can reach a published witness. The
    // candidate becomes a `sat` only by passing the EXISTING, UNCHANGED
    // `gate_sat_with_trusted_oracle`, through the SAME shared
    // `falsification_lane_verdict` rule the two BNN lanes use; every other
    // outcome is `None` here and falls through with no behaviour change.
    if let Some(sat) = falsification_lane_verdict(
        "falsify_portfolio",
        "Falsification portfolio",
        falsify_portfolio::try_portfolio_falsify(onnx, vnnlib, post_beta_deadline),
        |witness| gate_sat_with_trusted_oracle(onnx, vnnlib, Some(witness), instance_deadline),
    ) {
        crate::flight::note(
            "falsify_portfolio",
            crate::flight::FlightStatus::Ran,
            Some("sat: trusted-oracle gate confirmed the portfolio candidate".to_string()),
        );
        return sat;
    }

    // #router-r3 CR-ATK (`rule.attack_defer`): the upfront lane may DEFER the
    // unspent part of its slice to a late sat reserve when its best margin
    // plateaus, but only where that reserve can be honoured: the
    // post-verifier attack is enabled, no proof tail is reserved, no
    // concurrent margin-row worker can hold the tail, and the memory envelope
    // admits the graph-heavy tail. Unarmed (every run without
    // `optimizer.mode: on`) this is `None` and the predicate is never even
    // evaluated: the lane is today's, bit for bit.
    let upfront_defer_scope = crate::router::ostop::enter_upfront_scope(|| {
        postbab_wrapper_route.attack_enabled()
            && !proof_tail_reserved
            && !(super::margin_row_bab::concurrent_lane_armed_with_policy(
                margin_row_schedule_policy,
            ) && margin_row_concurrent_gpu_device_premise)
            // #router-r4 CR-L: under an armed lease the late tail must also
            // fit the lease (a peek: nothing is reserved for a time hold);
            // unarmed this is today's live gate, evaluated once.
            && crate::router::lease::peek(
                ny_core::router::lease::LeaseHolder::PostVerifierTail,
                optional_heavy_memory_allowed_now,
            )
    });
    // #router-r2 CR-1/CR-C: the upfront lane is handed its cell's window at its
    // own start (`upfront_window` unchanged when ungoverned).
    let upfront_window = crate::router::acting::claim_attack_window(
        ny_core::deadline_authority::LaneSlot::AttackUpfront,
        upfront_window,
    );
    // A lane the allocator granted ZERO seconds is SKIPPED, not run under a
    // small cap: it is not slow on this instance, it is structurally blind, and
    // its seconds are already committed to another lane's grant or to the
    // branch-and-bound residual.
    let upfront_witness = if upfront_window == crate::commands::lane_allocation::LaneWindow::Skip {
        // The two cap authorities zero a lane for DIFFERENT reasons, so the
        // receipt is taken from the plan that actually committed the zero
        // rather than assumed to be the knapsack's structural one.
        let reason = lane_allocation.as_ref().map_or(
            crate::commands::lane_allocation::KNAPSACK_ZERO_REASON,
            |plan| plan.allocation().zero_reason(),
        );
        crate::flight::note(
            "upfront_attack",
            crate::flight::FlightStatus::Skipped,
            Some(reason.to_string()),
        );
        let plan = lane_allocation
            .as_ref()
            .expect("a skipped lane must come from a committed attack-slice plan");
        let (binding, inactive_reason) = match plan.allocation().authority() {
            crate::commands::lane_allocation::AllocationAuthority::Frame => {
                ("frame_zero", "frame_skip")
            }
            crate::commands::lane_allocation::AllocationAuthority::Knapsack => {
                ("allocator_zero", "allocator_skip")
            }
        };
        note_upfront_attack_execution(
            crate::flight::FlightStatus::Skipped,
            UpfrontAttackConsultation::Ordinary,
            upfront_wrapper_route,
            None,
            None,
            upfront_window,
            post_beta_deadline
                .map(|deadline| deadline.saturating_duration_since(std::time::Instant::now())),
            "committed_cap",
            binding,
            UpfrontBudgetCompetition::NotEvaluated,
            None,
            inactive_reason,
        );
        eprintln!("Upfront attack: SKIPPED — {reason}");
        // #attack-vertex-geometry: an armed lever still reports on a skipped
        // lane (`engaged=0 reason=not_reached`), so the skip cannot read as
        // a measured null.
        attack_vertex_geometry::UpfrontAttackShapeReceipt::emit_unconsulted(
            upfront_attack_shape,
            "lane_skipped",
        );
        None
    } else {
        try_upfront_falsify(
            onnx,
            vnnlib,
            post_beta_deadline,
            upfront_wrapper_route,
            &upfront_attack_policy,
            UpfrontAttackConsultation::Ordinary,
            upfront_window,
            lane_allocation
                .as_ref()
                .and_then(CommittedAttackSlice::upfront_decision),
            upfront_attack_shape,
        )
    };
    // #router-r3 CR-ATK: CLOSE the defer scope the moment the upfront lane
    // returns — BEFORE the trusted-oracle gate below. The gate's ORT repair
    // (`refine_witness_with_ort` -> `gradient_guided_falsify`) runs an attack
    // restart loop on this same thread; with the scope still open it would
    // read as the upfront lane, could DEFER the repair (losing the sat it
    // exists to recover) and would book a defer the lane never made. `None`
    // scope (every unarmed row) is `false`.
    let upfront_deferred = crate::router::ostop::UpfrontDeferScope::close(upfront_defer_scope);
    if let Some(witness) = upfront_witness {
        let gated = gate_sat_with_trusted_oracle(onnx, vnnlib, Some(&witness), instance_deadline);
        if matches!(gated, VnncompResult::Sat { .. }) {
            crate::flight::note(
                "upfront_attack",
                crate::flight::FlightStatus::Ran,
                Some("sat: trusted-oracle gate confirmed the upfront candidate".to_string()),
            );
            return gated;
        }
        crate::flight::note(
            "upfront_attack",
            crate::flight::FlightStatus::Ran,
            Some("candidate rejected by the trusted-oracle gate; fell through".to_string()),
        );
        eprintln!(
            "Upfront attack: candidate rejected by the trusted-oracle gate; falling \
             through to the full verification path (verdict-neutral lane)"
        );
    } else {
        // `upfront_attack_execution` already records the stable route,
        // admission, cap authority, binding control, and inactive reason. This
        // human-oriented summary only records the consultation's final result.
        crate::flight::note(
            "upfront_attack",
            crate::flight::FlightStatus::Ran,
            Some("consulted; no confirmed candidate".to_string()),
        );
    }
    // #router-r3 CR-ATK: a lane that DEFERRED releases its unspent contract to
    // the late sat reserve (held out of the verifier below), never to the
    // terminal; `None` scope (every unarmed row) is the R2 release below.
    if upfront_deferred {
        crate::router::acting::release_lane_to_reserve(
            ny_core::deadline_authority::LaneSlot::AttackUpfront,
        );
    } else {
        // #router-r2 CR-H: the upfront lane returned without a sat; hand its
        // unspent contract to the terminal, which reads the live clock below.
        crate::router::acting::release_lane(
            ny_core::deadline_authority::LaneSlot::AttackUpfront,
            false,
        );
    }
    // New separately sealed dense-head route, after trusted SAT admission and
    // before any generic root. Its complete singleton cover uses ordinary
    // G2/Instance authorization and a genuinely run G3 over the original parse.
    // Preparation/proposal/replay are charged by the same attack_start elapsed
    // subtraction below; failed attempts never restart the original deadline.
    let input_head_attempt = super::safenlp_input_head::try_input_head_with_continuation(
        onnx,
        vnnlib,
        post_beta_deadline,
        &margin_row_runtime_policy,
    );
    if let Some(verdict) = input_head_attempt.verdict {
        return verdict;
    }
    let input_head_continuation = input_head_attempt.continuation;
    // The original-file prepared engine shares its completed root with real
    // conditional search. Its sealed receipt retains all source, leaf and
    // caller resource owners through the existing final writers. The legacy
    // policies remain frozen; unsupported demands decline before source work.
    // #prepared-root-route: whether it runs is THE admission
    // (`prepared_root_route::admission`), the one predicate the router
    // registry and the admission census ask too; the route only runs on its
    // answer.
    let prepared_root_admission = super::prepared_root_route::admission(
        prepared_classwise_requested,
        &margin_row_runtime_policy,
        &frozen_levers,
    );
    let prepared_root_open = if prepared_root_admission.classwise_armed() {
        crate::flight::note(
            "prepared_root",
            crate::flight::FlightStatus::Skipped,
            Some("armed original classwise policy".to_string()),
        );
        None
    } else {
        use super::prepared_root_route::PreparedRouteOutcome;
        match super::prepared_root_route::try_prepared_root_route(
            onnx,
            vnnlib,
            &margin_row_runtime_policy,
            prepared_root_admission,
            instance_deadline,
            post_beta_deadline,
        ) {
            PreparedRouteOutcome::Proven { receipt, report } => {
                crate::flight::note(
                    "prepared_root",
                    crate::flight::FlightStatus::Ran,
                    Some(format!("{report:?}")),
                );
                return VnncompResult::Unsat(receipt);
            }
            PreparedRouteOutcome::Open { owner, report } => {
                crate::flight::note(
                    "prepared_root",
                    crate::flight::FlightStatus::Ran,
                    Some(format!("{report:?}")),
                );
                Some(owner)
            }
            PreparedRouteOutcome::Refused { report } => {
                crate::flight::note(
                    "prepared_root",
                    crate::flight::FlightStatus::Skipped,
                    Some(format!("{report:?}")),
                );
                None
            }
        }
    };
    // The old producer is now selected. Release the actual unfinished owner
    // before its allocations, while all spent time remains in attack_start.
    drop(prepared_root_open);
    // Charge the time the attack already spent against the internal verifier budget
    // so BaB still completes inside the scored deadline / watchdog window.
    let ny_timeout = ny_timeout
        .saturating_sub(attack_start.elapsed().as_secs())
        .max(1);
    let timeout_before_fixed_reserves_secs = ny_timeout;

    // TYPED f32 ROOT TABLEAU (#twinwall-provenance): arm the category's
    // `margin_row.root_f32` before ANY margin-row lane can start. The gate
    // itself lives in ny-propagate and is otherwise env-only; the workspace
    // forbids writing process environment from code, so the preset speaks to
    // it through this setter. Pure loosening — see `set_root_f32_preset`.
    if let Some(on) = super::margin_row_bab::root_f32_from_preset(preset) {
        ny_propagate::margin_row::set_root_f32_preset(on);
    }

    // BACKWARD-INTERM compatibility bridge. Branch widths and adaptive-width
    // no longer use process-global setters on the scored route: they arrive in
    // the immutable MarginRowRuntimePolicy built from `frozen_levers`.
    if let Some(secs) = super::margin_row_bab::bi_secs_from_preset(preset) {
        ny_propagate::margin_row::set_bi_secs_preset(secs);
    }
    if let Some(on) = super::margin_row_bab::backward_interm_from_preset(preset) {
        ny_propagate::margin_row::set_backward_interm_preset(on);
    }
    // #clip-and-verify / #clip-stateful: the Clip-and-Verify half's ONLY
    // competition-reachable route. It shipped env-only, so on a scored run it
    // was unreachable BY CONSTRUCTION — `run_instance.sh` exports ZERO `NY_*`
    // (its only `export` is `OMP_NUM_THREADS=1`; the 27 `NY_` mentions there are
    // local shell vars, and `NY_BIN` is a developer override READ FROM the
    // caller's environment, not set by the script). The long-repeated "exactly
    // one" was false, and the conclusion is STRONGER for it. No shipped preset
    // sets this key, so the line is a NO-OP on every config and the lane stays
    // byte-identical; it makes the mechanism DELIVERABLE, it does not arm it.
    if let Some(on) = super::margin_row_bab::clip_stateful_from_preset(preset) {
        ny_propagate::margin_row::set_clip_stateful_preset(on);
    }
    // #closure-adaptive: the tier ladder's ONLY competition-reachable route.
    // It shipped without this line, so the whole ladder was dead code on a
    // scored run — `run_instance.sh` exports no `NY_*`, so the env
    // half can never arm it. No preset sets the key yet, so this is a
    // NO-OP on every shipped config and the lane stays byte-identical; it
    // makes the ladder DELIVERABLE, it does not arm it.
    if let Some(on) = super::margin_row_bab::closure_adaptive_from_preset(preset) {
        ny_propagate::margin_row::set_closure_adaptive_preset(on);
    }
    // #branch-reduceop: abc's tuned cifar100/tinyimagenet configs use
    // `reduceop: max`; ny has always used `min`. No preset sets this yet, so
    // the lane stays byte-identical until an A/B says otherwise.
    if let Some(on) = super::margin_row_bab::branch_reduce_max_from_preset(preset) {
        ny_propagate::margin_row::set_branch_reduce_max_preset(on);
    }
    // #branch-parent-lift: recover the candidate scores the expansion already
    // paid for. No preset sets this yet, so the lane stays byte-identical; this
    // makes the key DELIVERABLE, it does not arm it.
    if let Some(on) = super::margin_row_bab::parent_lift_from_preset(preset) {
        ny_propagate::margin_row::set_parent_lift_preset(on);
    }
    // #cgan-reclaim: the set's ONLY competition-reachable route. It shipped
    // env-only (`NY_CGAN_RECLAIM`), and `run_instance.sh` exports no `NY_*`, so
    // every one of its five retention sites was dead code on a
    // scored run — the sixth mechanism in that family. No preset sets the key
    // yet, so this is a NO-OP on every shipped config and the lane stays
    // byte-identical; it makes the set DELIVERABLE, it does not arm it.
    if let Some(on) = crate::preset::cgan_reclaim_from_preset(preset) {
        ny_propagate::set_cgan_reclaim_preset(on);
    }

    // #stale-alpha: the MO-lane current-box heuristic's ONLY
    // competition-reachable route. No preset sets the key, so this is a NO-OP
    // on every shipped config and the lane stays byte-identical.
    if let Some(on) = crate::preset::mo_alpha_heuristic_from_preset(preset) {
        ny_propagate::preset_gates::set_mo_alpha_heuristic_preset(on);
    }

    // MARGIN-ROW CONCURRENT LANE (#epoch-bab): start the twin-wall lane on a
    // background CPU thread NOW, so it gets the whole instance budget instead
    // of the scraps left after the internal verifier. The wall presets run the
    // verifier on `device: wgpu`, so the two lanes are on different hardware
    // and barely contend. Its verdict is consumed only if the verifier comes
    // back undecided (see the join below); it can never produce `sat`.
    // The proof-tail route's absolute β deadline is also the latest instant at
    // which any optional proof lane may work. The fixed interval after it is
    // exclusively for verdict normalization and RESULTS_FILE publication.
    // Historical and SafeNLP routes retain their existing instance deadlines.
    // Detached margin-row workers cannot be synchronously cancelled: dropping
    // their receiver stops publication but not CPU/Rayon work. Suppress them
    // entirely under proof-tail authority so no abandoned worker can contend
    // with the fixed publication reserve.
    // #router-r4 CR-L: the concurrent margin-row worker is the first optional
    // heavy lane of the row; under an armed lease it obtains its lease here
    // (returned at once below when no worker is spawned). Unarmed: today's
    // live gate, evaluated once, bit for bit.
    let margin_row_memory_allowed = crate::router::lease::admit(
        ny_core::router::lease::LeaseHolder::MarginRowConcurrent,
        optional_heavy_memory_allowed_now,
    );
    let frozen_pgd_schedule = preset_snapshot
        .as_ref()
        .and_then(BetaCrownPresetSnapshot::loaded)
        .and_then(|preset| resolve_initial_pgd_schedule(preset).ok())
        .flatten();
    let effective_deferred_pgd_fraction = effective_deferred_pgd_fraction(preset_snapshot.as_ref());
    // #acc-strict-intervals: resolve the typed key from the SAME frozen
    // snapshot, before it moves into the β-CROWN overrides. The receipt is
    // printed only when armed, so a dark run's stderr is unchanged.
    let nonlinear_case_split = nonlinear_case_split_from_snapshot(preset_snapshot.as_ref());
    if nonlinear_case_split {
        eprintln!("[nonlinear-case-split] armed=1 source=preset key=nonlinear_vnnlib.case_split");
    }
    let deferred_pgd_consumer_available =
        postbab_deferred_pgd_consumer_available(postbab_wrapper_route, margin_row_memory_allowed);
    let deferred_outer_pgd_priority =
        deferred_outer_pgd_has_priority(frozen_pgd_schedule, deferred_pgd_consumer_available);
    let margin_row_schedule_outer_route = if proof_tail_reserved {
        MarginRowScheduleOuterRoute::ProofTail
    } else if deferred_outer_pgd_priority {
        MarginRowScheduleOuterRoute::DeferredPgd
    } else if !margin_row_memory_allowed {
        MarginRowScheduleOuterRoute::Memory
    } else {
        MarginRowScheduleOuterRoute::Actionable
    };
    let (concurrent_route, concurrent_resources, concurrent_lane) =
        if margin_row_schedule_outer_route == MarginRowScheduleOuterRoute::Actionable {
            let admission = super::margin_row_bab::spawn_concurrent_lane_with_schedule_policy(
                onnx,
                vnnlib,
                post_beta_deadline,
                margin_row_runtime_policy,
                margin_row_schedule_policy,
                global_rayon_outcome,
                margin_row_concurrent_gpu_device_premise,
            );
            (
                admission.route.stable_token(),
                admission.resources,
                admission.lane,
            )
        } else {
            (
                "outer_suppressed",
                super::margin_row_bab::ConcurrentLaneResourceOutcome::NOT_CONSULTED,
                None,
            )
        };
    if concurrent_lane.is_none() {
        // #router-r4 CR-L: no worker, no working set: return its lease (a
        // no-op when no lease is armed or none was granted).
        crate::router::lease::release(ny_core::router::lease::LeaseHolder::MarginRowConcurrent);
    }
    if concurrent_lane.is_some() {
        crate::flight::note(
            "margin_row_concurrent",
            crate::flight::FlightStatus::Ran,
            Some("twin-wall lane spawned at instance start".to_string()),
        );
    } else {
        crate::flight::note(
            "margin_row_concurrent",
            crate::flight::FlightStatus::Skipped,
            Some(if proof_tail_reserved {
                "lane suppressed by proof-tail publication authority".to_string()
            } else if deferred_outer_pgd_priority {
                "lane suppressed so the frozen deferred-PGD owner receives its exclusive tail"
                    .to_string()
            } else if !margin_row_memory_allowed {
                format!(
                    "lane not started; independently, graph-heavy optional work is prohibited \
                     when the live cgroup/RLIMIT envelope is unavailable or below the {} GiB \
                     headroom boundary; {}=1 is the explicit operator override",
                    OPTIONAL_HEAVY_MIN_HEADROOM_BYTES / (1024 * 1024 * 1024),
                    OPTIONAL_HEAVY_MEMORY_OVERRIDE_ENV,
                )
            } else {
                "lane not armed for this instance".to_string()
            }),
        );
    }

    // MARGIN-ROW BUDGET RESERVE (#twinwall, opt-in NY_MARGIN_ROW_BAB=1): the
    // internal tier consumes ~95% of the scored budget, which would leave the
    // post-verifier margin-row lane nothing on timeout rows. When the lane is
    // ARMED and this instance IS the twin-wall family (cheap structural
    // check), hold back `NY_MARGIN_ROW_RESERVE_SECS` (default 45) from the
    // internal verifier. Verdict risk is confined to the opt-in config: an
    // instance the internal verifier could only decide in the reserved tail
    // loses that chance — the tier sweep measures exactly this trade.
    // The reserve above is a FIXED number of seconds, so its share of the
    // budget grows as the budget shrinks (measured: 47% of the internal tier
    // at a scored 100s, 24% at 200s — see `capped_reserve_secs`). The dark
    // ceiling makes it proportional instead — `margin_row.reserve_max_frac` in
    // the category preset, or `NY_MARGIN_ROW_RESERVE_MAX_FRAC` overriding it.
    // Absent from both ⇒ byte-identical to the shipped policy.
    // One decision only: `margin_row_reserve_decision` runs a structural probe
    // that parses the ONNX, so it must not be called twice per instance.
    let margin_row_reserve_actionable = margin_row_reserve_is_actionable(
        proof_tail_reserved,
        margin_row_memory_allowed,
        deferred_outer_pgd_priority,
    );
    let margin_row_internal_before_secs = ny_timeout;
    let uncapped = if !margin_row_reserve_actionable {
        super::margin_row_bab::MarginRowReserveDecision {
            configured_secs: 0,
            reserve_secs: 0,
            route: super::margin_row_bab::MarginRowReserveRoute::NotApplicable,
        }
    } else {
        super::margin_row_bab::margin_row_reserve_decision_with_policy(
            onnx,
            vnnlib,
            ny_timeout,
            margin_row_schedule_policy,
        )
    };
    let uncapped_reserve_secs = uncapped.reserve_secs;
    let reserve =
        uncapped.capped_to_internal_budget_with_policy(ny_timeout, margin_row_schedule_policy);
    if reserve.reserve_secs != uncapped_reserve_secs {
        eprintln!(
            "margin-row reserve ceiling: {}s -> {}s (frac={} of the {ny_timeout}s internal \
             budget; frozen_frac_bits={})",
            uncapped_reserve_secs,
            reserve.reserve_secs,
            margin_row_schedule_policy
                .configured_reserve_max_frac()
                .map_or_else(|| "none".to_string(), |f| f.to_string()),
            optional_f64_bits_token(margin_row_schedule_policy.configured_reserve_max_frac_bits),
        );
    }
    #[cfg(feature = "mip")]
    let verification_resources = match preset_snapshot.as_ref() {
        Some(BetaCrownPresetSnapshot::Loaded(config))
            if config.bab.single_hidden_hull == Some(ny_propagate::SingleHiddenHullMode::Root) =>
        {
            use super::beta_crown::hull_publication::{
                CallerVerificationResources, InstanceVerificationResources,
            };
            let deadline = match (beta_phase_deadline, instance_deadline) {
                (Some(a), Some(b)) => Some(a.min(b)),
                (a, b) => a.or(b),
            };
            Some(match InstanceVerificationResources::start(deadline) {
                Ok(owner) => CallerVerificationResources::Ready(owner),
                Err(reason) => CallerVerificationResources::Refused(reason.to_string()),
            })
        }
        _ => None,
    };
    let certified_root_cut_enabled = frozen_levers
        .get(&ny_levers::decls::certified_root_cut::ROOT_CERTIFIED_CUT)
        .as_bool();
    let certified_root_cut_owner = ny_propagate::beta_crown::certified_root_cut::QueryOwner::new(
        beta_solver_authority_deadline(beta_phase_deadline, solver_phase_deadline),
        certified_root_cut_enabled,
    );
    let mut instance_overrides = BetaCrownInstanceOverrides {
        certified_root_cut_enabled: Some(certified_root_cut_enabled),
        certified_root_cut_owner,
        input_head_continuation: input_head_continuation.clone(),
        #[cfg(feature = "mip")]
        verification_resources,
        frozen_levers: Some(std::sync::Arc::clone(&frozen_levers)),
        pgd_exact_vjp: Some(exact_vjp_policy),
        kfsb_cert_reuse_armed: Some(kfsb_cert_reuse_armed),
        chunk_wave_parallel_enabled: Some(chunk_wave_parallel_enabled),
        root_sparse_interm_crown: reserve.enables_scored_sparse_crown(),
        authoritative_deadline: beta_solver_authority_deadline(
            beta_phase_deadline,
            solver_phase_deadline,
        ),
        outer_deferred_internal_deadline: None,
        post_bab_wrapper_attack_enabled: Some(deferred_pgd_consumer_available),
        preset_snapshot,
        // #attack-concurrent: the concurrent margin-row worker owns the
        // concurrency whenever it exists (CR-X); read only by an armed race.
        attack_concurrent_wrapper: Some(
            crate::commands::beta_crown::attack_concurrent::ConcurrentAttackWrapperFacts {
                margin_row_lane_live: concurrent_lane.is_some(),
            },
        ),
    };
    if instance_overrides.root_sparse_interm_crown {
        eprintln!(
            "scored sparse root CROWN: armed by sealed adaptive-release route \
             (exact open-row policy; NY_ROOT_SPARSE_INTERM_CROWN=0 kills)"
        );
    }
    let ny_timeout = if reserve.reserve_secs > 0 {
        let kept = ny_timeout.saturating_sub(reserve.reserve_secs).max(10);
        crate::flight::note(
            "margin_row_reserve",
            crate::flight::FlightStatus::Ran,
            Some(format!(
                "reserved {}s (route={:?}, internal verifier keeps {kept}s)",
                reserve.reserve_secs, reserve.route
            )),
        );
        eprintln!(
            "margin-row BaB armed: reserving {}s of the internal budget \
             (internal verifier gets {kept}s, route={:?})",
            reserve.reserve_secs, reserve.route,
        );
        kept
    } else {
        crate::flight::note(
            "margin_row_reserve",
            crate::flight::FlightStatus::Skipped,
            Some(format!("no reserve held back (route={:?})", reserve.route)),
        );
        if matches!(
            reserve.route,
            super::margin_row_bab::MarginRowReserveRoute::AdaptiveReleasedAlphaBetaTier
        ) {
            eprintln!(
                "margin-row adaptive reserve: released {}s back to the internal verifier \
                 (internal verifier gets {ny_timeout}s, route={:?})",
                reserve.configured_secs, reserve.route,
            );
        }
        ny_timeout
    };
    crate::flight::note(
        MARGIN_ROW_SCHEDULE_EXECUTION_METHOD,
        crate::flight::FlightStatus::Ran,
        Some(render_margin_row_schedule_execution(
            margin_row_schedule_policy,
            global_rayon_outcome,
            margin_row_schedule_outer_route,
            concurrent_route,
            concurrent_resources,
            margin_row_internal_before_secs,
            uncapped,
            reserve,
            ny_timeout,
        )),
    );
    // The worker may publish an early certified UNSAT only after the complete
    // allocator context above is in the flight recorder. A proof that finished
    // even earlier still travels through the ordinary join channel.
    if let Some(lane) = &concurrent_lane {
        lane.mark_allocation_receipt_recorded();
    }

    // POST-BaB ATTACK BUDGET RESERVE (#postbab-reserve, opt-in
    // NY_POSTBAB_RESERVE_SECS=<secs>): the internal tier consumes ~95% of the
    // scored budget, so on categories where BaB is measured worthless past its
    // first seconds (acasxu prop_2: the preset's 2026-03-11 targeted 116s rerun
    // on all 42 prop_2 timeouts verified NOTHING extra) the post-BaB DLR-APGD
    // lane only ever starts when the internal verifier happens to return early
    // — a stochastic, host-speed-dependent event. Holding back a fixed reserve
    // makes the lane's budget deterministic. Opt-in and attack-side only: sat
    // still requires the unchanged trusted-ORT gate, and the only risk is the
    // measured-away chance that the internal verifier could have decided the
    // instance in the reserved tail.
    let verifier_before_postbab_reserve_secs = ny_timeout;
    let requested_postbab_reserve_secs = if postbab_reserve_is_actionable(
        deferred_pgd_consumer_available,
        margin_row_memory_allowed,
    ) {
        postbab_reserve_policy.configured_secs
    } else {
        0
    };
    let (ny_timeout, held_postbab_reserve_secs) = postbab_reserve_window(
        verifier_before_postbab_reserve_secs,
        requested_postbab_reserve_secs,
    );
    if held_postbab_reserve_secs > 0 {
        eprintln!(
            "post-BaB attack reserve armed: requested {requested_postbab_reserve_secs}s, \
             holding {held_postbab_reserve_secs}s of the internal budget \
             (internal verifier gets {ny_timeout}s)"
        );
    }
    let postbab_reserve_allocation = PostBabReserveExecution::from_decision(
        postbab_reserve_policy.configured_secs,
        verifier_before_postbab_reserve_secs,
        ny_timeout,
    );
    // #router-r3 CR-ATK: hold a DEFERRED upfront slice out of the verifier as
    // the late sat reserve, through the same never-extending window rule as
    // the configured reserve above. The verifier started that much earlier,
    // so it keeps today's window; the post-verifier attack (seeded by the
    // tree) spends the reserve. Zero — every row without a defer — is the
    // identity, so this changes nothing on any other run.
    let deferred_reserve_secs = crate::router::ostop::deferred_reserve_secs(
        deferred_pgd_consumer_available && concurrent_lane.is_none() && !proof_tail_reserved,
    );
    let (ny_timeout, held_deferred_secs) =
        postbab_reserve_window(ny_timeout, deferred_reserve_secs);
    if deferred_reserve_secs > 0 {
        crate::router::ostop::note_defer_held(
            deferred_reserve_secs,
            held_deferred_secs,
            ny_timeout,
        );
    }
    let held_postbab_reserve_secs = held_postbab_reserve_secs.saturating_add(held_deferred_secs);
    instance_overrides.outer_deferred_internal_deadline = frozen_outer_deferred_internal_deadline(
        solver_phase_deadline,
        timeout_before_fixed_reserves_secs,
        ny_timeout,
        effective_deferred_pgd_fraction,
        deferred_outer_pgd_priority,
    );
    if deferred_outer_pgd_priority
        && instance_overrides
            .outer_deferred_internal_deadline
            .is_none()
    {
        eprintln!(
            "Deferred outer PGD: no representable frozen internal deadline; verifier admission will fail closed"
        );
    }

    // #postbab-seed: clear the internal best-margin tracker so anything read
    // after the run belongs to THIS instance.
    reset_best_margin_candidate();
    // #bab-frontier: same reset contract for the BaB-frontier export channel
    // (docs/BAB_FRONTIER_SEEDING_DESIGN.md). Gate off => nothing is ever
    // recorded and the take below returns empty.
    reset_bab_frontier_export();
    // #smart-turn-qdq: clear the dark-lane latch so a report-only downgrade
    // below belongs to THIS instance.
    crate::commands::beta_crown::qdq_probe::reset_qdq_relaxation_engaged();
    // #graph-bab-cover-ledger: arm the process capture so every cover a
    // ledgered graph driver proves during THIS run is kept for publication.
    ny_propagate::certify::reset_graph_cover_capture();
    // B2.2: arm the lane proof capture — ONLY when the Proof profile switched
    // hint capture on (under Competition this arms nothing and no lane builds
    // a tape).
    ny_propagate::certify::reset_lane_proof_capture();
    begin_capture();
    let beta_started = std::time::Instant::now();
    if let Some(lane) = &concurrent_lane {
        lane.mark_verifier_started();
    }
    // #router-r2 CR-T: the internal verifier is the terminal. It claims its
    // cell with the timeout its own rule derived and keeps it UNCHANGED (the
    // terminal takes the remainder, never shortened); the claim records
    // whether every hand-on credit landed inside its window.
    let ny_timeout = crate::router::acting::claim_terminal(ny_timeout);
    let outcome = invoke_beta_crown(
        onnx,
        vnnlib,
        preset,
        ny_timeout,
        deferred_pgd_consumer_available,
        instance_overrides,
    );
    if let Some(lane) = &concurrent_lane {
        lane.mark_verifier_finished();
    }
    let beta_elapsed = beta_started.elapsed();
    let captured = take_captured_verification();
    let terminal_ingress = take_captured_terminal_ingress();
    let captured_deadline_plan = take_captured_deadline_plan();
    end_capture();
    // B2.2: keep the lanes' proof tapes for the Proof bundle (a no-op unless
    // one is wired); streamed by `after_publication_receipt`.
    super::proof_bundle::stash_lane_proofs(ny_propagate::certify::take_lane_proof_capture());
    let graph_cover_capture = ny_propagate::certify::take_graph_cover_capture();

    // #phase-ledger (dark, `NY_PHASE_LEDGER=1`): the internal verifier's own
    // verdict JSON plus the wall it actually consumed against the wall it was
    // granted. Without this the default log shows a silent gap between "verifier
    // started" and "post-BaB attack handed N s", so an instance that ends at 12 s
    // of a 600 s budget is indistinguishable from one whose proof lane was cut by
    // a deadline — the two call for opposite fixes. Diagnostic only: it reads
    // state the run already computed and changes no verdict, bound or schedule.
    if std::env::var("NY_PHASE_LEDGER").ok().as_deref() == Some("1") {
        eprintln!(
            "[phase-ledger] internal verifier returned after {:.2}s of a {}s internal grant \
             (outcome={}), leftover={:.2}s",
            beta_elapsed.as_secs_f64(),
            ny_timeout,
            if outcome.is_ok() { "ok" } else { "err" },
            instance_deadline
                .map(|d| d
                    .saturating_duration_since(std::time::Instant::now())
                    .as_secs_f64())
                .unwrap_or(f64::NAN),
        );
        eprintln!(
            "[phase-ledger] verifier JSON: {}",
            captured
                .as_ref()
                .map(|value| value.json())
                .unwrap_or("<none>")
        );
    }
    // The hull payload is a paid typed publication, with its own observations.
    // Do not allocate the legacy JSON parser's workspace for this new route.
    let legacy_json = captured
        .as_ref()
        .filter(|value| !value.has_hull())
        .map(|value| value.json());
    note_root_joint_interm_alpha_execution(legacy_json);
    note_mo_kfsb_execution(legacy_json);
    note_mo_alpha_step_execution(legacy_json);
    // The closest-to-violation points the internal graph-PGD search found, even
    // when they never crossed the internal violation threshold (the resister
    // class: the search burns its tier without emitting a witness while
    // stalling ULPs below the threshold). Up to two seeds — plain-lane and
    // #exploit-recycle-lane lineages park in different jam points and the
    // ULP-jitter is position-sensitive. Attack-only guidance for the post-BaB
    // lane below.
    let best_margin_candidates = take_best_margin_candidates();
    // #bab-frontier: the engine's surviving UNVERIFIED subboxes at exhaustion
    // (timeout/domain-limit/mem-cap) — exactly where a counterexample must
    // live if one exists. Attack-only guidance for the post-BaB lane below;
    // empty unless NY_POSTBAB_BAB_SEEDS is exact mode 1 or 2.
    let bab_frontier_seeds = take_bab_frontier_seeds();

    let captured_verifier_elapsed = captured
        .as_ref()
        .and_then(|value| value.hull_elapsed())
        .or_else(|| legacy_json.and_then(parse_competition_elapsed));
    // The separate original-hull publisher retains its own replay authority;
    // it never consumes the input-head Source partition. Only ordinary JSON
    // can match the bridge's opaque whole-root MIP publication receipt.
    let original_hull_capture = captured.as_ref().is_some_and(|value| value.has_hull());
    let original_mip_capture = input_head_continuation
        .as_ref()
        .and(legacy_json)
        .map(str::to_owned);
    let translated = match (outcome, captured) {
        // The verifier produced a JSON verdict — translate it. This is the normal path
        // for verified/violated/timeout/unknown.
        (_, Some(captured)) => translate_captured_verification(captured, || {
            crate::commands::graph_cover_publish::graph_instance_unsat(vnnlib, &graph_cover_capture)
        }),
        // No JSON verdict but the call returned Ok (verified IBP fast-path writes JSON,
        // so this is unusual): stay sound.
        (Ok(()), None) => VnncompResult::Unknown,
        // The primary CLI dispatch translates a verifier deadline into a
        // BetaCrownResult::Timeout and emits JSON. Keep this final typed
        // fallback at the capture boundary as well: a deadline from any
        // later/pre-dispatch seam must not become `unknown`.
        (Err(err), None)
            if error_chain_has_expired_typed_deadline(
                &err,
                match (beta_phase_deadline, instance_deadline) {
                    (Some(beta), Some(instance)) => Some(beta.min(instance)),
                    (Some(beta), None) => Some(beta),
                    (None, instance) => instance,
                },
            ) =>
        {
            eprintln!("Verification deadline exceeded before JSON publication: {err}");
            VnncompResult::Timeout
        }
        // The call errored before producing any verdict (e.g. propagation error during
        // the initial bound pass). The run did not crash; emit the sound `unknown`.
        (Err(err), None) => {
            // #nn4sys-corrupt-dual lesson: a model that fails to LOAD is a file
            // problem, not a verification result — a corrupt mscn_2048d_dual.onnx
            // spent a year of sweeps indistinguishable from a hard instance
            // (0-4s "unknown" on 140-800s budgets, 22 GT-solid rows invisible).
            // The verdict stays the sound competition `unknown`, but the marker
            // below is LOUD and greppable so no sweep harness can miss it again.
            let msg = err.to_string();
            if msg.contains("Model loading failed") {
                eprintln!(
                    "NY-HARNESS: MODEL-LOAD-FAILURE — the `unknown` below is a BROKEN \
                     MODEL FILE, not a verification result: {msg}"
                );
            } else {
                eprintln!("Verification produced no verdict (sound unknown): {err}");
            }
            // #nonlinear-vnnlib: the affine parser refuses non-linear arithmetic
            // outright, which makes every instance of a non-linear category an
            // instant `unknown` (adaptive_cruise_control_non_linear_2026: 50/50 at
            // 0.1s each — a guaranteed zero on a whole benchmark). Fall back to
            // the complete non-linear lane: first search for an exact,
            // independently backed-up counterexample; if none is found, try to
            // refute every input subbox with sound output bounds plus outward
            // interval evaluation of the ORIGINAL, UNRELAXED formula. Any
            // unsupported or unresolved operation remains `unknown`.
            if affine_parser_refused_for_representability(&msg)
                && nonlinear_fallback_may_precede_outer_pgd(deferred_outer_pgd_priority)
            {
                // SAT first: a counterexample is far cheaper than a proof and
                // settles the violated instances immediately. The value falls
                // through to the trusted-oracle gate below like any other `sat`
                // — it is NOT returned early, so the ORT re-confirmation still
                // runs.
                if let Some(witness) =
                    try_nonlinear_sat(onnx, vnnlib, ny_timeout / 4, post_beta_deadline)
                {
                    eprintln!(
                        "#nonlinear-vnnlib: EXACT counterexample found for a spec the affine \
                         parser refuses; the full unrelaxed formula holds at this point"
                    );
                    VnncompResult::Sat {
                        witness: Some(witness),
                    }
                } else {
                    // #acc-strict-intervals: the receipt is emitted whatever
                    // the unsat half returns (including every early refusal),
                    // so an armed null is distinguishable from "never engaged".
                    let mut case_split = NonlinearCaseSplitStats::new(nonlinear_case_split);
                    let refuted = nonlinear_float32::try_source_first(
                        onnx,
                        vnnlib,
                        ny_timeout,
                        post_beta_deadline,
                        &mut case_split,
                    ) == Some(true);
                    case_split.emit();
                    if refuted {
                        // No counterexample found, and the whole region is
                        // refuted by sound interval branch-and-bound.
                        eprintln!(
                            "#nonlinear-vnnlib: region exhaustively refuted by sound interval \
                             branch-and-bound over the declared box — no counterexample exists"
                        );
                        VnncompResult::Unsat(UnsatReceipt::legacy_uncovered(
                            LegacyUnsatAuthority::NonlinearIntervalBab,
                        ))
                    } else {
                        VnncompResult::Unknown
                    }
                }
            } else if crate::commands::cctsdb_subbox::cctsdb_subbox_refutes(
                onnx,
                vnnlib,
                cctsdb_subbox_deadline(post_beta_deadline),
            ) {
                // #cctsdb-subbox: ny has NO graph for this model as one unit,
                // but the declared box splits into two sub-boxes that each DO
                // build after an authenticated proto rewrite. `true` here means
                // BOTH were refuted by cell enumeration — never partial
                // coverage — after an exhaustive per-cell ONNX-Runtime
                // equivalence check against the ORIGINAL model. Any other
                // outcome returned `false` and fell through to the unchanged
                // `#graph-free-sat` behaviour below.
                VnncompResult::Unsat(UnsatReceipt::legacy_uncovered(
                    LegacyUnsatAuthority::CctsdbSubbox,
                ))
            } else if graph_free_falsification_applies(onnx) {
                // #graph-free-sat: ny has NO graph for this model, so it has no
                // bound and cannot prove anything — but the budget is still
                // whole. Spend it on the loader-independent ORT falsifier; a
                // candidate leaves here as an ordinary `Sat` and still faces the
                // unchanged trusted-oracle gate below.
                match try_graph_free_ort_falsify(onnx, vnnlib, post_beta_deadline) {
                    Some(witness) => VnncompResult::Sat {
                        witness: Some(witness),
                    },
                    None => VnncompResult::Unknown,
                }
            } else {
                VnncompResult::Unknown
            }
        }
    };
    // Source-dependent generic closure has no legacy publication authority.
    // A complete private original-input partition must produce its own
    // Instance token, actual G2 and original singleton G3 after fresh file,
    // consuming-thread FP and original-deadline checks. Independent SAT stays
    // on the ordinary trusted-oracle path below.
    let translated = match input_head_continuation
        .as_ref()
        .filter(|_| !original_hull_capture)
    {
        Some(source) => source.settle_result(translated, original_mip_capture.as_deref()),
        None => translated,
    };
    // #smart-turn-qdq REPORT-ONLY latch: a verdict computed through the dark
    // QDQ activation-relaxation lane is a FINDING this round, not a result.
    // The bound was printed by the probe; the verdict is withheld until the
    // mechanism survives review and the family adjudication policy is settled.
    let translated = if crate::commands::beta_crown::qdq_probe::qdq_relaxation_engaged()
        && matches!(
            translated,
            VnncompResult::Unsat(_) | VnncompResult::Sat { .. }
        ) {
        eprintln!(
            "[qdq_relax] report-only: withholding the internal verifier's {} verdict — the \
             dark QDQ relaxation lane may not publish verdicts this round",
            match &translated {
                VnncompResult::Unsat(_) => "unsat",
                _ => "sat",
            }
        );
        VnncompResult::Unknown
    } else {
        translated
    };
    // #router-r2 CR-H/CR-T: the terminal returned; record what it left. Its
    // unspent time is returned to the pool that every post-verifier lane
    // already reads from the live clock (a no-op when it was not governed).
    crate::router::acting::release_lane(
        ny_core::deadline_authority::LaneSlot::Verifier,
        matches!(
            translated,
            VnncompResult::Unsat(_) | VnncompResult::Sat { .. }
        ),
    );
    // #router-r4 CR-L: the verifier's working set is gone; its base lease
    // returns to the envelope the post-verifier lanes lease from.
    crate::router::lease::release(ny_core::router::lease::LeaseHolder::Terminal);
    let mut postbab_reserve_execution = postbab_reserve_allocation.and_then(|allocation| {
        allocation.observe_verifier_deadline(
            captured_deadline_plan,
            captured_verifier_elapsed,
            &translated,
        )
    });

    // TRUSTED-ORACLE COUNTEREXAMPLE GATE (soundness-critical).
    //
    // Every internal `sat` is re-confirmed by a REAL ONNX-Runtime forward on the
    // candidate input before we emit it. ny's internal forward (PGD evaluator and
    // its CPU-only re-validation) can agree on a WRONG output if the graph is loaded
    // or an op is implemented incorrectly — both share the same graph (confirmed on
    // cgan_2023: ny computed Y_0=0.4286645 crossing the unsafe threshold while real
    // ORT gives Y_0=0.4342193, which is SAFE). Scoring a false `sat` is -150 vs +10
    // for a correct one, so an UNCONFIRMED `sat` is never worth the risk: if ORT does
    // not confirm the violation — or cannot be consulted at all — we downgrade to the
    // sound `unknown`.
    // #graph-free-candidates: whether a `sat` reaches the gate below at all
    // (read before `translated` moves), for the side file's trusted-oracle
    // record. Pure observation.
    let translated_is_sat = matches!(translated, VnncompResult::Sat { .. });
    let (gated, internal_witness) = match translated {
        VnncompResult::Sat { witness } => {
            let internal_witness = witness.clone();
            let gated =
                gate_sat_with_trusted_oracle(onnx, vnnlib, witness.as_deref(), instance_deadline);
            // Keep the internal witness even when the gate DOWNGRADES: on the
            // ORT-divergence class (soundnessbench model_5: ny's internal forward
            // says violated, real ORT says SAFE) it is a near-miss and the best
            // available seed for the post-BaB attack below.
            (gated, internal_witness)
        }
        other => (other, None),
    };
    // #graph-free-candidates: append the gate's ruling on the graph-free lane's
    // accepted candidate to the ARMED side file. A no-op on every dark run (no
    // candidate is ever parked) and it cannot change `gated`.
    graph_free_sidefile::record_trusted_oracle_outcome(
        translated_is_sat,
        matches!(gated, VnncompResult::Sat { .. }),
    );
    if let VnncompResult::Sat { .. } = &gated {
        return gated;
    }

    // POST-BaB LEFTOVER-BUDGET FALSIFICATION (#postbab-apgd, strictly additive).
    // The internal search often EXHAUSTS (all restarts done) or emits an
    // ORT-rejected false witness well before the scored deadline (soundnessbench:
    // non-sat at ~50-125s of a 150s budget), so the remaining wall-clock is
    // otherwise WASTED. Spend it on the exact-gradient DLR-APGD attack — a
    // qualitatively different search from the internal one — and return `sat`
    // ONLY through the identical trusted-ORT gate. The verdict at this point is
    // already non-sat, so this pass can only ADD sats; it can never cost a
    // verdict (it runs strictly after the outcome is decided) nor introduce a
    // false one (the acceptance gate is unchanged). Kill switches: exact
    // NY_POSTBAB_ATTACK=0, or typed vnncomp_post_bab_attack=false.
    if deferred_pgd_consumer_available && postbab_escalation_allowed(&gated, terminal_ingress) {
        // MARGIN-ROW TWIN-WALL BaB (#twinwall, strictly additive): after the
        // generic verifier failed to decide and the attack found no CE, spend
        // the remaining budget on the certified margin-row lane. It can only
        // turn unknown/timeout into a certified-outward `unsat` (never `sat`,
        // fail-closed on any structural mismatch). Opt-in: NY_MARGIN_ROW_BAB=1.
        // Prefer the CONCURRENT lane's verdict: it has been running for the
        // whole instance, so it is strictly better-informed than a fresh
        // inline attempt on the leftover seconds. Give it a short grace to
        // land, then fall back to the inline attempt (which is what runs when
        // no concurrent lane was started).
        let mut margin_worker_still_running = false;
        // BORROW, do not move: the FINAL CONCURRENT-LANE JOIN below consults the
        // same handle after the attack lane has had its slice. Moving it here
        // is what silently discarded a certified proof on cifar100_2024.
        if !deferred_outer_pgd_priority {
            if let Some(lane) = &concurrent_lane {
                let grace =
                    concurrent_margin_row_grace(post_beta_deadline, std::time::Instant::now());
                match lane.peek(grace) {
                    super::margin_row_bab::ConcurrentLaneTake::Verdict(res) => return res,
                    super::margin_row_bab::ConcurrentLaneTake::FinishedWithoutVerdict => {
                        // #router-r4 CR-L: the worker ended; its lease returns.
                        crate::router::lease::release(
                            ny_core::router::lease::LeaseHolder::MarginRowConcurrent,
                        );
                    }
                    super::margin_row_bab::ConcurrentLaneTake::StillRunning => {
                        margin_worker_still_running = true;
                        eprintln!(
                            "Post-BaB attack: declined because the detached concurrent margin-row \
                         worker is still running; graph-heavy optional tails may not overlap"
                        );
                    }
                }
            } else if !proof_tail_reserved
                && crate::router::lease::admit(
                    ny_core::router::lease::LeaseHolder::MarginRowInline,
                    optional_heavy_memory_allowed_now,
                )
            {
                match super::margin_row_bab::try_margin_row_unsat(
                    onnx,
                    vnnlib,
                    // #twinwall-reserve-respect (banked 99ed4d42): when the post-BaB
                    // attack reserve is armed, the inline margin-row lane must not be
                    // handed the FULL instance deadline — measured, it consumed the
                    // whole tail (113.1s against a 45s margin-row slice on metaroom),
                    // starving the seeded post-BaB lane and once overrunning to the
                    // watchdog kill. Cap its deadline so the attack keeps its slice.
                    margin_row_lane_deadline(post_beta_deadline, held_postbab_reserve_secs),
                    margin_row_runtime_policy,
                ) {
                    super::margin_row_bab::MarginRowTry::Verdict(res) => return res,
                    super::margin_row_bab::MarginRowTry::FinishedWithoutVerdict => {
                        // #router-r4 CR-L: the inline worker ended; its lease
                        // returns.
                        crate::router::lease::release(
                            ny_core::router::lease::LeaseHolder::MarginRowInline,
                        );
                    }
                    super::margin_row_bab::MarginRowTry::StillRunning => {
                        margin_worker_still_running = true;
                        eprintln!(
                            "Post-BaB attack: declined because the detached inline margin-row \
                         worker is still running; graph-heavy optional tails may not overlap"
                        );
                    }
                }
            }
        }
        if deferred_pgd_consumer_available
            && postbab_after_margin_allowed(margin_worker_still_running)
        {
            if held_postbab_reserve_secs > 0
                && !crate::router::lease::peek(
                    ny_core::router::lease::LeaseHolder::PostVerifierTail,
                    optional_heavy_memory_allowed_now,
                )
            {
                eprintln!(
                    "post-BaB attack reserve: {}s was held at instance start but live \
                     cgroup/RLIMIT state became unavailable or fell below the graph-tail \
                     boundary before handoff; the lane will decline and preserve the existing verdict",
                    held_postbab_reserve_secs
                );
            }
            let postbab_witness = try_postbab_falsify(
                onnx,
                vnnlib,
                internal_witness.as_deref(),
                &best_margin_candidates,
                &bab_frontier_seeds,
                instance_deadline,
                postbab_reserve_execution.as_mut(),
                postbab_restart_policy,
                point_folded_twin_policy,
                postbab_active_set_policy,
            );
            // #router-r4 CR-L: the tail's graph loads are dropped; its lease
            // returns (a no-op when none was armed or granted).
            crate::router::lease::release(ny_core::router::lease::LeaseHolder::PostVerifierTail);
            if let Some(execution) = postbab_reserve_execution.take() {
                execution.note_terminal();
            }
            if let Some(witness) = postbab_witness {
                let regated =
                    gate_sat_with_trusted_oracle(onnx, vnnlib, Some(&witness), instance_deadline);
                if matches!(regated, VnncompResult::Sat { .. }) {
                    return regated;
                }
                // Gate rejected the candidate: keep the original (sound) verdict.
            }
        }
        // FINAL CONCURRENT-LANE JOIN (#twinwall-join, measured 2026-08-03).
        //
        // THE DEFECT THIS FIXES. The join above waits at most 5 s, anchored to
        // the moment the internal verifier RETURNS — not to the instance
        // deadline. On cifar100_2024 the verifier gives its slice back early
        // (BaB hits its phase deadline, Graph-MIP declines on the nnz cap), so
        // that 5 s window opens around t=57 s of a 100 s budget while the lane
        // is still working. Measured on resnet_large prop_idx_4486 with the
        // twin-wall pair armed: the lane returned `UNSAT in 77.3s
        // (root_bound=-0.2051, expansions=72, maxDepth=13, ledger=Some(true))`
        // — 20 s INSIDE the budget — and the instance still wrote `timeout`,
        // because by then the only remaining consumer was the APGD attack and
        // the handle had already been polled and dropped. A certified proof
        // was computed, printed, and thrown away.
        //
        // THE FIX. Consult the SAME handle once more after the attack lane has
        // had its full slice. The message the 5 s poll missed is still queued
        // (a `recv_timeout` that times out consumes nothing), so this collects
        // it with no extra work.
        //
        // SOUND AND STRICTLY ADDITIVE. (a) It runs only inside the
        // already-guarded `postbab_escalation_allowed` block, i.e. the verdict
        // is Unknown/Timeout and nothing is being overwritten. (b) The lane is
        // fail-closed — `run_margin_row_lane` returns `Unsat` or `Unknown`,
        // never `Sat` — so this can only convert timeout into a certified
        // `unsat`. (c) It is placed AFTER `try_postbab_falsify`, so the attack
        // keeps its whole slice and no `sat` can be lost to it; the lane has
        // been running on its own thread throughout, so waiting here costs it
        // nothing either. (d) The wait stops short of the scored deadline, and
        // the lane's own deadline is already `instance_deadline - 3s`.
        if !deferred_outer_pgd_priority {
            if let Some(lane) = concurrent_lane {
                // #router-r2 CR-R: with a publish grace armed, the join waits
                // until the lane's own publish deadline (never less than
                // today, always leaving the write reserve); unarmed this is
                // exactly CONCURRENT_LANE_JOIN_MARGIN.
                let join_margin =
                    crate::router::acting::final_join_margin(CONCURRENT_LANE_JOIN_MARGIN);
                let grace = instance_deadline
                    .map(|d| {
                        d.saturating_duration_since(std::time::Instant::now())
                            .saturating_sub(join_margin)
                    })
                    .unwrap_or_default();
                if !grace.is_zero() {
                    // #twinwall-join-visibility (g2_moat forensics, 2026-08-20):
                    // this wait is real but was SILENT. The lane's [trace] clock
                    // is lane-relative (starts at tree_loop entry, ~30s into the
                    // run when backward-interm is armed) and its cadence is
                    // geometric (exp 0,1,3,7,11,17,24,34,48,...), so 10.6s of
                    // blocking here showed NOTHING between the last trace line
                    // and `Result:` — which read as a publish-without-drain at
                    // "55s" when the write actually landed at ~98s. Log the wait
                    // and its outcome so the join can never masquerade as an
                    // early publish again. Telemetry only; verdict handling is
                    // unchanged.
                    eprintln!(
                        "margin-row BaB: final concurrent-lane join — waiting up to {:.1}s \
                         for the detached worker (scored deadline - {}s)",
                        grace.as_secs_f64(),
                        join_margin.as_secs()
                    );
                    let join_started = std::time::Instant::now();
                    match lane.take(grace) {
                        super::margin_row_bab::ConcurrentLaneTake::Verdict(res) => {
                            eprintln!(
                                "margin-row BaB: collected the CONCURRENT lane verdict at the \
                             post-BaB join (waited up to {:.1}s)",
                                grace.as_secs_f64()
                            );
                            return res;
                        }
                        super::margin_row_bab::ConcurrentLaneTake::FinishedWithoutVerdict => {
                            eprintln!(
                                "margin-row BaB: concurrent lane finished WITHOUT a verdict \
                                 {:.1}s into the final join wait (its own deadline is the \
                                 scored deadline - 3s); publishing the sound verdict",
                                join_started.elapsed().as_secs_f64()
                            );
                        }
                        super::margin_row_bab::ConcurrentLaneTake::StillRunning => {
                            eprintln!(
                                "margin-row BaB: final join grace ({:.1}s) exhausted with the \
                                 detached worker still running; publishing the sound verdict",
                                join_started.elapsed().as_secs_f64()
                            );
                        }
                    }
                }
            }
        }
    }
    gated
}

/// Headroom kept below the scored deadline when joining the concurrent
/// margin-row lane at the end of the post-BaB tail: enough for the results
/// write, and short enough that the wait cannot itself cause an overrun.
pub(crate) const CONCURRENT_LANE_JOIN_MARGIN: std::time::Duration =
    std::time::Duration::from_secs(2);

/// Detect an expired verifier deadline authority through arbitrary `anyhow`
/// context without relying on rendered error text.
///
/// `NyError::DeadlineExceeded` may also represent a recoverable node-local cap.
/// A live or absent outer authority therefore keeps the ordinary sound-unknown
/// translation rather than claiming whole-attempt exhaustion.
fn error_chain_has_expired_typed_deadline(
    error: &anyhow::Error,
    authority_deadline: Option<std::time::Instant>,
) -> bool {
    authority_deadline.is_some_and(|deadline| std::time::Instant::now() >= deadline)
        && error.chain().any(|cause| {
            cause
                .downcast_ref::<ny_core::NyError>()
                .is_some_and(ny_core::NyError::is_deadline_exceeded)
        })
}

/// Decide whether an inconclusive verifier result may enter any post-BaB lane.
///
/// The historical/default and required-plain-prefix policies are unchanged:
/// timeout/unknown may still spend leftover budget on the existing margin-row
/// and APGD lanes.  The typed marked-margin SafeNLP ingress is different: once
/// admitted it owns the terminal result, so timeout/unknown must return
/// directly without a fallback, retry, APGD pass, or second solve.
fn postbab_escalation_allowed(
    result: &VnncompResult,
    terminal_ingress: CapturedTerminalIngress,
) -> bool {
    matches!(result, VnncompResult::Unknown | VnncompResult::Timeout)
        && terminal_ingress == CapturedTerminalIngress::None
}

/// Time reserved below the scored deadline for the confirming ORT gate + true-f64
/// re-check + results write after the post-BaB attack returns a candidate.
const POSTBAB_ATTACK_SAFETY_MARGIN: std::time::Duration = std::time::Duration::from_secs(5);

/// Below this leftover budget the post-BaB attack is not worth starting.
const POSTBAB_ATTACK_MIN_BUDGET: std::time::Duration = std::time::Duration::from_secs(5);

const POSTBAB_RESERVE_EXECUTION_SCHEMA: &str = "ny-cli/postbab-reserve-execution/v2";
const POSTBAB_RESERVE_T1_MIN_WORK_BUDGET: std::time::Duration = std::time::Duration::from_secs(2);

/// Exact reserve decision carried to the first point where executable outer
/// falsification work has been admitted. Keeping all fields in one value makes
/// the engagement receipt invocation-local: search must never combine a budget
/// reduction from one row with attack work from another.
#[derive(Debug, Clone, PartialEq, Eq)]
struct PostBabReserveExecution {
    configured_secs: u64,
    held_secs: u64,
    verifier_before_secs: u64,
    verifier_after_secs: u64,
    verifier_elapsed_ms: Option<u64>,
    first_work_budget_ms: Option<u64>,
    work_units: u64,
}

impl PostBabReserveExecution {
    fn from_decision(configured_secs: u64, before_secs: u64, after_secs: u64) -> Option<Self> {
        let held_secs = before_secs.checked_sub(after_secs)?;
        (configured_secs > 0
            && held_secs > 0
            && configured_secs >= held_secs
            && (configured_secs == held_secs || after_secs == 10)
            && after_secs >= 10)
            .then_some(Self {
                configured_secs,
                held_secs,
                verifier_before_secs: before_secs,
                verifier_after_secs: after_secs,
                verifier_elapsed_ms: None,
                first_work_budget_ms: None,
                work_units: 0,
            })
    }

    /// Convert nominal allocation into execution evidence only when the
    /// shortened verifier wall actually bound. A natural early return would
    /// leave the zero-reserve arm the same outer budget, so arithmetic alone
    /// is not a counterfactual effect and must never earn T1 credit.
    fn observe_verifier_deadline(
        mut self,
        plan: Option<CapturedDeadlinePlan>,
        elapsed: Option<std::time::Duration>,
        outcome: &VnncompResult,
    ) -> Option<Self> {
        let plan = plan?;
        let elapsed = elapsed?;
        if !matches!(outcome, VnncompResult::Timeout)
            || plan.configured_timeout != std::time::Duration::from_secs(self.verifier_after_secs)
            || !plan.configured_deadline_strictly_won
            || !plan.configured_deadline_caused_terminal_timeout
            || elapsed < plan.configured_timeout
        {
            return None;
        }
        self.verifier_elapsed_ms = Some(u64::try_from(elapsed.as_millis()).unwrap_or(u64::MAX));
        Some(self)
    }

    /// Record one completed trusted-forward falsification probe. The live
    /// budget captured immediately before that probe is the one sealed in the
    /// receipt; setup time and failed graph loads cannot manufacture engagement.
    fn note_work_unit(&mut self, live_budget: std::time::Duration) {
        self.first_work_budget_ms
            .get_or_insert_with(|| u64::try_from(live_budget.as_millis()).unwrap_or(u64::MAX));
        self.work_units = self.work_units.saturating_add(1);
    }

    fn receipt_details(&self) -> Option<String> {
        let verifier_elapsed_ms = self.verifier_elapsed_ms?;
        let attack_budget_ms = self.first_work_budget_ms?;
        if self.work_units != 1
            || attack_budget_ms
                < u64::try_from(POSTBAB_RESERVE_T1_MIN_WORK_BUDGET.as_millis()).unwrap_or(u64::MAX)
        {
            return None;
        }
        Some(format!(
            "schema={POSTBAB_RESERVE_EXECUTION_SCHEMA} phase=terminal \
             configured_secs={} held_secs={} verifier_before_secs={} \
             verifier_after_secs={} verifier_elapsed_ms={verifier_elapsed_ms} \
             verifier_outcome=timeout deadline_bound=true \
             attack_budget_ms={attack_budget_ms} work_units={} work_started=true",
            self.configured_secs,
            self.held_secs,
            self.verifier_before_secs,
            self.verifier_after_secs,
            self.work_units,
        ))
    }

    fn note_terminal(self) {
        if let Some(details) = self.receipt_details() {
            crate::flight::note(
                "postbab_reserve_execution",
                crate::flight::FlightStatus::Ran,
                Some(details),
            );
        }
    }
}

/// Adaptive post-BaB reserves (#postbab-small-budget): `(safety_margin,
/// min_budget)` for the given leftover.
///
/// On small leftovers — the safenlp-class 20s scored budgets where a
/// mip-featured internal verify consumes its whole slice — the fixed 5s safety
/// margin swallowed the entire ~5s leftover and the attack lane never STARTED,
/// losing razor-thin SAT rows the same binary wins whenever the lane runs
/// (measured 2026-07-20 on safenlp hyperrectangle_1997: plain build leftover
/// ~6s → sat in 8 gradient steps / 9 ORT evals; mip build leftover ~5.1s →
/// lane skipped → timeout). On the tiny models behind such budgets the
/// confirming ORT gate is millisecond-scale, so a 3s margin + 2s minimum
/// re-opens the window; leftovers above the small threshold keep the
/// historical 5s/5s pair byte-identically.
///
/// SOUND / attack-only: this lane runs only when the verdict is already
/// unknown, every candidate still passes the unchanged trusted-oracle gate
/// (`gate_sat_with_trusted_oracle`), and a too-small slice merely finds
/// nothing — the change can only ADD ORT-confirmed sats, never flip a sound
/// verdict (worst case: seconds spent in an otherwise-dead window).
fn postbab_attack_reserves(
    remaining: std::time::Duration,
) -> (std::time::Duration, std::time::Duration) {
    const SMALL_LEFTOVER: std::time::Duration = std::time::Duration::from_secs(12);
    if remaining <= SMALL_LEFTOVER {
        (
            std::time::Duration::from_secs(3),
            std::time::Duration::from_secs(2),
        )
    } else {
        (POSTBAB_ATTACK_SAFETY_MARGIN, POSTBAB_ATTACK_MIN_BUDGET)
    }
}

/// #deadlane — process-memoized answer to "can ANY exact-gradient attack step
/// run on this net?", keyed by model path.
///
/// [`GraphNetwork::supports_attack_point_gradient`] is a purely static scan of
/// node layer types, so the answer is fixed for the whole process. Without the
/// memo the SAME probe is repeated by every lane: measured on vit_2023
/// ibp_3_3_8_3005 the upfront lane learned "exact gradient unavailable" at
/// t≈0.06 s and the post-BaB lane re-derived the identical answer 87.7 s later,
/// each time after a full ONNX re-load.
///
/// FAIL-OPEN: a model that does not load returns `true`, so a load hiccup can
/// only preserve today's behavior (run the lane, discover the answer inside),
/// never silently disable an attack that would have worked.
fn net_supports_attack_gradients(onnx: &Path) -> bool {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};
    static CACHE: OnceLock<Mutex<HashMap<PathBuf, bool>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    // A poisoned mutex must not change the verdict path: fail open.
    let mut guard = match cache.lock() {
        Ok(g) => g,
        Err(_) => return true,
    };
    if let Some(&hit) = guard.get(onnx) {
        return hit;
    }
    // The first refused node is carried into the log line so a dead lane names
    // the op that killed it (#ml4acopf-vjp): without it the next person has to
    // re-derive the op census by hand before knowing what to admit.
    let (supported, first_refusal) = match load_graph_network(onnx) {
        Ok(graph) => (
            graph.supports_attack_point_gradient(),
            graph.first_attack_point_gradient_refusal(),
        ),
        Err(_) => (true, None),
    };
    if !supported {
        let refused = first_refusal.map_or_else(
            || "empty graph".to_string(),
            |(node, layer)| format!("node '{node}' ({layer})"),
        );
        eprintln!(
            "Attack lanes: {} is outside the exact-gradient fragment (first refused: {refused}); \
             gradient-driven falsification is STATICALLY unavailable on this net (probed once)",
            onnx.display()
        );
    }
    guard.insert(onnx.to_path_buf(), supported);
    supported
}

/// #deadlane — does the post-BaB falsification lane have ANY stage it can
/// actually execute?
///
/// Pure so the decision is testable without a model or a clock. Two independent
/// capabilities feed every stage of [`try_postbab_falsify`]:
///
/// * `has_seed` — an internal near-miss witness, an exported best-margin point,
///   or a BaB-frontier center. These drive the DERIVATIVE-FREE stages
///   (trusted-ORT active-set repair, exact-f64 polish, ULP jitter), which need no
///   network gradient at all.
/// * `grad_ok` — [`net_supports_attack_gradients`]. Required by the Newton
///   equality-seek rows and by the final DLR-APGD lane. Taken as a CLOSURE so a
///   seeded lane never pays for the probe's ONNX load.
///
/// With NEITHER, every stage is structurally dead: the seeded stages have
/// nothing to start from and the gradient stages cannot take a step. Handing
/// such a lane budget is pure waste — measured on vit_2023, 9,407.6 s across the
/// 200-row category (47.0 % of the whole category budget), on a benchmark whose
/// official results contain ZERO `sat` instances, so a falsifier could not have
/// earned a point with any of it.
///
/// Deliberately conservative: EITHER capability keeps the lane and its full
/// window, so a lane that can run is unaffected.
fn postbab_lane_has_executable_stage(has_seed: bool, grad_ok: impl FnOnce() -> bool) -> bool {
    has_seed || grad_ok()
}

/// Operator assertion that the optional graph-heavy proof/attack tails may run
/// inside a finite cgroup/RLIMIT envelope.  `1` opts in, `0` opts out even on an
/// unbounded host; every other value keeps the fail-closed automatic policy.
const OPTIONAL_HEAVY_MEMORY_OVERRIDE_ENV: &str = "NY_OPTIONAL_HEAVY_UNDER_MEMORY_LIMIT";

/// Minimum LIVE cgroup/RLIMIT headroom for graph-heavy optional tails.
///
/// The failed 12 GiB campaign entered post-BaB with about 9.6 GiB remaining
/// and consumed all of it.  Requiring 16 GiB of *remaining* headroom adds 6.4
/// GiB beyond that observed failed allowance, while retaining the banked lanes
/// at startup on documented 24/32 GiB competition boxes and the 80 GiB default
/// profile.  This is an admission boundary, not a claimed aggregate peak proof;
/// the exact override exists for externally isolated runs with a stronger
/// containment contract.
const OPTIONAL_HEAVY_MIN_HEADROOM_BYTES: u64 = 16 * 1024 * 1024 * 1024;

// #router-r4 CR-L: one optional heavy lane's lease IS this measured boundary,
// so under a cgroup the lease's floor and today's gate ask for the same bytes.
const _: () = assert!(
    OPTIONAL_HEAVY_MIN_HEADROOM_BYTES == ny_core::router::lease::OPTIONAL_HEAVY_LEASE_BYTES
);

/// Graph-heavy optional tails currently have no aggregate peak reservation:
/// margin-row can overlap the verifier, and post-BaB may retain an ORT session
/// while loading several full GraphNetworks.  A 12 GiB measured run entered the
/// latter with about 9.6 GiB of live headroom and still hit `memory.max` exactly.
/// Therefore a constrained kernel envelope below the measured-safe admission
/// boundary is not treated as an amount these lanes may race to consume. Keep
/// the already-sound verifier verdict until the heavy work is isolated in a
/// child or gains an aggregate reservation contract.
fn optional_heavy_memory_allowed(
    process_envelope: ProcessMemoryEnvelope,
    operator_override: Option<&OsStr>,
) -> bool {
    match operator_override {
        Some(value) if value == OsStr::new("1") => true,
        Some(value) if value == OsStr::new("0") => false,
        _ => match process_envelope {
            ProcessMemoryEnvelope::Bounded { headroom_bytes } => {
                headroom_bytes >= OPTIONAL_HEAVY_MIN_HEADROOM_BYTES
            }
            ProcessMemoryEnvelope::Unbounded => true,
            ProcessMemoryEnvelope::Unavailable => false,
        },
    }
}

pub(crate) fn optional_heavy_memory_allowed_now() -> bool {
    optional_heavy_memory_allowed(
        ny_propagate::network::crown_memory::process_memory_envelope(),
        std::env::var_os(OPTIONAL_HEAVY_MEMORY_OVERRIDE_ENV).as_deref(),
    )
}

fn margin_row_reserve_is_actionable(
    proof_tail_reserved: bool,
    memory_allowed: bool,
    deferred_outer_pgd_priority: bool,
) -> bool {
    !proof_tail_reserved && memory_allowed && !deferred_outer_pgd_priority
}

fn postbab_reserve_is_actionable(lane_enabled: bool, memory_allowed: bool) -> bool {
    lane_enabled && memory_allowed
}

/// Apply a requested fixed reserve without ever extending a short verifier
/// window. The historical `saturating_sub(requested).max(10)` expression could
/// turn a sub-ten-second input into ten seconds and therefore create wall time;
/// compute the maximum hold first instead.
fn postbab_reserve_window(before_secs: u64, requested_secs: u64) -> (u64, u64) {
    let held_secs = requested_secs.min(before_secs.saturating_sub(10));
    (before_secs - held_secs, held_secs)
}

fn postbab_after_margin_allowed(margin_worker_still_running: bool) -> bool {
    !margin_worker_still_running
}

fn postbab_graph_stage_memory_allowed(stage: &str) -> bool {
    // #router-r4 CR-L: under an armed lease every graph-heavy stage of the
    // tail holds the ONE tail lease (acquired by the first stage, never
    // debited twice); unarmed this is today's live gate, evaluated once.
    let allowed = crate::router::lease::admit(
        ny_core::router::lease::LeaseHolder::PostVerifierTail,
        optional_heavy_memory_allowed_now,
    );
    if !allowed {
        println!(
            "Post-BaB attack: DECLINED before {stage} — the live cgroup/RLIMIT envelope is \
             unavailable or below the {} GiB graph-tail admission boundary ({}=1 overrides); \
             preserving the already-sound verifier verdict",
            OPTIONAL_HEAVY_MIN_HEADROOM_BYTES / (1024 * 1024 * 1024),
            OPTIONAL_HEAVY_MEMORY_OVERRIDE_ENV
        );
    }
    allowed
}

/// Freeze the post-BaB attack's hard deadline before any VNN-LIB, graph, or
/// runtime setup.  Deriving it directly from the scored deadline keeps setup
/// inside the attack budget instead of sliding the attack window later by the
/// amount of time setup consumed.
fn postbab_attack_window(
    scored_deadline: std::time::Instant,
    now: std::time::Instant,
) -> Option<(std::time::Instant, std::time::Duration)> {
    let leftover = scored_deadline.saturating_duration_since(now);
    let (safety_margin, min_budget) = postbab_attack_reserves(leftover);
    let attack_deadline = scored_deadline.checked_sub(safety_margin)?;
    let budget = attack_deadline.saturating_duration_since(now);
    (budget >= min_budget).then_some((attack_deadline, budget))
}

/// Default and hard-maximum wall slices for the opt-in BaB-frontier fast lane.
///
/// Ten seconds covers the measured ACASXu frontier hits (restart 5 / 562 ORT
/// evaluations and restart 42 / 4,338 evaluations) while staying far below the
/// ~33 seconds the equality-seek stage consumed before reaching the same APGD
/// search.  The override is capped so a malformed campaign launch cannot turn
/// this deliberately-small probe into another full-budget lane.
const POSTBAB_FRONTIER_FASTLANE_DEFAULT_SECS: u64 = 10;
const POSTBAB_FRONTIER_FASTLANE_MAX_SECS: u64 = 30;

/// A sub-second slice is too small to amortize graph loading and at least one
/// gradient restart.  The existing post-BaB minimum is separately retained for
/// the unchanged fall-through path.
const POSTBAB_FRONTIER_FASTLANE_MIN_BUDGET: std::time::Duration =
    std::time::Duration::from_millis(500);

/// Deadline handed to the INLINE margin-row lane (#twinwall-reserve-respect,
/// banked 99ed4d42): when the post-BaB attack reserve is armed, cap the lane at
/// `instance_deadline - postbab_reserve - safety` so the seeded post-BaB attack
/// lane keeps its guaranteed slice (the safety margin covers the gate/re-check/
/// results-write tail, same constant the attack itself budgets against).
///
/// Reserve unarmed (0) => the deadline is passed through unchanged (behavior
/// byte-identical to before the reserve knob existed). FAIL-CLOSED: if the cap
/// cannot be represented, the lane gets an already-lapsed deadline and simply
/// declines (`try_margin_row_unsat` returns `None` under 10s of budget) — it
/// never inherits the uncapped deadline.
fn margin_row_lane_deadline(
    instance_deadline: Option<std::time::Instant>,
    postbab_reserve_secs: u64,
) -> Option<std::time::Instant> {
    match postbab_reserve_secs {
        0 => instance_deadline,
        reserved => instance_deadline.map(|d| {
            std::time::Duration::from_secs(reserved)
                .checked_add(POSTBAB_ATTACK_SAFETY_MARGIN)
                .and_then(|hold| d.checked_sub(hold))
                .unwrap_or_else(std::time::Instant::now)
        }),
    }
}

/// Latest work deadline shared by β-CROWN and every optional post-β proof lane.
///
/// The proof-tail route supplies an earlier absolute β deadline so the final
/// publication margin cannot be consumed by concurrent-join grace or a fresh
/// inline margin-row attempt. Historical routes pass `None` and retain the
/// scored instance deadline.
fn post_beta_work_deadline(
    instance_deadline: Option<std::time::Instant>,
    beta_phase_deadline: Option<std::time::Instant>,
) -> Option<std::time::Instant> {
    match (instance_deadline, beta_phase_deadline) {
        (Some(instance), Some(beta)) => Some(instance.min(beta)),
        (Some(instance), None) => Some(instance),
        (None, Some(beta)) => Some(beta),
        (None, None) => None,
    }
}

/// Freeze a lane-local wall budget at admission and cap it by any enclosing
/// absolute authority. `None` means the duration overflowed; an already-lapsed
/// result is left to the caller to reject.
fn bounded_work_deadline(
    admitted_at: std::time::Instant,
    wall_budget: std::time::Duration,
    authority_deadline: Option<std::time::Instant>,
) -> Option<std::time::Instant> {
    let local_deadline = admitted_at.checked_add(wall_budget)?;
    Some(
        authority_deadline
            .map(|authority| authority.min(local_deadline))
            .unwrap_or(local_deadline),
    )
}

/// Freeze the nonlinear fallback's relative slice before any file/model/runtime
/// setup and cap it by the shared proof-work deadline.
fn nonlinear_lane_deadline(
    timeout_secs: u64,
    work_deadline: Option<std::time::Instant>,
) -> Option<std::time::Instant> {
    let admitted_at = std::time::Instant::now();
    let local_budget = std::time::Duration::from_secs(timeout_secs.max(1)).mul_f32(0.8);
    let deadline = bounded_work_deadline(admitted_at, local_budget, work_deadline)?;
    (deadline > admitted_at).then_some(deadline)
}

fn concurrent_margin_row_grace(
    work_deadline: Option<std::time::Instant>,
    now: std::time::Instant,
) -> std::time::Duration {
    work_deadline
        .map(|deadline| deadline.saturating_duration_since(now))
        .unwrap_or_else(|| std::time::Duration::from_secs(5))
        .min(std::time::Duration::from_secs(5))
}

/// Parse the opt-in frontier-fast-lane environment contract without touching
/// process-global state (keeps the budget rules directly unit-testable).
///
/// `NY_POSTBAB_FRONTIER_FASTLANE=1` is the only enabling spelling.  The optional
/// `NY_POSTBAB_FRONTIER_FASTLANE_SECS` is a whole-second cap (default 10, hard
/// maximum 30).  Even when armed, preserve [`POSTBAB_ATTACK_MIN_BUDGET`] for the
/// pre-existing jitter/Newton/APGD fall-through if this probe misses.
fn postbab_frontier_fastlane_budget_from_raw(
    enabled: Option<&str>,
    secs: Option<&str>,
    remaining: std::time::Duration,
) -> Option<std::time::Duration> {
    if enabled != Some("1") {
        return None;
    }
    let usable = remaining.checked_sub(POSTBAB_ATTACK_MIN_BUDGET)?;
    let configured_secs = secs
        .and_then(|s| s.trim().parse::<u64>().ok())
        .filter(|&s| s > 0)
        .unwrap_or(POSTBAB_FRONTIER_FASTLANE_DEFAULT_SECS)
        .min(POSTBAB_FRONTIER_FASTLANE_MAX_SECS);
    let budget = usable.min(std::time::Duration::from_secs(configured_secs));
    (budget >= POSTBAB_FRONTIER_FASTLANE_MIN_BUDGET).then_some(budget)
}

fn postbab_frontier_fastlane_budget(remaining: std::time::Duration) -> Option<std::time::Duration> {
    let enabled = std::env::var("NY_POSTBAB_FRONTIER_FASTLANE").ok();
    let secs = std::env::var("NY_POSTBAB_FRONTIER_FASTLANE_SECS").ok();
    postbab_frontier_fastlane_budget_from_raw(enabled.as_deref(), secs.as_deref(), remaining)
}

const ORT_ACTIVE_SET_PER_SEED_BUDGET: std::time::Duration = std::time::Duration::from_secs(3);
const ORT_ACTIVE_SET_TOTAL_BUDGET: std::time::Duration = std::time::Duration::from_secs(6);
const POSTBAB_DOWNSTREAM_RESERVE: std::time::Duration = std::time::Duration::from_secs(3);
const ORT_ACTIVE_SET_MIN_SEED_BUDGET: std::time::Duration = std::time::Duration::from_millis(500);
const ORT_ACTIVE_SET_PRIMARY_ITERS: usize = 28;
const ORT_ACTIVE_SET_RESTART_ITERS: usize = 32;
const ORT_ACTIVE_SET_MIN_RESTART_BUDGET: std::time::Duration =
    std::time::Duration::from_millis(100);

/// #sbench-f64-attack: the active-set phase caps. [`Self::HISTORICAL`] is the
/// constant triple every shipped preset runs with; `attack.active_set_repair_secs`
/// replaces it through [`Self::from_total`] (read once, in
/// `f64_target_attack::PostBabActiveSetPolicy`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct OrtActiveSetCaps {
    /// Wall cap of one seed lineage's slice.
    per_seed: std::time::Duration,
    /// Wall cap of the whole phase.
    total: std::time::Duration,
    /// Multiplier on the Newton iteration caps.
    iteration_scale: usize,
}

impl OrtActiveSetCaps {
    const HISTORICAL: Self = Self {
        per_seed: ORT_ACTIVE_SET_PER_SEED_BUDGET,
        total: ORT_ACTIVE_SET_TOTAL_BUDGET,
        iteration_scale: 1,
    };

    /// A configured phase total: half per lineage (the historical 3 s / 6 s
    /// ratio, so a 6 s total reproduces [`Self::HISTORICAL`] exactly) and
    /// iteration caps scaled by `ceil(total / 6 s)`, at most 64x.
    fn from_total(total: std::time::Duration) -> Self {
        let ratio = total.as_secs_f64() / ORT_ACTIVE_SET_TOTAL_BUDGET.as_secs_f64();
        let iteration_scale = if ratio.is_finite() && ratio > 1.0 {
            (ratio.ceil() as usize).min(64)
        } else {
            1
        };
        Self {
            per_seed: total / 2,
            total,
            iteration_scale,
        }
    }
}

/// Budget the trusted-ORT repair without regressing the historical first seed.
/// Its old three-second opportunity is retained.  Additional wall time is
/// admitted only when it leaves [`POSTBAB_DOWNSTREAM_RESERVE`] for the older
/// stage-0/final lanes, and the whole active-set phase remains capped at six
/// seconds even when all three possible seed lineages are present.
///
/// The scored path calls [`ort_active_set_phase_budget_with_caps`]; this
/// HISTORICAL-caps form is the pinned reference its tests compare against.
#[cfg_attr(not(test), allow(dead_code))]
fn ort_active_set_phase_budget(
    remaining: std::time::Duration,
    seed_count: usize,
) -> std::time::Duration {
    ort_active_set_phase_budget_with_caps(remaining, seed_count, OrtActiveSetCaps::HISTORICAL)
}

/// [`ort_active_set_phase_budget`] under explicit caps (#sbench-f64-attack);
/// the same rule with `caps.per_seed` / `caps.total` in place of the 3 s / 6 s
/// constants, so [`OrtActiveSetCaps::HISTORICAL`] is bit-identical.
fn ort_active_set_phase_budget_with_caps(
    remaining: std::time::Duration,
    seed_count: usize,
    caps: OrtActiveSetCaps,
) -> std::time::Duration {
    if seed_count == 0 {
        return std::time::Duration::ZERO;
    }
    let historical = remaining.min(caps.per_seed);
    if seed_count == 1 {
        return historical;
    }
    let extra_capacity = remaining
        .saturating_sub(historical)
        .saturating_sub(POSTBAB_DOWNSTREAM_RESERVE);
    let extra_cap = caps.total.saturating_sub(historical);
    historical.saturating_add(extra_capacity.min(extra_cap))
}

/// Slice the remaining active-set phase. Seed zero keeps its historical
/// up-to-three-second opportunity. Later seeds divide the live remainder by
/// the number of lineages still waiting, so each gets a fair chance; when an
/// earlier repair finishes before its slice, the next calculation reclaims
/// that unused wall time. The fixed phase deadline still owns the total cap.
///
/// The scored path calls [`ort_active_set_seed_budget_with_caps`]; this
/// HISTORICAL-caps form is the pinned reference its tests compare against.
#[cfg_attr(not(test), allow(dead_code))]
fn ort_active_set_seed_budget(
    phase_remaining: std::time::Duration,
    seed_index: usize,
    seed_count: usize,
) -> std::time::Duration {
    ort_active_set_seed_budget_with_caps(
        phase_remaining,
        seed_index,
        seed_count,
        OrtActiveSetCaps::HISTORICAL,
    )
}

/// [`ort_active_set_seed_budget`] under explicit caps (#sbench-f64-attack).
fn ort_active_set_seed_budget_with_caps(
    phase_remaining: std::time::Duration,
    seed_index: usize,
    seed_count: usize,
    caps: OrtActiveSetCaps,
) -> std::time::Duration {
    if seed_index >= seed_count {
        return std::time::Duration::ZERO;
    }
    let available = if seed_index == 0 {
        phase_remaining
    } else {
        let waiting = u32::try_from(seed_count - seed_index).unwrap_or(u32::MAX);
        phase_remaining / waiting
    };
    available.min(caps.per_seed)
}

/// Cap f64 polish to both its historical 40%-of-attack share and the absolute
/// attack deadline less the downstream reserve. Passing the *current* hard-
/// deadline remainder makes all earlier setup/search time count.
fn f64_polish_phase_budget(
    hard_deadline_remaining: std::time::Duration,
    initial_attack_budget: std::time::Duration,
) -> std::time::Duration {
    let historical_share = initial_attack_budget.saturating_mul(2) / 5;
    hard_deadline_remaining
        .saturating_sub(POSTBAB_DOWNSTREAM_RESERVE)
        .min(historical_share)
}

/// Insert a deterministic micro-basin extrapolation between the first two
/// attack seeds. The first lineage stays first; the second original lineage is
/// retained immediately after the extrapolation. Every coordinate is computed
/// in f64 and clamped to the declared f32 search box before deduplication.
fn insert_active_set_pair_extrapolation(
    seeds: &mut Vec<Vec<f32>>,
    has_internal_witness: bool,
    box_lo: &[f32],
    box_hi: &[f32],
) -> bool {
    // A witness plus a PGD point are heterogeneous lineages. Only extrapolate
    // the first two independently exported PGD seeds from the witness-free
    // near-miss path measured here.
    if has_internal_witness
        || seeds.len() < 2
        || box_lo.len() != box_hi.len()
        || seeds[0].len() != box_lo.len()
        || seeds[1].len() != box_lo.len()
    {
        return false;
    }
    let candidate: Option<Vec<f32>> = seeds[0]
        .iter()
        .zip(&seeds[1])
        .zip(box_lo.iter().zip(box_hi))
        .map(|((&first, &second), (&lo, &hi))| {
            if !first.is_finite() || !second.is_finite() || lo > hi {
                return None;
            }
            let extrapolated = 2.0 * f32_to_f64_exact(second) - f32_to_f64_exact(first);
            extrapolated.is_finite().then(|| {
                extrapolated
                    .max(f32_to_f64_exact(lo))
                    .min(f32_to_f64_exact(hi)) as f32
            })
        })
        .collect();
    let Some(candidate) = candidate else {
        return false;
    };
    if seeds.contains(&candidate) {
        return false;
    }
    seeds.insert(1, candidate);
    true
}

/// A missing/NaN true-f64 margin is fail-open; only a definite negative margin
/// may suppress an ORT-only artifact and let the remaining attack lineages run.
fn definite_f64_margin_rejection(margin: Option<f64>) -> bool {
    margin.is_some_and(|margin| margin < 0.0)
}

/// f64 polish must continue past a definite true-f64 rejection. Missing/NaN
/// f64 support remains fail-open, matching the unchanged outer acceptance gate.
fn f64_polish_candidate_is_terminal(
    ort_violates: Option<bool>,
    emitted_f64_margin: Option<f64>,
) -> bool {
    ort_violates == Some(true) && !definite_f64_margin_rejection(emitted_f64_margin)
}

/// Recheck admission after releasing another graph-backed oracle, run one
/// graph-loading stage when admitted, then restore the oracle before the caller
/// evaluates the stage's candidate.
///
/// The recheck is deliberately after the retained graph is dropped, and the
/// restore is after `stage` returns, so the stage's local
/// GraphNetwork has been destroyed. Repeating this swap preserves f64-guided
/// jitter and local candidate rejection across every seed/round without ever
/// retaining the f64 graph alongside fast-lane/Newton graph state.
fn run_graph_stage_without_retained_oracle<T, R>(
    retained_oracle: &mut Option<T>,
    admit_stage: impl FnOnce() -> bool,
    stage: impl FnOnce() -> R,
    reload_oracle: impl FnOnce() -> Option<T>,
) -> Option<R> {
    drop(retained_oracle.take());
    if !admit_stage() {
        return None;
    }
    let result = stage();
    *retained_oracle = reload_oracle();
    Some(result)
}

/// Post-BaB leftover-budget falsification (#postbab-apgd): after the internal
/// verifier returned `unknown`/`timeout`, spend the REMAINING scored budget on the
/// exact-gradient DLR-APGD attack ([`gradient_guided_falsify`]) for ANY spec shape
/// (no structural gate — the property-margin machinery handles single-clause
/// conjunctions, disjunctions, and per-clause boxes alike). Returns the SMT-LIB
/// witness for an ORT-confirmed violation, or `None`.
///
/// SOUNDNESS: acceptance inside the attack is the trusted ORT forward + zero-tol
/// [`property_violated_f64`], and the caller re-routes the witness through the
/// UNCHANGED [`gate_sat_with_trusted_oracle`] (ORT re-confirm + true-f64 gate).
/// The pass runs only after a non-sat outcome and only inside the leftover wall
/// budget (deadline minus safety margin), so it cannot steal from BaB, cannot blow
/// the watchdog, and can never manufacture a false `sat`.
fn try_postbab_falsify(
    onnx: &Path,
    vnnlib: &Path,
    internal_witness: Option<&str>,
    best_margin_candidates: &[BestMarginCandidate],
    bab_frontier_seeds: &[BabFrontierSeed],
    instance_deadline: Option<std::time::Instant>,
    reserve_execution: Option<&mut PostBabReserveExecution>,
    restart_policy: PostBabRestartPolicy,
    twin_policy: attack_twin_lane::PointFoldedTwinPolicy,
    active_set_policy: f64_target_attack::PostBabActiveSetPolicy,
) -> Option<String> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    ny_core::phase_cost::count(ny_core::phase_cost::CostCounter::AttackRuns, 1);
    // #sbench-f64-attack: the `[f64-attack] armed=1 ...` line prints when this
    // value drops — on EVERY return below — whenever the f64 stage is armed;
    // disarmed (every shipped preset) it prints nothing and does nothing.
    let mut f64_attack = f64_target_attack::F64AttackTelemetry::new(active_set_policy);
    // HISTORICAL (the constants) unless `attack.active_set_repair_secs` is set.
    let active_set_caps = active_set_policy.caps();
    // #sbench-f64-maximin: the ORT phase's caps — `active_set_caps` exactly,
    // except under `attack.f64_lift_step: lp_maximin`, where the ORT phase
    // keeps the historical caps and the configured total funds the f64 lift.
    let ort_phase_caps = active_set_policy.ort_phase_caps();
    // No known scored deadline => no measurable leftover budget => skip (the
    // upfront/refine lanes already cover the interactive paths).
    let scored_deadline = instance_deadline?;

    // #deadlane: DECLINE BEFORE THE WINDOW IS HANDED OUT. `postbab_attack_window`
    // grants ALL remaining wall (minus the safety margin), so a lane with no
    // executable stage would otherwise be handed the whole early-exit — measured
    // 87.8 s of a 100 s budget on vit_2023 ibp_3_3_8_3005 and 556.5 s of a 600 s
    // budget on ml4acopf 14_ieee_prop9, each consumed in ~0.05 s before printing
    // "exact gradient unavailable for this net". See
    // `postbab_lane_has_executable_stage` for why "no gradient AND no seed" is
    // structurally dead. `NY_POSTBAB_DEADLANE=0` restores the legacy behavior.
    let has_seed = internal_witness.is_some()
        || !best_margin_candidates.is_empty()
        || !bab_frontier_seeds.is_empty();
    // Re-read the LIVE process envelope here, after any margin-row work and the
    // verifier have changed residency.  A stale start-of-instance observation
    // cannot authorize a post-verifier allocation burst.
    if !postbab_graph_stage_memory_allowed("tail setup") {
        return None;
    }
    // #lsnc-attack-twin: a net the exact loader left STATICALLY outside the
    // exact-gradient fragment gets exact-gradient PGD on its point-folded ATTACK
    // twin before the tail declines. The lane returns only an ORT-confirmed
    // witness, which the caller re-gates; a miss falls through to the
    // historical tail unchanged (with at most half its window spent when that
    // tail has seeded stages of its own).
    if twin_policy.armed && !net_supports_attack_gradients(onnx) {
        if let Some(witness) =
            attack_twin_lane::try_point_folded_twin_falsify(onnx, vnnlib, scored_deadline, has_seed)
        {
            return Some(witness);
        }
    }
    let executable =
        postbab_lane_has_executable_stage(has_seed, || net_supports_attack_gradients(onnx));
    if std::env::var("NY_POSTBAB_DEADLANE").ok().as_deref() != Some("0") && !executable {
        println!(
            "Post-BaB attack: DECLINED — no exact-gradient support on this net and no \
             seed to drive the derivative-free stages; the remaining {:.1}s is left \
             to verdict publication",
            scored_deadline
                .saturating_duration_since(std::time::Instant::now())
                .as_secs_f64()
        );
        return None;
    }

    // Freeze the scored-minus-safety deadline BEFORE setup so graph/runtime
    // construction consumes this window rather than shifting it later.
    let (attack_deadline, budget) =
        postbab_attack_window(scored_deadline, std::time::Instant::now())?;
    // #router-r3 CR-ATK: a held deferred upfront slice is spent HERE; the
    // ledger records whether this budget covers it (`realized=`). A no-op on
    // every row without a held defer.
    crate::router::ostop::note_late_attack_start(budget);

    let spec = ny_onnx::vnnlib::load_vnnlib(vnnlib).ok()?;
    let (box_lo, box_hi, emit_pin) = build_search_box(&spec)?;

    // Seed restart 0 from the internal near-miss witness (the ORT-divergence
    // class: internal forward says violated, ORT says SAFE — a genuine violation
    // often sits nearby). Guidance only; arity mismatches are ignored.
    //
    // #postbab-seed fallback: when the internal verifier produced NO witness at
    // all (the soundnessbench resister class), seed from the best-margin point
    // the internal graph-PGD search exported — measured on model_5, the search
    // stalls a few f32 ULPs below the violation threshold, exactly the gap the
    // ULP-jitter stage below crosses in seconds. A wrong seed only spends
    // otherwise-dead budget; every candidate still passes the unchanged gate.
    // Seed list, tried in order by the stage-0 alternation below: the internal
    // near-miss witness first (the ORT-divergence class: internal forward says
    // violated, ORT says SAFE — a genuine violation often sits nearby), then
    // the exported best-margin points (#postbab-seed): plain-lane and
    // #exploit-recycle-lane lineages, best margin first. Guidance only; arity
    // mismatches are ignored; a wrong seed only spends otherwise-dead budget.
    let mut seeds: Vec<Vec<f32>> = Vec::new();
    if let Some(s) = internal_witness
        .and_then(|w| parse_witness_inputs(w).ok())
        .filter(|s| s.len() == box_lo.len())
    {
        seeds.push(s);
    }
    for c in best_margin_candidates
        .iter()
        .filter(|c| c.point.len() == box_lo.len())
    {
        println!(
            "Post-BaB attack: internal best-margin seed (joint hinge margin {:.6e}, 0 => internal CE)",
            c.margin
        );
        if !seeds.contains(&c.point) {
            seeds.push(c.point.clone());
        }
    }
    let seed_label = if internal_witness.is_some() {
        "internal-witness"
    } else {
        "internal-best-margin"
    };
    let seed = seeds.first().cloned();

    // #bab-frontier: surviving-unverified BaB subbox centers, exported at the
    // engine's exhaust exits in violation-priority order. They target the
    // APGD restart list ONLY (restarts 2..2+P) — deliberately NOT the stage-0
    // alternation below, whose full-budget legs a 256-entry list would starve.
    // Arity-filtered against the search box and deduped against the
    // witness/best-margin seeds. Guidance only: every candidate still passes
    // the unchanged zero-tol acceptance inside the attack and the unchanged
    // trusted-ORT gate in the caller.
    //
    // #bab-frontier v2 (NY_POSTBAB_BAB_SEEDS=2): the same list additionally
    // carries (a) each seed's SUBBOX, into which its whole APGD restart leg is
    // projected (basin containment — the search stays in the unverified
    // region instead of wandering the global box), and (b) CORNER seeds for
    // the top boxes (JointMarginCloser per-row minimizer corners when the
    // exporter attached them, else the subbox's two extreme corners). Mode 1
    // keeps the v1 centers-only behavior byte-identical for A/B runs.
    let seeds_mode = postbab_bab_seeds_mode();
    let priority_seeds =
        assemble_frontier_priority_seeds(bab_frontier_seeds, box_lo.len(), &seeds, seeds_mode);
    if !priority_seeds.is_empty() {
        if let Some(best) = bab_frontier_seeds
            .iter()
            .find(|s| s.center.len() == box_lo.len())
        {
            println!(
                "Post-BaB attack: {} BaB-frontier seeds (best margin {:.6e}{})",
                priority_seeds.len(),
                best.margin,
                if seeds_mode >= 2 {
                    ", v2: subbox-projected legs + corner seeds"
                } else {
                    ""
                }
            );
        }
    }

    let mut forward = match ny_onnx::diff::OrtForward::from_path(onnx, box_lo.len()) {
        Ok(f) => f,
        Err(err) => {
            eprintln!("Post-BaB attack: trusted forward unavailable ({err}); skipping");
            return None;
        }
    };

    // A reserve earns T1 work credit only after one REAL trusted-runtime
    // evaluation succeeds. Counting entry to a graph falsifier is not enough:
    // graph loading deliberately fails open in some capability probes and can
    // return before evaluating a point. Probe the best admitted lineage (or the
    // box center) after every structural/setup gate, use the result as a genuine
    // falsification attempt, and record it only after `OrtForward::run` succeeds.
    if reserve_execution.is_some() {
        let live_work_budget = attack_deadline.saturating_duration_since(std::time::Instant::now());
        if live_work_budget >= POSTBAB_RESERVE_T1_MIN_WORK_BUDGET {
            let raw_probe = seed
                .as_ref()
                .or_else(|| priority_seeds.first().map(|priority| &priority.point))
                .cloned()
                .unwrap_or_else(|| {
                    box_lo
                        .iter()
                        .zip(&box_hi)
                        .map(|(lo, hi)| lo + 0.5 * (hi - lo))
                        .collect()
                });
            if let Some(probe) =
                postbab_admissible_probe_point(&raw_probe, &spec, &box_lo, &box_hi, &emit_pin)
            {
                if let Ok(output) = forward.run(&probe) {
                    let probe64 = refine_emit_view(&probe, &emit_pin);
                    let output64: Vec<f64> = output
                        .iter()
                        .map(|&value| f32_to_f64_exact(value))
                        .collect();
                    let probe_violates = property_violated_f64(&spec, &probe64, &output64);
                    if let Some(execution) = reserve_execution {
                        execution.note_work_unit(live_work_budget);
                    }
                    if probe_violates {
                        println!(
                            "Post-BaB reserve probe: trusted-ORT seed violates the property; \
                             retaining all ordinary lineages for full acceptance"
                        );
                    }
                }
            }
        }
    }

    // #witness-deepen: the jitter deepens past the first violation toward the
    // target margin; the f64 enclosure oracle joins the objective at
    // checkpoints when the net supports the exact-f64 cell (None ⇒ ORT-only).
    let f64_oracle_enabled = witness_deepen_target().is_some();
    let load_f64_oracle = || {
        (f64_oracle_enabled
            && crate::router::lease::admit(
                ny_core::router::lease::LeaseHolder::PostVerifierTail,
                optional_heavy_memory_allowed_now,
            ))
        .then(|| F64MarginOracle::load(onnx, box_lo.len()))
        .flatten()
    };
    let mut f64_oracle = load_f64_oracle();

    println!(
        "Post-BaB attack: DLR-APGD falsification in leftover budget ({:.1}s, {} dims, seed={})",
        budget.as_secs_f64(),
        box_lo.len(),
        if seed.is_some() {
            seed_label
        } else {
            "box-center"
        }
    );

    // #postbab-restart-diversity reserve: at the standard ~11 s soundnessbench
    // window the seeded descent stack is OVERSUBSCRIBED (active-set + f64-polish
    // + one alternation round already exceed it), so a restart lane that only
    // consumed "time left after self-termination" would receive ~0 s and read
    // VOID at exactly the window that competes. When armed, carve the restarts'
    // share out of the DESCENT's deadline instead — two seconds per requested
    // restart, at most half the window — leaving the attack window itself and
    // every deadline outside this lane untouched. Zero restarts (the default)
    // keeps `descent_deadline == attack_deadline` and the whole lane
    // byte-identical.
    let restart_reserve = if restart_policy.configured_restarts > 0 {
        POSTBAB_RESTART_MIN_SLICE
            .saturating_mul(u32::try_from(restart_policy.configured_restarts).unwrap_or(u32::MAX))
            .min(budget / 2)
    } else {
        std::time::Duration::ZERO
    };
    let descent_deadline = attack_deadline
        .checked_sub(restart_reserve)
        .unwrap_or(attack_deadline);
    let restart_row_seed = postbab_restart_row_seed(onnx, vnnlib);
    if restart_policy.configured_restarts > 0 {
        println!(
            "Post-BaB attack: restart diversity armed ({} restarts requested, reserving {:.1}s \
             of the {:.1}s window, row seed {restart_row_seed:016x})",
            restart_policy.configured_restarts,
            restart_reserve.as_secs_f64(),
            budget.as_secs_f64()
        );
    }

    // Emit helper: reject only a DEFINITE local true-f64 miss so an ORT-only
    // boundary artifact cannot abort the remaining lineages. Missing f64
    // support stays fail-open, and the caller always re-runs the unchanged
    // trusted-ORT + true-f64 gate before accepting a witness.
    macro_rules! emit_found {
        ($found:expr) => {{
            let found = $found;
            let found64 = refine_emit_view(&found, &emit_pin);
            let local_f64_margin = f64_oracle
                .as_ref()
                .and_then(|oracle| oracle.point_margin_f64(&spec, &found64));
            if definite_f64_margin_rejection(local_f64_margin) {
                println!(
                    "Post-BaB attack: ORT-only candidate rejected by local true-f64 precheck \
                     (worst margin {:.3e}); continuing remaining lineages",
                    local_f64_margin.expect("definite rejection has a margin")
                );
            } else {
                let output = forward.run(&found).ok()?;
                return Some(format_smtlib_witness_f64(&found64, &output));
            }
        }};
    }

    // #ort-active-set-repair: the internal graph attack already did the hard
    // global search; spend a short FIRST slice repairing its exported near seed
    // against the trusted runtime's exact surface.  This precedes the f64/jitter
    // stages because it reaches the measured box-face conjunction in well under
    // one second, while those stages otherwise consume the whole leftover
    // window. The first seed retains its historical three-second opportunity;
    // extra time is admitted only above a three-second downstream reserve and
    // is dynamically fair-shared across every remaining lineage. The total
    // lane remains capped at six seconds and falls through on a miss.
    // Kill-switch: NY_ORT_ACTIVE_SET_REPAIR=0.
    let mut inserted_active_set_pair = false;
    if std::env::var("NY_ORT_ACTIVE_SET_REPAIR").ok().as_deref() != Some("0") && !seeds.is_empty() {
        inserted_active_set_pair = insert_active_set_pair_extrapolation(
            &mut seeds,
            internal_witness.is_some(),
            &box_lo,
            &box_hi,
        );
        if inserted_active_set_pair {
            println!(
                "Post-BaB active-set repair: inserted clamped pair extrapolation \
                 (seed 1 remains first; seed 2 retained)"
            );
        }
        let phase_start = std::time::Instant::now();
        // #postbab-restart-diversity: the descent deadline equals the attack
        // deadline unless restarts are armed, in which case their reserve is
        // carved out of this and every following descent stage.
        let remaining = descent_deadline.saturating_duration_since(phase_start);
        let phase_budget =
            ort_active_set_phase_budget_with_caps(remaining, seeds.len(), ort_phase_caps);
        if phase_budget >= ORT_ACTIVE_SET_MIN_SEED_BUDGET {
            // `phase_budget <= remaining`, so this cannot exceed the frozen
            // absolute attack deadline. Fail closed to that deadline on an
            // exotic platform whose Instant range rejects checked_add.
            let phase_deadline = phase_start
                .checked_add(phase_budget)
                .unwrap_or(attack_deadline);
            println!(
                "Post-BaB active-set repair: trusted-ORT bounded Newton ({:.1}s total, {:.1}s/seed cap)",
                phase_budget.as_secs_f64(),
                ort_phase_caps.per_seed.as_secs_f64()
            );
            for seed_idx in 0..seeds.len() {
                let now = std::time::Instant::now();
                let seed_budget = ort_active_set_seed_budget_with_caps(
                    phase_deadline.saturating_duration_since(now),
                    seed_idx,
                    seeds.len(),
                    ort_phase_caps,
                );
                if seed_budget < ORT_ACTIVE_SET_MIN_SEED_BUDGET {
                    break;
                }
                let seed_deadline = now.checked_add(seed_budget).unwrap_or(phase_deadline);
                println!(
                    "Post-BaB active-set repair: seed {}/{} ({:.1}s slice)",
                    seed_idx + 1,
                    seeds.len(),
                    seed_budget.as_secs_f64()
                );
                let mut outcome = ort_active_set_repair_falsify(
                    &mut forward,
                    &spec,
                    &box_lo,
                    &box_hi,
                    &emit_pin,
                    &seeds[seed_idx],
                    seed_deadline,
                    OrtActiveSetFdMode::Central,
                    ORT_ACTIVE_SET_PRIMARY_ITERS * ort_phase_caps.iteration_scale,
                );
                if let Some(found) = outcome.as_ref().and_then(|o| o.violation.as_ref()) {
                    emit_found!(found.clone());
                }

                // A central-Jacobian pass finds the right local cell, but its
                // best trusted sample can be a better basin than its final
                // iterate. Restart once from that exact point with a one-sided
                // in-box Jacobian (one new ORT forward per axis). Both passes
                // share the same absolute seed deadline, so this spends no new
                // phase or downstream budget.
                let restart_seed = outcome
                    .as_ref()
                    .and_then(|o| o.best_guidance.as_ref())
                    .map(|(point, _)| point.clone());
                if let Some(restart_seed) = restart_seed.filter(|_| {
                    seed_deadline.saturating_duration_since(std::time::Instant::now())
                        >= ORT_ACTIVE_SET_MIN_RESTART_BUDGET
                }) {
                    println!(
                        "Post-BaB active-set repair: seed {} cheap restart from best trusted point",
                        seed_idx + 1
                    );
                    if let Some(restarted) = ort_active_set_repair_falsify(
                        &mut forward,
                        &spec,
                        &box_lo,
                        &box_hi,
                        &emit_pin,
                        &restart_seed,
                        seed_deadline,
                        OrtActiveSetFdMode::OneSided,
                        ORT_ACTIVE_SET_RESTART_ITERS * ort_phase_caps.iteration_scale,
                    ) {
                        if let Some(found) = restarted.violation.as_ref() {
                            emit_found!(found.clone());
                        }
                        let previous_margin = outcome
                            .as_ref()
                            .and_then(|o| o.best_guidance.as_ref())
                            .map_or(f64::NEG_INFINITY, |(_, margin)| *margin);
                        let restarted_margin = restarted
                            .best_guidance
                            .as_ref()
                            .map_or(f64::NEG_INFINITY, |(_, margin)| *margin);
                        if restarted_margin > previous_margin {
                            outcome = Some(restarted);
                        }
                    }
                }

                if let Some(outcome) = outcome.as_ref() {
                    if let Some(margin) = adopt_active_set_guidance(&mut seeds[seed_idx], outcome) {
                        println!(
                            "Post-BaB active-set repair: seed {} retained improved ORT guidance \
                             (margin {margin:.3e})",
                            seed_idx + 1
                        );
                    }
                }
            }
        }
    }
    if inserted_active_set_pair {
        // The derived lineage is active-set-only. On a miss, remove it before
        // every legacy downstream lane so their seed count/order and fixed
        // deadline behavior remain unchanged. The original lineages retain
        // any strictly improved guidance in their original relative order.
        seeds.remove(1);
    }

    // #sbench-f64-attack: float64 TARGET-MARGIN repair (DARK unless
    // `attack.f64_target_margin_ulps` is set; every shipped preset leaves it
    // unset, so this block is skipped and the tail is byte-identical).
    //
    // The ORT repair above ranks points on the f32 surface; SoundnessBench's
    // planted regions are thinner than that surface's rounding (property_054:
    // ORT +6.8e-8, true-f64 -1.3e-6). This stage lifts every conjunct to an
    // EXACT-f64 margin of `ulps` f32 ULPs using the f64 twin of the batched
    // point-VJP plan (exact residual and exact Jacobian rows), starting from
    // the lineages the ORT repair just improved, and consults the trusted ORT
    // forward only where the exact margin is already non-negative.
    //
    // SOUNDNESS: a candidate is handed on only when ORT confirms it at zero
    // tolerance AND its exact-f64 margin is >= 0; `emit_found!` then applies
    // the same local true-f64 precheck as every lineage above, and the caller
    // re-runs the unchanged `gate_sat_with_trusted_oracle`. No `unsat` can come
    // from here. Budget: the same phase rule and caps as the ORT repair
    // (`active_set_caps`), inside the frozen descent deadline.
    if let Some(target_ulps) = active_set_policy.f64_target_ulps() {
        f64_attack.reach(seeds.len());
        if seeds.is_empty() {
            f64_attack.decline("no_seeds");
        } else if !postbab_graph_stage_memory_allowed("f64 target-margin plan build") {
            f64_attack.decline("memory_not_admitted");
        } else {
            let phase_start = std::time::Instant::now();
            let phase_budget = ort_active_set_phase_budget_with_caps(
                descent_deadline.saturating_duration_since(phase_start),
                seeds.len(),
                active_set_caps,
            );
            // #sbench-f64-maximin: record where the lift's wall comes from
            // (armed `lp_maximin` only; the min-norm stage records nothing
            // new, so its flight record is byte-identical).
            if active_set_policy.lift_step() == crate::preset::F64LiftStep::LpMaximin {
                f64_attack.note_lift_budget(phase_budget);
                crate::flight::note(
                    "f64_lift_budget",
                    if phase_budget < f64_target_attack::MIN_PHASE_BUDGET {
                        crate::flight::FlightStatus::Skipped
                    } else {
                        crate::flight::FlightStatus::Ran
                    },
                    Some(format!(
                        "step=lp_maximin post_bab_window_s={:.3} descent_left_s={:.3} \
                         ort_phase=historical_caps f64_phase_budget_s={:.3} \
                         f64_phase_total_cap_s={:.3} f64_per_seed_cap_s={:.3} source={} \
                         basin_hops={} lineages={}",
                        budget.as_secs_f64(),
                        descent_deadline
                            .saturating_duration_since(phase_start)
                            .as_secs_f64(),
                        phase_budget.as_secs_f64(),
                        active_set_caps.total.as_secs_f64(),
                        active_set_caps.per_seed.as_secs_f64(),
                        active_set_policy.f64_budget_source(),
                        active_set_policy.basin_hops(),
                        seeds.len(),
                    )),
                );
            }
            if phase_budget < f64_target_attack::MIN_PHASE_BUDGET {
                f64_attack.decline("insufficient_budget");
            } else {
                let phase_deadline = phase_start
                    .checked_add(phase_budget)
                    .unwrap_or(attack_deadline);
                // Reuse the graph the f64 oracle already holds; load one only
                // when deepening left none (dropped again right after the build:
                // the twin owns its weights).
                let build_started = std::time::Instant::now();
                let owned_oracle = if f64_oracle.is_some() {
                    None
                } else {
                    F64MarginOracle::load(onnx, box_lo.len())
                };
                let plan = f64_oracle
                    .as_ref()
                    .or(owned_oracle.as_ref())
                    .and_then(|oracle| oracle.reusable_for(box_lo.len()))
                    .and_then(|(graph, declared_shape)| {
                        f64_target_attack::build_plan(
                            graph,
                            declared_shape,
                            &box_lo,
                            &box_hi,
                            phase_deadline,
                        )
                    });
                drop(owned_oracle);
                match plan {
                    None => f64_attack.decline("plan_unavailable"),
                    Some(plan) => {
                        f64_attack.note_plan(&plan);
                        println!(
                            "Post-BaB f64 target-margin repair: exact-f64 {} twin ({} side \
                             branches, {} exact maps) built in {:.2}s, {:.1}s of phase left, {} \
                             lineages, target {} f32 ULPs",
                            plan.kind(),
                            plan.branch_count(),
                            plan.exact_branch_maps(),
                            build_started.elapsed().as_secs_f64(),
                            phase_deadline
                                .saturating_duration_since(std::time::Instant::now())
                                .as_secs_f64(),
                            seeds.len(),
                            target_ulps
                        );
                        if std::time::Instant::now() >= phase_deadline {
                            f64_attack.decline("plan_build_consumed_phase");
                        }
                        for seed_idx in 0..seeds.len() {
                            let now = std::time::Instant::now();
                            let seed_budget = ort_active_set_seed_budget_with_caps(
                                phase_deadline.saturating_duration_since(now),
                                seed_idx,
                                seeds.len(),
                                active_set_caps,
                            );
                            if seed_budget < ORT_ACTIVE_SET_MIN_SEED_BUDGET {
                                break;
                            }
                            let seed_deadline =
                                now.checked_add(seed_budget).unwrap_or(phase_deadline);
                            // `min_norm` (the default) is exactly C8's
                            // `f64_target_margin_repair` call; `lp_maximin`
                            // runs the LP-maximin lift (#sbench-f64-maximin).
                            let Some((outcome, lift_stats)) = f64_target_attack::f64_lift_lineage(
                                active_set_policy,
                                &plan,
                                |x: &[f32]| f64_target_attack::trusted_outputs(&mut forward, x),
                                &spec,
                                &box_lo,
                                &box_hi,
                                &emit_pin,
                                &seeds[seed_idx],
                                target_ulps,
                                seed_deadline,
                                f64_target_attack::BASE_ITERS * active_set_caps.iteration_scale,
                            ) else {
                                f64_attack.note_seed_declined();
                                continue;
                            };
                            println!(
                                "Post-BaB f64 target-margin repair: seed {}/{} ({:.1}s slice): \
                                 exact-f64 margin {:.3e} -> {:.3e}, target {:.3e}, trusted margin \
                                 {:.3e}, {} iterations, {} trusted evals, {} candidates; \
                                 stopped: {}",
                                seed_idx + 1,
                                seeds.len(),
                                seed_budget.as_secs_f64(),
                                outcome.initial_margin_f64,
                                outcome.best_margin_f64,
                                outcome.target_delta,
                                outcome.best_margin_ort,
                                outcome.newton_iters,
                                outcome.trusted_evals,
                                outcome.candidates,
                                outcome.stop
                            );
                            f64_attack.absorb(&outcome);
                            if let Some(lift) = lift_stats.as_ref() {
                                f64_attack.absorb_lift(lift);
                                println!(
                                    "Post-BaB f64 LP-maximin lift: seed {}/{}: {} SLP iterations \
                                     ({} accepted, {} LP solves, {} LP failures), {} hops ({} \
                                     improved), final trust radius {:.3e}; stopped: {}",
                                    seed_idx + 1,
                                    seeds.len(),
                                    lift.slp_iters,
                                    lift.accepted,
                                    lift.lp_solves,
                                    lift.lp_failures,
                                    lift.hops,
                                    lift.hops_improved,
                                    lift.rho_final,
                                    lift.stop
                                );
                            }
                            if let Some(found) = outcome.violation {
                                f64_attack.note_handoff();
                                emit_found!(found);
                            }
                            if let Some((guidance, margin)) = outcome.guidance {
                                // Same hand-off as the ORT repair: a strictly
                                // better exact point feeds every later lane.
                                seeds[seed_idx] = guidance;
                                println!(
                                    "Post-BaB f64 target-margin repair: seed {} retained improved \
                                     exact-f64 guidance (margin {margin:.3e})",
                                    seed_idx + 1
                                );
                            }
                        }
                    }
                }
            }
        }
    }

    // The active-set lane is guidance as well as a terminal falsifier. Its
    // strictly improved trusted-ORT point should feed the same later lanes as
    // the original internal seed; all of them keep their existing acceptance
    // gates and absolute deadlines.
    let seed = seeds.first().cloned();

    // #f64-polish (strictly additive, moat-safe): exact-f64 FD-APGD on the
    // near-miss seeds BEFORE the f32 stages, which otherwise spend the whole
    // leftover budget plateauing a few 1e-5..1e-3 below the CE threshold (their f32
    // forward's accumulation error swamps the signal). An exact-f64 forward+gradient
    // resolves it and climbs the last stretch. Bounded to <=40% of the initial
    // attack budget AND to the frozen attack deadline less the same three-second
    // downstream reserve, so prior setup/repair time cannot shift it into the
    // safety tail. Every candidate is ORT + true-f64 gated
    // (emit_found! -> the caller's gate_sat_with_trusted_oracle), so this can only
    // ADD sats. Kill-switch NY_F64_POLISH=0; runs only when the exact-f64 cell is
    // available (fail-open) AND a seed is in the near-miss band.
    if std::env::var("NY_F64_POLISH").ok().as_deref() != Some("0") && !seeds.is_empty() {
        let phase_start = std::time::Instant::now();
        let phase_budget = f64_polish_phase_budget(
            descent_deadline.saturating_duration_since(phase_start),
            budget,
        );
        if phase_budget >= std::time::Duration::from_secs(2) {
            let reserved_deadline = descent_deadline
                .checked_sub(POSTBAB_DOWNSTREAM_RESERVE)
                .unwrap_or(phase_start);
            let phase_deadline = phase_start
                .checked_add(phase_budget)
                .unwrap_or(reserved_deadline)
                .min(reserved_deadline);
            // Owned-oracle setup is deliberately inside `phase_deadline`; a slow
            // load reduces (rather than shifts) the live polish window.
            let owned_oracle = if f64_oracle.is_some() {
                None
            } else {
                F64MarginOracle::load(onnx, box_lo.len())
            };
            if let Some(oracle) = f64_oracle.as_ref().or(owned_oracle.as_ref()) {
                let band = f64_polish_band();
                for s in &seeds {
                    if phase_deadline.saturating_duration_since(std::time::Instant::now())
                        < std::time::Duration::from_secs(2)
                    {
                        break;
                    }
                    let s64: Vec<f64> = s.iter().map(|&v| f32_to_f64_exact(v)).collect();
                    // Near-miss gate: skip seeds genuinely far from a violation.
                    match oracle.point_margin_f64(&spec, &s64) {
                        Some(m) if m > -band => {
                            println!(
                                "Post-BaB attack: f64-polish seed (exact-f64 min-margin {m:.6e})"
                            );
                        }
                        _ => continue,
                    }
                    if let Some(found) = f64_polish_falsify(
                        &mut forward,
                        oracle,
                        &spec,
                        &box_lo,
                        &box_hi,
                        &emit_pin,
                        s,
                        phase_deadline,
                    ) {
                        emit_found!(found);
                    }
                }
            }
        }
    }

    // #bab-frontier-fastlane (default OFF): the sealed-input ACASXu A/B showed
    // that a frontier restart reaches the real CE in 562--4,338 ORT evaluations,
    // but only AFTER stage 0 burns ~33s in equality-seek.  When explicitly armed,
    // try the same ORT-confirmed gradient search first with a tight wall cap.  The
    // first frontier center is restart 0 (rather than waiting behind the legacy
    // witness/center slots), the remaining centers retain their priority order,
    // and the bounded restart cap remains active.
    //
    // A miss consumes only its opt-in slice and then enters the exact pre-existing
    // stage-0 + final-APGD path below with the same seeds and independent fixed RNG.
    // Acceptance is unchanged twice over: `gradient_guided_falsify` requires a
    // trusted-ORT + zero-tolerance `property_violated_f64` hit, and the caller
    // still routes the rendered witness through `gate_sat_with_trusted_oracle`.
    let fastlane_remaining = descent_deadline.saturating_duration_since(std::time::Instant::now());
    if let Some(fastlane_budget) =
        postbab_frontier_fastlane_budget(fastlane_remaining).filter(|_| !priority_seeds.is_empty())
    {
        println!(
            "Post-BaB frontier fast lane: {} priority seeds, {:.1}s cap before equality-seek",
            priority_seeds.len(),
            fastlane_budget.as_secs_f64()
        );
        let found = run_graph_stage_without_retained_oracle(
            &mut f64_oracle,
            || postbab_graph_stage_memory_allowed("frontier fast-lane graph load"),
            || {
                frontier_fastlane_gradient_falsify(
                    onnx,
                    &mut forward,
                    &spec,
                    &box_lo,
                    &box_hi,
                    &emit_pin,
                    &priority_seeds,
                    instance_deadline,
                    fastlane_budget,
                )
            },
            load_f64_oracle,
        )?;
        if let Some(found) = found {
            emit_found!(found);
        }
        println!(
            "Post-BaB frontier fast lane: no confirmed violation; falling through to equality-seek"
        );
    }

    // Stage 0 (#postbab-ulp-jitter + #postbab-equality-seek, ALTERNATED):
    // measured on the soundnessbench resisters, the two local searches are
    // complementary and each unsticks the other —
    //   * ULP-jitter: greedy per-coordinate {1..4096}-ULP ascent on the exact
    //     ORT property margin (crosses the f32-knife-edge gap the APGD step
    //     floor is ~1000x too coarse for; flipped model_5 and, from the
    //     exported internal best-margin seed, model_16/29);
    //   * Newton-feasibility: min-norm step lifting every below-target
    //     conjunct at once (crosses the sharp multi-conjunct stalls where NO
    //     single-coordinate move improves; flipped model_30 in one step from
    //     the jitter's deadline point).
    // Alternate them from the best point so far until neither improves the
    // ORT margin or the leftover budget runs out. Every candidate still passes
    // the unchanged zero-tolerance gate; fruitless rounds spend dead budget.
    //
    // #postbab-restart-diversity bookkeeping (pure, output-free): remember the
    // best converged (point, margin) across the seed descents so the armed
    // restart block below can diversify AWAY from the measured fixed point.
    // With `attack.post_bab_restarts` at its zero default this tracking is
    // dead state and the lane stays byte-identical.
    let mut restart_reference: Option<(Vec<f32>, f64)> = None;
    for (seed_idx, s0) in seeds.iter().enumerate() {
        // Seeds run SEQUENTIALLY, best margin first, each with the ORIGINAL
        // full-budget legs until its natural no-improvement stop — later seeds
        // inherit whatever budget the earlier ones did not use. NO pre-split:
        // an even split halved the per-seed rounds and lost the model_0 flip
        // (its jitter crosses in round 2). With one seed this is byte-identical
        // to the previous single-seed behavior.
        let seed_deadline = descent_deadline;
        if seed_deadline.saturating_duration_since(std::time::Instant::now())
            < std::time::Duration::from_secs(3)
        {
            break;
        }
        if seeds.len() > 1 {
            println!(
                "Post-BaB attack: stage-0 seed {}/{}",
                seed_idx + 1,
                seeds.len()
            );
        }
        let mut cur: Vec<f32> = s0.clone();
        let mut cur_margin = f64::NEG_INFINITY;
        let mut round = 0usize;
        loop {
            round += 1;
            let remaining = seed_deadline.saturating_duration_since(std::time::Instant::now());
            if remaining < std::time::Duration::from_secs(3) {
                break;
            }
            // Jitter leg: a quarter of the leftover budget per round.
            let jitter_deadline =
                (std::time::Instant::now() + (budget / 4).min(remaining)).min(seed_deadline);
            let outcome = ulp_jitter_falsify(
                &mut forward,
                &spec,
                &box_lo,
                &box_hi,
                &emit_pin,
                &cur,
                jitter_deadline,
                f64_oracle.as_ref(),
            );
            if let Some(found) = outcome.violation {
                emit_found!(found);
            }
            let mut improved = false;
            if let Some((jx, jm)) = outcome.best {
                if jm > cur_margin {
                    cur_margin = jm;
                    cur = jx;
                    improved = true;
                }
            }

            // Newton leg: min-norm multi-conjunct step from the jitter's point.
            let remaining = seed_deadline.saturating_duration_since(std::time::Instant::now());
            if remaining < std::time::Duration::from_secs(3) {
                break;
            }
            let slice = (budget / 4).min(remaining);
            let (violation, best) = run_graph_stage_without_retained_oracle(
                &mut f64_oracle,
                || postbab_graph_stage_memory_allowed("Newton graph load"),
                || {
                    equality_seek_falsify(
                        onnx,
                        &mut forward,
                        &spec,
                        &box_lo,
                        &box_hi,
                        &emit_pin,
                        Some(&cur),
                        slice,
                    )
                },
                load_f64_oracle,
            )?;
            if let Some(found) = violation {
                emit_found!(found);
            }
            if let Some(nx) = best {
                // Adopt the Newton point only when it genuinely improves the
                // ORT property margin (its feasibility residual is a different
                // metric, and a worse point would send the next jitter astray).
                if let Ok(out) = forward.run(&nx) {
                    let out64: Vec<f64> = out.iter().map(|&v| f32_to_f64_exact(v)).collect();
                    let nm = property_margin(&spec, &nx, &out64);
                    if nm > cur_margin {
                        cur_margin = nm;
                        cur = nx;
                        improved = true;
                    }
                }
            }
            println!(
                "Post-BaB attack: alternation round {round} best ORT margin {cur_margin:.6e}{}",
                if improved {
                    ""
                } else {
                    " (no improvement; stopping)"
                }
            );
            if !improved {
                break;
            }
        }
        if cur_margin.is_finite()
            && restart_reference
                .as_ref()
                .is_none_or(|(_, margin)| cur_margin > *margin)
        {
            restart_reference = Some((cur, cur_margin));
        }
    }
    if seeds.is_empty() {
        // No seed: one equality-seek pass from the box center — its global
        // minimum is the planted point regardless of the start.
        let remaining = descent_deadline.saturating_duration_since(std::time::Instant::now());
        let slice = (budget / 3).min(remaining);
        if slice >= std::time::Duration::from_secs(2) {
            let (violation, best) = run_graph_stage_without_retained_oracle(
                &mut f64_oracle,
                || postbab_graph_stage_memory_allowed("center-seek graph load"),
                || {
                    equality_seek_falsify(
                        onnx,
                        &mut forward,
                        &spec,
                        &box_lo,
                        &box_hi,
                        &emit_pin,
                        None,
                        slice,
                    )
                },
                load_f64_oracle,
            )?;
            if let Some(found) = violation {
                emit_found!(found);
            }
            if let Some(s) = best {
                let jitter_deadline =
                    (std::time::Instant::now() + budget / 6).min(descent_deadline);
                if let Some(found) = ulp_jitter_falsify(
                    &mut forward,
                    &spec,
                    &box_lo,
                    &box_hi,
                    &emit_pin,
                    &s,
                    jitter_deadline,
                    f64_oracle.as_ref(),
                )
                .violation
                {
                    emit_found!(found);
                }
            }
        }
    }

    // #postbab-restart-diversity (default OFF, `attack.post_bab_restarts`):
    // the 2026-08-31 soundnessbench window probe measured the stage-0 stack
    // CONVERGENT — bit-identical fixed points (margins to all printed digits)
    // at 11 s and at 49.6 s windows, self-terminating "no improvement;
    // stopping" — so window length is not the binding constraint and the open
    // axis is basin DIVERSITY (the reference tool runs 250 restarts on that
    // family). When armed, re-enter the same alternation up to N times from
    // deterministically seeded diversified basins (uniform / corner /
    // orthogonal-jitter away from the converged point, cycled), keeping the
    // best ORT margin across restarts. Seeding derives from the row's model
    // and property file names — never Date/random ambient state — so the
    // verdict stays a pure function of the instance. Each restart receives an
    // equal share of the reserve this lane carved out of the descent's
    // deadline above (two-second floor), so the attack window itself is
    // unchanged and the verifier grant untouched. SOUNDNESS: acceptance inside every
    // leg is the unchanged trusted-ORT zero-tolerance check, and the caller
    // still routes any witness through the UNCHANGED
    // `gate_sat_with_trusted_oracle`, so this lever can only ever ADD `sat`
    // through the existing gate.
    if restart_policy.configured_restarts > 0 {
        let configured = restart_policy.configured_restarts;
        let row_seed = restart_row_seed;
        {
            let mut used = 0u64;
            let mut best_margin = restart_reference
                .as_ref()
                .map_or(f64::NEG_INFINITY, |(_, margin)| *margin);
            for restart_index in 0..configured {
                let restart_start = std::time::Instant::now();
                let remaining = attack_deadline.saturating_duration_since(restart_start);
                if remaining < POSTBAB_RESTART_MIN_SLICE {
                    break;
                }
                let restarts_left = u32::try_from(configured - restart_index).unwrap_or(u32::MAX);
                let slice = (remaining / restarts_left)
                    .max(POSTBAB_RESTART_MIN_SLICE)
                    .min(remaining);
                let restart_deadline = restart_start
                    .checked_add(slice)
                    .unwrap_or(attack_deadline)
                    .min(attack_deadline);
                let basin = PostBabRestartBasin::from_index(restart_index);
                let mut cur = postbab_restart_basin_start(
                    basin,
                    &box_lo,
                    &box_hi,
                    restart_reference
                        .as_ref()
                        .map(|(point, _)| point.as_slice()),
                    row_seed,
                    restart_index,
                );
                used += 1;
                let mut cur_margin = f64::NEG_INFINITY;
                loop {
                    let leg_remaining =
                        restart_deadline.saturating_duration_since(std::time::Instant::now());
                    if leg_remaining < POSTBAB_RESTART_MIN_LEG {
                        break;
                    }
                    let jitter_deadline =
                        (std::time::Instant::now() + leg_remaining / 2).min(restart_deadline);
                    let outcome = ulp_jitter_falsify(
                        &mut forward,
                        &spec,
                        &box_lo,
                        &box_hi,
                        &emit_pin,
                        &cur,
                        jitter_deadline,
                        f64_oracle.as_ref(),
                    );
                    if let Some(found) = outcome.violation {
                        emit_found!(found);
                    }
                    let mut improved = false;
                    if let Some((jx, jm)) = outcome.best {
                        if jm > cur_margin {
                            cur_margin = jm;
                            cur = jx;
                            improved = true;
                        }
                    }
                    let leg_remaining =
                        restart_deadline.saturating_duration_since(std::time::Instant::now());
                    if leg_remaining >= POSTBAB_RESTART_MIN_LEG {
                        let (violation, best) = run_graph_stage_without_retained_oracle(
                            &mut f64_oracle,
                            || postbab_graph_stage_memory_allowed("restart Newton graph load"),
                            || {
                                equality_seek_falsify(
                                    onnx,
                                    &mut forward,
                                    &spec,
                                    &box_lo,
                                    &box_hi,
                                    &emit_pin,
                                    Some(&cur),
                                    leg_remaining,
                                )
                            },
                            load_f64_oracle,
                        )?;
                        if let Some(found) = violation {
                            emit_found!(found);
                        }
                        if let Some(nx) = best {
                            if let Ok(out) = forward.run(&nx) {
                                let out64: Vec<f64> =
                                    out.iter().map(|&v| f32_to_f64_exact(v)).collect();
                                let nm = property_margin(&spec, &nx, &out64);
                                if nm > cur_margin {
                                    cur_margin = nm;
                                    cur = nx;
                                    improved = true;
                                }
                            }
                        }
                    }
                    if !improved {
                        break;
                    }
                }
                println!(
                    "Post-BaB attack: restart {}/{configured} basin={} settled ORT margin \
                     {cur_margin:.6e}",
                    restart_index + 1,
                    basin.stable_token()
                );
                if cur_margin > best_margin {
                    best_margin = cur_margin;
                }
            }
            println!(
                "Post-BaB attack: restart diversity done: {used}/{configured} restarts used, \
                 best ORT margin {best_margin:.6e}"
            );
        }
    }

    let remaining = attack_deadline.saturating_duration_since(std::time::Instant::now());
    // #postbab-small-budget: same adaptive minimum as the entry gate, so the
    // gradient lane still fires inside a small re-opened window.
    if remaining < postbab_attack_reserves(remaining).1 {
        return None;
    }
    // The final APGD lane owns another full GraphNetwork; no f64-oracle graph
    // may remain resident across its load.
    drop(f64_oracle.take());
    if !postbab_graph_stage_memory_allowed("final APGD graph load") {
        return None;
    }
    let found = gradient_guided_falsify(
        onnx,
        &mut forward,
        &spec,
        &box_lo,
        &box_hi,
        &emit_pin,
        seed.as_deref(),
        &priority_seeds,
        instance_deadline,
        Some(remaining),
        true, // leftover budget: keep restarting until the wall deadline
    )?;

    // Render the witness in the emit view (pinned dims verbatim), Y recomputed with
    // the same trusted forward. The caller re-confirms via gate_sat_with_trusted_oracle.
    let output = forward.run(&found).ok()?;
    let found64 = refine_emit_view(&found, &emit_pin);
    Some(format_smtlib_witness_f64(&found64, &output))
}

/// #postbab-restart-diversity: minimum per-restart share of the leftover
/// window; below this a restart cannot run a useful jitter+Newton pair.
const POSTBAB_RESTART_MIN_SLICE: std::time::Duration = std::time::Duration::from_secs(2);
/// #postbab-restart-diversity: minimum time worth spending on one leg.
const POSTBAB_RESTART_MIN_LEG: std::time::Duration = std::time::Duration::from_secs(1);

/// #postbab-restart-diversity: the basin family a restart starts from,
/// cycled deterministically by restart index.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PostBabRestartBasin {
    /// Uniform sample of the search box.
    Uniform,
    /// A random corner of the search box (extreme point per axis).
    Corner,
    /// A large per-axis displacement away from the converged reference point
    /// (box center absent one), clamped into the box.
    OrthogonalJitter,
}

impl PostBabRestartBasin {
    const fn from_index(index: u64) -> Self {
        match index % 3 {
            0 => Self::Uniform,
            1 => Self::Corner,
            _ => Self::OrthogonalJitter,
        }
    }

    const fn stable_token(self) -> &'static str {
        match self {
            Self::Uniform => "uniform",
            Self::Corner => "corner",
            Self::OrthogonalJitter => "orthogonal-jitter",
        }
    }
}

/// #postbab-restart-diversity: FNV-1a 64 over the row's model and property
/// FILE NAMES (not absolute paths, which vary by host). Deterministic across
/// builds and runs by construction — restart seeding must never depend on
/// Date/random ambient state, or a verdict stops being a pure function of the
/// instance.
fn postbab_restart_row_seed(onnx: &Path, vnnlib: &Path) -> u64 {
    const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
    const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;
    let mut hash = FNV_OFFSET;
    let name_bytes = |path: &Path| {
        path.file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default()
    };
    for byte in name_bytes(onnx)
        .bytes()
        .chain(std::iter::once(0u8))
        .chain(name_bytes(vnnlib).bytes())
    {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }
    hash
}

/// #postbab-restart-diversity: the deterministic start point for one restart.
///
/// Pure in (basin, box, reference, row_seed, restart_index) so the schedule is
/// reproducible and testable. Every returned coordinate is inside
/// `[box_lo, box_hi]`; degenerate axes collapse to their single value.
fn postbab_restart_basin_start(
    basin: PostBabRestartBasin,
    box_lo: &[f32],
    box_hi: &[f32],
    reference: Option<&[f32]>,
    row_seed: u64,
    restart_index: u64,
) -> Vec<f32> {
    // xorshift state must be nonzero; golden-ratio-mix the restart index so
    // consecutive restarts land in unrelated streams.
    let mixed = row_seed ^ (restart_index.wrapping_add(1)).wrapping_mul(0x9E37_79B9_7F4A_7C15);
    let mut rng = SearchRng(if mixed == 0 { 1 } else { mixed });
    match basin {
        PostBabRestartBasin::Uniform => box_lo
            .iter()
            .zip(box_hi)
            .map(|(&lo, &hi)| rng.uniform(lo, hi))
            .collect(),
        PostBabRestartBasin::Corner => box_lo
            .iter()
            .zip(box_hi)
            .map(|(&lo, &hi)| if rng.next_u64() & 1 == 0 { lo } else { hi })
            .collect(),
        PostBabRestartBasin::OrthogonalJitter => box_lo
            .iter()
            .zip(box_hi)
            .enumerate()
            .map(|(d, (&lo, &hi))| {
                let anchor = reference
                    .and_then(|point| point.get(d).copied())
                    .filter(|value| value.is_finite())
                    .unwrap_or(lo + 0.5 * (hi - lo));
                // Displace by 25--75% of the axis range, direction from the
                // RNG; take the mirrored step when the first leaves the box,
                // then clamp. Far from the converged point by construction.
                let range = f32_to_f64_exact(hi) - f32_to_f64_exact(lo);
                let magnitude = f32_to_f64_exact(rng.uniform(0.25, 0.75)) * range;
                let sign = if rng.next_u64() & 1 == 0 { 1.0 } else { -1.0 };
                let anchor64 = f32_to_f64_exact(anchor);
                let candidate = anchor64 + sign * magnitude;
                let candidate =
                    if candidate < f32_to_f64_exact(lo) || candidate > f32_to_f64_exact(hi) {
                        anchor64 - sign * magnitude
                    } else {
                        candidate
                    };
                clamp_to_box(candidate as f32, lo, hi)
            })
            .collect(),
    }
}

/// #bab-frontier: the APGD priority-seed list from the exported BaB frontier.
/// Keeps only centers whose arity matches the search box (`dim`), preserving
/// the exported violation-priority order, and drops duplicates of `existing`
/// seeds (internal witness / best-margin points) or of earlier frontier
/// centers. Pure so the restart-schedule oracle can pin the behavior.
fn filter_bab_frontier_centers(
    frontier: &[BabFrontierSeed],
    dim: usize,
    existing: &[Vec<f32>],
) -> Vec<Vec<f32>> {
    let mut out: Vec<Vec<f32>> = Vec::new();
    for seed in frontier {
        if seed.center.len() != dim {
            continue;
        }
        if existing.contains(&seed.center) || out.contains(&seed.center) {
            continue;
        }
        out.push(seed.center.clone());
    }
    out
}

/// #bab-frontier gate mode for the CONSUMER side (must agree with the
/// recorder's gate in ny-propagate `record_bab_frontier_if_enabled`):
/// `NY_POSTBAB_BAB_SEEDS` unset/other (including retired mode `"3"`) => 0
/// (off — the recorder exported nothing, so the seed list is empty either
/// way); `"1"` => 1 (v1: center seeds only, no projection — preserved
/// byte-identical for A/B runs); `"2"` => 2 (v2: subbox-projected restart
/// legs + corner seeds). Values are exact: whitespace is not normalized.
fn postbab_bab_seeds_mode_from_raw(raw: Option<&str>) -> u8 {
    match raw {
        Some("1") => 1,
        Some("2") => 2,
        _ => 0,
    }
}

fn postbab_bab_seeds_mode() -> u8 {
    let raw = std::env::var("NY_POSTBAB_BAB_SEEDS").ok();
    postbab_bab_seeds_mode_from_raw(raw.as_deref())
}

/// One entry of the APGD priority-restart list (restarts `2..2+P`).
#[derive(Debug, Clone, PartialEq)]
struct PrioritySeed {
    /// The restart's starting point (a frontier subbox center or corner),
    /// clamped into the search box by [`restart_seed`].
    point: Vec<f32>,
    /// #bab-frontier v2 (a): the exporting BaB domain's subbox. When `Some`,
    /// the WHOLE APGD leg for this restart is projected into it (every
    /// iterate clamped to `[box_lo, box_hi] ∩ search box`) so the search
    /// stays in the unverified region instead of wandering the global box.
    /// `None` in v1/mode<2 — the leg then uses the global box, byte-identical
    /// to the pre-v2 schedule.
    subbox: Option<(Vec<f32>, Vec<f32>)>,
}

/// #bab-frontier: assemble the APGD priority-restart list from the exported
/// frontier. Pure (mode is an explicit argument) so the v2 oracles can pin
/// the behavior:
///
/// - `mode < 2` (off / v1): exactly [`filter_bab_frontier_centers`] — center
///   points in violation-priority order, no subboxes. Byte-identical to the
///   landed v1 list.
/// - `mode >= 2` (v2): every center carries its subbox for leg projection,
///   and the top [`BAB_FRONTIER_CORNER_BOXES`] subboxes additionally
///   contribute CORNER seeds — the exporter's JointMarginCloser per-row
///   minimizer corners when attached (`x_d = lo_d if a[j,d]>0 else hi_d`),
///   else the subbox's own two extreme corners (`box_lo`, `box_hi`). Corners
///   follow their box's center so the margin order is preserved at box
///   granularity. Arity-filtered and deduped against `existing` and earlier
///   entries, like v1.
///
/// Guidance only: every candidate still passes the unchanged zero-tol
/// acceptance inside the attack and the unchanged trusted-ORT gate above.
fn assemble_frontier_priority_seeds(
    frontier: &[BabFrontierSeed],
    dim: usize,
    existing: &[Vec<f32>],
    mode: u8,
) -> Vec<PrioritySeed> {
    if mode < 2 {
        return filter_bab_frontier_centers(frontier, dim, existing)
            .into_iter()
            .map(|point| PrioritySeed {
                point,
                subbox: None,
            })
            .collect();
    }
    let mut out: Vec<PrioritySeed> = Vec::new();
    for (box_idx, seed) in frontier.iter().enumerate() {
        if seed.center.len() != dim || seed.box_lo.len() != dim || seed.box_hi.len() != dim {
            continue;
        }
        let subbox = (seed.box_lo.clone(), seed.box_hi.clone());
        let push = |point: Vec<f32>, out: &mut Vec<PrioritySeed>| {
            if point.len() != dim
                || existing.contains(&point)
                || out.iter().any(|s| s.point == point)
            {
                return;
            }
            out.push(PrioritySeed {
                point,
                subbox: Some(subbox.clone()),
            });
        };
        push(seed.center.clone(), &mut out);
        if box_idx < BAB_FRONTIER_CORNER_BOXES {
            if seed.corners.is_empty() {
                // Fallback corners: the subbox's two extreme corners.
                push(seed.box_lo.clone(), &mut out);
                push(seed.box_hi.clone(), &mut out);
            } else {
                for corner in &seed.corners {
                    push(corner.clone(), &mut out);
                }
            }
        }
    }
    out
}

/// #bab-frontier v2 (a): the projection box for one restart leg. `Some` only
/// when `restart_idx` addresses a priority seed carrying a subbox (mode 2);
/// the subbox is intersected with the search box per-dim (defensive — the
/// exporter's boxes are subboxes of the root input box, but a stale or
/// mismatched seed must never let an iterate escape the spec's search box).
/// `None` (legacy restarts, v1 seeds, arity mismatch, or an empty
/// intersection from a bogus seed) => the leg uses the global box unchanged.
fn restart_projection_box(
    restart_idx: usize,
    priority_seeds: &[PrioritySeed],
    box_lo: &[f32],
    box_hi: &[f32],
) -> Option<(Vec<f32>, Vec<f32>)> {
    let seed = priority_seeds.get(restart_idx.checked_sub(2)?)?;
    let (sub_lo, sub_hi) = seed.subbox.as_ref()?;
    if sub_lo.len() != box_lo.len() || sub_hi.len() != box_hi.len() {
        return None;
    }
    let lo: Vec<f32> = sub_lo.iter().zip(box_lo).map(|(&s, &g)| s.max(g)).collect();
    let hi: Vec<f32> = sub_hi.iter().zip(box_hi).map(|(&s, &g)| s.min(g)).collect();
    if lo.iter().zip(&hi).any(|(l, h)| l > h) {
        return None; // disjoint (bogus/stale seed): fall back to the global box
    }
    Some((lo, hi))
}

/// Run the opt-in pre-equality gradient probe with frontier centers first.
///
/// The ordinary post-BaB schedule starts with the internal witness and global
/// center, then inserts frontier centers at restart 2.  This probe has no use for
/// the already-measured losing starts: promote `priority_seeds[0]` to restart 0,
/// keep the global center at restart 1, and feed the remaining frontier centers
/// to restarts 2 onward.  `gradient_guided_falsify` owns both acceptance gates;
/// this helper only changes search order and budget.
#[allow(clippy::too_many_arguments)]
fn frontier_fastlane_gradient_falsify(
    onnx: &Path,
    forward: &mut ny_onnx::diff::OrtForward,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    box_lo: &[f32],
    box_hi: &[f32],
    emit_pin: &[Option<f64>],
    priority_seeds: &[PrioritySeed],
    instance_deadline: Option<std::time::Instant>,
    budget: std::time::Duration,
) -> Option<Vec<f32>> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    let (first, rest) = frontier_fastlane_seed_partition(priority_seeds)?;
    gradient_guided_falsify(
        onnx,
        forward,
        spec,
        box_lo,
        box_hi,
        emit_pin,
        Some(&first.point),
        rest,
        instance_deadline,
        Some(budget),
        false, // deliberately bounded: wall cap + the existing 64-restart ceiling
    )
}

/// Pure seed partition used by the fast lane: the best exported frontier center
/// becomes restart 0 and every later center remains ordered after the unchanged
/// restart-1 global center.
fn frontier_fastlane_seed_partition(
    priority_seeds: &[PrioritySeed],
) -> Option<(&PrioritySeed, &[PrioritySeed])> {
    let (first, rest) = priority_seeds.split_first()?;
    Some((first, rest))
}

/// Box/trust-region constrained minimum-norm row lift.
///
/// Solving the ordinary Newton system and clipping its result is not equivalent
/// to solving the constrained system: once a coordinate clips, every row lift
/// changes.  SoundnessBench-style planted witnesses commonly sit on dozens of
/// input-box faces, so that shortcut can leave a tiny but permanent negative
/// margin.  This bounded-variable solve freezes one saturated coordinate at a
/// time and RE-SOLVES over the remaining columns.  The returned step therefore
/// respects every coordinate bound while retaining the simultaneous active-row
/// objective as closely as the remaining degrees of freedom allow.
fn bounded_min_norm_row_lift(
    rows: &[Vec<f64>],
    rhs: &[f64],
    lower: &[f64],
    upper: &[f64],
    deadline: Option<std::time::Instant>,
) -> Option<Vec<f64>> {
    let k = rows.len();
    let dim = lower.len();
    if k == 0
        || rhs.len() != k
        || upper.len() != dim
        || rows.iter().any(|row| row.len() != dim)
        || lower.iter().zip(upper).any(|(lo, hi)| lo > hi)
    {
        return None;
    }

    let mut delta = vec![0.0f64; dim];
    let mut free = vec![true; dim];
    for _ in 0..=dim {
        if deadline.is_some_and(|limit| std::time::Instant::now() >= limit) {
            return None;
        }
        let mut adjusted = rhs.to_vec();
        for (i, row) in rows.iter().enumerate() {
            for d in 0..dim {
                if !free[d] {
                    adjusted[i] -= row[d] * delta[d];
                }
            }
        }

        if !free.iter().any(|&is_free| is_free) {
            return Some(delta);
        }
        let mut gram = vec![0.0f64; k * k];
        for i in 0..k {
            for j in 0..=i {
                let dot: f64 = (0..dim)
                    .filter(|&d| free[d])
                    .map(|d| rows[i][d] * rows[j][d])
                    .sum();
                gram[i * k + j] = dot;
                gram[j * k + i] = dot;
            }
        }
        let trace: f64 = (0..k).map(|i| gram[i * k + i]).sum();
        let damping = (trace / k as f64).max(1e-30) * 1e-10;
        for i in 0..k {
            gram[i * k + i] += damping;
        }
        let weights = solve_dense_spd(&mut gram, adjusted, k)?;
        for d in 0..dim {
            if free[d] {
                delta[d] = rows.iter().zip(&weights).map(|(row, w)| row[d] * w).sum();
            }
        }

        let mut worst: Option<(usize, f64, f64)> = None; // (dim, violation, bound)
        for d in 0..dim {
            if !free[d] {
                continue;
            }
            let (violation, bound) = if delta[d] < lower[d] {
                (lower[d] - delta[d], lower[d])
            } else if delta[d] > upper[d] {
                (delta[d] - upper[d], upper[d])
            } else {
                (0.0, delta[d])
            };
            if violation > worst.map_or(1e-12, |(_, v, _)| v) {
                worst = Some((d, violation, bound));
            }
        }
        let Some((d, _, bound)) = worst else {
            return delta.iter().all(|v| v.is_finite()).then_some(delta);
        };
        delta[d] = bound;
        free[d] = false;
    }
    None
}

/// In-box central finite-difference pair for one coordinate.  At a box face
/// this naturally becomes a one-sided difference with the ACTUAL (shorter)
/// denominator; it never samples outside the organizer-valid inward box.
fn in_box_fd_axis_pair(
    x: &[f32],
    d: usize,
    h: f32,
    box_lo: &[f32],
    box_hi: &[f32],
) -> Option<(Vec<f32>, Vec<f32>, f64)> {
    if x.len() != box_lo.len()
        || x.len() != box_hi.len()
        || d >= x.len()
        || !h.is_finite()
        || h <= 0.0
    {
        return None;
    }
    let mut xp = x.to_vec();
    let mut xm = x.to_vec();
    xp[d] = clamp_to_box(x[d] + h, box_lo[d], box_hi[d]);
    xm[d] = clamp_to_box(x[d] - h, box_lo[d], box_hi[d]);
    let denom = f32_to_f64_exact(xp[d]) - f32_to_f64_exact(xm[d]);
    (denom > 0.0 && denom.is_finite()).then_some((xp, xm, denom))
}

/// Evaluate one finite-difference endpoint, except when clipping made that
/// endpoint the already-evaluated center. Box-face seeds are common in the
/// post-BaB lane; forwarding the center again is exactly redundant and can
/// consume a large fraction of a short repair slice.
fn eval_fd_endpoint_reusing_center<F>(
    endpoint: &[f32],
    center: &[f32],
    center_margins: &[f64],
    center_violates: bool,
    eval_endpoint: F,
) -> Option<(Vec<f64>, bool)>
where
    F: FnOnce(&[f32]) -> Option<(Vec<f64>, bool)>,
{
    if endpoint == center {
        Some((center_margins.to_vec(), center_violates))
    } else {
        eval_endpoint(endpoint)
    }
}

/// Turn an in-box central pair into a preferred-forward one-sided pair.
/// Exactly one returned endpoint equals `center`; the other is the inward
/// sample, and the denominator is its actual (possibly clipped) distance.
fn prefer_forward_one_sided_fd_pair(
    center: &[f32],
    d: usize,
    mut xp: Vec<f32>,
    mut xm: Vec<f32>,
) -> Option<(Vec<f32>, Vec<f32>, f64)> {
    if d >= center.len() || xp.len() != center.len() || xm.len() != center.len() {
        return None;
    }
    let denom = if xp != center {
        xm.clone_from_slice(center);
        f32_to_f64_exact(xp[d]) - f32_to_f64_exact(center[d])
    } else {
        xp.clone_from_slice(center);
        f32_to_f64_exact(center[d]) - f32_to_f64_exact(xm[d])
    };
    (denom > 0.0 && denom.is_finite()).then_some((xp, xm, denom))
}

/// ORT finite-difference active-set repair of a near counterexample.
///
/// The internal graph PGD already exports excellent near seeds on difficult
/// conjunctions, but a binding-row sign step and the old clip-after-Newton
/// repair can park a few `1e-5` below the trusted runtime's threshold.  For a
/// small-dimensional near seed, measure the ACTIVE constraint Jacobian against
/// the trusted ORT forward itself, then use [`bounded_min_norm_row_lift`] so
/// dozens of box-face coordinates do not invalidate the simultaneous lift.
///
/// This is attack-only guidance.  Every sampled point is accepted only by the
/// unchanged trusted-ORT, zero-tolerance full-property gate; the caller gates
/// the rendered witness again (including the true-f64 enclosure check).  A bad
/// finite-difference row can therefore only spend this bounded leftover slice.
struct OrtActiveSetRepairOutcome {
    violation: Option<Vec<f32>>,
    /// Strictly better trusted-ORT guidance for the already-gated downstream
    /// attack lanes. This is never a witness by itself: all later acceptance
    /// still goes through the unchanged trusted-ORT and true-f64 gates.
    best_guidance: Option<(Vec<f32>, f64)>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum OrtActiveSetFdMode {
    Central,
    OneSided,
}

/// Explicit, non-verdict research lanes for post-BaB attack development.
///
/// These commands deliberately require every external asset as an argument.
/// They never participate in `ny vnncomp`, and a missing or malformed
/// prerequisite is a command error rather than a silently skipped test.
#[derive(clap::Subcommand, Debug)]
pub(crate) enum VnncompResearchAction {
    /// Run one serial real-corpus margin-row measurement.
    MarginRow {
        /// Named probe; invalid names report the complete selector list.
        probe: String,
    },
    /// Compare the Pensieve fractional-head fast and full bound paths.
    PensieveGap {
        /// ONNX model containing the normalized-power fractional head.
        onnx: PathBuf,
        /// VNN-LIB property defining the model's root input box.
        vnnlib: PathBuf,
    },
    /// Run one serial graph-MIP measurement from an explicit corpus checkout.
    GraphMip {
        /// Named probe; invalid names report the complete selector list.
        probe: String,
        /// Benchmark-version directory containing the selected probe's
        /// `onnx/`, `vnnlib/`, and (where needed) `instances.csv`.
        #[arg(long)]
        bench_dir: PathBuf,
        /// Output directory required only by the `emit-smtlib` probe.
        #[arg(long)]
        corpus_dir: Option<PathBuf>,
    },
    /// Run trusted-ORT active-set repair from an explicit NumPy f32 seed.
    ActiveSet {
        /// ONNX model used by the trusted ORT forward.
        onnx: PathBuf,
        /// VNN-LIB property defining the search box and unsafe region.
        vnnlib: PathBuf,
        /// Little-endian, one-dimensional NumPy v1 f32 seed.
        seed: PathBuf,
        /// Total attack budget in milliseconds.
        #[arg(long, default_value_t = 3_000)]
        budget_ms: u64,
        /// Finite-difference policy.
        #[arg(long, value_enum, default_value_t = ResearchFdModeArg::Central)]
        fd_mode: ResearchFdModeArg,
        /// Iteration cap for the initial active-set pass.
        #[arg(long, default_value_t = 32)]
        max_iters: usize,
        /// Retry the best guidance point with one-sided differences.
        #[arg(long, default_value_t = false)]
        restart_one_sided: bool,
        /// Iteration cap for the optional one-sided retry.
        #[arg(long, default_value_t = 32)]
        restart_iters: usize,
    },
    /// Run equality-seek directly with an explicit wall-clock budget.
    EqualitySeek {
        /// ONNX model used by the trusted ORT forward.
        onnx: PathBuf,
        /// VNN-LIB property defining the search box and unsafe region.
        vnnlib: PathBuf,
        /// Total equality-seek budget in seconds.
        #[arg(long, default_value_t = 60)]
        budget_secs: u64,
    },
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ResearchFdModeArg {
    Central,
    OneSided,
}

impl From<ResearchFdModeArg> for OrtActiveSetFdMode {
    fn from(value: ResearchFdModeArg) -> Self {
        match value {
            ResearchFdModeArg::Central => Self::Central,
            ResearchFdModeArg::OneSided => Self::OneSided,
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct ActiveSetResearchPolicy {
    budget_ms: u64,
    fd_mode: OrtActiveSetFdMode,
    max_iters: usize,
    restart_one_sided: bool,
    restart_iters: usize,
}

fn adopt_active_set_guidance(
    seed: &mut Vec<f32>,
    outcome: &OrtActiveSetRepairOutcome,
) -> Option<f64> {
    let (guidance, margin) = outcome.best_guidance.as_ref()?;
    *seed = guidance.clone();
    Some(*margin)
}

/// Retain the strongest zero-tolerance trusted-ORT violation seen so far.
/// Returns true only for the first violation, for one-shot telemetry.
fn record_best_active_set_violation(
    best: &mut Option<(Vec<f32>, f64)>,
    point: &[f32],
    margin: f64,
) -> bool {
    let first = best.is_none();
    if best
        .as_ref()
        .is_none_or(|(_, best_margin)| margin > *best_margin)
    {
        *best = Some((point.to_vec(), margin));
    }
    first
}

#[allow(clippy::too_many_arguments)]
fn ort_active_set_repair_falsify(
    forward: &mut ny_onnx::diff::OrtForward,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    box_lo: &[f32],
    box_hi: &[f32],
    emit_pin: &[Option<f64>],
    seed: &[f32],
    deadline: std::time::Instant,
    fd_mode: OrtActiveSetFdMode,
    max_iters: usize,
) -> Option<OrtActiveSetRepairOutcome> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    use std::time::Instant;

    const MAX_DIM: usize = 512;
    const MAX_CONJUNCTS: usize = 64;
    const NEAR_BAND: f64 = 2e-2;
    const ACTIVE_BAND: f64 = 1e-4;
    // The box-face cell can become infeasible when asked to overshoot too far:
    // a 1e-5 target never crossed zero in the 128-D offline replay, whereas
    // 1e-6 crossed reliably in four iterations.  Acceptance still uses the
    // unchanged zero-tolerance whole-property and true-f64 gates below.
    const TARGET: f64 = 1e-6;
    const H_REL: f32 = 2e-3;
    const H_MIN: f32 = 2e-6;

    let dim = box_lo.len();
    if seed.len() != dim || box_hi.len() != dim || dim == 0 || dim > MAX_DIM {
        return None;
    }
    if !spec.per_clause_input_bounds.is_empty() {
        return None;
    }
    let conjuncts: &[ny_onnx::vnnlib::OutputConstraint] =
        if spec.output_constraint_clauses.len() == 1 {
            &spec.output_constraint_clauses[0]
        } else if spec.output_constraint_clauses.is_empty() {
            &spec.output_constraints
        } else {
            return None;
        };
    // A scalar inequality does not need an active-set simultaneous lift and
    // already has cheaper dedicated polish stages.  Keep this default-on lane
    // additive for genuine conjunctions so a miss cannot tax older scalar
    // post-BaB routes by up to its three-second cap.
    if conjuncts.len() < 2 || conjuncts.len() > MAX_CONJUNCTS {
        return None;
    }

    let width: Vec<f32> = box_lo
        .iter()
        .zip(box_hi)
        .map(|(lo, hi)| (hi - lo).max(0.0))
        .collect();
    if width.iter().all(|&w| w <= 0.0) {
        return None;
    }
    let mut x: Vec<f32> = seed
        .iter()
        .enumerate()
        .map(|(d, &v)| clamp_to_box(v, box_lo[d], box_hi[d]))
        .collect();
    let mut evals = 0usize;
    let eval = |point: &[f32],
                forward: &mut ny_onnx::diff::OrtForward,
                evals: &mut usize|
     -> Option<(Vec<f64>, bool)> {
        *evals += 1;
        let out = forward.run(point).ok()?;
        let out64: Vec<f64> = out.iter().map(|&v| f32_to_f64_exact(v)).collect();
        let margins: Vec<f64> = conjuncts
            .iter()
            .map(|c| constraint_margin(c, &out64))
            .collect();
        if !margins.iter().all(|m| m.is_finite()) {
            return None;
        }
        let violated = property_violated_f64(spec, &refine_emit_view(point, emit_pin), &out64);
        Some((margins, violated))
    };
    let phi = |margins: &[f64]| -> f64 {
        margins
            .iter()
            .map(|&m| (TARGET - m).max(0.0))
            .map(|d| d * d)
            .sum()
    };

    let search_started = Instant::now();
    let (mut margins, mut x_violates) = eval(&x, forward, &mut evals)?;
    let mut best_margin = margins.iter().copied().fold(f64::INFINITY, f64::min);
    if best_margin < -NEAR_BAND {
        return None;
    }
    let initial_margin = best_margin;
    let mut best_point = x.clone();
    let mut best_violation = None;
    if x_violates {
        record_best_active_set_violation(&mut best_violation, &x, initial_margin);
        println!(
            "Post-BaB active-set repair: first zero-tolerance ORT violation at seed \
             (0 iterations, {evals} ORT evals, {:.6}s)",
            search_started.elapsed().as_secs_f64()
        );
    }
    let mut cap = 0.25f64;
    let mut h_rel = f32_to_f64_exact(H_REL);
    let mut iterations = 0usize;
    let mut stop_reason = "iteration cap";

    // Keep misses observable in sealed runs. This is diagnostics only: a point
    // is still returned solely when the unchanged trusted-ORT property check
    // above found a real violation.
    let finish = |found: Option<Vec<f32>>,
                  best: f64,
                  best_point: &[f32],
                  iterations: usize,
                  evals: usize,
                  reason: &str| {
        if found.is_some() {
            println!(
                "Post-BaB active-set repair: ORT-confirmed violation (initial margin \
                 {initial_margin:.3e}, best search margin {best:.3e}, {iterations} iterations, \
                 {evals} ORT evals; stopped: {reason})"
            );
        } else {
            println!(
                "Post-BaB active-set repair: no violation (initial margin \
                 {initial_margin:.3e}, best search margin {best:.3e}, {iterations} iterations, \
                 {evals} ORT evals; stopped: {reason})"
            );
        }
        Some(OrtActiveSetRepairOutcome {
            violation: found,
            best_guidance: (best > initial_margin).then(|| (best_point.to_vec(), best)),
        })
    };

    for iteration in 0..max_iters {
        if Instant::now() >= deadline {
            stop_reason = "deadline before iteration";
            break;
        }
        iterations = iteration + 1;
        let min_margin = margins.iter().copied().fold(f64::INFINITY, f64::min);
        if min_margin >= TARGET {
            println!(
                "Post-BaB active-set repair: robust ORT violation (margin {min_margin:.3e}, \
                 {iteration} iterations, {evals} ORT evals)"
            );
            return Some(OrtActiveSetRepairOutcome {
                violation: clamp_inside_box(&x, box_lo, box_hi),
                best_guidance: None,
            });
        }
        let cutoff = (min_margin + ACTIVE_BAND).max(2.0 * TARGET);
        let active: Vec<usize> = margins
            .iter()
            .enumerate()
            .filter_map(|(i, &m)| (m < cutoff).then_some(i))
            .collect();
        if active.is_empty() {
            stop_reason = "no active constraints";
            break;
        }

        // Central finite differences of ALL active rows.  One perturbed ORT
        // forward supplies every row for a coordinate; dimensions, not
        // conjunct count, own the cost.  At a box face the denominator becomes
        // one-sided automatically while remaining strictly in the inward box.
        let mut rows = vec![vec![0.0f64; dim]; active.len()];
        for d in 0..dim {
            if Instant::now() >= deadline {
                return finish(
                    best_violation.map(|(point, _)| point),
                    best_margin,
                    &best_point,
                    iterations,
                    evals,
                    "deadline during finite differences",
                );
            }
            if width[d] <= 0.0 {
                continue;
            }
            let h = (h_rel * f32_to_f64_exact(width[d])).max(f32_to_f64_exact(H_MIN)) as f32;
            let Some((mut xp, mut xm, mut denom)) = in_box_fd_axis_pair(&x, d, h, box_lo, box_hi)
            else {
                continue;
            };
            // The cheap restart uses one inward sample per axis. Prefer +h
            // whenever it stays in the box; at the upper face use -h. By
            // replacing the unused endpoint with the already-known center,
            // the same difference formula below remains exact and the center
            // cache guarantees one (not two) ORT forwards per coordinate.
            if fd_mode == OrtActiveSetFdMode::OneSided {
                (xp, xm, denom) = prefer_forward_one_sided_fd_pair(&x, d, xp, xm)?;
            }
            let Some((mp, vp)) =
                eval_fd_endpoint_reusing_center(&xp, &x, &margins, x_violates, |point| {
                    eval(point, forward, &mut evals)
                })
            else {
                return finish(
                    best_violation.map(|(point, _)| point),
                    best_margin,
                    &best_point,
                    iterations,
                    evals,
                    "trusted ORT evaluation failed",
                );
            };
            let mp_min = mp.iter().copied().fold(f64::INFINITY, f64::min);
            if mp_min > best_margin {
                best_margin = mp_min;
                best_point = xp.clone();
            }
            if vp {
                if record_best_active_set_violation(&mut best_violation, &xp, mp_min) {
                    println!(
                        "Post-BaB active-set repair: first zero-tolerance ORT violation \
                         ({} iterations, {evals} ORT evals, {:.6}s)",
                        iteration + 1,
                        search_started.elapsed().as_secs_f64()
                    );
                }
                if mp_min >= TARGET {
                    return Some(OrtActiveSetRepairOutcome {
                        violation: clamp_inside_box(&xp, box_lo, box_hi),
                        best_guidance: None,
                    });
                }
            }
            if Instant::now() >= deadline {
                return finish(
                    best_violation.map(|(point, _)| point),
                    best_margin,
                    &best_point,
                    iterations,
                    evals,
                    "deadline during finite differences",
                );
            }
            let Some((mm, vm)) =
                eval_fd_endpoint_reusing_center(&xm, &x, &margins, x_violates, |point| {
                    eval(point, forward, &mut evals)
                })
            else {
                return finish(
                    best_violation.map(|(point, _)| point),
                    best_margin,
                    &best_point,
                    iterations,
                    evals,
                    "trusted ORT evaluation failed",
                );
            };
            let mm_min = mm.iter().copied().fold(f64::INFINITY, f64::min);
            if mm_min > best_margin {
                best_margin = mm_min;
                best_point = xm.clone();
            }
            if vm {
                if record_best_active_set_violation(&mut best_violation, &xm, mm_min) {
                    println!(
                        "Post-BaB active-set repair: first zero-tolerance ORT violation \
                         ({} iterations, {evals} ORT evals, {:.6}s)",
                        iteration + 1,
                        search_started.elapsed().as_secs_f64()
                    );
                }
                if mm_min >= TARGET {
                    return Some(OrtActiveSetRepairOutcome {
                        violation: clamp_inside_box(&xm, box_lo, box_hi),
                        best_guidance: None,
                    });
                }
            }
            for (row, &c) in rows.iter_mut().zip(&active) {
                row[d] = (mp[c] - mm[c]) / denom;
            }
        }

        let rhs: Vec<f64> = active.iter().map(|&c| TARGET - margins[c]).collect();
        let lower: Vec<f64> = (0..dim)
            .map(|d| {
                (f32_to_f64_exact(box_lo[d]) - f32_to_f64_exact(x[d]))
                    .max(-cap * f32_to_f64_exact(width[d]))
            })
            .collect();
        let upper: Vec<f64> = (0..dim)
            .map(|d| {
                (f32_to_f64_exact(box_hi[d]) - f32_to_f64_exact(x[d]))
                    .min(cap * f32_to_f64_exact(width[d]))
            })
            .collect();
        let Some(delta) = bounded_min_norm_row_lift(&rows, &rhs, &lower, &upper, Some(deadline))
        else {
            stop_reason = if Instant::now() >= deadline {
                "deadline during bounded solve"
            } else {
                "bounded solve failed"
            };
            break;
        };
        if !delta.iter().any(|&v| v != 0.0) {
            stop_reason = "zero bounded step";
            break;
        }

        let old_phi = phi(&margins);
        let mut scale = 1.0f64;
        let mut accepted = false;
        for _ in 0..14 {
            if Instant::now() >= deadline {
                return finish(
                    best_violation.map(|(point, _)| point),
                    best_margin,
                    &best_point,
                    iterations,
                    evals,
                    "deadline during line search",
                );
            }
            let cand: Vec<f32> = (0..dim)
                .map(|d| {
                    clamp_to_box(
                        (f32_to_f64_exact(x[d]) + scale * delta[d]) as f32,
                        box_lo[d],
                        box_hi[d],
                    )
                })
                .collect();
            if cand == x {
                scale *= 0.25;
                continue;
            }
            let Some((cand_margins, cand_violates)) = eval(&cand, forward, &mut evals) else {
                return finish(
                    best_violation.map(|(point, _)| point),
                    best_margin,
                    &best_point,
                    iterations,
                    evals,
                    "trusted ORT evaluation failed",
                );
            };
            let cand_min = cand_margins.iter().copied().fold(f64::INFINITY, f64::min);
            if cand_min > best_margin {
                best_margin = cand_min;
                best_point = cand.clone();
            }
            if cand_violates {
                if record_best_active_set_violation(&mut best_violation, &cand, cand_min) {
                    println!(
                        "Post-BaB active-set repair: first zero-tolerance ORT violation \
                         ({} iterations, {evals} ORT evals, {:.6}s)",
                        iteration + 1,
                        search_started.elapsed().as_secs_f64()
                    );
                }
                if cand_min >= TARGET {
                    println!(
                        "Post-BaB active-set repair: robust ORT violation (margin \
                         {cand_min:.3e}, {} iterations, {evals} ORT evals)",
                        iteration + 1
                    );
                    return Some(OrtActiveSetRepairOutcome {
                        violation: clamp_inside_box(&cand, box_lo, box_hi),
                        best_guidance: None,
                    });
                }
            }
            let cand_phi = phi(&cand_margins);
            if cand_phi < old_phi * (1.0 - 1e-5) || cand_min > min_margin + 1e-7 {
                x = cand;
                margins = cand_margins;
                x_violates = cand_violates;
                cap = (cap * 1.3).min(0.5);
                accepted = true;
                break;
            }
            scale *= 0.25;
        }
        if !accepted {
            cap *= 0.25;
            h_rel = (h_rel * 0.5).max(2e-5);
            if cap < 2e-6 {
                stop_reason = "trust region exhausted";
                break;
            }
        }
    }
    finish(
        best_violation.map(|(point, _)| point),
        best_margin,
        &best_point,
        iterations,
        evals,
        stop_reason,
    )
}

/// #postbab-equality-seek: NEWTON-FEASIBILITY search for a point satisfying
/// EVERY conjunct of a conjunctive property simultaneously.
///
/// MOTIVATION (measured, soundnessbench model_6): the resister instances plant
/// counterexamples where 12 outputs must cross 12 exact f64 thresholds AT
/// ONCE. Margin-ascent (hinge / min-margin) objectives stall at shoulder
/// points (model_6: min-margin ~-2e-5, no single-coordinate move improves),
/// and plain gradient descent on Σ margin² crawls (measured: L stuck at
/// ~6.5e-3 after 2322 steps / 90s). But each conjunct margin is
/// piecewise-LINEAR in the input, so the natural solver is Newton on the
/// violated subset: take the exact VJP row of every conjunct below target,
/// solve the (tiny) least-squares system for the MINIMUM-NORM step that lifts
/// them all to a small positive margin, and iterate across ReLU regions under
/// a trust region. Within one linear region the step is exact.
///
/// SOUNDNESS: identical acceptance to every other lane (trusted ORT forward +
/// zero-tolerance [`property_violated_f64`] every step; caller re-gates).
/// Returns `(violation, best_point)`: `best_point` is the best-feasibility
/// point seen, exported as guidance for the follow-up ULP-jitter — never a
/// verdict.
fn equality_seek_falsify(
    onnx: &Path,
    forward: &mut ny_onnx::diff::OrtForward,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    box_lo: &[f32],
    box_hi: &[f32],
    emit_pin: &[Option<f64>],
    seed: Option<&[f32]>,
    budget: std::time::Duration,
) -> (Option<Vec<f32>>, Option<Vec<f32>>) {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    use std::time::Instant;
    let deadline = Instant::now() + budget;
    let dim = box_lo.len();

    // Per-clause input boxes change which conjuncts are active per point;
    // restrict to the plain global-box case this stage is built for.
    if !spec.per_clause_input_bounds.is_empty() {
        return (None, None);
    }
    // The conjunct set: the single clause of a one-clause disjunction (the
    // soundnessbench shape) or the top-level conjunction.
    let conjuncts: &[ny_onnx::vnnlib::OutputConstraint] =
        if spec.output_constraint_clauses.len() == 1 {
            &spec.output_constraint_clauses[0]
        } else if spec.output_constraint_clauses.is_empty() {
            &spec.output_constraints
        } else {
            return (None, None); // true multi-clause disjunction: not this shape
        };
    if conjuncts.is_empty() {
        return (None, None);
    }

    let graph = match load_graph_network(onnx) {
        Ok(g) => g,
        Err(_) => return (None, None),
    };
    let (_bytes, input_shape) = match ny_onnx::diff::read_input_shape_maybe_gzip(onnx, dim) {
        Ok(v) => v,
        Err(_) => return (None, None),
    };
    // #ml4acopf-vjp: `input_shape` only shapes the graph-side VJP point below;
    // see `GraphNetwork::attack_point_gradient_input_shape`.
    let input_shape = graph.attack_point_gradient_input_shape(&input_shape);
    let width: Vec<f32> = box_lo
        .iter()
        .zip(box_hi)
        .map(|(l, h)| (h - l).max(0.0))
        .collect();
    if width.iter().all(|&w| w <= 0.0) {
        return (None, None);
    }
    let center: Vec<f32> = box_lo
        .iter()
        .zip(box_hi)
        .map(|(l, h)| l + 0.5 * (h - l))
        .collect();

    println!(
        "Post-BaB equality-seek: Newton-feasibility over {} conjuncts ({:.1}s budget)",
        conjuncts.len(),
        budget.as_secs_f64()
    );

    // Margins we aim to LIFT each violated conjunct to: a small positive value
    // (strictly inside the unsafe region, with room for f32 forward noise).
    const TARGET: f64 = 1e-6;

    // Margins of every conjunct at `out64` (f64; satisfaction margin: >= 0
    // means the conjunct holds). `None` on an unmodeled variant.
    let margins_of = |out64: &[f64]| -> Option<Vec<f64>> {
        let ms: Vec<f64> = conjuncts
            .iter()
            .map(|c| constraint_margin(c, out64))
            .collect();
        ms.iter().all(|m| m.is_finite()).then_some(ms)
    };
    // Feasibility residual w.r.t. TARGET: Σ_c max(TARGET - m_c, 0)². Zero iff
    // every conjunct sits at least TARGET inside the unsafe region.
    let phi_of = |ms: &[f64]| -> f64 {
        ms.iter()
            .map(|&m| (TARGET - m).max(0.0))
            .map(|d| d * d)
            .sum()
    };

    let mut rng = SimpleRng::new(0x5EE4_u64 ^ 0x9E37_79B9_7F4A_7C15);
    let mut best_phi = f64::INFINITY;
    let mut best_x: Option<Vec<f32>> = None;
    let mut newton_steps = 0usize;
    let mut vjp_rows = 0usize;
    let mut restart_idx = 0usize;

    'restarts: while Instant::now() < deadline {
        let mut x: Vec<f32> = match restart_idx {
            0 => seed
                .map(|s| {
                    s.iter()
                        .enumerate()
                        .map(|(d, &v)| clamp_to_box(v, box_lo[d], box_hi[d]))
                        .collect()
                })
                .unwrap_or_else(|| center.clone()),
            1 => center.clone(),
            _ => (0..dim)
                .map(|d| clamp_to_box(box_lo[d] + rng.next_f32() * width[d], box_lo[d], box_hi[d]))
                .collect(),
        };
        restart_idx += 1;

        // Trust region: cap on the width-relative per-coordinate step.
        let mut cap = 0.1f64;
        // Fine basin-hops taken after trust-region exhaustion (see below).
        let mut perturbs = 0usize;

        // Evaluate the restart's start point.
        let Ok(out) = forward.run(&x) else { continue };
        let out64: Vec<f64> = out.iter().map(|&v| f32_to_f64_exact(v)).collect();
        if property_violated_f64(spec, &refine_emit_view(&x, emit_pin), &out64) {
            return (clamp_inside_box(&x, box_lo, box_hi), best_x);
        }
        let Some(mut margins) = margins_of(&out64) else {
            break; // unmodeled conjunct — stage unavailable for this spec
        };
        // `cur_phi` follows the trajectory (reset upward by basin-hops);
        // `restart_best_phi` only reports the restart's best.
        let mut cur_phi = phi_of(&margins);
        let mut restart_best_phi = cur_phi;
        if cur_phi < best_phi {
            best_phi = cur_phi;
            best_x = Some(x.clone());
        }

        loop {
            if Instant::now() >= deadline {
                break 'restarts;
            }
            // Violated subset S = {c : margin_c < TARGET} at the current point.
            let violated: Vec<usize> = (0..conjuncts.len())
                .filter(|&c| margins[c] < TARGET)
                .collect();
            if violated.is_empty() {
                // All margins >= TARGET yet the zero-tol check above did not
                // fire (strict-only corner) — nothing further to solve here.
                break;
            }
            // Exact VJP rows of the violated conjuncts (d margin_c / d x).
            let x_arr = match ArrayD::from_shape_vec(IxDyn(&input_shape), x.clone()) {
                Ok(a) => a,
                Err(_) => break 'restarts,
            };
            let mut rows_a: Vec<Vec<f64>> = Vec::with_capacity(violated.len());
            for &c in &violated {
                let Some(r) = constraint_grad_row(&conjuncts[c], out64.len()) else {
                    break 'restarts; // unmodeled — unavailable
                };
                let spec_row = match Array2::from_shape_vec((1, r.len()), r) {
                    Ok(m) => m,
                    Err(_) => break 'restarts,
                };
                let g = match graph.attack_point_gradient(&x_arr, &spec_row, None, Some(deadline)) {
                    Ok(Some(g)) => g,
                    Ok(None) | Err(_) => break 'restarts, // ineligible / deadline
                };
                vjp_rows += 1;
                rows_a.push(g.iter().take(dim).map(|&v| f32_to_f64_exact(v)).collect());
            }
            if rows_a.len() != violated.len() {
                break 'restarts;
            }
            // Min-norm Newton step: delta = A^T (A A^T + lambda I)^{-1} rhs,
            // rhs_c = TARGET - margin_c (> 0 for the violated set).
            let k = violated.len();
            let mut gram = vec![0.0f64; k * k];
            for i in 0..k {
                for j in 0..=i {
                    let dot: f64 = rows_a[i].iter().zip(&rows_a[j]).map(|(a, b)| a * b).sum();
                    gram[i * k + j] = dot;
                    gram[j * k + i] = dot;
                }
            }
            let trace: f64 = (0..k).map(|i| gram[i * k + i]).sum();
            let lambda = (trace / k as f64).max(1e-30) * 1e-10;
            for i in 0..k {
                gram[i * k + i] += lambda;
            }
            let rhs: Vec<f64> = violated.iter().map(|&c| TARGET - margins[c]).collect();
            let Some(w) = solve_dense_spd(&mut gram, rhs, k) else {
                break; // singular even after damping — next restart
            };
            let mut delta = vec![0.0f64; dim];
            for i in 0..k {
                for (d, slot) in delta.iter_mut().enumerate() {
                    *slot += w[i] * rows_a[i][d];
                }
            }
            newton_steps += 1;

            // Trust-region clip (width-relative) + backtracking accept loop.
            let rel = delta
                .iter()
                .enumerate()
                .map(|(d, &v)| {
                    if width[d] > 0.0 {
                        (v.abs() / f32_to_f64_exact(width[d])).abs()
                    } else {
                        0.0
                    }
                })
                .fold(0.0f64, f64::max);
            if !(rel.is_finite()) || rel <= 0.0 {
                break;
            }
            let mut accepted = false;
            let mut scale = (cap / rel).min(1.0);
            // Float condition is the intended stop: scale shrinks 4x per
            // rejected step, so scale*rel geometrically crosses the 1e-9 floor.
            #[allow(clippy::while_float)]
            while scale * rel >= 1e-9 {
                if Instant::now() >= deadline {
                    break 'restarts;
                }
                let mut cand = x.clone();
                let mut moved = false;
                for d in 0..dim {
                    if width[d] <= 0.0 {
                        continue;
                    }
                    let nv = clamp_to_box(
                        (f32_to_f64_exact(cand[d]) + scale * delta[d]) as f32,
                        box_lo[d],
                        box_hi[d],
                    );
                    if nv != cand[d] {
                        moved = true;
                    }
                    cand[d] = nv;
                }
                if !moved {
                    break;
                }
                let Ok(out) = forward.run(&cand) else { break };
                let cand64: Vec<f64> = out.iter().map(|&v| f32_to_f64_exact(v)).collect();
                if property_violated_f64(spec, &refine_emit_view(&cand, emit_pin), &cand64) {
                    println!(
                        "Post-BaB equality-seek: ORT-confirmed violation (restart {}, {newton_steps} Newton steps, {vjp_rows} VJP rows)",
                        restart_idx - 1
                    );
                    return (clamp_inside_box(&cand, box_lo, box_hi), best_x);
                }
                let Some(cand_margins) = margins_of(&cand64) else {
                    break;
                };
                let cand_phi = phi_of(&cand_margins);
                if cand_phi < cur_phi {
                    cur_phi = cand_phi;
                    restart_best_phi = restart_best_phi.min(cand_phi);
                    x = cand;
                    margins = cand_margins;
                    if cand_phi < best_phi {
                        best_phi = cand_phi;
                        best_x = Some(x.clone());
                    }
                    // Full Newton step accepted => grow the trust region.
                    cap = (cap * 1.5).min(0.5);
                    accepted = true;
                    break;
                }
                scale *= 0.25;
            }
            if !accepted {
                cap *= 0.25;
                if cap < 1e-8 {
                    // Sharp local min of the feasibility residual (measured on
                    // the soundnessbench resisters: phi stalls at ~1e-9..1e-11,
                    // margins a few 1e-6 below target). Basin-hop: a FINE random
                    // perturbation around the stall point re-rolls the ReLU
                    // region while staying in the near-feasible neighborhood.
                    perturbs += 1;
                    if perturbs > 12 {
                        break; // genuinely stuck — next restart
                    }
                    for d in 0..dim {
                        if width[d] <= 0.0 {
                            continue;
                        }
                        let noise = (rng.next_f32() * 2.0 - 1.0) * 1e-4 * width[d];
                        x[d] = clamp_to_box(x[d] + noise, box_lo[d], box_hi[d]);
                    }
                    let Ok(out) = forward.run(&x) else { break };
                    let out64: Vec<f64> = out.iter().map(|&v| f32_to_f64_exact(v)).collect();
                    if property_violated_f64(spec, &refine_emit_view(&x, emit_pin), &out64) {
                        return (clamp_inside_box(&x, box_lo, box_hi), best_x);
                    }
                    let Some(ms) = margins_of(&out64) else { break };
                    cur_phi = phi_of(&ms);
                    margins = ms;
                    cap = 1e-3;
                }
            }
        }
        println!(
            "Post-BaB equality-seek: restart {} done at phi = {restart_best_phi:.6e} ({newton_steps} Newton steps, {vjp_rows} VJP rows)",
            restart_idx - 1
        );
    }

    println!(
        "Post-BaB equality-seek: no violation; best feasibility residual = {best_phi:.6e} ({newton_steps} Newton steps, {restart_idx} restarts)"
    );
    (None, best_x)
}

/// Execute an explicit post-BaB research lane.
pub(crate) fn handle_vnncomp_research_command(action: VnncompResearchAction) -> Result<()> {
    match action {
        VnncompResearchAction::MarginRow { probe } => super::margin_row_bab::research::run(&probe),
        VnncompResearchAction::PensieveGap { onnx, vnnlib } => {
            super::beta_crown::run_pensieve_fastpath_gap_research(&onnx, &vnnlib)
        }
        VnncompResearchAction::GraphMip {
            probe,
            bench_dir,
            corpus_dir,
        } => {
            #[cfg(feature = "mip")]
            {
                super::beta_crown::run_graph_mip_research(&probe, &bench_dir, corpus_dir.as_deref())
            }
            #[cfg(not(feature = "mip"))]
            {
                let _ = (probe, bench_dir, corpus_dir);
                anyhow::bail!("graph-mip research requires rebuilding ny-cli with --features mip")
            }
        }
        VnncompResearchAction::ActiveSet {
            onnx,
            vnnlib,
            seed,
            budget_ms,
            fd_mode,
            max_iters,
            restart_one_sided,
            restart_iters,
        } => {
            anyhow::ensure!(budget_ms > 0, "--budget-ms must be positive");
            anyhow::ensure!(
                (1..=128).contains(&max_iters),
                "--max-iters must be in 1..=128"
            );
            anyhow::ensure!(
                (1..=128).contains(&restart_iters),
                "--restart-iters must be in 1..=128"
            );
            let policy = ActiveSetResearchPolicy {
                budget_ms,
                fd_mode: fd_mode.into(),
                max_iters,
                restart_one_sided,
                restart_iters,
            };
            run_active_set_research(&onnx, &vnnlib, &seed, policy)
        }
        VnncompResearchAction::EqualitySeek {
            onnx,
            vnnlib,
            budget_secs,
        } => {
            anyhow::ensure!(budget_secs > 0, "--budget-secs must be positive");
            run_equality_seek_research(&onnx, &vnnlib, budget_secs)
        }
    }
}

fn run_active_set_research(
    onnx: &Path,
    vnnlib: &Path,
    seed_path: &Path,
    policy: ActiveSetResearchPolicy,
) -> Result<()> {
    let ActiveSetResearchPolicy {
        budget_ms,
        fd_mode,
        max_iters,
        restart_one_sided,
        restart_iters,
    } = policy;
    anyhow::ensure!(onnx.is_file(), "missing ONNX file {}", onnx.display());
    anyhow::ensure!(
        vnnlib.is_file(),
        "missing VNN-LIB file {}",
        vnnlib.display()
    );
    anyhow::ensure!(
        seed_path.is_file(),
        "missing NumPy seed file {}",
        seed_path.display()
    );

    let bytes =
        fs::read(seed_path).with_context(|| format!("read NumPy seed {}", seed_path.display()))?;
    anyhow::ensure!(
        bytes.len() >= 10,
        "NumPy seed is shorter than its v1 header"
    );
    anyhow::ensure!(&bytes[..6] == b"\x93NUMPY", "invalid NumPy magic");
    anyhow::ensure!(
        bytes[6..8] == [1, 0],
        "only NumPy v1 seed files are supported"
    );
    let header_len = usize::from(u16::from_le_bytes([bytes[8], bytes[9]]));
    let payload_start = 10usize
        .checked_add(header_len)
        .context("NumPy header length overflow")?;
    anyhow::ensure!(
        payload_start <= bytes.len(),
        "NumPy header extends past end of seed file"
    );
    let payload = &bytes[payload_start..];
    let (chunks, remainder) = payload.as_chunks::<4>();
    anyhow::ensure!(
        remainder.is_empty(),
        "NumPy seed payload is not a whole number of f32 values"
    );
    let seed: Vec<f32> = chunks
        .iter()
        .map(|bytes| f32::from_le_bytes(*bytes))
        .collect();

    let spec = ny_onnx::vnnlib::load_vnnlib(vnnlib)
        .with_context(|| format!("load VNN-LIB {}", vnnlib.display()))?;
    let (box_lo, box_hi, emit_pin) =
        build_search_box(&spec).context("property has no supported search box")?;
    anyhow::ensure!(
        seed.len() == box_lo.len(),
        "seed dimension {} does not match property input dimension {}",
        seed.len(),
        box_lo.len()
    );
    let mut forward = ny_onnx::diff::OrtForward::from_path(onnx, box_lo.len())
        .with_context(|| format!("load ORT model {}", onnx.display()))?;
    let start = forward.run(&seed).context("run initial ORT forward")?;
    let start64: Vec<f64> = start.iter().map(|&value| f32_to_f64_exact(value)).collect();
    println!(
        "initial ORT margin = {:.9e}",
        property_margin(&spec, &seed, &start64)
    );
    let repair_start = std::time::Instant::now();
    let deadline = repair_start
        .checked_add(std::time::Duration::from_millis(budget_ms))
        .context("active-set deadline overflow")?;
    println!(
        "active-set policy = {fd_mode:?}/{max_iters}{}",
        if restart_one_sided {
            "+best-one-sided-restart"
        } else {
            ""
        }
    );
    let mut outcome = ort_active_set_repair_falsify(
        &mut forward,
        &spec,
        &box_lo,
        &box_hi,
        &emit_pin,
        &seed,
        deadline,
        fd_mode,
        max_iters,
    );
    let restart_seed = outcome
        .as_ref()
        .filter(|outcome| outcome.violation.is_none())
        .and_then(|outcome| outcome.best_guidance.as_ref())
        .map(|(point, _)| point.clone());
    if restart_one_sided {
        if let Some(restart_seed) = restart_seed {
            println!(
                "active-set best-point one-sided restart ({restart_iters} iteration cap, \
                 {:.6}s remaining)",
                deadline
                    .saturating_duration_since(std::time::Instant::now())
                    .as_secs_f64()
            );
            if let Some(restarted) = ort_active_set_repair_falsify(
                &mut forward,
                &spec,
                &box_lo,
                &box_hi,
                &emit_pin,
                &restart_seed,
                deadline,
                OrtActiveSetFdMode::OneSided,
                restart_iters,
            ) {
                let previous_best = outcome
                    .as_ref()
                    .and_then(|outcome| outcome.best_guidance.as_ref())
                    .map_or(f64::NEG_INFINITY, |(_, margin)| *margin);
                let restarted_best = restarted
                    .best_guidance
                    .as_ref()
                    .map_or(f64::NEG_INFINITY, |(_, margin)| *margin);
                if restarted.violation.is_some() || restarted_best > previous_best {
                    outcome = Some(restarted);
                }
            }
        }
    }
    println!(
        "active-set repair elapsed = {:.6}s",
        repair_start.elapsed().as_secs_f64()
    );
    if let Some(point) = outcome
        .as_ref()
        .and_then(|outcome| outcome.violation.as_ref())
    {
        let output = forward.run(point).context("run repaired ORT forward")?;
        let output64: Vec<f64> = output
            .iter()
            .map(|&value| f32_to_f64_exact(value))
            .collect();
        println!(
            "repaired ORT margin = {:.9e}",
            property_margin(&spec, point, &output64)
        );
        if let Some(oracle) = F64MarginOracle::load(onnx, box_lo.len()) {
            let emit_point = refine_emit_view(point, &emit_pin);
            println!(
                "repaired true-f64 point/worst margins = {:.9e} / {:.9e}",
                oracle
                    .point_margin_f64(&spec, &emit_point)
                    .unwrap_or(f64::NAN),
                oracle.worst_margin(&spec, point).unwrap_or(f64::NAN)
            );
        }
    } else if let Some((point, tracked_margin)) = outcome
        .as_ref()
        .and_then(|outcome| outcome.best_guidance.as_ref())
    {
        let output = forward.run(point).context("run guidance ORT forward")?;
        let output64: Vec<f64> = output
            .iter()
            .map(|&value| f32_to_f64_exact(value))
            .collect();
        println!(
            "best guidance ORT margin = {:.9e} (tracked {:.9e})",
            property_margin(&spec, point, &output64),
            tracked_margin
        );
    } else {
        println!("no repair or improved guidance");
    }
    Ok(())
}

fn run_equality_seek_research(onnx: &Path, vnnlib: &Path, budget_secs: u64) -> Result<()> {
    anyhow::ensure!(onnx.is_file(), "missing ONNX file {}", onnx.display());
    anyhow::ensure!(
        vnnlib.is_file(),
        "missing VNN-LIB file {}",
        vnnlib.display()
    );
    let spec = ny_onnx::vnnlib::load_vnnlib(vnnlib)
        .with_context(|| format!("load VNN-LIB {}", vnnlib.display()))?;
    let (box_lo, box_hi, emit_pin) =
        build_search_box(&spec).context("property has no supported search box")?;
    let mut forward = ny_onnx::diff::OrtForward::from_path(onnx, box_lo.len())
        .with_context(|| format!("load ORT model {}", onnx.display()))?;
    let (violation, best) = equality_seek_falsify(
        onnx,
        &mut forward,
        &spec,
        &box_lo,
        &box_hi,
        &emit_pin,
        None,
        std::time::Duration::from_secs(budget_secs),
    );
    if let Some(point) = &violation {
        let output = forward.run(point).context("run violating ORT forward")?;
        let output64: Vec<f64> = output
            .iter()
            .map(|&value| f32_to_f64_exact(value))
            .collect();
        println!(
            "VIOLATION FOUND; ORT margin = {:.6e}",
            property_margin(&spec, point, &output64)
        );
    } else if let Some(point) = &best {
        let output = forward.run(point).context("run best-point ORT forward")?;
        let output64: Vec<f64> = output
            .iter()
            .map(|&value| f32_to_f64_exact(value))
            .collect();
        println!(
            "no violation; best point ORT min-margin = {:.6e}",
            property_margin(&spec, point, &output64)
        );
    } else {
        println!("no violation or guidance point");
    }
    Ok(())
}

/// Solve the small dense symmetric-positive-definite system `M w = rhs`
/// (row-major `M`, `k x k`) by Gaussian elimination with partial pivoting.
/// `None` when a pivot degenerates (singular despite damping). Used for the
/// (<= #conjuncts)-sized Newton systems of [`equality_seek_falsify`].
fn solve_dense_spd(m: &mut [f64], mut rhs: Vec<f64>, k: usize) -> Option<Vec<f64>> {
    debug_assert_eq!(m.len(), k * k);
    debug_assert_eq!(rhs.len(), k);
    for col in 0..k {
        // Partial pivot.
        let mut piv = col;
        for r in (col + 1)..k {
            if m[r * k + col].abs() > m[piv * k + col].abs() {
                piv = r;
            }
        }
        if m[piv * k + col].abs() < 1e-300 {
            return None;
        }
        if piv != col {
            for c in 0..k {
                m.swap(col * k + c, piv * k + c);
            }
            rhs.swap(col, piv);
        }
        let inv = 1.0 / m[col * k + col];
        for r in (col + 1)..k {
            let f = m[r * k + col] * inv;
            if f == 0.0 {
                continue;
            }
            for c in col..k {
                m[r * k + c] -= f * m[col * k + c];
            }
            rhs[r] -= f * rhs[col];
        }
    }
    // Back substitution.
    let mut w = vec![0.0f64; k];
    for row in (0..k).rev() {
        let mut acc = rhs[row];
        for c in (row + 1)..k {
            acc -= m[row * k + c] * w[c];
        }
        w[row] = acc / m[row * k + row];
        if !w[row].is_finite() {
            return None;
        }
    }
    Some(w)
}

/// #witness-deepen: target margin for accepted-witness deepening. A `sat`
/// witness accepted at a hair-thin margin (+1e-8, the "first violation wins"
/// artifact of the greedy searches) is FRAGILE: the measured cross-build ORT
/// divergence is max|dY| = 3.4e-7, so the organizer's re-run can score the
/// same point SAFE and the sat silently evaporates (soundnessbench
/// model_25/42/48: banked sats whose independent-ORT margins are
/// -2.2e-8/-3.7e-7/-1.4e-8). Deepening continues the same greedy ULP ascent
/// PAST the first violation until the margin clears this target — measured
/// headroom exists (a jitter climbed -2.9e-5 → +2.7e-7 in 473 ORT evals, and
/// the planted CEs sit in a region, not at a point). `NY_WITNESS_DEEPEN=0`
/// kills; `NY_WITNESS_DEEPEN_TARGET` overrides the 1e-5 default (chosen an
/// order above the divergence AND the f32 forward noise).
///
/// SOUNDNESS: pure witness STRENGTHENING. A deepened point replaces the
/// accepted one only after independently re-passing the identical
/// zero-tolerance gates; on any failure the ORIGINAL accepted witness is
/// emitted unchanged — a sat is never lost, and no sat is ever accepted on a
/// weaker gate than today.
fn witness_deepen_target() -> Option<f64> {
    if std::env::var("NY_WITNESS_DEEPEN").ok().as_deref() == Some("0") {
        return None;
    }
    Some(
        std::env::var("NY_WITNESS_DEEPEN_TARGET")
            .ok()
            .and_then(|s| s.parse::<f64>().ok())
            .filter(|v| v.is_finite() && *v > 0.0)
            .unwrap_or(1e-5),
    )
}

/// #witness-deepen: lazily-loaded exact-f64 enclosure margin oracle. Deepening
/// wants the witness that maximizes `min(bundled-ORT margin, exact-f64
/// WORST-case margin)` — the ORT margin alone can be an f32 artifact of the
/// bundled runtime, while the f64 enclosure margin is build-independent. The
/// f64 walk costs 50-200 ms, so it runs only at CHECKPOINTS (first violation,
/// margin doublings, final acceptance), never in the per-move loop.
/// Guidance-only: a load/support failure degrades to the plain ORT objective.
struct F64MarginOracle {
    net: GraphNetwork,
    input_shape: Vec<usize>,
    /// The flat input length `input_shape` was resolved against — the
    /// `expected_len` argument of [`ny_onnx::diff::read_input_shape_maybe_gzip`].
    /// Recorded so [`Self::reusable_for`] can refuse a consumer holding a
    /// DIFFERENT length: that resolver falls back to a flat `[expected_len]`
    /// whenever the declared element count disagrees, so the same model can
    /// legitimately produce two different shapes for two different lengths.
    dim: usize,
}

impl F64MarginOracle {
    fn load(onnx: &Path, dim: usize) -> Option<Self> {
        let (_bytes, input_shape) = ny_onnx::diff::read_input_shape_maybe_gzip(onnx, dim).ok()?;
        let net = load_graph_network(onnx).ok()?;
        net.supports_ibp_f64_cell().then_some(Self {
            net,
            input_shape,
            dim,
        })
    }

    /// The graph and declared input shape this oracle ALREADY loaded, offered
    /// to a consumer that resolves the SAME model at the SAME flat input
    /// length (#witness-deepen-gate-reuse).
    ///
    /// BIT-IDENTICAL to a second load, on three checked facts:
    ///
    /// * `load_graph_network` is a pure function of the model file (parse ->
    ///   `to_graph_network_with_options` with fixed options), and this type has
    ///   no `&mut self` method and no field assigned after construction, so the
    ///   pair handed out is the pair `load` built;
    /// * the only consumer of the pair is `propagate_ibp_f64_cell`, which takes
    ///   `&self` and reads STRUCTURE alone — `output_ancestors` (a fresh DFS
    ///   into a membership set), `exec_order`, and `node` — building its value
    ///   cache per call. It never touches `GraphNetwork`'s bound caches;
    /// * `exec_order`'s `OnceLock` memoizes `compute_topological_sort`, which
    ///   sorts the node keys before its DFS precisely so the order does not
    ///   depend on hash iteration, so a warmed graph and a cold one yield the
    ///   same order and therefore the same walk.
    ///
    /// `None` on a length mismatch, so the caller re-derives both exactly as it
    /// would have with no oracle in hand.
    fn reusable_for(&self, dim: usize) -> Option<(&GraphNetwork, &[usize])> {
        (self.dim == dim).then_some((&self.net, self.input_shape.as_slice()))
    }

    /// WORST-case (guaranteed) f64 property margin at the f32 point `x` — the
    /// same input view the true-f64 acceptance gate evaluates (the emitted
    /// witness re-parses to these f32 values for every searched dim).
    fn worst_margin(&self, spec: &ny_onnx::vnnlib::VnnLibSpec, x: &[f32]) -> Option<f64> {
        let point = ArrayD::from_shape_vec(IxDyn(&self.input_shape), x.to_vec())
            .ok()?
            .mapv(f32_to_f64_exact);
        let out = self
            .net
            .propagate_ibp_f64_cell(&ny_propagate::Interval64::point(point))
            .ok()?;
        let out_lo: Vec<f64> = out.lower.iter().copied().collect();
        let out_hi: Vec<f64> = out.upper.iter().copied().collect();
        let input_f64: Vec<f64> = x.iter().map(|&v| f32_to_f64_exact(v)).collect();
        Some(property_margin_f64_worst(
            spec, &input_f64, &out_lo, &out_hi,
        ))
    }

    /// Exact-f64 min-conjunct property margin at the f64 input point `x`
    /// (#f64-polish). Mirrors [`Self::worst_margin`] but keeps FULL f64 input
    /// precision — the whole point of the polish is a sub-f32-ULP signal that the
    /// f32 lanes cannot resolve. Convention matches the attack objective: a margin
    /// `>= 0` means the property is VIOLATED (a counterexample) at `x`; the polish
    /// MAXIMIZES this to climb from the f32 plateau (~-3.6e-5) up to/past 0.
    fn point_margin_f64(&self, spec: &ny_onnx::vnnlib::VnnLibSpec, x: &[f64]) -> Option<f64> {
        let point = ArrayD::from_shape_vec(IxDyn(&self.input_shape), x.to_vec()).ok()?;
        let out = self
            .net
            .propagate_ibp_f64_cell(&ny_propagate::Interval64::point(point))
            .ok()?;
        let out_lo: Vec<f64> = out.lower.iter().copied().collect();
        let out_hi: Vec<f64> = out.upper.iter().copied().collect();
        Some(property_margin_f64_worst(spec, x, &out_lo, &out_hi))
    }
}

/// #postbab-ulp-jitter: ULP-granular coordinate ascent on the ORT property
/// margin, seeded at an internal near-miss witness.
///
/// MOTIVATION (measured, soundnessbench model_5): the internal PGD lands a point
/// whose trusted-ORT min-margin is ~-3e-7 — the planted counterexample sits at
/// near-EXACT threshold equality, so the last gap is a few f32 ULPs of the
/// binding outputs. Every coarser search misses it: the APGD sign-step floor is
/// `1e-4 x box width` (~1000x too coarse) and the derivative-free hill-climb
/// perturbs at box scale. This stage tries per-coordinate +/-{1,4,16}-ULP moves,
/// keeping any move that improves the exact ORT margin (greedy coordinate
/// ascent), until a full sweep yields no improvement or the deadline hits.
///
/// SOUNDNESS: identical acceptance to every other lane — a candidate is returned
/// ONLY when the trusted ORT forward + zero-tolerance [`property_violated_f64`]
/// on the emit view confirms a genuine violation; the caller additionally
/// re-routes it through [`gate_sat_with_trusted_oracle`]. Guidance-only
/// otherwise: a fruitless jitter merely spends leftover budget.
fn ulp_jitter_falsify(
    forward: &mut ny_onnx::diff::OrtForward,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    box_lo: &[f32],
    box_hi: &[f32],
    emit_pin: &[Option<f64>],
    seed: &[f32],
    deadline: std::time::Instant,
    f64_oracle: Option<&F64MarginOracle>,
) -> JitterOutcome {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    let dim = box_lo.len();
    if seed.len() != dim {
        return JitterOutcome::unavailable();
    }
    let mut x: Vec<f32> = seed
        .iter()
        .enumerate()
        .map(|(d, &v)| clamp_to_box(v, box_lo[d], box_hi[d]))
        .collect();

    let mut evals = 0usize;
    let eval = |x: &[f32],
                forward: &mut ny_onnx::diff::OrtForward,
                evals: &mut usize|
     -> Option<(f64, bool)> {
        *evals += 1;
        let out = forward.run(x).ok()?;
        let out64: Vec<f64> = out.iter().map(|&v| f32_to_f64_exact(v)).collect();
        let violated = property_violated_f64(spec, &refine_emit_view(x, emit_pin), &out64);
        Some((property_margin(spec, x, &out64), violated))
    };

    // #witness-deepen tracker: every recorded point is an ORT-confirmed
    // zero-tolerance violation (identical acceptance to the pre-deepen return).
    // `best_ort` is the ascent frontier; `best_joint` the checkpointed
    // min(ORT margin, f64 worst-case margin)-best point we actually return.
    let deepen_target = witness_deepen_target();
    struct DeepenTracker {
        best_ort: (Vec<f32>, f64),
        best_joint: (Vec<f32>, f64),
        last_checkpoint: f64,
    }
    let mut deep: Option<DeepenTracker> = None;
    let checkpoint_joint = |x: &[f32], m: f64, evals: usize| -> f64 {
        match f64_oracle.and_then(|o| o.worst_margin(spec, x)) {
            Some(f64_m) => {
                println!(
                    "Post-BaB ULP-jitter: deepen checkpoint ORT margin {m:.3e}, \
                         f64 worst-case margin {f64_m:.3e} ({evals} ORT evals)"
                );
                m.min(f64_m)
            }
            None => m,
        }
    };
    // Record an ORT-confirmed violating point; `true` ⇒ the deepening target is
    // met (or deepening is off) and the caller should return `deepened()` now.
    let note_violation =
        |x: &[f32], m: f64, evals: usize, deep: &mut Option<DeepenTracker>| -> bool {
            let Some(target) = deepen_target else {
                // Kill-switch (NY_WITNESS_DEEPEN=0): first violation wins, as before.
                *deep = Some(DeepenTracker {
                    best_ort: (x.to_vec(), m),
                    best_joint: (x.to_vec(), m),
                    last_checkpoint: m,
                });
                return true;
            };
            match deep {
                None => {
                    // First violation: checkpoint (f64), keep as the fallback floor.
                    let joint = checkpoint_joint(x, m, evals);
                    *deep = Some(DeepenTracker {
                        best_ort: (x.to_vec(), m),
                        best_joint: (x.to_vec(), joint),
                        last_checkpoint: m.max(0.0),
                    });
                    joint >= target
                }
                Some(t) => {
                    if m > t.best_ort.1 {
                        t.best_ort = (x.to_vec(), m);
                    }
                    // Checkpoint on margin doublings and on target-crossing
                    // candidates; the per-move loop never pays the f64 walk.
                    if m >= 2.0 * t.last_checkpoint.max(1e-12)
                        || (m >= target && t.best_joint.1 < target)
                    {
                        let joint = checkpoint_joint(x, m, evals);
                        if joint > t.best_joint.1 {
                            t.best_joint = (x.to_vec(), joint);
                        }
                        t.last_checkpoint = m.max(0.0);
                    }
                    t.best_joint.1 >= target
                }
            }
        };
    // Final acceptance checkpoint: score the ascent frontier before returning.
    let finish_deepened = |mut t: DeepenTracker, evals: usize| -> JitterOutcome {
        if deepen_target.is_some() && t.best_ort.1 > t.last_checkpoint {
            let joint = checkpoint_joint(&t.best_ort.0, t.best_ort.1, evals);
            if joint > t.best_joint.1 {
                t.best_joint = (t.best_ort.0.clone(), joint);
            }
        }
        println!(
            "Post-BaB ULP-jitter: returning deepened witness (joint margin {:.3e}, \
             {evals} ORT evals; NY_WITNESS_DEEPEN=0 disables deepening)",
            t.best_joint.1
        );
        JitterOutcome::violation(t.best_joint.0, t.best_joint.1)
    };

    let Some((mut best, violated)) = eval(&x, forward, &mut evals) else {
        return JitterOutcome::unavailable();
    };
    if violated {
        println!("Post-BaB ULP-jitter: seed itself is ORT-confirmed (margin {best:.3e})");
        if note_violation(&x, best, evals, &mut deep) {
            return finish_deepened(deep.expect("violation recorded"), evals);
        }
        println!(
            "Post-BaB ULP-jitter: deepening below-target witness (margin {best:.3e} < {:.1e})",
            deepen_target.unwrap_or(f64::NAN)
        );
    } else {
        println!("Post-BaB ULP-jitter: seed ORT min-margin {best:.6e}; starting coordinate ascent");
    }
    if !best.is_finite() {
        return JitterOutcome::unavailable(); // outside every clause box — nothing ULP-local to fix
    }

    // +/-{1,4,16,64,256,1024,4096}-ULP trial moves per coordinate. The small end
    // crosses the model_5 class (gap of a few f32 ULPs); the large end
    // (~1e-4 relative) bridges the measured DEAD ZONE between the ULP scale and
    // the APGD step floor (1e-4 x box width): soundnessbench model_6's internal
    // best-margin seed sits at ORT margin ~-2e-5 — ~100 ULPs of the binding
    // output — where 16-ULP coordinate moves converge short (measured: stall at
    // -1.6e-5) and APGD overshoots. Greedy accept keeps every improving move,
    // so the ladder self-selects the productive scale per coordinate.
    const TRIALS: [(bool, u32); 14] = [
        (true, 1),
        (false, 1),
        (true, 4),
        (false, 4),
        (true, 16),
        (false, 16),
        (true, 64),
        (false, 64),
        (true, 256),
        (false, 256),
        (true, 1024),
        (false, 1024),
        (true, 4096),
        (false, 4096),
    ];
    loop {
        let mut improved = false;
        for d in 0..dim {
            if box_hi[d] <= box_lo[d] {
                continue;
            }
            for (up, steps) in TRIALS {
                if std::time::Instant::now() >= deadline {
                    println!(
                        "Post-BaB ULP-jitter: deadline (best margin {best:.6e}, {evals} ORT evals)"
                    );
                    return match deep {
                        Some(t) => finish_deepened(t, evals),
                        None => JitterOutcome::best_only(x, best),
                    };
                }
                let mut v = x[d];
                for _ in 0..steps {
                    v = if up { next_up_f32(v) } else { next_down_f32(v) };
                }
                v = clamp_to_box(v, box_lo[d], box_hi[d]);
                if v == x[d] || !v.is_finite() {
                    continue;
                }
                let old = x[d];
                x[d] = v;
                match eval(&x, forward, &mut evals) {
                    Some((m, viol)) => {
                        if viol {
                            if deep.is_none() {
                                println!(
                                    "Post-BaB ULP-jitter: ORT-confirmed violation (margin \
                                     {m:.3e}, {evals} ORT evals)"
                                );
                            }
                            // #witness-deepen: keep the point (fallback floor)
                            // and CONTINUE the same greedy ascent until the
                            // margin clears the target (return immediately when
                            // it already does, or when deepening is off).
                            if note_violation(&x, m, evals, &mut deep) {
                                return finish_deepened(deep.expect("violation recorded"), evals);
                            }
                        }
                        if m > best {
                            best = m;
                            improved = true;
                        } else {
                            x[d] = old;
                        }
                    }
                    None => x[d] = old,
                }
            }
        }
        if !improved {
            if let Some(t) = deep {
                println!(
                    "Post-BaB ULP-jitter: deepening converged below target (best margin \
                     {best:.6e}, {evals} ORT evals)"
                );
                return finish_deepened(t, evals);
            }
            println!(
                "Post-BaB ULP-jitter: converged without violation (best margin {best:.6e}, \
                 {evals} ORT evals)"
            );
            return JitterOutcome::best_only(x, best);
        }
    }
}

/// Result of [`ulp_jitter_falsify`]: an ORT-confirmed violation, or the best
/// (highest-ORT-margin) non-violating point it reached — guidance for the
/// Newton/jitter alternation in [`try_postbab_falsify`], never a verdict.
struct JitterOutcome {
    /// ORT-confirmed violating point (zero-tolerance), when found.
    violation: Option<Vec<f32>>,
    /// Best point visited (== violation when set) + its ORT property margin.
    best: Option<(Vec<f32>, f64)>,
}

impl JitterOutcome {
    fn unavailable() -> Self {
        Self {
            violation: None,
            best: None,
        }
    }
    fn violation(x: Vec<f32>, margin: f64) -> Self {
        Self {
            violation: Some(x.clone()),
            best: Some((x, margin)),
        }
    }
    fn best_only(x: Vec<f32>, margin: f64) -> Self {
        Self {
            violation: None,
            best: Some((x, margin)),
        }
    }
}

/// #moat-leak-cora-mnist-set (2026-07-09): true-f64 re-validation of an
/// ORT-f32-confirmed `sat` witness.
///
/// The trusted-oracle gate confirms via ONNX Runtime in **f32** (then decodes
/// those f32 output bits exactly as f64). A witness sitting a few f32-ULPs inside the box at a
/// robustness BOUNDARY (cora `mnist-set`/img0,img20 — unsat but on the knife's
/// edge) can therefore pass as `sat` while the true real-valued property HOLDS: a
/// false counterexample the organizer rejects (`-150`, a 0-wrong-moat break).
///
/// ny's SOUND f64 graph interval forward ([`GraphNetwork::propagate_ibp_f64_cell`])
/// re-evaluates the witness. For a concrete point its Higham-widened enclosure is
/// ~1e-14 wide — far tighter than any real boundary margin — so it cleanly
/// separates a genuine violation from an f32 artifact. Returns `true` (=> DOWNGRADE
/// the `sat` to sound `unknown`) ONLY when the f64 forward proves the property is
/// NOT violated at the witness. Returns `false` (=> keep the ORT verdict) when f64
/// confirms the violation OR the f64 path is unavailable/errors — so conv/graph
/// sats where the f64 cell is unsupported are never regressed.
///
/// SOUNDNESS: this is used ONLY to downgrade `sat`->`unknown` (always sound). A
/// wrong f64 output can at worst forgo a legitimate `+10`; it can NEVER turn
/// `unknown`/`unsat` into `sat`, so it cannot introduce a false verdict — which is
/// why re-loading via ny's graph loader here (the thing the ORT gate otherwise
/// avoids) is safe.
/// Snap witness coordinates that sit within a few ULPs of a DECLARED f64 input
/// bound to that bound verbatim (#witness-snap-declared). Motivation: attack /
/// MIP witnesses inherit the verifier's OUTWARD-rounded box, so a coordinate
/// meant to be exactly 0.0 is emitted as the denormal -1e-45 (and 1.0 as
/// 1.0000001). ONNX Runtime flushes/rounds these to the same forward as the
/// declared value, but the true-f64 gate (#moat-leak-cora-mnist-set) evaluates
/// them literally and rejects razor-thin violations that are EXACT at the true
/// boolean/vertex point (sat_relu: +/-1-weight Gemms are exact integer
/// arithmetic in f64 at 0/1 inputs). Snapping to the declared bound is sound by
/// construction: the declared value is inside the organizer's box by definition,
/// and the snapped witness must INDEPENDENTLY re-pass BOTH the trusted-ORT
/// confirmation and the true-f64 gate before it is emitted.
fn snap_witness_to_declared(spec: &ny_onnx::vnnlib::VnnLibSpec, witness: &str) -> Option<Vec<f64>> {
    let vals = parse_witness_inputs(witness).ok()?;
    if vals.len() != spec.input_bounds.len() {
        return None;
    }
    let within_ulps = |v: f32, b: f32, n: u32| -> bool {
        if v == b {
            return true;
        }
        let mut lo = v.min(b);
        let hi = v.max(b);
        for _ in 0..n {
            lo = next_up_f32(lo);
            if lo >= hi {
                return true;
            }
        }
        false
    };
    let mut snapped = false;
    let out: Vec<f64> = vals
        .iter()
        .zip(spec.input_bounds.iter())
        .map(|(&v, &(lo, hi))| {
            if lo.is_finite() && within_ulps(v, lo as f32, 4) && f32_to_f64_exact(v) != lo {
                snapped = true;
                lo
            } else if hi.is_finite() && within_ulps(v, hi as f32, 4) && f32_to_f64_exact(v) != hi {
                snapped = true;
                hi
            } else {
                f32_to_f64_exact(v)
            }
        })
        .collect();
    snapped.then_some(out)
}

/// Wall cap for one accepted-witness deepening pass (#witness-deepen): the
/// budget is otherwise-dead time (the sat is already secured), but the results
/// file must still be written before the watchdog grace window closes.
const WITNESS_DEEPEN_WALL_CAP: std::time::Duration = std::time::Duration::from_secs(30);

/// Margin-measure + safety window reserved below the scored deadline before a
/// deepening pass may start.
///
/// This covers everything [`deepen_accepted_witness`] still has to do AFTER
/// [`ulp_jitter_falsify`] returns at its own deadline, and an answer produced
/// after the scored budget does not score (the `run_instance.sh` OS backstop
/// sits at budget + 10 s and is NOT usable headroom), so it is sized against
/// the covered work rather than trimmed:
///
/// 1. one bundled-ORT forward at the deepened point — the session is already
///    committed and warm;
/// 2. rendering the witness text;
/// 3. [`confirm_violation_with_ort`], which re-reads and re-decodes the model
///    PROTOBUF on every call (`OrtForward::from_path` ->
///    `read_input_shapes_maybe_gzip`; #ort-session-once caches the committed
///    session, not the byte read), re-parses the property through the
///    #vnnlib-parse-once memo, and runs ORT once;
/// 4. the terminal true-f64 gate: one `propagate_ibp_f64_cell` walk, recorded
///    at 50-200 ms on [`F64MarginOracle`];
/// 5. #witness-exec-match: [`organizer_exec_matched_witness`], one more
///    protobuf read plus one ORT forward on the text that is actually
///    published — and, ONLY when the witness's `Y_j` block misses the
///    reference run, a repair that costs a second
///    [`confirm_violation_with_ort`] and a second true-f64 walk. This item was
///    added after the reserve was sized, so the reserve now covers strictly
///    more work than it was measured against. That is a SCORING risk (an
///    upheld `sat` arriving past the watchdog scores 0 instead of +10), never a
///    soundness one, and it is the direction the exec-match gate exists to buy:
///    a witness the organizer re-runs and rejects is worth less than a witness
///    that arrives a few hundred milliseconds later.
///
/// It no longer has to cover a `load_graph_network` — a full ONNX parse, shape
/// inference and graph conversion of the SAME model this call already loaded
/// for its f64 oracle (#witness-deepen-gate-reuse). The protobuf read in (3) is
/// the remaining item with no bound in this file, which is why the window
/// itself is unchanged: removing the redundant load buys margin inside the
/// reserve, not a smaller reserve.
const WITNESS_DEEPEN_SAFETY: std::time::Duration = std::time::Duration::from_millis(2500);

/// #witness-deepen: strengthen an ACCEPTED `sat` witness before emission.
///
/// The accepted witness passed every gate, but greedy searches return on the
/// FIRST zero-tolerance violation, so accepted margins park at +1e-8 artifact
/// levels — below the measured cross-build ORT divergence (max|dY| = 3.4e-7)
/// and thus fragile under the organizer's independent re-run (see
/// [`witness_deepen_target`]). When the accepted witness's bundled-ORT margin
/// is below target, continue the greedy ULP coordinate ascent from it
/// (deadline-bounded, budgeted by the scored instance deadline) and emit the
/// deepened point ONLY if it independently re-passes BOTH acceptance gates
/// (trusted-ORT zero-tolerance confirm + the true-f64 enclosure gate).
///
/// Returns `Some(deepened_witness)` on success; `None` ⇒ the caller emits the
/// ORIGINAL accepted witness unchanged — a sat is never lost, and no witness
/// is ever emitted on a weaker gate than today (pure strengthening).
fn deepen_accepted_witness(
    onnx: &Path,
    vnnlib: &Path,
    spec: Option<&ny_onnx::vnnlib::VnnLibSpec>,
    witness: &str,
    instance_deadline: Option<std::time::Instant>,
) -> Option<String> {
    let target = witness_deepen_target()?;
    let spec = spec?;
    // No scored deadline ⇒ no measurable dead budget ⇒ keep the original.
    let deadline = instance_deadline?;
    let budget = deadline
        .saturating_duration_since(std::time::Instant::now())
        .checked_sub(WITNESS_DEEPEN_SAFETY)?
        .min(WITNESS_DEEPEN_WALL_CAP);
    if budget < std::time::Duration::from_millis(800) {
        return None;
    }
    let seed = parse_witness_inputs(witness).ok()?;
    let (box_lo, box_hi, emit_pin) = build_search_box(spec)?;
    if seed.len() != box_lo.len() {
        return None;
    }
    let mut forward = ny_onnx::diff::OrtForward::from_path(onnx, box_lo.len()).ok()?;
    let out = forward.run(&seed).ok()?;
    let out64: Vec<f64> = out.iter().map(|&v| f32_to_f64_exact(v)).collect();
    let accepted_margin = property_margin(spec, &seed, &out64);
    if accepted_margin >= target {
        return None; // already robust — nothing to strengthen
    }
    println!(
        "Witness deepen: accepted sat margin {accepted_margin:.3e} < target {target:.1e}; \
         deepening for up to {:.1}s (NY_WITNESS_DEEPEN=0 disables)",
        budget.as_secs_f64()
    );
    let f64_oracle = F64MarginOracle::load(onnx, box_lo.len());
    let outcome = ulp_jitter_falsify(
        &mut forward,
        spec,
        &box_lo,
        &box_hi,
        &emit_pin,
        &seed,
        std::time::Instant::now() + budget,
        f64_oracle.as_ref(),
    );
    let deepened = outcome.violation?;
    let output = forward.run(&deepened).ok()?;
    let text = format_smtlib_witness_f64(&refine_emit_view(&deepened, &emit_pin), &output);
    if text == witness {
        return None;
    }
    // The deepened witness must INDEPENDENTLY re-pass the identical gates the
    // accepted witness passed; anything less keeps the original.
    //
    // #witness-deepen-gate-reuse: the gate walks the SAME graph `f64_oracle`
    // already holds for this `onnx`, so hand it over rather than let the gate
    // load the model a second time inside `WITNESS_DEEPEN_SAFETY`. Bit-identical
    // (see [`F64MarginOracle::reusable_for`]); a `None` oracle, or a witness
    // whose flat length differs from the search box, keeps the loading path.
    (confirm_violation_with_ort(onnx, vnnlib, Some(&text)).unwrap_or(false)
        && !f64_forward_rejects_witness_reusing(onnx, spec, &text, f64_oracle.as_ref()))
    .then(|| {
        println!(
            "Witness deepen: deepened witness re-passed ORT + true-f64 gates; emitting it \
             (original kept as fallback semantics: it had already passed)"
        );
        text
    })
}

/// Engagement counters for #witness-deepen-gate-reuse, incremented by
/// [`f64_forward_rejects_witness_reusing`]: how many times the terminal
/// true-f64 gate walked a graph a caller had ALREADY loaded, and how many times
/// it had to load one itself. Written on the shipped path; read only by the
/// reuse pin below, which asserts the shipped call site takes the fast lane.
static F64_GATE_GRAPH_REUSES: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static F64_GATE_GRAPH_LOADS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

/// `(reuses, loads)` observed so far by the terminal true-f64 gate.
#[cfg(test)]
fn f64_gate_graph_counters() -> (usize, usize) {
    use std::sync::atomic::Ordering::Relaxed;
    (
        F64_GATE_GRAPH_REUSES.load(Relaxed),
        F64_GATE_GRAPH_LOADS.load(Relaxed),
    )
}

fn f64_forward_rejects_witness(
    onnx: &Path,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    witness: &str,
) -> bool {
    f64_forward_rejects_witness_reusing(onnx, spec, witness, None)
}

/// As [`f64_forward_rejects_witness`], but able to walk a graph the caller has
/// ALREADY loaded for the same `onnx` (#witness-deepen-gate-reuse).
///
/// The gate's decision is UNCHANGED: `loaded` only supplies the `GraphNetwork`
/// and declared input shape that the `None` path would otherwise re-derive from
/// the same file, and [`F64MarginOracle::reusable_for`] refuses the pair unless
/// it was resolved at this witness's flat input length — the one input
/// `read_input_shape_maybe_gzip` reads besides the file itself. Every
/// subsequent step, including the `supports_ibp_f64_cell` check, is identical
/// on both paths.
fn f64_forward_rejects_witness_reusing(
    onnx: &Path,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    witness: &str,
    loaded: Option<&F64MarginOracle>,
) -> bool {
    let f64_says_not_violated = || -> Option<bool> {
        // #witness-f64-membership: parse the DECLARED decimals as f64 — the
        // "witness as the organizer parses it" view `property_violated_f64`
        // documents. The old f32 parse shifted pinned non-f32-representable
        // bounds outside their own degenerate [a,a] box, so the membership check
        // inside `property_violation_possible_f64` wrongly rejected genuine
        // violations (collins_rul_cnn_2022).
        let input_f64 = parse_witness_inputs_f64(witness).ok()?;
        let reused = loaded.and_then(|oracle| oracle.reusable_for(input_f64.len()));
        // Same order as the historical path (shape read, then graph build), and
        // still owned for the whole walk, so the fallback's failure modes and
        // memory profile are byte-for-byte what they were.
        let mut owned: Option<(GraphNetwork, Vec<usize>)> = None;
        if reused.is_none() {
            let (_bytes, input_shape) =
                ny_onnx::diff::read_input_shape_maybe_gzip(onnx, input_f64.len()).ok()?;
            owned = Some((load_graph_network(onnx).ok()?, input_shape));
        }
        let (net, input_shape): (&GraphNetwork, &[usize]) = match (reused, owned.as_ref()) {
            (Some(pair), _) => {
                F64_GATE_GRAPH_REUSES.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                println!(
                    "True-f64 gate: walking the graph this instance already loaded \
                     (no second ONNX load inside the deepening reserve)"
                );
                pair
            }
            (None, Some((net, shape))) => {
                F64_GATE_GRAPH_LOADS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                (net, shape.as_slice())
            }
            // `owned` is populated on exactly the branch where `reused` is None,
            // and a failed load has already returned above.
            (None, None) => return None,
        };
        if !net.supports_ibp_f64_cell() {
            return None; // f64 cell unavailable for this net -> do not downgrade
        }
        let input_arr = ArrayD::from_shape_vec(IxDyn(input_shape), input_f64.clone()).ok()?;
        let point = ny_propagate::Interval64::point(input_arr);
        let out = net.propagate_ibp_f64_cell(&point).ok()?;
        // Point input => tight [lower, upper] ENCLOSURE of the true f64 output.
        // #zero-margin-enclosure: decide on the WHOLE enclosure, not the midpoint —
        // an outward-widened interval around an EXACT zero-margin violation
        // (sat_relu boolean witnesses: +/-1-weight integer arithmetic gives Y
        // exactly on the threshold) has midpoint ~+2e-15 and the midpoint test
        // wrongly "proved" not-violated. Reject ONLY when no output vector in the
        // enclosure can violate (per-constraint favorable endpoints) — exactly the
        // documented contract ("downgrade ONLY on a definite f64 not-violated").
        let out_lo: Vec<f64> = out.lower.iter().copied().collect();
        let out_hi: Vec<f64> = out.upper.iter().copied().collect();
        // Verdict-NEUTRAL certification report (#sat-relu-zero-margin). The
        // downgrade decision below is unchanged; this only records when the
        // enclosure is strong enough that EVERY output vector it admits
        // violates — the CE-certificate primitive, and the answer W0.2 recorded
        // as a permanent NO on sat_relu before the f64 cell walk gained its
        // integer-exactness path.
        if property_violation_certain_f64(spec, &input_f64, &out_lo, &out_hi) {
            eprintln!(
                "True-f64 gate: enclosure CERTIFIES the violation (margin_worst {:+.6e}, \
                 max enclosure width {:.3e}) — every conforming implementation the \
                 enclosure covers violates",
                property_margin_f64_worst(spec, &input_f64, &out_lo, &out_hi),
                out_lo
                    .iter()
                    .zip(out_hi.iter())
                    .map(|(l, h)| h - l)
                    .fold(0.0f64, f64::max),
            );
        }
        Some(!property_violation_possible_f64(
            spec, &input_f64, &out_lo, &out_hi,
        ))
    };
    // Downgrade ONLY on a definite f64 "not violated"; None/err => keep (no regress).
    f64_says_not_violated().unwrap_or(false)
}

/// The organizer's exec-match tolerance on a PUBLISHED counterexample's `Y_j`
/// block: the witness is rejected when
/// `max_j |Y_ort - Y_file| / max_j |Y_file| > 1e-3`
/// (`SCORING-ZERO-TOL/counterexamples.py` plus `settings.py:68`).
///
/// Same constant and same shape as `beta_crown::output::ort_confirmed_output`,
/// which is the in-tree implementation of this gate for the STANDALONE `--json`
/// surface. This is deliberately a mirror, not a second scheme.
const COUNTEREXAMPLE_EXEC_MATCH_RTOL: f64 = 1e-3;

/// Outcome of running the organizer's exec-match gate over an ACCEPTED witness
/// (#witness-exec-match).
enum ExecMatchedWitness {
    /// The witness's own `Y_j` block already reproduces the reference runtime
    /// within the organizer's tolerance. Publish the text byte for byte.
    AsWritten,
    /// It does not. `text` re-renders the SAME input decimals with the reference
    /// runtime's own outputs; `detail` says what was wrong. The caller must
    /// re-pass both acceptance gates on `text` before publishing it.
    Repaired { text: String, detail: String },
}

/// Run the organizer's exec-match (`Y`-vs-ONNX-Runtime) check on a witness that
/// has already passed the trusted-oracle property gate (#witness-exec-match).
///
/// WHY THE PROPERTY GATE IS NOT ENOUGH. `confirm_violation_with_ort` evaluates
/// the property at ORT's outputs and then DISCARDS them, emitting the witness
/// text verbatim. On the ordinary competition path that text's `Y_j` lines are
/// ny's INTERNAL forward (`beta_crown::output::counterexample_vnnlib` renders
/// `output_in_original_coordinates` of ny's own evaluation). The organizer never
/// reads our property verdict; it re-executes the model and compares its own
/// outputs against the published ones first. So a row can hold a genuine
/// violation and still have its counterexample thrown out for a `Y` we never
/// checked. The internal-vs-ORT divergence this guards against is measured and
/// real — see `log_internal_vs_ort_divergence`, which reports exactly this
/// quantity but is explicitly informational and runs only on REJECTED witnesses.
///
/// TOLERANCE. The relative test is written as `diff <= RTOL * scale` with
/// `scale = max_j |Y_file|`. When `scale` is zero that demands exact equality,
/// which is STRICTER than the reference's `scale >= 1e-6` bypass. Being stricter
/// is free here and nowhere else: the consequence of a mismatch is a repair
/// rendered from ORT's own outputs, not a lost verdict, so erring toward
/// "repair" costs one already-warm ORT forward and removes a class of witnesses
/// whose acceptance would rest on a degenerate scale.
///
/// `Err` means the check could not be RUN (unparseable inputs, or a session /
/// inference failure). It must never read as a match: the caller fails closed to
/// the sound `unknown`.
fn organizer_exec_matched_witness(onnx: &Path, witness: &str) -> Result<ExecMatchedWitness> {
    let input_f64 = parse_witness_inputs_f64(witness)?;
    // Same split as the organizer and as `confirm_violation_with_ort`: the f64
    // decimals drive membership and the published text, the f32 cast drives the
    // forward. The session comes from the process-global cache (#ort-session-once).
    let input_f32: Vec<f32> = input_f64.iter().map(|&v| v as f32).collect();
    let mut forward = ny_onnx::diff::OrtForward::from_path(onnx, input_f32.len()).map_err(|e| {
        anyhow!(
            "building the exec-match ONNX Runtime session from {}: {e}",
            onnx.display()
        )
    })?;
    let produced = forward
        .run(&input_f32)
        .map_err(|e| anyhow!("exec-match ONNX Runtime inference failed: {e}"))?;
    if produced.is_empty() {
        anyhow::bail!("exec-match ONNX Runtime forward returned no outputs");
    }
    // The repair re-emits `input_f64` UNCHANGED, so every input-only decision
    // (box membership, `property_violated_f64`, the true-f64 enclosure gate)
    // reads exactly the values it read before.
    let repair = |detail: String| ExecMatchedWitness::Repaired {
        text: format_smtlib_witness_f64(&input_f64, &produced),
        detail,
    };
    let Some(claimed) = parse_witness_outputs(witness) else {
        return Ok(repair(
            "the witness carries no contiguous Y_j block".to_string(),
        ));
    };
    if claimed.len() != produced.len() {
        return Ok(repair(format!(
            "the witness declares {} Y_j values, the model produces {}",
            claimed.len(),
            produced.len()
        )));
    }
    let produced64: Vec<f64> = produced.iter().map(|&v| f32_to_f64_exact(v)).collect();
    if !claimed.iter().all(|v| v.is_finite()) || !produced64.iter().all(|v| v.is_finite()) {
        return Ok(repair(
            "the witness or the reference-runtime output is not finite".to_string(),
        ));
    }
    let scale = claimed.iter().fold(0.0_f64, |acc, &v| acc.max(v.abs()));
    let diff = produced64
        .iter()
        .zip(claimed.iter())
        .fold(0.0_f64, |acc, (&p, &c)| acc.max((p - c).abs()));
    if diff <= COUNTEREXAMPLE_EXEC_MATCH_RTOL * scale {
        return Ok(ExecMatchedWitness::AsWritten);
    }
    let rtol = COUNTEREXAMPLE_EXEC_MATCH_RTOL;
    Ok(repair(format!(
        "max|Y_ort - Y_file| = {diff:.6e} against scale {scale:.6e}, over the organizer's \
         {rtol:.0e} relative tolerance"
    )))
}

/// Confirm an internal `sat` against the trusted ONNX-Runtime oracle.
///
/// Returns the original `Sat` ONLY if a real ORT forward on the witness input
/// reproduces a property violation; otherwise returns the sound `Unknown` and logs
/// the reason. Any failure to consult the oracle (no witness, parse failure, model
/// load/inference error, ORT feature disabled) also downgrades to `Unknown` — we
/// never fall back to trusting ny's internal-only forward for a scored `sat`.
///
/// A confirmed witness is additionally re-checked in true f64
/// ([`f64_forward_rejects_witness`], #moat-leak-cora-mnist-set) and downgraded if
/// the f64 forward does not reproduce the violation — closing the razor-thin
/// f32-boundary false-`sat` hole.
fn gate_sat_with_trusted_oracle(
    onnx: &Path,
    vnnlib: &Path,
    witness: Option<&str>,
    instance_deadline: Option<std::time::Instant>,
) -> VnncompResult {
    // #sat-precedence: this whole function is the interval in which a candidate
    // counterexample can become a CONFIRMED one, so hold the adjudication marker
    // across all of it. While it is held the margin-row lane's early exit is
    // refused, which removes the window in which a lane `unsat` could be
    // published microseconds before this gate upholds a `sat` for the same row.
    // Deferring costs the lane only its early-exit latency: its verdict still
    // travels down the channel and is published at the ordinary join.
    let _adjudication = enter_sat_adjudication();
    let downgrade = |reason: String| -> VnncompResult {
        eprintln!(
            "Trusted-oracle gate: internal sat NOT confirmed by ONNX Runtime ({reason}); \
             downgrading to sound unknown"
        );
        VnncompResult::Unknown
    };

    // #moat-leak-cora-mnist-set: load the spec once for the true-f64 witness
    // re-check. `f64_keeps` returns false only when the sound f64 forward proves
    // the witness does NOT violate (razor-thin f32-boundary false CE). Skipped
    // when out of budget so a genuine sat is never lost to the recheck's load cost.
    let spec_f64 = ny_onnx::vnnlib::load_vnnlib(vnnlib).ok();
    let f64_keeps = |w: &str| -> bool {
        if let Some(dl) = instance_deadline {
            // The false-`sat` surfaces NEAR the deadline (in the watchdog's ~5s
            // grace window), so the recheck must run there too — the guard only
            // protects the final ~0.5s before the watchdog kill so the (fast, for
            // the small nets this fires on) recheck can't turn a genuine sat into
            // a lost timeout.
            if std::time::Instant::now().saturating_duration_since(dl)
                > std::time::Duration::from_millis(4500)
            {
                return true; // essentially at the watchdog -> keep the ORT verdict
            }
        }
        match spec_f64.as_ref() {
            Some(spec) => !f64_forward_rejects_witness(onnx, spec, w),
            None => true,
        }
    };

    // #witness-snap-declared: rebuild a boundary witness on the DECLARED f64
    // bounds and accept it only if it independently re-passes BOTH gates.
    let snapped_witness_passes = |w: &str| -> Option<String> {
        let spec = spec_f64.as_ref()?;
        let snapped = snap_witness_to_declared(spec, w)?;
        // Snapping changes the emitted input decimals. Re-run the ORIGINAL
        // model at that exact input view before publication; an input-only
        // witness would otherwise erase a traffic peel's repaired `Y_j`
        // coordinates when `uphold_sat` keeps the snapped candidate unchanged.
        let input_only = format_smtlib_witness_f64(&snapped, &[]);
        let text = rehydrate_original_witness_outputs(onnx, &input_only).ok()?;
        (confirm_violation_with_ort(onnx, vnnlib, Some(&text)).unwrap_or(false) && f64_keeps(&text))
            .then_some(text)
    };
    // #witness-deepen: every 'sat upheld' return funnels through here. When the
    // accepted witness's bundled-ORT margin is below target, spend the leftover
    // scored budget strengthening it; the deepened witness replaces the
    // accepted one ONLY after re-passing the identical gates, else the
    // accepted witness is emitted unchanged (a sat is never lost).
    //
    // #witness-exec-match — THE SECOND DEFECT THIS FUNNEL CLOSES. Every witness
    // that arrives here has had its PROPERTY validated at ONNX Runtime's
    // outputs by `confirm_violation_with_ort`. That is not the same as having
    // validated the `Y_j` block the witness PUBLISHES: on the ordinary path
    // those decimals are ny's own internal forward, straight out of
    // `beta_crown::output::counterexample_vnnlib`. The organizer re-executes the
    // model itself and REJECTS a counterexample whose published `Y` misses its
    // own run by more than `COUNTEREXAMPLE_EXEC_MATCH_RTOL`, so an unvalidated
    // `Y` is the one axis on which we are LOOSER than the organizer — and it is
    // the axis that scores a rejection rather than +10.
    //
    // The standalone `--json` surface has enforced this since
    // `beta_crown::output::ort_confirmed_output` landed, but it runs only under
    // `if !is_capturing()`, and the scored `ny vnncomp v1` path is capturing by
    // construction (`begin_capture` wraps `invoke_beta_crown`). So the gate was
    // absent from exactly the path that is scored. It now runs here, on the
    // witness text that is actually published, AFTER deepening.
    //
    // A mismatch is REPAIRED rather than refused: re-rendering `Y` from the same
    // ORT forward the organizer will run costs nothing and cannot change the
    // property decision, because the repair re-emits the identical input
    // decimals (`f64` `Display` is the shortest round-tripping decimal, so
    // `parse_witness_inputs_f64` recovers the same values bit for bit) and both
    // acceptance gates read the inputs only. The repair is then re-run through
    // BOTH gates anyway, and anything short of a clean pass FAILS CLOSED to the
    // sound `unknown` — an unverifiable `sat` is never worth the risk.
    let uphold_sat = |w: String| -> VnncompResult {
        // #sat-precedence: reaching here means ONNX Runtime reproduced the
        // violation at this witness and the true-f64 enclosure re-check did not
        // refute it — all four call sites of this closure sit behind exactly
        // those two conditions. So this instance holds a constructive,
        // reference-runtime-checked counterexample. Latch it BEFORE the
        // publication work below, so that
        // even a downgrade caused by an unverifiable `Y` block still bars every
        // lane from publishing a contradicting `unsat`: the outward choice there
        // is the 0-point `unknown`, not a bound-based verdict we have positive
        // evidence against.
        note_confirmed_sat();
        let witness =
            deepen_accepted_witness(onnx, vnnlib, spec_f64.as_ref(), &w, instance_deadline)
                .unwrap_or(w);
        // Bound to a `let` first: a `&witness` borrow written directly into a
        // match scrutinee lives to the end of the match, which would forbid
        // moving `witness` out in the `AsWritten` arm.
        let exec_match = organizer_exec_matched_witness(onnx, &witness);
        let publishable = match exec_match {
            Ok(ExecMatchedWitness::AsWritten) => witness,
            Ok(ExecMatchedWitness::Repaired { text, detail }) => {
                eprintln!(
                    "Exec-match gate: the accepted witness's Y_j block does NOT reproduce the \
                     reference runtime ({detail}); re-rendering Y from the ORT forward and \
                     re-running both acceptance gates on the result"
                );
                if !(confirm_violation_with_ort(onnx, vnnlib, Some(&text)).unwrap_or(false)
                    && f64_keeps(&text))
                {
                    return downgrade(
                        "the witness Y_j block would fail the organizer's exec-match check and \
                         the ORT-rendered repair does not re-pass the acceptance gates"
                            .into(),
                    );
                }
                println!(
                    "Exec-match gate: ORT-rendered witness re-passes ORT + true-f64 (sat upheld \
                     with the reference runtime's own Y)"
                );
                text
            }
            Err(error) => {
                return downgrade(format!(
                    "the organizer's exec-match (Y-vs-ORT) check could not be RUN ({error}); \
                     refusing to publish a counterexample we cannot validate the way the \
                     organizer will"
                ));
            }
        };
        VnncompResult::Sat {
            witness: Some(publishable),
        }
    };
    match confirm_violation_with_ort(onnx, vnnlib, witness) {
        Ok(true) => match witness {
            Some(w) if !f64_keeps(w) => match snapped_witness_passes(w) {
                Some(text) => {
                    println!(
                        "Trusted-oracle gate: declared-bound-snapped witness re-passes \
                         ORT + true-f64 (sat upheld)"
                    );
                    uphold_sat(text)
                }
                None => downgrade(
                    "true-f64 forward does not reproduce the ORT witness violation \
                     (razor-thin f32-boundary counterexample)"
                        .into(),
                ),
            },
            Some(w) => {
                println!(
                    "Trusted-oracle gate: ONNX Runtime confirms the counterexample (sat upheld)"
                );
                uphold_sat(w.to_string())
            }
            // UNREACHABLE, and now fails closed rather than relying on that.
            // `confirm_violation_with_ort` opens with
            // `witness.ok_or_else(...)?`, so `Ok(true)` implies `witness` was
            // `Some`; there is exactly one definition of that function in the
            // tree. A witness-less `sat` could not be exec-matched at all — the
            // organizer has nothing to re-execute — so if this arm ever becomes
            // reachable it must publish the sound `unknown`, not an
            // uncheckable `sat`.
            None => downgrade(
                "ONNX Runtime reported a violation for a sat that carries no witness, so \
                 there is no counterexample for the organizer to re-execute"
                    .into(),
            ),
        },
        // ny's own witness is a BOUNDARY point that ORT scores as SAFE at zero-tol. A
        // genuine violation often sits just inside the box near it; run a bounded
        // ORT-guided local search seeded from ny's witness for a robustly-violating
        // point that ORT confirms. Sound by construction: a genuinely-holding property
        // has NO violating point, so the search finds nothing and we still downgrade.
        Ok(false) => {
            // #postbab-apgd diagnostic (log-only, one extra ORT forward): quantify the
            // internal-forward vs ORT divergence at the rejected witness — the witness
            // carries the Y_j values ny's INTERNAL forward computed, so comparing them
            // to the real ORT forward at the same X separates "representation near-miss"
            // from "internal forward diverges" (soundnessbench model_5 class).
            if let Some(w) = witness {
                log_internal_vs_ort_divergence(onnx, w);
            }
            match refine_witness_with_ort(onnx, vnnlib, witness, instance_deadline) {
                Some(refined) if !f64_keeps(&refined) => match snapped_witness_passes(&refined) {
                    Some(text) => {
                        println!(
                            "Trusted-oracle gate: declared-bound-snapped refined witness \
                         re-passes ORT + true-f64 (sat upheld)"
                        );
                        uphold_sat(text)
                    }
                    None => downgrade(
                        "true-f64 forward does not reproduce the refined witness violation \
                     (razor-thin f32-boundary counterexample)"
                            .into(),
                    ),
                },
                Some(refined) => {
                    println!(
                        "ORT-guided refinement: recovered an ONNX-Runtime-confirmed \
                         counterexample near the boundary (sat upheld)"
                    );
                    uphold_sat(refined)
                }
                None => downgrade(
                    "ORT forward on the witness input is SAFE and bounded refinement \
                     found no confirmed violation (false counterexample)"
                        .into(),
                ),
            }
        }
        Err(err) => downgrade(err.to_string()),
    }
}

/// Maximum number of ORT forward evaluations a single refinement search may spend.
/// Sized so the search adds at most a small fraction of a per-instance timeout even
/// at the slowest ORT forward latencies we see.
const REFINE_MAX_ORT_EVALS: usize = 400;

/// Wall-clock cap for one refinement search; the loop also stops at this budget so a
/// slow model can never let the search blow the scored per-instance timeout.
const REFINE_WALL_BUDGET: std::time::Duration = std::time::Duration::from_secs(2);

/// Number of deterministic random restart seeds drawn from the box (in addition to
/// ny's own clamped witness) that seed the candidate pool.
const REFINE_RANDOM_SEEDS: usize = 8;

// --- Stage-2 escalation: gradient-guided PGD refinement (attack-side only). ---
//
// The derivative-free stage-1 hill-climb is hopeless on wide, high-dimensional
// input boxes (metaroom: a 3x32x56 image box with ~159 non-degenerate dims and
// widths up to ~0.5 — random coordinate perturbations essentially never find the
// thin violating region that gradient PGD walks straight into). When stage 1
// fails, the internal `sat` would be downgraded to `unknown`, i.e. the instance
// is LOST — so a bigger, gradient-guided budget is free EV as long as it respects
// the scored deadline. Kill-switch: `NY_ORT_REFINE_GRAD=0` (batteries-included
// default ON, disable-flag per the repo convention).

/// Hard wall-clock cap for one gradient-guided refinement.
const GRAD_REFINE_WALL_CAP: std::time::Duration = std::time::Duration::from_secs(30);

/// Fraction of the REMAINING scored instance budget the gradient stage may take
/// (the cap above still applies).
const GRAD_REFINE_BUDGET_FRACTION: f64 = 0.20;

/// Time reserved below the scored deadline for the final confirming forward and
/// the RESULTS_FILE write (the watchdog fires at deadline + 5s grace).
const GRAD_REFINE_SAFETY_MARGIN: std::time::Duration = std::time::Duration::from_secs(3);

/// Below this budget the gradient stage is not worth starting (a single ny CPU
/// gradient on a conv net costs ~50-200ms; a handful of steps achieve nothing).
const GRAD_REFINE_MIN_BUDGET: std::time::Duration = std::time::Duration::from_millis(500);

/// PGD steps per restart before moving to the next seed.
const GRAD_REFINE_MAX_STEPS_PER_RESTART: usize = 120;

/// Hard cap on restarts (the wall budget is the real limiter; this only guards a
/// degenerate spin where every restart dies after one step).
const GRAD_REFINE_MAX_RESTARTS: usize = 64;

/// Compute the stage-2 wall budget from the remaining scored instance budget.
///
/// `None` remaining (no deadline known — e.g. a caller without the vnncomp
/// protocol deadline) falls back to the fixed cap. Returns `None` when there is
/// not enough usable time to bother starting the stage.
fn grad_refine_budget(remaining: Option<std::time::Duration>) -> Option<std::time::Duration> {
    let budget = match remaining {
        Some(rem) => rem
            .checked_sub(GRAD_REFINE_SAFETY_MARGIN)?
            .mul_f64(GRAD_REFINE_BUDGET_FRACTION)
            .min(GRAD_REFINE_WALL_CAP),
        None => GRAD_REFINE_WALL_CAP,
    };
    (budget >= GRAD_REFINE_MIN_BUDGET).then_some(budget)
}

/// Build the inward-rounded f32 search box + per-dim emit view for a spec.
///
/// Shared by the stage-2 witness-refinement lane ([`refine_witness_with_ort`])
/// and the upfront falsification lane ([`try_upfront_falsify`]). See the extensive
/// #metaroom-degenerate-dims rationale on the refinement caller: each declared f64
/// bound is rounded INWARD to an f32 that provably lies inside the declared f64
/// interval (lower up, upper down), degenerate (`l == u`) and sub-ULP dims are
/// pinned and emitted verbatim as their declared f64 value. Returns `None` on an
/// empty / inverted / unsamplable box (the caller falls back to no refinement).
fn build_search_box(
    spec: &ny_onnx::vnnlib::VnnLibSpec,
) -> Option<(Vec<f32>, Vec<f32>, Vec<Option<f64>>)> {
    let dims = spec.input_bounds.len();
    let mut box_lo: Vec<f32> = Vec::with_capacity(dims);
    let mut box_hi: Vec<f32> = Vec::with_capacity(dims);
    let mut emit_pin: Vec<Option<f64>> = Vec::with_capacity(dims);
    for &(l, u) in &spec.input_bounds {
        if !(l.is_finite() && u.is_finite()) {
            // Unbounded faces keep the legacy finite-extreme sampling bounds.
            let lo32 = clamp_finite_inward(l, true);
            let hi32 = clamp_finite_inward(u, false);
            if lo32 > hi32 {
                return None;
            }
            box_lo.push(lo32);
            box_hi.push(hi32);
            emit_pin.push(None);
        } else if l == u {
            box_lo.push(l as f32);
            box_hi.push(l as f32);
            emit_pin.push(Some(l));
        } else if l < u {
            let lo32 = clamp_finite_inward(l, true);
            let hi32 = clamp_finite_inward(u, false);
            if lo32 <= hi32 {
                box_lo.push(lo32);
                box_hi.push(hi32);
                emit_pin.push(None);
            } else {
                // Sub-ULP interval: pin at the f64 midpoint (inside [l, u]).
                let m = l + 0.5 * (u - l);
                box_lo.push(m as f32);
                box_hi.push(m as f32);
                emit_pin.push(Some(m));
            }
        } else {
            // Inverted declared bound: unsatisfiable input box.
            return None;
        }
    }
    if box_lo.is_empty() {
        return None;
    }
    Some((box_lo, box_hi, emit_pin))
}

// --- Upfront falsification lane (#upfront-apgd, attack-side, soundness-safe). ---
//
// The internal verifier's counterexample search is SPSA-based (a single random
// finite-difference direction per step): on a high-dimensional conv ResNet that
// is far too noisy a descent direction to walk into the thin eps=0.0039 violating
// region, so genuine `sat` instances that AutoAttack/α,β-CROWN find with exact
// gradients are MISSED and downgraded to `unknown`. This lane runs FIRST, spending
// a bounded slice of the scored budget on the exact-gradient DLR-APGD search
// ([`gradient_guided_falsify`]) before the (weaker-attack, slower) BaB verifier.
// A hit short-circuits to a fast, ORT-confirmed `sat`; a miss cedes the remaining
// budget to BaB. Kill-switch: `NY_UPFRONT_ATTACK=0` (batteries-included default
// ON, disable-flag per the repo convention).
//
// SOUNDNESS: identical to the stage-2 refinement — the ONLY acceptance is the
// trusted ORT forward + zero-tolerance `property_violated_f64` gate, and the
// emitted witness is additionally routed through `gate_sat_with_trusted_oracle`
// (ORT re-confirm + true-f64 re-check). A stronger search can only surface a REAL
// in-box violation; it can never manufacture a false `sat`.

/// Is `onnx` a binarized (BNN) net — i.e. does it contain a `Sign` node?
///
/// Memoized per path exactly like [`net_supports_attack_gradients`], so the
/// probe's ONNX load is paid once per process. Fails CLOSED (`false` ⇒ the
/// historical non-BNN policy) on any load error, so a probe failure can never
/// change behaviour on a net we cannot classify.
///
/// This is the scoping predicate for the BNN attack-budget policy below. It is
/// NON-certified: it selects how much wall-clock the ATTACK lane may use.
/// Acceptance is always the unchanged `gate_sat_with_trusted_oracle`.
fn net_is_sign_network(onnx: &Path) -> bool {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};
    static CACHE: OnceLock<Mutex<HashMap<PathBuf, bool>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    // A poisoned mutex must not change the policy: fall back to the non-BNN path.
    let mut guard = match cache.lock() {
        Ok(g) => g,
        Err(_) => return false,
    };
    if let Some(&hit) = guard.get(onnx) {
        return hit;
    }
    let is_sign = load_graph_network(onnx).is_ok_and(|graph| graph.has_sign_layer());
    guard.insert(onnx.to_path_buf(), is_sign);
    is_sign
}

// Fraction of the scored instance budget the upfront attack may take ON A
// BINARIZED (Sign) NET, and its wall cap.
//
// #bnn-attack-budget. On a `Sign` net the ordinary 8 s / 4 s caps are exactly
// backwards. `Sign` is piecewise constant, so BaB makes no progress — before
// the surrogate-gradient attack existed ny scored **0/45** on
// `traffic_signs_recognition_2023`, every instance a timeout. Every point on
// such a benchmark comes from falsification, so time ceded to BaB is time
// thrown away.
//
// The hard-tail instances need a LOT of attack steps: the external
// `bnn_falsifier` prototype cracks net-2 `idx_10645_eps_1` only at iteration
// ~101 of a β 2→20 ramp, and in ny each step costs a full smooth-Sign forward.
// Measured on that instance at a 240 s budget: with the historical 4 s
// disjunction cap the lane got **9 gradient steps** and timed out; with a
// 150 s cap it reached **325 steps across 3 restarts and emitted a sound `sat`**
// (ORT-confirmed, independently re-validated strictly in-box).
//
// So on a Sign net take half the remaining budget, capped at 240 s. The
// governed `NY_BNN_ATTACK_FRAC` / `NY_BNN_ATTACK_CAP` overrides are resolved
// once into [`UpfrontAttackPolicy`] from the same entry-time [`ny_levers::LeverSet`]
// that produces the flight receipt. NON-certified: this only decides how long
// a NON-certified ascent runs; every candidate it produces is still checked by
// the UNCHANGED trusted-oracle gate.

/// Time reserved below the scored deadline for the confirming ORT re-check.
const UPFRONT_ATTACK_SAFETY_MARGIN: std::time::Duration = std::time::Duration::from_secs(3);

/// Below this the upfront attack is not worth starting.
const UPFRONT_ATTACK_MIN_BUDGET: std::time::Duration = std::time::Duration::from_millis(800);

/// Maximum input dimension for the typed relational-conjunction route.
///
/// ACAS Xu has five inputs. Keeping this structural ceiling here prevents a
/// category-level opt-in from turning the outer attack into a blanket lane for
/// image-sized conjunctions.
const UPFRONT_RELATIONAL_MAX_INPUT_DIMS: usize = 5;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UpfrontAttackAdmission {
    Forced,
    AutoDisjunction,
    PresetRelationalConjunction,
}

impl UpfrontAttackAdmission {
    const fn stable_token(self) -> &'static str {
        match self {
            Self::Forced => "forced",
            Self::AutoDisjunction => "auto_disjunction",
            Self::PresetRelationalConjunction => "preset_relational_conjunction",
        }
    }
}

/// Narrow structural predicate for the typed ACAS prop_2 route.
///
/// After normalizing `Y_i >= Y_j` to `Y_j <= Y_i`, every comparison must share
/// one right-hand reference output. This admits ACAS prop_2's
/// `Y_1..Y_4 <= Y_0` unsafe conjunction without charging the same bounded attack
/// to the mirror-shaped prop_3/prop_4 conjunctions (`Y_0 <= Y_1..Y_4`), which
/// are already fully solved by the proof path.
///
/// Constant thresholds, an `or` around one conjunction, dual-network
/// properties, and input dimensions above the ACAS-sized ceiling remain
/// ineligible.
fn is_low_dim_common_rhs_relational_conjunction(spec: &ny_onnx::vnnlib::VnnLibSpec) -> bool {
    use ny_onnx::vnnlib::OutputConstraint as OC;

    if spec.is_disjunction
        || spec.dual_network.is_some()
        || spec.num_inputs == 0
        || spec.num_inputs != spec.input_bounds.len()
        || spec.num_inputs > UPFRONT_RELATIONAL_MAX_INPUT_DIMS
        || spec.output_constraint_clauses.len() != 1
    {
        return false;
    }
    let clause = &spec.output_constraint_clauses[0];
    let normalized_pair = |constraint: &OC| match constraint {
        OC::LessEq(lhs, rhs) | OC::LessThan(lhs, rhs) => Some((*lhs, *rhs)),
        OC::GreaterEq(lhs, rhs) | OC::GreaterThan(lhs, rhs) => Some((*rhs, *lhs)),
        _ => None,
    };
    let Some((first_lhs, common_rhs)) = clause.first().and_then(normalized_pair) else {
        return false;
    };
    clause.len() >= 2
        && first_lhs != common_rhs
        && clause.iter().all(|constraint| {
            normalized_pair(constraint).is_some_and(|(lhs, rhs)| lhs != rhs && rhs == common_rhs)
        })
}

/// Select why a parsed property may enter the outer exact-gradient lane.
///
/// Keeping the reason typed matters for scheduling: existing automatic
/// multi-clause disjunctions retain their tighter wall cap even in a preset
/// that also opts into relational conjunctions.
///
/// #ml4acopf-upfront-single: the same holds under the TYPED force
/// (`attack.upfront_attack: true`). That key exists to WIDEN admission to the
/// single-clause shapes the automatic rule skips (safenlp's `Y_0 <= Y_1`,
/// ml4acopf's `Y_2382 >= 0.99` thermal-limit threshold); it must not also
/// un-clamp the multi-clause disjunctions the automatic rule already admits,
/// or arming a category for its single-clause rows silently moves every one
/// of its multi-clause rows from the automatic cap to the ordinary cap. So a
/// multi-clause disjunction under the preset force keeps
/// [`UpfrontAttackAdmission::AutoDisjunction`] (same budget class, same loss
/// ensemble, byte-identical to the unarmed category). The ENVIRONMENT force
/// (`NY_UPFRONT_ATTACK=1`, a developer override no scored run exports) keeps
/// its historical "force everything under the ordinary cap" meaning.
fn upfront_attack_admission(
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    wrapper_route: UpfrontWrapperRoute,
) -> Option<UpfrontAttackAdmission> {
    if !wrapper_route.attack_enabled() {
        return None;
    }
    let multi_clause_disjunction = spec.is_disjunction && spec.output_constraint_clauses.len() > 1;
    if multi_clause_disjunction && matches!(wrapper_route, UpfrontWrapperRoute::ForcedByPreset) {
        return Some(UpfrontAttackAdmission::AutoDisjunction);
    }
    if wrapper_route.forced() {
        return Some(UpfrontAttackAdmission::Forced);
    }
    if multi_clause_disjunction {
        return Some(UpfrontAttackAdmission::AutoDisjunction);
    }
    (wrapper_route.preset_relational_conjunction()
        && is_low_dim_common_rhs_relational_conjunction(spec))
    .then_some(UpfrontAttackAdmission::PresetRelationalConjunction)
}

/// Whether the WHOLE property is one constant threshold on one output
/// (`Y_i >= c`, `Y_i > c`, `Y_i <= c` or `Y_i < c`) — ml4acopf's prop2
/// `(assert (>= Y_2382 0.99))` shape.
///
/// Exactly one constraint in total: a single clause holding a single constant
/// comparison (or, for a programmatically built spec with no clause list, a
/// flat list of one). Dual-network properties are excluded. This decides only
/// the NON-certified ascent direction (see [`upfront_attack_loss_schedule`]);
/// acceptance is the unchanged ORT + zero-tolerance predicate.
fn is_single_output_threshold_objective(spec: &ny_onnx::vnnlib::VnnLibSpec) -> bool {
    use ny_onnx::vnnlib::OutputConstraint as OC;

    if spec.dual_network.is_some() {
        return false;
    }
    let only = match spec.output_constraint_clauses.as_slice() {
        [] => match spec.output_constraints.as_slice() {
            [only] => only,
            _ => return false,
        },
        [clause] => match clause.as_slice() {
            [only] => only,
            _ => return false,
        },
        _ => return false,
    };
    matches!(
        only,
        OC::LessEqConst(..)
            | OC::GreaterEqConst(..)
            | OC::LessThanConst(..)
            | OC::GreaterThanConst(..)
    )
}

/// Loss schedule for the upfront lane's exact-gradient restarts
/// (#ml4acopf-upfront-single).
///
/// DLR is ill-posed on a single-output constant threshold. Its denominator
/// `D = z_π1 − z_π3` is the spread between the largest and 3rd-largest of ALL
/// outputs (3804 of them on 300_ieee, none of which the property reads).
/// [`dlr_grad_row`] is the EXACT gradient of `margin / D` (its correction uses
/// `margin`, whose gradient is `m` whatever the constant offset), so the defect
/// is the objective, not the arithmetic: with `margin < 0` the loss rises
/// toward 0 just as well by WIDENING `D` as by moving the constrained output.
/// The π1/π3 entries carry weight `|margin| / D²` against the constrained
/// output's `1 / D`, a ratio of `|margin| / D`, so whenever `|margin|` is large
/// against that spread — measured `margin ≈ −9.8e3` at the box centre of
/// 300_ieee prop2 — the DLR restarts ascend `Y_π1 − Y_π3`, two outputs the
/// property never mentions. alpha-beta-CROWN's ml4acopf attack (50 restarts,
/// `pgd_order: before`) uses the hinge `C·y − rhs` instead, which below the
/// threshold IS this lane's raw margin. A FORCED admission of that shape
/// (the typed `attack.upfront_attack: true` force AND the developer
/// `NY_UPFRONT_ATTACK=1` override alike) therefore ascends the margin on every
/// restart; every other admission keeps the historical ensemble byte-for-byte
/// (AutoDisjunction and the relational route never admit a single constant
/// threshold, and `gradient_guided_falsify`'s other callers pass the ensemble
/// explicitly).
fn upfront_attack_loss_schedule(
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    admission: UpfrontAttackAdmission,
) -> AttackLossSchedule {
    if matches!(admission, UpfrontAttackAdmission::Forced)
        && is_single_output_threshold_objective(spec)
    {
        AttackLossSchedule::MarginOnly
    } else {
        AttackLossSchedule::MarginDlrEnsemble
    }
}

/// The cap TODAY'S rules would give the upfront lane, computed WITHOUT running it.
///
/// An exact mirror of the branch inside [`try_upfront_falsify`]: same admission
/// test on the same parsed spec, same `Sign`-net exception, same auto-disjunction
/// clamp, same helpers. It exists so the Layer-A allocator can size its pool from
/// what today would spend. The shared pure decision helper keeps this sizing path
/// and the live lane identical without moving any work onto the disarmed arm.
///
/// `remaining` is the budget PREDICTED to be left when this lane starts, i.e.
/// after the lanes ahead of it spend their full caps. That is an UNDER-estimate
/// whenever an upstream lane declines early, and under-estimating is the safe
/// direction: it can only make the allocator's pool smaller, which can only
/// leave MORE for the branch-and-bound residual claimant.
#[cfg(feature = "mip")]
fn upfront_today_cap(
    onnx: &Path,
    vnnlib: &Path,
    remaining: Option<std::time::Duration>,
    wrapper_route: UpfrontWrapperRoute,
    policy: &UpfrontAttackPolicy,
) -> Option<UpfrontBudgetDecision> {
    if !wrapper_route.attack_enabled() {
        return None;
    }
    let spec = ny_onnx::vnnlib::load_vnnlib(vnnlib).ok()?;
    let admission = upfront_attack_admission(&spec, wrapper_route)?;
    let base = upfront_attack_base_budget(remaining, policy)?;
    if base.budget < UPFRONT_ATTACK_MIN_BUDGET {
        return None;
    }
    let decision = upfront_effective_budget_decision(
        base,
        remaining,
        policy,
        admission,
        net_is_sign_network(onnx),
    );
    (decision.budget >= UPFRONT_ATTACK_MIN_BUDGET).then_some(decision)
}

/// The in-box objective probe: the property margin over a real ONNX Runtime
/// forward on the model as loaded, at 33 deterministic in-box points.
///
/// This is the ONE per-instance structural fact Layer A measures, and it is
/// measured rather than assumed: `ObjectiveQuality` has been a type in the tree
/// for months with its single caller hard-coding `Informative`.
///
/// WHOSE OBJECTIVE THIS IS, precisely, because the answer decides which lanes it
/// may zero. It is the POST-TERMINAL-OP property margin, the function the
/// trusted gate is written against. It is NOT the objective either BNN lane
/// uses: `SignSpaceProblem::assemble` strips a terminal Softmax (monotone, so it
/// cannot change the argmax) and both the LP walk and STE-PGD steer on the
/// pre-Softmax integer logit margin.
///
/// AND IT IS NOT ALWAYS THE UPFRONT LANE'S OBJECTIVE EITHER. That lane steers on
/// this margin only when it takes the exact-gradient recipe; on a `Sign` net it
/// differentiates a smooth surrogate instead, and its corner/face-grid sub-lanes
/// do not differentiate anything. So this verdict is not applied to that lane
/// directly — it is narrowed by [`upfront_lane_shape`] first. See
/// `lane_allocation::UpfrontLaneShape` for the five measured rows that forced
/// the narrowing.
///
/// Fails toward "not flat" on every uncertainty — an unparseable property, an
/// unbuildable box, an unavailable ORT session, a non-finite margin, or a probe
/// that ran out of wall before [`OBJECTIVE_PROBE_MIN_POINTS`] points. A `Flat`
/// verdict takes a lane to zero seconds, so it must never rest on an absence.
#[cfg(feature = "mip")]
fn probe_flat_objective_tier(onnx: &Path, vnnlib: &Path) -> bool {
    use crate::commands::lane_allocation::{
        probe_objective, probe_points, OBJECTIVE_PROBE_POINTS, OBJECTIVE_PROBE_WALL,
    };
    let Ok(spec) = ny_onnx::vnnlib::load_vnnlib(vnnlib) else {
        return false;
    };
    let Some((box_lo, box_hi, _emit_pin)) = build_search_box(&spec) else {
        return false;
    };
    let Ok(mut forward) = ny_onnx::diff::OrtForward::from_path(onnx, box_lo.len()) else {
        return false;
    };
    let points = probe_points(&box_lo, &box_hi, OBJECTIVE_PROBE_POINTS);
    let started = std::time::Instant::now();
    let probe = probe_objective(&points, OBJECTIVE_PROBE_WALL, started, |point| {
        let outputs = forward.run(point).ok()?;
        let outputs64: Vec<f64> = outputs.iter().map(|&v| f32_to_f64_exact(v)).collect();
        Some(property_margin(&spec, point, &outputs64))
    });
    match probe {
        Some(probe) => {
            eprintln!(
                "Lane allocation: objective probe took {} in-box points, {} distinct f32 \
                 value(s), tier={} [{:.3}s]",
                probe.points,
                probe.distinct_values,
                if probe.is_flat() {
                    "FLAT"
                } else {
                    "informative"
                },
                started.elapsed().as_secs_f64(),
            );
            probe.is_flat()
        }
        None => {
            eprintln!(
                "Lane allocation: objective probe INCONCLUSIVE (unevaluable or non-finite \
                 margin); no lane is zeroed"
            );
            false
        }
    }
}

/// The two structural facts that decide whether a FLAT probe verdict is
/// EVIDENCE ABOUT the upfront lane on this instance.
///
/// See [`crate::commands::lane_allocation::UpfrontLaneShape`] for the measured
/// case that forced this narrowing. Both facts are read from the same helpers
/// the lane itself uses, so they cannot drift from it:
///
/// * `steers_on_a_surrogate_objective` — [`net_is_sign_network`], the exact
///   predicate `try_upfront_falsify` and
///   `gradient_guided_falsify_with_schedule` use to switch the ascent
///   direction to the smooth-`Sign`/STE surrogate, plus
///   [`pre_softmax_attack_objective_armed`], which rewrites the objective on the
///   general route.
/// * `enumerates_points` — [`low_dim_corner_seeds`] non-empty (the corner sweep
///   admits) or [`UpfrontAttackAdmission::PresetRelationalConjunction`] (the
///   relational face grid admits), evaluated on THIS instance's box.
///
/// Fails toward "the verdict does not apply" on every uncertainty, which is the
/// direction that keeps a lane running: this function's `true`s are what remove
/// a lane, and removing a lane costs the rows that lane wins.
#[cfg(feature = "mip")]
fn upfront_lane_shape(
    onnx: &Path,
    vnnlib: &Path,
    wrapper_route: UpfrontWrapperRoute,
) -> crate::commands::lane_allocation::UpfrontLaneShape {
    use crate::commands::lane_allocation::UpfrontLaneShape;
    /// Every uncertainty resolves here: no zero may be drawn.
    const UNKNOWN: UpfrontLaneShape = UpfrontLaneShape {
        steers_on_a_surrogate_objective: true,
        enumerates_points: true,
    };
    let Ok(spec) = ny_onnx::vnnlib::load_vnnlib(vnnlib) else {
        return UNKNOWN;
    };
    let Some(admission) = upfront_attack_admission(&spec, wrapper_route) else {
        return UNKNOWN;
    };
    let enumerates_points = matches!(
        admission,
        UpfrontAttackAdmission::PresetRelationalConjunction
    ) || match build_search_box(&spec) {
        Some((box_lo, box_hi, _)) => !low_dim_corner_seeds(&box_lo, &box_hi).is_empty(),
        None => true,
    };
    UpfrontLaneShape {
        steers_on_a_surrogate_objective: net_is_sign_network(onnx)
            || pre_softmax_attack_objective_armed(),
        enumerates_points,
    }
}

/// Today's three private lane windows plus the exact policy lineage of the
/// upfront window before a frame or knapsack commits it.
#[cfg(feature = "mip")]
#[derive(Debug, Clone, Copy)]
struct TodayAttackSlice {
    slices: crate::commands::lane_allocation::TodaySlices,
    upfront_decision: Option<UpfrontBudgetDecision>,
}

/// A committed attack-slice plan with any exact upstream budget binding that
/// survived commitment.
///
/// The allocation module intentionally knows nothing about VNN-COMP's private
/// CAP/FRAC/AUTO policy. This local wrapper keeps that policy evidence beside
/// the generic plan, but only a fixed frame preserves the exact `Duration` it
/// was given. The knapsack floors its sole positive upfront rung to whole
/// seconds, so it can erase a treatment effect (for example, both 1.2 s and
/// 1.8 s become 1 s); its provenance therefore cannot prove T1 engagement.
/// Structural zeroes and lossy knapsack caps carry no numeric credit.
struct CommittedAttackSlice {
    allocation: crate::commands::lane_allocation::AttackSliceAllocation,
    upfront_decision: Option<UpfrontBudgetDecision>,
}

impl CommittedAttackSlice {
    #[cfg(feature = "mip")]
    fn from_today(
        allocation: crate::commands::lane_allocation::AttackSliceAllocation,
        upfront_decision: Option<UpfrontBudgetDecision>,
    ) -> Self {
        use crate::commands::lane_allocation::{AllocatedLane, AllocationAuthority, LaneWindow};

        let upfront_decision = match (
            allocation.authority(),
            allocation.window(AllocatedLane::UpfrontAttack),
            upfront_decision,
        ) {
            (AllocationAuthority::Frame, LaneWindow::Cap(cap), Some(decision))
                if cap == decision.budget =>
            {
                Some(decision)
            }
            _ => None,
        };
        Self {
            allocation,
            upfront_decision,
        }
    }

    fn allocation(&self) -> &crate::commands::lane_allocation::AttackSliceAllocation {
        &self.allocation
    }

    fn upfront_decision(&self) -> Option<UpfrontBudgetDecision> {
        self.upfront_decision
    }
}

/// TODAY'S SLICES, from TODAY'S HELPERS, in TODAY'S ORDER.
///
/// `lp_lane_plan` and `ste_lane_plan` are the very functions the unallocated
/// lanes call, and `upfront_today_cap` is an exact mirror of that lane's own
/// branch, so nothing derived from this can drift from the policy it describes.
///
/// The chain is by SUBTRACTION OF CAPS: each lane is sized against what is left
/// once the lanes ahead of it have spent their windows IN FULL. That is the
/// same under-estimate the Layer-A allocator already documents, and it is the
/// safe direction — it can only make a downstream window smaller, never larger.
/// It is also precisely the assumption the LIVE-clock lanes violate at run
/// time, which is #lane-budget-frame's whole subject: a lane that declines
/// leaves the real clock AHEAD of this prediction, and today the next lane to
/// read it simply grows.
#[cfg(feature = "mip")]
fn todays_attack_slice(
    onnx: &Path,
    vnnlib: &Path,
    post_beta_deadline: Option<std::time::Instant>,
    bnn_policy: BnnFalsificationPolicy,
    upfront_wrapper_route: UpfrontWrapperRoute,
    upfront_policy: &UpfrontAttackPolicy,
) -> TodayAttackSlice {
    use super::beta_crown::sign_space_falsify::{lp_lane_plan, ste_lane_plan};

    let remaining =
        post_beta_deadline.map(|d| d.saturating_duration_since(std::time::Instant::now()));
    let sign_space = bnn_policy
        .sign_space_enabled
        .then(|| lp_lane_plan(remaining))
        .flatten();
    let after_lp = remaining.map(|r| r.saturating_sub(sign_space.unwrap_or_default()));
    let ste_pgd = bnn_policy
        .ste_pgd_enabled
        .then(|| ste_lane_plan(after_lp))
        .flatten();
    let after_ste = after_lp.map(|r| r.saturating_sub(ste_pgd.unwrap_or_default()));
    let upfront_decision = upfront_today_cap(
        onnx,
        vnnlib,
        after_ste,
        upfront_wrapper_route,
        upfront_policy,
    );
    TodayAttackSlice {
        slices: crate::commands::lane_allocation::TodaySlices {
            sign_space,
            ste_pgd,
            upfront: upfront_decision.map(|decision| decision.budget),
        },
        upfront_decision,
    }
}

/// #lane-budget-frame — commit the whole attack slice up front, to exactly the
/// windows today's own rules produce against ONE reference clock reading.
///
/// No knapsack, no objective probe, no solver, no redistribution: this is the
/// IDENTITY plan, and the only thing it changes is WHEN each cap is decided.
/// `None` means no lane is consulted on this instance at all, in which case
/// there is nothing to frame and the caller runs exactly today's slice.
#[cfg(feature = "mip")]
fn frame_attack_slice_allocation(
    onnx: &Path,
    vnnlib: &Path,
    post_beta_deadline: Option<std::time::Instant>,
    bnn_policy: BnnFalsificationPolicy,
    upfront_wrapper_route: UpfrontWrapperRoute,
    upfront_policy: &UpfrontAttackPolicy,
) -> Option<CommittedAttackSlice> {
    let started = std::time::Instant::now();
    let today = todays_attack_slice(
        onnx,
        vnnlib,
        post_beta_deadline,
        bnn_policy,
        upfront_wrapper_route,
        upfront_policy,
    );
    let frame = crate::commands::lane_allocation::AttackSliceAllocation::frame(today.slices)?;
    eprintln!(
        "{} [framed in {:.3}s]",
        frame.ledger(),
        started.elapsed().as_secs_f64()
    );
    crate::flight::note(
        "lane_budget_frame",
        crate::flight::FlightStatus::Ran,
        Some(frame.ledger().to_string()),
    );
    Some(CommittedAttackSlice::from_today(
        frame,
        today.upfront_decision,
    ))
}

/// Non-mip build: the two BNN lanes cfg-compile away, so there is no attack
/// slice to frame. Identical `None` contract, so the call site is unchanged.
#[cfg(not(feature = "mip"))]
fn frame_attack_slice_allocation(
    _onnx: &Path,
    _vnnlib: &Path,
    _post_beta_deadline: Option<std::time::Instant>,
    _bnn_policy: BnnFalsificationPolicy,
    _upfront_wrapper_route: UpfrontWrapperRoute,
    _upfront_policy: &UpfrontAttackPolicy,
) -> Option<CommittedAttackSlice> {
    None
}

/// Build and solve this instance's Layer-A allocation. `None` means fail open:
/// every lane keeps its private fraction and the run is exactly today's.
#[cfg(feature = "mip")]
fn plan_attack_slice_allocation(
    onnx: &Path,
    vnnlib: &Path,
    post_beta_deadline: Option<std::time::Instant>,
    bnn_policy: BnnFalsificationPolicy,
    upfront_wrapper_route: UpfrontWrapperRoute,
    upfront_policy: &UpfrontAttackPolicy,
) -> Option<CommittedAttackSlice> {
    use crate::commands::lane_allocation::plan_attack_slice;

    let started = std::time::Instant::now();
    let today = todays_attack_slice(
        onnx,
        vnnlib,
        post_beta_deadline,
        bnn_policy,
        upfront_wrapper_route,
        upfront_policy,
    );
    let upfront = today.slices.upfront;
    // The probe costs an ORT session and up to 33 forwards, so it is not taken
    // when the only lane it could zero is not consulted anyway.
    let probe_is_flat = upfront.is_some() && probe_flat_objective_tier(onnx, vnnlib);
    // AND A FLAT VERDICT IS NOT AUTOMATICALLY EVIDENCE ABOUT THAT LANE. The
    // shape is only read when there is a verdict to narrow, and `net_is_sign_network`
    // is memoized and has already been consulted by `upfront_today_cap` above, so
    // this costs no forward and no graph load.
    let flat_zero_applies = probe_is_flat && {
        let shape = upfront_lane_shape(onnx, vnnlib, upfront_wrapper_route);
        let applies = crate::commands::lane_allocation::flat_verdict_zeroes_upfront(true, shape);
        if !applies {
            let reason = match (
                shape.steers_on_a_surrogate_objective,
                shape.enumerates_points,
            ) {
                (true, true) => "it steers on a surrogate objective AND enumerates points",
                (true, false) => "it steers on a surrogate objective, not on the probed margin",
                (false, true) => "it enumerates corners/faces rather than climbing",
                (false, false) => unreachable!("this arm is the applied zero"),
            };
            eprintln!(
                "Lane allocation: FLAT verdict NOT APPLIED to the upfront lane ({reason}); the \
                 probe measured a function that lane is not using, or one it enumerates rather \
                 than climbs, so the lane keeps today's cap"
            );
        }
        applies
    };

    match plan_attack_slice(today.slices, flat_zero_applies, ny_mip::ALLOC_SOLVE_CAP) {
        Ok(plan) => {
            eprintln!(
                "{} [planned in {:.3}s]",
                plan.ledger(),
                started.elapsed().as_secs_f64()
            );
            // THE RESIDUAL IS NAMED, not left unowned. Whatever the knapsack
            // does not grant is not lost and is not held by this module: the
            // attack slice simply returns earlier, and every ungranted second
            // reaches branch-and-bound through the SAME `attack_start`
            // subtraction that charges the lanes today.
            eprintln!(
                "Lane allocation: {:.2}s of the {:.2}s attack-slice pool is committed to \
                 lanes; the remaining {:.2}s is claimed by the branch-and-bound residual \
                 claimant through the same `attack_start` subtraction that charges the \
                 lanes today",
                plan.granted().as_secs_f64(),
                plan.pool().as_secs_f64(),
                plan.residual_to_bab().as_secs_f64(),
            );
            crate::flight::note(
                "lane_budget_allocator",
                crate::flight::FlightStatus::Ran,
                Some(plan.ledger().to_string()),
            );
            Some(CommittedAttackSlice::from_today(
                plan,
                today.upfront_decision,
            ))
        }
        Err(reason) => {
            eprintln!(
                "Lane allocation: falling open to today's plan ({reason:?}) \
                 [{:.3}s]",
                started.elapsed().as_secs_f64()
            );
            crate::flight::note(
                "lane_budget_allocator",
                crate::flight::FlightStatus::Skipped,
                Some(format!("fell open to today's plan: {reason:?}")),
            );
            None
        }
    }
}

/// Non-mip build: `ny-mip` is not linked, so there is no allocator to consult.
/// Identical `None` contract, so the call site is unchanged.
#[cfg(not(feature = "mip"))]
fn plan_attack_slice_allocation(
    _onnx: &Path,
    _vnnlib: &Path,
    _post_beta_deadline: Option<std::time::Instant>,
    _bnn_policy: BnnFalsificationPolicy,
    _upfront_wrapper_route: UpfrontWrapperRoute,
    _upfront_policy: &UpfrontAttackPolicy,
) -> Option<CommittedAttackSlice> {
    None
}

/// Compute the upfront-attack wall budget from the remaining scored budget.
/// Wall cap the PROBE-FIRST consultation of the upfront lane runs under
/// (#upfront-probe-first). Small on purpose: the rows this recovers are won in
/// 1-2 exact gradient steps and 2-3 ORT forwards (~0.1-0.2 s measured on the
/// five `traffic_signs model_30` eps>=3 rows), so the cap is insurance against
/// paying a full attack window for a lane that cannot win on this instance —
/// the lane is consulted a SECOND time, in its ordinary place and under its
/// ordinary window, if the probe comes back empty.
const UPFRONT_ATTACK_PROBE_CAP: std::time::Duration = std::time::Duration::from_secs(5);

/// Whether the scored-wall clamp is armed in the immutable entry-time
/// authority that also owns this run's flight receipt (#scored-wall-clamp).
///
/// Environment-over-preset precedence was already resolved while constructing
/// the set. Runtime execution must not reopen the mutable process environment
/// after that evidence boundary.
fn scored_wall_clamp_armed_from_levers(levers: &ny_levers::LeverSet) -> bool {
    levers.is_armed(&ny_levers::decls::dark_probes::SCORED_WALL_CLAMP)
}

/// The arming rule as a pure predicate over one raw environment string and one
/// typed preset answer.
///
/// Same declaration, same parser, same chokepoint as the frozen-authority
/// resolution above — only the lookup is injected. Since #scored-env-closure
/// the production caller reads the frozen `LeverSet`
/// (`scored_wall_clamp_armed_from_levers`), which resolves the SAME
/// declaration through the SAME layered parser, so this remains a test of the
/// arming rule — but it is no longer the production call path itself.
#[cfg(test)]
fn scored_wall_clamp_armed_from_raw(raw: Option<&str>, config: Option<bool>) -> bool {
    let owned = raw.map(str::to_owned);
    ny_levers::read_over_config_with(
        &ny_levers::decls::dark_probes::SCORED_WALL_CLAMP,
        move |_| owned,
        config.map(ny_levers::LeverValue::Bool),
    )
    .map(|resolved| resolved.value.as_bool())
    .unwrap_or(false)
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct UpfrontBudgetBinding {
    budget_fraction: bool,
    wall_cap: bool,
    auto_wall_cap: bool,
    bnn_budget_fraction: bool,
    bnn_wall_cap: bool,
}

impl UpfrontBudgetBinding {
    fn stable_token(self) -> String {
        let mut names = Vec::with_capacity(5);
        if self.budget_fraction {
            names.push("budget_fraction");
        }
        if self.wall_cap {
            names.push("wall_cap");
        }
        if self.auto_wall_cap {
            names.push("auto_wall_cap");
        }
        if self.bnn_budget_fraction {
            names.push("bnn_budget_fraction");
        }
        if self.bnn_wall_cap {
            names.push("bnn_wall_cap");
        }
        if names.is_empty() {
            "none".to_string()
        } else {
            names.join("+")
        }
    }

    fn union(self, other: Self) -> Self {
        Self {
            budget_fraction: self.budget_fraction || other.budget_fraction,
            wall_cap: self.wall_cap || other.wall_cap,
            auto_wall_cap: self.auto_wall_cap || other.auto_wall_cap,
            bnn_budget_fraction: self.bnn_budget_fraction || other.bnn_budget_fraction,
            bnn_wall_cap: self.bnn_wall_cap || other.bnn_wall_cap,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UpfrontBudgetCompetition {
    NotEvaluated,
    NotSign,
    OrdinaryWins,
    BnnWins,
    Tie,
}

impl UpfrontBudgetCompetition {
    const fn stable_token(self) -> &'static str {
        match self {
            Self::NotEvaluated => "not_evaluated",
            Self::NotSign => "not_sign",
            Self::OrdinaryWins => "ordinary_wins",
            Self::BnnWins => "bnn_wins",
            Self::Tie => "tie",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct UpfrontBudgetDecision {
    budget: std::time::Duration,
    binding: UpfrontBudgetBinding,
    competition: UpfrontBudgetCompetition,
}

fn upfront_attack_base_budget(
    remaining: Option<std::time::Duration>,
    policy: &UpfrontAttackPolicy,
) -> Option<UpfrontBudgetDecision> {
    let (budget, binding) = match remaining {
        Some(rem) => {
            let fractional = rem
                .checked_sub(UPFRONT_ATTACK_SAFETY_MARGIN)?
                .mul_f64(policy.budget_fraction);
            match fractional.cmp(&policy.wall_cap) {
                std::cmp::Ordering::Less => (
                    fractional,
                    UpfrontBudgetBinding {
                        budget_fraction: true,
                        ..UpfrontBudgetBinding::default()
                    },
                ),
                std::cmp::Ordering::Greater => (
                    policy.wall_cap,
                    UpfrontBudgetBinding {
                        wall_cap: true,
                        ..UpfrontBudgetBinding::default()
                    },
                ),
                std::cmp::Ordering::Equal => (
                    fractional,
                    UpfrontBudgetBinding {
                        budget_fraction: true,
                        wall_cap: true,
                        ..UpfrontBudgetBinding::default()
                    },
                ),
            }
        }
        None => (
            policy.wall_cap,
            UpfrontBudgetBinding {
                wall_cap: true,
                ..UpfrontBudgetBinding::default()
            },
        ),
    };
    Some(UpfrontBudgetDecision {
        budget,
        binding,
        competition: UpfrontBudgetCompetition::NotEvaluated,
    })
}

/// Sign-network candidate before it competes with the ordinary upfront base.
///
/// The inner minimum has two independently searchable controls. Naming its
/// exact winner is necessary but not sufficient for measurement credit: the
/// outer maximum below must also select this candidate.
fn bnn_attack_budget_decision(
    remaining: Option<std::time::Duration>,
    policy: &UpfrontAttackPolicy,
) -> UpfrontBudgetDecision {
    match remaining {
        Some(rem) => {
            let fractional = rem
                .saturating_sub(UPFRONT_ATTACK_SAFETY_MARGIN)
                .mul_f64(policy.bnn_budget_fraction);
            match fractional.cmp(&policy.bnn_wall_cap) {
                std::cmp::Ordering::Less => UpfrontBudgetDecision {
                    budget: fractional,
                    binding: UpfrontBudgetBinding {
                        bnn_budget_fraction: true,
                        ..UpfrontBudgetBinding::default()
                    },
                    competition: UpfrontBudgetCompetition::NotEvaluated,
                },
                std::cmp::Ordering::Greater => UpfrontBudgetDecision {
                    budget: policy.bnn_wall_cap,
                    binding: UpfrontBudgetBinding {
                        bnn_wall_cap: true,
                        ..UpfrontBudgetBinding::default()
                    },
                    competition: UpfrontBudgetCompetition::NotEvaluated,
                },
                std::cmp::Ordering::Equal => UpfrontBudgetDecision {
                    budget: fractional,
                    binding: UpfrontBudgetBinding {
                        bnn_budget_fraction: true,
                        bnn_wall_cap: true,
                        ..UpfrontBudgetBinding::default()
                    },
                    competition: UpfrontBudgetCompetition::NotEvaluated,
                },
            }
        }
        None => UpfrontBudgetDecision {
            budget: policy.bnn_wall_cap,
            binding: UpfrontBudgetBinding {
                bnn_wall_cap: true,
                ..UpfrontBudgetBinding::default()
            },
            competition: UpfrontBudgetCompetition::NotEvaluated,
        },
    }
}

/// Apply the property/network-specific clamps to an already admissible private
/// base budget while preserving every exact tie in the binding receipt.
///
/// Both the live lane and the up-front sizing mirror call this helper. An exact
/// fixed frame can therefore carry the numeric lineage that produced its cap
/// instead of replacing CAP/FRAC/AUTO with the generic fact that some allocator
/// later handed the lane a duration. A lossy whole-second knapsack cap remains
/// generic until its lower-policy counterfactual is proved separately.
fn upfront_effective_budget_decision(
    base: UpfrontBudgetDecision,
    remaining: Option<std::time::Duration>,
    policy: &UpfrontAttackPolicy,
    admission: UpfrontAttackAdmission,
    sign_net: bool,
) -> UpfrontBudgetDecision {
    if sign_net {
        let bnn = bnn_attack_budget_decision(remaining, policy);
        match bnn.budget.cmp(&base.budget) {
            std::cmp::Ordering::Greater => UpfrontBudgetDecision {
                competition: UpfrontBudgetCompetition::BnnWins,
                ..bnn
            },
            std::cmp::Ordering::Less => UpfrontBudgetDecision {
                competition: UpfrontBudgetCompetition::OrdinaryWins,
                ..base
            },
            std::cmp::Ordering::Equal => UpfrontBudgetDecision {
                budget: base.budget,
                binding: base.binding.union(bnn.binding),
                competition: UpfrontBudgetCompetition::Tie,
            },
        }
    } else if !matches!(admission, UpfrontAttackAdmission::AutoDisjunction) {
        UpfrontBudgetDecision {
            competition: UpfrontBudgetCompetition::NotSign,
            ..base
        }
    } else {
        let auto_binding = UpfrontBudgetBinding {
            auto_wall_cap: true,
            ..UpfrontBudgetBinding::default()
        };
        match policy.auto_wall_cap.cmp(&base.budget) {
            std::cmp::Ordering::Less => UpfrontBudgetDecision {
                budget: policy.auto_wall_cap,
                binding: auto_binding,
                competition: UpfrontBudgetCompetition::NotSign,
            },
            std::cmp::Ordering::Greater => UpfrontBudgetDecision {
                competition: UpfrontBudgetCompetition::NotSign,
                ..base
            },
            std::cmp::Ordering::Equal => UpfrontBudgetDecision {
                budget: base.budget,
                binding: base.binding.union(auto_binding),
                competition: UpfrontBudgetCompetition::NotSign,
            },
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CommittedUpfrontCapDecision {
    budget: Option<std::time::Duration>,
    binding: String,
    competition: UpfrontBudgetCompetition,
}

/// Clamp a probe/frame/knapsack cap to the live clock without inventing
/// upstream parameter credit.
///
/// When live remaining is smaller it is the sole binding. Equality retains
/// both causes. Missing provenance uses the generic `committed_cap` token,
/// which keeps execution fail-open while causing T1 to grant no CAP/FRAC/AUTO
/// credit.
fn clamp_committed_upfront_cap(
    cap: std::time::Duration,
    remaining: Option<std::time::Duration>,
    source_binding: &str,
    source_competition: UpfrontBudgetCompetition,
) -> CommittedUpfrontCapDecision {
    let (binding, competition) = match remaining {
        None => (source_binding.to_string(), source_competition),
        Some(remaining) => match remaining.checked_sub(UPFRONT_ATTACK_SAFETY_MARGIN) {
            None => (
                "live_remaining".to_string(),
                UpfrontBudgetCompetition::NotEvaluated,
            ),
            Some(usable) if usable < cap => (
                "live_remaining".to_string(),
                UpfrontBudgetCompetition::NotEvaluated,
            ),
            Some(usable) if usable == cap && source_binding == "probe_cap" => {
                // Preserve the v1 probe token ordering for exact-string
                // consumers outside this tree. In-tree validation is set-like.
                ("live_remaining+probe_cap".to_string(), source_competition)
            }
            Some(usable) if usable == cap => (
                format!("{source_binding}+live_remaining"),
                source_competition,
            ),
            Some(_) => (source_binding.to_string(), source_competition),
        },
    };
    let budget = crate::commands::lane_allocation::clamp_to_live_remaining(
        cap,
        remaining,
        UPFRONT_ATTACK_SAFETY_MARGIN,
    );
    CommittedUpfrontCapDecision {
        budget,
        binding,
        competition,
    }
}

/// Maximum number of genuinely varying coordinates for the exhaustive
/// low-dimensional corner precheck.  At five dimensions this is only 32 trusted
/// ORT forwards, while a sixth dimension would double the work on every robust
/// (UNSAT) instance that shares the preset.
const UPFRONT_CORNER_MAX_VARIABLE_DIMS: usize = 5;

/// Maximum total number of f32 coordinates materialized across every corner.
/// This bounds the corner payload to 4 MiB even for huge, mostly-pinned boxes.
const UPFRONT_CORNER_MAX_TOTAL_SCALARS: usize = 1_048_576;

/// Coarse and local grids for the typed low-dimensional relational lane.
///
/// For the largest admitted domain (five dimensions), enumerating every face
/// with exactly two free coordinates costs
/// `C(5,2) * 2^3 * 11^2 = 9,680` trusted forwards. Refining the best eight
/// faces costs at most another `8 * 31^2 = 7,688`, for a hard total below 18k.
/// The absolute attack deadline remains the primary wall bound.
const RELATIONAL_FACE_COARSE_TICKS: usize = 11;
const RELATIONAL_FACE_REFINE_TICKS: usize = 31;
const RELATIONAL_FACE_REFINE_TOP_K: usize = 8;
const RELATIONAL_FACE_MAX_EVALS: usize = 18_000;

#[derive(Debug)]
struct RelationalFaceBest {
    point: Vec<f32>,
    free_dims: Vec<usize>,
    margin: f64,
    violated: bool,
}

fn face_grid_value(lower: f32, upper: f32, index: usize, ticks: usize) -> f32 {
    debug_assert!(ticks >= 2);
    match index {
        0 => lower,
        i if i + 1 == ticks => upper,
        i => lower + (upper - lower) * (i as f32 / (ticks - 1) as f32),
    }
}

/// Deterministic face-grid candidate generation for a low-dimensional
/// relational conjunction.
///
/// A conjunction optimum can live on several input faces while retaining one
/// or two genuinely free coordinates. Full-box random/APGD restarts almost
/// never start on that lower-dimensional manifold, and corner-only enumeration
/// misses its interior. Enumerate every face with two free axes (one for a
/// one-dimensional domain), rank them by the exact parsed property margin, then
/// refine a bounded number locally around their coarse incumbents.
///
/// Candidate authority is unchanged: every evaluation uses the trusted ORT
/// forward at a point constructed inside `box_lo..=box_hi`, and a returned hit
/// must satisfy [`property_violated_f64`]. The caller still sends the rendered
/// witness through [`gate_sat_with_trusted_oracle`]. Any error, exhausted
/// evaluation cap, or absolute deadline expiry returns only an already
/// ORT-confirmed hit, otherwise `None`.
fn low_dim_relational_face_grid_falsify(
    forward: &mut ny_onnx::diff::OrtForward,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    box_lo: &[f32],
    box_hi: &[f32],
    emit_pin: &[Option<f64>],
    deadline: std::time::Instant,
) -> Option<Vec<f32>> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    if !is_low_dim_common_rhs_relational_conjunction(spec)
        || box_lo.len() != box_hi.len()
        || box_lo.len() != emit_pin.len()
        || box_lo.is_empty()
        || box_lo.len() > UPFRONT_RELATIONAL_MAX_INPUT_DIMS
        || box_lo
            .iter()
            .zip(box_hi)
            .any(|(&lower, &upper)| !lower.is_finite() || !upper.is_finite() || lower > upper)
    {
        return None;
    }

    let dimensions = box_lo.len();
    let free_sets: Vec<Vec<usize>> = if dimensions == 1 {
        vec![vec![0]]
    } else {
        (0..dimensions)
            .flat_map(|first| ((first + 1)..dimensions).map(move |second| vec![first, second]))
            .collect()
    };
    let center: Vec<f32> = box_lo
        .iter()
        .zip(box_hi)
        .map(|(&lower, &upper)| lower + 0.5 * (upper - lower))
        .collect();
    let mut evaluations = 0usize;
    let mut confirmed_hit: Option<(Vec<f32>, f64)> = None;
    let mut evaluate = |point: &[f32]| -> Option<(f64, bool)> {
        if evaluations >= RELATIONAL_FACE_MAX_EVALS || std::time::Instant::now() >= deadline {
            return None;
        }
        evaluations += 1;
        let output = forward.run(point).ok()?;
        if std::time::Instant::now() >= deadline {
            return None;
        }
        let output64: Vec<f64> = output
            .iter()
            .map(|&value| f32_to_f64_exact(value))
            .collect();
        let emitted = refine_emit_view(point, emit_pin);
        Some((
            property_margin(spec, point, &output64),
            property_violated_f64(spec, &emitted, &output64),
        ))
    };

    let mut faces = Vec::new();
    for free_dims in free_sets {
        let fixed_dims: Vec<usize> = (0..dimensions)
            .filter(|dimension| !free_dims.contains(dimension))
            .collect();
        let fixed_assignments = 1usize << fixed_dims.len();
        for sides in 0..fixed_assignments {
            let mut base = center.clone();
            for (bit, &dimension) in fixed_dims.iter().enumerate() {
                base[dimension] = if sides & (1usize << bit) == 0 {
                    box_lo[dimension]
                } else {
                    box_hi[dimension]
                };
            }

            let second_ticks = if free_dims.len() == 2 {
                RELATIONAL_FACE_COARSE_TICKS
            } else {
                1
            };
            let mut face_best: Option<RelationalFaceBest> = None;
            for first_index in 0..RELATIONAL_FACE_COARSE_TICKS {
                for second_index in 0..second_ticks {
                    let mut point = base.clone();
                    point[free_dims[0]] = face_grid_value(
                        box_lo[free_dims[0]],
                        box_hi[free_dims[0]],
                        first_index,
                        RELATIONAL_FACE_COARSE_TICKS,
                    );
                    if free_dims.len() == 2 {
                        point[free_dims[1]] = face_grid_value(
                            box_lo[free_dims[1]],
                            box_hi[free_dims[1]],
                            second_index,
                            RELATIONAL_FACE_COARSE_TICKS,
                        );
                    }
                    let Some((margin, violated)) = evaluate(&point) else {
                        return confirmed_hit.map(|(point, _)| point);
                    };
                    if violated
                        && confirmed_hit
                            .as_ref()
                            .is_none_or(|(_, incumbent)| margin > *incumbent)
                    {
                        confirmed_hit = Some((point.clone(), margin));
                    }
                    if margin.is_finite()
                        && face_best
                            .as_ref()
                            .is_none_or(|incumbent| margin > incumbent.margin)
                    {
                        face_best = Some(RelationalFaceBest {
                            point,
                            free_dims: free_dims.clone(),
                            margin,
                            violated,
                        });
                    }
                }
            }
            if let Some(best) = face_best {
                if best.violated {
                    return Some(best.point);
                }
                faces.push(best);
            }
        }
    }

    faces.sort_by(|left, right| {
        right
            .margin
            .partial_cmp(&left.margin)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    for face in faces.into_iter().take(RELATIONAL_FACE_REFINE_TOP_K) {
        let local_bounds: Vec<(f32, f32)> = face
            .free_dims
            .iter()
            .map(|&dimension| {
                let coarse_step = (box_hi[dimension] - box_lo[dimension])
                    / (RELATIONAL_FACE_COARSE_TICKS - 1) as f32;
                (
                    (face.point[dimension] - coarse_step).max(box_lo[dimension]),
                    (face.point[dimension] + coarse_step).min(box_hi[dimension]),
                )
            })
            .collect();
        let second_ticks = if face.free_dims.len() == 2 {
            RELATIONAL_FACE_REFINE_TICKS
        } else {
            1
        };
        let mut local_hit: Option<(Vec<f32>, f64)> = None;
        for first_index in 0..RELATIONAL_FACE_REFINE_TICKS {
            for second_index in 0..second_ticks {
                let mut point = face.point.clone();
                point[face.free_dims[0]] = face_grid_value(
                    local_bounds[0].0,
                    local_bounds[0].1,
                    first_index,
                    RELATIONAL_FACE_REFINE_TICKS,
                );
                if face.free_dims.len() == 2 {
                    point[face.free_dims[1]] = face_grid_value(
                        local_bounds[1].0,
                        local_bounds[1].1,
                        second_index,
                        RELATIONAL_FACE_REFINE_TICKS,
                    );
                }
                let Some((margin, violated)) = evaluate(&point) else {
                    return local_hit.or(confirmed_hit).map(|(point, _)| point);
                };
                if violated
                    && local_hit
                        .as_ref()
                        .is_none_or(|(_, incumbent)| margin > *incumbent)
                {
                    local_hit = Some((point, margin));
                }
            }
        }
        if let Some((point, margin)) = local_hit {
            println!(
                "Upfront attack: trusted-ORT relational face grid found a violation \
                 after {evaluations} evaluations (margin {margin:.3e})"
            );
            return Some(point);
        }
    }
    confirmed_hit.map(|(point, _)| point)
}

/// Deterministic box-corner seeds for a very low-dimensional attack domain.
///
/// Degenerate coordinates are emitted once at their sole in-box value rather
/// than multiplying duplicate points.  Refuse malformed boxes and domains above
/// the cap: the caller then proceeds directly to the existing APGD lane.
fn low_dim_corner_seeds(box_lo: &[f32], box_hi: &[f32]) -> Vec<Vec<f32>> {
    if box_lo.is_empty()
        || box_lo.len() != box_hi.len()
        || box_lo
            .iter()
            .zip(box_hi)
            .any(|(&lo, &hi)| !lo.is_finite() || !hi.is_finite() || lo > hi)
    {
        return Vec::new();
    }
    let mut varying = Vec::with_capacity(UPFRONT_CORNER_MAX_VARIABLE_DIMS);
    for (idx, (&lo, &hi)) in box_lo.iter().zip(box_hi).enumerate() {
        if lo < hi {
            if varying.len() == UPFRONT_CORNER_MAX_VARIABLE_DIMS {
                return Vec::new();
            }
            varying.push(idx);
        }
    }

    let count = 1usize << varying.len();
    let Some(total_scalars) = box_lo.len().checked_mul(count) else {
        return Vec::new();
    };
    if total_scalars > UPFRONT_CORNER_MAX_TOTAL_SCALARS {
        return Vec::new();
    }
    let mut corners = Vec::with_capacity(count);
    for mask in 0..count {
        let mut point = box_lo.to_vec();
        for (bit, &dim) in varying.iter().enumerate() {
            if mask & (1usize << bit) != 0 {
                point[dim] = box_hi[dim];
            }
        }
        corners.push(point);
    }
    corners
}

/// Check every low-dimensional box corner with the trusted ORT evaluator and
/// the exact same f64 property predicate used by APGD and final SAT admission.
///
/// This is candidate generation only.  A hit is still re-run through
/// `gate_sat_with_trusted_oracle` by the caller, so corner scheduling cannot
/// weaken acceptance or create a verdict from ny's internal model semantics.
fn low_dim_ort_corner_falsify(
    forward: &mut ny_onnx::diff::OrtForward,
    spec: &ny_onnx::vnnlib::VnnLibSpec,
    box_lo: &[f32],
    box_hi: &[f32],
    emit_pin: &[Option<f64>],
    deadline: std::time::Instant,
) -> Option<Vec<f32>> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    for point in low_dim_corner_seeds(box_lo, box_hi) {
        if std::time::Instant::now() >= deadline {
            return None;
        }
        let output = forward.run(&point).ok()?;
        if std::time::Instant::now() >= deadline {
            return None;
        }
        let output64: Vec<f64> = output.iter().map(|&v| f32_to_f64_exact(v)).collect();
        if property_violated_f64(spec, &refine_emit_view(&point, emit_pin), &output64)
            && std::time::Instant::now() < deadline
        {
            return Some(point);
        }
    }
    None
}

// --- Dark sign-space falsification lane (#bnn-sign-space). ----------------

/// The CALL-SITE rule for the sign-space lane, factored out so it can be tested
/// without a scored run.
///
/// This is the whole of the lane's verdict authority, and it is deliberately
/// tiny:
///
/// * no witness (lane disarmed, refused, exhausted, out of budget, or the
///   graph/property is outside the admitted fragment) => `None`. The `gate`
///   closure is NEVER invoked, so no new `sat` source exists on that arm and
///   the caller proceeds down the normal verification path EXACTLY as it would
///   have with the lane absent;
/// * a witness that the gate DOWNGRADES => `None`, and the caller falls through
///   the same way (`#upfront-gate-fallthrough`: forfeiting the instance on a
///   rejected candidate would cost the sound verifier its whole budget);
/// * a witness the gate UPHOLDS as `sat` => `Some(sat)`, which is the only way
///   this lane can terminate an instance.
///
/// There is no arm that can produce `unsat`, and none that can produce a `sat`
/// without the caller's UNCHANGED [`gate_sat_with_trusted_oracle`] having
/// confirmed it against the ORIGINAL model.
fn sign_space_lane_verdict(
    witness: Option<String>,
    gate: impl FnOnce(&str) -> VnncompResult,
) -> Option<VnncompResult> {
    falsification_lane_verdict("bnn_sign_space", "Sign-space falsification", witness, gate)
}

/// [`sign_space_lane_verdict`] with the lane's receipt key and stderr prefix
/// injected, so the STE-PGD lane obeys the SAME rule rather than a copy of it.
///
/// Every clause of the contract above applies verbatim to every lane routed
/// through here: no witness and a downgraded witness both produce `None`, and
/// the ONLY way to terminate an instance is a witness the caller's UNCHANGED
/// [`gate_sat_with_trusted_oracle`] upholds as `sat`.
fn falsification_lane_verdict(
    lane: &'static str,
    label: &str,
    witness: Option<String>,
    gate: impl FnOnce(&str) -> VnncompResult,
) -> Option<VnncompResult> {
    let witness = witness?;
    let gated = gate(&witness);
    if matches!(gated, VnncompResult::Sat { .. }) {
        return Some(gated);
    }
    crate::flight::note(
        lane,
        crate::flight::FlightStatus::Ran,
        Some("candidate rejected by the trusted-oracle gate; fell through".to_string()),
    );
    eprintln!(
        "{label}: candidate rejected by the trusted-oracle gate; falling \
         through to the full verification path (verdict-neutral lane)"
    );
    None
}

/// Singular machine-readable terminal for one BNN falsification lane.
///
/// The full four-axis policy is repeated deliberately: the search validator
/// rejects a lane terminal that cannot be joined exactly to the one frozen
/// policy record from the same row. Human refusal text and elapsed time remain
/// outside this causal contract.
#[cfg(feature = "mip")]
#[allow(clippy::too_many_arguments)]
fn bnn_falsification_execution_reason(
    lane: &str,
    route: &str,
    outcome: &str,
    policy: BnnFalsificationPolicy,
    work_started: bool,
    budget: Option<std::time::Duration>,
    opportunity_budget: Option<std::time::Duration>,
    free_units: u64,
    flips: u64,
    work_units: u64,
) -> String {
    let millis = |budget: Option<std::time::Duration>| {
        budget.map_or_else(
            || "none".to_string(),
            |duration| {
                u64::try_from(duration.as_millis())
                    .unwrap_or(u64::MAX)
                    .to_string()
            },
        )
    };
    let budget_ms = millis(budget);
    let opportunity_budget_ms = millis(opportunity_budget);
    format!(
        "schema=ny-cli/bnn-falsification-execution/v1 lane={lane} route={route} \
         outcome={outcome} sign_space_enabled={} minimal_move={} trust_region={} \
         ste_pgd_enabled={} work_started={work_started} budget_ms={budget_ms} \
         opportunity_budget_ms={opportunity_budget_ms} free_units={free_units} \
         flips={flips} work_units={work_units}",
        policy.sign_space_enabled,
        policy.minimal_move,
        policy.trust_region.stable_token(),
        policy.ste_pgd_enabled,
    )
}

#[cfg(feature = "mip")]
#[allow(clippy::too_many_arguments)]
fn note_bnn_falsification_execution(
    lane: &str,
    route: &str,
    outcome: &str,
    policy: BnnFalsificationPolicy,
    work_started: bool,
    budget: Option<std::time::Duration>,
    opportunity_budget: Option<std::time::Duration>,
    free_units: u64,
    flips: u64,
    work_units: u64,
) {
    crate::flight::note(
        "bnn_falsification_execution",
        if work_started {
            crate::flight::FlightStatus::Ran
        } else {
            crate::flight::FlightStatus::Skipped
        },
        Some(bnn_falsification_execution_reason(
            lane,
            route,
            outcome,
            policy,
            work_started,
            budget,
            opportunity_budget,
            free_units,
            flips,
            work_units,
        )),
    );
}

/// Clamp an allocated BNN cap to the live clock without admitting a dribble
/// the lane's own private budget policy would refuse.
///
/// Besides preserving route parity, this keeps `opportunity_budget_ms`
/// causal: a disabled lane cannot claim a kill opportunity from a positive but
/// unusable sub-floor remainder (including a sub-millisecond remainder that
/// would serialize as zero milliseconds).
#[cfg(feature = "mip")]
fn bnn_committed_opportunity_budget(
    cap: std::time::Duration,
    remaining: Option<std::time::Duration>,
) -> Option<std::time::Duration> {
    use super::beta_crown::sign_space_falsify::{LANE_PUBLICATION_MARGIN, MIN_LANE_BUDGET};

    let clamped = crate::commands::lane_allocation::clamp_to_live_remaining(
        cap,
        remaining,
        LANE_PUBLICATION_MARGIN,
    )?;
    (clamped >= MIN_LANE_BUDGET).then_some(clamped)
}

/// Consult the dark LP-guided sign-space falsifier and render any candidate as
/// an ORIGINAL-MODEL SMT-LIB witness for the caller's trusted-oracle gate.
///
/// Returns `None` for every non-candidate outcome, including the default
/// disarmed one. The candidate's `Y_j` values are supplied by
/// [`rehydrate_original_witness_outputs`] — a real ONNX Runtime forward on the
/// ORIGINAL graph — so the search's own integer logits never appear in a
/// published witness; if that re-forward fails, the candidate is dropped rather
/// than emitted on internal arithmetic.
#[cfg(feature = "mip")]
fn try_sign_space_falsify(
    onnx: &Path,
    vnnlib: &Path,
    instance_deadline: Option<std::time::Instant>,
    bnn_policy: BnnFalsificationPolicy,
    window: crate::commands::lane_allocation::LaneWindow,
) -> Option<String> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    use super::beta_crown::sign_space_falsify::{
        lp_lane_plan, run_sign_space_lane_granted_with_policy, run_sign_space_lane_with_policy,
        SignSpaceLaneOutcome,
    };
    use crate::commands::lane_allocation::LaneWindow;

    let remaining = instance_deadline
        .map(|deadline| deadline.saturating_duration_since(std::time::Instant::now()));
    let started = std::time::Instant::now();
    let (route, budget, opportunity_budget, outcome) = match window {
        // Today's unallocated route: the lane derives exactly the window it
        // derives from its own private helper.
        LaneWindow::Private => {
            let opportunity_budget = lp_lane_plan(remaining);
            (
                "private",
                bnn_policy
                    .sign_space_enabled
                    .then_some(opportunity_budget)
                    .flatten(),
                opportunity_budget,
                run_sign_space_lane_with_policy(onnx, vnnlib, remaining, bnn_policy),
            )
        }
        LaneWindow::Skip => {
            note_bnn_falsification_execution(
                "sign_space",
                "committed_skip",
                "window_skipped",
                bnn_policy,
                false,
                None,
                None,
                0,
                0,
                0,
            );
            return None;
        }
        LaneWindow::Cap(cap) => {
            let opportunity_budget = bnn_committed_opportunity_budget(cap, remaining);
            if !bnn_policy.sign_space_enabled {
                (
                    "committed_cap",
                    None,
                    opportunity_budget,
                    SignSpaceLaneOutcome::Disarmed,
                )
            } else {
                // A committed cap is still clamped to the LIVE remaining budget
                // before it is handed over. The allocator planned against a
                // prediction; the deadline is the fact, and no row may exceed its
                // official budget because an upstream lane overran its own cap.
                let Some(cap) = opportunity_budget else {
                    note_bnn_falsification_execution(
                        "sign_space",
                        "committed_cap",
                        "budget_unavailable",
                        bnn_policy,
                        false,
                        None,
                        None,
                        0,
                        0,
                        0,
                    );
                    return None;
                };
                (
                    "committed_cap",
                    Some(cap),
                    Some(cap),
                    run_sign_space_lane_granted_with_policy(onnx, vnnlib, cap, 0, bnn_policy),
                )
            }
        }
    };
    let (free_units, flips, work_units) = outcome.evidence_counts();
    if matches!(outcome, SignSpaceLaneOutcome::Disarmed) {
        note_bnn_falsification_execution(
            "sign_space",
            route,
            outcome
                .stable_terminal_token()
                .expect("a disarmed lane has a stable terminal token"),
            bnn_policy,
            false,
            budget,
            opportunity_budget,
            free_units,
            flips,
            work_units,
        );
        return None;
    }
    // The elapsed time is on the REFUSAL lines too, on purpose. Armed, this
    // lane spends scored budget before every other family's attack, and a
    // structural decline is only "free" if it is measured to be: this is the
    // number that decides whether the key can widen beyond the category where
    // it is validated (`preset::AttackPreset::bnn_sign_space`).
    eprintln!(
        "Sign-space falsification: {} [{:.2}s]",
        outcome.describe(),
        started.elapsed().as_secs_f64()
    );
    let Some(input) = outcome.candidate_input() else {
        note_bnn_falsification_execution(
            "sign_space",
            route,
            outcome
                .stable_terminal_token()
                .expect("a non-candidate lane has a stable terminal token"),
            bnn_policy,
            outcome.work_started(),
            budget,
            opportunity_budget,
            free_units,
            flips,
            work_units,
        );
        return None;
    };
    // Input-only witness first: the organizer parses these decimals AS WRITTEN,
    // and the outputs must come from the ORIGINAL model, never from the search.
    let input_only = format_smtlib_witness_f64(input, &[]);
    match rehydrate_original_witness_outputs(onnx, &input_only) {
        Ok(witness) => {
            note_bnn_falsification_execution(
                "sign_space",
                route,
                "candidate_reforwarded",
                bnn_policy,
                true,
                budget,
                opportunity_budget,
                free_units,
                flips,
                work_units,
            );
            Some(witness)
        }
        Err(error) => {
            note_bnn_falsification_execution(
                "sign_space",
                route,
                "candidate_reforward_failed",
                bnn_policy,
                true,
                budget,
                opportunity_budget,
                free_units,
                flips,
                work_units,
            );
            crate::flight::note(
                "bnn_sign_space",
                crate::flight::FlightStatus::Ran,
                Some(format!(
                    "candidate dropped: original-model re-forward failed ({error})"
                )),
            );
            eprintln!(
                "Sign-space falsification: could not re-forward the candidate through the \
                 ORIGINAL model ({error}); dropping it and continuing on the normal path"
            );
            None
        }
    }
}

/// #lane-value-scheduler: run the two binarized-net attack lanes under ONE
/// marginal-value ledger instead of a chain of private fixed fractions.
///
/// DARK. Reached only when `NY_LANE_VALUE_SCHEDULER` is armed; the caller
/// keeps the unscheduled call sites otherwise, so the default path is the
/// unwired tree.
///
/// Returns the receipt key of the lane that produced a CLAIMED counterexample
/// and the witness itself. Never a verdict: the caller still routes it through
/// the unchanged [`gate_sat_with_trusted_oracle`], via the same
/// [`falsification_lane_verdict`] rule the unscheduled lanes use.
///
/// WHAT THE SCHEDULE CHANGES, and it is only the budget:
///
/// * both lanes are planned by their OWN unchanged rules
///   (`lp_lane_plan` / `ste_lane_plan`), re-derived from the LIVE remaining
///   budget at each lane's own admission, so a yield upstream arrives
///   downstream as a bigger CAP rather than as unclaimed pool;
/// * the aggregate is bounded by one pool, `remaining - the 45 s publication
///   margin`, so no reallocation and no overrun can cross the wall that makes a
///   family bankable;
/// * each lane reports its actual cost and its progress in its own work units,
///   and the ledger is printed rather than inferred from stderr — the survey
///   found the flight sidecar records NOTHING between the TLL probe and the
///   post-attack marker, a 406.01 s hole on the row it measured.
///
/// ORDER IS PRESERVED, because it is measured: on the three `model_30` eps=1
/// rows the LP lane owns, the STE lane was measured `exhausted` over its whole
/// budget, and with the LP lane disabled entirely STE returned the SAME rows.
#[cfg(feature = "mip")]
fn run_bnn_lane_schedule(
    onnx: &Path,
    vnnlib: &Path,
    post_beta_deadline: Option<std::time::Instant>,
    bnn_policy: BnnFalsificationPolicy,
) -> Option<(&'static str, String)> {
    use super::beta_crown::sign_space_falsify::{
        lp_lane_plan, run_sign_space_lane_granted_with_policy, run_ste_pgd_lane_granted,
        ste_lane_plan, SignSpaceLaneOutcome, LANE_PUBLICATION_MARGIN,
    };
    use crate::commands::lane_schedule::{
        candidate_block, declined_block, lane_schedule_pool, measured_block, run_lane_schedule,
        DeadlineBudget, LaneBudgetSource, LaneSpec,
    };
    use ny_core::phase_yield::DeclineReason;

    if !bnn_policy.sign_space_enabled {
        note_bnn_falsification_execution(
            "sign_space",
            "scheduled",
            "disarmed",
            bnn_policy,
            false,
            None,
            None,
            0,
            0,
            0,
        );
    }
    if !bnn_policy.ste_pgd_enabled {
        note_bnn_falsification_execution(
            "ste_pgd",
            "scheduled",
            "disarmed",
            bnn_policy,
            false,
            None,
            None,
            0,
            0,
            0,
        );
    }
    if !bnn_policy.sign_space_enabled && !bnn_policy.ste_pgd_enabled {
        return None;
    }

    let budget = DeadlineBudget {
        deadline: post_beta_deadline,
    };
    // Sized off the LIVE remaining budget, not off a precomputed total: a pool
    // derived from a stale deadline is exactly how an `error` row appears.
    let Some(pool) = lane_schedule_pool(budget.remaining(), LANE_PUBLICATION_MARGIN) else {
        for (lane, enabled) in [
            ("sign_space", bnn_policy.sign_space_enabled),
            ("ste_pgd", bnn_policy.ste_pgd_enabled),
        ] {
            if enabled {
                note_bnn_falsification_execution(
                    lane,
                    "scheduled",
                    "budget_unavailable",
                    bnn_policy,
                    false,
                    None,
                    None,
                    0,
                    0,
                    0,
                );
            }
        }
        return None;
    };

    // Which lane produced the witness, for the receipt key.
    let winner: std::rc::Rc<std::cell::RefCell<Option<&'static str>>> =
        std::rc::Rc::new(std::cell::RefCell::new(None));

    let sign_space_invoked = std::rc::Rc::new(std::cell::Cell::new(false));
    let ste_pgd_invoked = std::rc::Rc::new(std::cell::Cell::new(false));
    let mut lanes: Vec<LaneSpec> = Vec::with_capacity(2);
    if bnn_policy.sign_space_enabled {
        let onnx = onnx.to_path_buf();
        let vnnlib = vnnlib.to_path_buf();
        let winner = std::rc::Rc::clone(&winner);
        let invoked = std::rc::Rc::clone(&sign_space_invoked);
        lanes.push(LaneSpec {
            name: "bnn_sign_space",
            plan: Box::new(lp_lane_plan),
            // Measured prior: this lane produced the candidate on 3 of the 3
            // `model_30` eps=1 rows and on none of the 9 open deeper rows.
            prior_value: 3.0,
            run: Box::new(move |window| {
                invoked.set(true);
                let started = std::time::Instant::now();
                let outcome = run_sign_space_lane_granted_with_policy(
                    &onnx,
                    &vnnlib,
                    window,
                    LP_LANE_VALUE_STALL_LP_SOLVES,
                    bnn_policy,
                );
                let elapsed = started.elapsed();
                eprintln!(
                    "Sign-space falsification: {} [{:.2}s of a {:.2}s scheduled cap]",
                    outcome.describe(),
                    elapsed.as_secs_f64(),
                    window.as_secs_f64(),
                );
                let (free_units, flips, work_units) = outcome.evidence_counts();
                match &outcome {
                    SignSpaceLaneOutcome::Exhausted {
                        margin_gain,
                        lp_solves,
                        ..
                    } => {
                        note_bnn_falsification_execution(
                            "sign_space",
                            "scheduled",
                            outcome
                                .stable_terminal_token()
                                .expect("an exhausted lane has a stable terminal token"),
                            bnn_policy,
                            outcome.work_started(),
                            Some(window),
                            Some(window),
                            free_units,
                            flips,
                            work_units,
                        );
                        // The lane's OWN unit: pattern-margin movement over
                        // realizability LPs. NOT flips -- 34 flips bought
                        // 217.52 s and delivered nothing on the row measured.
                        let (gain, units) = (*margin_gain as f64, *lp_solves as u64);
                        measured_block(gain, units, elapsed)
                    }
                    SignSpaceLaneOutcome::Candidate(_) => {
                        match outcome
                            .candidate_input()
                            .map(|input| format_smtlib_witness_f64(input, &[]))
                            .and_then(|input_only| {
                                rehydrate_original_witness_outputs(&onnx, &input_only).ok()
                            }) {
                            Some(witness) => {
                                note_bnn_falsification_execution(
                                    "sign_space",
                                    "scheduled",
                                    "candidate_reforwarded",
                                    bnn_policy,
                                    true,
                                    Some(window),
                                    Some(window),
                                    free_units,
                                    flips,
                                    work_units,
                                );
                                *winner.borrow_mut() = Some("bnn_sign_space");
                                candidate_block(witness, elapsed)
                            }
                            None => {
                                note_bnn_falsification_execution(
                                    "sign_space",
                                    "scheduled",
                                    "candidate_reforward_failed",
                                    bnn_policy,
                                    true,
                                    Some(window),
                                    Some(window),
                                    free_units,
                                    flips,
                                    work_units,
                                );
                                // A candidate whose ORIGINAL-model re-forward
                                // failed is DROPPED, exactly as unscheduled.
                                declined_block(DeclineReason::Empty, elapsed)
                            }
                        }
                    }
                    _ => {
                        note_bnn_falsification_execution(
                            "sign_space",
                            "scheduled",
                            outcome
                                .stable_terminal_token()
                                .expect("a non-candidate lane has a stable terminal token"),
                            bnn_policy,
                            outcome.work_started(),
                            Some(window),
                            Some(window),
                            free_units,
                            flips,
                            work_units,
                        );
                        declined_block(DeclineReason::Empty, elapsed)
                    }
                }
            }),
        });
    }
    if bnn_policy.ste_pgd_enabled {
        let onnx = onnx.to_path_buf();
        let vnnlib = vnnlib.to_path_buf();
        let winner = std::rc::Rc::clone(&winner);
        let invoked = std::rc::Rc::clone(&ste_pgd_invoked);
        lanes.push(LaneSpec {
            name: "bnn_ste_pgd",
            plan: Box::new(ste_lane_plan),
            prior_value: 2.0,
            run: Box::new(move |window| {
                invoked.set(true);
                let started = std::time::Instant::now();
                let outcome = run_ste_pgd_lane_granted(&onnx, &vnnlib, window);
                let elapsed = started.elapsed();
                eprintln!(
                    "STE-PGD falsification: {} [{:.2}s of a {:.2}s scheduled cap]",
                    outcome.describe(),
                    elapsed.as_secs_f64(),
                    window.as_secs_f64(),
                );
                let (free_units, flips, work_units) = outcome.evidence_counts();
                match &outcome {
                    SignSpaceLaneOutcome::Exhausted {
                        margin_gain,
                        lp_solves,
                        ..
                    } => {
                        note_bnn_falsification_execution(
                            "ste_pgd",
                            "scheduled",
                            outcome
                                .stable_terminal_token()
                                .expect("an exhausted lane has a stable terminal token"),
                            bnn_policy,
                            outcome.work_started(),
                            Some(window),
                            Some(window),
                            free_units,
                            flips,
                            work_units,
                        );
                        // This lane's denominator is PROBES, which it reports
                        // in the `lp_solves` slot. It is honest only for stage
                        // B: `probes` is not incremented in stage A, which is
                        // 75% of its budget.
                        measured_block(*margin_gain as f64, *lp_solves as u64, elapsed)
                    }
                    SignSpaceLaneOutcome::Candidate(_) => {
                        match outcome
                            .candidate_input()
                            .map(|input| format_smtlib_witness_f64(input, &[]))
                            .and_then(|input_only| {
                                rehydrate_original_witness_outputs(&onnx, &input_only).ok()
                            }) {
                            Some(witness) => {
                                note_bnn_falsification_execution(
                                    "ste_pgd",
                                    "scheduled",
                                    "candidate_reforwarded",
                                    bnn_policy,
                                    true,
                                    Some(window),
                                    Some(window),
                                    free_units,
                                    flips,
                                    work_units,
                                );
                                *winner.borrow_mut() = Some("bnn_ste_pgd");
                                candidate_block(witness, elapsed)
                            }
                            None => {
                                note_bnn_falsification_execution(
                                    "ste_pgd",
                                    "scheduled",
                                    "candidate_reforward_failed",
                                    bnn_policy,
                                    true,
                                    Some(window),
                                    Some(window),
                                    free_units,
                                    flips,
                                    work_units,
                                );
                                declined_block(DeclineReason::Empty, elapsed)
                            }
                        }
                    }
                    _ => {
                        note_bnn_falsification_execution(
                            "ste_pgd",
                            "scheduled",
                            outcome
                                .stable_terminal_token()
                                .expect("a non-candidate lane has a stable terminal token"),
                            bnn_policy,
                            outcome.work_started(),
                            Some(window),
                            Some(window),
                            free_units,
                            flips,
                            work_units,
                        );
                        declined_block(DeclineReason::Empty, elapsed)
                    }
                }
            }),
        });
    }

    let (witness, ledger) = run_lane_schedule(
        lanes,
        Box::new(DeadlineBudget {
            deadline: post_beta_deadline,
        }),
        pool,
        LANE_SCHEDULE_FLOOR,
    );
    for (lane, enabled, invoked) in [
        (
            "sign_space",
            bnn_policy.sign_space_enabled,
            sign_space_invoked.get(),
        ),
        ("ste_pgd", bnn_policy.ste_pgd_enabled, ste_pgd_invoked.get()),
    ] {
        if enabled && !invoked {
            note_bnn_falsification_execution(
                lane,
                "scheduled",
                "not_admitted",
                bnn_policy,
                false,
                None,
                None,
                0,
                0,
                0,
            );
        }
    }
    eprintln!("{}", ledger.describe());
    crate::flight::note(
        "lane_value_scheduler",
        crate::flight::FlightStatus::Ran,
        Some(ledger.describe()),
    );
    let lane = (*winner.borrow())?;
    witness.map(|w| (lane, w))
}

/// Non-mip build: neither lane exists, so the schedule cannot.
#[cfg(not(feature = "mip"))]
fn run_bnn_lane_schedule(
    _onnx: &Path,
    _vnnlib: &Path,
    _post_beta_deadline: Option<std::time::Instant>,
    _bnn_policy: BnnFalsificationPolicy,
) -> Option<(&'static str, String)> {
    None
}

/// The LP walk's VALUE-based yield rule under the scheduler, in LP solves.
///
/// The shipped rule (`stall_lp_solves: 32`) asks "has this walk accepted ANY
/// flip", which is a never-started test: measured on
/// `model_48_idx_1703_eps_1`, the walk accepted 34 flips, moved the margin to
/// -82, produced nothing, and burned all 217.52 s with the rule permanently
/// disarmed. This one asks whether the margin has MOVED.
///
/// NOT MEASURED on the nine open rows, and deliberately loose: at 64 it is
/// twice the shipped never-started threshold, so a walk that is still finding
/// improving flips at the rate the three `model_30` rows do (78-99 flips over
/// 311 LPs) is nowhere near it. Reachable only with the scheduler armed.
#[cfg(feature = "mip")]
const LP_LANE_VALUE_STALL_LP_SOLVES: usize = 64;

/// Minimum window worth admitting a scheduled lane with. Mirrors the lanes'
/// own `MIN_LANE_BUDGET`.
#[cfg(feature = "mip")]
const LANE_SCHEDULE_FLOOR: std::time::Duration = std::time::Duration::from_secs(20);

/// Consult the dark STE-PGD falsifier and render any candidate as an
/// ORIGINAL-MODEL SMT-LIB witness for the caller's trusted-oracle gate.
///
/// Byte-for-byte the same publication path as [`try_sign_space_falsify`]: the
/// candidate is emitted INPUT-ONLY, its `Y_j` values come from
/// [`rehydrate_original_witness_outputs`] (a real ONNX Runtime forward on the
/// ORIGINAL graph), and a failed re-forward DROPS the candidate rather than
/// publishing the search's own arithmetic. Returns `None` for every
/// non-candidate outcome, including the default disarmed one.
#[cfg(feature = "mip")]
fn try_ste_pgd_falsify(
    onnx: &Path,
    vnnlib: &Path,
    instance_deadline: Option<std::time::Instant>,
    bnn_policy: BnnFalsificationPolicy,
    window: crate::commands::lane_allocation::LaneWindow,
) -> Option<String> {
    // #phase-cost: see `ny_core::phase_cost` (observability only).
    let _phase_cost = ny_core::phase_cost::enter(ny_core::phase_cost::CostPhase::Attack);
    use super::beta_crown::sign_space_falsify::{
        run_ste_pgd_lane_granted, run_ste_pgd_lane_with_policy, ste_lane_plan, SignSpaceLaneOutcome,
    };
    use crate::commands::lane_allocation::LaneWindow;

    let remaining = instance_deadline
        .map(|deadline| deadline.saturating_duration_since(std::time::Instant::now()));
    let started = std::time::Instant::now();
    let (route, budget, opportunity_budget, outcome) = match window {
        LaneWindow::Private => {
            let opportunity_budget = ste_lane_plan(remaining);
            (
                "private",
                bnn_policy
                    .ste_pgd_enabled
                    .then_some(opportunity_budget)
                    .flatten(),
                opportunity_budget,
                run_ste_pgd_lane_with_policy(onnx, vnnlib, remaining, bnn_policy),
            )
        }
        LaneWindow::Skip => {
            note_bnn_falsification_execution(
                "ste_pgd",
                "committed_skip",
                "window_skipped",
                bnn_policy,
                false,
                None,
                None,
                0,
                0,
                0,
            );
            return None;
        }
        LaneWindow::Cap(cap) => {
            let opportunity_budget = bnn_committed_opportunity_budget(cap, remaining);
            if !bnn_policy.ste_pgd_enabled {
                (
                    "committed_cap",
                    None,
                    opportunity_budget,
                    SignSpaceLaneOutcome::Disarmed,
                )
            } else {
                let Some(cap) = opportunity_budget else {
                    note_bnn_falsification_execution(
                        "ste_pgd",
                        "committed_cap",
                        "budget_unavailable",
                        bnn_policy,
                        false,
                        None,
                        None,
                        0,
                        0,
                        0,
                    );
                    return None;
                };
                (
                    "committed_cap",
                    Some(cap),
                    Some(cap),
                    run_ste_pgd_lane_granted(onnx, vnnlib, cap),
                )
            }
        }
    };
    let (free_units, flips, work_units) = outcome.evidence_counts();
    if matches!(outcome, SignSpaceLaneOutcome::Disarmed) {
        note_bnn_falsification_execution(
            "ste_pgd",
            route,
            outcome
                .stable_terminal_token()
                .expect("a disarmed lane has a stable terminal token"),
            bnn_policy,
            false,
            budget,
            opportunity_budget,
            free_units,
            flips,
            work_units,
        );
        return None;
    }
    // The elapsed time is on the REFUSAL lines too, for the same reason it is
    // on the sign-space lane's: a structural decline is only "free" if it is
    // measured to be, and that number is what decides whether this lever can
    // ever become a typed preset key.
    eprintln!(
        "STE-PGD falsification: {} [{:.2}s]",
        outcome.describe(),
        started.elapsed().as_secs_f64()
    );
    let Some(input) = outcome.candidate_input() else {
        note_bnn_falsification_execution(
            "ste_pgd",
            route,
            outcome
                .stable_terminal_token()
                .expect("a non-candidate lane has a stable terminal token"),
            bnn_policy,
            outcome.work_started(),
            budget,
            opportunity_budget,
            free_units,
            flips,
            work_units,
        );
        return None;
    };
    let input_only = format_smtlib_witness_f64(input, &[]);
    match rehydrate_original_witness_outputs(onnx, &input_only) {
        Ok(witness) => {
            note_bnn_falsification_execution(
                "ste_pgd",
                route,
                "candidate_reforwarded",
                bnn_policy,
                true,
                budget,
                opportunity_budget,
                free_units,
                flips,
                work_units,
            );
            Some(witness)
        }
        Err(error) => {
            note_bnn_falsification_execution(
                "ste_pgd",
                route,
                "candidate_reforward_failed",
                bnn_policy,
                true,
                budget,
                opportunity_budget,
                free_units,
                flips,
                work_units,
            );
            crate::flight::note(
                "bnn_ste_pgd",
                crate::flight::FlightStatus::Ran,
                Some(format!(
                    "candidate dropped: original-model re-forward failed ({error})"
                )),
            );
            eprintln!(
                "STE-PGD falsification: could not re-forward the candidate through the \
                 ORIGINAL model ({error}); dropping it and continuing on the normal path"
            );
            None
        }
    }
}

