    #[test]
    fn ort_refine_vjp_private_budget_preserves_sequential_fallback() {
        use std::time::Duration;

        assert_eq!(ort_refine_vjp_budget(Duration::ZERO), None);
        assert_eq!(ort_refine_vjp_budget(Duration::from_secs(1)), None);
        assert_eq!(
            ort_refine_vjp_budget(Duration::from_millis(1999)),
            None,
            "a sub-500ms quarter is too small to admit device setup"
        );
        assert_eq!(
            ort_refine_vjp_budget(Duration::from_secs(2)),
            Some(Duration::from_millis(500)),
            "the minimum boundary is inclusive"
        );
        assert_eq!(
            ort_refine_vjp_budget(Duration::from_secs(3)),
            Some(Duration::from_millis(750))
        );
        assert_eq!(
            ort_refine_vjp_budget(Duration::from_secs(4)),
            Some(Duration::from_secs(1))
        );
        assert_eq!(
            ort_refine_vjp_budget(Duration::from_secs(30)),
            Some(Duration::from_secs(1)),
            "long lanes keep all but the hard one-second pre-wave cap"
        );
    }

    #[test]
    fn margin_subgradient_row_picks_binding_constraint_of_active_clause() {
        // metaroom-shaped disjunction: unsafe iff any Y_i >= Y_2 (i != 2).
        let spec = spec_with(
            3,
            vec![vec![OC::GreaterEq(0, 2)], vec![OC::GreaterEq(1, 2)]],
            true,
            vec![(0.0, 1.0)],
        );
        // Y = [0.1, 0.8, 1.0]: clause margins are -0.9 and -0.2 -> the active
        // (max) clause is Y_1 >= Y_2, whose margin row is +1 at 1, -1 at 2.
        let row = margin_subgradient_row(&spec, &[0.5], &[0.1, 0.8, 1.0], None).unwrap();
        assert_eq!(row, vec![0.0, 1.0, -1.0]);

        // Conjunction clause: binding = MIN constraint margin within the clause.
        let conj = spec_with(
            2,
            vec![vec![OC::GreaterEqConst(0, 1.0), OC::GreaterEqConst(1, 1.0)]],
            true,
            vec![(0.0, 1.0)],
        );
        // Y = [0.9, 0.2]: binding constraint is Y_1 >= 1.0 (margin -0.8 < -0.1).
        let row = margin_subgradient_row(&conj, &[0.5], &[0.9, 0.2], None).unwrap();
        assert_eq!(row, vec![0.0, 1.0]);
    }

    /// #traffic-saturated-softmax: when the post-`Softmax` outputs saturate every
    /// disjunct margin ties exactly, and the historical `max_by` silently returns
    /// the LAST clause. The monotone `tiebreak` view (ny's pre-`Softmax` logits)
    /// must then select the argmax disjunct — and must change NOTHING when the
    /// outputs are informative.
    #[test]
    fn margin_subgradient_row_breaks_saturated_ties_in_logit_space() {
        // Unsafe iff Y_0 >= Y_3 or Y_1 >= Y_3 or Y_2 >= Y_3.
        let spec = spec_with(
            4,
            vec![
                vec![OC::GreaterEq(0, 3)],
                vec![OC::GreaterEq(1, 3)],
                vec![OC::GreaterEq(2, 3)],
            ],
            true,
            vec![(0.0, 1.0)],
        );
        // SATURATED softmax: p_true = 1, every other output exactly 0, so all
        // three clause margins are exactly -1.
        let saturated = [0.0, 0.0, 0.0, 1.0];
        // Historical behaviour (no tie-break): the LAST clause, Y_2 >= Y_3.
        let row = margin_subgradient_row(&spec, &[0.5], &saturated, None).unwrap();
        assert_eq!(row, vec![0.0, 0.0, 1.0, -1.0]);
        // With logits, clause 0 (Y_0) is the argmax target -> its row instead.
        let logits = [-10.0, -900.0, -500.0, 3.0];
        let row = margin_subgradient_row(&spec, &[0.5], &saturated, Some(&logits)).unwrap();
        assert_eq!(row, vec![1.0, 0.0, 0.0, -1.0]);
        // UNSATURATED outputs: no tie, so the tie-break is inert — the pick is the
        // same with and without it (softmax is monotone, so it would agree anyway).
        let informative = [0.30, 0.05, 0.15, 0.50];
        let a = margin_subgradient_row(&spec, &[0.5], &informative, None).unwrap();
        let b = margin_subgradient_row(&spec, &[0.5], &informative, Some(&logits)).unwrap();
        assert_eq!(a, vec![1.0, 0.0, 0.0, -1.0]);
        assert_eq!(a, b);
        // A tie-break vector of the wrong length is ignored (historical pick).
        let row = margin_subgradient_row(&spec, &[0.5], &saturated, Some(&[1.0, 2.0])).unwrap();
        assert_eq!(row, vec![0.0, 0.0, 1.0, -1.0]);
    }

    /// Reference `softmax` in f64, max-subtracted exactly as ORT does it.
    fn softmax_f64(logits: &[f64]) -> Vec<f64> {
        let max = logits.iter().copied().fold(f64::NEG_INFINITY, f64::max);
        let exps: Vec<f64> = logits.iter().map(|z| (z - max).exp()).collect();
        let sum: f64 = exps.iter().sum();
        exps.iter().map(|e| e / sum).collect()
    }

    /// #pre-softmax-objective CORRECTNESS CHECK.
    ///
    /// On an ADMITTED net+spec (one normalization group, argmax-complement
    /// disjunction of bare pairwise atoms), scoring the search on pre-Softmax
    /// LOGITS must rank candidate points EXACTLY as scoring them on
    /// post-Softmax PROBABILITIES does — because softmax over one group is
    /// strictly order-preserving and the property is built only from
    /// comparisons within that group.
    ///
    /// The case is deliberately UNSATURATED: every probability is a distinct
    /// positive number and every candidate's post-Softmax margin is distinct,
    /// so the post-Softmax ranking is a real ranking and the agreement is a
    /// genuine check rather than a comparison against a constant. The final
    /// block then shows the SATURATED case the lever exists for, where the
    /// post-Softmax ranking collapses and the logit ranking survives.
    #[test]
    fn pre_softmax_scoring_preserves_the_post_softmax_ranking_when_unsaturated() {
        // Argmax complement over 4 outputs with true label 3 — the admitted
        // shape, and the shape `ny_onnx::admit_pre_softmax_attack_scoring`
        // requires.
        let spec = spec_with(
            4,
            vec![
                vec![OC::GreaterEq(0, 3)],
                vec![OC::GreaterEq(1, 3)],
                vec![OC::GreaterEq(2, 3)],
            ],
            true,
            vec![(0.0, 1.0)],
        );

        // Small, well-separated logits: softmax stays far from f32 underflow.
        let candidates: Vec<(&str, Vec<f64>)> = vec![
            ("far", vec![-2.0, -3.0, -2.5, 1.0]),
            ("mid", vec![-0.5, -1.5, -1.0, 1.0]),
            ("near", vec![0.6, -1.0, 0.2, 1.0]),
            ("violating", vec![1.4, -1.0, 0.2, 1.0]),
            ("between", vec![0.1, -0.7, -0.2, 1.0]),
        ];

        let mut pre: Vec<(&str, f64)> = Vec::new();
        let mut post: Vec<(&str, f64)> = Vec::new();
        for (name, logits) in &candidates {
            let probabilities = softmax_f64(logits);
            // The case must not be saturated, or the test proves nothing.
            assert!(
                probabilities.iter().all(|p| *p > 1e-3),
                "{name}: fixture must be UNSATURATED, got {probabilities:?}"
            );
            pre.push((name, property_margin(&spec, &[0.5], logits)));
            post.push((name, property_margin(&spec, &[0.5], &probabilities)));
        }

        // The post-Softmax margins must themselves be all-distinct, otherwise
        // "the rankings agree" would be satisfiable by a degenerate ordering.
        for i in 0..post.len() {
            for j in (i + 1)..post.len() {
                assert!(
                    (post[i].1 - post[j].1).abs() > 1e-9,
                    "post-Softmax fixture margins must be distinct: {:?} vs {:?}",
                    post[i],
                    post[j]
                );
            }
        }

        let mut pre_order = pre.clone();
        pre_order.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        let mut post_order = post.clone();
        post_order.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());

        let pre_names: Vec<&str> = pre_order.iter().map(|(n, _)| *n).collect();
        let post_names: Vec<&str> = post_order.iter().map(|(n, _)| *n).collect();
        assert_eq!(
            pre_names, post_names,
            "pre-Softmax scoring must induce the SAME ranking as post-Softmax \
             scoring on an admitted net+spec\npre  {pre:?}\npost {post:?}"
        );

        // Order preservation is pointwise, not merely aggregate: the SIGN of
        // every margin agrees too, so the two spaces also agree on which
        // candidates are violations. (This is the property that makes a
        // logit-scored search hunt for the same region ORT will confirm.)
        for ((name, pre_margin), (_, post_margin)) in pre.iter().zip(post.iter()) {
            assert_eq!(
                *pre_margin >= 0.0,
                *post_margin >= 0.0,
                "{name}: violation status must agree across the two spaces"
            );
        }

        // And the case the lever exists for: with CONFIDENT logits the f32
        // forward underflows, the post-Softmax margin is the same value at
        // every candidate, and only the logit ranking carries information.
        let saturating: Vec<Vec<f64>> = vec![
            vec![-900.0, -1400.0, -1100.0, 300.0],
            vec![-500.0, -1400.0, -1100.0, 300.0],
            vec![-100.0, -1400.0, -1100.0, 300.0],
        ];
        let saturated_post: Vec<f64> = saturating
            .iter()
            .map(|logits| {
                // f32 is what the trusted forward actually returns.
                let probabilities: Vec<f64> = softmax_f64(logits)
                    .iter()
                    .map(|p| f32_to_f64_exact(*p as f32))
                    .collect();
                property_margin(&spec, &[0.5], &probabilities)
            })
            .collect();
        assert!(
            saturated_post.windows(2).all(|w| w[0] == w[1]),
            "the defect: post-Softmax margins must be bit-identical here, got {saturated_post:?}"
        );
        let saturated_pre: Vec<f64> = saturating
            .iter()
            .map(|logits| property_margin(&spec, &[0.5], logits))
            .collect();
        assert!(
            saturated_pre.windows(2).all(|w| w[0] < w[1]),
            "the fix: pre-Softmax margins must still be strictly ordered, got {saturated_pre:?}"
        );
    }

    /// (d) DEFAULTS UNCHANGED. With no lever set the pre-Softmax objective is
    /// disarmed, so the attack lane never runs the admission guard, never reads
    /// a pre-Softmax tensor, and scores on the trusted forward's output exactly
    /// as it does at HEAD.
    #[test]
    fn pre_softmax_attack_objective_is_dark_by_default() {
        ny_test_utils::env::with_serialized_env_vars_removed(
            &["NY_ATTACK_PRE_SOFTMAX_OBJECTIVE"],
            || {
                assert!(
                    !pre_softmax_attack_objective_armed(),
                    "the pre-Softmax attack objective must be dark with no lever set"
                );
            },
        );
    }

    /// (d) The gate is armed by the EXACT byte string "1" and disarmed by the
    /// exact "0"; every other byte string is a recorded rejection that resolves
    /// to the declaration's `false` default, so a typo can never silently arm a
    /// scored run.
    #[test]
    fn pre_softmax_attack_objective_gate_parses_exactly_one() {
        for value in [
            "", "0", "01", "1 ", " 1", "true", "TRUE", "yes", "on", "2", "1\n",
        ] {
            ny_test_utils::env::with_serialized_env_vars(
                &[("NY_ATTACK_PRE_SOFTMAX_OBJECTIVE", value)],
                || {
                    assert!(
                        !pre_softmax_attack_objective_armed(),
                        "{value:?} must not arm the pre-Softmax attack objective"
                    );
                },
            );
        }
        ny_test_utils::env::with_serialized_env_vars(
            &[("NY_ATTACK_PRE_SOFTMAX_OBJECTIVE", "1")],
            || {
                assert!(
                    pre_softmax_attack_objective_armed(),
                    "exact \"1\" must arm the pre-Softmax attack objective"
                );
            },
        );
    }

    /// #traffic-ranked-target: rank 0 must be the argmax target (byte-identical
    /// to [`margin_subgradient_row`]); ranks 1, 2, … must walk DOWN the logit
    /// ranking; ranks past the end must clamp to the last, never panic.
    #[test]
    fn margin_subgradient_row_ranked_walks_the_logit_ranking() {
        let spec = spec_with(
            4,
            vec![
                vec![OC::GreaterEq(0, 3)],
                vec![OC::GreaterEq(1, 3)],
                vec![OC::GreaterEq(2, 3)],
            ],
            true,
            vec![(0.0, 1.0)],
        );
        let saturated = [0.0, 0.0, 0.0, 1.0];
        // Logit margins vs Y_3=3: clause 0 -> -13, clause 2 -> -503, clause 1 ->
        // -903. Ranking (closest to violation first) is 0, 2, 1.
        let logits = [-10.0, -900.0, -500.0, 3.0];
        let expect = |i: usize| {
            let mut row = vec![0.0f32; 4];
            row[i] = 1.0;
            row[3] = -1.0;
            row
        };
        for (rank, clause) in [(0usize, 0usize), (1, 2), (2, 1)] {
            let row = margin_subgradient_row_ranked(&spec, &[0.5], &saturated, Some(&logits), rank)
                .unwrap();
            assert_eq!(
                row,
                expect(clause),
                "rank {rank} must target clause {clause}"
            );
        }
        // Rank 0 is exactly the unranked entry point.
        assert_eq!(
            margin_subgradient_row_ranked(&spec, &[0.5], &saturated, Some(&logits), 0).unwrap(),
            margin_subgradient_row(&spec, &[0.5], &saturated, Some(&logits)).unwrap()
        );
        // Past the end clamps to the last ranked target.
        assert_eq!(
            margin_subgradient_row_ranked(&spec, &[0.5], &saturated, Some(&logits), 99).unwrap(),
            expect(1)
        );
    }

    #[test]
    fn margin_subgradient_row_respects_per_clause_input_boxes() {
        // Two clauses with disjoint X boxes; only the clause containing X may be
        // picked, even if the other clause's margin is larger.
        let mut spec = spec_with(
            1,
            vec![
                vec![OC::GreaterEqConst(0, 10.0)], // X in [0,1]: far margin
                vec![OC::GreaterEqConst(0, 1.0)],  // X in [2,3]: near margin
            ],
            true,
            vec![(0.0, 3.0)],
        );
        spec.per_clause_input_bounds = vec![
            std::iter::once((0usize, (0.0f64, 1.0f64))).collect(),
            std::iter::once((0usize, (2.0f64, 3.0f64))).collect(),
        ];
        // X = 0.5 is only in clause 0's box -> its row (+1 at 0) despite clause 1
        // having the better output margin.
        let row = margin_subgradient_row(&spec, &[0.5], &[0.9], None).unwrap();
        assert_eq!(row, vec![1.0]);
        // X = 5.0 is outside every clause box -> no direction.
        assert!(margin_subgradient_row(&spec, &[5.0], &[0.9], None).is_none());
    }

    #[test]
    fn constraint_grad_row_matches_constraint_margin_semantics() {
        // margin(LessEq(i,j)) = y_j - y_i.
        assert_eq!(
            constraint_grad_row(&OC::LessEq(0, 1), 2).unwrap(),
            vec![-1.0, 1.0]
        );
        // margin(GreaterThan(i,j)) = y_i - y_j.
        assert_eq!(
            constraint_grad_row(&OC::GreaterThan(0, 1), 2).unwrap(),
            vec![1.0, -1.0]
        );
        // margin(LessEqConst(i,k)) = k - y_i.
        assert_eq!(
            constraint_grad_row(&OC::LessEqConst(1, 0.5), 2).unwrap(),
            vec![0.0, -1.0]
        );
        // margin(GreaterEqConst(i,k)) = y_i - k.
        assert_eq!(
            constraint_grad_row(&OC::GreaterEqConst(0, 0.5), 2).unwrap(),
            vec![1.0, 0.0]
        );
        // Out-of-range output index -> no row.
        assert!(constraint_grad_row(&OC::GreaterEq(0, 7), 2).is_none());
        // Self-comparison accumulates to a zero row (margin is constant 0).
        assert_eq!(
            constraint_grad_row(&OC::GreaterEq(1, 1), 2).unwrap(),
            vec![0.0, 0.0]
        );
    }

    #[test]
    fn margin_is_max_over_disjunctive_clauses() {
        // (Y_0 >= 1.0) OR (Y_0 <= -1.0): unsafe if either holds.
        let spec = spec_with(
            1,
            vec![
                vec![OC::GreaterEqConst(0, 1.0)],
                vec![OC::LessEqConst(0, -1.0)],
            ],
            true,
            vec![(-2.0, 2.0)],
        );
        // Y_0 = 0.3: clause A margin = -0.7, clause B margin = -1.3 -> max -0.7 < 0.
        assert!((property_margin(&spec, &[0.0], &[0.3]) - (-0.7)).abs() < 1e-6);
        // Y_0 = 1.2: clause A satisfied (margin 0.2) -> property margin > 0.
        assert!(property_margin(&spec, &[0.0], &[1.2]) > 0.0);
    }

    #[test]
    fn margin_is_min_over_conjunction_clause() {
        // Single clause, conjunction of two: Y_0 >= 1.0 AND Y_1 <= 0.0.
        let spec = spec_with(
            2,
            vec![vec![OC::GreaterEqConst(0, 1.0), OC::LessEqConst(1, 0.0)]],
            true,
            vec![(0.0, 1.0)],
        );
        // First holds (margin +0.5), second fails (margin -0.5) -> min -0.5 < 0.
        assert!(property_margin(&spec, &[0.0], &[1.5, 0.5]) < 0.0);
        assert!(!spec.is_unsafe(&[1.5, 0.5]));
        // Both hold -> margin > 0 and is_unsafe true.
        assert!(property_margin(&spec, &[0.0], &[1.5, -0.5]) > 0.0);
        assert!(spec.is_unsafe(&[1.5, -0.5]));
    }

    #[test]
    fn per_clause_input_box_excludes_clause_from_margin() {
        // Disjunction with a per-clause input box on clause 0: X_0 in [10, 20].
        let mut spec = spec_with(
            1,
            vec![
                vec![OC::GreaterEqConst(0, 1.0)],
                vec![OC::LessEqConst(0, -1.0)],
            ],
            true,
            vec![(0.0, 30.0)],
        );
        let mut m0 = std::collections::BTreeMap::new();
        m0.insert(0usize, (10.0f64, 20.0f64));
        spec.per_clause_input_bounds = vec![m0, std::collections::BTreeMap::new()];

        // Output satisfies clause 0 (Y_0 = 5 >= 1) but input X_0 = 0 is OUTSIDE the
        // clause-0 input box -> clause 0 contributes -inf; clause 1 (Y_0 <= -1) fails.
        let margin_outside = property_margin(&spec, &[0.0], &[5.0]);
        assert!(margin_outside < 0.0, "got {margin_outside}");
        // Same output, but input INSIDE the clause-0 box -> clause 0 counts, margin > 0.
        let margin_inside = property_margin(&spec, &[15.0], &[5.0]);
        assert!(margin_inside > 0.0, "got {margin_inside}");
    }

    #[test]
    fn smtlib_witness_format_matches_renderer() {
        let input = [0.1_f64, -0.25_f64];
        let output = [0.1_f32];
        let w = format_smtlib_witness_f64(&input, &output);
        let lines: Vec<&str> = w.split('\n').collect();
        assert!(lines[0].starts_with("((X_0 "), "{w}");
        assert!(lines[1].starts_with("(X_1 "), "{w}");
        assert!(lines[2].starts_with("(Y_0 "), "{w}");
        assert!(w.ends_with(')'), "{w}");
        // X decimals remain the exact f64 emit view; strict organizer box
        // membership must not change as a side effect of Y hardening.
        assert_eq!(lines[0], format!("((X_0 {})", input[0]));
        assert_eq!(lines[1], format!("(X_1 {})", input[1]));
        // Strip the assignment close plus the outer-list close.
        let y0_text = lines[2]
            .strip_prefix("(Y_0 ")
            .and_then(|text| text.strip_suffix("))"))
            .expect("Y_0 assignment");
        let y0: f64 = y0_text.parse().expect("Y_0 decimal");
        assert_eq!(y0, f64::from(output[0]));
        assert_ne!(
            output[0]
                .to_string()
                .parse::<f64>()
                .expect("short f32 decimal"),
            f64::from(output[0])
        );
        // Round-trips back through the gate's own witness parser.
        let parsed = parse_witness_inputs(&w).expect("parse refined witness");
        assert_eq!(parsed, vec![0.1_f32, -0.25_f32]);
    }

    #[test]
    fn clamp_to_box_pins_into_interval() {
        assert_eq!(clamp_to_box(5.0, -1.0, 1.0), 1.0);
        assert_eq!(clamp_to_box(-5.0, -1.0, 1.0), -1.0);
        assert_eq!(clamp_to_box(0.25, -1.0, 1.0), 0.25);
        // Degenerate fixed input (lo == hi) pins exactly.
        assert_eq!(clamp_to_box(0.9, 0.5, 0.5), 0.5);
    }

