        let row = "onnx/ruarobot/perturbations_0.onnx,\
                   vnnlib/ruarobot/hyperrectangle_5984.vnnlib,20";
        let fields: Vec<_> = row.split(',').collect();
        assert_eq!(fields.len(), 3);
